fn binds_a_scalar(name: &str) -> bool { name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "f32" || name == "f64" || name == "bool" || name == "char" || name == "String" }

fn binds_tuple_parts(found: &Ty, count: i64) -> Vec<Ty> {
    match found {
        Ty::Tuple(parts) => { if (parts.len() as i64) == count { return parts.to_owned(); } },
        _ => { },
    }
    let mut unknown: Vec<Ty> = vec![];
    for index in 0..count { unknown.push(Ty::Unknown); }
    unknown
}

pub fn binds_hands_a_view(method: &str) -> bool { method == "filter" || method == "find" || method == "take_while" || method == "skip_while" || method == "min_by_key" || method == "max_by_key" }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn binds_item_params(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, arg: &Expr, ty: &Ty, held: &str) -> Vec<(String, bool)> {
    let mut out: Vec<(String, bool)> = vec![];
    let types: Vec<Ty> = match ty {
        Ty::Fn { params, .. } => params.to_owned(),
        _ => return out,
    };
    match arg {
        Expr::Closure { params, .. } => {
            let mut at: i64 = 0;
            for p in params.iter() {
                let p = *p;
                if at < types.len() as i64 {
                    match *nikaia_std::index::get(&types, (at) as usize) {
                        Ty::Var { ref name, view } => { if name == held { out.push((world.words.resolve(p).to_owned(), view)); } },
                        _ => { },
                    }
                }
                at += 1;
            }
        },
        _ => { },
    }
    out
}


