fn unwritable_payload(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, ty: &str, variant: &str, payloads: &impl Fn(&str, &str) -> Option<Vec<Ty>>) -> Vec<String> {
    let carried = match payloads(ty, variant) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    for held in carried.iter() { if rust_constant_type(world.library, held).is_none() && state.declared_below(world, held).is_none() { return vec![format!("{}::{}", ty, variant), held.text()]; } }
    vec![]
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn unwritable_in(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, value: &BuildValue, payloads: &impl Fn(&str, &str) -> Option<Vec<Ty>>) -> Vec<String> {
    match value {
        BuildValue::Struct { name, fields } => {
            let own = state.unwritable_field(world, &Ty::Named { name: name.to_owned(), args: vec![], view: false });
            if !own.is_empty() { return own; }
            for (_, held) in fields.iter() {
                let inner = unwritable_in(state, world, held, payloads);
                if !inner.is_empty() { return inner; }
            }
            return vec![];
        },
        BuildValue::Variant { ty, variant, payload } => {
            let own = unwritable_payload(state, world, ty, variant, payloads);
            if !own.is_empty() { return own; }
            for held in payload.iter() {
                let inner = unwritable_in(state, world, held, payloads);
                if !inner.is_empty() { return inner; }
            }
            return vec![];
        },
        BuildValue::List(items) => {
            for held in items.iter() {
                let inner = unwritable_in(state, world, held, payloads);
                if !inner.is_empty() { return inner; }
            }
            return vec![];
        },
        BuildValue::Tuple(parts) => {
            for held in parts.iter() {
                let inner = unwritable_in(state, world, held, payloads);
                if !inner.is_empty() { return inner; }
            }
            return vec![];
        },
        _ => return vec![],
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn written_below(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, value: &BuildValue, want: Option<&Ty>, payloads: &impl Fn(&str, &str) -> Option<Vec<Ty>>, float_text: &impl Fn(f64) -> String) -> Option<String> {
    if want.is_none() { return rust_value(value, float_text); }
    let wanted: Ty = nikaia_std::index::or(want.as_ref(), || &Ty::Unknown).clone();
    match value {
        BuildValue::List(items) => {
            let mut held: Ty = element_of(&wanted);
            let mut borrow: &'static str = "";
            let slice = slice_element(&wanted);
            if slice.is_some() {
                held = nikaia_std::index::or(slice.as_ref(), || &Ty::Unknown).clone();
                borrow = "&";
            }
            let some_held: Option<Ty> = Some(held.clone());
            let mut written: Vec<String> = vec![];
            for item in items.iter() {
                let text = match written_below(state, world, item, (some_held).as_ref(), payloads, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(text);
            }
            return Some(format!("{}[{}]", borrow, written.join(", ")));
        },
        BuildValue::Struct { name, fields } => {
            let declared = state.fields_of(world, name);
            let mut written: Vec<String> = vec![];
            for (field, held) in fields.iter() {
                let field_want = const_field_type((declared).as_ref(), field);
                let text = match written_below(state, world, held, (field_want).as_ref(), payloads, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(format!("{}: {}", field, text));
            }
            return Some(format!("{} {{ {} }}", name, written.join(", ")));
        },
        BuildValue::Variant { ty, variant, payload } => {
            if payload.is_empty() { return Some(format!("{}::{}", ty, variant)); }
            let declared = nikaia_std::index::or(payloads(ty, variant), || vec![].into());
            let mut written: Vec<String> = vec![];
            let mut at: i64 = 0;
            for held in payload.iter() {
                let part_want = nth_type(&declared, at);
                let text = match written_below(state, world, held, (part_want).as_ref(), payloads, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(text);
                at = at + 1;
            }
            return Some(format!("{}::{}({})", ty, variant, written.join(", ")));
        },
        _ => return rust_value(value, float_text),
    }
}

impl CheckState {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    #[allow(clippy::too_many_arguments)]
    pub fn a_table_that_crosses(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, bound: &str, want: &Ty, pairs: &[BuildValue], span: &Span, payloads: &impl Fn(&str, &str) -> Option<Vec<Ty>>, float_text: &impl Fn(f64) -> String) -> CheckTable {
        let args = type_arguments(want);
        if args.len() != 2 { return no_table(false); }
        if !a_str_view_key(nikaia_std::index::get(&args, 0)) {
            self.a_table_key_that_is_not_text(bound, &(*nikaia_std::index::get(&args, 0)).text(), span);
            return no_table(true);
        }
        let held: Ty = (*nikaia_std::index::get(&args, 1)).clone();
        let mut value_below: String = String::from("");
        let mut borrow: &'static str = "";
        let constant = rust_constant_type(world.library, &held);
        if constant.is_some() { value_below = nikaia_std::index::or(constant.as_deref(), || "").to_owned(); } else {
            let declared = match self.declared_below(world, &held) { Some(__nikaia_value) => __nikaia_value, None => return no_table(false) };
            value_below = format!("&'static {}", declared);
            borrow = "&";
        }
        let some_held: Option<Ty> = Some(held.clone());
        let mut keys: Vec<String> = vec![];
        let mut values: Vec<String> = vec![];
        let mut seen: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        let mut at: i64 = 0;
        for pair in pairs.iter() {
            let parts: Vec<BuildValue> = match pair {
                BuildValue::Tuple(inner) => inner.to_owned(),
                _ => return no_table(false),
            };
            if parts.len() != 2 { return no_table(false); }
            let key = match text_of_value(nikaia_std::index::get(&parts, 0)) { Some(__nikaia_value) => __nikaia_value, None => return no_table(false) };
            if seen.contains_key(&key) {
                let first = nikaia_std::index::or(*nikaia_std::index::get(&seen, &key), || 0);
                self.a_table_with_one_key_twice(bound, &key, first, at, span);
                return no_table(true);
            }
            seen.insert(key.to_owned(), at);
            keys.push(key.to_owned());
            let text = match written_below(self, world, nikaia_std::index::get(&parts, 1), (some_held).as_ref(), &payloads, &float_text) { Some(__nikaia_value) => __nikaia_value, None => return no_table(false) };
            values.push(format!("{}{}", borrow, text));
            at = at + 1;
        }
        let table = match build(&keys) { Some(__nikaia_value) => __nikaia_value, None => return no_table(false) };
        let mut disps: Vec<String> = vec![];
        for (d1, d2) in table.disps.iter() {
            let d1 = nikaia_std::num::value(d1);let d2 = nikaia_std::num::value(d2);
            disps.push(format!("({}, {})", d1, d2));
        }
        let mut written_keys: Vec<String> = vec![];
        for key in table.keys.iter() { written_keys.push(format!("\"{}\"", as_a_literal(key))); }
        let mut written_values: Vec<String> = vec![];
        for place in table.order.iter() {
            let place = nikaia_std::num::value(place);
            written_values.push((*nikaia_std::index::get(&values, nikaia_std::index::at(place))).to_owned());
        }
        CheckTable { found: true, below: format!("Fixed<{}>", value_below), written: format!("Fixed::new({}, &[{}], &[{}], &[{}])", table.seed, disps.join(", "), written_keys.join(", "), written_values.join(", ")), said: false }
    }
}


// --- check_copies.nika ---

pub fn check_parts_beside(beside: &[ParsedView<'_, '_, '_, '_, '_, '_>], here_at: i64) -> collections::BTreeMap<String, Vec<Ty>> {
    let mut parts: collections::BTreeMap<String, Vec<Ty>> = collections::BTreeMap::new();
    let mut at: i64 = 0;
    for other in beside.iter() {
        if at != here_at { for item in other.items.iter() { copies_parts_of(other, &item.node, &mut parts); } }
        at = at + 1;
    }
    parts
}

fn copies_parts_of(other: &ParsedView<'_, '_, '_, '_, '_, '_>, item: &Item, parts: &mut collections::BTreeMap<String, Vec<Ty>>) {
    match item {
        Item::Struct { name, generics, fields, .. } => {
            let name = *name;
            if !generics.is_empty() { return; }
            let named = other.text(name);
            if parts.contains_key(&named) { return; }
            let mut held: Vec<Ty> = vec![];
            for field in fields.iter() { held.push(written_ty(other.words, other.aliases, &field.ty)); }
            parts.insert(named, held);
        },
        Item::Enum { name, variants, .. } => {
            let name = *name;
            let named = other.text(name);
            if parts.contains_key(&named) { return; }
            let mut held: Vec<Ty> = vec![];
            for variant in variants.iter() {
                match &variant.fields {
                    VariantFields::Unit => { },
                    VariantFields::Tuple(types) => { for ty in types.iter() { held.push(written_ty(other.words, other.aliases, ty)); } },
                    VariantFields::Named(fields) => { for field in fields.iter() { held.push(written_ty(other.words, other.aliases, &field.ty)); } },
                }
            }
            parts.insert(named, held);
        },
        _ => { },
    }
}

fn copies_declared_in(view: &ParsedView<'_, '_, '_, '_, '_, '_>) -> Vec<String> {
    let mut names: Vec<String> = vec![];
    for item in view.items.iter() {
        match &item.node {
            Item::Struct { name, .. } => { let name = *name; names.push(view.text(name)); },
            Item::Enum { name, .. } => { let name = *name; names.push(view.text(name)); },
            _ => { },
        }
    }
    names
}

fn copies_dropped_in(view: &ParsedView<'_, '_, '_, '_, '_, '_>, dropped: &mut collections::BTreeSet<String>) {
    for item in view.items.iter() {
        match &item.node {
            Item::Impl { trait_name, target, .. } => {
                let trait_name = *trait_name;
                let named = match trait_name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if view.text(named) == "Drop" { dropped.insert(view.text(target.name)); }
            },
            _ => { },
        }
    }
}

impl CheckState {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn collect_copies(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>) {
        let declared = copies_declared_in(&world.here);
        let mut package: Vec<String> = declared.to_owned();
        let mut at: i64 = 0;
        for other in world.beside.iter() {
            if at != world.here_at { for name in copies_declared_in(other) { if !nikaia_std::list::contains(&declared, &name) { package.push(name); } } }
            at = at + 1;
        }
        let mut dropped: collections::BTreeSet<String> = collections::BTreeSet::new();
        copies_dropped_in(&world.here, &mut dropped);
        for unit in world.beside.iter() { copies_dropped_in(unit, &mut dropped); }
        let mut copies: collections::BTreeSet<String> = collections::BTreeSet::new();
        for (name, contract) in world.library.types.iter() { if contract.copies { copies.insert(name.to_owned()); } }
        loop {
            let mut joining: Vec<String> = vec![];
            for name in package.iter() {
                if copies.contains(name) || dropped.contains(name) { continue; }
                let mut parts: Vec<Ty> = vec![];
                if nikaia_std::list::contains(&declared, &name) {
                    if self.enum_payloads.contains_key(name) {
                        let held = match self.enum_payloads.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
                        parts = held.to_owned();
                    } else {
                        let fields = match self.structs.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
                        for field in fields.iter() { parts.push(field.ty.clone()); }
                    }
                } else {
                    let held = match world.parts_beside.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    parts = held.to_owned();
                }
                let named = Ty::Named { name: name.to_owned(), args: vec![], view: false };
                if self.cleanup_of(world, &named).is_some() { continue; }
                let mut all = true;
                for ty in parts.iter() { if !a_copied_part(ty, &copies) { all = false; } }
                if all { joining.push(name.to_owned()); }
            }
            if joining.is_empty() { break; }
            for name in joining.iter() { copies.insert(name.to_owned()); }
        }
        let mut in_package: collections::BTreeSet<String> = collections::BTreeSet::new();
        let mut own: collections::BTreeSet<String> = collections::BTreeSet::new();
        for name in copies.iter() {
            if nikaia_std::list::contains(&package, &name) { in_package.insert(name.to_owned()); }
            if nikaia_std::list::contains(&declared, &name) { own.insert(name.to_owned()); }
        }
        self.copies_in_the_package = in_package;
        self.facts.copies = own;
    }
}


// --- check_core_args.nika ---

fn check_core_args_runs(callee: Option<&FnContract>, at: i64) -> bool {
    let contract = match callee { Some(__nikaia_value) => __nikaia_value, None => return true };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    let mut i: i64 = 0;
    for (name, _) in call_arguments(signature) {
        if i == at { return !nikaia_std::list::contains(&contract.keeps, &name); }
        i += 1;
    }
    true
}

fn check_core_args_is_lambda(arg: &Expr, expected: &[Ty], at: i64) -> bool {
    if at >= expected.len() as i64 { return false; }
    let mut closure = false;
    match arg {
        Expr::Closure { .. } => { closure = true; },
        _ => { },
    }
    if !closure { return false; }
    matches!(*nikaia_std::index::get(&expected, nikaia_std::index::at(at)), Ty::Fn { .. })
}

fn check_core_args_named(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, arg: &Expr) -> bool {
    match arg {
        Expr::Path(_, _) => true,
        Expr::Variable(name, _) => { let name = *name; state.binding(world.words.resolve(name)).is_none() },
        _ => false,
    }
}

fn check_core_args_a_run_parameter(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, arg: &Expr) -> bool {
    match arg {
        Expr::Variable(name, _) => { let name = *name; state.run_code.contains(world.words.resolve(name)) },
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
fn check_core_args_lambda<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, arg: &Expr, want: &Ty, declared_here: bool, callee: Option<&FnContract>, at: i64, span: &Span) -> Ty {
    let id = id_of(arg) as i64;
    let runs = check_core_args_runs(callee, at);
    match arg {
        Expr::Closure { params, mutable, body, .. } => {
            match want {
                Ty::Fn { params: given, result, is_sync, can_throw } => {
                    let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync;
                    let pauses: bool = !is_sync;
                    let fails: bool = can_throw;
                    if pauses && declared_here {
                        state.facts.future_lambdas.insert(id);
                        if runs { state.facts.run_lambdas.insert(id); }
                    }
                    if !runs {
                        state.facts.kept_lambdas.insert(id, (pauses, fails));
                        state.a_kept_lambdas_hulls(world, arg);
                        state.a_kept_lambda_takes_these(world, arg, pauses, span);
                    }
                    state.a_lambdas_text_is_its_own(world, want, arg);
                    let (came_to, paused) = check_core_lambda(state, world, host, params, mutable, body, given, &CheckPromises { may_pause: pauses, may_fail: fails }, span);
                    if paused && !declared_here { state.flow.paused_args.push(id); }
                    let written: Ty = nikaia_std::index::or(match result {
                        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                        None => None,
                    }, || Ty::Unknown);
                    let mut out: Option<Ty> = None;
                    if !written.is_unknown() { out = Some(written); } else if !came_to.is_unknown() { out = Some(came_to); }
                    return Ty::Fn { params: given.to_owned(), result: Box::new(out), is_sync: !pauses, can_throw: fails };
                },
                _ => { },
            }
        },
        _ => { },
    }
    Ty::Unknown
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
fn check_core_args_other<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, arg: &Expr, expected: &[Ty], declared_here: bool, callee: Option<&FnContract>, at: i64, span: &Span) -> Ty {
    let mut lends = false;
    let mut wants_fn = false;
    let mut wants_pausing_fn = false;
    let mut wants_throwing_fn = false;
    if at < expected.len() as i64 {
        lends = (*nikaia_std::index::get(&expected, nikaia_std::index::at(at))).is_a_view();
        match nikaia_std::index::get(&expected, nikaia_std::index::at(at)) {
            Ty::Fn { is_sync, can_throw, .. } => {
                let can_throw = *can_throw; let is_sync = *is_sync;
                wants_fn = true;
                let plain: bool = is_sync;
                wants_pausing_fn = !plain;
                wants_throwing_fn = can_throw;
            },
            _ => { },
        }
    }
    if !lends { check_core_a_field_of_a_borrowed_subject(state, world, host, arg, span, "passed"); }
    let found = check_core_expr(state, world, host, arg, span);
    let named = check_core_args_named(&state, world, arg);
    let runs = check_core_args_runs(callee, at);
    let mut found_fn = false;
    let mut found_throws = false;
    let mut arity: i64 = 0;
    match found {
        Ty::Fn { ref params, can_throw, .. } => {
            found_fn = true;
            found_throws = can_throw;
            arity = params.len() as i64;
        },
        _ => { },
    }
    if declared_here && named && runs && wants_throwing_fn && found_throws { state.facts.boxed_fn_values.insert(id_of(arg) as i64, arity); }
    if declared_here && named && runs && wants_throwing_fn && found_fn && !found_throws { state.facts.infallible_fn_values.insert(id_of(arg) as i64, arity); }
    if declared_here && named && runs && wants_pausing_fn && found_fn { state.facts.sync_functions_run_async.insert(id_of(arg) as i64, arity); }
    if declared_here && wants_fn && found_fn && runs && !check_core_args_a_run_parameter(&state, world, arg) && !named { state.facts.kept_args.insert(id_of(arg) as i64); }
    if wants_fn && found_fn && !runs && named { check_core_a_kept_lambda(state, world, host, nikaia_std::index::get(&expected, nikaia_std::index::at(at)), arg, span); }
    found
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
pub fn check_core_arguments_given<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, args: &[Expr], expected: &[Ty], declared_here: bool, callee: Option<&FnContract>, span: &Span) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    let mut at: i64 = 0;
    for arg in args.iter() {
        if check_core_args_is_lambda(arg, expected, at) { out.push(check_core_args_lambda(state, world, host, arg, nikaia_std::index::get(&expected, nikaia_std::index::at(at)), declared_here, callee, at, span)); } else { out.push(check_core_args_other(state, world, host, arg, expected, declared_here, callee, at, span)); }
        at += 1;
    }
    out
}

fn check_core_args_door(writing: bool) -> String {
    if writing { return "update_all".to_owned(); }
    "access_all".to_owned()
}

fn check_core_args_door_shape(writing: bool) -> String {
    if writing { return "update_all(a, b) fn(x, y) { … }".to_owned(); }
    "access_all(a, b) fn(x, y) { … }".to_owned()
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_args_no_door(state: &mut CheckState, writing: bool, wanted: &str, span: &Span) { state.no_door(&check_core_args_door(writing), &check_core_args_door_shape(writing), wanted, span); }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
fn check_core_args_door_block<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, writing: bool, args: &[Expr], params: &[winnow_grammar::Symbol], mutable: &[winnow_grammar::Symbol], body: &Block, span: &Span) -> Ty {
    let count = args.len() as i64 - 1;
    if count < 2 {
        check_core_args_no_door(state, writing, "It's for several locks, so pass at least two.", span);
        return Ty::Unknown;
    }
    let mut held: Vec<Ty> = vec![];
    let mut at: i64 = 0;
    while at < count {
        let lock = nikaia_std::index::get(&args, (at) as usize);
        let found = check_core_expr(state, world, host, &lock, span);
        let content = locked_content_of(&found);
        if content.is_some() {
            let inside: Ty = nikaia_std::index::or(content, || Ty::Unknown);
            let mut view: Ty = inside.clone();
            if !writing {
                match inside {
                    Ty::Named { ref name, ref args, .. } => { view = Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }; },
                    _ => { },
                }
            }
            held.push(view);
        } else if found.is_unknown() && !state.is_a_number(world, &lock) { held.push(Ty::Unknown); } else {
            let door = check_core_args_door(writing);
            state.findings.push(CheckFinding { severity: CheckSeverity::Error, span: span.clone(), code: "NK1124".to_owned(), message: format!("`{}` takes locks, but this is a `{}`.", door, found.text()), notes: vec!["Taking several locks together keeps them in one order, and only a lock can be taken.".to_owned()], help: Some("Pass `SharedMut[T]` values or `Locked[T]` fields.".to_owned()), labels: vec![] });
            held.push(Ty::Unknown);
        }
        at += 1;
    }
    if !params.is_empty() && (params.len() as i64) != count { check_core_args_no_door(state, writing, "The block takes one value per lock, in the order the locks are written.", span); }
    if writing {
        state.an_update_block_returns_nothing(body, span);
        state.an_update_block_reads_what_it_writes(world, params, body, span);
    }
    let outer_door = state.flow.at_a_write_door;
    state.flow.at_a_write_door = writing;
    let outer_inside = state.inside_a_door;
    state.inside_a_door = true;
    check_core_lambda(state, world, host, params, mutable, body, &held, &CheckPromises { may_pause: true, may_fail: true }, span);
    state.flow.at_a_write_door = outer_door;
    state.inside_a_door = outer_inside;
    if writing { return Ty::Tuple(vec![]); }
    Ty::Named { name: SEEN.to_owned(), args: vec![Ty::Unknown], view: false }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_locks<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, writing: bool, args: &[Expr], span: &Span) -> Ty {
    if args.is_empty() {
        check_core_args_no_door(state, writing, "It takes the locks and then the block.", span);
        return Ty::Unknown;
    }
    let last = nikaia_std::index::get(&args, nikaia_std::index::at(args.len() as i64 - 1));
    match last {
        Expr::Closure { params, mutable, body, .. } => { return check_core_args_door_block(state, world, host, writing, args, params, mutable, body, span); },
        _ => { },
    }
    check_core_args_no_door(state, writing, "The block comes last: `fn(a, b) { … }`.", span);
    Ty::Unknown
}

fn check_core_args_fn_element(declared: Option<&Ty>) -> Option<Ty> {
    let ty = match declared { Some(__nikaia_value) => __nikaia_value, None => return None };
    match ty {
        Ty::Named { name, args, .. } => {
            if name == "Vec" && !args.is_empty() {
                match nikaia_std::index::get(&args, 0) {
                    Ty::Fn { .. } => { return Some((*nikaia_std::index::get(&args, 0)).clone()); },
                    _ => { },
                }
            }
        },
        _ => { },
    }
    None
}

fn check_core_args_an_integer(name: &str) -> bool { name == "u8" || name == "u32" || name == "u64" || name == "i32" || name == "i64" }

fn check_core_args_plain_name(ty: &Ty) -> String {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if !view && args.is_empty() { name.to_owned() } else { "".to_owned() } },
        _ => "".to_owned(),
    }
}

fn check_core_args_array_element(declared: Option<&Ty>) -> Option<Ty> {
    let ty = match declared { Some(__nikaia_value) => __nikaia_value, None => return None };
    match ty {
        Ty::Named { name, args, .. } => if name == "Array" && args.len() == 2 && holds_an_array(nikaia_std::index::get(&args, 0)) { Some((*nikaia_std::index::get(&args, 0)).clone()) } else { None },
        _ => None,
    }
}

fn check_core_args_a_closure(value: &Expr) -> bool { matches!(value, Expr::Closure { .. }) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
