fn check_core_call_lent(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, args: &[Expr], params: &[Ty], found: &[Ty]) {
    let mut i: i64 = -1;
    for given in args.iter() {
        i += 1;
        if i >= params.len() as i64 || i >= found.len() as i64 { break; }
        if (*nikaia_std::index::get(&params, nikaia_std::index::at(i))).is_a_view() && !(*nikaia_std::index::get(&found, nikaia_std::index::at(i))).is_a_view() && !check_core_call_opaque(nikaia_std::index::get(&found, nikaia_std::index::at(i))) && !(moves(nikaia_std::index::get(&found, nikaia_std::index::at(i))) && state.a_map_read_past_a_jump(world, given)) { state.facts.lent_args.insert(id_of(given) as i64); }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
fn check_core_call_kept<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, func: &Expr, args: &[Expr], name: &str, params: &[Ty], gives: Ty, is_sync: bool, fails: bool, span: &Span) -> Ty {
    state.read_at.push((name.to_owned(), span.start as i64));
    let found = check_core_arguments_given(state, world, host, args, params, false, None, span);
    check_core_call_lent(state, world, args, params, &found);
    state.kept_arguments_are_its_own(world, args, params);
    state.facts.kept_calls.insert(id_of(func) as i64, (!is_sync, fails));
    if state.current.is_some() {
        let current: String = nikaia_std::index::or(match state.current.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into());
        let key = format!("{}::{}", current, name);
        let a_param = !current.contains("::") && check_core_call_a_param_of(world, &current, name);
        if fails && world.own.code_throws.contains_key(&key) {
            let set = match *nikaia_std::index::get(&world.own.code_throws, &key) { Some(__nikaia_value) => __nikaia_value, None => return gives };
            let mut contract = FnContract::empty();
            contract.fails_with = set.to_owned();
            state.may_fail_here(world, host, &key, &contract, span);
            check_core_args_a_field_called(state, &current, &key);
            check_core_args_code_said(state, &current, !is_sync, false);
        } else if fails && (a_param || state.stored_code.contains_key(&key)) {
            check_core_args_a_field_called(state, &current, &key);
            check_core_args_code_said(state, &current, !is_sync, false);
        } else { check_core_args_code_said(state, &current, !is_sync, fails); }
    }
    gives
}

