// this was written - see `contracts::sync`.
fn check_core_call_mut_args(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, callee: Option<&FnContract>, seen: &str, args: &[Expr]) {
    let contract: &FnContract = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut i: i64 = -1;
    for (param, _) in signature.params.iter() {
        i += 1;
        if i < args.len() as i64 && nikaia_std::list::contains(&signature.mutable, &param) { if !seen.is_empty() { check_core_call_mut_place(state, world, nikaia_std::index::get(&args, nikaia_std::index::at(i)), &format!("@{}::{}", seen, param)); } else { check_core_method_code_lent(state, world, nikaia_std::index::get(&args, nikaia_std::index::at(i))); } }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_call_mut_place(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, arg: &Expr, place: &str) {
    match arg {
        Expr::Variable(bound, _) => {
            let bound = *bound;
            let named: String = format!("{}", world.words.resolve(bound));
            let local: CheckLocal = match state.binding(&named) { Some(__nikaia_value) => __nikaia_value, None => return };
            if !local.written_mut || !check_core_stmt_holds_code(&local.ty) { return; }
            let current: String = match match state.current.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => return };
            let key = format!("{}::{}", current, named);
            let mut entry: CheckStoredCode = nikaia_std::index::or(state.stored_code.remove(&key), || CheckStoredCode::empty());
            entry.free.insert(place.to_owned());
            state.stored_code.insert(key, entry);
        },
        _ => { },
    }
}

fn check_core_call_a_param_of(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, current: &str, name: &str) -> bool {
    let contract = match *nikaia_std::index::get(&world.own.functions, current) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    for (param, ty) in signature.params.iter() { if param == name && check_core_stmt_holds_code(ty) { return true; } }
    false
}

fn check_core_call_takes_code(callee: Option<&FnContract>) -> bool {
    let contract: &FnContract = match callee { Some(__nikaia_value) => __nikaia_value, None => return false };
    let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    for (_, ty) in signature.params.iter() { if check_core_stmt_holds_code(ty) { return true; } }
    false
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_call_from_given<H: CheckHost>(state: &CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, contract: &FnContract, args: &[Expr]) -> FnContract {
    let mut given = contract.clone();
    let mut any = false;
    for error in contract.fails_with.iter() { if throws_given(error) { any = true; } }
    if !any { return given; }
    let mut set: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut params: Vec<String> = vec![];
    if contract.signature.is_some() {
        let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return given };
        for (param, _) in signature.params.iter() { params.push(param.to_owned()); }
    }
    for error in contract.fails_with.iter() {
        if !throws_given(error) {
            set.insert(error.to_owned());
            continue;
        }
        let inner: String = nikaia_std::index::or(error.strip_prefix("from("), || "").to_owned();
        let param: String = nikaia_std::index::or(inner.strip_suffix(')'), || "").to_owned();
        let mut at: i64 = -1;
        let mut i: i64 = 0;
        for each in params.iter() {
            if *each == param && at < 0 { at = i; }
            i += 1;
        }
        if at < 0 || at >= args.len() as i64 {
            set.insert("?".to_owned());
            continue;
        }
        let mut stored = CheckStoredCode::empty();
        check_core_places_code_into(state, world, host, nikaia_std::index::get(&args, nikaia_std::index::at(at)), &mut stored);
        if stored.unresolved { set.insert("?".to_owned()); }
        for name in stored.free.iter() { check_core_call_set_into(world, name, &mut set); }
        for name in stored.resolved.iter() { check_core_call_set_into(world, name, &mut set); }
    }
    let mut errors: Vec<String> = vec![];
    for error in set.iter() { errors.push(error.to_owned()); }
    given.fails_with = errors;
    given
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_call_from_newly<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, contract: &FnContract, args: &[Expr], span: &Span) {
    if state.flow.guarded.is_none() { return; }
    let mut params: Vec<String> = vec![];
    if contract.signature.is_some() {
        let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
        for (param, _) in signature.params.iter() { params.push(param.to_owned()); }
    }
    for error in contract.fails_with.iter() {
        if !throws_given(error) { continue; }
        let inner: String = nikaia_std::index::or(error.strip_prefix("from("), || "").to_owned();
        let param: String = nikaia_std::index::or(inner.strip_suffix(')'), || "").to_owned();
        let mut at: i64 = -1;
        let mut i: i64 = 0;
        for each in params.iter() {
            if *each == param && at < 0 { at = i; }
            i += 1;
        }
        if at < 0 || at >= args.len() as i64 { continue; }
        let mut stored = CheckStoredCode::empty();
        check_core_places_code_into(&state, world, host, nikaia_std::index::get(&args, nikaia_std::index::at(at)), &mut stored);
        let mut names: Vec<String> = vec![];
        for name in stored.free.iter() { names.push(name.to_owned()); }
        for name in stored.resolved.iter() { names.push(name.to_owned()); }
        for name in names.iter() {
            if world.newly_throws.contains_key(name) {
                let list = match world.newly_throws.get(name) { Some(__nikaia_value) => __nikaia_value, None => return };
                state.newly_reaches_a_handler(name, &list, span);
            }
        }
    }
}

fn check_core_call_set_into(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, name: &str, set: &mut collections::BTreeSet<String>) {
    if name.starts_with('@') {
        let place: String = nikaia_std::index::or(name.strip_prefix('@'), || "").to_owned();
        let settled = match *nikaia_std::index::get(&world.own.code_throws, &place) { Some(__nikaia_value) => __nikaia_value, None => return };
        for error in settled.iter() { set.insert(error.to_owned()); }
        return;
    }
    if world.own.functions.contains_key(name) {
        let own = match *nikaia_std::index::get(&world.own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for error in own.fails_with.iter() { set.insert(error.to_owned()); }
        return;
    }
    if world.library.functions.contains_key(name) {
        let contract = match *nikaia_std::index::get(&world.library.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for error in contract.fails_with.iter() { set.insert(error.to_owned()); }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_call_feed_params<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, key: &str, contract: &FnContract, args: &[Expr], frame: &CheckStoredCode) {
    let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut i: i64 = -1;
    for (param, ty) in signature.params.iter() {
        i += 1;
        if i >= args.len() as i64 || !check_core_stmt_holds_code(ty) { continue; }
        let mut stored = frame.clone();
        check_core_places_code_into(&state, world, host, nikaia_std::index::get(&args, nikaia_std::index::at(i)), &mut stored);
        let place = format!("{}::{}", key, param);
        let mut entry: CheckStoredCode = nikaia_std::index::or(state.stored_code.remove(&place), || CheckStoredCode::empty());
        for resolved in stored.resolved.iter() { entry.resolved.insert(resolved.to_owned()); }
        entry.unresolved = entry.unresolved || stored.unresolved;
        for free in stored.free.iter() { entry.free.insert(free.to_owned()); }
        state.stored_code.insert(place, entry);
    }
}

