// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_expr_char_scalars<H: CheckHost>(state: &mut CheckState, host: &H, text: &str, span: &Span) {
    let value = match host.decoded(text) { Some(__nikaia_value) => __nikaia_value, None => return };
    let count = value.chars().count() as i64;
    if count <= 1 { return; }
    let composed = host.composed(&value);
    let scalars: Vec<scalar> = nikaia_std::list::chars(composed.chars());
    if scalars.len() == 1 {
        let one = *nikaia_std::index::get(&scalars, 0);
        let hex = hex_of(one as i64);
        let note = format!("Your editor stored this character decomposed, as {} scalars; composed (NFC) they are the one scalar `'{}'`, and that is what the literal is.", count, one);
        state.findings.push(CheckFinding { severity: CheckSeverity::Warning, span: span.clone(), code: String::from("NK1213"), message: format!("This `'…'` is written as {} scalars that compose to one, `'{}'`.", count, one), notes: vec![note], help: Some(format!("Write the composed character, `'{}'`, or `'\\u{{{}}}'`.", one, hex)), labels: vec![] });
        return;
    }
    let mut quoted: String = String::from("");
    let mut escaped = false;
    for c in text.chars() {
        if c == '"' && !escaped { quoted.push('\\'); }
        escaped = c == '\\' && !escaped;
        quoted.push(c);
    }
    let note = format!("A `'…'` is one `u8` or one `scalar` (Part I 2.6), and these {} scalars do not compose to one: what a reader sees as one character here is a grapheme, which is text.", count);
    state.findings.push(check_refusal("NK1212", span, format!("This `'…'` holds {} scalars, and a character literal holds one.", count), vec![note], Some(format!("Write it as a text literal: `\"{}\"`.", quoted))));
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_expr<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, span: &Span) -> Ty {
    let reaching: Option<String> = match state.flow.reaching.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    state.flow.reaching = None;
    state.flow.reached = reaching;
    check_narrow_reads_of_the_maybe(state, expr);
    let said_before = state.flow.unknown_said;
    let walked = check_core_value_of(state, world, host, expr, span);
    let said_inside = state.flow.unknown_said > said_before;
    let opened = check_core_expr_open_receiver(state, expr, walked);
    let ty = check_core_expr_flat_get(state, world, expr, opened);
    if state.flow.read_a_map && check_core_expr_a_map_read(world, expr) { state.flow.map_read_sites.insert(id_of(expr) as i64); }
    if check_core_expr_makes_a_value(expr) { check_crossings_a_value_with_a_cleanup_made(state, world, &ty); }
    state.a_member_of_an_unknown_lambda_parameter(world, expr, span);
    if ty.is_unknown() && !said_inside { state.a_value_of_no_known_type(world, expr, span); }
    ty
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_expr_an_open_char_read(state: &mut CheckState, expr: &Expr, name: &str, span: &Span) {
    if state.flow.open_chars.is_empty() { return; }
    let local = match state.binding(name) { Some(__nikaia_value) => __nikaia_value, None => return };
    let found = match *nikaia_std::index::get(&state.flow.open_chars, &local.id) { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut open = found.clone();
    open.reads.insert(id_of(expr) as i64, span.clone());
    state.flow.open_chars.insert(local.id, open);
}

fn check_core_expr_makes_a_value(expr: &Expr) -> bool { matches!(expr, Expr::Call { .. } | Expr::MethodCall { .. } | Expr::SafeMethod { .. } | Expr::StructLit { .. }) }

fn check_core_expr_a_map_read(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, expr: &Expr) -> bool {
    match expr {
        Expr::Index { .. } => true,
        Expr::MethodCall { method, .. } => { let method = *method; world.words.resolve(method) == "get" },
        _ => false,
    }
}

fn check_core_expr_its_own(ty: &Ty, own: &str) -> bool {
    match ty {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); match inner {
            Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && name == own },
            _ => false,
        } },
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && name == own },
        _ => false,
    }
}

