fn check_core_ops_plain_text(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && name == TEXT },
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_ops_text_base(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, .. } => check_core_ops_base(name) == "String" || check_core_ops_base(name) == "str",
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_ops_held_matches(inner: &Ty, other: &Ty) -> bool {
    match inner {
        Ty::Named { name, args, .. } => name != "str" && name != "String" && *other == Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false },
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_ops_not_plain(inner: &Ty) -> bool {
    match inner {
        Ty::Named { name, .. } => !a_number_name(name) && !check_core_ops_plain_base(&check_core_ops_base(name)),
        _ => false,
    }
}

fn check_core_ops_a_number_written(node: &Expr) -> bool { matches!(node, Expr::LitInt { .. } | Expr::LitFloat { .. }) }

fn check_core_ops_number_written_kind(node: &Expr) -> String {
    match node {
        Expr::LitInt { .. } => "integer".to_owned(),
        Expr::LitFloat { .. } => "float".to_owned(),
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); if *op == UnaryOp::Neg { check_core_ops_number_written_kind(expr) } else { "".to_owned() } },
        _ => "".to_owned(),
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_ops_own_type(inner: &Ty) -> bool {
    match inner {
        Ty::Named { args, view, .. } => { let view = *view; !view && args.is_empty() && check_core_ops_not_plain(inner) },
        _ => false,
    }
}

fn check_core_ops_kind(ty: &Ty) -> String {
    match ty {
        Ty::Named { name, args, .. } => {
            if !args.is_empty() { return String::from(""); }
            if a_number_name(name) { return String::from("number"); }
            let base = check_core_ops_base(name);
            if base == "String" || base == "str" { return String::from("text"); }
            if base == "bool" || base == "char" { return base; }
        },
        _ => { },
    }
    String::from("")
}

fn check_core_ops_plain_base(base: &str) -> bool { base == "bool" || base == "char" || base == "scalar" || base == "String" || base == "str" }

