pub fn check_specialised(function: &str, on: &str) -> String {
    let tail: String = on.replace("::", "__");
    format!("{}__{}", function, tail)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_grammar_call<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, key: &str, args: &[Expr], span: &Span) -> Ty {
    for arg in args.iter() {
        let given = check_core_expr(state, world, host, arg, span);
        let over_bytes = match given {
            Ty::Named { ref name, args: ref inner, .. } => name == "Bytes" && inner.is_empty(),
            _ => false,
        };
        let over_text = match given {
            Ty::Named { ref name, args: ref inner, .. } => (name == "String" || name == "str" || name == "Mapped") && inner.is_empty(),
            _ => false,
        };
        if !over_bytes && !over_text && !given.is_unknown() { state.findings.push(check_core_grammar_input_refused(key, &given, span)); }
        let cut = nikaia_std::index::or(nikaia_std::search::find(&key, &"::", 0), || 0);
        if over_bytes && cut > 0 {
            state.facts.bytes_entries.insert(id_of(arg) as i64);
            state.facts.bytes_grammars.insert(nikaia_std::index::get(&key, nikaia_std::index::at(0..cut)).to_owned());
        }
    }
    let contract = match match *nikaia_std::index::get(&world.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    if !contract.fails_with.is_empty() && state.flow.guarded.is_some() {
        let held: Option<CheckGuarded> = match state.flow.guarded.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        let mut guarded = nikaia_std::index::or(held, || CheckGuarded::nothing());
        guarded.fallible = true;
        for thrown in contract.fails_with.iter() { guarded.thrown.insert(thrown.to_owned()); }
        state.flow.guarded = Some(guarded);
    }
    let signature = match contract.signature { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    nikaia_std::index::or(signature.result, || Ty::Unknown)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_a_compound_write_to_a_map_slot<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, target: &Expr, span: &Span) {
    match target {
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let read = check_core_expr(state, world, host, target, span);
            let nullable = matches!(read, Ty::Nullable(_));
            if !nullable { return; }
            let slot = format!("{}[{}]", host.written(base), host.written(index));
            let notes: Vec<String> = vec!["A missing key is normal, not a bug, so this line has to say what a missing key counts as.".to_owned()];
            let help: String = format!("Write it out with a fallback for a missing key: `{} = ({} ?? 0) + 1`.", slot, slot);
            state.findings.push(check_refusal("NK1162", span, format!("`{}` reads the map before writing it, and the key might not be there yet.", slot), notes, Some(help)));
        },
        _ => { return; },
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_an_instantiation<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, name: &str, call: i64, args: &[Expr], span: &Span) {
    if !state.walks_fields.contains_key(name) { return; }
    if args.is_empty() { return; }
    let before = state.findings.len() as i64;
    let given = check_core_expr(state, world, host, nikaia_std::index::get(&args, 0), span);
    state.findings.truncate(nikaia_std::count::of(before));
    let on: String = match given {
        Ty::Named { ref name, .. } => name.to_owned(),
        _ => return,
    };
    let fields = match state.shape_of(&world.here, world, &on) { Some(__nikaia_value) => __nikaia_value, None => return };
    state.facts.unrolled_calls.insert(call, check_specialised(name, &on));
    state.facts.unrolled.insert((name.to_owned(), on.to_owned()), fields);
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn check_core_a_mut_parameter_given_away<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, value: &Expr, span: &Span, what: &str) {
    let name: String = match value {
        Expr::Variable(symbol, _) => { let symbol = *symbol; world.words.resolve(symbol).to_owned() },
        _ => return,
    };
    let local = match state.binding(&name) { Some(__nikaia_value) => __nikaia_value, None => return };
    if !local.changing { return; }
    let ty = check_core_expr(state, world, host, value, span);
    if ty.is_a_view() && what == "handed back" {
        let notes: Vec<String> = vec![format!("`mut {}: {}` changes the caller's view in place, so handing it back hands back a view of the caller's view.", name, ty.text()).to_owned()];
        let help: String = format!("Take `{}: {}` without `mut`, and walk a local of its own: `let mut at = {}`, then `return at`.", name, ty.text(), name);
        state.findings.push(check_refusal("NK1131", span, format!("You can't hand back `{}` here: a `mut` parameter that is a view is only borrowed.", name), notes, Some(help)));
        return;
    }
    if ty.is_unknown() || state.copied(world, &ty) { return; }
    let mut way: String = "".to_owned();
    if what == "handed back" { way = " to return".to_owned(); }
    let notes: Vec<String> = vec![format!("`mut {}` is passed as `ref mut`, so the caller's `{}` is changed in place and stays the caller's. Giving it away would take it from them.", name, ty.text())];
    let help: String = format!("Write `{}.clone()` for a copy{}, or drop the `mut` if the function is meant to use up its value.", name, way);
    state.findings.push(check_refusal("NK1131", span, format!("You can't give away `{}` here: a `mut` parameter is only borrowed.", name), notes, Some(help)));
}

fn check_core_grammar_input_refused(key: &str, given: &Ty, span: &Span) -> CheckFinding {
    let message = format!("`{}` parses a `String` or a `Bytes`, and is handed a `{}`.", key, given.text());
    let notes: Vec<String> = vec!["A grammar reads text or bytes; the argument decides which.".to_owned()];
    let help = "Hand it the text or the bytes to parse.".to_owned();
    check_refusal("NK1282", span, message, notes, Some(help))
}


// --- check_core_places.nika ---

fn check_core_places_named(name: &str) -> Ty { Ty::Named { name: name.to_owned(), args: vec![], view: false } }

fn check_core_places_str_view() -> Ty { Ty::Named { name: "str".to_owned(), args: vec![], view: true } }

fn check_core_places_base(name: &str) -> String {
    let parts: Vec<&str> = name.split("::").collect::<Vec<_>>();
    if parts.is_empty() { return name.to_owned(); }
    let last = parts.len() as i64 - 1;
    format!("{}", *nikaia_std::index::get(&parts, nikaia_std::index::at(last)))
}

fn check_core_places_a_list(base: &str) -> bool { base == "Vec" || base == "List" || base == "Array" }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_places_a_range(index: &Expr) -> bool { matches!(index, Expr::Range { .. }) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_places_a_closure(value: Option<&Expr>) -> bool {
    let v: &Expr = match value { Some(__nikaia_value) => __nikaia_value, None => return false };
    matches!(v, Expr::Closure { .. })
}

fn check_core_places_position(field: &str) -> i64 {
    if field.is_empty() { return -1; }
    for c in field.chars() { if c < '0' || c > '9' { return -1; } }
    nikaia_std::index::or(text::parse_i64(field), || -1)
}

fn check_core_places_bound(bound: &collections::BTreeMap<String, Ty>, p: &str) -> Ty {
    nikaia_std::index::or(match bound.get(p) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Ty::Unknown)
}

fn check_core_places_unrolled_default(unrolling: Option<&CheckUnrolling>) -> Ty {
    let u: &CheckUnrolling = match unrolling { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    Ty::Nullable(Box::new(u.field.ty.clone()))
}

fn check_core_places_offered(name: &str) -> bool { name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64" || name == "f32" || name == "f64" || name == "bool" || name == "char" || name == "scalar" || name == "String" || name == "str" }

pub fn check_core_places_beyond_f32(value: &Expr) -> bool {
    match check_peeled(value) {
        Expr::LitFloat(written, _) => {
            let number = nikaia_std::index::or(text::parse_f64(written), || 0.0);
            number > 340282346638528859811704183484516925440.0
        },
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); *op == UnaryOp::Neg && check_core_places_beyond_f32(expr) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); check_core_places_beyond_f32(lhs) || check_core_places_beyond_f32(rhs) },
        _ => false,
    }
}

fn check_core_places_an_integer(name: &str) -> bool { name == "u8" || name == "u32" || name == "u64" || name == "i32" || name == "i64" }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_places_given<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, value: Option<&Expr>, field: &str, span: &Span) -> Ty {
    if value.is_none() { return nikaia_std::index::or(state.lookup(field), || Ty::Unknown); }
    let v: &Expr = match value { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    check_core_expr(state, world, host, v, span)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_places_tuple_part(state: &mut CheckState, parts: &[Ty], field: &str, span: &Span) -> Ty {
    let at = check_core_places_position(field);
    if at >= 0 && at >= parts.len() as i64 {
        let count = parts.len() as i64;
        let mut last = count - 1;
        if last < 0 { last = 0; }
        let mut help: String = String::from("There's nothing in it to read.");
        if count > 0 { help = format!("Use one of `.0` to `.{}`.", last); }
        state.findings.push(CheckFinding { severity: CheckSeverity::Error, span: span.clone(), code: "NK1107".to_owned(), message: format!("This tuple has no part `.{}`.", at), notes: vec![format!("A tuple's parts are counted from 0, and this one has {}.", count)], help: Some(help), labels: vec![] });
        return Ty::Unknown;
    }
    if at < 0 { return Ty::Unknown; }
    (*nikaia_std::index::get(&parts, nikaia_std::index::at(at))).clone()
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_core_places_a_named_field(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, expr: &Expr, on: &Ty, ty: &str, field: &str, span: &Span) -> Ty {
    if (ty == "String" || ty == "str") && field == "bytes" {
        state.facts.text_bytes.insert(id_of(expr) as i64);
        return check_core_places_named("Bytes");
    }
    if (ty == "String" || ty == "str") && field == "scalars" {
        state.facts.text_scalars.insert(id_of(expr) as i64);
        return Ty::Seq { item: Box::new(check_core_places_named("scalar")), is_sync: true, pauses: false, can_throw: false, parallel: false, shape: Shape { ends: true, sized: false, replays: false } };
    }
    if (ty == "String" || ty == "str") && field == "graphemes" {
        state.facts.text_graphemes.insert(id_of(expr) as i64);
        let grapheme = check_core_places_str_view();
        return Ty::Seq { item: Box::new(grapheme), is_sync: true, pauses: false, can_throw: false, parallel: false, shape: Shape { ends: false, sized: false, replays: false } };
    }
    let boxed = state.facts.boxed_members.get(ty);
    if boxed.is_some() {
        let members = match boxed { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
        if members.contains(field) { state.facts.boxed_reads.insert(id_of(expr) as i64); }
    }
    if state.opaque_handles.contains(ty) {
        state.a_handle_has_nothing_inside(ty, &format!("the field `{}`", field), span);
        return Ty::Unknown;
    }
    if ty == "$Variant" {
        if field == "name" { return check_core_places_str_view(); }
        state.a_reflected_variant_has_two_members(field, span);
        return Ty::Unknown;
    }
    if ty == "$Field" {
        if field == "name" { return check_core_places_str_view(); }
        if field == "default" { return check_core_places_unrolled_default((state.flow.unrolling).as_ref()); }
        state.a_reflected_field_has_two_members(field, span);
        return Ty::Unknown;
    }
    let declared: Option<Vec<FieldContract>> = state.fields_of(world, ty);
    if declared.is_none() {
        state.nothing_says_what_a_parameter_can_do(ty, "field", field, span);
        return Ty::Unknown;
    }
    let fields: Vec<FieldContract> = match declared { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    for found in fields.iter() {
        if found.name == field {
            state.field_is_reachable(ty, found, span);
            if a_field_of_static_text(&world.here, ty, field) { state.facts.static_field_reads.insert(id_of(expr) as i64); }
            return substitute(&found.ty, &state.arguments_of(on));
        }
    }
    state.no_such_field(ty, field, &fields, span);
    Ty::Unknown
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
pub fn check_core_field<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, safe: bool, base: &Expr, name: winnow_grammar::Symbol, span: &Span) -> Ty {
    let on = check_core_expr(state, world, host, base, span);
    let field: String = format!("{}", world.words.resolve(name));
    if safe {
        match on {
            Ty::Nullable(ref inner) => {
                let inner = nikaia_std::boxed::open(inner);
                match *inner {
                    Ty::Tuple(ref parts) => {
                        let part = check_core_places_tuple_part(state, parts, &field, span);
                        if part.is_unknown() { return Ty::Unknown; }
                        return state.a_safe_reach(base, &part);
                    },
                    _ => { },
                }
                return state.a_safe_field(world, inner, base, &field, expr, span);
            },
            Ty::Unknown => { return Ty::Unknown; },
            _ => { state.reaches_through_a_plain_value(world, &on, base, &field, false, expr, span); },
        }
    }
    state.a_read_of_a_part(base, expr, &field, span);
    match on {
        Ty::Nullable(_) => {
            state.reaches_into_a_nullable(&on, "field", &field, span);
            return Ty::Unknown;
        },
        _ => { },
    }
    let members = several_errors_of(&on);
    if !members.is_empty() {
        let named = members_named(&members);
        state.findings.push(CheckFinding { severity: CheckSeverity::Error, span: span.clone(), code: "NK1107".to_owned(), message: format!("This is an error, one of {}, and an error has no field `{}`.", named, field), notes: vec!["A field belongs to one of them, and which one it is is said by a `match`.".to_owned()], help: Some(format!("Take it apart first: `match error {{ … }}`, and read `{}` in the arm of the type that has it.", field)), labels: vec![] });
        return Ty::Unknown;
    }
    match on {
        Ty::Tuple(ref parts) => { return check_core_places_tuple_part(state, parts, &field, span); },
        _ => { },
    }
    let mut seen: Ty = on.clone();
    match on {
        Ty::Named { ref name, .. } => { if state.fields_of(world, name).is_none() { seen = nikaia_std::index::or(state.seen_through(world, &on), || on.clone().into()); } },
        _ => { },
    }
    let ty: String = match seen {
        Ty::Named { ref name, .. } => name.to_owned(),
        _ => return Ty::Unknown,
    };
    let got = check_core_places_a_named_field(state, world, expr, &seen, &ty, &field, span);
    match got {
        Ty::Named { ref name, ref args, .. } => { if args.is_empty() && is_whole_number(name) { state.facts.whole_fields.insert(id_of(expr) as i64); } },
        _ => { },
    }
    check_core_places_array_length(state, id_of(expr) as i64, &got);
    got
}

