fn check_core_places_lent_field(want: &Ty, given: &Ty) -> bool {
    let viewed = match want {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_a_view() },
        _ => want.is_a_view(),
    };
    let owned = match given {
        Ty::Named { view, .. } => { let view = *view; !view },
        _ => false,
    };
    viewed && owned
}

