fn check_core_stmt_a_shift(op: Option<&BinaryOp>) -> bool {
    if op.is_none() { return false; }
    let o: &BinaryOp = match op { Some(__nikaia_value) => __nikaia_value, None => return false };
    *o == BinaryOp::Shl || *o == BinaryOp::Shr
}

