fn check_fields_map_parts(ty: &Ty) -> Vec<Ty> {
    match ty {
        Ty::Named { args, .. } => if args.len() == 2 { args.to_owned() } else { vec![Ty::Unknown, Ty::Unknown] },
        _ => vec![Ty::Unknown, Ty::Unknown],
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
