fn host_known(local: &CheckLocal) -> Option<BuildValue> {
    let built: Option<BuildValue> = match local.built.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if built.is_some() { return std::convert::identity(built); }
    let number = match local.constant { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(BuildValue::Int(number))
}

fn host_stopped_line(said: &str) -> String {
    for line in said.lines() { if line.contains("the program stopped") { return line.to_owned(); } }
    said.to_owned()
}

fn host_folds(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, value: &Expr, enums: &collections::BTreeSet<String>) -> bool {
    match value {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::LitBool(_, _) => true,
        Expr::LitStr { .. } => true,
        Expr::Variable(_, _) => true,
        Expr::Path(_, _) => true,
        Expr::Tuple(parts, _) => host_all_fold(world, parts, enums),
        Expr::ListLit { items, .. } => host_all_fold(world, items, enums),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); host_folds(world, expr, enums) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); host_folds(world, lhs, enums) && host_folds(world, rhs, enums) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); host_folds(world, base, enums) && host_folds(world, index, enums) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); host_folds(world, base, enums) },
        Expr::StructLit { fields, .. } => {
            let mut all = true;
            for field in fields.iter() {
                let given = match field.value.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                };
                if given.is_none() || !host_folds(world, &nikaia_std::index::or(given, || Expr::LitNull(fresh_id())), enums) { all = false; }
            }
            all
        },
        Expr::LitInterpolated { parts, .. } => {
            let mut all = true;
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { if !host_folds(world, expr, enums) { all = false; } },
                    _ => { },
                }
            }
            all
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            let mut all = host_folds(world, cond, enums) && host_branch_folds(world, then_branch, enums);
            if else_branch.is_some() {
                let other = nikaia_std::index::or(match else_branch {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, || Block { stmts: vec![] });
                all = all && host_branch_folds(world, &other, enums);
            }
            all
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            match func {
                Expr::Variable(name, _) => { let name = *name; world.words.resolve(name) == "asset" },
                Expr::Path(path, _) => path.len() == 2 && enums.contains(world.words.resolve(*nikaia_std::index::get(&path, 0))) && config.is_empty() && host_all_fold(world, args, enums),
                _ => false,
            }
        },
        _ => false,
    }
}

fn host_all_fold(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, values: &[Expr], enums: &collections::BTreeSet<String>) -> bool {
    for value in values.iter() { if !host_folds(world, value, enums) { return false; } }
    true
}

fn host_branch_folds(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, block: &Block, enums: &collections::BTreeSet<String>) -> bool {
    if block.stmts.len() != 1 { return false; }
    match &nikaia_std::index::get(&block.stmts, 0).node {
        Stmt::Expr(inner) => host_folds(world, inner, enums),
        _ => false,
    }
}

fn host_enum_names(view: &ParsedView<'_, '_, '_, '_, '_, '_>, out: &mut collections::BTreeSet<String>) {
    for item in view.items.iter() {
        let named: String = match &item.node {
            Item::Enum { name, .. } => { let name = *name; view.text(name) },
            _ => String::from(""),
        };
        if named != "" { out.insert(named); }
    }
}

fn host_grammar_names(view: &ParsedView<'_, '_, '_, '_, '_, '_>, out: &mut collections::BTreeSet<String>) {
    for item in view.items.iter() {
        let named: String = match &item.node {
            Item::Grammar(def) => view.text(def.name),
            _ => String::from(""),
        };
        if named != "" { out.insert(named); }
    }
}

fn host_runs_a_grammar(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, value: &Expr, grammars: &collections::BTreeSet<String>) -> bool {
    let mut runs = false;
    for expr in visited_in_expr(value) {
        match expr {
            Expr::Call { func, .. } => {
                let func = nikaia_std::boxed::open(func);
                match func {
                    Expr::Path(path, _) => { if !path.is_empty() && grammars.contains(world.words.resolve(*nikaia_std::index::get(&path, 0))) { runs = true; } },
                    _ => { },
                }
            },
            Expr::MethodCall { receiver, .. } => {
                let receiver = nikaia_std::boxed::open(receiver);
                match receiver {
                    Expr::Variable(name, _) => {
                        let name = *name;
                        if grammars.contains(world.words.resolve(name)) { runs = true; }
                    },
                    _ => { },
                }
            },
            _ => { },
        }
    }
    runs
}

fn host_assets_in<H: CheckHost>(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, value: &Expr) -> Vec<(String, bool)> {
    let mut found: Vec<(String, bool)> = vec![];
    for expr in visited_in_expr(value) {
        match expr {
            Expr::Call { func, args, .. } => {
                let func = nikaia_std::boxed::open(func);
                match func {
                    Expr::Variable(name, _) => {
                        let name = *name;
                        if world.words.resolve(name) == "asset" {
                            let mut path: String = String::from("");
                            let mut literal = false;
                            if args.len() == 1 {
                                match nikaia_std::index::get(&args, 0) {
                                    Expr::LitStr { text, .. } => {
                                        let read = host.decoded(text);
                                        if read.is_some() {
                                            path = nikaia_std::index::or(read, || "".into());
                                            literal = true;
                                        }
                                    },
                                    _ => { },
                                }
                            }
                            found.push((path, literal));
                        }
                    },
                    _ => { },
                }
            },
            _ => { },
        }
    }
    found
}

fn host_ring_names(view: &ParsedView<'_, '_, '_, '_, '_, '_>, comptimes: &mut collections::BTreeSet<String>, options: &mut collections::BTreeMap<String, Vec<String>>) {
    for item in view.items.iter() {
        match &item.node {
            Item::Comptime { name, .. } => {
                let name = *name;
                comptimes.insert(view.text(name));
            },
            Item::Fn { name, receiver, config, .. } => {
                let name = *name;
                if receiver.is_none() && name.is_some() {
                    let mut held: Vec<String> = vec![];
                    for option in config.iter() { held.push(view.text(option.name)); }
                    options.insert(view.text(match name { Some(__nikaia_value) => __nikaia_value, None => continue }), held);
                }
            },
            _ => { },
        }
    }
}

fn host_ring_edge(view: &ParsedView<'_, '_, '_, '_, '_, '_>, expr: &Expr, comptimes: &collections::BTreeSet<String>, options: &collections::BTreeMap<String, Vec<String>>, out: &mut Vec<String>) {
    match expr {
        Expr::Variable(name, _) => {
            let name = *name;
            let named = view.text(name);
            if comptimes.contains(&named) { out.push(format!("c:{}", named)); }
            if options.get(&named).is_some() { out.push(format!("f:{}", named)); }
        },
        Expr::Call { func, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            match func {
                Expr::Variable(name, _) => {
                    let name = *name;
                    let named = view.text(name);
                    let mut given: collections::BTreeSet<String> = collections::BTreeSet::new();
                    for arg in config.iter() { given.insert(view.text(arg.name)); }
                    let declared: Vec<String> = nikaia_std::index::or(match options.get(&named) {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || vec![].into());
                    for option in declared.iter() { if !given.contains(option) { out.push(format!("d:{}:{}", named, option)); } }
                },
                _ => { },
            }
        },
        _ => { },
    }
}

fn host_ring_graph(view: &ParsedView<'_, '_, '_, '_, '_, '_>, comptimes: &collections::BTreeSet<String>, options: &collections::BTreeMap<String, Vec<String>>, graph: &mut collections::BTreeMap<String, Vec<String>>, labels: &mut collections::BTreeMap<String, String>) {
    for item in view.items.iter() {
        match &item.node {
            Item::Comptime { name, value, .. } => {
                let name = *name;
                let named = view.text(name);
                let mut out: Vec<String> = vec![];
                for expr in visited_in_expr(value) { host_ring_edge(view, expr, comptimes, options, &mut out); }
                graph.insert(format!("c:{}", named), out);
                labels.insert(format!("c:{}", named), named.to_owned());
            },
            Item::Fn { name, receiver, config, body, .. } => {
                let name = *name;
                if receiver.is_none() && name.is_some() {
                    let named = view.text(match name { Some(__nikaia_value) => __nikaia_value, None => continue });
                    let mut out: Vec<String> = vec![];
                    for expr in visited_in_block(body) { host_ring_edge(view, expr, comptimes, options, &mut out); }
                    graph.insert(format!("f:{}", named), out);
                    labels.insert(format!("f:{}", named), named.to_owned());
                    for option in config.iter() {
                        let mut read: Vec<String> = vec![];
                        for expr in visited_in_expr(&option.default) { host_ring_edge(view, expr, comptimes, options, &mut read); }
                        let key = format!("d:{}:{}", named, view.text(option.name));
                        graph.insert(key.to_owned(), read);
                        labels.insert(key, named.to_owned());
                    }
                }
            },
            _ => { },
        }
    }
}

fn host_ring_reach(graph: &collections::BTreeMap<String, Vec<String>>, labels: &collections::BTreeMap<String, String>, at: &str, path: &mut Vec<String>, done: &mut collections::BTreeSet<String>) -> Vec<String> {
    let mut from = path.len() as i64;
    let mut i: i64 = 0;
    for held in path.iter() {
        if held == at && from == path.len() as i64 { from = i; }
        i += 1;
    }
    if from < path.len() as i64 {
        let mut computed = false;
        let mut ring: Vec<String> = vec![];
        let mut j = from;
        while j < path.len() as i64 {
            if !(*nikaia_std::index::get(&path, nikaia_std::index::at(j))).starts_with("f:") { computed = true; }
            ring.push(nikaia_std::index::or(match labels.get(nikaia_std::index::get(&path, nikaia_std::index::at(j))) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into()));
            j += 1;
        }
        if !computed { return vec![]; }
        ring.push(nikaia_std::index::or(match labels.get(at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into()));
        return ring;
    }
    if done.contains(at) { return vec![]; }
    let next: Vec<String> = nikaia_std::index::or(match graph.get(at) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    path.push(at.to_owned());
    for step in next.iter() {
        let ring = host_ring_reach(graph, labels, step, path, done);
        if !ring.is_empty() { return ring; }
    }
    path.pop();
    done.insert(at.to_owned());
    vec![]
}

fn host_ring(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, value: &Expr) -> Vec<String> {
    let mut comptimes: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut options: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    if world.here_at < 0 { host_ring_names(&world.here, &mut comptimes, &mut options); }
    for file in world.beside.iter() { host_ring_names(file, &mut comptimes, &mut options); }
    let mut start: Vec<String> = vec![];
    for expr in visited_in_expr(value) { host_ring_edge(&world.here, expr, &comptimes, &options, &mut start); }
    if start.is_empty() { return vec![]; }
    let mut graph: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    let mut labels: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    if world.here_at < 0 { host_ring_graph(&world.here, &comptimes, &options, &mut graph, &mut labels); }
    for file in world.beside.iter() { host_ring_graph(file, &comptimes, &options, &mut graph, &mut labels); }
    let mut path: Vec<String> = vec![];
    let mut done: collections::BTreeSet<String> = collections::BTreeSet::new();
    for step in start.iter() {
        let ring = host_ring_reach(&graph, &labels, step, &mut path, &mut done);
        if !ring.is_empty() { return ring; }
    }
    vec![]
}

