fn check_is_fatal(ledger: &Ledger, error: &str) -> bool {
    let types = match ledger.implementations.get("Fatal") { Some(__nikaia_value) => __nikaia_value, None => return false };
    types.contains(error)
}

impl CheckState {
    pub fn a_fatal_error_passes(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, guarded: &CheckGuarded, handler: &Block, span: &Span) {
        let named = fatal_named(handler, world.words);
        let mut passing: Vec<String> = vec![];
        for error in guarded.thrown.iter() { if (check_is_fatal(world.own, error) || check_is_fatal(world.library, error)) && !named.contains(error) { passing.push(error.to_owned()); } }
        if passing.is_empty() { return; }
        if self.flow.guarded.is_some() {
            let held: Option<CheckGuarded> = match self.flow.guarded.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            let mut outer = nikaia_std::index::or(held, || CheckGuarded::nothing());
            outer.fallible = true;
            for error in passing.iter() { outer.thrown.insert(error.to_owned()); }
            self.flow.guarded = Some(outer);
        }
        if self.flow.throwing || self.flow.caught { return; }
        let mut quoted: Vec<String> = vec![];
        for error in passing.iter() { quoted.push(format!("`{}`", error)); }
        let list = quoted.join(", ");
        self.findings.push(check_refusal("NK2605", span, format!("This function can fail, because {} passes this `catch`.", list), vec![format!("{} is fatal: a `catch` takes it only in a `match` arm that names its type, and this handler does not.", list)], Some("Add `throws` to the function, or name the type in a `match error` arm of the handler.".to_owned())));
    }
}

impl CheckState {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn may_fail_here<H: CheckHost>(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, key: &str, contract: &FnContract, span: &Span) {
        if !contract.fails_with.is_empty() {
            let word = type_last_segment(key);
            self.a_way_out("fails", &word, span);
        }
        if !contract.fails_with.is_empty() {
            if self.flow.guarded.is_some() {
                let held: Option<CheckGuarded> = match self.flow.guarded.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                };
                let mut guarded = nikaia_std::index::or(held, || CheckGuarded::nothing());
                guarded.fallible = true;
                for thrown in contract.fails_with.iter() { guarded.thrown.insert(thrown.to_owned()); }
                self.flow.guarded = Some(guarded);
            }
            if world.newly_throws.contains_key(key) {
                let list = match world.newly_throws.get(key) { Some(__nikaia_value) => __nikaia_value, None => return };
                self.newly_reaches_a_handler(key, &list, span);
            }
            if self.handed_over.is_some() {
                let held = match match self.handed_over.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => return };
                if !held.caught {
                    let mut handed = held;
                    handed.fails = true;
                    let may_fail = handed.promised.may_fail;
                    self.handed_over = Some(handed);
                    if !may_fail { return; }
                }
            }
        }
        if contract.fails_with.is_empty() || self.flow.throwing || self.flow.caught { return; }
        if self.inside_an_action.is_some() { return; }
        let function = match match self.current.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        let mut errors: Vec<String> = vec![];
        for error in contract.fails_with.iter() { errors.push(format!("`{}`", error)); }
        let list = errors.join(", ");
        self.findings.push(CheckFinding { severity: CheckSeverity::Error, span: span.clone(), code: "NK2605".to_owned(), message: format!("This function can fail, because `{}` can fail.", key), notes: vec![format!("`{}` can fail with {}.", key, list), "A call that can fail looks like any other call, so its failure passes straight through this function unless you handle it.".to_owned()], help: Some(format!("Add `throws` to `{}`, or handle it at the call: `… catch {{ … }}`.", function)), labels: vec![] });
    }
}


