pub fn integer_named(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if args.is_empty() && !view && (name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64") { Some(name.to_owned()) } else { None } },
        _ => None,
    }
}

