fn held_name(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if !view && args.is_empty() { Some(name.to_owned()) } else { None } },
        _ => None,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
