// this was written - see `contracts::sync`.
fn a_type_named(ty: &Ty, wanted: &str, viewed: bool) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; name == wanted && args.is_empty() && view == viewed },
        _ => false,
    }
}

