fn check_reads_keyed_by_views(on: &Ty) -> bool {
    match on {
        Ty::Named { name, args, .. } => {
            let base = type_last_segment(name);
            let keyed = base == "HashMap" || base == "BTreeMap" || base == "HashSet" || base == "BTreeSet" || base == "Map" || base == "Set";
            keyed && !args.is_empty() && (*nikaia_std::index::get(&args, 0)).is_a_view() && names_text(nikaia_std::index::get(&args, 0))
        },
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_reads_keyed_by_numbers(on: &Ty) -> bool {
    match on {
        Ty::Named { name, args, .. } => {
            let base = type_last_segment(name);
            let keyed = base == "HashMap" || base == "BTreeMap" || base == "HashSet" || base == "BTreeSet" || base == "Map" || base == "Set";
            keyed && !args.is_empty() && check_copied(nikaia_std::index::get(&args, 0))
        },
        _ => false,
    }
}


// --- check_references.nika ---

fn check_reference_opened(opened: &str) -> String {
    if opened == ".as_deref()" { return ".as_deref()".to_owned(); }
    ".as_ref()".to_owned()
}

fn check_reference_written(expr: &Expr) -> bool {
    match expr {
        Expr::Unary { op, .. } => matches!(op, UnaryOp::Ref),
        _ => false,
    }
}

fn check_reference_nullable(ty: &Ty) -> bool { matches!(ty, Ty::Nullable(_)) }

fn check_reference_nullable_view(ty: &Ty) -> bool {
    match ty {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_a_view() },
        _ => false,
    }
}

