// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn ends_in_tuple(expr: &Expr) -> bool {
    let ends = tuple_ends(expr);
    if ends.is_empty() { return false; }
    let mut tuples = 0;
    for end in ends.iter() {
        let end = *end;
        match end {
            Expr::Tuple(_, _) => { tuples = tuples + 1; },
            Expr::LitNull(_) => { },
            _ => { return false; },
        }
    }
    tuples > 0
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn tuple_ends(expr: &Expr) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    match expr {
        Expr::If { then_branch, else_branch, .. } => {
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
            for block in [then_branch, otherwise] {
                let tail = block_tail(block);
                if tail.len() != 1 { return vec![]; }
                for end in tuple_ends(*nikaia_std::index::get(&tail, 0)) { out.push(end); }
            }
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { for end in tuple_ends(&arm.body) { out.push(end); } } },
        Expr::Block(block, _) => {
            let tail = block_tail(block);
            if tail.len() != 1 { return vec![]; }
            return tuple_ends(*nikaia_std::index::get(&tail, 0));
        },
        _ => { out.push(expr); },
    }
    out
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn literal_tuple_parts(value: &Expr) -> Vec<&Expr> {
    match value {
        Expr::Tuple(parts, _) => refs_of(parts),
        _ => vec![],
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn list_items(value: &Expr) -> Vec<&Expr> {
    match value {
        Expr::ListLit { items, .. } => refs_of(items),
        _ => vec![],
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn named_arguments(ty: &Ty) -> Vec<Ty> {
    match ty {
        Ty::Named { args, .. } => args.to_owned(),
        _ => vec![],
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn refs_of(items: &[Expr]) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = vec![];
    for item in items.iter() { out.push(item); }
    out
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn check_texts_a_byte_as_a_scalar(written: &str, name: Option<String>, span: &Span) -> CheckFinding {
    let value = nikaia_std::index::or(a_high_byte(written), || 128);
    let hex = hex_of(value);
    let note = "Above `\\x7F` a `'\\xNN'` names a byte, which is a `u8` and no `scalar`: the scalar of that number is another character, two bytes in UTF-8 (Part I 2.6).";
    let mut annotated = format!("`let b: u8 = '{}'`", written);
    if name.is_some() { annotated = format!("`let {}: u8 = '{}'`", nikaia_std::index::or(name.as_deref(), || ""), written); }
    check_refusal("NK1212", span, format!("`'{}'` is the byte {}, and it is used as a `scalar`.", written, value), vec![note.to_owned()], Some(format!("For the scalar U+00{}, write `'\\u{{{}}}'`; for the byte, declare it a `u8`: {}.", hex.to_uppercase(), hex, annotated)))
}

impl CheckState {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn chars_typed_by_their_uses(&mut self) {
        for (_, open) in self.flow.open_chars.iter() {
            let mut first_byte: Option<Span> = None;
            let mut first_scalar: Option<Span> = None;
            for (read, at) in open.reads.iter() {
                let read = nikaia_std::num::value(read);let at = *at;
                if open.bytes.contains(&read) { if first_byte.is_none() || nikaia_std::index::or(first_byte.as_ref().map(|__nikaia_it| __nikaia_it.start), || 0) > at.start { first_byte = Some(at.clone()); } } else if first_scalar.is_none() || nikaia_std::index::or(first_scalar.as_ref().map(|__nikaia_it| __nikaia_it.start), || 0) > at.start { first_scalar = Some(at.clone()); }
            }
            if first_byte.is_some() && first_scalar.is_some() {
                let byte_at = nikaia_std::index::or(first_byte, || open.at.clone().into());
                let scalar_at = nikaia_std::index::or(first_scalar, || open.at.clone().into());
                let mut first = "scalar";
                let mut second = "u8";
                let mut later = byte_at.clone();
                if byte_at.start < scalar_at.start {
                    first = "u8";
                    second = "scalar";
                    later = scalar_at.clone();
                }
                let note = "A `'…'` takes its type from how it's used, `u8` or `scalar`, and these uses want both.";
                self.findings.push(check_refusal("NK1200", &later, format!("You're using `{}` as {} `{}` and here as {} `{}`.", open.name, an_or_a(first), first, an_or_a(second), second), vec![note.to_owned()], Some(format!("Declare its type, `let {}: u8 = '{}'`, and convert with `as` where the other one is needed.", open.name, open.written))));
            } else if first_byte.is_some() { self.facts.byte_literals.insert(open.literal); } else if a_high_byte(&open.written).is_some() { self.findings.push(check_texts_a_byte_as_a_scalar(&open.written, Some(open.name.to_owned()), &open.at)); }
        }
        self.flow.open_chars = collections::BTreeMap::new();
        for (literal, held) in self.flow.high_bytes.iter() {
            let literal = nikaia_std::num::value(literal);
            if !self.facts.byte_literals.contains(&literal) { self.findings.push(check_texts_a_byte_as_a_scalar(&held.0, None, &held.1)); }
        }
        self.flow.high_bytes = collections::BTreeMap::new();
    }
}


// --- check_types.nika ---

pub fn a_number_name(name: &str) -> bool { name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "isize" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "usize" || name == "f32" || name == "f64" }

pub fn a_float_type(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => args.is_empty() && (name == "f32" || name == "f64"),
        _ => false,
    }
}

pub fn an_integer_literal(expr: &Expr) -> bool {
    match check_peeled(expr) {
        Expr::LitInt { .. } => true,
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); *op == UnaryOp::Neg && an_integer_literal(expr) },
        _ => false,
    }
}

pub fn type_last_segment(name: &str) -> String { nikaia_std::index::or(name.rsplit("::").next(), || name.into()).to_owned() }

pub fn view_of_type(inner: &Ty) -> Ty {
    match inner {
        Ty::Named { name, args, view } => { let view = *view; if view { inner.clone() } else if args.is_empty() && name == "String" { Ty::Named { name: String::from("str"), args: vec![], view: true } } else { Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true } } },
        Ty::Nullable(held) => { let held = nikaia_std::boxed::open(held); Ty::Nullable(Box::new(view_of_type(held))) },
        _ => Ty::Unknown,
    }
}

pub fn viewed_from_type(view: &Ty) -> Vec<Ty> {
    match view {
        Ty::Named { name, args, view } => { let view = *view; if !view { vec![] } else if args.is_empty() && name == "str" { vec![Ty::Named { name: String::from("String"), args: vec![], view: false }] } else { vec![Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false }] } },
        _ => vec![],
    }
}

pub fn unviewed_type(ty: &Ty) -> Ty {
    match ty {
        Ty::Named { name, args, .. } => Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false },
        _ => ty.clone(),
    }
}

pub fn copies_as_a_view(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; view && args.is_empty() && (a_number_name(name) || name == "bool" || name == "char" || name == "scalar") },
        _ => false,
    }
}

pub fn value_of_a_copy(ty: &Ty) -> Ty {
    if copies_as_a_view(ty) { return unviewed_type(ty); }
    ty.clone()
}

pub fn is_a_view_of_a_string(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; view && args.is_empty() && type_last_segment(name) == "String" },
        _ => false,
    }
}

pub fn a_copy_by_value(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && (a_number_name(name) || name == "bool" || name == "char" || name == "scalar") },
        _ => false,
    }
}

pub fn moves_away(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == ARRAY { any_moves_away(args) } else { !view && !a_number_name(name) && name != "bool" && name != "char" && name != "scalar" && name != "Shared" && name != "SharedMut" } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); moves_away(inner) },
        Ty::Tuple(parts) => any_moves_away(parts),
        _ => false,
    }
}

fn any_moves_away(types: &[Ty]) -> bool {
    for ty in types.iter() { if moves_away(ty) { return true; } }
    false
}

pub fn copies_plainly(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == ARRAY { all_copy(args) } else { view || name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64" || name == "f32" || name == "f64" || name == "bool" || name == "char" || name == "scalar" } },
        _ => false,
    }
}

fn all_copy(types: &[Ty]) -> bool {
    for ty in types.iter() { if !copies_plainly(ty) { return false; } }
    true
}

pub fn holds_an_array(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => name == ARRAY || any_holds_an_array(args),
        Ty::Tuple(parts) => any_holds_an_array(parts),
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); holds_an_array(inner) },
        _ => false,
    }
}

fn any_holds_an_array(types: &[Ty]) -> bool {
    for ty in types.iter() { if holds_an_array(ty) { return true; } }
    false
}

pub fn is_a_list_type(ty: &Ty) -> bool {
    match ty.unseen() {
        Ty::Named { ref name, .. } => name == "Vec" || name == "List" || name == "Array",
        _ => false,
    }
}

pub fn is_a_collection_type(ty: &Ty) -> bool {
    if is_a_list_type(ty) { return true; }
    match ty.unseen() {
        Ty::Named { ref name, .. } => {
            let last = type_last_segment(name);
            last == "HashMap" || last == "HashSet" || last == "BTreeMap" || last == "BTreeSet" || last == "TrustedMap" || last == "TrustedSet"
        },
        _ => false,
    }
}

pub fn is_text_type(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => args.is_empty() && (name == "String" || name == "str"),
        _ => false,
    }
}

pub fn is_a_hull(name: &str) -> bool { name == "Shared" || name == "SharedMut" || name == "Locked" }

pub fn locked_content_of(ty: &Ty) -> Option<Ty> {
    match ty {
        Ty::Named { name, args, .. } => if (name == "SharedMut" || name == "Locked") && !args.is_empty() { Some((*nikaia_std::index::get(&args, 0)).clone()) } else { None },
        _ => None,
    }
}

pub fn is_a_handle(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && (name == "Shared" || name == "SharedMut") },
        _ => false,
    }
}

pub fn locked_content(ty: &Ty) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == "Locked" && !view && args.len() == 1 { (*nikaia_std::index::get(&args, 0)).clone() } else { ty.clone() } },
        _ => ty.clone(),
    }
}

pub fn becomes_shared(found: &Ty, want: &Ty) -> bool {
    match want {
        Ty::Named { name, args, view } => {
            let view = *view;
            if !is_a_hull(name) || view || args.len() != 1 || found.is_unknown() { false } else { found.fits(nikaia_std::index::get(&args, 0)) || found.fits(&locked_content(nikaia_std::index::get(&args, 0))) }
        },
        _ => false,
    }
}

pub fn way_out_of_a_mismatch(found: &Ty, want: &Ty) -> String {
    if becomes_shared(found, want) {
        let hull = match want {
            Ty::Named { name, .. } => name.to_owned(),
            _ => String::from(""),
        };
        return format!("Wrap it: `{}(…)`.", hull);
    }
    let element = part_of_a_list(found, want);
    if element.is_some() {
        let written = nikaia_std::index::or(element, || "?".into());
        return format!("This is part of a list. Declare the parameter `ref Array[{}]` to take a part or a whole list alike.", written);
    }
    let found_text = found.text();
    let want_text = want.text();
    if found_text == "ref String" && want_text == "String" { return String::from("Write `.clone()` to turn this view into text of its own."); }
    if found_text == "String" && want_text == "ref String" { return String::from("Write `ref` in front of it to pass a view of it."); }
    if a_number_name(&found_text) && a_number_name(&want_text) { return format!("Convert it with `as {}`. A number goes into another type on its own only where every value it can hold fits.", want_text); }
    let article = if want_text.starts_with('i') || want_text.starts_with('a') || want_text.starts_with('e') || want_text.starts_with('o') || want_text.starts_with('I') || want_text.starts_with('A') || want_text.starts_with('E') || want_text.starts_with('O') { "an" } else { "a" };
    format!("Make it {} `{}`, or change the declaration to `{}`.", article, want_text, found_text)
}

fn part_of_a_list(found: &Ty, want: &Ty) -> Option<String> {
    let run = match found {
        Ty::Named { name, args, view } => { let view = *view; view && name == ARRAY && args.len() == 1 },
        _ => false,
    };
    if !run { return None; }
    let (name, args) = match want {
        Ty::Named { name, args, .. } => (name, args),
        _ => return None,
    };
    if type_last_segment(name) != "Vec" { return None; }
    if args.is_empty() { return Some(String::from("?")); }
    Some((*nikaia_std::index::get(&args, 0)).text())
}

pub fn element_walked(over: &Ty, bindings: i64) -> Ty {
    if bindings != 1 { return Ty::Unknown; }
    match over {
        Ty::Named { name, args, view } => {
            let view = *view;
            let last = type_last_segment(name);
            if args.len() == 1 { if last == "Vec" || last == "List" || last == "BTreeSet" || last == "HashSet" { (*nikaia_std::index::get(&args, 0)).clone() } else { Ty::Unknown } } else if !args.is_empty() && !view && name == ARRAY { (*nikaia_std::index::get(&args, 0)).clone() } else if args.is_empty() && last == "Bytes" { Ty::Named { name: String::from("u8"), args: vec![], view: false } } else { Ty::Unknown }
        },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; if slice && !mutable { item.clone() } else { Ty::Unknown } },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); item.clone() },
        _ => Ty::Unknown,
    }
}

pub fn elements_walked(over: &Ty, bindings: i64) -> Vec<Ty> {
    if bindings == 1 { return vec![element_walked(over, 1)]; }
    let parts = parts_walked(over, bindings);
    if (parts.len() as i64) == bindings { return parts; }
    let mut unknown: Vec<Ty> = vec![];
    for _ in 0..bindings { unknown.push(Ty::Unknown); }
    unknown
}

fn parts_walked(over: &Ty, bindings: i64) -> Vec<Ty> {
    match over {
        Ty::Named { name, args, .. } => {
            let last = type_last_segment(name);
            if (last == "HashMap" || last == "Map" || last == "BTreeMap" || last == "TrustedMap") && args.len() == 2 && bindings == 2 { vec![(*nikaia_std::index::get(&args, 0)).clone(), (*nikaia_std::index::get(&args, 1)).clone()] } else if (last == "Vec" || last == "List" || last == "BTreeSet" || last == "HashSet") && args.len() == 1 || name == ARRAY && !args.is_empty() { tuple_parts(nikaia_std::index::get(&args, 0)) } else { vec![] }
        },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); tuple_parts(item) },
        _ => vec![],
    }
}

fn tuple_parts(ty: &Ty) -> Vec<Ty> {
    match ty {
        Ty::Tuple(parts) => parts.to_owned(),
        _ => vec![],
    }
}

pub fn wholly_known(ty: &Ty) -> bool {
    match ty {
        Ty::Unknown => false,
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); wholly_known(inner) },
        Ty::Tuple(parts) => parts.iter().all(|part| { wholly_known(part) }),
        Ty::Named { args, .. } => args.iter().all(|arg| { wholly_known(arg) }),
        _ => true,
    }
}

pub fn a_map_type(name: &str) -> bool {
    let last = type_last_segment(name);
    last == "HashMap" || last == "BTreeMap" || last == "Map"
}

pub fn is_a_literal_other_than(expr: &Expr, kind: &str) -> bool {
    match expr {
        Expr::LitBool(_, _) => kind != "bool",
        Expr::LitStr { .. } => kind != "text",
        Expr::LitInterpolated { .. } => kind != "text",
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::LitChar(_, _) => true,
        Expr::LitNull(_) => true,
        _ => false,
    }
}

pub fn a_copied_part(ty: &Ty, copies: &collections::BTreeSet<String>) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if name == "Array" { args.iter().all(|arg| { a_count(arg) || a_copied_part(arg, copies) }) } else { !view && args.is_empty() && (a_copied_scalar(name) || copies.contains(name)) } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); a_copied_part(inner, copies) },
        Ty::Tuple(parts) => parts.iter().all(|part| { a_copied_part(part, copies) }),
        _ => false,
    }
}

fn a_copied_scalar(name: &str) -> bool { matches!(name, "i32" | "i64" | "u8" | "u32" | "u64" | "f32" | "f64" | "bool" | "char" | "scalar") }

pub fn tail_value_of(block: &Block) -> Option<&Expr> {
    if block.stmts.is_empty() { return None; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(value) => Some(value),
        _ => None,
    }
}

pub fn check_peeled(value: &Expr) -> &Expr {
    match value {
        Expr::Block(block, _) => {
            let tail = match tail_value_of(block) { Some(__nikaia_value) => __nikaia_value, None => return value };
            check_peeled(tail)
        },
        _ => value,
    }
}


