pub fn blocks_of_expr(expr: &Expr) -> Vec<&Block> {
    let mut out: Vec<&Block> = vec![];
    match expr {
        Expr::Block(block, _) => {
            out.push(block);
            return out;
        },
        Expr::Unsafe(block, _) => {
            out.push(block);
            return out;
        },
        Expr::Overlap(block, _) => {
            out.push(block);
            return out;
        },
        Expr::Closure { body, .. } => {
            out.push(body);
            return out;
        },
        Expr::Spawn { .. } => { return out; },
        Expr::If { then_branch, else_branch, .. } => {
            out.push(then_branch);
            if else_branch.is_some() { out.push(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out }); }
        },
        Expr::TryCatch { handler, .. } => { out.push(handler); },
        Expr::Select(arms, _) => { for arm in arms.iter() { out.push(select_body(arm)); } },
        _ => { },
    }
    for child in child_exprs_of(expr) { for block in blocks_of_expr(child) { out.push(block); } }
    out
}

fn setting_value(setting: &ConfigArg) -> &Expr { &setting.value }

fn select_value(arm: &SelectArm) -> &Expr { &arm.value }

fn select_body(arm: &SelectArm) -> &Block { &arm.body }

fn match_body(arm: &MatchArm) -> &Expr { &arm.body }

pub fn blocks_of_stmt(stmt: &Stmt) -> Vec<&Block> {
    let mut out: Vec<&Block> = vec![];
    match stmt {
        Stmt::For { body, .. } => { out.push(body); },
        Stmt::While { body, .. } => { out.push(body); },
        Stmt::Let { value, .. } => { return blocks_of_expr(value); },
        Stmt::Comptime { value, .. } => { return blocks_of_expr(value); },
        Stmt::Expr(value) => { return blocks_of_expr(value); },
        Stmt::Assign { target, value, .. } => {
            for block in blocks_of_expr(target) { out.push(block); }
            for block in blocks_of_expr(value) { out.push(block); }
        },
        Stmt::Return(value) => { if value.is_some() { return blocks_of_expr(match value { Some(__nikaia_value) => __nikaia_value, None => return out }); } },
        Stmt::Break => { },
        Stmt::Continue => { },
    }
    out
}


// --- check_walks.nika ---

pub fn check_not_pure_because(contract: &FnContract) -> Option<String> {
    if !contract.sync_claim.is_sync() { return Some("can pause".to_owned()); }
    if !contract.fails_with.is_empty() { return Some("can fail".to_owned()); }
    if contract.mutates { return Some("changes what it is called on".to_owned()); }
    if !contract.touches_known || !contract.touches.is_empty() { return Some("touches something outside the program's values".to_owned()); }
    if contract.touches_a_lock.holds() { return Some("takes a lock".to_owned()); }
    None
}

fn check_walks_clash(earlier: &Accounted, later: &Accounted) -> Option<Verdict> {
    match earlier {
        Accounted::Operation(first) => match later {
            Accounted::Operation(second) => {
                let verdict = verdict(first, second);
                if verdict.is_overlap() { return None; }
                Some(verdict)
            },
            _ => None,
        },
        _ => None,
    }
}

impl CheckState {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn branches_meet_on_nothing(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, block: &Block) {
        for stmt in block.stmts.iter() {
            match &stmt.node {
                Stmt::Let { names, .. } => {
                    let mut bound: Vec<String> = vec![];
                    for name in names.iter() {
                        let name = *name;
                        bound.push(world.words.resolve(name).to_owned());
                    }
                    let name = bound.join("`, `");
                    self.findings.push(CheckFinding { severity: CheckSeverity::Error, span: stmt.span.clone(), code: "NK2104".to_owned(), message: format!("A branch of an `overlap` can't declare `{}`.", name), notes: vec!["Each statement in the block runs as its own branch, and the block's value is their results in the order they're written.".to_owned()], help: Some(format!("Take the value from the block instead: `let ({}, …) = overlap {{ … }}`.", name)), labels: vec![] });
                },
                _ => { },
            }
        }
        let mut operations: Vec<Accounted> = vec![];
        for stmt in block.stmts.iter() { operations.push(accounted(&stmt.node, world.words, &Walking { own: world.own, library: world.library, into: Going::Ours })); }
        for i in 0..operations.len() as i64 {
            for j in i + 1..operations.len() as i64 {
                let clash = check_walks_clash(nikaia_std::index::get(&operations, (i) as usize), nikaia_std::index::get(&operations, nikaia_std::index::at(j)));
                if clash.is_some() {
                    let verdict = nikaia_std::index::or(clash, || Verdict::NotAccountedFor);
                    let why = capitalised(&verdict.why());
                    self.findings.push(CheckFinding { severity: CheckSeverity::Error, span: nikaia_std::index::get(&block.stmts, nikaia_std::index::at(j)).span.clone(), code: "NK2104".to_owned(), message: "These two branches can't run at the same time.".to_owned(), notes: vec![format!("{}.", why), "`overlap` runs its branches at once, so they can't depend on each other.".to_owned()], help: Some("If they should run in order, write them as ordinary statements.".to_owned()), labels: vec![] });
                    break;
                }
            }
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn a_guard_reading_inside_a_box<H: CheckHost>(&mut self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, pattern: &MatchPattern, body: &Expr, guard: &Expr) {
        let mut inside: Vec<String> = vec![];
        self.names_inside_boxes(world, pattern, &mut inside);
        if inside.is_empty() { return; }
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        for each in check_visit_preorder(guard) { check_walks_reads(world, host, each, &inside, &mut read); }
        if read.is_empty() { return; }
        let mut typed: collections::BTreeMap<String, Ty> = collections::BTreeMap::new();
        self.typed_inside_boxes(world, pattern, &mut typed);
        let mut copied: collections::BTreeSet<String> = collections::BTreeSet::new();
        for name in read.iter() {
            let ty = match match *nikaia_std::index::get(&typed, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => continue };
            if (a_copy_by_value(&ty) || ty.is_a_view()) && !check_core_flow_a_slice(&ty) { copied.insert(name.to_owned()); }
        }
        self.facts.guards_inside_boxes.insert(id_of(body) as i64, copied);
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn a_claim_reaches<H: CheckHost>(&self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, condition: &Expr, not_pure: &mut Vec<String>) {
        let mut found: Vec<String> = vec![];
        for each in check_visit_preorder(condition) { self.a_claim_looks_at(world, host, each, &mut found); }
        not_pure.extend(found);
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn a_claim_looks_at<H: CheckHost>(&self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, found: &mut Vec<String>) {
        self.a_claim_reads(world, expr, found);
        if check_visit_has_holes(expr) { for hole in host.literal_holes(expr) { for inner in check_visit_preorder(&hole) { self.a_claim_looks_at(world, host, inner, found); } } }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn a_claim_reads(&self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, expr: &Expr, found: &mut Vec<String>) {
        let form = check_walks_form(expr);
        if !form.is_empty() { found.push(format!("the condition {}", form)); }
        match expr {
            Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); self.a_claim_names(world, func, found); },
            _ => { },
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn a_claim_names(&self, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, func: &Expr, found: &mut Vec<String>) {
        let mut name: String = "".to_owned();
        match func {
            Expr::Variable(symbol, _) => {
                let symbol = *symbol;
                name = world.words.resolve(symbol).to_owned();
            },
            Expr::Path(segments, _) => {
                let mut parts: Vec<String> = vec![];
                for segment in segments.iter() {
                    let segment = *segment;
                    parts.push(world.words.resolve(segment).to_owned());
                }
                let joined = parts.join("::");
                name = world.here.unaliased(&joined);
            },
            _ => {
                found.push("The condition calls something that isn't a plain name.".to_owned());
                return;
            },
        }
        let mut constructs = self.variant_parts.contains_key(&name) || self.declares_a_type(world, &name) || is_hull(&name);
        if !constructs {
            let at = nikaia_std::search::find(&name, &"::", 0);
            if at.is_some() {
                let cut = nikaia_std::index::or(at, || 0);
                let ty = nikaia_std::index::get(&name, nikaia_std::index::at(0..cut)).to_owned();
                let variant = nikaia_std::index::get(&name, nikaia_std::index::at(cut + "::".len() as i64..)).to_owned();
                constructs = self.is_variant(&ty, &variant);
            }
        }
        if constructs { return; }
        let resolved = resolve_call(world, &name);
        if resolved.is_none() {
            found.push(format!("The compiler knows nothing about `{}`, so it might change something.", name));
            return;
        }
        let call = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
        let why = check_not_pure_because(call.contract);
        if why.is_some() {
            let because = nikaia_std::index::or(why, || "".to_owned().into());
            found.push(format!("`{}` {}", name, because));
        }
    }
}

fn check_walks_form(expr: &Expr) -> &'static str {
    match expr {
        Expr::Spawn { .. } => "starts a task",
        Expr::Select(_, _) => "waits in a `select`",
        Expr::Overlap(_, _) => "runs an `overlap`",
        Expr::Dsl { .. } => "runs a `dsl` block",
        Expr::Asm { .. } => "runs `unsafe` code",
        Expr::Unsafe(_, _) => "runs `unsafe` code",
        Expr::Try(_, _) => "can fail",
        Expr::Throw(_, _) => "can fail",
        Expr::TryCatch { .. } => "can fail",
        Expr::Return(_, _) => "jumps",
        Expr::Break(_) => "jumps",
        Expr::Continue(_) => "jumps",
        Expr::Block(_, _) => "contains a block, which might change something",
        Expr::If { .. } => "contains a block, which might change something",
        Expr::Match { .. } => "contains a block, which might change something",
        Expr::Closure { .. } => "contains a block, which might change something",
        _ => "",
    }
}

fn check_walks_reads<H: CheckHost>(world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, inside: &[String], read: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Variable(symbol, _) => {
            let symbol = *symbol;
            let name = world.words.resolve(symbol).to_owned();
            for bound in inside.iter() { if *bound == name { read.insert(name.to_owned()); } }
        },
        _ => { },
    }
    if check_visit_has_holes(expr) { for hole in host.literal_holes(expr) { for inner in check_visit_preorder(&hole) { check_walks_reads(world, host, inner, inside, read); } } }
}


// --- check_widen.nika ---

fn integer_rank(name: &str) -> i64 {
    if name == "u8" { return 0; }
    if name == "u32" { return 1; }
    if name == "u64" { return 2; }
    if name == "i32" { return 3; }
    if name == "i64" { return 4; }
    -1
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn common_integer(a: &str, b: &str) -> Option<String> {
    let x = integer_rank(a);
    let y = integer_rank(b);
    if x < 0 || y < 0 { return None; }
    let mut low = x;
    let mut high = y;
    if y < x {
        low = y;
        high = x;
    }
    let names = vec!["u8", "u32", "u64", "i32", "i64"];
    if low == 0 { return Some((*nikaia_std::index::get(&names, nikaia_std::index::at(high))).to_owned()); }
    if low == 1 {
        if high <= 2 { return Some((*nikaia_std::index::get(&names, nikaia_std::index::at(high))).to_owned()); }
        return Some("i64".to_owned());
    }
    if low == 2 {
        if high == 2 { return Some("u64".to_owned()); }
        return None;
    }
    if high == 3 { return Some("i32".to_owned()); }
    Some("i64".to_owned())
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn an_integer_named(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; if !view && args.is_empty() && integer_rank(name) >= 0 { Some(name.to_owned()) } else { None } },
        _ => None,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn a_plain_name(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, .. } => if args.is_empty() { Some(name.to_owned()) } else { None },
        _ => None,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn widened_into(found: &Ty, want: &Ty) -> Option<String> {
    let from = nikaia_std::index::or(an_integer_named(found), || "".into());
    let into = nikaia_std::index::or(an_integer_named(want), || "".into());
    if from.is_empty() || into.is_empty() || from == into { return None; }
    let common = nikaia_std::index::or(common_integer(&from, &into), || "".into());
    if common == into { return Some(into.to_owned()); }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn an_integer_that_does_not_widen(found: &Ty, want: &Ty) -> bool {
    let from = nikaia_std::index::or(an_integer_named(found), || "".into());
    let into = nikaia_std::index::or(an_integer_named(want), || "".into());
    if from.is_empty() || into.is_empty() || from == into { return false; }
    widened_into(found, want).is_none()
}

