    #[allow(clippy::too_many_arguments)]
    pub fn emit_core_safe_method<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<(), Box<dyn std::error::Error>> {
        let flattens = self.facts.flattened_reaches.contains(&node_key(receiver));
        let mut lent: String = String::from("");
        if self.facts.lent_reaches.contains(&node_key(receiver)) && !emit_place_already_lent(world, receiver) { lent = ".as_ref()".to_owned(); }
        out.push("match ");
        let name = nikaia_std::index::or(walk.held.get(&node_key(receiver)), || "").to_owned();
        if walk.held.contains_key(&node_key(receiver)) { out.push(&name); } else if lent == "" && emit_place_an_index(receiver) { host.expr(walk, out, receiver, depth, flow, scope)?; } else { self.emit_core_postfix_base(world, walk, out, host, receiver, depth, flow, scope)?; }
        out.push(&lent);
        let inner = "    ".repeat(nikaia_std::count::of(depth + 1));
        let outer = "    ".repeat(nikaia_std::count::of(depth));
        out.push(&format!(" {{\n{}", inner));
        out.push("Some(__nikaia_it) => ");
        if !flattens { out.push("Some("); }
        let copy = self.facts.owned_copies.contains(&node_key(receiver));
        let held_copy = walk.reached_copy;
        walk.reached_copy = copy;
        let text_copy = copy && self.facts.text_copies.contains(&node_key(receiver)) && args.is_empty() && world.words.resolve(method) == "clone";
        let mut done = false;
        if text_copy {
            out.push("__nikaia_it.to_string()");
            done = true;
        } else { done = self.emit_core_a_field_call(world, walk, out, host, receiver, true, method, args, depth + 1, flow, scope)?; }
        if !done { self.emit_core_method_call(world, walk, out, host, None, node_key(receiver), method, args, config, depth + 1, flow, scope)?; }
        walk.reached_copy = held_copy;
        if !flattens { out.push(")"); }
        out.push(&format!(",\n{}None => None,\n{}}}", inner, outer));
        Ok(())
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
