    #[allow(clippy::too_many_arguments)]
    pub fn emit_core_against_a_length<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, op: BinaryOp, lhs: &Expr, rhs: &Expr, depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<bool, Box<dyn std::error::Error>> {
        let mut counter_first = true;
        if emit_read_a_length(world, rhs) && !emit_read_a_length(world, lhs) && walk.never_negative(world, &scope.function, lhs) { counter_first = true; } else if emit_read_a_length(world, lhs) && !emit_read_a_length(world, rhs) && walk.never_negative(world, &scope.function, rhs) { counter_first = false; } else { return Ok(false); }
        let counter = if counter_first { lhs } else { rhs };
        let length = if counter_first { rhs } else { lhs };
        let mut written = EmitOut::empty();
        self.emit_core_nested(world, walk, &mut written, host, length, 255, depth, flow, scope)?;
        let mut bare: String = String::from("");
        let mut stripped = false;
        if written.buf.ends_with(" as i64") {
            bare = nikaia_std::index::or(written.buf.strip_suffix(" as i64"), || "").to_owned();
            stripped = true;
        } else if written.buf.starts_with('(') && written.buf.ends_with(" as i64)") {
            let inner = nikaia_std::index::or(written.buf.strip_prefix('('), || "").to_owned();
            bare = nikaia_std::index::or(inner.strip_suffix(" as i64)"), || "").to_owned();
            stripped = true;
        }
        if !stripped { return Ok(false); }
        match counter {
            Expr::LitInt { value, negative, .. } => {
                let negative = *negative; let value = *value;
                if !negative && bare.ends_with(".len()") {
                    let receiver = nikaia_std::index::or(bare.strip_suffix(".len()"), || "").to_owned();
                    let empty = emit_read_emptiness(emit_read_turned(op, counter_first), value);
                    if empty.is_some() {
                        let mut not: String = String::from("!");
                        if nikaia_std::index::or(empty, || false) { not = "".to_owned(); }
                        out.push(&format!("{}{}.is_empty()", not, receiver));
                        return Ok(true);
                    }
                }
            },
            _ => { },
        }
        let mut counted: String = String::from("");
        match counter {
            Expr::LitInt { value, negative, .. } => {
                let negative = *negative; let value = *value;
                if !negative { counted = format!("{}", value); } else { counted = self.emit_read_counted(world, walk, host, counter, depth, flow, scope)?; }
            },
            _ => { counted = self.emit_read_counted(world, walk, host, counter, depth, flow, scope)?; },
        }
        let symbol = binary_op(op);
        if counter_first { out.push(&format!("{} {} {}", counted, symbol, bare)); } else { out.push(&format!("{} {} {}", bare, symbol, counted)); }
        Ok(true)
    }
