// --- emit_locals.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
struct NnState {
    declared: collections::BTreeMap<winnow_grammar::Symbol, i64>,
    candidates: collections::BTreeMap<winnow_grammar::Symbol, i64>,
    symbols: Vec<winnow_grammar::Symbol>,
    spoiled: collections::BTreeSet<winnow_grammar::Symbol>,
    seen: collections::BTreeSet<String>,
}

pub fn nonnegative_locals(body: &Block) -> Vec<winnow_grammar::Symbol> {
    let mut state = NnState { declared: collections::BTreeMap::new(), candidates: collections::BTreeMap::new(), symbols: vec![], spoiled: collections::BTreeSet::new(), seen: collections::BTreeSet::new() };
    let visited = visited_in_block(body);
    nn_every(body, &visited, &mut state);
    for expr in visited.iter() {
        let expr = *expr;
        match expr {
            Expr::Call { args, .. } => { nn_spoil_all(args, &mut state); },
            Expr::MethodCall { args, .. } => { nn_spoil_all(args, &mut state); },
            Expr::SafeMethod { args, .. } => { nn_spoil_all(args, &mut state); },
            _ => { },
        }
    }
    let mut out: Vec<winnow_grammar::Symbol> = vec![];
    for at in 0..state.symbols.len() as i64 {
        let symbol = *nikaia_std::index::get(&state.symbols, (at) as usize);
        if nn_every_declaration(&state, symbol) && !state.spoiled.contains(&symbol) { out.push(symbol); }
    }
    out
}

fn nn_every_declaration(state: &NnState, name: winnow_grammar::Symbol) -> bool {
    let declared = nikaia_std::index::or(state.declared.get(&name), || 0);
    declared > 0 && nikaia_std::index::or(state.candidates.get(&name), || 0) == declared
}

fn nn_spoil_all(args: &[Expr], state: &mut NnState) {
    for arg in args.iter() {
        match arg {
            Expr::Variable(name, _) => { let name = *name; nn_spoil(name, state); },
            _ => { },
        }
    }
}

fn nn_spoil(name: winnow_grammar::Symbol, state: &mut NnState) { state.spoiled.insert(name); }

fn nn_candidate(name: winnow_grammar::Symbol, state: &mut NnState) {
    let before = nikaia_std::index::or(state.candidates.get(&name), || 0);
    state.candidates.insert(name, before + 1);
    if before == 0 { state.symbols.push(name); }
}

fn nn_declare(name: winnow_grammar::Symbol, state: &mut NnState) {
    let before = nikaia_std::index::or(state.declared.get(&name), || 0);
    state.declared.insert(name, before + 1);
}

fn nn_literal(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { negative, .. } => { let negative = *negative; !negative },
        _ => false,
    }
}

fn nn_keeps(op: Option<&BinaryOp>, value: &Expr) -> bool {
    let held = match op { Some(__nikaia_value) => __nikaia_value, None => return nn_literal(value) };
    match held {
        BinaryOp::Add => nn_literal(value),
        BinaryOp::Mul => nn_literal(value),
        _ => false,
    }
}

fn nn_range_from_literal(iter: &Expr) -> bool {
    match iter {
        Expr::Range { start, .. } => { let start = nikaia_std::boxed::open(start); nn_literal(start) },
        _ => false,
    }
}

fn nn_note(stmt: &Stmt, state: &mut NnState) {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            for name in names.iter() {
                let name = *name;
                nn_declare(name, state);
            }
            if names.len() == 1 && ty.is_none() && nn_literal(value) { nn_candidate(*nikaia_std::index::get(&names, 0), state); }
        },
        Stmt::For { bindings, iter, .. } => {
            for name in bindings.iter() {
                let name = *name;
                nn_declare(name, state);
            }
            if bindings.len() == 1 && nn_range_from_literal(iter) { nn_candidate(*nikaia_std::index::get(&bindings, 0), state); }
        },
        Stmt::Assign { target, op, value } => {
            match target {
                Expr::Variable(name, _) => {
                    let name = *name;
                    if !nn_keeps((op).as_ref(), value) { nn_spoil(name, state); }
                },
                _ => { },
            }
        },
        _ => { },
    }
}

fn nn_kind(stmt: &Stmt) -> &'static str {
    match stmt {
        Stmt::Let { .. } => "let",
        Stmt::Comptime { .. } => "comptime",
        Stmt::Assign { .. } => "assign",
        Stmt::For { .. } => "for",
        Stmt::While { .. } => "while",
        Stmt::Return(_) => "return",
        Stmt::Break => "break",
        Stmt::Continue => "continue",
        Stmt::Expr(_) => "expr",
    }
}

fn nn_key(stmt: &Spanned<Stmt>) -> String {
    let held = match &stmt.node {
        Stmt::Expr(value) => node_key(value),
        Stmt::Return(value) => nn_held((value).as_ref()),
        Stmt::Let { value, .. } => node_key(value),
        _ => 0,
    };
    format!("{}:{}:{}:{}", stmt.span.start, stmt.span.end, nn_kind(&stmt.node), held)
}

fn nn_held(value: Option<&Expr>) -> i64 {
    let held = match value { Some(__nikaia_value) => __nikaia_value, None => return 0 };
    node_key(held)
}

fn nn_every(body: &Block, visited: &[&Expr], state: &mut NnState) {
    let mut blocks: Vec<&Block> = vec![body];
    for expr in visited.iter() {
        let expr = *expr;
        match expr {
            Expr::Block(inner, _) => { blocks.push(inner); },
            Expr::Unsafe(inner, _) => { blocks.push(inner); },
            Expr::Overlap(inner, _) => { blocks.push(inner); },
            Expr::If { then_branch, else_branch, .. } => {
                blocks.push(then_branch);
                blocks.extend(nn_maybe_block((else_branch).as_ref()));
            },
            Expr::Closure { body, .. } => { blocks.push(body); },
            _ => { },
        }
    }
    let mut at: i64 = 0;
    while ((at) as usize) < blocks.len() {
        let block = *nikaia_std::index::get(&blocks, (at) as usize);
        for stmt in block.stmts.iter() {
            match &stmt.node {
                Stmt::For { body, .. } => { blocks.push(body); },
                Stmt::While { body, .. } => { blocks.push(body); },
                _ => { },
            }
            let key = nn_key(stmt);
            if state.seen.contains(&key) { continue; }
            state.seen.insert(key);
            nn_note(&stmt.node, state);
        }
        at += 1;
    }
}

fn nn_maybe_block(block: Option<&Block>) -> Vec<&Block> {
    let held = match block { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    vec![held]
}


// --- emit_misc.nika ---

pub fn is_reserved(name: &str) -> bool { matches!(name, "abstract" | "async" | "await" | "become" | "box" | "const" | "do" | "dyn" | "extern" | "final" | "gen" | "loop" | "macro" | "mod" | "move" | "override" | "priv" | "ref" | "static" | "trait" | "try" | "type" | "typeof" | "unsafe" | "unsized" | "virtual" | "where" | "yield") }

pub fn escaped_name(name: &str) -> String {
    if is_reserved(name) { return format!("r#{}", name); }
    name.to_owned()
}

pub fn emit_local_name(comptimes: &collections::BTreeSet<String>, name: &str) -> String {
    if comptimes.contains(name) { return format!("{}__nikaia_local", name); }
    escaped_name(name)
}

pub fn opaque_type_text(name: &str, release: &str) -> String { format!("#[repr(transparent)]\n#[derive(Debug)]\n// A C type keeps the name its header gives it, which is not the\n// shape Rust's own lint expects (Part III, C.1: what `rustc` would\n// say here is about a file nobody wrote).\n#[allow(non_camel_case_types)]\npub struct {}(core::ptr::NonNull<core::ffi::c_void>);\n\n#[allow(dead_code)]\nimpl {} {{\n    /// What a declaration that says `-> {}` hands back\n    /// (ADR-302 D12): the address, or an abort naming the\n    /// declaration that claimed it would be one.\n    #[track_caller]\n    fn from_c(declaration: &str, address: *mut core::ffi::c_void) -> {} {{\n        match core::ptr::NonNull::new(address) {{\n            Some(address) => {}(address),\n            None => nikaia_std::foreign::nothing_came_back(declaration),\n        }}\n    }}\n\n    /// The same, where the declaration **does** say `?` (D1).\n    fn maybe(address: *mut core::ffi::c_void) -> Option<{}> {{\n        core::ptr::NonNull::new(address).map({})\n    }}\n\n    /// The same address, without giving the handle away\n    /// (ADR-302 D7): what a C function is handed is the\n    /// pointer, and this handle stays the caller's to close.\n    fn lent(&self) -> {} {{\n        {}(self.0)\n    }}\n}}\n\nimpl Drop for {} {{\n    fn drop(&mut self) {{\n        let _released = unsafe {{ {}(self.lent()) }};\n    }}\n}}\n\n", name, name, name, name, name, name, name, name, name, name, release) }

fn emit_lends(contract: &FnContract, at: i64, library: &Ledger, described: &Ledger) -> bool { lends_in(contract, at, &vec![library, described]) }

fn emit_field_type(contract: Option<&FieldContract>) -> Ty {
    let held = match contract { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    held.ty.clone()
}

impl EmitState {
    pub fn method_pauses(&self, on: i64) -> bool { self.facts.pausing_methods.contains(&on) }
    pub fn method_can_fail(&self, on: i64) -> bool { self.facts.fallible_methods.contains(&on) }
    pub fn emit_call_fails(&self, world: &EmitWorld<'_, '_, '_, '_>, expr: &Expr) -> bool {
        match expr {
            Expr::Call { func, .. } => {
                let func = nikaia_std::boxed::open(func);
                let kept = self.facts.kept_calls.get(&node_key(func));
                if kept.is_some() {
                    let pair = match kept { Some(__nikaia_value) => __nikaia_value, None => return false };
                    return pair.1;
                }
                return self.facts.run_code_fails.contains(&node_key(func)) || call_can_fail(world.words, &self.own_contracts, world.library, &self.described, func);
            },
            Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); return self.method_can_fail(node_key(receiver)) },
            _ => return false,
        }
    }
    pub fn emit_catch_nests_a_failure(&self, world: &EmitWorld<'_, '_, '_, '_>, guarded: &Expr) -> bool {
        let mut apart: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for each in visited_in_expr(guarded) {
            match each {
                Expr::Closure { .. } => { for inner in visited_in_expr(each) { apart.insert(node_key(inner)); } },
                Expr::TryCatch { .. } => { for inner in visited_in_expr(each) { apart.insert(node_key(inner)); } },
                _ => { },
            }
        }
        let top = node_key(guarded);
        for each in visited_in_expr(guarded) {
            let key = node_key(each);
            if key != top && !apart.contains(&key) && self.emit_call_fails(world, each) { return true; }
        }
        false
    }
    pub fn lambda_decides(&self, key: &str) -> bool {
        let contract = match self.own_contracts.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => return false };
        matches!(contract.sync_claim, Sync::From(_))
    }
    pub fn lowered_pausing(&self, key: &str) -> bool { call_pauses(&self.own_contracts, key) || self.lambda_decides(key) }
    pub fn closes_a_pausing_cycle(&self, caller: &str, callee: &str) -> bool {
        let seen = match self.pausing_reach.get(callee) { Some(__nikaia_value) => __nikaia_value, None => return false };
        seen.contains(caller)
    }
    pub fn method_closes_a_pausing_cycle(&self, caller: &str, method: &str) -> bool {
        let suffix = format!("::{}", method);
        for key in self.pausing_reach.keys() {
            if !key.ends_with(&suffix) { continue; }
            let seen = match self.pausing_reach.get(key) { Some(__nikaia_value) => __nikaia_value, None => continue };
            if seen.contains(caller) { return true; }
        }
        false
    }
    pub fn a_package_grammar_entry(&self, key: &str) -> bool {
        let contract = match self.own_contracts.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => return false };
        if contract.fails_with.len() != 1 || *nikaia_std::index::get(&contract.fails_with, 0) != "ParseError" { return false; }
        let signature = match match contract.signature.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return false };
        signature.params.len() == 1 && nikaia_std::index::get(&signature.params, 0).0 == "input"
    }
    pub fn enclosing_shape_walk(&self, on: &str) -> Option<String> {
        for key in self.facts.unrolled.keys() { if key.1 == on { return Some(key.0.to_owned()); } }
        None
    }
    pub fn unrolls_here(&self, world: &EmitWorld<'_, '_, '_, '_>, name: &str, on: &str, iter: &Expr) -> Option<Vec<FieldContract>> {
        match iter {
            Expr::Path(segments, _) => {
                if segments.len() != 2 { return None; }
                let parameter = world.words.resolve(*nikaia_std::index::get(&segments, 0));
                let member = world.words.resolve(*nikaia_std::index::get(&segments, 1));
                if parameter != name || member != "fields" && member != "variants" { return None; }
                let walk = match self.enclosing_shape_walk(on) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let found = match self.facts.unrolled.get(&(walk, on.to_owned())) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return Some(found.to_owned());
            },
            _ => { },
        }
        None
    }
    pub fn boxed_bindings(&self, world: &EmitWorld<'_, '_, '_, '_>, pattern: &MatchPattern) -> Vec<String> {
        let mut out: Vec<String> = vec![];
        match pattern {
            MatchPattern::Tuple { path, parts } => {
                let (owner, variant) = self.boxed_owner(world, path);
                for at in 0..parts.len() as i64 {
                    let boxed = !variant.is_empty() && self.is_boxed(&owner, &boxed_member(&variant, at, ""));
                    if boxed && self.binds_one_name(nikaia_std::index::get(&parts, nikaia_std::index::at(at))) { out.extend(self.single_binding(world, nikaia_std::index::get(&parts, nikaia_std::index::at(at)))); } else { out.extend(self.boxed_bindings(world, nikaia_std::index::get(&parts, nikaia_std::index::at(at)))); }
                }
            },
            MatchPattern::Named { path, fields, .. } => {
                let (owner, variant) = self.boxed_owner(world, path);
                if owner.is_empty() { return out; }
                for each in fields.iter() {
                    let field = world.words.resolve(each.name).to_owned();
                    let mut member = field.to_owned();
                    if !variant.is_empty() { member = boxed_member(&variant, -1, &field); }
                    if self.is_boxed(&owner, &member) && self.binds_one_name(&each.pat) { out.extend(self.single_binding(world, &each.pat)); } else { out.extend(self.boxed_bindings(world, &each.pat)); }
                }
            },
            MatchPattern::Or(alternatives) => { if !alternatives.is_empty() { out.extend(self.boxed_bindings(world, nikaia_std::index::get(&alternatives, 0))); } },
            _ => { },
        }
        out
    }
    fn binds_one_name(&self, pattern: &MatchPattern) -> bool {
        match pattern {
            MatchPattern::Path(one) => one.len() == 1,
            _ => false,
        }
    }
    fn single_binding(&self, world: &EmitWorld<'_, '_, '_, '_>, pattern: &MatchPattern) -> Vec<String> {
        match pattern {
            MatchPattern::Path(one) => self.binding_if_named(world, one),
            _ => vec![],
        }
    }
    fn binding_if_named(&self, world: &EmitWorld<'_, '_, '_, '_>, one: &[winnow_grammar::Symbol]) -> Vec<String> {
        let name = world.words.resolve(*nikaia_std::index::get(&one, 0)).to_owned();
        if name == "_" { return vec![]; }
        vec![escaped_name(&name)]
    }
    fn boxed_owner(&self, world: &EmitWorld<'_, '_, '_, '_>, path: &[winnow_grammar::Symbol]) -> (String, String) {
        if path.is_empty() { return (String::from(""), String::from("")); }
        let last = world.words.resolve(*nikaia_std::index::get(&path, nikaia_std::index::at(path.len() as i64 - 1))).to_owned();
        if path.len() >= 2 {
            let owner = world.words.resolve(*nikaia_std::index::get(&path, nikaia_std::index::at(path.len() as i64 - 2))).to_owned();
            if self.facts.boxed_members.contains_key(&owner) { return (owner, last); }
        }
        (last, String::from(""))
    }
    pub fn narrows(&self, operand: &Expr) -> Option<FactNarrowing> {
        let found = match self.facts.narrowing_casts.get(&node_key(operand)) { Some(__nikaia_value) => __nikaia_value, None => return None };
        Some(found.clone())
    }
    pub fn a_code_parameter_taken_whole(&self, world: &EmitWorld<'_, '_, '_, '_>, function: &str, name: &str) -> bool {
        let contract = match self.own_contracts.functions.get(function) { Some(__nikaia_value) => __nikaia_value, None => return false };
        let signature = match match contract.signature.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return false };
        for at in 0..signature.params.len() as i64 {
            let param = (*nikaia_std::index::get(&signature.params, nikaia_std::index::at(at))).clone();
            if param.0 != name { continue; }
            let is_code = matches!(param.1, Ty::Fn { .. });
            if !is_code || nikaia_std::list::contains(&contract.keeps, &name) { continue; }
            if !emit_lends(&contract, at, world.library, &self.described) { return true; }
        }
        false
    }
    pub fn attribute_in_rust(&self, world: &EmitWorld<'_, '_, '_, '_>, written: &str) -> String {
        let pieces: Vec<&str> = written.split(" { ").collect::<Vec<_>>();
        let name = (*nikaia_std::index::get(&pieces, 0)).to_owned();
        let mut inside: String = String::from("");
        if pieces.len() > 1 {
            let mut rest: Vec<String> = vec![];
            for at in 1..pieces.len() as i64 { rest.push((*nikaia_std::index::get(&pieces, (at) as usize)).to_owned()); }
            let joined = rest.join(" { ");
            let stripped = joined.strip_suffix(" }");
            if stripped.is_some() { inside = nikaia_std::index::or(stripped, || "").to_owned(); } else { inside = joined.to_owned(); }
        }
        let mut fields: Vec<String> = vec![];
        for part in top_level_parts(&inside) {
            let halves: Vec<&str> = part.split(": ").collect::<Vec<_>>();
            if halves.len() < 2 { continue; }
            let field = (*nikaia_std::index::get(&halves, 0)).to_owned();
            let mut value_parts: Vec<String> = vec![];
            for at in 1..halves.len() as i64 { value_parts.push((*nikaia_std::index::get(&halves, (at) as usize)).to_owned()); }
            let value = value_parts.join(": ");
            let ty = emit_field_type((self.field_contract(world, &name, &field)).as_ref());
            fields.push(format!("{}: {}", escaped_name(&field), held_literal(&value, &ty)));
        }
        format!("{} {{ {} }}", name, fields.join(", "))
    }
}


// --- emit_ops.nika ---

pub fn precedence(op: BinaryOp) -> i64 {
    match op {
        BinaryOp::Mul | BinaryOp::Div | BinaryOp::Rem => 14,
        BinaryOp::Add | BinaryOp::Sub => 13,
        BinaryOp::Shl | BinaryOp::Shr => 12,
        BinaryOp::BitAnd => 11,
        BinaryOp::BitXor => 10,
        BinaryOp::BitOr => 9,
        BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => 7,
        BinaryOp::And => 4,
        BinaryOp::Or => 3,
    }
}

pub fn binary_op(op: BinaryOp) -> String {
    match op {
        BinaryOp::Add => String::from("+"),
        BinaryOp::Sub => String::from("-"),
        BinaryOp::Mul => String::from("*"),
        BinaryOp::Div => String::from("/"),
        BinaryOp::Rem => String::from("%"),
        BinaryOp::Eq => String::from("=="),
        BinaryOp::Ne => String::from("!="),
        BinaryOp::Lt => String::from("<"),
        BinaryOp::Le => String::from("<="),
        BinaryOp::Gt => String::from(">"),
        BinaryOp::Ge => String::from(">="),
        BinaryOp::And => String::from("&&"),
        BinaryOp::Or => String::from("||"),
        BinaryOp::BitAnd => String::from("&"),
        BinaryOp::BitOr => String::from("|"),
        BinaryOp::BitXor => String::from("^"),
        BinaryOp::Shl => String::from("<<"),
        BinaryOp::Shr => String::from(">>"),
    }
}

pub fn unary_op(op: UnaryOp) -> String {
    match op {
        UnaryOp::Neg => String::from("-"),
        UnaryOp::Not => String::from("!"),
        UnaryOp::Ref => String::from("&"),
    }
}

pub fn repeat_suffix(rep: Repeat) -> String {
    match rep {
        Repeat::Star => String::from("*"),
        Repeat::Plus => String::from("+"),
        Repeat::Optional => String::from("?"),
        Repeat::Exactly(n) => format!("{{{}}}", n),
        Repeat::AtLeast(n) => format!("{{{},}}", n),
        Repeat::Between(n, m) => format!("{{{},{}}}", n, m),
    }
}

pub fn pointing(mutable: bool) -> String {
    if mutable { return String::from("mut"); }
    String::from("const")
}

pub fn jumps(expr: &Expr) -> bool { matches!(expr, Expr::Throw(_, _) | Expr::Return(_, _) | Expr::Break(_) | Expr::Continue(_)) }

pub fn jumps_at_the_end(expr: &Expr) -> bool {
    match expr {
        Expr::Coalesce { fallback, .. } => { let fallback = nikaia_std::boxed::open(fallback); jumps_at_the_end(fallback) },
        Expr::Block(block, _) => block_jumps_at_the_end(block),
        _ => jumps(expr),
    }
}

fn block_jumps_at_the_end(block: &Block) -> bool {
    if block.stmts.is_empty() { return false; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Return(_) => true,
        Stmt::Break => true,
        Stmt::Continue => true,
        Stmt::Expr(inner) => jumps_at_the_end(inner),
        _ => false,
    }
}

pub fn never_a_value(expr: &Expr) -> bool {
    match expr {
        Expr::Match { arms, .. } => {
            let mut all = !arms.is_empty();
            for arm in arms.iter() { if !never_a_value(&arm.body) { all = false; } }
            all
        },
        Expr::If { then_branch, else_branch, .. } => if else_branch.is_none() { false } else { block_never_a_value(then_branch) && block_never_a_value(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false }) },
        Expr::Block(block, _) => block_never_a_value(block),
        _ => jumps_at_the_end(expr),
    }
}

fn block_never_a_value(block: &Block) -> bool {
    if block.stmts.is_empty() { return false; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Return(_) => true,
        Stmt::Break => true,
        Stmt::Continue => true,
        Stmt::Expr(inner) => never_a_value(inner),
        _ => false,
    }
}

pub fn a_number(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); a_negated_number(*op, expr) },
        _ => false,
    }
}

fn a_negated_number(op: UnaryOp, inner: &Expr) -> bool {
    match op {
        UnaryOp::Neg => a_number(inner),
        _ => false,
    }
}

pub fn only_literals(index: &Expr) -> bool {
    match index {
        Expr::LitInt { .. } => true,
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); only_literals(expr) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); only_literals(lhs) && only_literals(rhs) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); only_literals(start) && only_literals(end) },
        _ => false,
    }
}

pub fn a_negation_inside(index: &Expr) -> bool {
    match index {
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); a_negation_or_inside(*op, expr) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); a_negation_inside(lhs) || a_negation_inside(rhs) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); a_negation_inside(start) || a_negation_inside(end) },
        _ => false,
    }
}

fn a_negation_or_inside(op: UnaryOp, inner: &Expr) -> bool {
    match op {
        UnaryOp::Neg => true,
        _ => a_negation_inside(inner),
    }
}

pub fn is_length(method: &str, args: &[Expr]) -> bool { method == "len" && args.is_empty() }

pub fn is_count(callee: &str, at: i64) -> bool { callee == "repeat" && at == 0 }

pub fn a_list_read_as_a_slice(written: String) -> String {
    if written.starts_with("&Vec<") && written.ends_with('>') {
        let rest = nikaia_std::index::or(written.strip_prefix("&Vec<"), || "");
        let element = nikaia_std::index::or(rest.strip_suffix('>'), || "");
        return format!("&[{}]", element);
    }
    written
}

pub fn frame_attribute(frame: &FrameAttr) -> String {
    let mut keys: Vec<String> = vec![];
    let boundary = match frame.boundary.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if boundary.is_some() { keys.push(format!("boundary = \"{}\"", nikaia_std::index::or(boundary.as_deref(), || ""))); }
    if frame.unchecked { keys.push(String::from("unchecked")); }
    if keys.is_empty() { return String::from("#[frame]"); }
    format!("#[frame({})]", keys.join(", "))
}

pub fn is_a_place(expr: &Expr) -> bool { matches!(expr, Expr::Variable(_, _) | Expr::Field { .. } | Expr::SafeField { .. } | Expr::Index { .. }) }

pub fn binds_a_part(part: &MatchPattern) -> bool {
    match part {
        MatchPattern::Path(one) => one.len() == 1,
        MatchPattern::Otherwise => true,
        MatchPattern::Rest => true,
        _ => false,
    }
}


// --- emit_out.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EmitMapEntry {
    pub start: i64,
    pub end: i64,
    pub source: Span,
    pub unit: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmitOut {
    pub buf: String,
    pub entries: Vec<EmitMapEntry>,
}

impl EmitOut {
    pub fn empty() -> EmitOut { EmitOut { buf: String::from(""), entries: vec![] } }
    pub fn push(&mut self, text: &str) { self.buf.push_str(text); }
    pub fn mark(&self) -> i64 { self.buf.len() as i64 }
    pub fn record(&mut self, span: &Span, start: i64) {
        let end = self.buf.len() as i64;
        self.entries.push(EmitMapEntry { start, end, source: Span { start: span.start, end: span.end }, unit: 0 });
    }
    pub fn shift_entries(&mut self, at: i64, by: i64) {
        for k in 0..self.entries.len() as i64 {
            if nikaia_std::index::get(&self.entries, (k) as usize).start >= at { self.entries[nikaia_std::index::at(k)].start += by; }
            if nikaia_std::index::get(&self.entries, (k) as usize).end >= at { self.entries[nikaia_std::index::at(k)].end += by; }
        }
    }
    pub fn append(&mut self, other: EmitOut) {
        let offset = self.buf.len() as i64;
        self.buf.push_str(&other.buf);
        for entry in other.entries.iter() {
            let entry = *entry;
            self.entries.push(EmitMapEntry { start: entry.start + offset, end: entry.end + offset, source: entry.source, unit: entry.unit });
        }
    }
}


// --- emit_reach.nika ---

pub fn pausing_reach(words: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, items: &[Spanned<Item>], contracts: &Ledger) -> collections::BTreeMap<String, collections::BTreeSet<String>> {
    let mut pausing: collections::BTreeSet<String> = collections::BTreeSet::new();
    for key in contracts.functions.keys() {
        let contract = match contracts.functions.get(key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !contract.sync_claim.is_sync() { pausing.insert(key.to_owned()); }
    }
    let empty: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    if pausing.is_empty() { return empty; }
    let mut by_last: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for key in pausing.iter() {
        let last = reach_last_segment(key);
        let mut keys = reach_keys_for(&by_last, &last);
        keys.push(key.to_owned());
        by_last.insert(last, keys);
    }
    let mut graph: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for item in items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let held = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                graph.insert(words.resolve(held).to_owned(), reach_edges_of(words, aliases, &pausing, &by_last, body));
            },
            Item::Impl { target, methods, .. } => {
                let owner = words.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, .. } => {
                            let name = *name;
                            let own = reach_method_name(words, name);
                            graph.insert(format!("{}::{}", owner, own), reach_edges_of(words, aliases, &pausing, &by_last, body));
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    let mut reaches = graph.to_owned();
    loop {
        let mut changed = false;
        for key in graph.keys() {
            let mut entry: collections::BTreeSet<String> = reach_set_for(&reaches, key);
            let before = entry.len() as i64;
            for next in entry.to_owned() {
                let more = match reaches.get(&next) { Some(__nikaia_value) => __nikaia_value, None => continue };
                for reached in more.iter() { entry.insert(reached.to_owned()); }
            }
            if (entry.len() as i64) != before { changed = true; }
            reaches.insert(key.to_owned(), entry);
        }
        if !changed { break; }
    }
    let mut kept: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for key in reaches.keys() {
        if !pausing.contains(key) { continue; }
        let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
        for reached in reach_set_for(&reaches, key) { if pausing.contains(&reached) { seen.insert(reached); } }
        kept.insert(key.to_owned(), seen);
    }
    kept
}

fn reach_method_name(words: &winnow_grammar::InternerContext, name: Option<winnow_grammar::Symbol>) -> String {
    let held = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("new") };
    words.resolve(held).to_owned()
}

fn reach_last_segment(key: &str) -> String {
    let mut last: String = key.to_owned();
    for part in key.split("::") { last = part.to_owned(); }
    last
}

fn reach_edges_of(words: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, pausing: &collections::BTreeSet<String>, by_last: &collections::BTreeMap<String, Vec<String>>, body: &Block) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for expr in visited_in_block(body) {
        match expr {
            Expr::Call { func, .. } => {
                let func = nikaia_std::boxed::open(func);
                match func {
                    Expr::Variable(name, _) => { let name = *name; reach_note(aliases, pausing, by_last, &words.resolve(name).to_owned(), &mut out); },
                    Expr::Path(segments, _) => {
                        let mut joined: Vec<String> = vec![];
                        for segment in segments.iter() {
                            let segment = *segment;
                            joined.push(words.resolve(segment).to_owned());
                        }
                        reach_note(aliases, pausing, by_last, &joined.join("::"), &mut out);
                    },
                    _ => { },
                }
            },
            Expr::MethodCall { method, .. } => { let method = *method; reach_note(aliases, pausing, by_last, &words.resolve(method).to_owned(), &mut out); },
            Expr::SafeMethod { method, .. } => { let method = *method; reach_note(aliases, pausing, by_last, &words.resolve(method).to_owned(), &mut out); },
            _ => { },
        }
    }
    out
}

fn reach_note(aliases: &collections::BTreeMap<String, String>, pausing: &collections::BTreeSet<String>, by_last: &collections::BTreeMap<String, Vec<String>>, written: &str, out: &mut collections::BTreeSet<String>) {
    let name = unaliased_in(aliases, written);
    if pausing.contains(&name) {
        out.insert(name);
        return;
    }
    let keys = match by_last.get(&name) { Some(__nikaia_value) => __nikaia_value, None => return };
    for key in keys.iter() { out.insert(key.to_owned()); }
}

fn reach_keys_for(by_last: &collections::BTreeMap<String, Vec<String>>, last: &str) -> Vec<String> {
    let found = match by_last.get(last) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    found.to_owned()
}

fn reach_set_for(reaches: &collections::BTreeMap<String, collections::BTreeSet<String>>, key: &str) -> collections::BTreeSet<String> {
    let found = match reaches.get(key) { Some(__nikaia_value) => __nikaia_value, None => return collections::BTreeSet::new() };
    found.to_owned()
}


