#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Finding {
    pub code: String,
    pub span: Span,
    pub message: String,
    pub notes: Vec<String>,
    pub help: Option<String>,
    pub warning: bool,
    pub labels: Vec<CheckLabel>,
}

pub fn refusal(code: &str, span: Span, message: String, notes: Vec<String>, help: String) -> Finding { Finding { code: code.to_owned(), span, message, notes, help: Some(help), warning: false, labels: vec![] } }


// --- fixed.nika ---

pub const HASHED_FROM: i64 = 12;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Table {
    pub seed: u64,
    pub disps: Vec<(u32, u32)>,
    pub keys: Vec<String>,
    pub order: Vec<i64>,
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fnv(key: &str, seed: u64) -> u64 {
    let mut hash: u64 = 14695981039346656037u64 ^ seed;
    for b in key.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211u64);
    }
    hash
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn displace(f1: u32, f2: u32, d1: u32, d2: u32) -> u32 { d2.wrapping_add(f1.wrapping_mul(d1)).wrapping_add(f2) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn build(keys: &[String]) -> Option<Table> {
    let n = keys.len() as i64;
    if n < HASHED_FROM {
        let mut written: Vec<String> = vec![];
        let mut order: Vec<i64> = vec![];
        for at in 0..n {
            written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(at))).to_owned());
            order.push(at);
        }
        return Some(Table { seed: 0, disps: vec![], keys: written, order });
    }
    let mut buckets = (n + 4) / 5;
    if buckets < 1 { buckets = 1; }
    for seed in 0..200 {
        let table = attempt(keys, u64::try_from(seed).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")), buckets, n);
        if table.is_some() { return std::convert::identity(table); }
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn attempt(keys: &[String], seed: u64, buckets: i64, n: i64) -> Option<Table> {
    let mut by_bucket: Vec<Vec<(i64, u32, u32)>> = vec![];
    for _ in 0..buckets { by_bucket.push(vec![]); }
    for at in 0..n {
        let hash = fnv(nikaia_std::index::get(&keys, nikaia_std::index::at(at)), seed);
        let g = (hash >> 32) as u32;
        let f1 = hash as u32;
        let f2 = (hash >> 16) as u32;
        by_bucket[nikaia_std::index::at(g as i64 % buckets)].push((at, f1, f2));
    }
    let mut order: Vec<(i64, i64)> = vec![];
    for b in 0..buckets {
        let size = (*nikaia_std::index::get(&by_bucket, (b) as usize)).len() as i64;
        if size > 0 { order.push((0 - size, b)); }
    }
    order.sort();
    let mut disps: Vec<(u32, u32)> = vec![];
    for _ in 0..buckets { disps.push((0, 0)); }
    let mut slots: Vec<i64> = vec![];
    for _ in 0..n { slots.push(-1); }
    for (_, bucket) in order.iter() {
        let bucket = nikaia_std::num::value(bucket);
        let mut placed = false;
        let mut d1: u32 = 0u32;
        while !placed && (d1 as i64) < n {
            let mut d2: u32 = 0u32;
            while !placed && (d2 as i64) < n {
                let mut taken: Vec<(i64, i64)> = vec![];
                let mut fits = true;
                for (at, f1, f2) in (*nikaia_std::index::get(&by_bucket, nikaia_std::index::at(bucket))).iter() {
                    let at = nikaia_std::num::value(at);let f1 = nikaia_std::num::value(f1);let f2 = nikaia_std::num::value(f2);
                    let slot = displace(f1, f2, d1, d2) as i64 % n;
                    let mut clash = *nikaia_std::index::get(&slots, nikaia_std::index::at(slot)) >= 0;
                    for t in taken.iter() { if t.0 == slot { clash = true; } }
                    if clash {
                        fits = false;
                        break;
                    }
                    taken.push((slot, at));
                }
                if fits {
                    { let __nikaia_stored = (d1, d2); nikaia_std::index::set(&mut disps, nikaia_std::index::at(bucket), __nikaia_stored); }
                    for (slot, at) in taken.iter() {
                        let slot = nikaia_std::num::value(slot);let at = nikaia_std::num::value(at);
                        { let __nikaia_stored = at; nikaia_std::index::set(&mut slots, nikaia_std::index::at(slot), __nikaia_stored); }
                    }
                    placed = true;
                }
                d2 += 1;
            }
            d1 += 1;
        }
        if !placed { return None; }
    }
    let mut written: Vec<String> = vec![];
    let mut at_of: Vec<i64> = vec![];
    for slot in slots.iter() {
        let slot = nikaia_std::num::value(slot);
        if slot < 0 { return None; }
        written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(slot))).to_owned());
        at_of.push(slot);
    }
    Some(Table { seed, disps, keys: written, order: at_of })
}


// --- fold.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Constant {
    pub value: Integer,
    pub pinned: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Folded {
    Value(Constant),
    Overflows(Constant),
    TooLarge(bool),
    Nothing,
}

const I8_LOW: u64 = 128;

const I8_HIGH: u64 = 127;

const I16_LOW: u64 = 32768;

const I16_HIGH: u64 = 32767;

const U8_HIGH: u64 = 255;

const U16_HIGH: u64 = 65535;

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fits(c: &Constant, ty: &str) -> bool { integer_fits(&c.value, ty) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn integer_fits(n: &Integer, ty: &str) -> bool {
    match ty {
        "i64" => integer_as_count(n).is_some(),
        "i32" => fits_an_i32(n),
        "u64" => !n.negative,
        "u32" => !n.negative && u32::try_from(n.magnitude).ok().is_some(),
        "i8" => within(n, I8_LOW, I8_HIGH),
        "i16" => within(n, I16_LOW, I16_HIGH),
        "u8" => within(n, 0u64, U8_HIGH),
        "u16" => within(n, 0u64, U16_HIGH),
        _ => true,
    }
}

fn fits_an_i32(n: &Integer) -> bool {
    let count = match integer_as_count(n) { Some(__nikaia_value) => __nikaia_value, None => return false };
    i32::try_from(count).ok().is_some()
}

fn within(n: &Integer, low: u64, high: u64) -> bool {
    if n.negative { return n.magnitude <= low; }
    n.magnitude <= high
}

fn stepped(n: Option<Integer>, heading: bool, pinned: String) -> Folded {
    let found = match n { Some(__nikaia_value) => __nikaia_value, None => return Folded::TooLarge(heading) };
    Folded::Value(Constant { value: found, pinned })
}

pub fn constant_of(expr: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    match expr {
        Expr::LitInt { value, negative, .. } => { let negative = *negative; let value = *value; Folded::Value(Constant { value: integer(value, negative), pinned: String::from("") }) },
        Expr::Variable(name, _) => { let name = *name; name_is(name) },
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); negated(op, expr, name_is) },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); combined(op, lhs, rhs, name_is) },
        _ => Folded::Nothing,
    }
}

fn negated(op: &UnaryOp, inner: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    if *op != UnaryOp::Neg { return Folded::Nothing; }
    match constant_of(inner, name_is) {
        Folded::Value(c) => pinned_step(Constant { value: integer_negated(&c.value), pinned: c.pinned }),
        Folded::TooLarge(negative) => Folded::TooLarge(!negative),
        other => other,
    }
}

fn pinned_step(c: Constant) -> Folded { if fits(&c, &c.pinned) { Folded::Value(c) } else { Folded::Overflows(c) } }

fn combined(op: &BinaryOp, lhs: &Expr, rhs: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    let a = match constant_of(lhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    let b = match constant_of(rhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    if !a.pinned.is_empty() && !b.pinned.is_empty() && a.pinned != b.pinned { return Folded::Nothing; }
    let pinned = if a.pinned.is_empty() { b.pinned.to_owned() } else { a.pinned.to_owned() };
    if !pinned.is_empty() && (shifts_literals(lhs) || shifts_literals(rhs)) { return Folded::Nothing; }
    let x = a.value;
    let y = b.value;
    let folded = match op {
        BinaryOp::Add => stepped(integer_sum(&x, &y), x.negative, pinned),
        BinaryOp::Sub => stepped(integer_difference(&x, &y), x.negative, pinned),
        BinaryOp::Mul => stepped(integer_product(&x, &y), x.negative != y.negative, pinned),
        BinaryOp::Div => divided(integer_quotient(&x, &y, false), pinned),
        BinaryOp::Rem => divided(integer_quotient(&x, &y, true), pinned),
        BinaryOp::Shl => fold_shifted(lhs, rhs, &x, &y, true),
        BinaryOp::Shr => fold_shifted(lhs, rhs, &x, &y, false),
        _ => Folded::Nothing,
    };
    match folded {
        Folded::Value(c) => pinned_step(c),
        other => other,
    }
}

fn divided(n: Option<Integer>, pinned: String) -> Folded {
    let found = match n { Some(__nikaia_value) => __nikaia_value, None => return Folded::Nothing };
    Folded::Value(Constant { value: found, pinned })
}

fn fold_shifted(lhs: &Expr, rhs: &Expr, x: &Integer, y: &Integer, left: bool) -> Folded {
    if !written_in_literals(lhs) || !written_in_literals(rhs) { return Folded::Nothing; }
    if y.negative || y.magnitude >= 64u64 { return Folded::Nothing; }
    let found = match integer_shifted(x, y, left) { Some(__nikaia_value) => __nikaia_value, None => return Folded::TooLarge(x.negative) };
    Folded::Value(Constant { value: found, pinned: String::from("") })
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn written_in_literals(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); *op == UnaryOp::Neg && written_in_literals(expr) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); written_in_literals(lhs) && written_in_literals(rhs) },
        _ => false,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn shifts_literals(expr: &Expr) -> bool {
    match expr {
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); shifts_literals(expr) },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); (*op == BinaryOp::Shl || *op == BinaryOp::Shr) && written_in_literals(lhs) && written_in_literals(rhs) || shifts_literals(lhs) || shifts_literals(rhs) },
        _ => false,
    }
}

pub fn wants_widening(folded: &Folded) -> bool {
    match folded {
        Folded::Value(c) => c.pinned.is_empty() && !fits(c, "i32") && fits(c, "i64"),
        _ => false,
    }
}


// --- foreign.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
struct Walked {
    seen: Vec<Seen>,
    with_names: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Seen {
    Path { name: String, span: Span },
    Call { name: String, wrote: Option<Wrote>, span: Span },
    Name(String),
    Spawn { span: Span },
    Opaque { span: Span },
    Joins { construct: String, span: Span },
}

pub fn written_in(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names: false };
    for item in program.items.iter() { item_names(&item.node, &item.span, names, unaliased, holes_of, root_at, &mut found); }
    found.seen
}

pub fn seen_in(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    block_names(block, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

pub fn seen_in_expression(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    let nowhere = Span::nowhere();
    expression_paths(expr, &nowhere, names, unaliased, holes_of, root_at, &mut found);
    expression_blocks(expr, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

fn item_names(item: &Item, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match item {
        Item::Fn { args, ret_type, body, .. } => {
            for arg in args.iter() { type_names(&arg.ty, span, names, unaliased, found); }
            maybe_type_names((ret_type).as_ref(), span, names, unaliased, found);
            block_names(body, names, unaliased, holes_of, root_at, found);
        },
        Item::Struct { fields, .. } => { for field in fields.iter() { type_names(&field.ty, span, names, unaliased, found); } },
        Item::Impl { methods, .. } => { for method in methods.iter() { item_names(&method.node, &method.span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn type_names(ty: &Type, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) {
    let name = unaliased(names.resolve(ty.name));
    if name.contains("::") { found.seen.push(named_at(name, span)); }
    for argument in ty.generics.iter() { type_names(argument, span, names, unaliased, found); }
    maybe_type_names((*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), span, names, unaliased, found);
}

fn maybe_type_names(ty: Option<&Type>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) { type_names(match ty { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, found); }

fn block_names(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, .. } => { maybe_type_names((ty).as_ref(), &stmt.span, names, unaliased, found); },
            _ => { },
        }
        statement_paths(&stmt.node, &stmt.span, names, unaliased, holes_of, root_at, found);
        statement_blocks(&stmt.node, names, unaliased, holes_of, root_at, found);
    }
}

fn statement_paths(stmt: &Stmt, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::Let { value, .. } => { expression_paths(value, span, names, unaliased, holes_of, root_at, found); },
        Stmt::Comptime { value, .. } => { expression_paths(value, span, names, unaliased, holes_of, root_at, found); },
        Stmt::Assign { target, value, .. } => {
            expression_paths(target, span, names, unaliased, holes_of, root_at, found);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
        },
        Stmt::For { iter, .. } => { expression_paths(iter, span, names, unaliased, holes_of, root_at, found); },
        Stmt::While { cond, .. } => { expression_paths(cond, span, names, unaliased, holes_of, root_at, found); },
        Stmt::Return(value) => { maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found); },
        Stmt::Expr(value) => { expression_paths(value, span, names, unaliased, holes_of, root_at, found); },
        _ => { },
    }
}

fn maybe_expression_paths(expr: Option<&Expr>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) { expression_paths(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, holes_of, root_at, found); }

fn expression_paths(expr: &Expr, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match expr {
        Expr::Spawn { .. } => { found.seen.push(Seen::Spawn { span: span.clone() }); },
        Expr::Dsl { .. } => { found.seen.push(Seen::Opaque { span: span.clone() }); },
        Expr::Overlap(_, _) => { found.seen.push(Seen::Joins { construct: String::from("overlap"), span: span.clone() }); },
        Expr::Select(_, _) => { found.seen.push(Seen::Joins { construct: String::from("select"), span: span.clone() }); },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); a_named_call(func, args, span, names, root_at, found); },
        _ => { },
    }
    for hole in holes_of(expr) { expression_paths(&hole, span, names, unaliased, holes_of, root_at, found); }
    match expr {
        Expr::Path(segments, _) => { if !segments.is_empty() { found.seen.push(named_at(path_name(segments, names, unaliased), span)); } },
        Expr::Variable(name, _) => {
            let name = *name;
            if found.with_names { found.seen.push(Seen::Name(names.resolve(name).to_owned())); }
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            expression_paths(func, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            expression_paths(lhs, span, names, unaliased, holes_of, root_at, found);
            expression_paths(rhs, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            expression_paths(index, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            expression_paths(start, span, names, unaliased, holes_of, root_at, found);
            expression_paths(end, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { expression_paths(part, span, names, unaliased, holes_of, root_at, found); } },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            expression_paths(fallback, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found); },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); expression_paths(cond, span, names, unaliased, holes_of, root_at, found); },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            for arm in arms.iter() {
                maybe_expression_paths((arm.guard).as_ref(), span, names, unaliased, holes_of, root_at, found);
                expression_paths(&arm.body, span, names, unaliased, holes_of, root_at, found);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            expression_paths(count, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { expression_paths(item, span, names, unaliased, holes_of, root_at, found); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found); },
        Expr::Select(arms, _) => { for arm in arms.iter() { expression_paths(&arm.value, span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn statement_blocks(stmt: &Stmt, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::For { body, .. } => { block_names(body, names, unaliased, holes_of, root_at, found); },
        Stmt::While { body, .. } => { block_names(body, names, unaliased, holes_of, root_at, found); },
        Stmt::Let { value, .. } => { expression_blocks(value, names, unaliased, holes_of, root_at, found); },
        Stmt::Comptime { value, .. } => { expression_blocks(value, names, unaliased, holes_of, root_at, found); },
        Stmt::Expr(value) => { expression_blocks(value, names, unaliased, holes_of, root_at, found); },
        Stmt::Assign { target, value, .. } => {
            expression_blocks(target, names, unaliased, holes_of, root_at, found);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
        },
        Stmt::Return(value) => { expression_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found); },
        _ => { },
    }
}

fn expression_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match expr {
        Expr::Block(block, _) => { block_names(block, names, unaliased, holes_of, root_at, found); },
        Expr::Unsafe(block, _) => { block_names(block, names, unaliased, holes_of, root_at, found); },
        Expr::Overlap(block, _) => { block_names(block, names, unaliased, holes_of, root_at, found); },
        Expr::Closure { body, .. } => { block_names(body, names, unaliased, holes_of, root_at, found); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            expression_blocks(func, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            expression_blocks(cond, names, unaliased, holes_of, root_at, found);
            block_names(then_branch, names, unaliased, holes_of, root_at, found);
            block_names(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            expression_blocks(expr, names, unaliased, holes_of, root_at, found);
            block_names(handler, names, unaliased, holes_of, root_at, found);
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
            for arm in arms.iter() {
                maybe_expression_blocks((arm.guard).as_ref(), names, unaliased, holes_of, root_at, found);
                expression_blocks(&arm.body, names, unaliased, holes_of, root_at, found);
            }
        },
        Expr::Select(arms, _) => {
            for arm in arms.iter() {
                expression_blocks(&arm.value, names, unaliased, holes_of, root_at, found);
                block_names(&arm.body, names, unaliased, holes_of, root_at, found);
            }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            expression_blocks(lhs, names, unaliased, holes_of, root_at, found);
            expression_blocks(rhs, names, unaliased, holes_of, root_at, found);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_blocks(expr, names, unaliased, holes_of, root_at, found); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); expression_blocks(inner, names, unaliased, holes_of, root_at, found); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); expression_blocks(inner, names, unaliased, holes_of, root_at, found); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_blocks(expr, names, unaliased, holes_of, root_at, found); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); expression_blocks(base, names, unaliased, holes_of, root_at, found); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); expression_blocks(base, names, unaliased, holes_of, root_at, found); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            expression_blocks(base, names, unaliased, holes_of, root_at, found);
            expression_blocks(index, names, unaliased, holes_of, root_at, found);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            expression_blocks(start, names, unaliased, holes_of, root_at, found);
            expression_blocks(end, names, unaliased, holes_of, root_at, found);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { expression_blocks(part, names, unaliased, holes_of, root_at, found); } },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
            expression_blocks(fallback, names, unaliased, holes_of, root_at, found);
        },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
            expression_blocks(count, names, unaliased, holes_of, root_at, found);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { expression_blocks(item, names, unaliased, holes_of, root_at, found); } },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_expression_blocks((field.value).as_ref(), names, unaliased, holes_of, root_at, found); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            expression_blocks(base, names, unaliased, holes_of, root_at, found);
            for field in fields.iter() { maybe_expression_blocks((field.value).as_ref(), names, unaliased, holes_of, root_at, found); }
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_expression_blocks((value).as_ref(), names, unaliased, holes_of, root_at, found); },
        _ => { },
    }
}

fn maybe_expression_blocks(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) { expression_blocks(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found); }

fn path_name(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut name = unaliased(names.resolve(*nikaia_std::index::get(&segments, 0)));
    for k in 1..segments.len() as i64 {
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        name = format!("{}::{}", name, segment);
    }
    name
}

fn named_at(name: String, span: &Span) -> Seen { Seen::Path { name, span: span.clone() } }

fn a_named_call(func: &Expr, args: &[Expr], span: &Span, names: &winnow_grammar::InternerContext, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    let name = match func {
        Expr::Variable(name, _) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments, _) => written_path(names, segments),
        _ => String::from(""),
    };
    if name.is_empty() {
        found.seen.push(Seen::Opaque { span: span.clone() });
        return;
    }
    let at = root_at(&name);
    let mut wrote: Option<Wrote> = None;
    if at >= 0 && at < args.len() as i64 { wrote = written_root(names, nikaia_std::index::get(&args, nikaia_std::index::at(at))); }
    found.seen.push(Seen::Call { name, wrote, span: span.clone() });
}


// --- grammar_decode.nika ---

#[derive(Debug, Clone, PartialEq)]
pub enum GrDecoded {
    Value(BuildValue),
    Unreadable(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct GrCursor {
    chars: Vec<scalar>,
    at: i64,
    detail: String,
    failed: bool,
}

impl GrCursor {
    fn peek_is(&self, c: scalar) -> bool { self.at < self.chars.len() as i64 && *nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at)) == c }
    fn fail(&mut self, detail: String) {
        if !self.failed {
            self.failed = true;
            self.detail = detail;
        }
    }
    fn skip_blanks(&mut self) { while self.at < self.chars.len() as i64 && (*nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at))).is_whitespace() { self.at += 1; } }
    fn expect(&mut self, want: scalar) {
        if self.failed { return; }
        if self.at >= self.chars.len() as i64 {
            self.fail(format!("expected `{}` and the dump ended", want));
            return;
        }
        let found = *nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at));
        self.at += 1;
        if found != want { self.fail(format!("expected `{}` and found `{}`", want, found)); }
    }
    fn word(&mut self) -> String {
        let mut out: String = String::from("");
        while self.at < self.chars.len() as i64 {
            let c = *nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at));
            if c.is_whitespace() || c == '(' || c == ')' { break; }
            out.push(c);
            self.at += 1;
        }
        out
    }
    fn quoted(&mut self, char_of: &impl Fn(i64) -> Option<scalar>) -> String {
        self.expect('"');
        let mut written: String = String::from("");
        if self.failed { return written; }
        loop {
            if self.at >= self.chars.len() as i64 {
                self.fail(String::from("the dump ended inside a string"));
                return written;
            }
            let c = *nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at));
            self.at += 1;
            if c == '"' { break; }
            written.push(c);
            if c == '\\' {
                if self.at >= self.chars.len() as i64 {
                    self.fail(String::from("the dump ended inside an escape"));
                    return written;
                }
                written.push(*nikaia_std::index::get(&self.chars, nikaia_std::index::at(self.at)));
                self.at += 1;
            }
        }
        let decoded = decoded(&written, &char_of);
        if decoded.is_none() {
            self.fail(format!("`{}` contains an escape the compiler can't read", written));
            return written;
        }
        nikaia_std::index::or(decoded, || written.into())
    }
}

pub fn gr_decode(source: &str, char_of: &impl Fn(i64) -> Option<scalar>) -> GrDecoded {
    let mut at = GrCursor { chars: nikaia_std::list::chars(source.chars()), at: 0, detail: String::from(""), failed: false };
    let value = gr_read(&mut at, char_of);
    if at.failed || value.is_none() { return GrDecoded::Unreadable(at.detail.to_owned()); }
    GrDecoded::Value(nikaia_std::index::or(value, || BuildValue::Bool(false)))
}

fn gr_items(at: &mut GrCursor, char_of: &impl Fn(i64) -> Option<scalar>) -> Vec<BuildValue> {
    let mut items: Vec<BuildValue> = vec![];
    loop {
        at.skip_blanks();
        if at.failed || at.at >= at.chars.len() as i64 || at.peek_is(')') { break; }
        let item = gr_read(at, char_of);
        if item.is_none() { break; }
        items.push(nikaia_std::index::or(item, || BuildValue::Bool(false)));
    }
    items
}

fn gr_read(at: &mut GrCursor, char_of: &impl Fn(i64) -> Option<scalar>) -> Option<BuildValue> {
    at.skip_blanks();
    at.expect('(');
    at.skip_blanks();
    if at.failed { return None; }
    let tag = at.word();
    at.skip_blanks();
    let value = match gr_shaped(&tag, at, char_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    at.skip_blanks();
    at.expect(')');
    if at.failed { return None; }
    Some(value)
}

fn gr_shaped(tag: &str, at: &mut GrCursor, char_of: &impl Fn(i64) -> Option<scalar>) -> Option<BuildValue> {
    if tag == "i" {
        let digits = at.word();
        let mut negative = false;
        let mut body = digits.to_owned();
        if digits.starts_with('-') {
            negative = true;
            body = nikaia_std::index::or(digits.strip_prefix('-'), || "").to_owned();
        }
        let magnitude = text::parse_u64(&body);
        if magnitude.is_none() {
            at.fail(format!("`{}` is not a whole number", digits));
            return None;
        }
        Some(BuildValue::Int(integer(nikaia_std::index::or(magnitude, || 0), negative)))
    } else if tag == "f" {
        let written = at.word();
        let number = text::parse_f64(&written);
        if number.is_none() {
            at.fail(format!("`{}` is not a number", written));
            return None;
        }
        Some(BuildValue::Float(nikaia_std::index::or(number, || 0.0)))
    } else if tag == "b" { Some(BuildValue::Bool(at.word() == "true")) } else if tag == "c" {
        let constructor = at.word();
        let parts = gr_items(at, char_of);
        Some(BuildValue::Constant { constructor, parts })
    } else if tag == "v" {
        let ty = at.word();
        at.skip_blanks();
        let variant = at.word();
        let payload = gr_items(at, char_of);
        Some(BuildValue::Variant { ty, variant, payload })
    } else if tag == "s" { Some(BuildValue::Text(at.quoted(char_of))) } else if tag == "l" { Some(BuildValue::List(gr_items(at, char_of))) } else if tag == "t" {
        let name = at.word();
        let mut fields: collections::BTreeMap<String, BuildValue> = collections::BTreeMap::new();
        loop {
            at.skip_blanks();
            if !at.peek_is('(') { break; }
            at.at += 1;
            at.skip_blanks();
            let field = at.word();
            let held = gr_read(at, char_of);
            if held.is_none() { return None; }
            at.skip_blanks();
            at.expect(')');
            fields.insert(field, nikaia_std::index::or(held, || BuildValue::Bool(false)));
        }
        Some(BuildValue::Struct { name, fields })
    } else {
        at.fail(format!("`{}` is not a shape this reads", tag));
        None
    }
}

pub fn gr_manifest(key: &str, dependencies: &[(String, String)]) -> String {
    let mut out: String = String::from("# GENERATED. A parser compiled so that a grammar can run while the program\n# is built (issue #178). Rewritten when the grammar changes.\n\n[workspace]\n\n[package]\n");
    out.push_str(&format!("name = \"p{}\"\n", key));
    out.push_str("version = \"0.0.0\"\nedition = \"2024\"\n\n[[bin]]\n");
    out.push_str(&format!("name = \"p{}\"\npath = \"src/main.rs\"\n\n", key));
    out.push_str("[dependencies]\n");
    let mut traced = false;
    for (name, value) in dependencies.iter() {
        if name == "\"winnow-grammar\"" { traced = true; }
        out.push_str(&format!("{} = {}\n", name, value));
    }
    if traced { out.push_str("\n[features]\ntrace = [\"winnow-grammar/trace\"]\n"); }
    out
}

pub fn gr_dump_helpers() -> String {
    String::from("
fn __nikaia_text(out: &mut String, s: &str) {
    out.push_str(\"(s \\\"\");
    for c in s.chars() {
        match c {
            '\\\\' => out.push_str(\"\\\\\\\\\"),
            '\"' => out.push_str(\"\\\\\\\"\"),
            '\\n' => out.push_str(\"\\\\n\"),
            '\\r' => out.push_str(\"\\\\r\"),
            '\\t' => out.push_str(\"\\\\t\"),
            _ => out.push(c),
        }
    }
    out.push_str(\"\\\")\");
}
")
}

pub fn gr_main(named: &str, entry: &str, dump: &str) -> String { format!("\nfn main() {{\n    let path = std::env::args().nth(1).expect(\"the input path\");\n    let text = std::fs::read_to_string(&path).expect(\"reading the input\");\n    let outcome = {{\n        use winnow::Parser;\n        let _source = &*text;\n        let mut stream = winnow_grammar::ParseInput::<()> {{\n            state: winnow_grammar::ParseContext::<()>::default(),\n            input: winnow::stream::LocatingSlice::new(_source),\n        }};\n        {}::parse_{}().parse_next(&mut stream).map_err(|e| e.render(_source))\n    }};\n    match outcome {{\n        Ok(value) => {{\n            let mut out = String::new();\n{}            println!(\"{{out}}\");\n        }}\n        Err(message) => {{\n            eprint!(\"{{message}}\");\n            std::process::exit(2);\n        }}\n    }}\n}}\n", named, entry, dump) }


// --- integers.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Integer {
    pub magnitude: u64,
    pub negative: bool,
}

pub fn integer(magnitude: u64, negative: bool) -> Integer { Integer { magnitude, negative: negative && magnitude != 0u64 } }

pub fn integer_of_count(n: i64) -> Integer {
    if n < 0 { return integer(u64::try_from(0 - (n + 1)).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")) + 1u64, true); }
    integer(u64::try_from(n).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")), false)
}

pub fn integer_as_count(n: &Integer) -> Option<i64> {
    if !n.negative { return i64::try_from(n.magnitude).ok(); }
    let below = match i64::try_from(n.magnitude - 1u64).ok() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(-1 - below)
}

pub fn integer_text(n: &Integer) -> String {
    if n.negative { return format!("-{}", n.magnitude); }
    format!("{}", n.magnitude)
}

pub fn integer_negated(n: &Integer) -> Integer { integer(n.magnitude, !n.negative) }

pub fn integer_sum(a: &Integer, b: &Integer) -> Option<Integer> {
    if a.negative == b.negative {
        let sum = match a.magnitude.checked_add(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(integer(sum, a.negative));
    }
    if a.magnitude >= b.magnitude { return Some(integer(a.magnitude - b.magnitude, a.negative)); }
    Some(integer(b.magnitude - a.magnitude, b.negative))
}

pub fn integer_difference(a: &Integer, b: &Integer) -> Option<Integer> { integer_sum(a, &integer_negated(b)) }

pub fn integer_product(a: &Integer, b: &Integer) -> Option<Integer> {
    let product = match a.magnitude.checked_mul(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(integer(product, a.negative != b.negative))
}

pub fn integer_quotient(a: &Integer, b: &Integer, remainder: bool) -> Option<Integer> {
    if remainder {
        let left = match a.magnitude.checked_rem(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(integer(left, a.negative));
    }
    let quotient = match a.magnitude.checked_div(b.magnitude) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(integer(quotient, a.negative != b.negative))
}

pub fn integer_order(a: &Integer, b: &Integer) -> i64 {
    if a.negative != b.negative { return if a.negative { -1 } else { 1 }; }
    if a.magnitude == b.magnitude { return 0; }
    let larger = a.magnitude > b.magnitude;
    if larger != a.negative { return 1; }
    -1
}

pub fn integer_bits(a: &Integer, b: &Integer, op: &str) -> Option<Integer> {
    if !a.negative && !b.negative {
        let x = a.magnitude;
        let y = b.magnitude;
        if op == "&" { return Some(integer(x & y, false)); }
        if op == "|" { return Some(integer(x | y, false)); }
        return Some(integer(x ^ y, false));
    }
    let x = match integer_as_count(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let y = match integer_as_count(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if op == "&" { return Some(integer_of_count(x & y)); }
    if op == "|" { return Some(integer_of_count(x | y)); }
    Some(integer_of_count(x ^ y))
}

pub fn integer_shifted(a: &Integer, b: &Integer, left: bool) -> Option<Integer> {
    if b.negative || b.magnitude >= 64u64 { return None; }
    let count = i64::try_from(b.magnitude).unwrap_or_else(|_| panic!("the value does not fit in an `i64`"));
    if left {
        let mut magnitude = a.magnitude;
        for _ in 0..count { magnitude = match magnitude.checked_mul(2u64) { Some(__nikaia_value) => __nikaia_value, None => return None }; }
        return Some(integer(magnitude, a.negative));
    }
    if !a.negative {
        let mut magnitude = a.magnitude;
        for _ in 0..count { magnitude /= 2; }
        return Some(integer(magnitude, false));
    }
    let mut value = match integer_as_count(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for _ in 0..count { if value % 2 != 0 { value = (value - 1) / 2; } else { value /= 2; } }
    Some(integer_of_count(value))
}


// --- interpreter.nika ---

pub fn run(items: &[Spanned<Item>], words: &winnow_grammar::InternerContext, debug: &impl Fn(&Expr) -> String, format_of: &impl Fn(&[FPart]) -> String) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    out.push(String::from("[Nikaia Kernel] Interpreter Init..."));
    for item in items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let called = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                if words.resolve(called) == "main" {
                    out.push(String::from("[Nikaia Kernel] Executing 'main'..."));
                    block(body, words, debug, format_of, &mut out);
                    return out;
                }
            },
            _ => { },
        }
    }
    out.push(String::from("[Nikaia Kernel] No main function found."));
    out
}

fn block(b: &Block, words: &winnow_grammar::InternerContext, debug: &impl Fn(&Expr) -> String, format_of: &impl Fn(&[FPart]) -> String, out: &mut Vec<String>) { for stmt in b.stmts.iter() { statement(&stmt.node, words, debug, format_of, out); } }

fn statement(stmt: &Stmt, words: &winnow_grammar::InternerContext, debug: &impl Fn(&Expr) -> String, format_of: &impl Fn(&[FPart]) -> String, out: &mut Vec<String>) {
    match stmt {
        Stmt::Let { names, value, .. } => {
            let mut bound: Vec<String> = vec![];
            for n in names.iter() {
                let n = *n;
                bound.push(words.resolve(n).to_owned());
            }
            out.push(format!("[Nikaia Runtime] Bind: {} = <evaluated>", bound.join(", ")));
            expression(value, words, debug, format_of, out);
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            out.push(format!("[Nikaia Runtime] Bind: {} = <evaluated>", words.resolve(name)));
            expression(value, words, debug, format_of, out);
        },
        Stmt::Expr(e) => { expression(e, words, debug, format_of, out); },
        Stmt::Assign { .. } => { out.push(String::from("[Nikaia Runtime] Assignment (Skipped)")); },
        Stmt::Return(_) => { out.push(String::from("[Nikaia Runtime] Return (Skipped)")); },
        Stmt::Break => { out.push(String::from("[Nikaia Runtime] Break (Skipped)")); },
        Stmt::Continue => { out.push(String::from("[Nikaia Runtime] Continue (Skipped)")); },
        Stmt::For { body, .. } => {
            out.push(String::from("[Nikaia Runtime] For loop (single pass)"));
            block(body, words, debug, format_of, out);
        },
        Stmt::While { body, .. } => {
            out.push(String::from("[Nikaia Runtime] While loop (single pass)"));
            block(body, words, debug, format_of, out);
        },
    }
}

fn expression(e: &Expr, words: &winnow_grammar::InternerContext, debug: &impl Fn(&Expr) -> String, format_of: &impl Fn(&[FPart]) -> String, out: &mut Vec<String>) {
    match e {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            match func {
                Expr::Variable(name, _) => {
                    let name = *name;
                    if words.resolve(name) == "println" {
                        printed(args, "", format_of, out);
                        return;
                    }
                    if words.resolve(name) == "log" {
                        printed(args, "[LOG] ", format_of, out);
                        return;
                    }
                },
                _ => { },
            }
            out.push(String::from("[Nikaia Runtime] Call to unknown function"));
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            out.push(String::from("[Nikaia Runtime] Spawning Task (Async -> Sync Simulation)..."));
            match body {
                Expr::Block(b, _) => { block(b, words, debug, format_of, out); },
                _ => { expression(body, words, debug, format_of, out); },
            }
        },
        Expr::LitStr { .. } => { },
        Expr::LitInterpolated { .. } => { },
        Expr::Block(b, _) => { block(b, words, debug, format_of, out); },
        Expr::Dsl { target, .. } => { let target = *target; out.push(format!("[Nikaia Runtime] DSL Block '{}' (Skipped)", words.resolve(target))); },
        _ => { out.push(format!("[Nikaia Runtime] Eval: {}", debug(e))); },
    }
}

fn printed(args: &[Expr], lead: &str, format_of: &impl Fn(&[FPart]) -> String, out: &mut Vec<String>) {
    for arg in args.iter() {
        match arg {
            Expr::LitStr { text, .. } => { out.push(format!("{}{}", lead, text)); },
            Expr::LitInterpolated { parts, .. } => { out.push(format!("{}{}", lead, format_of(parts))); },
            _ => { if lead.is_empty() { out.push(String::from("<expression>")); } },
        }
    }
}


// --- keep.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KeepContext {
    pub borrowing: collections::BTreeSet<String>,
    pub structs: collections::BTreeMap<String, DeclaredStruct>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeclaredStruct {
    pub generic: bool,
    pub fields: Vec<(String, Type)>,
}

impl KeepContext {
    pub fn of(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> KeepContext {
        let mut structs: collections::BTreeMap<String, DeclaredStruct> = collections::BTreeMap::new();
        for item in items.iter() {
            match &item.node {
                Item::Struct { name, generics, fields, .. } => {
                    let name = *name;
                    let mut written: Vec<(String, Type)> = vec![];
                    for field in fields.iter() { written.push((names.resolve(field.name).to_owned(), field.ty.clone())); }
                    structs.insert(names.resolve(name).to_owned(), DeclaredStruct { generic: !generics.is_empty(), fields: written });
                },
                _ => { },
            }
        }
        KeepContext { borrowing: borrowing_types(names, items), structs }
    }
    pub fn not_held(&self, names: &winnow_grammar::InternerContext, ty: &Type, seen: &mut Vec<String>) -> Option<String> {
        let name = names.resolve(ty.name);
        if ty.is_view {
            if name == "String" && ty.generics.is_empty() { return None; }
            return Some(format!("a view of `{}` rather than of text", name));
        }
        if ty.is_tuple && self.carries(names, ty) { return Some(String::from("a tuple of views")); }
        if self.structs.contains_key(name) && self.borrowing.contains(name) { return self.struct_not_held(names, name, seen); }
        if !self.carries(names, ty) { return None; }
        if name == "Vec" || name == "List" {
            for argument in ty.generics.iter() {
                let why = self.not_held(names, argument, seen);
                if why.is_some() { return std::convert::identity(why); }
            }
            return None;
        }
        Some(format!("a `{}` of views", name))
    }
    pub fn struct_not_held(&self, names: &winnow_grammar::InternerContext, name: &str, seen: &mut Vec<String>) -> Option<String> {
        let declared = match *nikaia_std::index::get(&self.structs, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if declared.generic { return Some(format!("`{}`, a struct of views with type parameters", name)); }
        for one in seen.iter() { if one == name { return None; } }
        seen.push(name.to_owned());
        for (field, ty) in declared.fields.iter() {
            let why = self.not_held(names, ty, seen);
            if why.is_some() {
                let held = nikaia_std::index::or(why, || "".into());
                return Some(format!("`{}.{}`, which holds {}", name, field, held));
            }
        }
        None
    }
    pub fn carries(&self, names: &winnow_grammar::InternerContext, ty: &Type) -> bool {
        if ty.is_view && !ty.lasting || self.borrowing.contains(names.resolve(ty.name)) { return true; }
        for argument in ty.generics.iter() { if self.carries(names, argument) { return true; } }
        false
    }
}

pub fn struct_in(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> Option<String> {
    let name = names.resolve(ty.name);
    if borrowing.contains(name) { return Some(name.to_owned()); }
    for argument in ty.generics.iter() {
        let found = struct_in(names, argument, borrowing);
        if found.is_some() { return std::convert::identity(found); }
    }
    None
}

pub fn names_a_struct_of_views(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> bool {
    if borrowing.contains(names.resolve(ty.name)) { return true; }
    for argument in ty.generics.iter() { if names_a_struct_of_views(names, argument, borrowing) { return true; } }
    false
}

pub fn a_ledger_type_with_a_view(ty: &Ty) -> bool {
    match ty {
        Ty::Named { view, args, .. } => { let view = *view; view || any_with_a_view(args) },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); a_ledger_type_with_a_view(inner) },
        Ty::Tuple(parts) => any_with_a_view(parts),
        Ty::Unknown => true,
        _ => false,
    }
}

fn any_with_a_view(types: &[Ty]) -> bool {
    for one in types.iter() { if a_ledger_type_with_a_view(one) { return true; } }
    false
}

pub fn takes_a_keep(contract: &FnContract) -> bool {
    for held in contract.views.iter() { if held.state == State::Tethered { return true; } }
    false
}

pub fn keeping_method_key(ledger: &Ledger, methods: &MethodIndex, target: Option<&str>, on_self: bool, method: &str) -> Option<String> {
    if on_self && target.is_some() {
        let owner = nikaia_std::index::or(target, || "");
        let key = format!("{}::{}", owner, method);
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if takes_a_keep(contract) { return Some(key); }
        return None;
    }
    let mut found: Option<String> = None;
    for key in method_keys(methods, method) {
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if takes_a_keep(contract) {
            if found.is_some() { return None; }
            found = Some(key.to_owned());
        }
    }
    found
}

pub fn written_callee(names: &winnow_grammar::InternerContext, func: &Expr, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments, _) => Some(unaliased(&joined_segments(segments, names))),
        _ => None,
    }
}

pub fn root_of(names: &winnow_grammar::InternerContext, expr: &Expr) -> Option<String> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); root_of(names, base) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); root_of(names, expr) },
        _ => None,
    }
}

pub fn taken_from(names: &winnow_grammar::InternerContext, value: &Expr) -> Option<String> {
    match value {
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; if hands_back_what_it_removes(names.resolve(method)) { root_of(names, receiver) } else { None } },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); taken_from(names, inner) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); taken_from(names, expr) },
        _ => None,
    }
}

const OWNED: [&str; 14] = ["to_owned", "clone_text", "len", "is_empty", "count", "starts_with", "ends_with", "contains", "contains_key", "parse", "to_uppercase", "to_lowercase", "join", "repeat"];

const KEEPS: [&str; 6] = ["push", "insert", "extend", "append", "push_front", "push_back"];

const SHEDS: [&str; 9] = ["clear", "remove", "drain", "pop", "truncate", "retain", "pop_front", "pop_back", "take"];

const TAKES: [&str; 6] = ["remove", "pop", "pop_front", "pop_back", "swap_remove", "take"];

pub fn hands_back_its_own(method: &str) -> bool {
    for one in OWNED.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn keeps_what_it_is_given(method: &str) -> bool {
    for one in KEEPS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn drops_entries(method: &str) -> bool {
    for one in SHEDS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn hands_back_what_it_removes(method: &str) -> bool {
    for one in TAKES.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn capitalised(text: &str) -> String {
    let mut out: String = String::from("");
    let mut first = true;
    for c in text.chars() {
        if first {
            let mut letter: String = String::from("");
            letter.push(c);
            out.push_str(&letter.to_uppercase());
            first = false;
        } else { out.push(c); }
    }
    out
}


// --- keeps.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KeepsBody<'a, 'a1> {
    pub parameters: collections::BTreeSet<String>,
    pub lent: collections::BTreeSet<String>,
    pub fields: collections::BTreeMap<String, collections::BTreeMap<String, Ty>>,
    pub returns_a_view: bool,
    pub hands_back_its_last: bool,
    pub unresolved: bool,
    pub own_methods: &'a MethodIndex,
    pub library_methods: &'a1 MethodIndex,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct KeepsWalk {
    uses: Uses,
    aliases: collections::BTreeMap<String, collections::BTreeSet<String>>,
    views: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

pub fn uses_in(body: &Block, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger) -> Uses {
    let mut walk = KeepsWalk { uses: Uses { kept: collections::BTreeSet::new(), passed: vec![] }, aliases: collections::BTreeMap::new(), views: collections::BTreeMap::new() };
    keeps_block(body, interner, holes_of, context, own, library, &mut walk);
    if context.hands_back_its_last && !body.stmts.is_empty() {
        match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1)).node {
            Stmt::Expr(value) => { hand_over(value, interner, context, own, library, &mut walk); },
            _ => { },
        }
    }
    walk.uses
}

fn keeps_block(block: &Block, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { for stmt in block.stmts.iter() { keeps_statement(&stmt.node, interner, holes_of, context, own, library, walk); } }

fn keeps_statement(stmt: &Stmt, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match stmt {
        Stmt::Assign { value, .. } => { hand_over(value, interner, context, own, library, walk); },
        Stmt::Return(value) => { if !context.returns_a_view { hand_over_maybe((value).as_ref(), interner, context, own, library, walk); } },
        Stmt::Let { names, value, mutable, .. } => {
            let mutable = *mutable;
            let reached = reached_of(value, interner, context, own, library, &walk, true);
            let viewed = keeps_viewed_of(value, interner, context, own, library, &walk);
            if mutable { for name in reached_of(value, interner, context, own, library, &walk, false) { if !context.lent.contains(&name) { walk.uses.kept.insert(name.to_owned()); } } }
            if !reached.is_empty() {
                for bound in names.iter() {
                    let bound = *bound;
                    alias(interner.resolve(bound).to_owned(), &reached, &mut walk.aliases);
                }
            }
            if !viewed.is_empty() {
                for bound in names.iter() {
                    let bound = *bound;
                    alias(interner.resolve(bound).to_owned(), &viewed, &mut walk.views);
                }
            }
        },
        _ => { },
    }
    keeps_statement_parts(stmt, interner, holes_of, context, own, library, walk);
}

fn keeps_statement_parts(stmt: &Stmt, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match stmt {
        Stmt::Let { value, .. } => { keeps_expression(value, interner, holes_of, context, own, library, walk); },
        Stmt::Comptime { value, .. } => { keeps_expression(value, interner, holes_of, context, own, library, walk); },
        Stmt::Assign { target, value, .. } => {
            keeps_expression(target, interner, holes_of, context, own, library, walk);
            keeps_expression(value, interner, holes_of, context, own, library, walk);
        },
        Stmt::For { iter, .. } => { keeps_expression(iter, interner, holes_of, context, own, library, walk); },
        Stmt::While { cond, .. } => { keeps_expression(cond, interner, holes_of, context, own, library, walk); },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            keeps_expression(returned, interner, holes_of, context, own, library, walk);
        },
        Stmt::Expr(value) => { keeps_expression(value, interner, holes_of, context, own, library, walk); },
        _ => { },
    }
    match stmt {
        Stmt::For { body, .. } => { keeps_block(body, interner, holes_of, context, own, library, walk); },
        Stmt::While { body, .. } => { keeps_block(body, interner, holes_of, context, own, library, walk); },
        Stmt::Let { value, .. } => { keeps_blocks_in(value, interner, holes_of, context, own, library, walk); },
        Stmt::Comptime { value, .. } => { keeps_blocks_in(value, interner, holes_of, context, own, library, walk); },
        Stmt::Expr(value) => { keeps_blocks_in(value, interner, holes_of, context, own, library, walk); },
        Stmt::Assign { target, value, .. } => {
            keeps_blocks_in(target, interner, holes_of, context, own, library, walk);
            keeps_blocks_in(value, interner, holes_of, context, own, library, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            keeps_blocks_in(returned, interner, holes_of, context, own, library, walk);
        },
        _ => { },
    }
}

fn alias(name: String, reached: &collections::BTreeSet<String>, into: &mut collections::BTreeMap<String, collections::BTreeSet<String>>) {
    let mut all: collections::BTreeSet<String> = collections::BTreeSet::new();
    if into.contains_key(&name) {
        let before = match *nikaia_std::index::get(&into, &name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for one in before.iter() { all.insert(one.to_owned()); }
    }
    for one in reached.iter() { all.insert(one.to_owned()); }
    into.insert(name, all);
}

fn hand_over_maybe(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { hand_over(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, interner, context, own, library, walk); }

fn hand_over(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { for name in reached_of(expr, interner, context, own, library, &walk, true) { walk.uses.kept.insert(name); } }

fn reached_of(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk, through_calls: bool) -> collections::BTreeSet<String> {
    let mut found: collections::BTreeSet<String> = collections::BTreeSet::new();
    match expr {
        Expr::If { then_branch, else_branch, .. } => {
            reached_by_last(then_branch, interner, context, own, library, walk, through_calls, &mut found);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return found };
            reached_by_last(otherwise, interner, context, own, library, walk, through_calls, &mut found);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { for name in reached_of(&arm.body, interner, context, own, library, walk, through_calls) { found.insert(name); } } },
        Expr::Block(block, _) => { reached_by_last(block, interner, context, own, library, walk, through_calls, &mut found); },
        Expr::Variable(ident, _) => {
            let ident = *ident;
            let name = interner.resolve(ident).to_owned();
            if context.parameters.contains(&name) { found.insert(name.to_owned()); }
            let aliased = match *nikaia_std::index::get(&walk.aliases, &name) { Some(__nikaia_value) => __nikaia_value, None => return found };
            for one in aliased.iter() { found.insert(one.to_owned()); }
        },
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if through_calls { for one in keeps_viewed_of(base, interner, context, own, library, walk) { found.insert(one); } }
            let parameter = match parameter_named(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return found };
            if parameter != "self" && !a_field_that_copies(&parameter, interner.resolve(name), context) { found.insert(parameter); }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if through_calls { for one in through_a_view(func, args, interner, context, own, library, walk) { found.insert(one); } }
        },
        _ => { },
    }
    found
}

#[allow(clippy::too_many_arguments)]
fn reached_by_last(block: &Block, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk, through_calls: bool, found: &mut collections::BTreeSet<String>) {
    if block.stmts.is_empty() { return; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(value) => { for name in reached_of(value, interner, context, own, library, walk, through_calls) { found.insert(name); } },
        _ => { },
    }
}

fn keeps_viewed_of(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk) -> collections::BTreeSet<String> {
    let mut found: collections::BTreeSet<String> = collections::BTreeSet::new();
    match expr {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            for one in through_a_view(func, args, interner, context, own, library, walk) { found.insert(one); }
        },
        Expr::Variable(ident, _) => {
            let ident = *ident;
            let viewing = match *nikaia_std::index::get(&walk.views, interner.resolve(ident)) { Some(__nikaia_value) => __nikaia_value, None => return found };
            for one in viewing.iter() { found.insert(one.to_owned()); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); return keeps_viewed_of(base, interner, context, own, library, walk); },
        Expr::If { then_branch, else_branch, .. } => {
            viewed_by_last(then_branch, interner, context, own, library, walk, &mut found);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return found };
            viewed_by_last(otherwise, interner, context, own, library, walk, &mut found);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { for one in keeps_viewed_of(&arm.body, interner, context, own, library, walk) { found.insert(one); } } },
        Expr::Block(block, _) => { viewed_by_last(block, interner, context, own, library, walk, &mut found); },
        _ => { },
    }
    found
}

fn viewed_by_last(block: &Block, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk, found: &mut collections::BTreeSet<String>) {
    if block.stmts.is_empty() { return; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(value) => { for one in keeps_viewed_of(value, interner, context, own, library, walk) { found.insert(one); } },
        _ => { },
    }
}

fn through_a_view(func: &Expr, args: &[Expr], interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk) -> collections::BTreeSet<String> {
    let mut found: collections::BTreeSet<String> = collections::BTreeSet::new();
    let callee = resolved_callee(func, interner, own, library);
    for at in 0..args.len() as i64 { if a_position_the_result_points_into((callee).as_deref(), at, own, library) { for one in reached_of(nikaia_std::index::get(&args, nikaia_std::index::at(at)), interner, context, own, library, walk, true) { found.insert(one); } } }
    found
}

fn a_position_the_result_points_into(callee: Option<&str>, at: i64, own: &Ledger, library: &Ledger) -> bool {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return false }.to_owned();
    if own.functions.contains_key(&known) { return points_into_at(match *nikaia_std::index::get(&own.functions, &known) { Some(__nikaia_value) => __nikaia_value, None => return false }, at); }
    points_into_at(match *nikaia_std::index::get(&library.functions, &known) { Some(__nikaia_value) => __nikaia_value, None => return false }, at)
}

fn points_into_at(contract: &FnContract, at: i64) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    if at >= signature.params.len() as i64 { return false; }
    let parameter = &nikaia_std::index::get(&signature.params, nikaia_std::index::at(at)).0;
    if nikaia_std::list::contains(&contract.borrows, &parameter) { return true; }
    contract.returns.contains(&format!("ref({})", parameter)) || contract.returns.contains(&format!("ref({} |", parameter)) || contract.returns.contains(&format!("| {})", parameter)) || contract.returns.contains(&format!("| {} |", parameter))
}

fn keeps_expression(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    classify(expr, interner, holes_of, context, own, library, walk);
    for hole in holes_of(expr) { keeps_expression(&hole, interner, holes_of, context, own, library, walk); }
    match expr {
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            keeps_expression(func, interner, holes_of, context, own, library, walk);
            keeps_expressions(args, interner, holes_of, context, own, library, walk);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_expression(receiver, interner, holes_of, context, own, library, walk);
            keeps_expressions(args, interner, holes_of, context, own, library, walk);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_expression(receiver, interner, holes_of, context, own, library, walk);
            keeps_expressions(args, interner, holes_of, context, own, library, walk);
            for setting in config.iter() { keeps_expression(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            keeps_expression(lhs, interner, holes_of, context, own, library, walk);
            keeps_expression(rhs, interner, holes_of, context, own, library, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, walk); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); keeps_expression(inner, interner, holes_of, context, own, library, walk); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); keeps_expression(inner, interner, holes_of, context, own, library, walk); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, walk); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); keeps_expression(base, interner, holes_of, context, own, library, walk); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); keeps_expression(base, interner, holes_of, context, own, library, walk); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            keeps_expression(base, interner, holes_of, context, own, library, walk);
            keeps_expression(index, interner, holes_of, context, own, library, walk);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            keeps_expression(start, interner, holes_of, context, own, library, walk);
            keeps_expression(end, interner, holes_of, context, own, library, walk);
        },
        Expr::Tuple(items, _) => { keeps_expressions(items, interner, holes_of, context, own, library, walk); },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            keeps_expression(value, interner, holes_of, context, own, library, walk);
            keeps_expression(fallback, interner, holes_of, context, own, library, walk);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); keeps_expression(expr, interner, holes_of, context, own, library, walk); },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); keeps_expression(cond, interner, holes_of, context, own, library, walk); },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            keeps_expression(value, interner, holes_of, context, own, library, walk);
            for arm in arms.iter() {
                keeps_maybe((arm.guard).as_ref(), interner, holes_of, context, own, library, walk);
                keeps_expression(&arm.body, interner, holes_of, context, own, library, walk);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { keeps_maybe((field.value).as_ref(), interner, holes_of, context, own, library, walk); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            keeps_expression(value, interner, holes_of, context, own, library, walk);
            keeps_expression(count, interner, holes_of, context, own, library, walk);
        },
        Expr::ListLit { items, .. } => { keeps_expressions(items, interner, holes_of, context, own, library, walk); },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            keeps_expression(base, interner, holes_of, context, own, library, walk);
            for field in fields.iter() { keeps_maybe((field.value).as_ref(), interner, holes_of, context, own, library, walk); }
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); keeps_maybe((value).as_ref(), interner, holes_of, context, own, library, walk); },
        Expr::Select(arms, _) => { for arm in arms.iter() { keeps_expression(&arm.value, interner, holes_of, context, own, library, walk); } },
        _ => { },
    }
}

fn keeps_expressions(items: &[Expr], interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { for item in items.iter() { keeps_expression(item, interner, holes_of, context, own, library, walk); } }

fn keeps_maybe(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { keeps_expression(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, interner, holes_of, context, own, library, walk); }

fn keeps_blocks_in(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match expr {
        Expr::Block(block, _) => { keeps_block(block, interner, holes_of, context, own, library, walk); },
        Expr::Unsafe(block, _) => { keeps_block(block, interner, holes_of, context, own, library, walk); },
        Expr::Overlap(block, _) => { keeps_block(block, interner, holes_of, context, own, library, walk); },
        Expr::Closure { body, .. } => { keeps_block(body, interner, holes_of, context, own, library, walk); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            keeps_blocks_in(func, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_blocks_in(receiver, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            keeps_blocks_in(receiver, interner, holes_of, context, own, library, walk);
            for arg in args.iter() { keeps_blocks_in(arg, interner, holes_of, context, own, library, walk); }
            for setting in config.iter() { keeps_blocks_in(&setting.value, interner, holes_of, context, own, library, walk); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            keeps_block(then_branch, interner, holes_of, context, own, library, walk);
            keeps_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, interner, holes_of, context, own, library, walk);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            keeps_blocks_in(expr, interner, holes_of, context, own, library, walk);
            keeps_block(handler, interner, holes_of, context, own, library, walk);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { keeps_blocks_in(&arm.body, interner, holes_of, context, own, library, walk); } },
        Expr::Select(arms, _) => { for arm in arms.iter() { keeps_block(&arm.body, interner, holes_of, context, own, library, walk); } },
        _ => { },
    }
}

fn classify(expr: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    match expr {
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                if field.value.is_none() {
                    let named = interner.resolve(field.name).to_owned();
                    keep_viewed_name(&named, walk);
                    if context.parameters.contains(&named) { walk.uses.kept.insert(named); }
                } else { keep_part((field.value).as_ref(), interner, context, own, library, walk); }
            }
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { keep_part(Some(item), interner, context, own, library, walk); } },
        Expr::Tuple(items, _) => { for item in items.iter() { keep_part(Some(item), interner, context, own, library, walk); } },
        Expr::ListRepeat { value, .. } => { let value = nikaia_std::boxed::open(value); keep_part(Some(value), interner, context, own, library, walk); },
        Expr::Coalesce { value, .. } => { let value = nikaia_std::boxed::open(value); keep_named(value, interner, context, own, library, walk); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); keep_named(base, interner, context, own, library, walk); },
        Expr::Try(value, _) => { let value = nikaia_std::boxed::open(value); keep_named(value, interner, context, own, library, walk); },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            keep_named(base, interner, context, own, library, walk);
            for field in fields.iter() { if field.value.is_some() { keep_part((field.value).as_ref(), interner, context, own, library, walk); } }
        },
        Expr::Match { value, .. } => {
            let value = nikaia_std::boxed::open(value);
            let name = match parameter_named(value, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return };
            if !context.lent.contains(&name) { walk.uses.kept.insert(name); }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); keep_what_a_task_names(body, interner, holes_of, context, walk); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = resolved_callee(func, interner, own, library);
            for at in 0..args.len() as i64 { if !a_position_the_result_points_into((callee).as_deref(), at, own, library) { keep_argument(nikaia_std::index::get(&args, nikaia_std::index::at(at)), (callee).as_deref(), at, interner, context, own, library, walk); } }
            for setting in config.iter() { keep_option(setting, (callee).as_deref(), interner, context, own, library, walk); }
        },
        Expr::MethodCall { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            keep_receiver(receiver, interner.resolve(method), interner, context, own, library, walk);
            keep_method_arguments(args, interner.resolve(method), interner, context, own, library, walk);
            keep_method_options(config, interner, context, own, library, walk);
        },
        Expr::SafeMethod { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            keep_receiver(receiver, interner.resolve(method), interner, context, own, library, walk);
            keep_method_arguments(args, interner.resolve(method), interner, context, own, library, walk);
            keep_method_options(config, interner, context, own, library, walk);
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn keep_argument(arg: &Expr, callee: Option<&str>, at: i64, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    let known = nikaia_std::index::or(callee, || "").to_owned();
    for parameter in keeps_handed(arg, interner, context, own, library, &walk) { if callee.is_none() { walk.uses.kept.insert(parameter); } else { walk.uses.passed.push(Passed { parameter, callee: known.to_owned(), at }); } }
}

fn keep_option(setting: &ConfigArg, callee: Option<&str>, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    let names = keeps_handed(&setting.value, interner, context, own, library, &walk);
    if names.is_empty() { return; }
    let known = nikaia_std::index::or(callee, || "").to_owned();
    let mut at: Option<i64> = None;
    if own.functions.contains_key(&known) { at = option_at(match *nikaia_std::index::get(&own.functions, &known) { Some(__nikaia_value) => __nikaia_value, None => return }, interner.resolve(setting.name)); } else if library.functions.contains_key(&known) { at = option_at(match *nikaia_std::index::get(&library.functions, &known) { Some(__nikaia_value) => __nikaia_value, None => return }, interner.resolve(setting.name)); }
    for parameter in names.iter() { if at.is_none() { walk.uses.kept.insert(parameter.to_owned()); } else { walk.uses.passed.push(Passed { parameter: parameter.to_owned(), callee: known.to_owned(), at: nikaia_std::index::or(at, || 0) }); } }
}

fn keep_method_options(config: &[ConfigArg], interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) { for setting in config.iter() { for name in keeps_handed(&setting.value, interner, context, own, library, &walk) { walk.uses.kept.insert(name); } } }

fn keep_receiver(receiver: &Expr, method: &str, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    let mut names: Vec<String> = vec![];
    match receiver {
        Expr::Variable(ident, _) => {
            let ident = *ident;
            if context.parameters.contains(interner.resolve(ident)) { names.push(interner.resolve(ident).to_owned()); }
            for one in keeps_viewed_of(receiver, interner, context, own, library, &walk) { names.push(one); }
        },
        _ => { },
    }
    if names.is_empty() { return; }
    let ours = receiver_taken_in(own, context.own_methods, method);
    let theirs = receiver_taken_in(library, context.library_methods, method);
    if context.unresolved || ours.hit || theirs.hit || !ours.any && !theirs.any { for name in names.iter() { walk.uses.kept.insert(name.to_owned()); } }
}

fn takes_its_receiver(contract: &FnContract) -> bool {
    if contract.mutates { return true; }
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    if !signature.takes_a_receiver() { return true; }
    let subject = &nikaia_std::index::get(&signature.params, 0).1;
    if subject.is_a_view() { return false; }
    match subject {
        Ty::Named { .. } => moves(&subject),
        _ => true,
    }
}

fn keep_method_arguments(args: &[Expr], method: &str, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    let ours = candidate_keys(own, context.own_methods, method);
    for k in 0..args.len() as i64 {
        let theirs = keeps_at_in(library, context.library_methods, method, k + 1);
        for name in keeps_handed(nikaia_std::index::get(&args, (k) as usize), interner, context, own, library, &walk) {
            for key in ours.iter() { walk.uses.passed.push(Passed { parameter: name.to_owned(), callee: key.to_owned(), at: k + 1 }); }
            if theirs.hit || ours.is_empty() && !theirs.any { walk.uses.kept.insert(name); }
        }
    }
}

fn candidate_keys(ledger: &Ledger, methods: &MethodIndex, method: &str) -> Vec<String> {
    let mut keys: Vec<String> = vec![];
    for key in method_keys(methods, method) {
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if takes_self(contract) { keys.push(key.to_owned()); }
    }
    keys
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CandidatesSay {
    any: bool,
    hit: bool,
}

fn receiver_taken_in(ledger: &Ledger, methods: &MethodIndex, method: &str) -> CandidatesSay {
    let mut asked = CandidatesSay { any: false, hit: false };
    for key in method_keys(methods, method) {
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if takes_self(contract) {
            asked.any = true;
            asked.hit = asked.hit || takes_its_receiver(contract);
        }
    }
    asked
}

fn keeps_at_in(ledger: &Ledger, methods: &MethodIndex, method: &str, at: i64) -> CandidatesSay {
    let mut asked = CandidatesSay { any: false, hit: false };
    for key in method_keys(methods, method) {
        let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if takes_self(contract) && has_position(contract, at) {
            asked.any = true;
            asked.hit = asked.hit || keeps_at(contract, at);
        }
    }
    asked
}

fn has_position(contract: &FnContract, at: i64) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    at < signature.params.len() as i64
}

fn takes_self(contract: &FnContract) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return true };
    signature.takes_a_receiver()
}

fn keep_what_a_task_names(body: &Expr, interner: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, context: &KeepsBody<'_, '_>, walk: &mut KeepsWalk) {
    let seen = match body {
        Expr::Closure { body, .. } => seen_in(body, interner, &name_as_it_is, holes_of, &no_root, true),
        Expr::Block(block, _) => seen_in(block, interner, &name_as_it_is, holes_of, &no_root, true),
        _ => {
            for name in context.parameters.iter() { walk.uses.kept.insert(name.to_owned()); }
            return;
        },
    };
    for one in seen.iter() {
        match one {
            Seen::Spawn { .. } => {
                for name in context.parameters.iter() { walk.uses.kept.insert(name.to_owned()); }
                return;
            },
            _ => { },
        }
    }
    for one in seen.iter() {
        match one {
            Seen::Name(name) => {
                keep_if_a_parameter(name, context, &mut walk.uses);
                keep_viewed_name(name, walk);
            },
            _ => { },
        }
    }
}

fn keep_if_a_parameter(name: &str, context: &KeepsBody<'_, '_>, uses: &mut Uses) { if context.parameters.contains(name) { uses.kept.insert(name.to_owned()); } }

fn keep_named(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    for one in keeps_viewed_of(expr, interner, context, own, library, &walk) { walk.uses.kept.insert(one); }
    walk.uses.kept.insert(match parameter_named(expr, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return });
}

fn keep_part(expr: Option<&Expr>, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &mut KeepsWalk) {
    let part = match expr { Some(__nikaia_value) => __nikaia_value, None => return };
    for one in keeps_handed(part, interner, context, own, library, &walk) { walk.uses.kept.insert(one); }
}

fn keep_viewed_name(name: &str, walk: &mut KeepsWalk) {
    let viewing = match *nikaia_std::index::get(&walk.views, name) { Some(__nikaia_value) => __nikaia_value, None => return }.to_owned();
    for one in viewing.iter() { walk.uses.kept.insert(one.to_owned()); }
}

fn keeps_handed(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>, own: &Ledger, library: &Ledger, walk: &KeepsWalk) -> Vec<String> {
    let mut names: Vec<String> = vec![];
    let part = part_of_a_parameter(expr, interner, context);
    if part.is_some() { names.push(nikaia_std::index::or(part, || "".into())); }
    for one in keeps_viewed_of(expr, interner, context, own, library, walk) { names.push(one); }
    names
}

fn parameter_named(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>) -> Option<String> {
    match expr {
        Expr::Variable(ident, _) => { let ident = *ident; match context.parameters.contains(interner.resolve(ident)) {
            true => Some(interner.resolve(ident).to_owned()),
            false => None,
        } },
        _ => None,
    }
}

fn part_of_a_parameter(expr: &Expr, interner: &winnow_grammar::InternerContext, context: &KeepsBody<'_, '_>) -> Option<String> {
    match expr {
        Expr::Field { base, name, .. } => {
            let base = nikaia_std::boxed::open(base); let name = *name;
            if parameter_named(base, interner, context).is_none() {
                let deeper = match part_of_a_parameter(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return not_self(deeper);
            }
            let parameter = match parameter_named(base, interner, context) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if a_field_that_copies(&parameter, interner.resolve(name), context) { return None; }
            return not_self(parameter);
        },
        _ => { return parameter_named(expr, interner, context); },
    }
}

fn not_self(name: String) -> Option<String> {
    if name == "self" { return None; }
    Some(name)
}

fn a_field_that_copies(parameter: &str, field: &str, context: &KeepsBody<'_, '_>) -> bool {
    let fields = match *nikaia_std::index::get(&context.fields, parameter) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let ty = match *nikaia_std::index::get(&fields, field) { Some(__nikaia_value) => __nikaia_value, None => return false };
    !moves(ty)
}

fn resolved_callee(func: &Expr, interner: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger) -> Option<String> {
    let written = match func {
        Expr::Variable(ident, _) => { let ident = *ident; interner.resolve(ident).to_owned() },
        Expr::Path(segments, _) => written_path(interner, segments),
        _ => return None,
    };
    if own.functions.contains_key(&written) || library.functions.contains_key(&written) { return Some(written); }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn name_as_it_is(name: &str) -> String { name.to_owned() }


// --- leaves.nika ---

pub fn leaves_stmt(stmt: &Stmt, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    match stmt {
        Stmt::Return(_) => { return true; },
        Stmt::Break => { return true; },
        Stmt::Continue if with_continue => { return true; },
        _ => { },
    }
    let found = match stmt {
        Stmt::Let { value, .. } => leaves_within(value, throwing, holes_of, with_continue),
        Stmt::Comptime { value, .. } => leaves_within(value, throwing, holes_of, with_continue),
        Stmt::Assign { target, value, .. } => leaves_within(target, throwing, holes_of, with_continue) || leaves_within(value, throwing, holes_of, with_continue),
        Stmt::For { iter, .. } => leaves_within(iter, throwing, holes_of, with_continue),
        Stmt::While { cond, .. } => leaves_within(cond, throwing, holes_of, with_continue),
        Stmt::Return(value) => maybe_leaves_within((value).as_ref(), throwing, holes_of, with_continue),
        Stmt::Expr(value) => leaves_within(value, throwing, holes_of, with_continue),
        _ => false,
    };
    if found { return true; }
    match stmt {
        Stmt::For { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Stmt::While { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Stmt::Let { value, .. } => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Comptime { value, .. } => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Expr(value) => blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Assign { target, value, .. } => blocks_leave(target, throwing, holes_of, with_continue) || blocks_leave(value, throwing, holes_of, with_continue),
        Stmt::Return(value) => maybe_blocks_leave((value).as_ref(), throwing, holes_of, with_continue),
        _ => false,
    }
}

pub fn leaves_block(block: &Block, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for stmt in block.stmts.iter() { if leaves_stmt(&stmt.node, throwing, holes_of, with_continue) { return true; } }
    false
}

pub fn leaves_expr(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool { leaves_within(expr, throwing, holes_of, with_continue) || blocks_leave(expr, throwing, holes_of, with_continue) }

fn leaves_here(e: &Expr, throwing: &impl Fn(&Expr) -> bool, with_continue: bool) -> bool {
    match e {
        Expr::Throw(_, _) => true,
        Expr::Return(_, _) => true,
        Expr::Break(_) => true,
        Expr::Try(_, _) => true,
        Expr::Continue(_) => with_continue,
        Expr::Call { .. } => throwing(e),
        Expr::MethodCall { .. } => throwing(e),
        Expr::SafeMethod { .. } => throwing(e),
        _ => false,
    }
}

fn leaves_within(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    if leaves_here(expr, throwing, with_continue) { return true; }
    for hole in holes_of(expr) { if leaves_within(&hole, throwing, holes_of, with_continue) { return true; } }
    match expr {
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if leaves_within(func, throwing, holes_of, with_continue) { return true; }
            any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue)
        },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); leaves_within(receiver, throwing, holes_of, with_continue) || any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); leaves_within(receiver, throwing, holes_of, with_continue) || any_leaves_within(args, throwing, holes_of, with_continue) || config_leaves_within(config, throwing, holes_of, with_continue) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); leaves_within(lhs, throwing, holes_of, with_continue) || leaves_within(rhs, throwing, holes_of, with_continue) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); leaves_within(inner, throwing, holes_of, with_continue) },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); leaves_within(inner, throwing, holes_of, with_continue) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); leaves_within(base, throwing, holes_of, with_continue) || leaves_within(index, throwing, holes_of, with_continue) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); leaves_within(start, throwing, holes_of, with_continue) || leaves_within(end, throwing, holes_of, with_continue) },
        Expr::Tuple(parts, _) => any_leaves_within(parts, throwing, holes_of, with_continue),
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); leaves_within(value, throwing, holes_of, with_continue) || leaves_within(fallback, throwing, holes_of, with_continue) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); leaves_within(expr, throwing, holes_of, with_continue) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); leaves_within(cond, throwing, holes_of, with_continue) },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            if leaves_within(value, throwing, holes_of, with_continue) { return true; }
            for arm in arms.iter() { if maybe_leaves_within((arm.guard).as_ref(), throwing, holes_of, with_continue) || leaves_within(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        Expr::StructLit { fields, .. } => fields_leave_within(fields, throwing, holes_of, with_continue),
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); leaves_within(value, throwing, holes_of, with_continue) || leaves_within(count, throwing, holes_of, with_continue) },
        Expr::ListLit { items, .. } => any_leaves_within(items, throwing, holes_of, with_continue),
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); leaves_within(base, throwing, holes_of, with_continue) || fields_leave_within(fields, throwing, holes_of, with_continue) },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_leaves_within((value).as_ref(), throwing, holes_of, with_continue) },
        Expr::Select(arms, _) => {
            for arm in arms.iter() { if leaves_within(&arm.value, throwing, holes_of, with_continue) { return true; } }
            false
        },
        _ => false,
    }
}

fn maybe_leaves_within(expr: Option<&Expr>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    leaves_within(present, throwing, holes_of, with_continue)
}

fn maybe_blocks_leave(expr: Option<&Expr>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    blocks_leave(present, throwing, holes_of, with_continue)
}

fn any_leaves_within(exprs: &[Expr], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for e in exprs.iter() { if leaves_within(e, throwing, holes_of, with_continue) { return true; } }
    false
}

fn config_leaves_within(config: &[ConfigArg], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for c in config.iter() { if leaves_within(&c.value, throwing, holes_of, with_continue) { return true; } }
    false
}

fn fields_leave_within(fields: &[FieldInit], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for field in fields.iter() { if maybe_leaves_within((field.value).as_ref(), throwing, holes_of, with_continue) { return true; } }
    false
}

fn blocks_leave(expr: &Expr, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    match expr {
        Expr::Block(block, _) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Unsafe(block, _) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Overlap(block, _) => leaves_block(block, throwing, holes_of, with_continue),
        Expr::Closure { body, .. } => leaves_block(body, throwing, holes_of, with_continue),
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if blocks_leave(func, throwing, holes_of, with_continue) { return true; }
            any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue)
        },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); blocks_leave(receiver, throwing, holes_of, with_continue) || any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); blocks_leave(receiver, throwing, holes_of, with_continue) || any_blocks_leave(args, throwing, holes_of, with_continue) || config_blocks_leave(config, throwing, holes_of, with_continue) },
        Expr::If { then_branch, else_branch, .. } => {
            if leaves_block(then_branch, throwing, holes_of, with_continue) { return true; }
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
            leaves_block(otherwise, throwing, holes_of, with_continue)
        },
        Expr::TryCatch { expr, handler, .. } => { let expr = nikaia_std::boxed::open(expr); blocks_leave(expr, throwing, holes_of, with_continue) || leaves_block(handler, throwing, holes_of, with_continue) },
        Expr::Match { arms, .. } => {
            for arm in arms.iter() { if blocks_leave(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        Expr::Select(arms, _) => {
            for arm in arms.iter() { if leaves_block(&arm.body, throwing, holes_of, with_continue) { return true; } }
            false
        },
        _ => false,
    }
}

fn any_blocks_leave(exprs: &[Expr], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for e in exprs.iter() { if blocks_leave(e, throwing, holes_of, with_continue) { return true; } }
    false
}

fn config_blocks_leave(config: &[ConfigArg], throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>, with_continue: bool) -> bool {
    for c in config.iter() { if blocks_leave(&c.value, throwing, holes_of, with_continue) { return true; } }
    false
}


// --- ledger.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerLine<'a> {
    Table { kind: &'a str, name: &'a str },
    Sources,
    Pair { key: &'a str, value: &'a str },
    Nothing,
    Unterminated,
    Bad(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Refused {
    Because(String),
}

impl Refused {
    fn message(&self) -> String {
        match self {
            Refused::Because(why) => why.to_owned(),
        }
    }
}
impl std::fmt::Display for Refused {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for Refused {}

grammar! {
    grammar LedgerText {

        rule WS =
            ""
            -> { }

        pub rule file -> Vec<LedgerLine<'a>> =
            ls:line* last:BODY eof
            -> {
                let mut all = Vec::new();
                for l in ls.into_iter() { all.push(l); }
                all.push(last);
                all
            }

        rule line -> LedgerLine<'a> =
            l:BODY line_ending
            -> { l }

        rule BODY -> LedgerLine<'a> =
            SP l:AFTER
            -> { l }

        rule AFTER -> LedgerLine<'a> =
            "#" REST
            -> { LedgerLine::Nothing }
          | "[" t:TABLE
            -> { t }
          | peek(END)
            -> { LedgerLine::Nothing }
          | k:text(KEY) "=" v:text(REST)
            -> { LedgerLine::Pair { key: k.trim(), value: v.trim() } }
          | r:text(REST)
            -> { LedgerLine::Bad(r.trim()) }

        rule TABLE -> LedgerLine<'a> =
            "sources]" SP peek(END)
            -> { LedgerLine::Sources }
          | k:KIND ".\"" n:text(NAME) CLOSE
            -> { LedgerLine::Table { kind: k, name: n } }
          | KIND ".\"" REST
            -> { LedgerLine::Unterminated }

        rule KIND -> &'a str =
            "fn"
            -> { "fn" }
          | "type"
            -> { "type" }
          | "trait"
            -> { "trait" }
          | "impl"
            -> { "impl" }

        rule SP =
            SPACE*
            -> { }

        rule SPACE =
            " "
            -> { }
          | "\t"
            -> { }

        rule END =
            line_ending
            -> { }
          | eof
            -> { }

        rule REST =
            until(line_ending | eof)
            -> { }

        rule CLOSE =
            "\"]" SP peek(END)
            -> { }

        rule NAME =
            until("\"]" | line_ending | eof)
            -> { }

        rule KEY =
            until("=" | line_ending | eof)
            -> { }
    }
}

grammar! {
    grammar LedgerValue {

        pub rule list -> Vec<&'a str> =
            "[" items:__nikaia_list<&'a str>(item = QUOTED, sep = ",") TRAILING "]" eof
            -> { items }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule QUOTED -> &'a str =
            "\"" s:text(INSIDE) "\""
            -> { s }

        rule INSIDE =
            PIECE*
            -> { }

        rule PIECE =
            ESCAPED
            -> { }
          | not("\"") not("\\") any
            -> { }

        rule ESCAPED =
            "\\" any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn unquote(value: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, "")?)
}

fn unquote_at(value: &str, at: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    if value.len() < 2 || !value.starts_with("\"") || !value.ends_with("\"") { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a quoted string, found `{}`", at, value)), &"unquote_at")); }
    let opened: String = nikaia_std::index::or(value.strip_prefix("\""), || "").to_owned();
    Ok(unescaped(&nikaia_std::index::or(opened.strip_suffix("\""), || "").to_owned()))
}

pub fn list(value: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, "")?)
}

fn list_at(value: &str, at: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "[]" { return Ok(vec![]); }
    let entries = match nikaia_std::grammar::parse(&*value, LedgerValue::parse_list()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a list, found `{}`", at, value)), &"list_at")) },
    };
    let mut out: Vec<String> = vec![];
    for entry in entries.iter() {
        let entry = *entry;
        out.push(unescaped(entry));
    }
    Ok(out)
}

fn unescaped(inside: &str) -> String {
    if !inside.contains("\\") { return inside.to_owned(); }
    let mut out: String = String::from("");
    let mut escaped = false;
    for c in inside.chars() {
        if escaped {
            if c == 'n' { out.push('\n'); } else { out.push(c); }
            escaped = false;
        } else if c == '\\' { escaped = true; } else { out.push(c); }
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Section {
    Header,
    Function,
    Kind,
    Sources,
    Nothing,
}

pub fn read(written: &str) -> Result<Ledger, nikaia_std::error::Thrown<Refused>> {
    let mut ledger = Ledger::blank();
    let mut section = Section::Header;
    let mut current: String = String::from("");
    let mut function = FnContract::empty();
    let mut a_type = TypeContract::empty();
    let mut traits: Vec<String> = vec![];
    let mut functions: Vec<String> = vec![];
    let mut answers: Vec<(String, String)> = vec![];
    let lines = match nikaia_std::grammar::parse(&*written, LedgerText::parse_file()) {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}", error)), &"read")) },
    };
    let mut n: i64 = 0;
    for one in lines.iter() {
        n += 1;
        match one {
            LedgerLine::Table { kind, name } => {
                let kind = *kind; let name = *name;
                if section == Section::Function {
                    ledger_borrows_in_order(&mut function);
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                current = name.to_owned();
                if kind == "fn" {
                    if ledger.functions.contains_key(&current) {
                        function = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.functions, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || FnContract::empty());
                    }
                    functions.push(current.to_owned());
                    section = Section::Function;
                } else if kind == "type" {
                    if ledger.types.contains_key(&current) {
                        a_type = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.types, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || TypeContract::empty());
                    }
                    section = Section::Kind;
                } else if kind == "trait" {
                    if !ledger.traits.contains_key(&current) { ledger.traits.insert(current.to_owned(), collections::BTreeSet::new()); }
                    traits.push(current.to_owned());
                    section = Section::Nothing;
                } else {
                    answers.push(implemented(&current, n)?);
                    section = Section::Nothing;
                }
            },
            LedgerLine::Sources => {
                if section == Section::Function {
                    ledger_borrows_in_order(&mut function);
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                section = Section::Sources;
            },
            LedgerLine::Pair { key, value } => {
                let key = *key; let value = *value;
                if section == Section::Header { header(&mut ledger, key, value, n)?; } else if section == Section::Sources { ledger.sources.insert(unquoted(key, n)?, unquoted(value, n)?); } else if section == Section::Function { function_key(&mut function, &current, key, value, n)?; } else if section == Section::Kind { type_key(&mut a_type, key, value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a `trait` or an `impl` table has no keys, and this has `{}`", n, key)), &"read")); }
            },
            LedgerLine::Unterminated => { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unterminated section header", n)), &"read")); },
            LedgerLine::Bad(text) => {
                let text = *text;
                return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: not a key and a value: {}", n, text)), &"read"));
            },
            LedgerLine::Nothing => { },
        }
    }
    if section == Section::Function {
        ledger_borrows_in_order(&mut function);
        ledger.functions.insert(current.to_owned(), function);
    }
    if section == Section::Kind { ledger.types.insert(current.to_owned(), a_type); }
    for name in traits.iter() {
        let prefix = format!("{}::", name);
        let mut methods: collections::BTreeSet<String> = collections::BTreeSet::new();
        for entry in functions.iter() {
            let method = after_prefix(entry, &prefix);
            if method.is_some() {
                let rest = nikaia_std::index::or(method, || "".into());
                if !rest.contains("::") { methods.insert(rest.to_owned()); }
            }
        }
        ledger.traits.insert(name.to_owned(), methods);
    }
    let mut done: Vec<String> = vec![];
    for (trait_name, _) in answers.iter() {
        if !nikaia_std::list::contains(&done, &trait_name) {
            let mut types: collections::BTreeSet<String> = collections::BTreeSet::new();
            for (other, answering) in answers.iter() { if other == trait_name { types.insert(answering.to_owned()); } }
            ledger.implementations.insert(trait_name.to_owned(), types);
            done.push(trait_name.to_owned());
        }
    }
    Ok(ledger)
}

fn header(ledger: &mut Ledger, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "version" {
        let number = nikaia_std::index::or(text::parse_i64(value), || -1);
        if number < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        if number > 4294967295i64 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        ledger.version = u32::try_from(number).unwrap_or_else(|_| panic!("the value does not fit in an `u32`"));
    } else if key == "toolchain" { ledger.toolchain = unquoted(value, n)?; } else if key == "inference" { ledger.inference = unquoted(value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown header key `{}`", n, key)), &"header")); }
    Ok(())
}

fn implemented(name: &str, n: i64) -> Result<(String, String), nikaia_std::error::Thrown<Refused>> {
    let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
    let at = find_text(&c, 0, " for ");
    if at < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: an `impl` entry is `A for T`: {}", n, name)), &"implemented")); }
    Ok((trimmed(&slice(&c, 0, at)), trimmed(&slice(&c, at + 5, c.len() as i64))))
}

fn function_key(entry: &mut FnContract, name: &str, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "sync" { entry.sync_claim = sync_of(value, n)?; } else if key == "throws" { entry.fails_with = throws_of(value, n)?; } else if key == "returns" {
        let written = unquoted(value, n)?;
        if written.contains(':') {
            entry.borrows = path_borrows_of(&written, n)?;
            entry.returns = written.to_owned();
        } else { entry.borrows = borrows_of(&written, n)?; }
    } else if key == "signature" {
        let spelled = spelled_signature(&unquoted(value, n)?, name)?;
        if spelled.mutates { entry.mutates = true; }
        if !spelled.borrows.is_empty() { entry.borrows = spelled.borrows.to_owned(); }
        entry.signature = Some(spelled.signature);
    } else if key == "keeps" { entry.keeps = entries(value, n)?; } else if key == "mutates" { entry.mutates = value == "true"; } else if key == "locks" {
        let said = value.trim();
        if said == "true" { entry.touches_a_lock = Lock::Holds; } else if said == "\"?\"" { entry.touches_a_lock = Lock::Undecided; } else { entry.touches_a_lock = Lock::No; }
    } else if key == "threads" {
        let said = value.trim();
        if said == "true" { entry.threads = Threads::May; } else if said == "false" { entry.threads = Threads::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `threads` is `true` or `false`, not `{}`. (Leave it out if nobody knows.)", n, said)), &"function_key")); }
    } else if key == "touches" {
        let mut touches: Vec<Touch> = vec![];
        for one in entries(value, n)? { touches.push(touch_of(&one)?); }
        entry.touches = touches;
        entry.touches_known = true;
    } else if key == "provenance" { entry.provenance = Some(provenance_of(&unquoted(value, n)?, n)?); } else if key == "views" {
        let mut views: Vec<Held> = vec![];
        for held in entries(value, n)? {
            let read = held_of(&held);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a tether state is `name: borrowed` or `name: tethered`, not `{}`", n, held)), &"function_key")); }
            views.push(nikaia_std::index::or(read, || Held { position: String::from(""), state: State::Borrowed }));
        }
        entry.views = views;
    } else if key == "sharing" {
        let mut classes: Vec<Class> = vec![];
        for class in entries(value, n)? {
            let read = class_of(&class);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a sharing class is `a | b: plain` or `a | b: atomic`, not `{}`", n, class)), &"function_key")); }
            classes.push(nikaia_std::index::or(read, || Class { members: vec![], count: Count::Atomic }));
        }
        entry.sharing = classes;
    } else if key == "maps" { entry.maps = entries(value, n)?; } else if key == "ends_by_length" { entry.ends_by_length = value == "true"; } else if key == "pieces" { entry.pieces = value == "true"; } else if key == "requires" { entry.requires = entries(value, n)?; } else if key == "ensures" { entry.ensures = entries(value, n)?; } else if key == "inferred" { entry.inferred = entries(value, n)?; } else if key == "from" { entry.from = entries(value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a fn", n, key)), &"function_key")); }
    Ok(())
}

fn type_key(entry: &mut TypeContract, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "crosses" { if value == "true" { entry.crosses = Crosses::May; } else if value == "false" { entry.crosses = Crosses::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `crosses` is `true` or `false`, not `{}` - and leaving the line out is the third answer", n, value)), &"type_key")); } } else if key == "compares" { entry.compares = value.trim() == "true"; } else if key == "equates" { entry.equates = value.trim() == "true"; } else if key == "orders" { entry.orders = value.trim() == "true"; } else if key == "copies" { entry.copies = value.trim() == "true"; } else if key == "tethered" { entry.tethered = entries(value, n)?; } else if key == "attribute" { entry.mark = unquoted(value, n)?; } else if key == "constant" { entry.constant = unquoted(value, n)?; } else if key == "touches" { entry.touches = entries(value, n)?; } else if key == "iterates" {
        let said = unquoted(value, n)?;
        if said != "throws" { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `iterates` is `throws` and nothing else, not `{}` - a step that cannot fail says nothing", n, said)), &"type_key")); }
        entry.iterates_fallibly = true;
    } else if key == "variants" {
        let mut variants: Vec<VariantContract> = vec![];
        for one in entries(value, n)? { variants.push(variant_of(&one)); }
        entry.variants = variants;
    } else if key == "fields" {
        let mut fields: Vec<FieldContract> = vec![];
        for one in entries(value, n)? { fields.push(field_of(&one)); }
        entry.fields = fields;
    } else if key == "attributes" { entry.attributes = entries(value, n)?; } else if key == "variant_attributes" {
        for one in entries(value, n)? {
            let c: Vec<scalar> = nikaia_std::list::chars(one.chars());
            let colon = find(&c, 0, ':');
            if colon < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a variant's attribute is `Variant: Value {{ … }}`, not `{}`", n, one)), &"type_key")); }
            let named = slice(&c, 0, colon).trim().to_owned();
            let held = slice(&c, colon + 1, c.len() as i64).trim().to_owned();
            for at in 0..entry.variants.len() as i64 { if nikaia_std::index::get(&entry.variants, (at) as usize).name == named { entry.variants[nikaia_std::index::at(at)].attributes.push(held.to_owned()); } }
        }
    } else if key == "field_attributes" {
        for one in entries(value, n)? {
            let c: Vec<scalar> = nikaia_std::list::chars(one.chars());
            let colon = find(&c, 0, ':');
            if colon < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a field's attribute is `field: Value {{ … }}`, not `{}`", n, one)), &"type_key")); }
            let field = slice(&c, 0, colon);
            let held = slice(&c, colon + 1, c.len() as i64);
            let named = field.trim().to_owned();
            for at in 0..entry.fields.len() as i64 { if nikaia_std::index::get(&entry.fields, (at) as usize).name == named { entry.fields[nikaia_std::index::at(at)].attributes.push(held.trim().to_owned()); } }
        }
    } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a type", n, key)), &"type_key")); }
    Ok(())
}

fn unquoted(value: &str, n: i64) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, &format!("line {}: ", n))?)
}

fn entries(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, &format!("line {}: ", n))?)
}

fn sync_of(value: &str, n: i64) -> Result<Sync, nikaia_std::error::Thrown<Refused>> {
    if value == "true" { return Ok(Sync::Asserted); }
    if value == "false" { return Ok(Sync::No); }
    if value == "\"inferred\"" { return Ok(Sync::Inferred); }
    let c: Vec<scalar> = nikaia_std::list::chars(value.chars());
    if value.ends_with(")\"") && (value.starts_with("\"sync(") || value.starts_with("\"from(")) && c.len() >= 8 {
        let inside = slice(&c, 6, c.len() as i64 - 2);
        let name = inside.trim();
        if !name.is_empty() { return Ok(Sync::From(name.to_owned())); }
    }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `sync` is `true` (the source says so), `\"inferred\"` (the body implies it) or `\"sync(f)\"` (its lambda decides), not `{}`", n, value)), &"sync_of"))
}

fn throws_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "true" {
        let unnamed: String = String::from("?");
        return Ok(vec![unnamed]);
    }
    Ok(entries(value, n)?)
}

fn ledger_borrows_in_order(entry: &mut FnContract) {
    if entry.returns.is_empty() { return; }
    let signature = match match entry.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut ordered: Vec<String> = vec![];
    for param in signature.params.iter() { if entry.borrows.contains(&param.0) { ordered.push(param.0.to_owned()); } }
    if (ordered.len() as i64) == entry.borrows.len() as i64 { entry.borrows = ordered; }
}

fn path_borrows_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    let mut names: Vec<String> = vec![];
    for part in value.split("),") {
        let pieces: Vec<&str> = part.split(':').collect::<Vec<_>>();
        if pieces.len() != 2 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: expected `path: ref(…)`, found `{}`", n, value)), &"path_borrows_of")); }
        let mut written = (*nikaia_std::index::get(&pieces, 1)).trim().to_owned();
        if !written.ends_with(')') { written = format!("{})", written); }
        for name in borrows_of(&written, n)? { if !nikaia_std::list::contains(&names, &name) { names.push(name.to_owned()); } }
    }
    Ok(names)
}

fn borrows_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    let c: Vec<scalar> = nikaia_std::list::chars(value.chars());
    let mut from: i64 = -1;
    if value.ends_with(')') { if value.starts_with("ref(") { from = 4; } else if value.starts_with("borrows(") { from = 8; } }
    if from < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: expected `ref(…)`, found `{}`", n, value)), &"borrows_of")); }
    let inside = slice(&c, from, c.len() as i64 - 1);
    let mut names: Vec<String> = vec![];
    for part in inside.split('|') {
        let name = part.trim();
        if !name.is_empty() { names.push(name.to_owned()); }
    }
    Ok(names)
}

fn provenance_of(value: &str, n: i64) -> Result<Provenance, nikaia_std::error::Thrown<Refused>> {
    if value == "trusted" { return Ok(Provenance::Trusted); }
    if value == "untrusted" { return Ok(Provenance::Untrusted); }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a provenance is `trusted` or `untrusted`, not `{}`", n, value)), &"provenance_of"))
}

pub fn touch_of(written: &str) -> Result<Touch, nikaia_std::error::Thrown<Refused>> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<scalar> = nikaia_std::list::chars(whole.chars());
    let space = find_last(&c, ' ');
    if space < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `resource read` or `resource write`, found `{}`", whole)), &"touch_of")); }
    let said = slice(&c, space + 1, c.len() as i64);
    let access = said.trim();
    let mut write = false;
    if access == "write" { write = true; } else if access != "read" { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `read` or `write`, not `{}` (in `{}`)", access, whole)), &"touch_of")); }
    let before = slice(&c, 0, space);
    let resource = before.trim();
    let r: Vec<scalar> = nikaia_std::list::chars(resource.chars());
    let open = find(&r, 0, '(');
    let mut kind: String = resource.to_owned();
    let mut parameter: Option<String> = None;
    if open >= 0 {
        if !resource.ends_with(')') { return Err(nikaia_std::error::throwing(Refused::Because(format!("a resource is `kind(parameter)`, and `{}` has no `)`", resource)), &"touch_of")); }
        let named = __keep_frame.put(slice(&r, 0, open));
        kind = named.trim().to_owned();
        let inside = __keep_frame.put(slice(&r, open + 1, r.len() as i64 - 1));
        parameter = Some(inside.trim().to_owned());
    }
    if kind.is_empty() { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch needs a resource kind, found `{}`", whole)), &"touch_of")); }
    Ok(Touch { kind, parameter, write })
}

pub fn held_of(written: &str) -> Option<Held> {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let state = State::parse(&slice(&c, colon + 1, c.len() as i64));
    if state.is_none() { return None; }
    let position = slice(&c, 0, colon);
    Some(Held { position: position.trim().to_owned(), state: nikaia_std::index::or(state, || State::Borrowed) })
}

pub fn class_of(written: &str) -> Option<Class> {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let named = slice(&c, 0, colon);
    let mut members: Vec<String> = vec![];
    for part in named.split('|') {
        let member = part.trim();
        if !member.is_empty() { members.push(member.to_owned()); }
    }
    if members.is_empty() { return None; }
    let count = Count::parse(&slice(&c, colon + 1, c.len() as i64));
    if count.is_none() { return None; }
    Some(Class { members, count: nikaia_std::index::or(count, || Count::Atomic) })
}

pub fn variant_of(written: &str) -> VariantContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<scalar> = nikaia_std::list::chars(whole.chars());
    let paren = find(&c, 0, '(');
    if paren >= 0 {
        let named = slice(&c, 0, paren);
        let rest = slice(&c, paren + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), ')');
        let mut holds: Vec<FieldContract> = vec![];
        let mut at = 0;
        for part in split_args(&inside) {
            holds.push(FieldContract { name: format!("{}", at), ty: parse(&part), public: true, default: String::from(""), attributes: vec![] });
            at += 1;
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: true, attributes: vec![] };
    }
    let brace = find(&c, 0, '{');
    if brace >= 0 {
        let named = slice(&c, 0, brace);
        let rest = slice(&c, brace + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), '}');
        let mut holds: Vec<FieldContract> = vec![];
        for part in split_args(&inside) {
            let p: Vec<scalar> = nikaia_std::list::chars(part.chars());
            let colon = find(&p, 0, ':');
            if colon >= 0 {
                let field = __keep_frame.put(slice(&p, 0, colon));
                holds.push(FieldContract { name: field.trim().to_owned(), ty: parse(&slice(&p, colon + 1, p.len() as i64)), public: true, default: String::from(""), attributes: vec![] });
            }
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: false, attributes: vec![] };
    }
    let nothing: Vec<FieldContract> = vec![];
    VariantContract { name: whole.to_owned(), holds: nothing, positional: false, attributes: vec![] }
}

fn field_of(written: &str) -> FieldContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut field: String = written.trim().to_owned();
    let mut public = false;
    if field.starts_with("pub ") {
        public = true;
        let rest = __keep_frame.put(from_char(&field, 4));
        field = rest.trim().to_owned();
    }
    let c: Vec<scalar> = nikaia_std::list::chars(field.chars());
    let colon = find(&c, 0, ':');
    if colon < 0 { return FieldContract { name: field.to_owned(), ty: Ty::Unknown, public, default: String::from(""), attributes: vec![] }; }
    let name = slice(&c, 0, colon);
    let equals = find(&c, colon + 1, '=');
    if equals >= 0 {
        let default = slice(&c, equals + 1, c.len() as i64);
        return FieldContract { name: name.trim().to_owned(), ty: parse(&slice(&c, colon + 1, equals)), public, default: default.trim().to_owned(), attributes: vec![] };
    }
    FieldContract { name: name.trim().to_owned(), ty: parse(&slice(&c, colon + 1, c.len() as i64)), public, default: String::from(""), attributes: vec![] }
}

pub fn signature_of(written: &str) -> Result<Signature, nikaia_std::error::Thrown<Refused>> {
    let spelled = spelled_signature(written, "")?;
    Ok(spelled.signature)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Spelling {
    pub signature: Signature,
    pub borrows: Vec<String>,
    pub mutates: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Piece<'a> {
    Owner { view: bool, mutates: bool },
    Typed { ty: &'a str, mutates: bool },
    Named { name: &'a str, ty: &'a str, mutable: bool },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Declared<'a, 'a1> {
    name: &'a str,
    traits: Vec<&'a1 str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Setting<'a, 'a1, 'a2> {
    name: &'a str,
    ty: &'a1 str,
    default: &'a2 str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Signed<'a, 'a1, 'a2, 'a3> {
    declared: Vec<Declared<'a, 'a>>,
    parts: Vec<Piece<'a1>>,
    settings: Vec<Setting<'a2, 'a2, 'a2>>,
    result: Option<&'a3 str>,
}

grammar! {
    grammar SignatureText {

        pub rule signature -> Signed<'a, 'a, 'a, 'a> =
            d:bracket "(" ps:__nikaia_list<Piece<'a>>(item = part, sep = ",") TRAILING ss:settings ")" r:result? eof
            -> { Signed { declared: d, parts: ps, settings: ss, result: r } }

        rule bracket -> Vec<Declared<'a, 'a>> =
            "[" ds:__nikaia_list<Declared<'a, 'a>>(item = declared, sep = ",") "]"
            -> { ds }
          | empty
            -> { Vec::new() }

        rule declared -> Declared<'a, 'a> =
            n:raw_ident COLON ts:__nikaia_list<&'a str>(item = BOUND, sep = "+")
            -> { Declared { name: n, traits: ts } }
          | n:raw_ident
            -> { Declared { name: n, traits: Vec::new() } }

        rule part -> Piece<'a> =
            REF MUT SELF
            -> { Piece::Owner { view: true, mutates: true } }
          | REF SELF
            -> { Piece::Owner { view: true, mutates: false } }
          | MUT SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: true } }
          | SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }
          | SELF
            -> { Piece::Owner { view: false, mutates: false } }
          | MUT n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: true } }
          | n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: false } }
          | t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }

        rule settings -> Vec<Setting<'a, 'a, 'a>> =
            ";" ss:__nikaia_list<Setting<'a, 'a, 'a>>(item = setting, sep = ",") TRAILING
            -> { ss }
          | empty
            -> { Vec::new() }

        rule setting -> Setting<'a, 'a, 'a> =
            n:raw_ident COLON t:SETTING_TYPE "=" d:DEFAULT
            -> { Setting { name: n, ty: t, default: d } }

        rule result -> &'a str =
            "->" t:REST
            -> { t }

        pub rule pointed -> Vec<Vec<&'a str>> =
            ps:POINTING* eof
            -> { ps }

        rule POINTING -> Vec<&'a str> =
            "ref(" ns:__nikaia_list<&'a str>(item = POINTED_NAME, sep = "|") ")"
            -> { ns }
          | WORD_CHARS
            -> { Vec::new() }
          | any
            -> { Vec::new() }

        rule POINTED_NAME -> &'a str =
            WS0 n:raw_ident WS0
            -> { n }

        rule WS0 =
            " "*
            -> { }

        rule WORD_CHARS =
            WORD_CHAR+
            -> { }

        rule WORD_CHAR =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }
          | "$"
            -> { }

        rule REF =
            "ref" not(WORD_CHAR)
            -> { }

        rule MUT =
            "mut" not(WORD_CHAR)
            -> { }

        rule SELF =
            "self" not(WORD_CHAR)
            -> { }

        rule COLON =
            ":" not(":")
            -> { }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule BOUND -> &'a str =
            t:text(BOUND_RUN)
            -> { t.trim() }

        rule BOUND_RUN =
            BOUND_PIECE+
            -> { }

        rule BOUND_PIECE =
            not("+") not(",") not("]") SPAN
            -> { }

        rule TYPE -> &'a str =
            t:text(TYPE_RUN)
            -> { t.trim() }

        rule TYPE_RUN =
            TYPE_PIECE+
            -> { }

        rule TYPE_PIECE =
            not(",") not(")") not(";") SPAN
            -> { }

        rule SETTING_TYPE -> &'a str =
            t:text(SETTING_RUN)
            -> { t.trim() }

        rule SETTING_RUN =
            SETTING_PIECE+
            -> { }

        rule SETTING_PIECE =
            not("=") not(",") not(")") SPAN
            -> { }

        rule DEFAULT -> &'a str =
            t:text(DEFAULT_RUN)
            -> { t.trim() }

        rule DEFAULT_RUN =
            DEFAULT_PIECE+
            -> { }

        rule DEFAULT_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule REST -> &'a str =
            t:text(REST_RUN)
            -> { t.trim() }

        rule REST_RUN =
            until(eof)
            -> { }

        rule SPAN =
            PARENS
            -> { }
          | BRACKETS
            -> { }
          | BRACES
            -> { }
          | STRING
            -> { }
          | any
            -> { }

        rule PARENS =
            "(" IN_PARENS* ")"
            -> { }

        rule BRACES =
            "{" IN_BRACES* "}"
            -> { }

        rule IN_BRACES =
            not("}") SPAN
            -> { }

        rule IN_PARENS =
            not(")") SPAN
            -> { }

        rule BRACKETS =
            "[" IN_BRACKETS* "]"
            -> { }

        rule IN_BRACKETS =
            not("]") SPAN
            -> { }

        rule STRING =
            "\"" STRING_PIECE* "\""
            -> { }

        rule STRING_PIECE =
            "\\" any
            -> { }
          | not("\"") any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn spelled_signature(written: &str, key: &str) -> Result<Spelling, nikaia_std::error::Thrown<Refused>> {
    let parts = match nikaia_std::grammar::parse(&*written, SignatureText::parse_signature()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("a signature is `[T](a: A; o: O = v) -> R`, found `{}`", written)), &"spelled_signature")) },
    };
    let mut variables: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut bounds: Vec<(String, Vec<String>)> = vec![];
    for declared in parts.declared.iter() {
        variables.insert(declared.name.to_owned());
        if !declared.traits.is_empty() || key.is_empty() {
            let mut traits: Vec<String> = vec![];
            for one in declared.traits.iter() {
                let one = *one;
                traits.push(one.to_owned());
            }
            bounds.push(a_bound(declared.name, traits));
        }
    }
    let mut params: Vec<(String, Ty)> = vec![];
    let mut changed: Vec<String> = vec![];
    let mut order: Vec<String> = vec![];
    let mut receiver_changes = false;
    let mut first = true;
    for part in parts.parts.iter() {
        match part {
            Piece::Owner { view, mutates } => {
                let mutates = *mutates; let view = *view;
                let owner = nikaia_std::index::or(owner_of(key), || "?".into());
                let written_type = if view { format!("ref {}", owner) } else { owner.to_owned() };
                params.push(a_param("self", typed(&written_type, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Typed { ty, mutates } => {
                let mutates = *mutates; let ty = *ty;
                params.push(a_param("self", typed(ty, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Named { name, ty, mutable } => {
                let mutable = *mutable; let name = *name; let ty = *ty;
                params.push(a_param(name, typed(ty, &variables)));
                if mutable { changed.push(name.to_owned()); }
                order.push(name.to_owned());
            },
        }
        first = false;
    }
    let mut config: Vec<ConfigContract> = vec![];
    for setting in parts.settings.iter() { config.push(ConfigContract { name: setting.name.to_owned(), ty: typed(setting.ty, &variables), default: setting.default.to_owned() }); }
    let mut result: Option<Ty> = None;
    let mut borrows: Vec<String> = vec![];
    let result_text = nikaia_std::index::or(parts.result, || "");
    if parts.result.is_some() {
        result = Some(typed(result_text, &variables));
        borrows = pointed_into(result_text, &order);
    }
    Ok(Spelling { signature: Signature { bounds, params, mutable: changed, config, result }, borrows, mutates: receiver_changes })
}

fn typed(written: &str, variables: &collections::BTreeSet<String>) -> Ty {
    let ty = parse(written);
    if variables.is_empty() { return ty; }
    ty.parameterise(variables)
}

fn pointed_into(result: &str, order: &[String]) -> Vec<String> {
    if !result.contains("ref(") { return vec![]; }
    let groups = match nikaia_std::grammar::parse(&*result, SignatureText::parse_pointed()) {
        Ok(value) => value,
        Err(_error) => { return vec![]; },
    };
    let mut named: Vec<String> = vec![];
    for group in groups.iter() {
        for name in group.iter() {
            let name = *name;
            if !nikaia_std::list::contains(&named, &name) { named.push(name.to_owned()); }
        }
    }
    let mut borrows: Vec<String> = vec![];
    for name in order.iter() { if nikaia_std::list::contains(&named, &name) { borrows.push(name.to_owned()); } }
    for name in named.iter() { if !nikaia_std::list::contains(&borrows, &name) { borrows.push(name.to_owned()); } }
    borrows
}

fn a_bound(name: &str, traits: Vec<String>) -> (String, Vec<String>) { (name.to_owned(), traits) }

fn a_receiver() -> String {
    let receiver: String = String::from("self");
    receiver
}

fn owner_of(key: &str) -> Option<String> {
    let c: Vec<scalar> = nikaia_std::list::chars(key.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    if last < 0 { return None; }
    Some(slice(&c, 0, last))
}

fn find(c: &[scalar], from: i64, target: scalar) -> i64 {
    for at in from..c.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == target { return at; } }
    -1
}

fn find_last(c: &[scalar], target: scalar) -> i64 {
    let mut found: i64 = -1;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, (at) as usize) == target { found = at; } }
    found
}

fn find_text(c: &[scalar], from: i64, word: &str) -> i64 {
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    if w.is_empty() || (c.len() as i64) < w.len() as i64 { return -1; }
    for at in from..c.len() as i64 - w.len() as i64 + 1 {
        let mut same = true;
        for k in 0..w.len() as i64 { if same && *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { same = false; } }
        if same { return at; }
    }
    -1
}

fn slice(c: &[scalar], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn from_char(written: &str, front: i64) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    slice(&c, front, c.len() as i64)
}

fn after_prefix(written: &str, prefix: &str) -> Option<String> {
    if !written.starts_with(prefix) { return None; }
    let p: Vec<scalar> = nikaia_std::list::chars(prefix.chars());
    Some(from_char(written, p.len() as i64))
}

fn without_last(written: &str, last: scalar) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let mut end = c.len() as i64;
    while end > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == last { end -= 1; }
    slice(&c, 0, end)
}

fn a_param(name: &str, ty: Ty) -> (String, Ty) { (name.to_owned(), ty) }

fn trimmed(written: &str) -> String { written.trim().to_owned() }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Spelled {
    pub text: String,
    pub borrows_said: bool,
    pub mutates_said: bool,
}

pub fn spell(text: &str, key: &str, borrows: &[String], mutates: bool) -> Spelled {
    let c: Vec<scalar> = nikaia_std::list::chars(text.trim().chars());
    let mut declared: Vec<String> = vec![];
    let mut open: i64 = 0;
    if !c.is_empty() && *nikaia_std::index::get(&c, 0) == '[' {
        let close = matching(&c, 1, '[', ']');
        if close < 0 { return as_written(text); }
        for entry in split_args(&slice(&c, 1, close)) {
            let entry = trimmed(&entry);
            if !entry.is_empty() { declared.push(entry); }
        }
        open = close + 1;
        while open < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(open))).is_whitespace() { open += 1; }
    }
    if open >= c.len() as i64 || *nikaia_std::index::get(&c, nikaia_std::index::at(open)) != '(' { return as_written(text); }
    let close = matching(&c, open + 1, '(', ')');
    if close < 0 { return as_written(text); }
    let inside: Vec<scalar> = nikaia_std::list::chars(slice(&c, open + 1, close).chars());
    let mut result = slice(&c, close + 1, c.len() as i64);
    let semicolon = top_level_semicolon(&inside);
    let positional = if semicolon < 0 { slice(&inside, 0, inside.len() as i64) } else { slice(&inside, 0, semicolon) };
    let mut parameters: Vec<String> = vec![];
    for part in split_args(&positional) {
        let part = trimmed(&part);
        if !part.is_empty() { parameters.push(part); }
    }
    let mut mutates_said = false;
    let mut written_parameters: Vec<String> = vec![];
    for k in 0..parameters.len() as i64 {
        if k == 0 && !is_named(nikaia_std::index::get(&parameters, 0)) {
            written_parameters.push(receiver(nikaia_std::index::get(&parameters, 0), key, mutates));
            mutates_said = mutates;
        } else { written_parameters.push((*nikaia_std::index::get(&parameters, (k) as usize)).to_owned()); }
    }
    let mut borrows_said = false;
    if !borrows.is_empty() && !word_starts(&result, "ref").is_empty() {
        let pointed = joined_by(borrows, " | ");
        result = replace_ref(&result, &format!("ref({})", pointed));
        borrows_said = true;
    }
    let mut seen: Vec<String> = vec![];
    for entry in declared.iter() { seen.push(before_colon(entry)); }
    let mut body = joined_by(&written_parameters, ", ");
    if semicolon >= 0 {
        let options = trimmed(&slice(&inside, semicolon + 1, inside.len() as i64));
        body = format!("{}; {}", body, options);
    }
    for variable in variables(&format!("{}{}", body, result)) {
        if !nikaia_std::list::contains(&seen, &variable) {
            seen.push(variable.to_owned());
            declared.push(variable.to_owned());
        }
    }
    let mut before: String = String::from("");
    if !declared.is_empty() {
        let names = joined_by(&declared, ", ");
        before = format!("[{}]", names);
    }
    Spelled { text: without_dollars(&format!("{}({}){}", before, body, result)), borrows_said, mutates_said }
}

fn as_written(text: &str) -> Spelled { Spelled { text: text.to_owned(), borrows_said: false, mutates_said: false } }

fn receiver(written: &str, key: &str, mutates: bool) -> String {
    let has_owner = owner_of(key).is_some();
    let owner = nikaia_std::index::or(owner_of(key), || "".into());
    let viewed = after_prefix(written, "ref ");
    if viewed.is_some() && has_owner && nikaia_std::index::or(viewed.as_deref(), || "") == owner {
        if mutates { return String::from("ref mut self"); }
        return String::from("ref self");
    }
    if viewed.is_none() && has_owner && written == owner && !mutates { return String::from("self"); }
    if mutates { return format!("mut self: {}", written); }
    format!("self: {}", written)
}

fn is_named(part: &str) -> bool {
    let mut rest = trimmed(part);
    while rest.starts_with("mut ") { rest = from_char(&rest, 4); }
    let c: Vec<scalar> = nikaia_std::list::chars(rest.chars());
    let mut end: i64 = 0;
    while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
    if end == 0 || !(is_lower(*nikaia_std::index::get(&c, 0)) || *nikaia_std::index::get(&c, 0) == '_') { return false; }
    let after = trimmed_start(&slice(&c, end, c.len() as i64));
    after.starts_with(':') && !after.starts_with("::")
}

fn matching(c: &[scalar], from: i64, open: scalar, close: scalar) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == open { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == close {
            if depth == 0 { return at; }
            depth -= 1;
        }
    }
    -1
}

fn top_level_semicolon(c: &[scalar]) -> i64 {
    let mut depth = 0;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, (at) as usize) == '[' || *nikaia_std::index::get(&c, (at) as usize) == '(' { depth += 1; } else if *nikaia_std::index::get(&c, (at) as usize) == ']' || *nikaia_std::index::get(&c, (at) as usize) == ')' { if depth > 0 { depth -= 1; } } else if *nikaia_std::index::get(&c, (at) as usize) == ';' && depth == 0 { return at; } }
    -1
}

fn word_starts(text: &str, word: &str) -> Vec<i64> {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let mut starts: Vec<i64> = vec![];
    let mut at = find_text(&c, 0, word);
    while at >= 0 {
        let free_before = at == 0 || !(is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(at - 1))) || *nikaia_std::index::get(&c, nikaia_std::index::at(at - 1)) == '$');
        let blank_after = (at + w.len() as i64) < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + w.len() as i64)) == ' ';
        if free_before && blank_after { starts.push(at); }
        at = find_text(&c, at + 1, word);
    }
    starts
}

fn replace_ref(text: &str, by: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    let mut from: i64 = 0;
    for at in word_starts(text, "ref") {
        out.push_str(&slice(&c, from, at));
        out.push_str(by);
        from = at + 3;
    }
    out.push_str(&slice(&c, from, c.len() as i64));
    out
}

fn variables(text: &str) -> Vec<String> {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let mut out: Vec<String> = vec![];
    for at in 0..c.len() as i64 {
        if *nikaia_std::index::get(&c, (at) as usize) == '$' {
            let mut end = at + 1;
            while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
            let name = slice(&c, at + 1, end);
            if !name.is_empty() && !nikaia_std::list::contains(&out, &name) { out.push(name); }
        }
    }
    out
}

fn joined_by(parts: &[String], between: &str) -> String {
    let mut out: String = String::from("");
    for k in 0..parts.len() as i64 {
        if k > 0 { out.push_str(between); }
        out.push_str(nikaia_std::index::get(&parts, (k) as usize));
    }
    out
}

fn without_dollars(text: &str) -> String {
    let mut out: String = String::from("");
    for c in text.chars() { if c != '$' { out.push(c); } }
    out
}

fn trimmed_start(written: &str) -> String { written.trim_start().to_owned() }

fn is_word_char(c: scalar) -> bool { is_lower(c) || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' }

fn is_lower(c: scalar) -> bool { c >= 'a' && c <= 'z' }


// --- ledger_items.nika ---

fn is_offered(name: &str) -> bool { name == "i32" || name == "i64" || name == "u8" || name == "u32" || name == "u64" || name == "f32" || name == "f64" || name == "bool" || name == "char" || name == "scalar" || name == "String" || name == "str" || name == "Self" }

pub fn types_this_file_declares(program: &Program, words: &winnow_grammar::InternerContext) -> collections::BTreeSet<String> {
    let mut declared: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in program.items.iter() {
        match &item.node {
            Item::Struct { name, .. } => {
                let name = *name;
                declared.insert(words.resolve(name).to_owned());
            },
            Item::Enum { name, .. } => {
                let name = *name;
                declared.insert(words.resolve(name).to_owned());
            },
            Item::Extern { opaque, .. } => { for handle in opaque.iter() { declared.insert(words.resolve(handle.node.name).to_owned()); } },
            _ => { },
        }
    }
    declared
}

pub fn impl_parameters(words: &winnow_grammar::InternerContext, target: &Type, declared: &collections::BTreeSet<String>) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for slot in target.generics.iter() {
        if !slot.generics.is_empty() || slot.is_tuple || slot.is_view || slot.is_nullable { continue; }
        let name = words.resolve(slot.name);
        if !is_offered(name) && !declared.contains(name) { out.push(name.to_owned()); }
    }
    out
}

pub fn a_literal(expr: &Expr) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_, _) => true,
        Expr::LitBool(_, _) => true,
        Expr::LitStr { .. } => true,
        Expr::LitChar(_, _) => true,
        Expr::LitNull(_) => true,
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            let negated = matches!(op, UnaryOp::Neg);
            negated && is_a_number(expr)
        },
        _ => false,
    }
}

fn is_a_number(expr: &Expr) -> bool { matches!(expr, Expr::LitInt { .. } | Expr::LitFloat(_, _)) }

pub fn declared_extern(words: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, declarations: &[Spanned<TraitMethod>]) -> Vec<DeclaredFn> {
    let mut out: Vec<DeclaredFn> = vec![];
    for declaration in declarations.iter() {
        let mut declared = declared_trait_method(words, aliases, "", &declaration.node, false);
        declared.contract.sync_claim = Sync::Asserted;
        declared.contract.fails_with = vec![];
        out.push(DeclaredFn { key: words.resolve(declaration.node.name).to_owned(), contract: declared.contract });
    }
    out
}

pub fn declared_grammar(words: &winnow_grammar::InternerContext, aliases: &collections::BTreeMap<String, String>, definition: &GrammarDef) -> Vec<DeclaredFn> {
    let owner = words.resolve(definition.name).to_owned();
    let mut out: Vec<DeclaredFn> = vec![];
    for rule in definition.rules.iter() {
        if !rule.is_entry { continue; }
        let mut pieces = false;
        for alt in rule.alts.iter() { if folds_in_parallel(&alt.pattern.node) { pieces = true; } }
        let mut contract = FnContract::empty();
        contract.public = definition.public;
        contract.pieces = pieces;
        contract.fails_with = vec![String::from("ParseError")];
        contract.sync_claim = Sync::Asserted;
        let mut result: Option<Ty> = None;
        if rule.ret_type.is_some() {
            let written = match rule.ret_type.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return out };
            result = Some(written_ty(words, aliases, written));
        }
        contract.signature = Some(Signature { bounds: vec![], mutable: vec![], params: vec![(String::from("input"), Ty::Unknown)], config: vec![], result });
        out.push(DeclaredFn { key: format!("{}::{}", owner, words.resolve(rule.name)), contract });
    }
    out
}

fn folds_in_parallel(pattern: &Pattern) -> bool {
    match pattern {
        Pattern::Fold(spec) => spec.parallel,
        Pattern::Bind { pat, .. } => { let pat = nikaia_std::boxed::open(pat); match &pat.node {
            Pattern::Fold(spec) => spec.parallel,
            _ => false,
        } },
        _ => false,
    }
}

pub fn literal_of(value: &BuildValue, float_text: &impl Fn(f64) -> String) -> Option<String> {
    match value {
        BuildValue::Int(n) => return Some(integer_text(n)),
        BuildValue::Float(f) => {
            let f = *f;
            if f.is_finite() { return Some(float_text(f)); }
            return None;
        },
        BuildValue::Bool(b) => {
            let b = *b;
            if b { return Some(String::from("true")); }
            return Some(String::from("false"));
        },
        BuildValue::Text(text) => return Some(format!("\"{}\"", as_a_literal(text))),
        BuildValue::Struct { name, fields } => {
            let mut written: Vec<String> = vec![];
            for (field, held) in fields.iter() {
                let text = match literal_of(held, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(format!("{}: {}", field, text));
            }
            return Some(format!("{} {{ {} }}", name, written.join(", ")));
        },
        BuildValue::List(items) => {
            for item in items.iter() { if !is_a_scalar_value(item) { return None; } }
            let mut written: Vec<String> = vec![];
            for item in items.iter() {
                let text = match literal_of(item, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(text);
            }
            return Some(format!("[{}]", written.join(", ")));
        },
        BuildValue::Variant { ty, variant, payload } => {
            if payload.is_empty() { return Some(format!("{}::{}", ty, variant)); }
            let mut written: Vec<String> = vec![];
            for held in payload.iter() {
                let text = match literal_of(held, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(text);
            }
            return Some(format!("{}::{}({})", ty, variant, written.join(", ")));
        },
        BuildValue::Constant { constructor, parts } => {
            let mut written: Vec<String> = vec![];
            for held in parts.iter() {
                let text = match literal_of(held, float_text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                written.push(text);
            }
            return Some(format!("{}({})", constructor, written.join(", ")));
        },
        _ => return None,
    }
}

fn is_a_scalar_value(value: &BuildValue) -> bool { matches!(value, BuildValue::Int(_) | BuildValue::Float(_) | BuildValue::Bool(_)) }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PublishedEnsures {
    pub key: String,
    pub condition: String,
}

pub fn expression_ensures(item: &Item, words: &winnow_grammar::InternerContext, ledger: &Ledger, reads_back: &impl Fn(&str, &collections::BTreeSet<String>) -> bool) -> Option<PublishedEnsures> {
    let (name, receiver, args, config, ret_type, body) = match item {
        Item::Fn { name, receiver, args, config, ret_type, body, .. } => { let name = *name; (name, receiver, args, config, ret_type, body) },
        _ => return None,
    };
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ret = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return None };
    if receiver.is_some() || !config.is_empty() || !ret.generics.is_empty() || body.stmts.len() != 1 { return None; }
    let answer = words.resolve(ret.name);
    if !(answer == "i32" || answer == "i64" || answer == "u8" || answer == "u32" || answer == "u64") { return None; }
    let value = match &nikaia_std::index::get(&body.stmts, 0).node {
        Stmt::Return(returned) => match returned { Some(__nikaia_value) => __nikaia_value, None => return None },
        _ => return None,
    };
    let key = words.resolve(symbol).to_owned();
    let contract = match *nikaia_std::index::get(&ledger.functions, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !contract.sync_claim.is_sync() || !contract.ensures.is_empty() { return None; }
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    for arg in args.iter() { names.insert(words.resolve(arg.name).to_owned()); }
    let mut nodes: Vec<SolverTerm> = vec![];
    let term = match lin_term(value, words, &|candidate| { names.contains(candidate) }, &|name| { nothing_pinned(name) }, &mut nodes) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let text = term_ledger_text(term, &|at| { (*nikaia_std::index::get(&nodes, nikaia_std::index::at(at))).clone() });
    let condition = format!("result == {}", text);
    let mut readable = names.to_owned();
    readable.insert(String::from("result"));
    if !reads_back(&condition, &readable) { return None; }
    Some(PublishedEnsures { key, condition })
}


// --- ledger_ops.nika ---

pub fn published_entries(ledger: &Ledger, foreign: &collections::BTreeSet<String>) -> Ledger {
    let mut out = ledger.clone();
    out.functions = collections::BTreeMap::new();
    for (key, contract) in ledger.functions.iter() { if !of_another(key, foreign) { out.functions.insert(key.to_owned(), contract.clone()); } }
    out.types = collections::BTreeMap::new();
    for (key, contract) in ledger.types.iter() { if !of_another(key, foreign) { out.types.insert(key.to_owned(), contract.clone()); } }
    out.traits = collections::BTreeMap::new();
    for (key, methods) in ledger.traits.iter() { if !of_another(key, foreign) { out.traits.insert(key.to_owned(), methods.to_owned()); } }
    out
}

fn of_another(key: &str, foreign: &collections::BTreeSet<String>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && foreign.contains(*nikaia_std::index::get(&parts, 0))
}

pub fn stale_units(ledger: &Ledger, sources: &collections::BTreeMap<String, String>) -> Vec<String> {
    let mut moved: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (unit, hash) in sources.iter() {
        let recorded = nikaia_std::index::or(*nikaia_std::index::get(&ledger.sources, unit), || "");
        if !ledger.sources.contains_key(unit) || recorded != hash { moved.insert(unit.to_owned()); }
    }
    for (unit, _) in ledger.sources.iter() { if !sources.contains_key(unit) { moved.insert(unit.to_owned()); } }
    let mut out: Vec<String> = vec![];
    for unit in moved.iter() { out.push(unit.to_owned()); }
    out
}

pub fn absorb_into(ledger: &mut Ledger, module: Option<&str>, renames: &collections::BTreeMap<String, String>, other: &Ledger) {
    let mut declared: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (name, _) in other.types.iter() { declared.insert(name.to_owned()); }
    for (name, _) in other.traits.iter() { declared.insert(name.to_owned()); }
    let prefix = nikaia_std::index::or(match module {
        Some(__nikaia_it) => Some(__nikaia_it.to_string()),
        None => None,
    }, || "".into());
    let qualified = module.is_some();
    for (field, holds) in other.code_locks.iter() {
        let holds = *holds;
        let parts: Vec<&str> = field.splitn(2, '.').collect::<Vec<_>>();
        if qualified && declared.contains(*nikaia_std::index::get(&parts, 0)) { ledger.code_locks.insert(format!("{}::{}", prefix, field), holds.clone()); } else { ledger.code_locks.insert(field.to_owned(), holds.clone()); }
    }
    for (field, set) in other.code_throws.iter() {
        let parts: Vec<&str> = field.splitn(2, '.').collect::<Vec<_>>();
        if qualified && declared.contains(*nikaia_std::index::get(&parts, 0)) { ledger.code_throws.insert(format!("{}::{}", prefix, field), set.to_owned()); } else { ledger.code_throws.insert(field.to_owned(), set.to_owned()); }
    }
    let mut kept: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for (from, to) in renames.iter() { if !qualified || *from != prefix { kept.insert(from.to_owned(), to.to_owned()); } }
    for (name, contract) in other.functions.iter() {
        let mut entry = contract.clone();
        if entry.signature.is_some() {
            let mut signature = nikaia_std::index::or(match entry.signature.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Signature::empty());
            let mut params: Vec<(String, Ty)> = vec![];
            for (param, ty) in signature.params.iter() { params.push((param.to_owned(), qualified_ty(ty, &prefix, qualified, &declared, &kept))); }
            signature.params = params;
            let mut options: Vec<ConfigContract> = vec![];
            for option in signature.config.iter() {
                let mut changed = option.clone();
                changed.ty = qualified_ty(&option.ty, &prefix, qualified, &declared, &kept);
                if qualified { changed.default = qualified_default(&option.default, &prefix, &declared); }
                options.push(changed);
            }
            signature.config = options;
            if signature.result.is_some() {
                let result = nikaia_std::index::or(match signature.result.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || Ty::Unknown);
                signature.result = Some(qualified_ty(&result, &prefix, qualified, &declared, &kept));
            }
            entry.signature = Some(signature);
        }
        ledger.functions.insert(key_under(name, &prefix, qualified), entry);
    }
    for (name, contract) in other.types.iter() {
        let mut entry = contract.clone();
        let mut fields: Vec<FieldContract> = vec![];
        for field in contract.fields.iter() {
            let mut changed = field.clone();
            changed.ty = qualified_ty(&field.ty, &prefix, qualified, &declared, &kept);
            if qualified {
                changed.default = qualified_default(&field.default, &prefix, &declared);
                let mut attributes: Vec<String> = vec![];
                for attribute in field.attributes.iter() { attributes.push(qualified_default(attribute, &prefix, &declared)); }
                changed.attributes = attributes;
            }
            fields.push(changed);
        }
        entry.fields = fields;
        if qualified {
            let mut attributes: Vec<String> = vec![];
            for attribute in contract.attributes.iter() { attributes.push(qualified_default(attribute, &prefix, &declared)); }
            entry.attributes = attributes;
            let mut variants: Vec<VariantContract> = vec![];
            for variant in contract.variants.iter() {
                let mut changed = variant.clone();
                let mut held: Vec<String> = vec![];
                for attribute in variant.attributes.iter() { held.push(qualified_default(attribute, &prefix, &declared)); }
                changed.attributes = held;
                variants.push(changed);
            }
            entry.variants = variants;
        }
        ledger.types.insert(key_under(name, &prefix, qualified), entry);
    }
    for (trait_name, types) in other.implementations.iter() {
        let mut widened = types.to_owned();
        if qualified { for ty in types.iter() { widened.insert(format!("{}::{}", prefix, ty)); } }
        if qualified { widen(ledger, format!("{}::{}", prefix, trait_name), &widened); }
        widen(ledger, trait_name.to_owned(), &widened);
    }
    for (name, methods) in other.traits.iter() { ledger.traits.insert(key_under(name, &prefix, qualified), methods.to_owned()); }
}

fn widen(ledger: &mut Ledger, name: String, types: &collections::BTreeSet<String>) {
    let mut all: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.implementations, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    for ty in types.iter() { all.insert(ty.to_owned()); }
    ledger.implementations.insert(name, all);
}

fn qualified_default(text: &str, prefix: &str, declared: &collections::BTreeSet<String>) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    let mut at: i64 = 0;
    let mut quoted = false;
    while ((at) as usize) < c.len() {
        let here = *nikaia_std::index::get(&c, (at) as usize);
        if quoted {
            out.push(here);
            if here == '\\' && ((at + 1) as usize) < c.len() {
                out.push(*nikaia_std::index::get(&c, (at + 1) as usize));
                at += 2;
                continue;
            }
            if here == '"' { quoted = false; }
            at += 1;
            continue;
        }
        if here == '"' {
            quoted = true;
            out.push(here);
            at += 1;
            continue;
        }
        if here.is_alphabetic() || here == '_' {
            let start: i64 = at;
            let mut word: String = String::from("");
            while ((at) as usize) < c.len() && ((*nikaia_std::index::get(&c, (at) as usize)).is_alphanumeric() || *nikaia_std::index::get(&c, (at) as usize) == '_') {
                word.push(*nikaia_std::index::get(&c, (at) as usize));
                at += 1;
            }
            let after_path = start >= 2 && *nikaia_std::index::get(&c, nikaia_std::index::at(start - 1)) == ':' && *nikaia_std::index::get(&c, nikaia_std::index::at(start - 2)) == ':';
            if !after_path && declared.contains(&word) {
                out.push_str(prefix);
                out.push_str("::");
            }
            out.push_str(&word);
            continue;
        }
        out.push(here);
        at += 1;
    }
    out
}

fn key_under(name: &str, prefix: &str, qualified: bool) -> String {
    if qualified { return format!("{}::{}", prefix, name); }
    name.to_owned()
}

fn qualified_ty(ty: &Ty, prefix: &str, qualified: bool, declared: &collections::BTreeSet<String>, renames: &collections::BTreeMap<String, String>) -> Ty {
    let mut out = ty.clone();
    if qualified { out = qualify(ty, prefix, declared); }
    if !renames.is_empty() { out = renamed(&out, renames); }
    out
}


// --- ledger_text.nika ---

pub fn ledger_text(ledger: &Ledger) -> String {
    let mut out: String = String::from("");
    out.push_str("# AUTO-GENERATED by `nikaia`. Commit this file like a lockfile.\n");
    out.push_str("# Do not edit by hand - it is regenerated on every build.\n");
    out.push_str("#\n");
    out.push_str("# What a caller has to know about a function it cannot see the body of:\n");
    out.push_str("# whether it may pause (`sync`), whether it may fail and with what\n");
    out.push_str("# (`throws`), and what its result may point into (`returns`). Part III, 13.5.\n");
    out.push_str("#\n");
    out.push_str("# A `\"?\"` among the errors is the absence of a claim: it fails, with\n");
    out.push_str("# something this compiler cannot name.\n");
    out.push_str(&contract_text(ledger, &no_notes()));
    out
}

pub fn derived_text(ledger: &Ledger) -> String {
    let mut out: String = String::from("");
    out.push_str("# AUTO-GENERATED by `nikaia`, beside the contract it describes.\n");
    out.push_str("# What that contract was derived from: the compiler, the inference and\n");
    out.push_str("# the sources. A consumer believes the contract while the sources hash\n");
    out.push_str("# as recorded here. Part III, 13.5.\n");
    out.push_str("version = 3\n");
    out.push_str(&format!("toolchain = \"{}\"\n", ledger.toolchain));
    out.push_str(&format!("inference = \"{}\"\n", ledger.inference));
    if !ledger.sources.is_empty() {
        out.push_str("\n[sources]\n");
        for (unit, hash) in ledger.sources.iter() { out.push_str(&format!("\"{}\" = \"{}\"\n", unit, hash)); }
    }
    out
}

pub fn description_text(ledger: &Ledger, crate_name: &str, version: &str, notes: &Notes) -> String {
    let mut out: String = String::from("");
    out.push_str(&format!("# The boundary of `{}`, described before it is called\n", crate_name));
    out.push_str("# ([ADR-290](../../docs/specification/adr/adr-290.md) D2).\n");
    out.push_str("#\n");
    out.push_str(&format!("# Written by `nikaia describe {}` from the crate's `pub` signatures,\n", crate_name));
    out.push_str("# translated by Part III 15.2's table. **Committed and reviewed like code**,\n");
    out.push_str("# and a hand edit is expected: what a signature cannot say is written\n");
    out.push_str("# fail-closed, and what it says wrongly is caught by the reviewer or by\n");
    out.push_str("# nobody (D5).\n");
    out.push_str("#\n");
    out.push_str("# What the signatures do not say: no `touches` on any entry, which reads as\n");
    out.push_str("# *touches everything*; no `locks`, which is that column's third answer.\n");
    out.push_str("# Neither is something a Rust signature can tell anybody, and reading\n");
    out.push_str("# silence as nothing at all is the polarity ADR-010 D1 forbids.\n");
    out.push_str("#\n");
    out.push_str(&format!("# crate: {} {}\n", crate_name, version));
    if !notes.about_the_crate.is_empty() {
        out.push_str("#\n");
        for line in notes.about_the_crate.iter() { out.push_str(&format!("# {}\n", line)); }
    }
    out.push_str(&contract_text(ledger, notes));
    out
}

fn no_notes() -> Notes { Notes { about_the_crate: vec![], about_a_function: collections::BTreeMap::new() } }

pub fn throws_text(errors: &[String]) -> String { format!("[{}]", quoted_all(errors)) }

fn quoted_all(items: &[String]) -> String {
    let mut out: String = String::from("");
    for item in items.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(&format!("\"{}\"", item));
    }
    out
}

fn ledger_escaped(value: &str) -> String { value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n") }

pub fn contract_text(ledger: &Ledger, notes: &Notes) -> String {
    let mut out = format!("version = {}\n", ledger.version);
    for (name, contract) in ledger.functions.iter() {
        out.push('\n');
        let about: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&notes.about_a_function, name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for line in about.iter() { out.push_str(&format!("# {}\n", line)); }
        out.push_str(&format!("[fn.\"{}\"]\n", name));
        out.push_str(&function_text(name, contract));
    }
    for (name, _) in ledger.traits.iter() { out.push_str(&format!("\n[trait.\"{}\"]\n", name)); }
    for (trait_name, types) in ledger.implementations.iter() { for ty in types.iter() { out.push_str(&format!("\n[impl.\"{} for {}\"]\n", trait_name, ty)); } }
    for (name, contract) in ledger.types.iter() {
        out.push_str(&format!("\n[type.\"{}\"]\n", name));
        out.push_str(&type_text(contract));
    }
    out
}

fn function_text(name: &str, contract: &FnContract) -> String {
    let mut out: String = String::from("");
    if contract.public { out.push_str("pub = true\n"); }
    match &contract.sync_claim {
        Sync::Asserted => { out.push_str("sync = true\n"); },
        Sync::Inferred => { out.push_str("sync = \"inferred\"\n"); },
        Sync::Unpromised => { out.push_str("sync = \"inferred\"\n"); },
        Sync::From(lambda) => { out.push_str(&format!("sync = \"sync({})\"\n", lambda)); },
        Sync::No => { },
    }
    if !contract.fails_with.is_empty() { out.push_str(&format!("throws = {}\n", throws_text(&contract.fails_with))); }
    let spelled = spelled_of(name, contract);
    let mut borrows_said = false;
    let mut mutates_said = false;
    let mut signature_line: String = String::from("");
    if spelled.is_some() {
        let said = match spelled { Some(__nikaia_value) => __nikaia_value, None => return out };
        borrows_said = said.borrows_said;
        mutates_said = said.mutates_said;
        signature_line = format!("signature = \"{}\"\n", ledger_escaped(&said.text));
    }
    if !contract.returns.is_empty() { out.push_str(&format!("returns = \"{}\"\n", contract.returns)); } else if !contract.borrows.is_empty() && !borrows_said { out.push_str(&format!("returns = \"ref({})\"\n", contract.borrows.join(" | "))); }
    if !contract.keeps.is_empty() { out.push_str(&format!("keeps = [{}]\n", quoted_all(&contract.keeps))); }
    if contract.mutates && !mutates_said { out.push_str("mutates = true\n"); }
    match contract.touches_a_lock {
        Lock::No => { },
        Lock::Holds => { out.push_str("locks = true\n"); },
        Lock::Undecided => { out.push_str("locks = \"?\"\n"); },
    }
    match contract.threads {
        Threads::Undecided => { },
        Threads::May => { out.push_str("threads = true\n"); },
        Threads::MayNot => { out.push_str("threads = false\n"); },
    }
    if contract.touches_known {
        let mut touched: Vec<String> = vec![];
        for touch in contract.touches.iter() { touched.push(touch.text()); }
        out.push_str(&format!("touches = [{}]\n", quoted_all(&touched)));
    }
    if contract.provenance.is_some() {
        let provenance = match match contract.provenance.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return out };
        out.push_str(&format!("provenance = \"{}\"\n", provenance.as_str()));
    }
    if !contract.views.is_empty() {
        let mut views: Vec<String> = vec![];
        for held in contract.views.iter() { views.push(held.text()); }
        out.push_str(&format!("views = [{}]\n", quoted_all(&views)));
    }
    if !contract.sharing.is_empty() {
        let mut classes: Vec<String> = vec![];
        for class in contract.sharing.iter() { classes.push(class.text()); }
        out.push_str(&format!("sharing = [{}]\n", quoted_all(&classes)));
    }
    if !contract.maps.is_empty() { out.push_str(&format!("maps = [{}]\n", quoted_all(&contract.maps))); }
    if contract.ends_by_length { out.push_str("ends_by_length = true\n"); }
    if contract.pieces { out.push_str("pieces = true\n"); }
    out.push_str(&claims_text("requires", &contract.requires));
    out.push_str(&claims_text("ensures", &contract.ensures));
    out.push_str(&claims_text("inferred", &contract.inferred));
    out.push_str(&claims_text("from", &contract.from));
    out.push_str(&signature_line);
    out
}

fn spelled_of(name: &str, contract: &FnContract) -> Option<Spelled> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(spell(&signature.text(), name, &contract.borrows, contract.mutates))
}

fn claims_text(key: &str, claims: &[String]) -> String {
    if claims.is_empty() { return String::from(""); }
    let mut escaped: Vec<String> = vec![];
    for claim in claims.iter() { escaped.push(ledger_escaped(claim)); }
    format!("{} = [{}]\n", key, quoted_all(&escaped))
}

fn type_text(contract: &TypeContract) -> String {
    let mut out: String = String::from("");
    if contract.public { out.push_str("pub = true\n"); }
    if !contract.fields.is_empty() {
        let mut fields: Vec<String> = vec![];
        for field in contract.fields.iter() {
            let word = if field.public { "pub " } else { "" };
            let default = if !field.default.is_empty() { format!(" = {}", field.default) } else { String::from("") };
            fields.push(ledger_escaped(&format!("{}{}: {}{}", word, field.name, field.ty.text(), default)));
        }
        out.push_str(&format!("fields = [{}]\n", quoted_all(&fields)));
        let mut attributes: Vec<String> = vec![];
        for field in contract.fields.iter() { for attribute in field.attributes.iter() { attributes.push(ledger_escaped(&format!("{}: {}", field.name, attribute))); } }
        if !attributes.is_empty() { out.push_str(&format!("field_attributes = [{}]\n", quoted_all(&attributes))); }
    }
    if !contract.variants.is_empty() {
        let mut variants: Vec<String> = vec![];
        for variant in contract.variants.iter() { variants.push(variant.text()); }
        out.push_str(&format!("variants = [{}]\n", quoted_all(&variants)));
        let mut attributes: Vec<String> = vec![];
        for variant in contract.variants.iter() { for attribute in variant.attributes.iter() { attributes.push(ledger_escaped(&format!("{}: {}", variant.name, attribute))); } }
        if !attributes.is_empty() { out.push_str(&format!("variant_attributes = [{}]\n", quoted_all(&attributes))); }
    }
    match contract.crosses {
        Crosses::May => { out.push_str("crosses = true\n"); },
        Crosses::MayNot => { out.push_str("crosses = false\n"); },
        Crosses::Undecided => { },
    }
    if contract.compares { out.push_str("compares = true\n"); }
    if contract.equates { out.push_str("equates = true\n"); }
    if contract.orders { out.push_str("orders = true\n"); }
    if contract.copies { out.push_str("copies = true\n"); }
    if contract.iterates_fallibly { out.push_str("iterates = \"throws\"\n"); }
    if !contract.touches.is_empty() { out.push_str(&format!("touches = [{}]\n", quoted_all(&contract.touches))); }
    if !contract.tethered.is_empty() { out.push_str(&format!("tethered = [{}]\n", quoted_all(&contract.tethered))); }
    if !contract.attributes.is_empty() {
        let mut escaped: Vec<String> = vec![];
        for attribute in contract.attributes.iter() { escaped.push(ledger_escaped(attribute)); }
        out.push_str(&format!("attributes = [{}]\n", quoted_all(&escaped)));
    }
    if !contract.mark.is_empty() { out.push_str(&format!("attribute = \"{}\"\n", contract.mark)); }
    if !contract.constant.is_empty() { out.push_str(&format!("constant = \"{}\"\n", contract.constant)); }
    out
}


// --- lends.nika ---

const COPIED: [&str; 20] = ["i8", "i16", "i32", "i64", "isize", "usize", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "char", "scalar", "Duration", "Instant", "Shared", "SharedMut", "Locked"];

pub fn lends_in(contract: &FnContract, at: i64, copying: &[&Ledger]) -> bool { lends_with(contract, at, copying, false) }

pub fn lends_in_own(contract: &FnContract, at: i64, copying: &[&Ledger]) -> bool { lends_with(contract, at, copying, true) }

fn lends_with(contract: &FnContract, at: i64, copying: &[&Ledger], own: bool) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let mut position: i64 = 0;
    for (name, ty) in signature.params.iter() {
        if position == at {
            if nikaia_std::list::contains(&signature.mutable, &name) || name == "self" { return false; }
            if ty.is_a_view() { return true; }
            return (!signature.takes_a_receiver() || own && a_function_value(ty)) && moves(ty) && !a_ledger_copies(ty, copying) && !nikaia_std::list::contains(&contract.keeps, &name);
        }
        position += 1;
    }
    false
}

fn a_function_value(ty: &Ty) -> bool { matches!(ty, Ty::Fn { .. }) }

pub fn a_ledger_copies(ty: &Ty, copying: &[&Ledger]) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && described_as_copying(name, copying) },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); a_ledger_copies(inner, copying) },
        _ => false,
    }
}

fn described_as_copying(name: &str, copying: &[&Ledger]) -> bool {
    for ledger in copying.iter() {
        let ledger = *ledger;
        let described = match *nikaia_std::index::get(&ledger.types, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if described.copies { return true; }
    }
    false
}

pub fn moves(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; a_name_that_moves(name, args, view) },
        Ty::Fn { .. } => true,
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); moves(inner) },
        Ty::Tuple(parts) => any_moves(parts),
        _ => false,
    }
}

fn a_name_that_moves(name: &str, args: &[Ty], view: bool) -> bool {
    let base = base_name(name);
    if base == ARRAY { return any_moves(args); }
    if view { return false; }
    for one in COPIED.iter() {
        let one = *one;
        if one == base { return false; }
    }
    true
}

fn any_moves(types: &[Ty]) -> bool {
    for one in types.iter() { if moves(one) { return true; } }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Passed {
    pub parameter: String,
    pub callee: String,
    pub at: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Uses {
    pub kept: collections::BTreeSet<String>,
    pub passed: Vec<Passed>,
}

pub fn kept_by(graph: &collections::BTreeMap<String, Uses>, own: &Ledger, library: &Ledger) -> collections::BTreeMap<String, collections::BTreeSet<String>> {
    let mut kept: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, uses) in graph.iter() { kept.insert(name.to_owned(), uses.kept.to_owned()); }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, uses) in graph.iter() {
            for passed in uses.passed.iter() {
                if keeps_already(&kept, name, &passed.parameter) { continue; }
                if keeps_its(&passed.callee, passed.at, &kept, own, library) {
                    add_kept(&mut kept, name, &passed.parameter);
                    changed = true;
                }
            }
        }
    }
    kept
}

fn keeps_already(kept: &collections::BTreeMap<String, collections::BTreeSet<String>>, name: &str, parameter: &str) -> bool {
    let parameters = match *nikaia_std::index::get(&kept, name) { Some(__nikaia_value) => __nikaia_value, None => return false };
    parameters.contains(parameter)
}

fn add_kept(kept: &mut collections::BTreeMap<String, collections::BTreeSet<String>>, name: &str, parameter: &str) {
    let mut parameters: collections::BTreeSet<String> = collections::BTreeSet::new();
    if kept.contains_key(name) {
        let held = match *nikaia_std::index::get(&kept, name) { Some(__nikaia_value) => __nikaia_value, None => return };
        for one in held.iter() { parameters.insert(one.to_owned()); }
    }
    parameters.insert(parameter.to_owned());
    kept.insert(name.to_owned(), parameters);
}

fn keeps_its(callee: &str, at: i64, settling: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger, library: &Ledger) -> bool {
    if settling.contains_key(callee) {
        let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
        let parameter = match parameter_at(contract, at) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return keeps_already(settling, callee, &parameter);
    }
    if own.functions.contains_key(callee) {
        let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return keeps_at(contract, at);
    }
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return true };
    keeps_at(contract, at)
}

fn keeps_at(contract: &FnContract, at: i64) -> bool {
    let parameter = match parameter_at(contract, at) { Some(__nikaia_value) => __nikaia_value, None => return true };
    nikaia_std::list::contains(&contract.keeps, &parameter)
}

fn parameter_at(contract: &FnContract, at: i64) -> Option<String> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut position: i64 = 0;
    for (name, _) in signature.params.iter() {
        if position == at { return Some(name.to_owned()); }
        position += 1;
    }
    for option in signature.config.iter() {
        if position == at { return Some(option.name.to_owned()); }
        position += 1;
    }
    None
}

pub fn option_at(contract: &FnContract, name: &str) -> Option<i64> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut position = signature.params.len() as i64;
    for option in signature.config.iter() {
        if option.name == name { return Some(position); }
        position += 1;
    }
    None
}

pub fn lends_option(contract: &FnContract, option: &ConfigContract) -> bool {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    if signature.takes_a_receiver() || contract.keeps.contains(&option.name) { return false; }
    match &option.ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && name == "String" },
        _ => false,
    }
}

pub fn lowered_options(contract: &FnContract) -> Vec<ConfigContract> {
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    let mut out: Vec<ConfigContract> = vec![];
    for option in signature.config.iter() { if lends_option(contract, option) { out.push(ConfigContract { name: option.name.to_owned(), ty: Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }, default: option.default.to_owned() }); } else { out.push(option.clone()); } }
    out
}


// --- libraries.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Flags {
    Taken { flags: Vec<String> },
    Refused { word: String },
}

pub fn filtered(said: &str, on_macos: bool) -> Flags {
    let mut out: Vec<String> = vec![];
    let mut framework = false;
    for word in said.split_whitespace() {
        if framework {
            out.push(format!("-framework {}", word));
            framework = false;
        } else if on_macos && word == "-framework" { framework = true; } else if word.starts_with("-l") && word.len() > 2 || word.starts_with("-L") && word.len() > 2 || word == "-pthread" || on_macos && word.starts_with("-F") && word.len() > 2 { out.push(word.to_owned()); } else { return Flags::Refused { word: word.to_owned() }; }
    }
    if framework { return Flags::Refused { word: String::from("-framework") }; }
    Flags::Taken { flags: out }
}

pub fn as_rustc_args(flags: &[String]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for flag in flags.iter() {
        if flag.starts_with("-l") { out.push(format!("-Clink-arg={}", flag)); } else if flag.starts_with("-L") {
            let dir = nikaia_std::index::or(flag.strip_prefix("-L"), || "");
            out.push(String::from("-L"));
            out.push(format!("native={}", dir));
        } else if flag.starts_with("-F") {
            let dir = nikaia_std::index::or(flag.strip_prefix("-F"), || "");
            out.push(String::from("-L"));
            out.push(format!("framework={}", dir));
        } else if flag.starts_with("-framework ") {
            let name = nikaia_std::index::or(flag.strip_prefix("-framework "), || "");
            out.push(String::from("-l"));
            out.push(format!("framework={}", name));
        } else { out.push(format!("-Clink-arg={}", flag)); }
    }
    out
}


// --- locks.nika ---

const DOORS: [&str; 10] = ["Locked::get", "Locked::set", "Locked::set(after)", "Locked::access", "Locked::update", "SharedMut::get", "SharedMut::set", "SharedMut::set(after)", "SharedMut::access", "SharedMut::update"];

const MULTI: [&str; 2] = ["access_all", "update_all"];

const FIELD: &str = "field:";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BodyCalls {
    pub resolved: collections::BTreeSet<String>,
    pub unresolved: bool,
    pub fields_called: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reaches {
    pub itself: Lock,
    pub callees: collections::BTreeSet<String>,
}

pub fn stored_reaches(field: &str, resolved: &collections::BTreeSet<String>, unresolved: bool, free: &collections::BTreeSet<String>, graph: &mut collections::BTreeMap<String, Reaches>) {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    if unresolved { reaches.itself = reaches.itself.or(Lock::Undecided); }
    if any_in(resolved, &DOORS) || any_in(free, &MULTI) { reaches.itself = reaches.itself.or(Lock::Holds); }
    for to in resolved.iter() { reaches.callees.insert(to.to_owned()); }
    for to in free.iter() {
        if to.starts_with('@') {
            reaches.itself = reaches.itself.or(Lock::Undecided);
            continue;
        }
        reaches.callees.insert(to.to_owned());
    }
    graph.insert(format!("{}{}", FIELD, field), reaches);
}

pub fn unit_reaches(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, calls: &collections::BTreeMap<String, BodyCalls>, graph: &mut collections::BTreeMap<String, Reaches>) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                graph.insert(key.to_owned(), body_reaches(body, *nikaia_std::index::get(&calls, &key), names, unaliased, holes_of));
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, .. } => {
                            let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            graph.insert(key.to_owned(), body_reaches(body, *nikaia_std::index::get(&calls, &key), names, unaliased, holes_of));
                        },
                        _ => { },
                    }
                }
            },
            Item::Grammar(def) => { rules_reaches(def, names, unaliased, holes_of, calls, graph); },
            _ => { },
        }
    }
}

pub fn free_calls(body: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> collections::BTreeSet<String> {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    walk_calls(body, names, unaliased, holes_of, &mut reaches);
    reaches.callees
}

pub fn declared_types(program: &Program, names: &winnow_grammar::InternerContext, declared: &mut collections::BTreeSet<String>) {
    for item in program.items.iter() {
        match &item.node {
            Item::Enum { name, .. } => {
                let name = *name;
                declared.insert(names.resolve(name).to_owned());
            },
            Item::Struct { name, .. } => {
                let name = *name;
                declared.insert(names.resolve(name).to_owned());
            },
            _ => { },
        }
    }
}

pub fn locking_of(graph: &collections::BTreeMap<String, Reaches>, declared: &collections::BTreeSet<String>, library: &Ledger, own: &Ledger) -> Locking {
    let mut itself: collections::BTreeMap<String, Lock> = collections::BTreeMap::new();
    let mut callees: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, reaches) in graph.iter() {
        itself.insert(name.to_owned(), reaches.itself.clone());
        callees.insert(name.to_owned(), reaches.callees.to_owned());
    }
    locking(&itself, &callees, declared, library, own)
}

fn key_of_function(name: Option<&winnow_grammar::Symbol>, owner: &str, names: &winnow_grammar::InternerContext) -> String {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return with_owner(owner, "new") };
    with_owner(owner, names.resolve(*symbol))
}

fn with_owner(owner: &str, own: &str) -> String {
    if owner.is_empty() { return own.to_owned(); }
    format!("{}::{}", owner, own)
}

fn body_reaches(body: &Block, calls: Option<&BodyCalls>, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Reaches {
    let mut reaches = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    resolved_into(calls, true, &mut reaches);
    walk_calls(body, names, unaliased, holes_of, &mut reaches);
    reaches
}

fn resolved_into(calls: Option<&BodyCalls>, with_fields: bool, reaches: &mut Reaches) {
    let known = match calls { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unresolved { reaches.itself = reaches.itself.or(Lock::Undecided); }
    if any_in(&known.resolved, &DOORS) { reaches.itself = reaches.itself.or(Lock::Holds); }
    for to in known.resolved.iter() { reaches.callees.insert(to.to_owned()); }
    if with_fields { for field in known.fields_called.iter() { reaches.callees.insert(format!("{}{}", FIELD, field)); } }
}

fn rules_reaches(def: &GrammarDef, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, calls: &collections::BTreeMap<String, BodyCalls>, graph: &mut collections::BTreeMap<String, Reaches>) {
    let named = names.resolve(def.name).to_owned();
    let mut whole = Reaches { itself: Lock::No, callees: collections::BTreeSet::new() };
    for rule in def.rules.iter() {
        for alt in rule.alts.iter() {
            let action = match alt.action.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
            walk_calls(action, names, unaliased, holes_of, &mut whole);
        }
    }
    for rule in def.rules.iter() {
        if !rule.is_entry { continue; }
        let key = format!("{}::{}", named, names.resolve(rule.name));
        let mut reaches = Reaches { itself: whole.itself.clone(), callees: whole.callees.to_owned() };
        resolved_into(*nikaia_std::index::get(&calls, &key), false, &mut reaches);
        graph.insert(key, reaches);
    }
}

fn walk_calls(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, reaches: &mut Reaches) {
    for seen in seen_in(block, names, unaliased, holes_of, &no_root, false) {
        match seen {
            Seen::Call { ref name, .. } => {
                let called = unaliased(name);
                if a_name_in(&called, &MULTI) { reaches.itself = reaches.itself.or(Lock::Holds); }
                reaches.callees.insert(called);
            },
            _ => { },
        }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn no_root(_name: &str) -> i64 { -1 }

fn any_in(names: &collections::BTreeSet<String>, table: &[&str]) -> bool {
    for name in names.iter() { if a_name_in(name, table) { return true; } }
    false
}

fn a_name_in(name: &str, table: &[&str]) -> bool {
    for one in table.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Locking {
    pub functions: collections::BTreeMap<String, Lock>,
    pub fields: collections::BTreeMap<String, Lock>,
}

pub fn locking(itself: &collections::BTreeMap<String, Lock>, callees: &collections::BTreeMap<String, collections::BTreeSet<String>>, declared: &collections::BTreeSet<String>, library: &Ledger, own: &Ledger) -> Locking {
    let mut touches = itself.to_owned();
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in callees.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&touches, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Lock::No);
            if before.holds() { continue; }
            let mut reached = Lock::No;
            for callee in called.iter() { reached = reached.or(theirs_of(&touches, library, declared, callee)); }
            let grown = before.or(reached);
            if grown != before {
                touches.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
    let mut answer = Locking { functions: collections::BTreeMap::new(), fields: collections::BTreeMap::new() };
    for (name, holds) in touches.iter() {
        let holds = *holds;
        if name.starts_with("field:") {
            let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
            let field = slice(&c, 6, c.len() as i64);
            let settled = if published(own, &field) { holds.clone().or(Lock::Undecided) } else { holds.clone() };
            answer.fields.insert(field, settled);
        } else if own.functions.contains_key(name) { answer.functions.insert(name.to_owned(), holds.clone()); }
    }
    answer
}

fn theirs_of(touches: &collections::BTreeMap<String, Lock>, library: &Ledger, declared: &collections::BTreeSet<String>, callee: &str) -> Lock {
    let constructed = format!("{}::new", callee);
    for key in [callee.to_owned(), constructed] {
        let found = match match *nikaia_std::index::get(&touches, &key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => match described(library, &key) { Some(__nikaia_value) => __nikaia_value, None => continue } };
        return found;
    }
    if is_a_variant(declared, callee) { Lock::No } else { Lock::Undecided }
}

fn described(library: &Ledger, key: &str) -> Option<Lock> {
    let contract = match *nikaia_std::index::get(&library.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(contract.touches_a_lock.clone())
}

fn is_a_variant(declared: &collections::BTreeSet<String>, callee: &str) -> bool {
    let mut parts: Vec<String> = vec![];
    for part in callee.split("::") { parts.push(part.to_owned()); }
    if parts.len() < 2 || *nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1)) == "new" { return false; }
    declared.contains(&struct_type(callee))
}

fn published(own: &Ledger, field: &str) -> bool {
    let c: Vec<scalar> = nikaia_std::list::chars(field.chars());
    let dot = find_text(&c, 0, ".");
    if dot < 0 { return false; }
    let owner = slice(&c, 0, dot);
    let name = slice(&c, dot + 1, c.len() as i64);
    let contract = match *nikaia_std::index::get(&own.types, &owner) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !contract.public { return false; }
    for one in contract.fields.iter() { if one.name == name && one.public { return true; } }
    false
}


// --- logic_alethe.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LgPart {
    id: i64,
    positive: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgClause {
    step: String,
    parts: Vec<LgPart>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgProof {
    text: String,
    count: i64,
}

impl LgProof {
    fn assume(&mut self, term: &str) -> String {
        let name = format!("h{}", self.count);
        self.count += 1;
        self.text.push_str(&format!("(assume {} {})\n", name, term));
        name
    }
    fn step(&mut self, body: &str) -> String {
        let name = format!("t{}", self.count);
        self.count += 1;
        self.text.push_str(&format!("(step {} {})\n", name, body));
        name
    }
}

const LG_CHOICES: i64 = 1024;

fn lg_is_literal(arena: &TermArena, part: &LgPart) -> bool {
    match arena.at(part.id) {
        SolverTerm::Le(_, _) => true,
        SolverTerm::Lt(_, _) => true,
        SolverTerm::Ge(_, _) => true,
        SolverTerm::Gt(_, _) => true,
        SolverTerm::Eq(_, _) => part.positive,
        _ => false,
    }
}

fn lg_literal(arena: &TermArena, part: &LgPart) -> String {
    if part.positive { return lg_term(arena, part.id); }
    format!("(not {})", lg_term(arena, part.id))
}

fn lg_negation(literal: &str) -> String {
    if literal.starts_with("(not ") && literal.ends_with(')') {
        let opened: String = nikaia_std::index::or(literal.strip_prefix("(not "), || "").to_owned();
        return nikaia_std::index::or(opened.strip_suffix(')'), || "").to_owned();
    }
    format!("(not {})", literal)
}

fn lg_spaced(lits: &[String]) -> String {
    let mut out: String = String::from("");
    for lit in lits.iter() { out.push_str(&format!(" {}", lit)); }
    out
}

fn lg_has(list: &[String], text: &str) -> bool {
    for one in list.iter() { if one == text { return true; } }
    false
}

fn lg_resolved(arena: &TermArena, proof: &mut LgProof, clause: &LgClause, rest: &[LgPart], tautology: &str, instead: &[LgPart]) -> LgClause {
    let mut parts: Vec<LgPart> = vec![];
    for part in rest.iter() {
        let part = *part;
        parts.push(LgPart { id: part.id, positive: part.positive });
    }
    for part in instead.iter() {
        let part = *part;
        parts.push(LgPart { id: part.id, positive: part.positive });
    }
    let mut text: Vec<String> = vec![];
    for part in parts.iter() {
        let part = *part;
        text.push(lg_literal(arena, &part));
    }
    let step = proof.step(&format!("(cl{}) :rule resolution :premises ({} {})", lg_spaced(&text), clause.step, tautology));
    LgClause { step, parts }
}

fn lg_inserted(rest: &[LgPart], at: i64, part: LgPart) -> Vec<LgPart> {
    let mut parts: Vec<LgPart> = vec![];
    let mut place = at;
    if place > rest.len() as i64 { place = rest.len() as i64; }
    let mut index: i64 = 0;
    for one in rest.iter() {
        let one = *one;
        if index == place { parts.push(LgPart { id: part.id, positive: part.positive }); }
        parts.push(LgPart { id: one.id, positive: one.positive });
        index += 1;
    }
    if place >= rest.len() as i64 { parts.push(part); }
    parts
}

fn lg_opened(arena: &mut TermArena, proof: &mut LgProof, clause: &LgClause, at: i64) -> Option<Vec<LgClause>> {
    let id = nikaia_std::index::get(&clause.parts, nikaia_std::index::at(at)).id;
    let positive = nikaia_std::index::get(&clause.parts, nikaia_std::index::at(at)).positive;
    let mut rest: Vec<LgPart> = vec![];
    let mut index: i64 = 0;
    for one in clause.parts.iter() {
        let one = *one;
        if index != at { rest.push(LgPart { id: one.id, positive: one.positive }); }
        index += 1;
    }
    let written = lg_literal(&arena, &LgPart { id, positive });
    let node = arena.at(id);
    let none: Vec<LgPart> = vec![];
    Some(match node {
        SolverTerm::Bool(b) => {
            if b == positive {
                let nothing: Vec<LgClause> = vec![];
                nothing
            } else if positive {
                let tautology = proof.step("(cl (not false)) :rule false");
                vec![lg_resolved(&arena, proof, clause, &rest, &tautology, &none)]
            } else {
                let tautology = proof.step("(cl true) :rule true");
                vec![lg_resolved(&arena, proof, clause, &rest, &tautology, &none)]
            }
        },
        SolverTerm::Not(a) => {
            if positive { vec![LgClause { step: clause.step.to_owned(), parts: lg_inserted(&rest, at, LgPart { id: a, positive: false }) }] } else {
                let tautology = proof.step(&format!("(cl (not {}) {}) :rule not_not", written, lg_term(&arena, a)));
                vec![lg_resolved(&arena, proof, clause, &rest, &tautology, &vec![LgPart { id: a, positive: true }])]
            }
        },
        SolverTerm::And(ref parts) => {
            if positive {
                let mut out: Vec<LgClause> = vec![];
                let mut i = 0;
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    let tautology = proof.step(&format!("(cl (not {}) {}) :rule and_pos :args ({})", written, lg_term(&arena, part), i));
                    out.push(lg_resolved(&arena, proof, clause, &rest, &tautology, &vec![LgPart { id: part, positive: true }]));
                    i += 1;
                }
                out
            } else {
                let mut negations: Vec<String> = vec![];
                let mut instead: Vec<LgPart> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    negations.push(format!("(not {})", lg_term(&arena, part)));
                    instead.push(LgPart { id: part, positive: false });
                }
                let tautology = proof.step(&format!("(cl {}{}) :rule and_neg", lg_term(&arena, id), lg_spaced(&negations)));
                vec![lg_resolved(&arena, proof, clause, &rest, &tautology, &instead)]
            }
        },
        SolverTerm::Or(ref parts) => {
            if positive {
                let mut texts: Vec<String> = vec![];
                let mut instead: Vec<LgPart> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    texts.push(lg_term(&arena, part));
                    instead.push(LgPart { id: part, positive: true });
                }
                let tautology = proof.step(&format!("(cl (not {}){}) :rule or_pos", written, lg_spaced(&texts)));
                vec![lg_resolved(&arena, proof, clause, &rest, &tautology, &instead)]
            } else {
                let mut out: Vec<LgClause> = vec![];
                let mut i = 0;
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    let tautology = proof.step(&format!("(cl {} (not {})) :rule or_neg :args ({})", lg_term(&arena, id), lg_term(&arena, part), i));
                    out.push(lg_resolved(&arena, proof, clause, &rest, &tautology, &vec![LgPart { id: part, positive: false }]));
                    i += 1;
                }
                out
            }
        },
        SolverTerm::Ne(a, b) => {
            let equal = arena.equal(a, b);
            vec![LgClause { step: clause.step.to_owned(), parts: lg_inserted(&rest, at, LgPart { id: equal, positive: !positive }) }]
        },
        SolverTerm::Eq(a, b) => {
            if positive { return None; }
            let a_text = lg_term(&arena, a);
            let b_text = lg_term(&arena, b);
            let total = proof.step(&format!("(cl (or (= {} {}) (not (<= {} {})) (not (<= {} {})))) :rule la_disequality", a_text, b_text, a_text, b_text, b_text, a_text));
            let below = arena.le(a, b);
            let above = arena.le(b, a);
            let split = proof.step(&format!("(cl (= {} {}) (not (<= {} {})) (not (<= {} {}))) :rule or :premises ({})", a_text, b_text, a_text, b_text, b_text, a_text, total));
            vec![lg_resolved(&arena, proof, clause, &rest, &split, &vec![LgPart { id: below, positive: false }, LgPart { id: above, positive: false }])]
        },
        _ => { return None; },
    })
}

fn lg_refutation_of(answer: &LgAnswer) -> Option<LgRefutation> {
    match answer {
        LgAnswer::Proved { certificate } => lg_unsplit(certificate),
        _ => None,
    }
}

fn lg_unsplit(certificate: &LgCertificate) -> Option<LgRefutation> {
    match certificate {
        LgCertificate::Refuted(found) => Some(found.clone()),
        _ => None,
    }
}

fn lg_bound_term(arena: &mut TermArena, lin: &LgLin) -> i64 {
    let mut sum: i64 = -1;
    let mut have = false;
    for (name, k) in lin.terms.iter() {
        let k = nikaia_std::num::value(k);
        let v = arena.var(name);
        let mut part = v;
        if k != 1 {
            let factor = arena.int(k);
            part = arena.mul(factor, v);
        }
        if have { sum = arena.add(sum, part); } else {
            sum = part;
            have = true;
        }
    }
    let constant = arena.int(lin.constant);
    let mut whole = constant;
    if have {
        whole = sum;
        if lin.constant != 0 { whole = arena.add(sum, constant); }
    }
    let zero = arena.int(0);
    arena.le(whole, zero)
}

fn lg_alethe_number(n: i64) -> String {
    if n < 0 { return lg_smt_int(n); }
    format!("{}", n)
}

fn lg_atom(lin: &LgLin) -> String {
    let mut items: Vec<String> = vec![];
    for (name, k) in lin.terms.iter() {
        let k = nikaia_std::num::value(k);
        if k == 1 { items.push(lg_symbol(name)); } else { items.push(format!("(* {} {})", lg_alethe_number(k), lg_symbol(name))); }
    }
    if lin.constant != 0 || items.is_empty() { items.push(lg_alethe_number(lin.constant)); }
    if items.len() == 1 { return format!("(<= {} 0)", *nikaia_std::index::get(&items, 0)); }
    format!("(<= (+ {}) 0)", items.join(" "))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgBelow {
    step: String,
    lits: Vec<String>,
}

fn lg_choice(arena: &mut TermArena, proof: &mut LgProof, chosen: &[LgPart]) -> Option<LgBelow> {
    let mut facts: Vec<i64> = vec![];
    let mut seen: Vec<String> = vec![];
    for part in chosen.iter() {
        let part = *part;
        let text = lg_literal(&arena, &part);
        if lg_has(&seen, &text) { continue; }
        seen.push(text);
        if part.positive { facts.push(part.id); } else { facts.push(arena.not(part.id)); }
    }
    let falsum = arena.boolean(false);
    let answer = lg_check(&arena, &facts, falsum, &lg_budget());
    let refutation = lg_refutation_of(&answer);
    let mut why = lg_why();
    let read = lg_indexed(&arena, &facts, falsum, &mut why);
    if read.is_none() || refutation.is_none() { return None; }
    let indexed = match read { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !indexed.ors.is_empty() { return None; }
    let steps = match refutation { Some(__nikaia_value) => __nikaia_value, None => return None }.steps.to_owned();
    let bounds = indexed.atoms.to_owned();
    let mut source_text: Vec<String> = vec![];
    let mut source_weight: Vec<i64> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let mut id = fact;
        let mut positive = true;
        match arena.at(fact) {
            SolverTerm::Not(inner) => {
                id = inner;
                positive = false;
            },
            _ => { },
        }
        let negation = lg_negation(&lg_literal(&arena, &LgPart { id, positive }));
        let mut equal = false;
        match arena.at(id) {
            SolverTerm::Eq(_, _) => { equal = true; },
            _ => { },
        }
        if equal && positive {
            source_text.push(negation.to_owned());
            source_weight.push(-1);
            source_text.push(negation);
            source_weight.push(1);
        } else {
            source_text.push(negation);
            source_weight.push(1);
        }
    }
    if (source_text.len() as i64) != bounds.len() as i64 { return None; }
    let mut lemmas: Vec<String> = vec![];
    let mut used: Vec<String> = vec![];
    let mut made_lin: Vec<LgLin> = vec![];
    let mut made_atom: Vec<String> = vec![];
    for step in steps.iter() {
        let step = *step;
        let made = match lg_lemma_of(&step, &bounds, &source_text, &source_weight, &made_lin, &made_atom, &mut used) { Some(__nikaia_value) => __nikaia_value, None => return None };
        lemmas.push(proof.step(&made.lemma));
        made_atom.push(lg_atom(&made.bound));
        made_lin.push(made.bound.clone());
    }
    if made_lin.is_empty() { return None; }
    let last = (*nikaia_std::index::get(&made_lin, nikaia_std::index::at(made_lin.len() as i64 - 1))).clone();
    let last_atom = (*nikaia_std::index::get(&made_atom, nikaia_std::index::at(made_atom.len() as i64 - 1))).to_owned();
    if !last.terms.is_empty() || last.constant <= 0 { return None; }
    lemmas.push(proof.step(&format!("(cl (not {})) :rule la_generic :args (1)", last_atom)));
    let step = proof.step(&format!("(cl{}) :rule resolution :premises ({})", lg_spaced(&used), lemmas.join(" ")));
    Some(LgBelow { step, lits: used })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgMade {
    bound: LgLin,
    lemma: String,
}

fn lg_lemma_of(step: &LgStep, bounds: &[LgLin], source_text: &[String], source_weight: &[i64], made_lin: &[LgLin], made_atom: &[String], used: &mut Vec<String>) -> Option<LgMade> {
    Some(match step.clone() {
        LgStep::Hypothesis(i) => {
            if i < 0 || i >= bounds.len() as i64 { return None; }
            let bound = (*nikaia_std::index::get(&bounds, nikaia_std::index::at(i))).clone();
            let negation = (*nikaia_std::index::get(&source_text, nikaia_std::index::at(i))).to_owned();
            let weight = *nikaia_std::index::get(&source_weight, nikaia_std::index::at(i));
            if !lg_has(&used, &negation) { used.push(negation.to_owned()); }
            LgMade { bound: bound.clone(), lemma: format!("(cl {} {}) :rule la_generic :args ({} 1)", negation, lg_atom(&bound), weight) }
        },
        LgStep::Tighten(from) => {
            if from < 0 || from >= made_lin.len() as i64 { return None; }
            let before = (*nikaia_std::index::get(&made_lin, nikaia_std::index::at(from))).clone();
            let before_atom = (*nikaia_std::index::get(&made_atom, nikaia_std::index::at(from))).to_owned();
            let mut factor: i64 = 0;
            for (_, k) in before.terms.iter() {
                let k = nikaia_std::num::value(k);
                factor = lg_gcd(factor, k.abs());
            }
            let bound = lg_tightened(&before);
            LgMade { bound: bound.clone(), lemma: format!("(cl (not {}) {}) :rule la_generic :args (1 {})", before_atom, lg_atom(&bound), factor) }
        },
        LgStep::Combine { left, by_left, right, by_right } => {
            if left < 0 || left >= made_lin.len() as i64 || right < 0 || right >= made_lin.len() as i64 { return None; }
            let l = (*nikaia_std::index::get(&made_lin, nikaia_std::index::at(left))).clone();
            let l_atom = (*nikaia_std::index::get(&made_atom, nikaia_std::index::at(left))).to_owned();
            let r = (*nikaia_std::index::get(&made_lin, nikaia_std::index::at(right))).clone();
            let r_atom = (*nikaia_std::index::get(&made_atom, nikaia_std::index::at(right))).to_owned();
            let scaled_left = match lg_scale(&l, by_left) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let scaled_right = match lg_scale(&r, by_right) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let bound = match lg_add(&scaled_left, &scaled_right) { Some(__nikaia_value) => __nikaia_value, None => return None };
            LgMade { bound: bound.clone(), lemma: format!("(cl (not {}) (not {}) {}) :rule la_generic :args ({} {} 1)", l_atom, r_atom, lg_atom(&bound), by_left, by_right) }
        },
    })
}

fn lg_hulled(arena: &mut TermArena, proof: &mut LgProof, clause: &LgClause) -> Vec<LgClause> {
    let mut parts: Vec<i64> = vec![];
    for part in clause.parts.iter() {
        let part = *part;
        if part.positive { parts.push(part.id); } else { parts.push(arena.not(part.id)); }
    }
    let either = arena.or(parts);
    let falsum = arena.boolean(false);
    let facts: Vec<i64> = vec![either];
    let mut why = lg_why();
    let read = lg_indexed(&arena, &facts, falsum, &mut why);
    let mut out: Vec<LgClause> = vec![];
    if read.is_none() { return out; }
    let indexed = match read { Some(__nikaia_value) => __nikaia_value, None => return out };
    let mut bounds: Vec<LgLin> = vec![];
    for item in indexed.top.iter() {
        let item = *item;
        if item.atom { bounds.push((*nikaia_std::index::get(&indexed.atoms, nikaia_std::index::at(item.n))).clone()); }
    }
    for bound in bounds.iter() {
        let hull = lg_bound_term(arena, bound);
        let mut lemmas: Vec<String> = vec![];
        let mut lits: Vec<String> = vec![];
        let mut complete = true;
        for part in clause.parts.iter() {
            let part = *part;
            let found = lg_choice(arena, proof, &vec![LgPart { id: part.id, positive: part.positive }, LgPart { id: hull, positive: false }]);
            if found.is_none() {
                complete = false;
                break;
            }
            let below = match found { Some(__nikaia_value) => __nikaia_value, None => return out };
            let pivot = lg_negation(&lg_literal(&arena, &part));
            for lit in below.lits.iter() { if *lit != pivot && !lg_has(&lits, lit) { lits.push(lit.to_owned()); } }
            lemmas.push(below.step.to_owned());
        }
        if !complete { continue; }
        if (lemmas.len() as i64) != clause.parts.len() as i64 { continue; }
        let mut premises: Vec<String> = vec![clause.step.to_owned()];
        for lemma in lemmas.iter() { premises.push(lemma.to_owned()); }
        let step = proof.step(&format!("(cl{}) :rule resolution :premises ({})", lg_spaced(&lits), premises.join(" ")));
        if lits.len() == 1 && *nikaia_std::index::get(&lits, 0) == lg_term(&arena, hull) { out.push(LgClause { step, parts: vec![LgPart { id: hull, positive: true }] }); }
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgSearch {
    arena: TermArena,
    proof: LgProof,
    clauses: Vec<LgClause>,
    work: i64,
}

fn lg_below(search: &mut LgSearch, depth: i64, chosen: &mut Vec<LgPart>) -> Option<LgBelow> {
    search.work += 1;
    if search.work > LG_CHOICES { return None; }
    let refuted = lg_choice(&mut search.arena, &mut search.proof, &chosen);
    if refuted.is_some() { return std::convert::identity(refuted); }
    if depth >= search.clauses.len() as i64 { return None; }
    let clause = LgClause { step: nikaia_std::index::get(&search.clauses, nikaia_std::index::at(depth)).step.to_owned(), parts: nikaia_std::index::get(&search.clauses, nikaia_std::index::at(depth)).parts.to_owned() };
    let mut steps: Vec<String> = vec![];
    let mut all_lits: Vec<Vec<String>> = vec![];
    for part in clause.parts.iter() {
        let part = *part;
        chosen.push(LgPart { id: part.id, positive: part.positive });
        let found = lg_below(search, depth + 1, chosen);
        chosen.pop();
        let here = match found { Some(__nikaia_value) => __nikaia_value, None => return None };
        let pivot = lg_negation(&lg_literal(&search.arena, &part));
        if !lg_has(&here.lits, &pivot) { return Some(here); }
        steps.push(here.step.to_owned());
        all_lits.push(here.lits.to_owned());
    }
    let mut lits: Vec<String> = vec![];
    let mut at: i64 = 0;
    for part in clause.parts.iter() {
        let part = *part;
        let pivot = lg_negation(&lg_literal(&search.arena, &part));
        for lit in (*nikaia_std::index::get(&all_lits, (at) as usize)).iter() { if *lit != pivot && !lg_has(&lits, lit) { lits.push(lit.to_owned()); } }
        at += 1;
    }
    let mut premises: Vec<String> = vec![clause.step.to_owned()];
    for one in steps.iter() { premises.push(one.to_owned()); }
    let step = search.proof.step(&format!("(cl{}) :rule resolution :premises ({})", lg_spaced(&lits), premises.join(" ")));
    Some(LgBelow { step, lits })
}

pub fn lg_alethe_write(source: &TermArena, facts: &[i64], goal: i64) -> Option<String> {
    let mut arena = TermArena { nodes: source.nodes.to_owned() };
    let mut proof = LgProof { text: String::from(""), count: 0 };
    let mut pending: Vec<LgClause> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let step = proof.assume(&lg_term(&arena, fact));
        pending.push(LgClause { step, parts: vec![LgPart { id: fact, positive: true }] });
    }
    let step = proof.assume(&format!("(not {})", lg_term(&arena, goal)));
    pending.push(LgClause { step, parts: vec![LgPart { id: goal, positive: false }] });
    let mut clauses: Vec<LgClause> = vec![];
    while !pending.is_empty() {
        let clause = (*nikaia_std::index::get(&pending, nikaia_std::index::at(pending.len() as i64 - 1))).clone();
        pending.pop();
        let mut open: i64 = -1;
        let mut index: i64 = 0;
        for part in clause.parts.iter() {
            let part = *part;
            if open < 0 && !lg_is_literal(&arena, &part) { open = index; }
            index += 1;
        }
        if open < 0 { clauses.push(clause); } else {
            let more = match lg_opened(&mut arena, &mut proof, &clause, open) { Some(__nikaia_value) => __nikaia_value, None => return None };
            for one in more.iter() { pending.push(one.clone()); }
        }
    }
    for clause in clauses.iter() { if clause.parts.is_empty() { return Some(proof.text.to_owned()); } }
    let mut reversed: Vec<LgClause> = vec![];
    let mut back = clauses.len() as i64;
    while back > 0 {
        back -= 1;
        reversed.push((*nikaia_std::index::get(&clauses, nikaia_std::index::at(back))).clone());
    }
    let mut hulls: Vec<LgClause> = vec![];
    for clause in reversed.iter() { if clause.parts.len() > 1 { hulls.extend(lg_hulled(&mut arena, &mut proof, clause)); } }
    for hull in hulls.iter() { reversed.push(hull.clone()); }
    let mut ordered: Vec<LgClause> = vec![];
    for clause in reversed.iter() {
        let mut at = ordered.len() as i64;
        while at > 0 && (clause.parts.len() as i64) < nikaia_std::index::get(&ordered, nikaia_std::index::at(at - 1)).parts.len() as i64 { at -= 1; }
        ordered.insert(nikaia_std::count::of(at), clause.clone());
    }
    let mut search = LgSearch { arena, proof, clauses: ordered, work: 0 };
    let mut none: Vec<LgPart> = vec![];
    let last = match lg_below(&mut search, 0, &mut none) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if last.lits.is_empty() { return Some(search.proof.text.to_owned()); }
    None
}


