#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LgUnknown {
    OutsideTheTheory,
    Overflow,
    TooManyCases,
    TooManyBounds,
    NoContradiction,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgWhy {
    pub unknown: LgUnknown,
    pub quotients: Vec<i64>,
}

pub fn lg_why() -> LgWhy { LgWhy { unknown: LgUnknown::NoContradiction, quotients: vec![] } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LgBudget {
    pub cases: i64,
    pub bounds: i64,
}

pub fn lg_budget() -> LgBudget { LgBudget { cases: 1024, bounds: 4096 } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LgStep {
    Hypothesis(i64),
    Tighten(i64),
    Combine { left: i64, by_left: i64, right: i64, by_right: i64 },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgRefutation {
    pub steps: Vec<LgStep>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LgCertificate {
    Refuted(LgRefutation),
    Split { disjunction: i64, cases: Vec<LgCertificate> },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgModel {
    pub values: collections::BTreeMap<String, i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LgAnswer {
    Proved { certificate: LgCertificate },
    Refuted { model: LgModel },
    Unknown { why: LgUnknown },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LgRejected {
    NotReadable,
    NotOpen { disjunction: i64 },
    Cases { expected: i64, found: i64 },
    Reference { case: i64, step: i64 },
    Multiplier { case: i64, step: i64 },
    Overflow { case: i64, step: i64 },
    NotAContradiction { case: i64 },
}

impl LgRejected {
    pub fn debug(&self) -> String {
        match self {
            LgRejected::NotReadable => String::from("NotReadable"),
            LgRejected::NotOpen { disjunction } => { let disjunction = *disjunction; format!("NotOpen {{ disjunction: {} }}", disjunction) },
            LgRejected::Cases { expected, found } => { let expected = *expected; let found = *found; format!("Cases {{ expected: {}, found: {} }}", expected, found) },
            LgRejected::Reference { case, step } => { let case = *case; let step = *step; format!("Reference {{ case: {}, step: {} }}", case, step) },
            LgRejected::Multiplier { case, step } => { let case = *case; let step = *step; format!("Multiplier {{ case: {}, step: {} }}", case, step) },
            LgRejected::Overflow { case, step } => { let case = *case; let step = *step; format!("Overflow {{ case: {}, step: {} }}", case, step) },
            LgRejected::NotAContradiction { case } => { let case = *case; format!("NotAContradiction {{ case: {} }}", case) },
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgLin {
    pub terms: collections::BTreeMap<String, i64>,
    pub constant: i64,
}

fn lg_constant(c: i64) -> LgLin { LgLin { terms: collections::BTreeMap::new(), constant: c } }

fn lg_variable(name: &str) -> LgLin {
    let mut terms: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    terms.insert(name.to_owned(), 1);
    LgLin { terms, constant: 0 }
}

pub fn lg_add(a: &LgLin, b: &LgLin) -> Option<LgLin> {
    let mut terms = a.terms.to_owned();
    for (name, k) in b.terms.iter() {
        let k = nikaia_std::num::value(k);
        let before = nikaia_std::index::or(terms.get(name), || 0);
        let sum = match before.checked_add(k) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if sum == 0 { terms.remove(name); } else { terms.insert(name.to_owned(), sum); }
    }
    let constant = match a.constant.checked_add(b.constant) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LgLin { terms, constant })
}

pub fn lg_scale(a: &LgLin, k: i64) -> Option<LgLin> {
    if k == 0 { return Some(lg_constant(0)); }
    let mut terms: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (name, c) in a.terms.iter() {
        let c = nikaia_std::num::value(c);
        terms.insert(name.to_owned(), match c.checked_mul(k) { Some(__nikaia_value) => __nikaia_value, None => return None });
    }
    let constant = match a.constant.checked_mul(k) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LgLin { terms, constant })
}

fn lg_sub(a: &LgLin, b: &LgLin) -> Option<LgLin> {
    let negated = match lg_scale(b, -1) { Some(__nikaia_value) => __nikaia_value, None => return None };
    lg_add(a, &negated)
}

fn lg_add_constant(a: &LgLin, c: i64) -> LgLin { LgLin { terms: a.terms.to_owned(), constant: a.constant.saturating_add(c) } }

fn lg_gcd(a: i64, b: i64) -> i64 {
    if b == 0 { return a; }
    lg_gcd(b, a % b)
}

pub fn lg_tightened(a: &LgLin) -> LgLin {
    let mut g: i64 = 0;
    for (_, k) in a.terms.iter() {
        let k = nikaia_std::num::value(k);
        g = lg_gcd(g, k.abs());
    }
    if g <= 1 { return LgLin { terms: a.terms.to_owned(), constant: a.constant }; }
    let mut terms: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (name, k) in a.terms.iter() {
        let k = nikaia_std::num::value(k);
        terms.insert(name.to_owned(), k / g);
    }
    let mut constant = a.constant.div_euclid(g);
    if a.constant.rem_euclid(g) != 0 { constant += 1; }
    LgLin { terms, constant }
}

pub fn lg_terms_cmp(a: &collections::BTreeMap<String, i64>, b: &collections::BTreeMap<String, i64>) -> i64 {
    let mut left_names: Vec<&str> = vec![];
    let mut left_ks: Vec<i64> = vec![];
    for (name, k) in a.iter() {
        let k = nikaia_std::num::value(k);
        left_names.push(name);
        left_ks.push(k);
    }
    let mut right_names: Vec<&str> = vec![];
    let mut right_ks: Vec<i64> = vec![];
    for (name, k) in b.iter() {
        let k = nikaia_std::num::value(k);
        right_names.push(name);
        right_ks.push(k);
    }
    let mut at: i64 = 0;
    while ((at) as usize) < left_ks.len() && ((at) as usize) < right_ks.len() {
        if AsRef::<str>::as_ref(&(*nikaia_std::index::get(&left_names, (at) as usize))) < AsRef::<str>::as_ref(&(*nikaia_std::index::get(&right_names, (at) as usize))) { return -1; }
        if AsRef::<str>::as_ref(&(*nikaia_std::index::get(&right_names, (at) as usize))) < AsRef::<str>::as_ref(&(*nikaia_std::index::get(&left_names, (at) as usize))) { return 1; }
        if *nikaia_std::index::get(&left_ks, (at) as usize) < *nikaia_std::index::get(&right_ks, (at) as usize) { return -1; }
        if *nikaia_std::index::get(&right_ks, (at) as usize) < *nikaia_std::index::get(&left_ks, (at) as usize) { return 1; }
        at += 1;
    }
    if (left_ks.len() as i64) < right_ks.len() as i64 { return -1; }
    if (left_ks.len() as i64) > right_ks.len() as i64 { return 1; }
    0
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgFormula {
    True,
    False,
    Le(LgLin),
    And(Vec<LgFormula>),
    Or(Vec<LgFormula>),
}

fn lg_linear(arena: &TermArena, id: i64, why: &mut LgWhy) -> Option<LgLin> {
    let node = arena.at(id);
    match node {
        SolverTerm::Int(n) => Some(lg_constant(n)),
        SolverTerm::Var(ref name) => Some(lg_variable(name)),
        SolverTerm::Add(a, b) => {
            let x = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match lg_linear(arena, b, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            lg_overflowed(lg_add(&x, &y), why)
        },
        SolverTerm::Sub(a, b) => {
            let x = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match lg_linear(arena, b, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            lg_overflowed(lg_sub(&x, &y), why)
        },
        SolverTerm::Neg(a) => {
            let x = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            lg_overflowed(lg_scale(&x, -1), why)
        },
        SolverTerm::Mul(a, b) => {
            let l = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let r = match lg_linear(arena, b, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if l.terms.is_empty() { lg_overflowed(lg_scale(&r, l.constant), why) } else if r.terms.is_empty() { lg_overflowed(lg_scale(&l, r.constant), why) } else {
                why.unknown = LgUnknown::OutsideTheTheory;
                None
            }
        },
        SolverTerm::Quot(a, k) => {
            if k <= 0 {
                why.unknown = LgUnknown::OutsideTheTheory;
                return None;
            }
            if !why.quotients.contains(&id) { why.quotients.push(id); }
            Some(lg_variable(&lg_quotient_name(id)))
        },
        _ => {
            why.unknown = LgUnknown::OutsideTheTheory;
            None
        },
    }
}

fn lg_overflowed(made: Option<LgLin>, why: &mut LgWhy) -> Option<LgLin> {
    if made.is_none() { why.unknown = LgUnknown::Overflow; }
    made
}

fn lg_compare(arena: &TermArena, a: i64, b: i64, op: i64, holds: bool, why: &mut LgWhy) -> Option<LgFormula> {
    let mut kind = op;
    if !holds { kind = lg_negated(op); }
    let x = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let y = match lg_linear(arena, b, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let a_minus_b = match lg_overflowed(lg_sub(&x, &y), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let b_minus_a = match lg_overflowed(lg_sub(&y, &x), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if kind == 0 { return Some(LgFormula::Le(lg_add_constant(&a_minus_b, 1))); }
    if kind == 1 { return Some(LgFormula::Le(a_minus_b)); }
    if kind == 2 { return Some(LgFormula::Le(lg_add_constant(&b_minus_a, 1))); }
    if kind == 3 { return Some(LgFormula::Le(b_minus_a)); }
    if kind == 4 { return Some(LgFormula::And(vec![LgFormula::Le(a_minus_b), LgFormula::Le(b_minus_a)])); }
    Some(LgFormula::Or(vec![LgFormula::Le(lg_add_constant(&a_minus_b, 1)), LgFormula::Le(lg_add_constant(&b_minus_a, 1))]))
}

fn lg_negated(op: i64) -> i64 {
    if op == 0 { return 3; }
    if op == 1 { return 2; }
    if op == 2 { return 1; }
    if op == 3 { return 0; }
    if op == 4 { return 5; }
    4
}

fn lg_formula(arena: &TermArena, id: i64, holds: bool, why: &mut LgWhy) -> Option<LgFormula> {
    let node = arena.at(id);
    match node {
        SolverTerm::Bool(b) => { if b == holds { Some(LgFormula::True) } else { Some(LgFormula::False) } },
        SolverTerm::Not(a) => lg_formula(arena, a, !holds, why),
        SolverTerm::And(ref parts) => lg_junction(arena, parts, holds, holds, why),
        SolverTerm::Or(ref parts) => lg_junction(arena, parts, holds, !holds, why),
        SolverTerm::Le(a, b) => lg_compare(arena, a, b, 1, holds, why),
        SolverTerm::Lt(a, b) => lg_compare(arena, a, b, 0, holds, why),
        SolverTerm::Ge(a, b) => lg_compare(arena, a, b, 3, holds, why),
        SolverTerm::Gt(a, b) => lg_compare(arena, a, b, 2, holds, why),
        SolverTerm::Eq(a, b) => lg_compare(arena, a, b, 4, holds, why),
        SolverTerm::Ne(a, b) => lg_compare(arena, a, b, 5, holds, why),
        _ => {
            why.unknown = LgUnknown::OutsideTheTheory;
            None
        },
    }
}

fn lg_junction(arena: &TermArena, parts: &[i64], holds: bool, conjunction: bool, why: &mut LgWhy) -> Option<LgFormula> {
    let mut made: Vec<LgFormula> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        made.push(match lg_formula(arena, part, holds, why) { Some(__nikaia_value) => __nikaia_value, None => return None });
    }
    if conjunction { return Some(LgFormula::And(made)); }
    Some(LgFormula::Or(made))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LgItem {
    pub atom: bool,
    pub n: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgIndexed {
    pub atoms: Vec<LgLin>,
    pub ors: Vec<Vec<Vec<LgItem>>>,
    pub top: Vec<LgItem>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgForm {
    terms: collections::BTreeMap<String, i64>,
    constant: i64,
}

impl LgIndexed {
    fn atom(&mut self, lin: LgLin) -> Vec<LgItem> {
        self.atoms.push(lin);
        vec![LgItem { atom: true, n: self.atoms.len() as i64 - 1 }]
    }
    fn strongest(&self, alternative: &[LgItem]) -> Vec<LgForm> {
        let mut by_form: Vec<LgForm> = vec![];
        for item in alternative.iter() {
            let item = *item;
            if !item.atom { continue; }
            let atom = (*nikaia_std::index::get(&self.atoms, nikaia_std::index::at(item.n))).clone();
            let mut at: i64 = 0;
            let mut placed = false;
            while at < by_form.len() as i64 {
                let order = lg_terms_cmp(&atom.terms, &nikaia_std::index::get(&by_form, nikaia_std::index::at(at)).terms);
                if order == 0 {
                    if atom.constant > nikaia_std::index::get(&by_form, nikaia_std::index::at(at)).constant { by_form[nikaia_std::index::at(at)].constant = atom.constant; }
                    placed = true;
                    break;
                }
                if order < 0 { break; }
                at += 1;
            }
            if !placed { by_form.insert(nikaia_std::count::of(at), LgForm { terms: atom.terms.to_owned(), constant: atom.constant }); }
        }
        by_form
    }
    fn hull(&self, alternatives: &[Vec<LgItem>]) -> Vec<LgLin> {
        let mut common: Vec<LgForm> = vec![];
        let mut first = true;
        for alternative in alternatives.iter() {
            let each = self.strongest(alternative);
            if first {
                common = each;
                first = false;
                continue;
            }
            let mut kept: Vec<LgForm> = vec![];
            for form in common.iter() {
                for other in each.iter() {
                    if lg_terms_cmp(&form.terms, &other.terms) == 0 {
                        let mut c = form.constant;
                        if other.constant < c { c = other.constant; }
                        kept.push(LgForm { terms: form.terms.to_owned(), constant: c });
                        break;
                    }
                }
            }
            common = kept;
        }
        let mut out: Vec<LgLin> = vec![];
        for form in common.iter() { if !form.terms.is_empty() { out.push(LgLin { terms: form.terms.to_owned(), constant: form.constant }); } }
        out
    }
    fn items(&mut self, formula: &LgFormula) -> Vec<LgItem> {
        match formula {
            LgFormula::True => vec![],
            LgFormula::False => self.atom(lg_constant(1)),
            LgFormula::Le(lin) => self.atom(lin.clone()),
            LgFormula::And(parts) => {
                let mut out: Vec<LgItem> = vec![];
                for part in parts.iter() { out.extend(self.items(part)); }
                out
            },
            LgFormula::Or(parts) => self.items_of_or(parts),
        }
    }
    fn items_of_or(&mut self, parts: &[LgFormula]) -> Vec<LgItem> {
        let at = self.ors.len() as i64;
        let empty: Vec<Vec<LgItem>> = vec![];
        self.ors.push(empty);
        let mut alternatives: Vec<Vec<LgItem>> = vec![];
        for part in parts.iter() { alternatives.push(self.items(part)); }
        if alternatives.is_empty() { return self.atom(lg_constant(1)); }
        if alternatives.len() == 1 { return (*nikaia_std::index::get(&alternatives, 0)).to_owned(); }
        for alternative in alternatives.iter() { if alternative.is_empty() { return vec![]; } }
        let mut items: Vec<LgItem> = vec![LgItem { atom: false, n: at }];
        for hull in self.hull(&alternatives) { items.extend(self.atom(hull)); }
        { let __nikaia_stored = alternatives.to_owned(); nikaia_std::index::set(&mut self.ors, nikaia_std::index::at(at), __nikaia_stored); }
        items
    }
}

pub fn lg_indexed(arena: &TermArena, facts: &[i64], goal: i64, why: &mut LgWhy) -> Option<LgIndexed> {
    let mut all: Vec<LgFormula> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        all.push(match lg_formula(arena, fact, true, why) { Some(__nikaia_value) => __nikaia_value, None => return None });
    }
    all.push(match lg_formula(arena, goal, false, why) { Some(__nikaia_value) => __nikaia_value, None => return None });
    let mut at: i64 = 0;
    while ((at) as usize) < why.quotients.len() {
        all.push(match lg_quotient(arena, *nikaia_std::index::get(&why.quotients, (at) as usize), why) { Some(__nikaia_value) => __nikaia_value, None => return None });
        at += 1;
    }
    let mut indexed = LgIndexed { atoms: vec![], ors: vec![], top: vec![] };
    let whole = LgFormula::And(all);
    indexed.top = indexed.items(&whole);
    Some(indexed)
}

fn lg_quotient_name(id: i64) -> String { format!("quot#{}", id) }

fn lg_quotient(arena: &TermArena, id: i64, why: &mut LgWhy) -> Option<LgFormula> {
    match arena.at(id) {
        SolverTerm::Quot(a, k) => lg_quotient_of(arena, id, a, k, why),
        _ => None,
    }
}

fn lg_quotient_of(arena: &TermArena, id: i64, a: i64, k: i64, why: &mut LgWhy) -> Option<LgFormula> {
    let e = match lg_linear(arena, a, why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let kq = match lg_overflowed(lg_scale(&lg_variable(&lg_quotient_name(id)), k), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let e_minus_kq = match lg_overflowed(lg_sub(&e, &kq), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let kq_minus_e = match lg_overflowed(lg_sub(&kq, &e), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let negative = lg_add_constant(&e, 1);
    let not_negative = match lg_overflowed(lg_scale(&e, -1), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let below = match lg_overflowed(lg_add_constant_checked(&e_minus_kq, 1 - k), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let above = match lg_overflowed(lg_add_constant_checked(&kq_minus_e, 1 - k), why) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let upwards = LgFormula::Or(vec![LgFormula::Le(negative), LgFormula::And(vec![LgFormula::Le(kq_minus_e.clone()), LgFormula::Le(below)])]);
    let downwards = LgFormula::Or(vec![LgFormula::Le(not_negative), LgFormula::And(vec![LgFormula::Le(e_minus_kq.clone()), LgFormula::Le(above)])]);
    Some(LgFormula::And(vec![upwards, downwards]))
}

fn lg_add_constant_checked(a: &LgLin, c: i64) -> Option<LgLin> {
    let sum = match a.constant.checked_add(c) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LgLin { terms: a.terms.to_owned(), constant: sum })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgHeld {
    lin: LgLin,
    step: i64,
    form: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgClosed {
    Refuted(LgRefutation),
    Consistent { found: bool, values: collections::BTreeMap<String, i64> },
    Unknown(LgUnknown),
}

fn lg_tighten_step(bound: &LgLin, steps: &mut Vec<LgStep>, ranks: &collections::BTreeMap<String, i64>) -> LgHeld {
    let made = steps.len() as i64 - 1;
    let mut g: i64 = 0;
    for (_, k) in bound.terms.iter() {
        let k = nikaia_std::num::value(k);
        g = lg_gcd(g, k.abs());
    }
    if g <= 1 { return LgHeld { lin: bound.clone(), step: made, form: lg_form_of(&bound.terms, ranks) }; }
    let tight = lg_tightened(bound);
    let form = lg_form_of(&tight.terms, ranks);
    steps.push(LgStep::Tighten(made));
    LgHeld { lin: tight, step: steps.len() as i64 - 1, form }
}

fn lg_form_of(terms: &collections::BTreeMap<String, i64>, ranks: &collections::BTreeMap<String, i64>) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    for (name, k) in terms.iter() {
        let k = nikaia_std::num::value(k);
        out.push(nikaia_std::index::or(ranks.get(name), || -1));
        out.push(k);
    }
    out
}

fn lg_form_cmp(a: &[i64], b: &[i64]) -> i64 {
    let mut at: i64 = 0;
    while ((at) as usize) < a.len() && ((at) as usize) < b.len() {
        if *nikaia_std::index::get(&a, (at) as usize) < *nikaia_std::index::get(&b, (at) as usize) { return -1; }
        if *nikaia_std::index::get(&b, (at) as usize) < *nikaia_std::index::get(&a, (at) as usize) { return 1; }
        at += 1;
    }
    if (a.len() as i64) < b.len() as i64 { return -1; }
    if (b.len() as i64) < a.len() as i64 { return 1; }
    0
}

fn lg_place_before(held: &[LgHeld], b: i64, a: i64) -> bool {
    let order = lg_form_cmp(&nikaia_std::index::get(&held, nikaia_std::index::at(b)).form, &nikaia_std::index::get(&held, nikaia_std::index::at(a)).form);
    if order != 0 { return order < 0; }
    nikaia_std::index::get(&held, nikaia_std::index::at(a)).lin.constant < nikaia_std::index::get(&held, nikaia_std::index::at(b)).lin.constant
}

fn lg_sorted_places(held: &[LgHeld], places: &[i64]) -> Vec<i64> {
    let mut out = places.to_owned();
    let mut i: i64 = 1;
    while ((i) as usize) < out.len() {
        let x = *nikaia_std::index::get(&out, (i) as usize);
        let mut j: i64 = i;
        while j > 0 && lg_place_before(held, x, *nikaia_std::index::get(&out, nikaia_std::index::at(j - 1))) {
            { let __nikaia_stored = *nikaia_std::index::get(&out, nikaia_std::index::at(j - 1)); nikaia_std::index::set(&mut out, nikaia_std::index::at(j), __nikaia_stored); }
            j -= 1;
        }
        { let __nikaia_stored = x; nikaia_std::index::set(&mut out, nikaia_std::index::at(j), __nikaia_stored); }
        i += 1;
    }
    out
}

fn lg_contradictory(bounds: &[LgLin], budget: &LgBudget) -> LgClosed {
    let mut steps: Vec<LgStep> = vec![];
    let mut round_names: Vec<String> = vec![];
    let mut round_places: Vec<Vec<i64>> = vec![];
    let mut held: Vec<LgHeld> = vec![];
    let mut alive: Vec<i64> = vec![];
    let mut every: collections::BTreeSet<String> = collections::BTreeSet::new();
    for bound in bounds.iter() { for (name, _) in bound.terms.iter() { every.insert(name.to_owned()); } }
    let mut ranks: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut rank_names: Vec<String> = vec![];
    let mut quotients: Vec<bool> = vec![];
    for name in every.iter() {
        ranks.insert(name.to_owned(), ranks.len() as i64);
        rank_names.push(name.to_owned());
        quotients.push(name.starts_with("quot#"));
    }
    let mut present: Vec<bool> = vec![];
    let mut ups: Vec<i64> = vec![];
    let mut downs: Vec<i64> = vec![];
    for _ in quotients.iter() {
        present.push(false);
        ups.push(0);
        downs.push(0);
    }
    let mut index = 0;
    for bound in bounds.iter() {
        steps.push(LgStep::Hypothesis(index));
        alive.push(held.len() as i64);
        held.push(lg_tighten_step(bound, &mut steps, &ranks));
        index += 1;
    }
    loop {
        for place in alive.iter() {
            let place = nikaia_std::num::value(place);
            if nikaia_std::index::get(&held, nikaia_std::index::at(place)).lin.terms.is_empty() && nikaia_std::index::get(&held, nikaia_std::index::at(place)).lin.constant > 0 { return LgClosed::Refuted(lg_traced(&steps, nikaia_std::index::get(&held, nikaia_std::index::at(place)).step)); }
        }
        let mut live: Vec<i64> = vec![];
        for place in alive.iter() {
            let place = nikaia_std::num::value(place);
            if !nikaia_std::index::get(&held, nikaia_std::index::at(place)).lin.terms.is_empty() { live.push(place); }
        }
        let ordered = lg_sorted_places(&held, &live);
        let mut now: Vec<i64> = vec![];
        let mut kept: i64 = -1;
        for place in ordered.iter() {
            let place = nikaia_std::num::value(place);
            if kept >= 0 && lg_form_cmp(&nikaia_std::index::get(&held, nikaia_std::index::at(kept)).form, &nikaia_std::index::get(&held, nikaia_std::index::at(place)).form) == 0 { continue; }
            now.push(place);
            kept = place;
        }
        let mut cleared: i64 = 0;
        while ((cleared) as usize) < present.len() {
            { let __nikaia_stored = false; nikaia_std::index::set(&mut present, (cleared) as usize, __nikaia_stored); }
            { let __nikaia_stored = 0; nikaia_std::index::set(&mut ups, (cleared) as usize, __nikaia_stored); }
            { let __nikaia_stored = 0; nikaia_std::index::set(&mut downs, (cleared) as usize, __nikaia_stored); }
            cleared += 1;
        }
        for place in now.iter() {
            let place = nikaia_std::num::value(place);
            let form = &nikaia_std::index::get(&held, nikaia_std::index::at(place)).form;
            let mut at: i64 = 0;
            while ((at + 1) as usize) < form.len() {
                let rank = *nikaia_std::index::get(&form, (at) as usize);
                let k = *nikaia_std::index::get(&form, (at + 1) as usize);
                { let __nikaia_stored = true; nikaia_std::index::set(&mut present, nikaia_std::index::at(rank), __nikaia_stored); }
                if k > 0 { ups[nikaia_std::index::at(rank)] += 1; }
                if k < 0 { downs[nikaia_std::index::at(rank)] += 1; }
                at += 2;
            }
        }
        let mut chosen: i64 = -1;
        let mut have = false;
        let mut fewest: i64 = 0;
        let mut others = false;
        let mut rank: i64 = 0;
        while rank < quotients.len() as i64 {
            if *nikaia_std::index::get(&present, nikaia_std::index::at(rank)) && !*nikaia_std::index::get(&quotients, nikaia_std::index::at(rank)) { others = true; }
            rank += 1;
        }
        rank = 0;
        while rank < quotients.len() as i64 {
            if *nikaia_std::index::get(&present, nikaia_std::index::at(rank)) && !(others && *nikaia_std::index::get(&quotients, nikaia_std::index::at(rank))) {
                let made = *nikaia_std::index::get(&ups, nikaia_std::index::at(rank)) * *nikaia_std::index::get(&downs, nikaia_std::index::at(rank));
                if !have || made < fewest {
                    have = true;
                    chosen = rank;
                    fewest = made;
                }
            }
            rank += 1;
        }
        if !have {
            let mut round_bounds: Vec<Vec<LgLin>> = vec![];
            for places in round_places.iter() {
                let mut lins: Vec<LgLin> = vec![];
                for place in places.iter() {
                    let place = nikaia_std::num::value(place);
                    lins.push(nikaia_std::index::get(&held, nikaia_std::index::at(place)).lin.clone());
                }
                round_bounds.push(lins);
            }
            return lg_consistent(&round_names, &round_bounds);
        }
        let mut stop: Vec<LgClosed> = vec![];
        alive = lg_eliminate(&mut held, &now, nikaia_std::index::get(&rank_names, nikaia_std::index::at(chosen)), budget, &mut steps, &mut round_names, &mut round_places, &ranks, &mut stop);
        if !stop.is_empty() { return (*nikaia_std::index::get(&stop, 0)).clone(); }
    }
}

#[allow(clippy::too_many_arguments)]
fn lg_eliminate(held: &mut Vec<LgHeld>, now: &[i64], name: &str, budget: &LgBudget, steps: &mut Vec<LgStep>, round_names: &mut Vec<String>, round_places: &mut Vec<Vec<i64>>, ranks: &collections::BTreeMap<String, i64>, stop: &mut Vec<LgClosed>) -> Vec<i64> {
    let mut without: Vec<i64> = vec![];
    let mut up: Vec<i64> = vec![];
    let mut down: Vec<i64> = vec![];
    let mut with_places: Vec<i64> = vec![];
    for place in now.iter() {
        let place = nikaia_std::num::value(place);
        let k = nikaia_std::index::get(&held, nikaia_std::index::at(place)).lin.terms.get(name);
        if k.is_none() {
            without.push(place);
            continue;
        }
        with_places.push(place);
        if nikaia_std::index::or(k, || 0) > 0 { up.push(place); } else { down.push(place); }
    }
    round_names.push(name.to_owned());
    round_places.push(with_places);
    let mut made: Vec<LgHeld> = vec![];
    for up_at in up.iter() {
        let up_at = nikaia_std::num::value(up_at);
        let u = nikaia_std::index::get(&held, nikaia_std::index::at(up_at));
        for down_at in down.iter() {
            let down_at = nikaia_std::num::value(down_at);
            let d = nikaia_std::index::get(&held, nikaia_std::index::at(down_at));
            let a = nikaia_std::index::or(u.lin.terms.get(name), || 0);
            let b = -nikaia_std::index::or(d.lin.terms.get(name), || 0);
            let left = lg_scale(&u.lin, b);
            let right = lg_scale(&d.lin, a);
            if left.is_none() || right.is_none() { return lg_stopped(stop, LgUnknown::Overflow); }
            let sum = lg_add(&match left { Some(__nikaia_value) => __nikaia_value, None => return lg_stopped(stop, LgUnknown::Overflow) }, &match right { Some(__nikaia_value) => __nikaia_value, None => return lg_stopped(stop, LgUnknown::Overflow) });
            if sum.is_none() { return lg_stopped(stop, LgUnknown::Overflow); }
            steps.push(LgStep::Combine { left: u.step, by_left: b, right: d.step, by_right: a });
            made.push(lg_tighten_step(&match sum { Some(__nikaia_value) => __nikaia_value, None => return lg_stopped(stop, LgUnknown::Overflow) }, steps, ranks));
            if (without.len() as i64 + made.len() as i64) > budget.bounds { return lg_stopped(stop, LgUnknown::TooManyBounds); }
        }
    }
    let mut next = without;
    for one in made.into_iter() {
        next.push(held.len() as i64);
        held.push(one);
    }
    next
}

fn lg_stopped(stop: &mut Vec<LgClosed>, why: LgUnknown) -> Vec<i64> {
    stop.push(LgClosed::Unknown(why));
    vec![]
}

fn lg_consistent(names: &[String], bounds: &[Vec<LgLin>]) -> LgClosed {
    let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut round = names.len() as i64;
    while round > 0 {
        round -= 1;
        let name = (*nikaia_std::index::get(&names, nikaia_std::index::at(round))).to_owned();
        let mut low: Option<i64> = None;
        let mut high: Option<i64> = None;
        for bound in (*nikaia_std::index::get(&bounds, nikaia_std::index::at(round))).iter() {
            let k = nikaia_std::index::or(bound.terms.get(&name), || 0);
            let mut rest = bound.constant;
            for (other, c) in bound.terms.iter() {
                let c = nikaia_std::num::value(c);
                if *other != name {
                    let value = values.get(other);
                    if value.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
                    let product = c.checked_mul(nikaia_std::index::or(value, || 0));
                    if product.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
                    let total = rest.checked_add(nikaia_std::index::or(product, || 0));
                    if total.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
                    rest = nikaia_std::index::or(total, || 0);
                }
            }
            let negated = rest.checked_neg();
            if negated.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
            if k > 0 {
                let limit = nikaia_std::index::or(negated, || 0).div_euclid(k);
                if high.is_none() || limit < nikaia_std::index::or(high, || limit.into()) { high = Some(limit); }
            } else {
                let flipped = k.checked_neg();
                if flipped.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
                let quotient = nikaia_std::index::or(negated, || 0).div_euclid(nikaia_std::index::or(flipped, || 1));
                let limit = quotient.checked_neg();
                if limit.is_none() { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
                if low.is_none() || nikaia_std::index::or(low, || 0) < nikaia_std::index::or(limit, || 0) { low = std::convert::identity(limit); }
            }
        }
        let mut value: i64 = 0;
        if low.is_some() && high.is_some() && nikaia_std::index::or(low, || 0) > nikaia_std::index::or(high, || 0) { return LgClosed::Consistent { found: false, values: collections::BTreeMap::new() }; }
        if low.is_some() && nikaia_std::index::or(low, || 0) > 0 { value = nikaia_std::index::or(low, || 0); } else if high.is_some() && nikaia_std::index::or(high, || 0) < 0 { value = nikaia_std::index::or(high, || 0); }
        values.insert(name.to_owned(), value);
    }
    LgClosed::Consistent { found: true, values }
}

fn lg_traced(steps: &[LgStep], last: i64) -> LgRefutation {
    let mut needed: Vec<bool> = vec![];
    for _ in steps.iter() { needed.push(false); }
    { let __nikaia_stored = true; nikaia_std::index::set(&mut needed, nikaia_std::index::at(last), __nikaia_stored); }
    let mut at = last;
    while at >= 0 {
        if *nikaia_std::index::get(&needed, nikaia_std::index::at(at)) {
            match (*nikaia_std::index::get(&steps, nikaia_std::index::at(at))).clone() {
                LgStep::Hypothesis(_) => { },
                LgStep::Tighten(from) => { { let __nikaia_stored = true; nikaia_std::index::set(&mut needed, nikaia_std::index::at(from), __nikaia_stored); } },
                LgStep::Combine { left, right, .. } => {
                    { let __nikaia_stored = true; nikaia_std::index::set(&mut needed, nikaia_std::index::at(left), __nikaia_stored); }
                    { let __nikaia_stored = true; nikaia_std::index::set(&mut needed, nikaia_std::index::at(right), __nikaia_stored); }
                },
            }
        }
        at -= 1;
    }
    let mut renumbered: Vec<i64> = vec![];
    for _ in steps.iter() { renumbered.push(-1); }
    let mut kept: Vec<LgStep> = vec![];
    at = 0;
    while at <= last {
        if *nikaia_std::index::get(&needed, nikaia_std::index::at(at)) {
            { let __nikaia_stored = kept.len() as i64; nikaia_std::index::set(&mut renumbered, nikaia_std::index::at(at), __nikaia_stored); }
            match (*nikaia_std::index::get(&steps, nikaia_std::index::at(at))).clone() {
                LgStep::Hypothesis(i) => { kept.push(LgStep::Hypothesis(i)); },
                LgStep::Tighten(from) => { kept.push(LgStep::Tighten(*nikaia_std::index::get(&renumbered, nikaia_std::index::at(from)))); },
                LgStep::Combine { left, by_left, right, by_right } => { kept.push(LgStep::Combine { left: *nikaia_std::index::get(&renumbered, nikaia_std::index::at(left)), by_left, right: *nikaia_std::index::get(&renumbered, nikaia_std::index::at(right)), by_right }); },
            }
        }
        at += 1;
    }
    LgRefutation { steps: kept }
}


// --- logic_normal.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgNormal {
    pub arena: TermArena,
    pub facts: Vec<i64>,
    pub goal: i64,
    pub names: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgOrdered {
    shape: String,
    named: String,
    fact: i64,
}

pub fn lg_normal_of(arena: &TermArena, facts: &[i64], goal: i64) -> LgNormal {
    let mut ordered: Vec<LgOrdered> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let shape = lg_written(arena, fact, true, true);
        let named = lg_written(arena, fact, false, true);
        let mut seen = false;
        for one in ordered.iter() { if one.named == named { seen = true; } }
        if !seen {
            let mut at = ordered.len() as i64;
            while at > 0 && AsRef::<str>::as_ref(&(shape)) < AsRef::<str>::as_ref(&(nikaia_std::index::get(&ordered, nikaia_std::index::at(at - 1)).shape)) { at -= 1; }
            ordered.insert(nikaia_std::count::of(at), LgOrdered { shape, named, fact });
        }
    }
    let mut normal = LgNormal { arena: TermArena::empty(), facts: vec![], goal: 0, names: vec![] };
    let mut renamed: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for one in ordered.iter() {
        let copied = lg_copy(&mut normal, arena, one.fact, &mut renamed, true);
        normal.facts.push(copied);
    }
    normal.goal = lg_copy(&mut normal, arena, goal, &mut renamed, true);
    normal
}

fn lg_written(arena: &TermArena, id: i64, shape: bool, turn: bool) -> String {
    let mut out: String = String::from("");
    lg_write(arena, id, shape, turn, &mut out);
    out
}

fn lg_write(arena: &TermArena, id: i64, shape: bool, turn: bool, out: &mut String) {
    let node = nikaia_std::index::get(&arena.nodes, nikaia_std::index::at(id));
    if turn {
        match node {
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; return lg_write_binary("<=", arena, b, a, shape, out); },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; return lg_write_binary("<", arena, b, a, shape, out); },
            SolverTerm::Not(a) => {
                let a = *a;
                out.push_str("(not ");
                lg_write(arena, a, shape, true, out);
                out.push_str(")");
                return;
            },
            SolverTerm::And(parts) => { return lg_write_joined("and", arena, parts, shape, true, out); },
            SolverTerm::Or(parts) => { return lg_write_joined("or", arena, parts, shape, true, out); },
            _ => { },
        }
    }
    match node {
        SolverTerm::Bool(b) => { let b = *b; out.push_str(if b { "true" } else { "false" }); },
        SolverTerm::Int(n) => { let n = *n; out.push_str(&format!("{}", n)); },
        SolverTerm::Var(name) => { out.push_str(if shape { "?" } else { name }); },
        SolverTerm::Neg(a) => {
            let a = *a;
            out.push_str("(- ");
            lg_write(arena, a, shape, false, out);
            out.push_str(")");
        },
        SolverTerm::Not(a) => {
            let a = *a;
            out.push_str("(not ");
            lg_write(arena, a, shape, false, out);
            out.push_str(")");
        },
        SolverTerm::Add(a, b) => { let a = *a; let b = *b; lg_write_binary("+", arena, a, b, shape, out); },
        SolverTerm::Sub(a, b) => { let a = *a; let b = *b; lg_write_binary("-", arena, a, b, shape, out); },
        SolverTerm::Mul(a, b) => { let a = *a; let b = *b; lg_write_binary("*", arena, a, b, shape, out); },
        SolverTerm::Quot(a, k) => {
            let a = *a; let k = *k;
            out.push_str("(quot ");
            lg_write(arena, a, shape, false, out);
            out.push_str(&format!(" {})", k));
        },
        SolverTerm::Le(a, b) => { let a = *a; let b = *b; lg_write_binary("<=", arena, a, b, shape, out); },
        SolverTerm::Lt(a, b) => { let a = *a; let b = *b; lg_write_binary("<", arena, a, b, shape, out); },
        SolverTerm::Ge(a, b) => { let a = *a; let b = *b; lg_write_binary(">=", arena, a, b, shape, out); },
        SolverTerm::Gt(a, b) => { let a = *a; let b = *b; lg_write_binary(">", arena, a, b, shape, out); },
        SolverTerm::Eq(a, b) => { let a = *a; let b = *b; lg_write_binary("=", arena, a, b, shape, out); },
        SolverTerm::Ne(a, b) => { let a = *a; let b = *b; lg_write_binary("distinct", arena, a, b, shape, out); },
        SolverTerm::And(parts) => { lg_write_joined("and", arena, parts, shape, false, out); },
        SolverTerm::Or(parts) => { lg_write_joined("or", arena, parts, shape, false, out); },
        SolverTerm::Other => { out.push_str("false"); },
    }
}

fn lg_write_binary(op: &str, arena: &TermArena, a: i64, b: i64, shape: bool, out: &mut String) {
    out.push_str("(");
    out.push_str(op);
    out.push_str(" ");
    lg_write(arena, a, shape, false, out);
    out.push_str(" ");
    lg_write(arena, b, shape, false, out);
    out.push_str(")");
}

fn lg_write_joined(op: &str, arena: &TermArena, parts: &[i64], shape: bool, turn: bool, out: &mut String) {
    out.push_str("(");
    out.push_str(op);
    out.push_str(" ");
    let mut first = true;
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        if !first { out.push_str(" "); }
        first = false;
        lg_write(arena, part, shape, turn, out);
    }
    out.push_str(")");
}

fn lg_copy(normal: &mut LgNormal, from: &TermArena, id: i64, renamed: &mut collections::BTreeMap<String, String>, turn: bool) -> i64 {
    let node = nikaia_std::index::get(&from.nodes, nikaia_std::index::at(id));
    if turn {
        match node {
            SolverTerm::Ge(a, b) => {
                let a = *a; let b = *b;
                let x = lg_copy(normal, from, b, renamed, false);
                let y = lg_copy(normal, from, a, renamed, false);
                return normal.arena.le(x, y);
            },
            SolverTerm::Gt(a, b) => {
                let a = *a; let b = *b;
                let x = lg_copy(normal, from, b, renamed, false);
                let y = lg_copy(normal, from, a, renamed, false);
                return normal.arena.lt(x, y);
            },
            SolverTerm::Not(a) => {
                let a = *a;
                let x = lg_copy(normal, from, a, renamed, true);
                return normal.arena.not(x);
            },
            SolverTerm::And(parts) => {
                let mut made: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    made.push(lg_copy(normal, from, part, renamed, true));
                }
                return normal.arena.and(made);
            },
            SolverTerm::Or(parts) => {
                let mut made: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    made.push(lg_copy(normal, from, part, renamed, true));
                }
                return normal.arena.or(made);
            },
            _ => { },
        }
    }
    match node {
        SolverTerm::Bool(b) => { let b = *b; normal.arena.boolean(b) },
        SolverTerm::Int(n) => { let n = *n; normal.arena.int(n) },
        SolverTerm::Other => normal.arena.boolean(false),
        SolverTerm::Var(name) => {
            let known = renamed.get(name);
            let mut fresh = format!("v{}", renamed.len() as i64);
            if known.is_some() {
                fresh = nikaia_std::index::or(match known {
                    Some(__nikaia_it) => Some(__nikaia_it.to_string()),
                    None => None,
                }, || fresh.into());
            } else {
                normal.names.push(name.to_owned());
                renamed.insert(name.to_owned(), fresh.to_owned());
            }
            normal.arena.var(&fresh)
        },
        SolverTerm::Neg(a) => {
            let a = *a;
            let x = lg_copy(normal, from, a, renamed, false);
            normal.arena.neg(x)
        },
        SolverTerm::Not(a) => {
            let a = *a;
            let x = lg_copy(normal, from, a, renamed, false);
            normal.arena.not(x)
        },
        SolverTerm::Add(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.add(x, y)
        },
        SolverTerm::Sub(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.sub(x, y)
        },
        SolverTerm::Mul(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.mul(x, y)
        },
        SolverTerm::Quot(a, k) => {
            let a = *a; let k = *k;
            let x = lg_copy(normal, from, a, renamed, false);
            normal.arena.quot(x, k)
        },
        SolverTerm::Le(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.le(x, y)
        },
        SolverTerm::Lt(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.lt(x, y)
        },
        SolverTerm::Ge(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.ge(x, y)
        },
        SolverTerm::Gt(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.gt(x, y)
        },
        SolverTerm::Eq(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.equal(x, y)
        },
        SolverTerm::Ne(a, b) => {
            let a = *a; let b = *b;
            let x = lg_copy(normal, from, a, renamed, false);
            let y = lg_copy(normal, from, b, renamed, false);
            normal.arena.unequal(x, y)
        },
        SolverTerm::And(parts) => {
            let mut made: Vec<i64> = vec![];
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                made.push(lg_copy(normal, from, part, renamed, false));
            }
            normal.arena.and(made)
        },
        SolverTerm::Or(parts) => {
            let mut made: Vec<i64> = vec![];
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                made.push(lg_copy(normal, from, part, renamed, false));
            }
            normal.arena.or(made)
        },
    }
}

impl LgNormal {
    pub fn text(&self) -> String {
        let mut out: String = String::from("");
        for fact in self.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            lg_write(&self.arena, fact, false, false, &mut out);
            out.push_str("\n");
        }
        out.push_str("|- ");
        lg_write(&self.arena, self.goal, false, false, &mut out);
        out
    }
    pub fn named(&self, model: &LgModel) -> LgModel {
        let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for (name, value) in model.values.iter() {
            let value = nikaia_std::num::value(value);
            values.insert(self.original(name), value);
        }
        LgModel { values }
    }
    fn original(&self, name: &str) -> String {
        if name.starts_with('v') {
            let digits = nikaia_std::index::or(name.strip_prefix('v'), || "").to_owned();
            let mut plain = !digits.is_empty();
            for c in digits.chars() { if c < '0' || c > '9' { plain = false; } }
            if plain {
                let n = nikaia_std::index::or(text::parse_i64(&digits), || -1);
                if n >= 0 && n < self.names.len() as i64 { return (*nikaia_std::index::get(&self.names, nikaia_std::index::at(n))).to_owned(); }
            }
        }
        name.to_owned()
    }
}

pub fn lg_certificate_text(certificate: &LgCertificate) -> String {
    match certificate {
        LgCertificate::Refuted(refutation) => {
            let mut steps: Vec<String> = vec![];
            for step in refutation.steps.iter() {
                let step = *step;
                steps.push(lg_step_text(&step));
            }
            format!("R({})", steps.join(","))
        },
        LgCertificate::Split { disjunction, cases } => {
            let disjunction = *disjunction;
            let mut parts: Vec<String> = vec![];
            for one in cases.iter() { parts.push(lg_certificate_text(one)); }
            format!("S{}[{}]", disjunction, parts.join("|"))
        },
    }
}

fn lg_step_text(step: &LgStep) -> String {
    match step.clone() {
        LgStep::Hypothesis(n) => format!("h{}", n),
        LgStep::Tighten(n) => format!("t{}", n),
        LgStep::Combine { left, by_left, right, by_right } => format!("c{}:{}:{}:{}", left, by_left, right, by_right),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgParsed {
    certificate: LgCertificate,
    rest: String,
}

pub fn lg_certificate_of(text: &str) -> Option<LgCertificate> {
    let parsed = match lg_certificate_from(text) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if parsed.rest.is_empty() { return Some(parsed.certificate.clone()); }
    None
}

fn lg_certificate_from(text: &str) -> Option<LgParsed> {
    if text.starts_with("R(") {
        let rest = nikaia_std::index::or(text.strip_prefix("R("), || "").to_owned();
        let end = match nikaia_std::search::find(&rest, &")", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let mut steps: Vec<LgStep> = vec![];
        let inside = nikaia_std::index::get(&rest, nikaia_std::index::at(0..end)).to_owned();
        for word in inside.split(',') {
            if word.is_empty() { continue; }
            steps.push(match lg_step_of(word) { Some(__nikaia_value) => __nikaia_value, None => return None });
        }
        return Some(LgParsed { certificate: LgCertificate::Refuted(LgRefutation { steps }), rest: nikaia_std::index::get(&rest, nikaia_std::index::at(end + ")".len() as i64..)).to_owned() });
    }
    if !text.starts_with('S') { return None; }
    let rest = nikaia_std::index::or(text.strip_prefix('S'), || "").to_owned();
    let open = match nikaia_std::search::find(&rest, &"[", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let disjunction = match lg_number(&nikaia_std::index::get(&rest, nikaia_std::index::at(0..open)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut after = nikaia_std::index::get(&rest, nikaia_std::index::at(open + 1..)).to_owned();
    let mut cases: Vec<LgCertificate> = vec![];
    loop {
        let case = match lg_certificate_from(&after) { Some(__nikaia_value) => __nikaia_value, None => return None };
        cases.push(case.certificate.clone());
        if case.rest.starts_with('|') { after = nikaia_std::index::or(case.rest.strip_prefix('|'), || "").to_owned(); } else {
            if !case.rest.starts_with(']') { return None; }
            return Some(LgParsed { certificate: LgCertificate::Split { disjunction, cases }, rest: nikaia_std::index::or(case.rest.strip_prefix(']'), || "").to_owned() });
        }
    }
}

fn lg_number(word: &str) -> Option<i64> {
    let n = match text::parse_i64(word) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if n < 0 { return None; }
    Some(n)
}

fn lg_step_of(word: &str) -> Option<LgStep> {
    if word.starts_with('h') { return Some(LgStep::Hypothesis(match lg_number(&nikaia_std::index::or(word.strip_prefix('h'), || "").to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None })); }
    if word.starts_with('t') { return Some(LgStep::Tighten(match lg_number(&nikaia_std::index::or(word.strip_prefix('t'), || "").to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None })); }
    if !word.starts_with('c') { return None; }
    let body = nikaia_std::index::or(word.strip_prefix('c'), || "").to_owned();
    let parts: Vec<&str> = body.split(':').collect::<Vec<_>>();
    if parts.len() != 4 { return None; }
    let left = match lg_number(*nikaia_std::index::get(&parts, 0)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let by_left = match text::parse_i64(*nikaia_std::index::get(&parts, 1)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let right = match lg_number(*nikaia_std::index::get(&parts, 2)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let by_right = match text::parse_i64(*nikaia_std::index::get(&parts, 3)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LgStep::Combine { left, by_left, right, by_right })
}

pub fn lg_model_text(model: &LgModel) -> String {
    if model.values.is_empty() { return String::from("-"); }
    let mut values: Vec<String> = vec![];
    for (name, value) in model.values.iter() {
        let value = nikaia_std::num::value(value);
        values.push(format!("{}={}", name, value));
    }
    values.join(",")
}

pub fn lg_model_of(text: &str) -> Option<LgModel> {
    let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    if text != "-" {
        for pair in text.split(',') {
            let at = match nikaia_std::search::find(&pair, &"=", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let name = nikaia_std::index::get(&pair, nikaia_std::index::at(0..at)).to_owned();
            if name.is_empty() { return None; }
            for c in name.chars() { if c.is_whitespace() { return None; } }
            let value = match text::parse_i64(&nikaia_std::index::get(&pair, nikaia_std::index::at(at + 1..)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
            values.insert(name, value);
        }
    }
    Some(LgModel { values })
}


// --- logic_search.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgBranch {
    held_atoms: Vec<i64>,
    held_why: Vec<collections::BTreeSet<i64>>,
    open_ors: Vec<i64>,
    open_why: Vec<collections::BTreeSet<i64>>,
}

impl LgBranch {
    fn absorb(&mut self, items: &[LgItem], why: &collections::BTreeSet<i64>) {
        for item in items.iter() {
            let item = *item;
            if item.atom {
                if !self.held_atoms.contains(&item.n) {
                    self.held_atoms.push(item.n);
                    self.held_why.push(why.to_owned());
                }
            } else {
                self.open_ors.push(item.n);
                self.open_why.push(why.to_owned());
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LgWork {
    n: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgSearched {
    Done { certificate: LgCertificate, relies: collections::BTreeSet<i64> },
    Consistent { found: bool, values: collections::BTreeMap<String, i64> },
    Unknown(LgUnknown),
}

fn lg_search(indexed: &LgIndexed, state: &LgBranch, budget: &LgBudget, work: &mut LgWork) -> LgSearched {
    work.n += 1;
    if work.n > budget.cases { return LgSearched::Unknown(LgUnknown::TooManyCases); }
    let mut bounds: Vec<LgLin> = vec![];
    for atom in state.held_atoms.iter() {
        let atom = nikaia_std::num::value(atom);
        bounds.push((*nikaia_std::index::get(&indexed.atoms, nikaia_std::index::at(atom))).clone());
    }
    let closed = lg_contradictory(&bounds, budget);
    match closed {
        LgClosed::Refuted(ref refutation) => {
            let mut relies: collections::BTreeSet<i64> = collections::BTreeSet::new();
            let mut steps: Vec<LgStep> = vec![];
            for step in refutation.steps.iter() {
                let step = *step;
                match step {
                    LgStep::Hypothesis(i) => {
                        for one in (*nikaia_std::index::get(&state.held_why, nikaia_std::index::at(i))).iter() {
                            let one = nikaia_std::num::value(one);
                            relies.insert(one);
                        }
                        steps.push(LgStep::Hypothesis(*nikaia_std::index::get(&state.held_atoms, nikaia_std::index::at(i))));
                    },
                    _ => { steps.push(step.clone()); },
                }
            }
            return LgSearched::Done { certificate: LgCertificate::Refuted(LgRefutation { steps }), relies };
        },
        LgClosed::Consistent { found, ref values } => { if state.open_ors.is_empty() { return LgSearched::Consistent { found, values: values.to_owned() }; } },
        LgClosed::Unknown(why) => { return LgSearched::Unknown(why.clone()); },
    }
    let mut at: i64 = 0;
    let mut index: i64 = 1;
    while ((index) as usize) < state.open_ors.len() {
        let here = *nikaia_std::index::get(&state.open_ors, (index) as usize);
        let best = *nikaia_std::index::get(&state.open_ors, nikaia_std::index::at(at));
        let fewer = ((*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(here))).len() as i64) < (*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(best))).len() as i64;
        let same = ((*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(here))).len() as i64) == (*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(best))).len() as i64;
        if fewer || same && here < best { at = index; }
        index += 1;
    }
    let mut rest = LgBranch { held_atoms: state.held_atoms.to_owned(), held_why: state.held_why.to_owned(), open_ors: vec![], open_why: vec![] };
    let mut position: i64 = 0;
    let mut disjunction: i64 = 0;
    let mut brought: collections::BTreeSet<i64> = collections::BTreeSet::new();
    while ((position) as usize) < state.open_ors.len() {
        if position == at {
            disjunction = *nikaia_std::index::get(&state.open_ors, (position) as usize);
            brought = (*nikaia_std::index::get(&state.open_why, (position) as usize)).to_owned();
        } else {
            rest.open_ors.push(*nikaia_std::index::get(&state.open_ors, (position) as usize));
            rest.open_why.push((*nikaia_std::index::get(&state.open_why, (position) as usize)).to_owned());
        }
        position += 1;
    }
    let mut why = brought.to_owned();
    why.insert(disjunction);
    let mut cases: Vec<LgCertificate> = vec![];
    let mut reliance = brought.to_owned();
    for alternative in (*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(disjunction))).iter() {
        let mut branch = LgBranch { held_atoms: rest.held_atoms.to_owned(), held_why: rest.held_why.to_owned(), open_ors: rest.open_ors.to_owned(), open_why: rest.open_why.to_owned() };
        branch.absorb(alternative, &why);
        let found = lg_search(indexed, &branch, budget, work);
        match found {
            LgSearched::Done { ref certificate, ref relies } => {
                if !relies.contains(&disjunction) { return LgSearched::Done { certificate: certificate.clone(), relies: relies.to_owned() }; }
                for one in relies.iter() {
                    let one = nikaia_std::num::value(one);
                    if one != disjunction { reliance.insert(one); }
                }
                cases.push(certificate.clone());
            },
            LgSearched::Consistent { found, ref values } => { return LgSearched::Consistent { found, values: values.to_owned() }; },
            LgSearched::Unknown(why_not) => { return LgSearched::Unknown(why_not.clone()); },
        }
    }
    LgSearched::Done { certificate: LgCertificate::Split { disjunction, cases }, relies: reliance }
}

fn lg_refuted(arena: &TermArena, facts: &[i64], goal: i64, values: &collections::BTreeMap<String, i64>) -> Option<LgModel> {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        arena.variables(fact, &mut names);
    }
    arena.variables(goal, &mut names);
    let mut given = values.to_owned();
    for name in names.iter() { if given.get(name).is_none() { given.insert(name.to_owned(), 0); } }
    let model = LgModel { values: given };
    if lg_verify_model(arena, facts, goal, &model) { return Some(model); }
    None
}

pub fn lg_check(arena: &TermArena, facts: &[i64], goal: i64, budget: &LgBudget) -> LgAnswer {
    let mut why = lg_why();
    let read = lg_indexed(arena, facts, goal, &mut why);
    if read.is_none() { return LgAnswer::Unknown { why: why.unknown.clone() }; }
    let indexed = match read { Some(__nikaia_value) => __nikaia_value, None => return LgAnswer::Unknown { why: LgUnknown::NoContradiction } };
    let mut state = LgBranch { held_atoms: vec![], held_why: vec![], open_ors: vec![], open_why: vec![] };
    let none: collections::BTreeSet<i64> = collections::BTreeSet::new();
    state.absorb((indexed.top).as_ref(), &none);
    let mut work = LgWork { n: 0 };
    let found = lg_search(&indexed, &state, budget, &mut work);
    match found {
        LgSearched::Done { ref certificate, .. } => LgAnswer::Proved { certificate: certificate.clone() },
        LgSearched::Consistent { found, ref values } => lg_consistent_answer(arena, facts, goal, found, values),
        LgSearched::Unknown(why_not) => LgAnswer::Unknown { why: why_not.clone() },
    }
}

fn lg_consistent_answer(arena: &TermArena, facts: &[i64], goal: i64, found: bool, values: &collections::BTreeMap<String, i64>) -> LgAnswer {
    if !found { return LgAnswer::Unknown { why: LgUnknown::NoContradiction }; }
    let model = lg_refuted(arena, facts, goal, values);
    if model.is_none() { return LgAnswer::Unknown { why: LgUnknown::NoContradiction }; }
    LgAnswer::Refuted { model: nikaia_std::index::or(model, || LgModel { values: collections::BTreeMap::new() }) }
}

pub fn lg_bool_value(arena: &TermArena, id: i64, values: &collections::BTreeMap<String, i64>) -> Option<bool> {
    let node = arena.at(id);
    match node {
        SolverTerm::Bool(x) => Some(x),
        SolverTerm::Not(a) => {
            let x = match lg_bool_value(arena, a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(!x)
        },
        SolverTerm::And(ref parts) => {
            let mut all = true;
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                let x = match lg_bool_value(arena, part, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                all = all && x;
            }
            Some(all)
        },
        SolverTerm::Or(ref parts) => {
            let mut any = false;
            for part in parts.iter() {
                let part = nikaia_std::num::value(part);
                let x = match lg_bool_value(arena, part, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                any = any || x;
            }
            Some(any)
        },
        SolverTerm::Le(a, b) => lg_compared(arena, a, b, 1, values),
        SolverTerm::Lt(a, b) => lg_compared(arena, a, b, 0, values),
        SolverTerm::Ge(a, b) => lg_compared(arena, a, b, 3, values),
        SolverTerm::Gt(a, b) => lg_compared(arena, a, b, 2, values),
        SolverTerm::Eq(a, b) => lg_compared(arena, a, b, 4, values),
        SolverTerm::Ne(a, b) => lg_compared(arena, a, b, 5, values),
        _ => None,
    }
}

fn lg_compared(arena: &TermArena, a: i64, b: i64, op: i64, values: &collections::BTreeMap<String, i64>) -> Option<bool> {
    let x = match arena.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let y = match arena.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if op == 0 { return Some(x < y); }
    if op == 1 { return Some(x <= y); }
    if op == 2 { return Some(x > y); }
    if op == 3 { return Some(x >= y); }
    if op == 4 { return Some(x == y); }
    Some(x != y)
}

pub fn lg_verify_model(arena: &TermArena, facts: &[i64], goal: i64, model: &LgModel) -> bool {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        let held = lg_bool_value(arena, fact, &model.values);
        if held.is_none() || !nikaia_std::index::or(held, || false) { return false; }
    }
    let goal_value = lg_bool_value(arena, goal, &model.values);
    goal_value.is_some() && !nikaia_std::index::or(goal_value, || true)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgChecking {
    held: collections::BTreeSet<i64>,
    open: collections::BTreeSet<i64>,
}

impl LgChecking {
    fn absorb(&mut self, items: &[LgItem]) {
        for item in items.iter() {
            let item = *item;
            if item.atom { self.held.insert(item.n); } else { self.open.insert(item.n); }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LgVerdict {
    rejected: Option<LgRejected>,
    case: i64,
}

pub fn lg_verify(arena: &TermArena, facts: &[i64], goal: i64, certificate: &LgCertificate) -> Option<LgRejected> {
    let mut why = lg_why();
    let read = lg_indexed(arena, facts, goal, &mut why);
    if read.is_none() { return Some(LgRejected::NotReadable); }
    let indexed = match read { Some(__nikaia_value) => __nikaia_value, None => return Some(LgRejected::NotReadable) };
    let mut branch = LgChecking { held: collections::BTreeSet::new(), open: collections::BTreeSet::new() };
    branch.absorb((indexed.top).as_ref());
    let mut verdict = LgVerdict { rejected: None, case: 0 };
    lg_follow(&indexed, &branch, certificate, &mut verdict);
    match verdict.rejected.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn lg_follow(indexed: &LgIndexed, branch: &LgChecking, certificate: &LgCertificate, verdict: &mut LgVerdict) {
    if verdict.rejected.is_some() { return; }
    match certificate {
        LgCertificate::Refuted(refutation) => {
            let at = verdict.case;
            verdict.case += 1;
            verdict.rejected = lg_replay(indexed, branch, refutation, at);
        },
        LgCertificate::Split { disjunction, cases } => {
            let disjunction = *disjunction;
            let which = disjunction;
            if !branch.open.contains(&which) {
                verdict.rejected = Some(LgRejected::NotOpen { disjunction: which });
                return;
            }
            let alternatives = (*nikaia_std::index::get(&indexed.ors, nikaia_std::index::at(which))).to_owned();
            if (alternatives.len() as i64) != cases.len() as i64 {
                verdict.rejected = Some(LgRejected::Cases { expected: alternatives.len() as i64, found: cases.len() as i64 });
                return;
            }
            let mut at: i64 = 0;
            while at < alternatives.len() as i64 {
                let mut next = LgChecking { held: branch.held.to_owned(), open: branch.open.to_owned() };
                next.open.remove(&which);
                next.absorb((*nikaia_std::index::get(&alternatives, nikaia_std::index::at(at))).as_ref());
                lg_follow(indexed, &next, nikaia_std::index::get(&cases, nikaia_std::index::at(at)), verdict);
                if verdict.rejected.is_some() { return; }
                at += 1;
            }
        },
    }
}

fn lg_replay(indexed: &LgIndexed, branch: &LgChecking, refutation: &LgRefutation, case: i64) -> Option<LgRejected> {
    let mut made: Vec<LgLin> = vec![];
    let mut at: i64 = 0;
    for step in refutation.steps.iter() {
        let step = *step;
        let bound = lg_replayed(indexed, branch, &step, &made, at, case);
        if bound.rejected.is_some() {
            return match bound.rejected.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
        }
        made.push(nikaia_std::index::or(bound.lin, || lg_constant(0).into()));
        at += 1;
    }
    if !made.is_empty() {
        let last = (*nikaia_std::index::get(&made, nikaia_std::index::at(made.len() as i64 - 1))).clone();
        if last.terms.is_empty() && last.constant > 0 { return None; }
    }
    Some(LgRejected::NotAContradiction { case })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgReplayed {
    lin: Option<LgLin>,
    rejected: Option<LgRejected>,
}

fn lg_replayed(indexed: &LgIndexed, branch: &LgChecking, step: &LgStep, made: &[LgLin], at: i64, case: i64) -> LgReplayed {
    let reference = LgRejected::Reference { case, step: at };
    match step.clone() {
        LgStep::Hypothesis(a) => {
            if branch.held.contains(&a) { return LgReplayed { lin: Some((*nikaia_std::index::get(&indexed.atoms, nikaia_std::index::at(a))).clone()), rejected: None }; }
            return LgReplayed { lin: None, rejected: Some(reference) };
        },
        LgStep::Tighten(from) => {
            if from < 0 || from >= at { return LgReplayed { lin: None, rejected: Some(reference) }; }
            return LgReplayed { lin: Some(lg_tightened(nikaia_std::index::get(&made, nikaia_std::index::at(from)))), rejected: None };
        },
        LgStep::Combine { left, by_left, right, by_right } => {
            if by_left <= 0 || by_right <= 0 { return LgReplayed { lin: None, rejected: Some(LgRejected::Multiplier { case, step: at }) }; }
            let overflow = LgRejected::Overflow { case, step: at };
            if left < 0 || left >= at { return LgReplayed { lin: None, rejected: Some(reference) }; }
            let l = lg_scale(nikaia_std::index::get(&made, nikaia_std::index::at(left)), by_left);
            if l.is_none() { return LgReplayed { lin: None, rejected: Some(overflow) }; }
            if right < 0 || right >= at { return LgReplayed { lin: None, rejected: Some(reference) }; }
            let r = lg_scale(nikaia_std::index::get(&made, nikaia_std::index::at(right)), by_right);
            if r.is_none() { return LgReplayed { lin: None, rejected: Some(overflow) }; }
            let sum = lg_add(&nikaia_std::index::or(l, || lg_constant(0).into()), &nikaia_std::index::or(r, || lg_constant(0).into()));
            if sum.is_none() { return LgReplayed { lin: None, rejected: Some(overflow) }; }
            return LgReplayed { lin: std::convert::identity(sum), rejected: None };
        },
    }
}


// --- logic_smtlib.nika ---

pub fn lg_smtlib_write(arena: &TermArena, facts: &[i64], goal: i64) -> String {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        arena.variables(fact, &mut names);
    }
    arena.variables(goal, &mut names);
    let mut out: String = String::from("(set-logic QF_LIA)\n");
    for name in names.iter() { out.push_str(&format!("(declare-const {} Int)\n", lg_symbol(name))); }
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        out.push_str(&format!("(assert {})\n", lg_term(arena, fact)));
    }
    out.push_str(&format!("(assert (not {}))\n", lg_term(arena, goal)));
    out.push_str("(check-sat)\n");
    out
}

pub fn lg_symbol(name: &str) -> String {
    let mut simple = !name.is_empty();
    let mut first = true;
    for c in name.chars() {
        if first && c >= '0' && c <= '9' { simple = false; }
        first = false;
        let letter = c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9';
        let one = format!("{}", c);
        if !letter && !"~!@$%^&*_-+=<>.?/".contains(&one) { simple = false; }
    }
    if simple { return name.to_owned(); }
    format!("|{}|", name)
}

fn lg_smt_binary(op: &str, arena: &TermArena, a: i64, b: i64) -> String { format!("({} {} {})", op, lg_term(arena, a), lg_term(arena, b)) }

fn lg_smt_list(op: &str, arena: &TermArena, parts: &[i64], empty: &str) -> String {
    if parts.is_empty() { return empty.to_owned(); }
    if parts.len() == 1 { return lg_term(arena, *nikaia_std::index::get(&parts, 0)); }
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        written.push(lg_term(arena, part));
    }
    format!("({} {})", op, written.join(" "))
}

pub fn lg_term(arena: &TermArena, id: i64) -> String {
    let node = arena.at(id);
    match node {
        SolverTerm::Bool(b) => if b { String::from("true") } else { String::from("false") },
        SolverTerm::Int(n) => lg_smt_int(n),
        SolverTerm::Var(ref name) => lg_symbol(name),
        SolverTerm::Add(a, b) => lg_smt_binary("+", arena, a, b),
        SolverTerm::Sub(a, b) => lg_smt_binary("-", arena, a, b),
        SolverTerm::Neg(a) => format!("(- {})", lg_term(arena, a)),
        SolverTerm::Mul(a, b) => lg_smt_binary("*", arena, a, b),
        SolverTerm::Quot(a, k) => {
            let e = lg_term(arena, a);
            format!("(ite (>= {} 0) (div {} {}) (- (div (- {}) {})))", e, e, k, e, k)
        },
        SolverTerm::Le(a, b) => lg_smt_binary("<=", arena, a, b),
        SolverTerm::Lt(a, b) => lg_smt_binary("<", arena, a, b),
        SolverTerm::Ge(a, b) => lg_smt_binary(">=", arena, a, b),
        SolverTerm::Gt(a, b) => lg_smt_binary(">", arena, a, b),
        SolverTerm::Eq(a, b) => lg_smt_binary("=", arena, a, b),
        SolverTerm::Ne(a, b) => format!("(not {})", lg_smt_binary("=", arena, a, b)),
        SolverTerm::And(ref parts) => lg_smt_list("and", arena, parts, "true"),
        SolverTerm::Or(ref parts) => lg_smt_list("or", arena, parts, "false"),
        SolverTerm::Not(a) => format!("(not {})", lg_term(arena, a)),
        SolverTerm::Other => String::from("false"),
    }
}

fn lg_smt_int(n: i64) -> String {
    if n >= 0 { return format!("{}", n); }
    if n == -9223372036854775807i64 - 1i64 { return String::from("(- 9223372036854775808)"); }
    format!("(- {})", -n)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LgScript {
    pub arena: TermArena,
    pub assertions: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LgReadError {
    Syntax(String),
    Unsupported(String),
    Undeclared(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LgRead {
    Script(LgScript),
    Failed(LgReadError),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgSexp {
    Atom(String),
    List(Vec<LgSexp>),
}

fn lg_show(sexp: &LgSexp) -> String {
    match sexp {
        LgSexp::Atom(a) => a.to_owned(),
        LgSexp::List(items) => {
            let mut shown: Vec<String> = vec![];
            for item in items.iter() { shown.push(lg_show(item)); }
            format!("({})", shown.join(" "))
        },
    }
}

fn lg_unquoted(name: &str) -> String {
    if name.len() >= 2 && name.starts_with('|') && name.ends_with('|') {
        let opened: String = nikaia_std::index::or(name.strip_prefix('|'), || "").to_owned();
        return nikaia_std::index::or(opened.strip_suffix('|'), || "").to_owned();
    }
    name.to_owned()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgParsedSexps {
    Done(Vec<LgSexp>),
    Failed(LgReadError),
}

fn lg_parse(source: &str) -> LgParsedSexps {
    let chars: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let mut stack: Vec<Vec<LgSexp>> = vec![vec![]];
    let mut at: i64 = 0;
    while ((at) as usize) < chars.len() {
        let c = *nikaia_std::index::get(&chars, (at) as usize);
        at += 1;
        if c == ';' {
            while ((at) as usize) < chars.len() {
                let next = *nikaia_std::index::get(&chars, (at) as usize);
                at += 1;
                if next == '\n' { break; }
            }
        } else if c == '(' { stack.push(vec![]); } else if c == ')' {
            if stack.len() < 2 { return LgParsedSexps::Failed(LgReadError::Syntax(String::from("a `)` with no `(`"))); }
            let list = (*nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))).to_owned();
            stack.pop();
            let last = stack.len() as i64 - 1;
            stack[nikaia_std::index::at(last)].push(LgSexp::List(list));
        } else if c.is_whitespace() { at += 0; } else if c == '|' {
            let mut atom: String = String::from("|");
            let mut closed = false;
            while ((at) as usize) < chars.len() {
                let next = *nikaia_std::index::get(&chars, (at) as usize);
                at += 1;
                if next == '|' {
                    closed = true;
                    break;
                }
                atom.push(next);
            }
            if !closed { return LgParsedSexps::Failed(LgReadError::Syntax(String::from("an unclosed `|`"))); }
            atom.push('|');
            let last = stack.len() as i64 - 1;
            stack[nikaia_std::index::at(last)].push(LgSexp::Atom(atom));
        } else if c == '"' {
            let mut atom: String = String::from("\"");
            let mut closed = false;
            while ((at) as usize) < chars.len() {
                let next = *nikaia_std::index::get(&chars, (at) as usize);
                at += 1;
                if next == '"' {
                    if ((at) as usize) < chars.len() && *nikaia_std::index::get(&chars, (at) as usize) == '"' {
                        at += 1;
                        atom.push_str("\"\"");
                    } else {
                        closed = true;
                        break;
                    }
                } else { atom.push(next); }
            }
            if !closed { return LgParsedSexps::Failed(LgReadError::Syntax(String::from("an unclosed string"))); }
            atom.push('"');
            let last = stack.len() as i64 - 1;
            stack[nikaia_std::index::at(last)].push(LgSexp::Atom(atom));
        } else {
            let mut atom: String = String::from("");
            atom.push(c);
            while ((at) as usize) < chars.len() {
                let next = *nikaia_std::index::get(&chars, (at) as usize);
                if next.is_whitespace() || next == '(' || next == ')' { break; }
                atom.push(next);
                at += 1;
            }
            let last = stack.len() as i64 - 1;
            stack[nikaia_std::index::at(last)].push(LgSexp::Atom(atom));
        }
    }
    if stack.len() != 1 { return LgParsedSexps::Failed(LgReadError::Syntax(String::from("a `(` with no `)`"))); }
    LgParsedSexps::Done((*nikaia_std::index::get(&stack, 0)).to_owned())
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum LgTermRead {
    Term(i64),
    Failed(LgReadError),
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LgReader {
    arena: TermArena,
    declared: collections::BTreeSet<String>,
}

impl LgReader {
    fn term(&mut self, sexp: &LgSexp) -> LgTermRead {
        match sexp {
            LgSexp::Atom(a) => self.atom(a),
            LgSexp::List(items) => self.application(sexp, items),
        }
    }
    fn atom(&mut self, a: &str) -> LgTermRead {
        if a == "true" { return LgTermRead::Term(self.arena.boolean(true)); }
        if a == "false" { return LgTermRead::Term(self.arena.boolean(false)); }
        let mut digits = !a.is_empty();
        for c in a.chars() { if c < '0' || c > '9' { digits = false; } }
        if digits {
            let n = text::parse_i64(a);
            if n.is_none() { return LgTermRead::Failed(LgReadError::Unsupported(format!("the numeral {}", a))); }
            return LgTermRead::Term(self.arena.int(nikaia_std::index::or(n, || 0)));
        }
        let name = lg_unquoted(a);
        if self.declared.contains(&name) { return LgTermRead::Term(self.arena.var(&name)); }
        LgTermRead::Failed(LgReadError::Undeclared(name))
    }
    fn application(&mut self, sexp: &LgSexp, items: &[LgSexp]) -> LgTermRead {
        if items.is_empty() { return LgTermRead::Failed(LgReadError::Unsupported(lg_show(sexp))); }
        if !lg_is_atom(items, 0) { return LgTermRead::Failed(LgReadError::Unsupported(lg_show(sexp))); }
        let op = lg_atom_at(items, 0);
        let mut args: Vec<i64> = vec![];
        let mut at: i64 = 1;
        while ((at) as usize) < items.len() {
            match self.term(nikaia_std::index::get(&items, (at) as usize)) {
                LgTermRead::Term(id) => { args.push(id); },
                LgTermRead::Failed(ref why) => { return LgTermRead::Failed(why.clone()); },
            }
            at += 1;
        }
        let n = args.len() as i64;
        if op == "not" && n == 1 { return LgTermRead::Term(self.arena.not(*nikaia_std::index::get(&args, 0))); }
        if op == "and" { return LgTermRead::Term(self.arena.and(args)); }
        if op == "or" { return LgTermRead::Term(self.arena.or(args)); }
        if op == "=>" && n == 2 {
            let not_x = self.arena.not(*nikaia_std::index::get(&args, 0));
            return LgTermRead::Term(self.arena.or(vec![not_x, *nikaia_std::index::get(&args, 1)]));
        }
        if op == "-" && n == 1 { return LgTermRead::Term(self.arena.neg(*nikaia_std::index::get(&args, 0))); }
        if n >= 2 {
            if op == "+" || op == "-" || op == "*" {
                let mut acc = *nikaia_std::index::get(&args, 0);
                let mut next: i64 = 1;
                while next < n {
                    if op == "+" { acc = self.arena.add(acc, *nikaia_std::index::get(&args, (next) as usize)); } else if op == "-" { acc = self.arena.sub(acc, *nikaia_std::index::get(&args, (next) as usize)); } else { acc = self.arena.mul(acc, *nikaia_std::index::get(&args, (next) as usize)); }
                    next += 1;
                }
                return LgTermRead::Term(acc);
            }
            if op == "<=" || op == "<" || op == ">=" || op == ">" || op == "=" {
                let mut links: Vec<i64> = vec![];
                let mut next: i64 = 0;
                while next + 1 < n {
                    let a = *nikaia_std::index::get(&args, (next) as usize);
                    let b = *nikaia_std::index::get(&args, (next + 1) as usize);
                    if op == "<=" { links.push(self.arena.le(a, b)); } else if op == "<" { links.push(self.arena.lt(a, b)); } else if op == ">=" { links.push(self.arena.ge(a, b)); } else if op == ">" { links.push(self.arena.gt(a, b)); } else { links.push(self.arena.equal(a, b)); }
                    next += 1;
                }
                if links.len() == 1 { return LgTermRead::Term(*nikaia_std::index::get(&links, 0)); }
                return LgTermRead::Term(self.arena.and(links));
            }
        }
        if op == "distinct" && n == 2 { return LgTermRead::Term(self.arena.unequal(*nikaia_std::index::get(&args, 0), *nikaia_std::index::get(&args, 1))); }
        LgTermRead::Failed(LgReadError::Unsupported(lg_show(sexp)))
    }
}

pub fn lg_smtlib_read(source: &str) -> LgRead {
    let mut reader = LgReader { arena: TermArena::empty(), declared: collections::BTreeSet::new() };
    let mut assertions: Vec<i64> = vec![];
    let commands = match lg_parse(source) {
        LgParsedSexps::Done(ref read) => read.to_owned(),
        LgParsedSexps::Failed(ref why) => { return LgRead::Failed(why.clone()); },
    };
    for command in commands.iter() {
        match command.clone() {
            LgSexp::Atom(_) => { return LgRead::Failed(LgReadError::Syntax(String::from("a command is a list"))); },
            LgSexp::List(ref items) => {
                let head = lg_head(items);
                let n = items.len() as i64;
                if n >= 1 && (head == "set-logic" || head == "set-info" || head == "set-option" || head == "check-sat" || head == "exit") { continue; }
                if n == 3 && head == "declare-const" && lg_atom_at(items, 2) == "Int" && lg_is_atom(items, 1) {
                    reader.declared.insert(lg_unquoted(&lg_atom_at(items, 1)));
                    continue;
                }
                if n == 4 && head == "declare-fun" && lg_is_atom(items, 1) && lg_is_empty_list(items, 2) && lg_atom_at(items, 3) == "Int" && lg_is_atom(items, 3) {
                    reader.declared.insert(lg_unquoted(&lg_atom_at(items, 1)));
                    continue;
                }
                if n == 2 && head == "assert" {
                    match reader.term(nikaia_std::index::get(&items, 1)) {
                        LgTermRead::Term(id) => { assertions.push(id); },
                        LgTermRead::Failed(ref why) => { return LgRead::Failed(why.clone()); },
                    }
                    continue;
                }
                return LgRead::Failed(LgReadError::Unsupported(lg_show(command)));
            },
        }
    }
    LgRead::Script(LgScript { arena: reader.arena, assertions })
}

fn lg_head(items: &[LgSexp]) -> String {
    if items.is_empty() { return String::from(""); }
    lg_atom_at(items, 0)
}

fn lg_atom_at(items: &[LgSexp], at: i64) -> String {
    match (*nikaia_std::index::get(&items, nikaia_std::index::at(at))).clone() {
        LgSexp::Atom(a) => a,
        LgSexp::List(_) => String::from(""),
    }
}

fn lg_is_atom(items: &[LgSexp], at: i64) -> bool {
    match (*nikaia_std::index::get(&items, nikaia_std::index::at(at))).clone() {
        LgSexp::Atom(_) => true,
        LgSexp::List(_) => false,
    }
}

fn lg_is_empty_list(items: &[LgSexp], at: i64) -> bool {
    match (*nikaia_std::index::get(&items, nikaia_std::index::at(at))).clone() {
        LgSexp::Atom(_) => false,
        LgSexp::List(ref inside) => inside.is_empty(),
    }
}


// --- manifest.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Switch {
    Kept,
    Moved(String),
}

pub fn known() -> Vec<String> { vec![String::from("target"), String::from("user-parallelism"), String::from("reentrancy-check"), String::from("cleanup-deadline"), String::from("optimization"), String::from("refuted-claims"), String::from("artifact"), String::from("symbol-prefix")] }

fn withdrawn(key: &str) -> &'static str {
    if key == "ordering" { return "statements run in the order they are written, so there's nothing left for it to turn off. To run two things together, write `overlap { … }`; `--overlaps` shows which branches did"; }
    ""
}

fn moved(key: &str) -> &'static str {
    if key == "cleanup-deadline" { return "the runtime configuration file `nikaia-runtime.toml`, which is read when the program starts. How long a program waits at exit is set by whoever runs it, and the compiler no longer reads this key"; }
    ""
}

pub fn build_key(key: &str) -> Result<Switch, nikaia_std::error::Thrown<Refused>> {
    let gone = withdrawn(key);
    if !gone.is_empty() { return Err(nikaia_std::error::throwing(Refused::Because(format!("`{}` in `[build]` is no longer supported: {}", key, gone)), &"build_key")); }
    if !contains(&known(), key) {
        let expected = choices(&known());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build]` has no key called `{}`. The keys are: {}.", key, expected)), &"build_key"));
    }
    let went = moved(key);
    if !went.is_empty() { return Ok(Switch::Moved(format!("`{}` in `[build]` has moved to {}", key, went))); }
    Ok(Switch::Kept)
}

pub fn targets() -> Vec<String> { vec![String::from("x86_64-linux"), String::from("aarch64-linux"), String::from("wasm32-unknown")] }

pub fn codegen_keys() -> Vec<String> { vec![String::from("opt-level"), String::from("lto"), String::from("incremental"), String::from("debug")] }

pub fn codegen_table(target: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&targets(), target) {
        let expected = choices(&targets());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` isn't a machine Nikaia builds for. The machines are: {}.", target, expected)), &"codegen_table"));
    }
    Ok(())
}

pub fn codegen_key(target: &str, key: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&codegen_keys(), key) {
        let expected = choices(&codegen_keys());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` has no key called `{}`. The keys are: {}.", target, key, expected)), &"codegen_key"));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DependencyShape {
    Rust,
    Path,
    Nikaia,
}

pub fn dependency(name: &str, typed: bool, kind: &str, has_path: bool) -> Result<DependencyShape, nikaia_std::error::Thrown<Refused>> {
    if typed {
        if kind == "rust" { return Ok(DependencyShape::Rust); }
        return Err(nikaia_std::error::throwing(Refused::Because(format!("Dependency `{}` has `type = \"{}\"`, which isn't a kind of dependency Nikaia knows. The only one is `rust`, for a crate from crates.io.", name, kind)), &"dependency"));
    }
    if has_path { return Ok(DependencyShape::Path); }
    Ok(DependencyShape::Nikaia)
}

pub fn crate_name(key: &str) -> String {
    let mut name: String = String::from("");
    for c in key.chars() { if c == '-' { name.push('_'); } else { name.push(c); } }
    name
}

fn contains(words: &[String], word: &str) -> bool {
    for w in words.iter() { if w == word { return true; } }
    false
}

fn choices(words: &[String]) -> String {
    let mut out: String = String::from("");
    for w in words.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(w);
    }
    out
}


// --- modules.nika ---

pub fn declared_names(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for item in items.iter() {
        let name = name_declared(names, &item.node);
        if !name.is_empty() { out.push(name); }
    }
    out
}

pub fn a_use_refused(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], here: &str, reachable: &collections::BTreeSet<String>, alone: bool, beside: &impl Fn(&str) -> bool) -> Option<String> {
    let mut named: Vec<(String, String)> = vec![];
    for item in items.iter() {
        let segments = use_segments(names, &item.node);
        if segments.is_empty() || *nikaia_std::index::get(&segments, 0) == "std" { continue; }
        let first = (*nikaia_std::index::get(&segments, 0)).to_owned();
        if segments.len() > 1 {
            let written = segments.join("::");
            return Some(format!("`use {}` in {}: `use` takes a package name only, not a path into it. Write `use {}`, and `{}` where you need it.", written, here, first, written));
        }
        let called = alias_of(names, &item.node);
        if !called.is_empty() { named.push((first, called)); } else { named.push((first.to_owned(), first)); }
    }
    let mut once: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (_, called) in named.iter() {
        if once.contains(called) { return Some(format!("`{}` is used twice in {}. Two packages can't have the same name in one file. Write `use … as …` to give one of them another name.", called, here)); }
        once.insert(called.to_owned());
    }
    for (package, _) in named.iter() {
        if reachable.contains(package) { continue; }
        if alone { return Some(format!("`use {}` in {}: a single file outside a project has no dependencies, so there's no `{}` to use.\nDependencies are declared in a project's `nikaia.toml`. Put this file in a project whose `nikaia.toml` declares it:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package)); }
        if beside(package) { return Some(format!("`use {}` in {}: the files of a package already see each other, so there's nothing to bring in. Remove the line and use the name directly.", package, here)); }
        return Some(format!("`use {}` in {}: there's no dependency called `{}`.\nAdd it to the project's `[dependencies]` under that name:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package));
    }
    None
}

fn use_segments(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Import { path, .. } => {
            for segment in path.iter() {
                let segment = *segment;
                out.push(names.resolve(segment).to_owned());
            }
        },
        _ => { },
    }
    out
}

fn alias_of(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Import { alias, .. } => { let alias = *alias; a_symbols_text(names, alias) },
        _ => String::from(""),
    }
}

pub fn could_promise(contracts: &Ledger, theirs: &collections::BTreeSet<String>, paused_by_code: &collections::BTreeMap<String, Vec<String>>) -> String {
    let mut never: Vec<String> = vec![];
    for (key, contract) in contracts.functions.iter() { if !of_a_dependency(key, theirs) && contract.public && inferred_sync(&contract.sync_claim) { never.push(format!("`{}`", key)); } }
    let mut through: Vec<String> = vec![];
    for (key, lambdas) in paused_by_code.iter() {
        let contract = match *nikaia_std::index::get(&contracts.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if of_a_dependency(key, theirs) || !contract.public || !no_sync(&contract.sync_claim) { continue; }
        let mut named: Vec<String> = vec![];
        for lambda in lambdas.iter() { if !nikaia_std::list::contains(&contract.keeps, &lambda) { named.push(lambda.to_owned()); } }
        if (named.len() as i64) == lambdas.len() as i64 { through.push(format!("`{}` (`sync({})`)", key, named.join(", "))); }
    }
    let mut out: String = String::from("");
    if !never.is_empty() {
        let one = never.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", never.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} never pause{} and do{} not promise it: {}\n  help: write `sync` after the result, and callers in other packages can rely on it\n", count, functions, s, es, never.join(", ")));
    }
    if !through.is_empty() {
        let one = through.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", through.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let they = if one { "it is" } else { "they are" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} pause{} only where the lambdas {} given do, and do{} not promise it: {}\n  help: write `sync(f)` after the result, naming those lambdas, and callers in other packages can rely on it\n", count, functions, s, they, es, through.join(", ")));
    }
    out
}

fn of_a_dependency(key: &str, theirs: &collections::BTreeSet<String>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && theirs.contains(*nikaia_std::index::get(&parts, 0))
}

fn inferred_sync(claim: &Sync) -> bool { matches!(claim, Sync::Inferred) }

fn no_sync(claim: &Sync) -> bool { matches!(claim, Sync::No) }

pub fn pause_path(chain: &[String]) -> String {
    let mut steps: Vec<String> = vec![];
    let mut k: i64 = 0;
    while ((k + 1) as usize) < chain.len() {
        steps.push(format!("`{}` calls `{}`", *nikaia_std::index::get(&chain, (k) as usize), *nikaia_std::index::get(&chain, (k + 1) as usize)));
        k += 1;
    }
    steps.join(", which ")
}

pub fn lost_sync_unplaced(message: &str, help: &str) -> String { format!("warning[NK2211]: {}\n   = note: a method call it makes, or one of the calls it leads to, can pause.\n   = help: {}\n", message, help) }

pub fn test_function(k: i64) -> String { format!("__nikaia_test_{}", k) }

pub fn test_dispatcher(cli: &str, with_use: bool, count: i64, dispatch: &str) -> String {
    let mut text: String = String::from("");
    if with_use { text.push_str("use std::cli\n"); }
    text.push_str(&format!("fn {}() throws {{\n    let which = {}::args().nth(1) ?? \"\"\n", dispatch, cli));
    for k in 0..count { text.push_str(&format!("    if which == \"{}\" {{\n        {}()\n        return\n    }}\n", k, test_function(k))); }
    text.push_str("    panic(f\"this build has no test numbered `{which}`\")\n}\n");
    text
}


// --- names.nika ---

pub fn names_in(expr: &Expr, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Variable(name, _) => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
        },
        Expr::Path(segments, _) => { if !segments.is_empty() { out.insert(words.resolve(*nikaia_std::index::get(&segments, 0)).to_owned()); } },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            names_in(func, words, out);
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::MethodCall { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::SafeMethod { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out); },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            names_in(lhs, words, out);
            names_in(rhs, words, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); names_in(inner, words, out); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            names_in(base, words, out);
            names_in(index, words, out);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { names_in(part, words, out); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            names_in(value, words, out);
            names_in(count, words, out);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { names_in(item, words, out); } },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            names_in(value, words, out);
            names_in(fallback, words, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            names_in(start, words, out);
            names_in(end, words, out);
        },
        Expr::StructLit { name, fields, .. } => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            names_in(base, words, out);
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::Block(block, _) => { names_in_block(block, words, out); },
        Expr::Unsafe(block, _) => { names_in_block(block, words, out); },
        Expr::Overlap(block, _) => { names_in_block(block, words, out); },
        Expr::Closure { body, .. } => { names_in_block(body, words, out); },
        Expr::Select(arms, _) => {
            for arm in arms.iter() {
                a_symbol(arm.binding, words, out);
                names_in(&arm.value, words, out);
                names_in_block(&arm.body, words, out);
            }
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            names_in(cond, words, out);
            names_in_block(then_branch, words, out);
            maybe_names_in_block((else_branch).as_ref(), words, out);
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            names_in(value, words, out);
            for arm in arms.iter() {
                match &arm.pattern {
                    MatchPattern::Literal(pattern) => { names_in(pattern, words, out); },
                    _ => { },
                }
                names_in(&arm.body, words, out);
            }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); names_in(body, words, out); },
        Expr::Throw(thrown, _) => { let thrown = nikaia_std::boxed::open(thrown); names_in(thrown, words, out); },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_names_in((value).as_ref(), words, out); },
        Expr::Break(_) => { },
        Expr::Continue(_) => { },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            names_in(expr, words, out);
            names_in_block(handler, words, out);
        },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { names_in(expr, words, out); },
                    FPart::Text(_) => { },
                }
            }
        },
        Expr::Dsl { target, package, context, content, .. } => {
            let context = *context; let package = *package; let target = *target;
            out.insert(words.resolve(target).to_owned());
            a_symbol(package, words, out);
            a_symbol(context, words, out);
            words_of(content, out);
        },
        Expr::Asm { bindings, code, .. } => {
            for binding in bindings.iter() { out.insert(words.resolve(binding.variable).to_owned()); }
            words_of(code, out);
        },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_, _) => { },
        Expr::LitBool(_, _) => { },
        Expr::LitNull(_) => { },
        Expr::LitChar(_, _) => { },
        Expr::LitStr { .. } => { },
    }
}

pub fn names_in_block(block: &Block, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { for stmt in block.stmts.iter() { names_in_statement(&stmt.node, words, out); } }

pub fn names_in_statement(stmt: &Stmt, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match stmt {
        Stmt::Let { value, .. } => { names_in(value, words, out); },
        Stmt::Comptime { value, .. } => { names_in(value, words, out); },
        Stmt::Expr(value) => { names_in(value, words, out); },
        Stmt::Assign { target, value, .. } => {
            names_in(target, words, out);
            names_in(value, words, out);
        },
        Stmt::For { iter, body, .. } => {
            names_in(iter, words, out);
            names_in_block(body, words, out);
        },
        Stmt::While { cond, body } => {
            names_in(cond, words, out);
            names_in_block(body, words, out);
        },
        Stmt::Return(value) => { maybe_names_in((value).as_ref(), words, out); },
        Stmt::Break => { },
        Stmt::Continue => { },
    }
}

fn maybe_names_in(expr: Option<&Expr>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn maybe_names_in_block(block: Option<&Block>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in_block(match block { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn a_symbol(name: Option<winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    let named = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    out.insert(words.resolve(named).to_owned());
}

fn words_of(text: &str, out: &mut collections::BTreeSet<String>) {
    let mut word: String = String::from("");
    for c in text.chars() {
        if c.is_alphanumeric() || c == '_' { word.push(c); } else {
            if !word.is_empty() { out.insert(word.to_owned()); }
            word = String::from("");
        }
    }
    if !word.is_empty() { out.insert(word); }
}


// --- order.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Operation {
    pub binds: Option<String>,
    pub mentions: collections::BTreeSet<String>,
    pub reaches: Vec<Reached>,
    pub callee: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Accounted {
    Operation(Operation),
    NotAnOperation,
    Opaque(String),
    DivertingHandler,
    UncaughtFailure(String),
    NoTouches(String),
    UnknownResource { callee: String, kind: String },
    MayNotCross { callee: String, crossing: Crossing },
    NonLiteralArgument(String),
}

impl Accounted {
    pub fn why(&self) -> String {
        match self {
            Accounted::Operation(_) => String::from("it is an operation"),
            Accounted::NotAnOperation => String::from("one of them performs no operation at all"),
            Accounted::Opaque(what) => format!("one of them holds {}", what),
            Accounted::DivertingHandler => String::from("its `catch` can leave the function, so the next statement might never run. Make the handler return a value instead, and check it afterwards"),
            Accounted::UncaughtFailure(name) => format!("`{}` can fail and nothing catches it, so the next statement might never run. `catch` it into a value, and check it afterwards", name),
            Accounted::NoTouches(name) => format!("nothing says what `{}` touches, so it might touch anything", name),
            Accounted::UnknownResource { callee, kind } => unknown_resource(callee, kind),
            Accounted::MayNotCross { callee, crossing } => may_not_cross(callee, crossing),
            Accounted::NonLiteralArgument(name) => format!("`{}` isn't a literal, and only literals can be sent to another thread", name),
        }
    }
}

fn unknown_resource(callee: &str, kind: &str) -> String {
    let article = an_or_a(kind);
    format!("`{}` says it touches {} `{}`, which this version of Nikaia doesn't know, so it might touch anything", callee, article, kind)
}

fn may_not_cross(callee: &str, crossing: &Crossing) -> String {
    let note = nikaia_std::index::or(crossing.note(), || "It can't.".into());
    format!("what `{}` returns would have to move to another thread. {}", callee, note)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Verdict {
    Overlap,
    DataDependency(String),
    Shadowed(String),
    SameResource { kind: String, named: Option<String>, unnameable: bool },
    SameDestination { one: String, other: String },
    NotAccountedFor,
}

impl Verdict {
    pub fn is_overlap(&self) -> bool { matches!(self, Verdict::Overlap) }
    pub fn why(&self) -> String {
        match self {
            Verdict::Overlap => String::from("they meet on nothing"),
            Verdict::DataDependency(name) => format!("the second uses `{}`", name),
            Verdict::Shadowed(name) => format!("both bind `{}`", name),
            Verdict::SameResource { kind, named, unnameable } => { let unnameable = *unnameable; same_resource(kind, (named).as_deref(), unnameable) },
            Verdict::SameDestination { one, other } => format!("one touches {} and the other {}, which might be the same place. Use `seq` to run them in order", one, other),
            Verdict::NotAccountedFor => String::from("the compiler can't tell what one of them does"),
        }
    }
}

fn same_resource(kind: &str, named: Option<&str>, unnameable: bool) -> String {
    if named.is_some() {
        let name = nikaia_std::index::or(named, || "");
        return format!("both reach {} `{}`, and one writes it", kind, name);
    }
    if unnameable { return format!("both touch a {} the compiler can't name, and one writes to it", kind); }
    format!("both touch {}, and one writes to it", kind)
}

pub fn verdict(earlier: &Operation, later: &Operation) -> Verdict {
    let bound = written_or_nothing((earlier.binds).as_deref());
    if earlier.binds.is_some() && later.mentions.contains(&bound) { return Verdict::DataDependency(bound.to_owned()); }
    if earlier.binds.is_some() && earlier.binds == later.binds { return Verdict::Shadowed(bound.to_owned()); }
    for a in earlier.reaches.iter() { for b in later.reaches.iter() { if a.conflicts_with(b) { return conflict(a, b); } } }
    Verdict::Overlap
}

fn conflict(a: &Reached, b: &Reached) -> Verdict {
    if a.kind != b.kind { return Verdict::SameDestination { one: a.kind.to_owned(), other: b.kind.to_owned() }; }
    let named = match readable_name(a) { Some(__nikaia_value) => __nikaia_value, None => match readable_name(b) { Some(__nikaia_value) => __nikaia_value, None => return Verdict::SameResource { kind: a.kind.to_owned(), named: None, unnameable: a.unknown || b.unknown } } };
    Verdict::SameResource { kind: a.kind.to_owned(), named: Some(named), unnameable: false }
}

fn readable_name(reached: &Reached) -> Option<String> {
    if reached.unknown { return None; }
    match reached.named.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub fn group_verdict(run: &[Operation]) -> Verdict {
    for i in 0..run.len() as i64 {
        for j in i + 1..run.len() as i64 {
            let found = verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(j)));
            if !found.is_overlap() { return found; }
        }
    }
    Verdict::Overlap
}

pub fn group_of(run: &[Operation]) -> i64 {
    let mut taken: i64 = if !run.is_empty() { 1 } else { 0 };
    while taken < run.len() as i64 {
        if !fits_with_the_front(run, taken) { break; }
        taken += 1;
    }
    if taken < 2 { return 0; }
    taken
}

fn fits_with_the_front(run: &[Operation], at: i64) -> bool {
    for i in 0..at { if !verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(at))).is_overlap() { return false; } }
    true
}

const KNOWN_KINDS: [&str; 6] = ["file", "stdout", "stderr", "args", "lock", "socket"];

pub fn accounted(stmt: &Stmt, words: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>) -> Accounted {
    match stmt {
        Stmt::Let { names, value, ty, .. } => {
            if ty.is_some() { return Accounted::Opaque(String::from("a written type, which would have to be carried onto one half of a pattern")); }
            if names.len() != 1 { return Accounted::Opaque(String::from("several names bound at once")); }
            let binds: Option<String> = Some(words.resolve(*nikaia_std::index::get(&names, 0)).to_owned());
            accounted_value(binds, value, words, walking)
        },
        Stmt::Expr(value) => accounted_value(None, value, words, walking),
        _ => Accounted::NotAnOperation,
    }
}

fn accounted_value(binds: Option<String>, value: &Expr, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>) -> Accounted {
    match value {
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if diverts_within(&handler.stmts, false) { return Accounted::DivertingHandler; }
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(expr, names, &mut reduced);
            reduce_handler(handler, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(expr, names, &mut mentions);
            names_in_block(handler, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, true, walking)
        },
        _ => {
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(value, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(value, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, false, walking)
        },
    }
}

fn accounted_reduced(binds: Option<String>, mentions: collections::BTreeSet<String>, reduced: &Reduced, caught: bool, walking: &Walking<'_, '_>) -> Accounted {
    if reduced.calls.is_empty() && !reduced.performs { return Accounted::NotAnOperation; }
    let mut reaches: Vec<Reached> = vec![];
    let mut named_by: Vec<String> = vec![];
    for call in reduced.calls.iter() {
        let refused = a_call_reaches(call, caught, walking, &mut reaches, &mut named_by);
        if refused.is_some() { return nikaia_std::index::or(refused, || Accounted::NotAnOperation); }
    }
    for method in reduced.methods.iter() { if !reaches_nothing(method, walking) { return Accounted::NoTouches(method.to_owned()); } }
    if reduced.refused.is_some() {
        return nikaia_std::index::or(match reduced.refused.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Accounted::NotAnOperation);
    }
    Accounted::Operation(Operation { binds, mentions, reaches, callee: named_by.join(" + ") })
}

fn a_call_reaches(call: &OneCall, caught: bool, walking: &Walking<'_, '_>, reaches: &mut Vec<Reached>, named_by: &mut Vec<String>) -> Option<Accounted> {
    let key = call.key.to_owned();
    let contract = match touches_described(&key, walking) { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    if !caught && !contract.fails_with.is_empty() { return Some(Accounted::UncaughtFailure(key)); }
    for touch in contract.touches.iter() { if !known_kind(&touch.kind) { return Some(Accounted::UnknownResource { callee: key.to_owned(), kind: touch.kind.to_owned() }); } }
    let signature = match match contract.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    let crossed = crossing(&signature.result_or_unit(), walking);
    if !crossed.may() { return Some(Accounted::MayNotCross { callee: key.to_owned(), crossing: crossed }); }
    let parameters = call_parameters(&signature);
    for touch in contract.touches.iter() {
        let named = argument_named((touch.parameter).as_deref(), &parameters, &call.arguments);
        reaches.push(Reached { kind: touch.kind.to_owned(), unknown: touch.parameter.is_some() && named.is_none(), named, write: touch.write });
    }
    named_by.push(key);
    None
}

fn touches_described(key: &str, walking: &Walking<'_, '_>) -> Option<FnContract> {
    let mine: Option<FnContract> = match *nikaia_std::index::get(&walking.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    let found = match mine { Some(__nikaia_value) => __nikaia_value, None => match match *nikaia_std::index::get(&walking.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return None } };
    if !found.touches_known { return None; }
    Some(found)
}

fn known_kind(kind: &str) -> bool {
    for known in KNOWN_KINDS.iter() {
        let known = *known;
        if known == kind { return true; }
    }
    false
}

fn call_parameters(signature: &Signature) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for i in 0..signature.params.len() as i64 { if i > 0 || nikaia_std::index::get(&signature.params, (i) as usize).0 != "self" { out.push(nikaia_std::index::get(&signature.params, (i) as usize).0.to_owned()); } }
    out
}

fn argument_named(parameter: Option<&str>, parameters: &[String], arguments: &[Expr]) -> Option<String> {
    let wanted = match parameter { Some(__nikaia_value) => __nikaia_value, None => return None };
    for at in 0..parameters.len() as i64 {
        if *nikaia_std::index::get(&parameters, (at) as usize) == wanted {
            if ((at) as usize) >= arguments.len() { return None; }
            return literal_text(nikaia_std::index::get(&arguments, (at) as usize));
        }
    }
    None
}

fn literal_text(expr: &Expr) -> Option<String> {
    match expr {
        Expr::LitStr { text, .. } => Some(text.to_owned()),
        _ => None,
    }
}

fn reaches_nothing(method: &str, walking: &Walking<'_, '_>) -> bool {
    let mut candidates = method_entries(method, walking.own);
    if candidates.is_empty() { candidates = method_entries(method, walking.library); }
    if candidates.is_empty() { return false; }
    for contract in candidates.iter() { if !contract.touches_known || !contract.touches.is_empty() { return false; } }
    true
}

fn method_entries(method: &str, ledger: &Ledger) -> Vec<FnContract> {
    let suffix = format!("::{}", method);
    let mut out: Vec<FnContract> = vec![];
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) && takes_a_subject((contract.signature).as_ref()) { out.push(contract.clone()); } }
    out
}

fn takes_a_subject(signature: Option<&Signature>) -> bool {
    let written = match signature { Some(__nikaia_value) => __nikaia_value, None => return true };
    written.takes_a_receiver()
}

#[derive(Debug, Clone, PartialEq)]
pub struct OneCall {
    pub key: String,
    pub arguments: Vec<Expr>,
}

#[derive(Debug, Clone, PartialEq)]
struct Reduced {
    calls: Vec<OneCall>,
    performs: bool,
    methods: Vec<String>,
    refused: Option<Accounted>,
}

fn noted(reduced: &mut Reduced, why: Accounted) { if reduced.refused.is_none() { reduced.refused = Some(why); } }

fn stopped(reduced: &mut Reduced, why: Accounted) {
    reduced.performs = true;
    noted(reduced, why);
}

fn reduce_handler(block: &Block, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => { reduce(value, names, reduced); },
            Stmt::Expr(value) => { reduce(value, names, reduced); },
            _ => { stopped(reduced, Accounted::Opaque(String::from("a `catch` handler doing more than handing back a value"))); },
        }
    }
}

fn reduce(node: &Expr, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    match node {
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_, _) => { },
        Expr::LitBool(_, _) => { },
        Expr::LitNull(_) => { },
        Expr::LitChar(_, _) => { },
        Expr::LitStr { .. } => { },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !config.is_empty() {
                stopped(reduced, Accounted::Opaque(String::from("a call with options, which nothing matches against the callee's order yet")));
                return;
            }
            let key = match called_key(func, names) { Some(__nikaia_value) => __nikaia_value, None => return stopped(reduced, Accounted::Opaque(String::from("a call through something that is not a name"))) };
            for arg in args.iter() { reduce(arg, names, reduced); }
            reduced.calls.push(OneCall { key, arguments: args.to_owned() });
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced); },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if a_short_circuit(op) {
                stopped(reduced, Accounted::Opaque(String::from("a `&&` or `||`, whose right side runs only sometimes")));
                return;
            }
            reduce(lhs, names, reduced);
            reduce(rhs, names, reduced);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { reduce(part, names, reduced); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { reduce(item, names, reduced); } },
        Expr::Return(_, _) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Break(_) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Continue(_) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Variable(name, _) => { let name = *name; noted(reduced, Accounted::NonLiteralArgument(names.resolve(name).to_owned())); },
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::SafeField { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
            reduce(index, names, reduced);
        },
        Expr::Path(_, _) => { },
        Expr::StructLit { fields, .. } => {
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            for field in fields.iter() { reduce_maybe((field.value).as_ref(), names, reduced); }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(start, names, reduced);
            reduce(end, names, reduced);
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            noted(reduced, Accounted::Opaque(String::from("a `??`, whose fallback runs only sometimes")));
            reduce(value, names, reduced);
            reduce(fallback, names, reduced);
        },
        Expr::LitInterpolated { .. } => { stopped(reduced, Accounted::Opaque(String::from("text with code in it, whose holes this has not parsed"))); },
        Expr::MethodCall { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced); },
        Expr::SafeMethod { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced); },
        Expr::Closure { .. } => { stopped(reduced, Accounted::Opaque(String::from("a lambda, whose body this analysis does not read"))); },
        _ => { stopped(reduced, Accounted::Opaque(String::from("something with its own control flow"))); },
    }
}

fn reduce_method(receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    reduce(receiver, names, reduced);
    for arg in args.iter() { reduce(arg, names, reduced); }
    for option in config.iter() { reduce(&option.value, names, reduced); }
    reduced.methods.push(names.resolve(method).to_owned());
}

fn reduce_maybe(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) { reduce(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, reduced); }

fn a_short_circuit(op: &BinaryOp) -> bool { matches!(op, BinaryOp::And | BinaryOp::Or) }

fn called_key(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments, _) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

fn joined_segments(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() {
        let segment = *segment;
        parts.push(names.resolve(segment).to_owned());
    }
    parts.join("::")
}

pub fn diverts_within(stmts: &[Spanned<Stmt>], bound: bool) -> bool {
    for stmt in stmts.iter() {
        let leaves = match &stmt.node {
            Stmt::Return(_) => true,
            Stmt::Break => !bound,
            Stmt::Continue => !bound,
            Stmt::Expr(expr) => holds_throw(expr, bound),
            Stmt::Let { value, .. } => holds_throw(value, bound),
            Stmt::Comptime { value, .. } => holds_throw(value, bound),
            Stmt::Assign { value, .. } => holds_throw(value, bound),
            Stmt::For { body, .. } => diverts_within(&body.stmts, true),
            Stmt::While { body, .. } => diverts_within(&body.stmts, true),
        };
        if leaves { return true; }
    }
    false
}

fn holds_throw(expr: &Expr, bound: bool) -> bool {
    match expr {
        Expr::Throw(_, _) => true,
        Expr::Block(block, _) => diverts_within(&block.stmts, bound),
        Expr::Overlap(block, _) => diverts_within(&block.stmts, bound),
        Expr::If { then_branch, else_branch, .. } => diverts_within(&then_branch.stmts, bound) || else_diverts((else_branch).as_ref(), bound),
        Expr::Match { arms, .. } => an_arm_throws(arms, bound),
        _ => false,
    }
}

fn else_diverts(block: Option<&Block>, bound: bool) -> bool {
    let written = match block { Some(__nikaia_value) => __nikaia_value, None => return false };
    diverts_within(&written.stmts, bound)
}

fn an_arm_throws(arms: &[MatchArm], bound: bool) -> bool {
    for arm in arms.iter() { if holds_throw(&arm.body, bound) { return true; } }
    false
}

pub fn overlap_report(items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool) -> String {
    let mut out: String = String::from("");
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => { block_report(&item.node, None, names, walking, overlaps_in, pauses, &mut out); },
            Item::Impl { target, methods, .. } => {
                let owner: Option<String> = Some(names.resolve(target.name).to_owned());
                for method in methods.iter() { block_report(&method.node, (owner).as_deref(), names, walking, overlaps_in, pauses, &mut out); }
            },
            _ => { },
        }
    }
    if out.is_empty() { out.push_str("this program writes no `overlap { … }` block.\n"); }
    out
}

fn block_report(item: &Item, target: Option<&str>, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    match item {
        Item::Fn { name, body, .. } => {
            let name = *name;
            let own_name = function_name(names, name);
            let key = keyed(target, &own_name);
            for block in overlaps_in(body) { one_block_report(&key, &block, names, walking, pauses, out); }
        },
        _ => { },
    }
}

fn keyed(target: Option<&str>, own_name: &str) -> String {
    let owner = match target { Some(__nikaia_value) => __nikaia_value, None => return own_name.to_owned() };
    format!("{}::{}", owner, own_name)
}

fn one_block_report(key: &str, block: &Block, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    if block.stmts.is_empty() { return; }
    let mut operations: Vec<Operation> = vec![];
    let mut present: Vec<bool> = vec![];
    let mut lines: Vec<String> = vec![];
    for stmt in block.stmts.iter() {
        let answer = accounted(&stmt.node, names, walking);
        let named = match answer {
            Accounted::Operation(ref operation) => operation.callee.to_owned(),
            _ => String::from("…"),
        };
        match answer {
            Accounted::Operation(ref operation) => {
                operations.push(operation.clone());
                present.push(true);
            },
            _ => {
                operations.push(Operation { binds: None, mentions: collections::BTreeSet::new(), reaches: vec![], callee: String::from("") });
                present.push(false);
            },
        }
        let when = if pauses(stmt) { "started first" } else { "runs while they wait" };
        lines.push(format!("    {} {}", padded_right(when, 22), named));
    }
    let count = block.stmts.len() as i64;
    let refused = first_refused(&operations, &present);
    if refused.is_empty() { out.push_str(&format!("{}: an `overlap` of {} branches, which meet on nothing\n", key, count)); } else { out.push_str(&refused_header(key, count, &operations, &refused)); }
    for line in lines.iter() {
        out.push_str(line);
        out.push('\n');
    }
}

fn first_refused(operations: &[Operation], present: &[bool]) -> Vec<i64> {
    for i in 0..operations.len() as i64 { for j in i + 1..operations.len() as i64 { if *nikaia_std::index::get(&present, (i) as usize) && *nikaia_std::index::get(&present, nikaia_std::index::at(j)) && !verdict(nikaia_std::index::get(&operations, (i) as usize), nikaia_std::index::get(&operations, nikaia_std::index::at(j))).is_overlap() { return vec![i, j]; } } }
    vec![]
}

fn refused_header(key: &str, count: i64, operations: &[Operation], pair: &[i64]) -> String {
    let first = *nikaia_std::index::get(&pair, 0) + 1;
    let second = *nikaia_std::index::get(&pair, 1) + 1;
    let why = verdict(nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 0))), nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 1)))).why();
    format!("{}: an `overlap` of {} branches, and branches {} and {} may not run together - {}\n", key, count, first, second, why)
}

fn padded_right(text: &str, width: i64) -> String {
    let mut out = text.to_owned();
    let mut have = text.chars().count() as i64;
    while have < width {
        out.push(' ');
        have += 1;
    }
    out
}


// --- parse_errors.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Failure {
    pub offset: i64,
    pub expected: Vec<String>,
    pub also: Vec<String>,
    pub has_found: bool,
    pub found: String,
    pub has_message: bool,
    pub message: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseReading {
    pub at: i64,
    pub word: String,
    pub message: String,
    pub notes: Vec<String>,
    pub help: Option<String>,
}

pub const RESERVED_WORDS: [&str; 38] = ["as", "break", "catch", "comptime", "continue", "dsl", "else", "enum", "extern", "false", "fn", "for", "grammar", "if", "impl", "in", "let", "match", "mut", "null", "overlap", "pub", "ref", "return", "select", "self", "spawn", "struct", "sync", "test", "throw", "throws", "trait", "true", "unsafe", "use", "while", "with"];

fn missing_value_message(prev: &str) -> String {
    if prev == "=" { return String::from("`=` has nothing after it."); }
    if prev == "+" || prev == "-" || prev == "*" || prev == "/" || prev == "%" || prev == "==" || prev == "!=" || prev == "<" || prev == ">" || prev == "<=" || prev == ">=" || prev == "&&" || prev == "||" { return format!("`{}` has nothing on its right.", prev); }
    String::from("")
}

fn reading_at(at: i64, word: &str, message: &str, help: &str) -> ParseReading { ParseReading { at, word: word.to_owned(), message: message.to_owned(), notes: vec![], help: Some(help.to_owned()) } }

fn lists(what: &[String], one: &str) -> bool {
    for e in what.iter() { if e == one { return true; } }
    false
}

fn is_digit(ch: scalar) -> bool { ch >= '0' && ch <= '9' }

fn upto(c: &[scalar], to: i64) -> String { slice(c, 0, to) }

fn last_line_to(c: &[scalar], to: i64) -> String {
    let mut from = to;
    while from > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(from - 1)) != '\n' { from -= 1; }
    slice(c, from, to)
}

fn last_line_of(c: &[scalar], to: i64) -> Option<String> {
    if to == 0 { return None; }
    let mut end = to;
    if *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == '\n' {
        end -= 1;
        if end > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == '\r' { end -= 1; }
    }
    let mut from = end;
    while from > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(from - 1)) != '\n' { from -= 1; }
    Some(slice(c, from, end))
}

fn trimmed_len(c: &[scalar], to: i64) -> i64 {
    let mut end = to;
    while end > 0 && (*nikaia_std::index::get(&c, nikaia_std::index::at(end - 1))).is_whitespace() { end -= 1; }
    end
}

fn parses_further(input: &str, past: i64, stops_at: &impl Fn(&str) -> i64) -> bool {
    let stop = stops_at(input);
    stop < 0 || stop > past
}

fn a_better_reading(error: &Failure, c: &[scalar], at: i64, stops_at: &impl Fn(&str) -> i64) -> Option<ParseReading> {
    let source = slice(c, 0, c.len() as i64);
    let prev_end = trimmed_len(c, at);
    let prev = previous_token(&source, prev_end);
    let before = upto(c, at);
    let has_found = error.has_found;
    let found_word = error.found.to_owned();
    if !has_found && lists(&error.expected, "`\"`") {
        let open = unclosed_quote(&source);
        if open >= 0 { return Some(reading_at(open, "\"", "This string is never closed.", "End it with `\"` where the text is meant to stop.")); }
    }
    let mut wrong_closer = false;
    if has_found {
        let word = found_word.to_owned();
        wrong_closer = (word == "}" || word == ")" || word == "]") && !lists(&error.expected, &format!("`{}`", word));
    }
    if (!has_found || wrong_closer) && (lists(&error.expected, "`}`") || lists(&error.expected, "`)`") || lists(&error.expected, "`]`")) {
        let open = unclosed_bracket(&before);
        if open < 0 { return None; }
        let bracket = *nikaia_std::index::get(&c, nikaia_std::index::at(open));
        let mut close = ']';
        if bracket == '{' { close = '}'; } else if bracket == '(' { close = ')'; }
        let mut why: String = String::from("the file ended while it was still open");
        if has_found { why = format!("a `{}` closed something else first", found_word); }
        return Some(reading_at(open, &format!("{}", bracket), &format!("This `{}` is never closed.", bracket), &format!("Add the `{}` where it's meant to end; {}.", close, why)));
    }
    if has_found {
        let word = found_word.to_owned();
        if word == "struct" || word == "enum" || word == "trait" || word == "impl" || word == "grammar" {
            let open = unclosed_bracket(&before);
            if open >= 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(open)) == '{' {
                let opened = trimmed_len(c, open);
                let whole = last_line_to(c, opened);
                let line = whole.trim_start();
                if line.starts_with("impl") { return Some(reading_at(at, &word, &format!("An `impl` holds methods, and a `{}` can't be declared inside one.", word), &format!("Move the `{}` out of the `impl`, to the top level of the file.", word))); }
            }
        }
    }
    if has_found && found_word == "/" && last_line_to(c, at).trim().is_empty() && !(at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/') { return Some(reading_at(at, "/", "A single `/` is division, and nothing stands before it to divide.", "A comment starts with `//`.")); }
    if has_found {
        let quote = found_word.to_owned();
        if quote == "“" || quote == "”" || quote == "‘" || quote == "’" || quote == "„" { return Some(reading_at(at, &quote, &format!("`{}` isn't a quote the language reads.", quote), "Text is written between straight quotes: `\"hi\"`.")); }
    }
    let mut closes = !has_found;
    if has_found {
        let word = found_word.to_owned();
        closes = word == "}" || word == ")" || word == "]" || word == "newline";
    }
    if lists(&error.expected, "expression") && closes {
        let message = missing_value_message(&prev);
        if message.is_empty() { return None; }
        return Some(reading_at(prev_end - prev.len() as i64, &prev, &message, "Write the value after it, on the same line."));
    }
    if has_found && found_word == "{" && (prev == "if" || prev == "while") { return Some(reading_at(prev_end - prev.len() as i64, &prev, &format!("`{}` needs a condition before its `{{`.", prev), &format!("Write `{} cond {{ … }}`.", prev))); }
    if (prev == "let" || prev == "mut") && has_found {
        let word = found_word.to_owned();
        if !word.is_empty() {
            let letters: Vec<scalar> = nikaia_std::list::chars(word.chars());
            let first = *nikaia_std::index::get(&letters, 0);
            if is_digit(first) || first == '"' || first == '\'' { return Some(reading_at(at, &word, &format!("`let` names what it binds, but `{}` is a value.", word), "Write a name: `let x = …`, then use `x`.")); }
        }
    }
    if has_found && found_word == "," && prev == "," { return Some(reading_at(at, ",", "There are two commas here.", "Remove one.")); }
    if has_found && found_word == "=" {
        let line = nikaia_std::index::or(last_line_of(c, at), || "".into());
        let l = line.trim_start();
        if l.starts_with("if ") || l.starts_with("while ") || l.contains(" if ") {
            let compared = format!("{}=={}", upto(c, at), slice(c, at + 1, c.len() as i64));
            if parses_further(&compared, at + 2, stops_at) { return Some(reading_at(at, "=", "`=` gives a name a value; a condition compares with `==`.", "Write `==` here.")); }
        }
    }
    let closer_wanted = lists(&error.expected, "`}`") || lists(&error.expected, "`)`") || lists(&error.expected, "`]`");
    if closer_wanted && has_found {
        let word = found_word.to_owned();
        if !word.is_empty() {
            let letters: Vec<scalar> = nikaia_std::list::chars(word.chars());
            let first = *nikaia_std::index::get(&letters, 0);
            if first.is_alphabetic() || first == '_' {
                let separated = format!("{},{}", upto(c, prev_end), slice(c, prev_end, c.len() as i64));
                if parses_further(&separated, at + 1, stops_at) { return Some(reading_at(prev_end, "", &format!("A `,` is missing before `{}`.", word), &format!("Separate `{}` and `{}` with a comma.", prev, word))); }
            }
        }
    }
    None
}

fn reserved_word_note(has_found: bool, found: &str, c: &[scalar], at: i64, stops_at: &impl Fn(&str) -> i64) -> Option<String> {
    if !has_found { return None; }
    let token = found.to_owned();
    let mut listed = false;
    for word in RESERVED_WORDS.iter() {
        let word = *word;
        if word == token { listed = true; }
    }
    if !listed { return None; }
    let rest = slice(c, at, c.len() as i64);
    if !rest.starts_with(&token) { return None; }
    let letters: Vec<scalar> = nikaia_std::list::chars(token.chars());
    let width = letters.len() as i64;
    let mut with_a_name = upto(c, at);
    let mut placed: i64 = 0;
    while placed < width {
        with_a_name.push('z');
        placed += 1;
    }
    with_a_name = format!("{}{}", with_a_name, slice(c, at + width, c.len() as i64));
    if parses_further(&with_a_name, at + width, stops_at) { return Some(format!("`{}` is a reserved word, so it can't be used as a name here.", token)); }
    None
}

fn sorted_words(list: &[String]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for item in list.iter() {
        let mut at: i64 = 0;
        let mut seen = false;
        while ((at) as usize) < out.len() && AsRef::<str>::as_ref(&(*nikaia_std::index::get(&out, (at) as usize))) < AsRef::<str>::as_ref(&(item)) { at += 1; }
        if ((at) as usize) < out.len() && *nikaia_std::index::get(&out, (at) as usize) == *item { seen = true; }
        if !seen {
            let mut rest: Vec<String> = vec![];
            for k in at..out.len() as i64 { rest.push((*nikaia_std::index::get(&out, nikaia_std::index::at(k))).to_owned()); }
            while out.len() > ((at) as usize) { out.pop(); }
            out.push(item.to_owned());
            for r in rest.iter() { out.push(r.to_owned()); }
        }
    }
    out
}

fn what_was_expected(error: &Failure) -> String {
    let mut listed: Vec<String> = vec![];
    let from = if_empty(&error.expected, &error.also);
    for e in from.iter() {
        if e == "whitespace" || e == "block comment" || e == "`//`" || error.has_found && e == "end of input" { continue; }
        listed.push(e.to_owned());
    }
    let expected = sorted_words(&listed);
    let mut wanted: Option<String> = None;
    if expected.len() == 1 { wanted = Some((*nikaia_std::index::get(&expected, 0)).to_owned()); } else if expected.len() >= 2 && expected.len() <= 4 {
        let mut head: Vec<String> = vec![];
        for k in 0..expected.len() as i64 - 1 { head.push((*nikaia_std::index::get(&expected, (k) as usize)).to_owned()); }
        wanted = Some(format!("{} or {}", head.join(", "), *nikaia_std::index::get(&expected, nikaia_std::index::at(expected.len() as i64 - 1))));
    }
    let mut found: Option<String> = None;
    if error.has_found {
        let word = error.found.to_owned();
        if word == "newline" { found = Some(String::from("the end of the line")); } else { found = Some(format!("`{}`", word)); }
    }
    if wanted.is_some() && found.is_some() { return format!("Expected {} here, but found {}.", nikaia_std::index::or(wanted.as_deref(), || ""), nikaia_std::index::or(found.as_deref(), || "")); }
    if wanted.is_some() { return format!("Expected {}, but the file ended.", nikaia_std::index::or(wanted.as_deref(), || "")); }
    if found.is_some() { return format!("Didn't expect {} here.", nikaia_std::index::or(found.as_deref(), || "")); }
    String::from("The file ended too early.")
}

fn if_empty(first: &[String], second: &[String]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    if first.is_empty() { for s in second.iter() { out.push(s.to_owned()); } } else { for s in first.iter() { out.push(s.to_owned()); } }
    out
}

pub fn a_parse_error(error: &Failure, source: &str, stops_at: &impl Fn(&str) -> i64) -> ParseReading {
    let c: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let mut at = error.offset;
    if at > c.len() as i64 { at = c.len() as i64; }
    let before = last_line_to(&c, at);
    if !error.has_message {
        let better = a_better_reading(error, &c, at, stops_at);
        if better.is_some() { return nikaia_std::index::or(better, || reading_at(at, "", "", "").into()); }
    }
    let mut help: Option<String> = None;
    let mut message = what_was_expected(error);
    if error.has_message {
        let parts = first_sentence(&error.message);
        message = (*nikaia_std::index::get(&parts, 0)).to_owned();
        if parts.len() > 1 { help = Some((*nikaia_std::index::get(&parts, 1)).to_owned()); }
    }
    let mut notes: Vec<String> = vec![];
    let said_word = error.found.to_owned();
    let reserved = reserved_word_note(error.has_found, &error.found, &c, at, stops_at);
    if reserved.is_some() { notes.push(nikaia_std::index::or(reserved, || "".into())); }
    let lambda = an_effect_on_a_lambda_note(&said_word, &before);
    if lambda.is_some() { notes.push(nikaia_std::index::or(lambda, || "".into())); }
    let ref_note = the_spelling_ref_replaced_note(&said_word);
    if ref_note.is_some() { notes.push(nikaia_std::index::or(ref_note, || "".into())); }
    if error.has_found {
        let pairs = vec![coalesce_fallback_note(&said_word, &before)];
        for pair in pairs.iter() {
            if pair.len() >= 2 {
                notes.push((*nikaia_std::index::get(&pair, 0)).to_owned());
                help = Some((*nikaia_std::index::get(&pair, 1)).to_owned());
            }
        }
    }
    let mut word: String = String::from("");
    if error.has_found && slice(&c, at, c.len() as i64).starts_with(&said_word) { word = said_word; }
    ParseReading { at, word, message, notes, help }
}

pub fn unclosed_block_comment(error: &Failure, source: &str) -> Option<ParseReading> {
    if !lists(&error.expected, "`*/`") { return None; }
    let at = opening_of_an_unclosed_comment(source);
    if at < 0 { return None; }
    Some(ParseReading { at, word: String::from("/*"), message: String::from("This block comment is never closed."), notes: vec![], help: Some(String::from("Close it with `*/`. Comments nest, so every `/*` inside it needs its own `*/` too.")) })
}


// --- parse_notes.nika ---

pub fn previous_token(source: &str, end: i64) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(source.chars());
    if end <= 0 { return String::from(""); }
    let last = *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1));
    let mut start = end - 1;
    if a_word_char(last) { while start > 0 && a_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(start - 1))) { start -= 1; } } else if an_operator_char(last) { while start > 0 && an_operator_char(*nikaia_std::index::get(&c, nikaia_std::index::at(start - 1))) { start -= 1; } }
    slice(&c, start, end)
}

fn a_word_char(c: scalar) -> bool { c.is_alphanumeric() || c == '_' }

fn an_operator_char(c: scalar) -> bool { c == '=' || c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '<' || c == '>' || c == '!' || c == '&' || c == '|' }

pub fn unclosed_quote(source: &str) -> i64 {
    let c: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let mut open: i64 = -1;
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if open >= 0 {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' {
                at += 2;
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { open = -1; }
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { open = at; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
            at = past_the_line(&c, at);
            continue;
        }
        at += 1;
    }
    open
}

pub fn unclosed_bracket(source: &str) -> i64 {
    let c: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let mut stack: Vec<i64> = vec![];
    let mut in_string = false;
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if in_string {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' {
                at += 2;
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { in_string = false; }
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' { in_string = true; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
            at = past_the_line(&c, at);
            continue;
        } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '{' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '(' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '[' { stack.push(at); } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '}' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ')' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ']' { stack.pop(); }
        at += 1;
    }
    if stack.is_empty() { return -1; }
    *nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))
}

fn past_the_line(c: &[scalar], at: i64) -> i64 {
    let mut k = at;
    while k < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(k)) != '\n' { k += 1; }
    k + 1
}

pub fn opening_of_an_unclosed_comment(source: &str) -> i64 {
    let c: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let mut open: Vec<i64> = vec![];
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        if open.is_empty() {
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' {
                at += 1;
                while at < c.len() as i64 {
                    if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '\\' { at += 2; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '"' {
                        at += 1;
                        break;
                    } else { at += 1; }
                }
                continue;
            }
            if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' {
                while at < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) != '\n' { at += 1; }
                continue;
            }
        }
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '/' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '*' {
            open.push(at);
            at += 2;
            continue;
        }
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '*' && at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == '/' && !open.is_empty() {
            open.pop();
            at += 2;
            continue;
        }
        at += 1;
    }
    if open.is_empty() { return -1; }
    *nikaia_std::index::get(&open, 0)
}

pub fn first_sentence(text: &str) -> Vec<String> {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let mut quoted = false;
    for at in 0..c.len() as i64 {
        if *nikaia_std::index::get(&c, (at) as usize) == '`' { quoted = !quoted; } else if *nikaia_std::index::get(&c, (at) as usize) == '.' && !quoted && ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at + 1) as usize) == ' ' {
            let rest = slice(&c, at + 1, c.len() as i64).trim().to_owned();
            if rest.is_empty() { return vec![slice(&c, 0, at + 1)]; }
            return vec![slice(&c, 0, at + 1), rest];
        }
    }
    vec![text.to_owned()]
}

pub fn the_spelling_ref_replaced_note(found: &str) -> Option<String> {
    if found != "&" { return None; }
    Some(String::from("A view is written `ref T`: `ref String` for text, `ref Array[T]` for elements something else keeps, and `ref value` to borrow a value. (`&&` still means *and*.)"))
}

pub fn an_effect_on_a_lambda_note(found: &str, before: &str) -> Option<String> {
    if found != "sync" && found != "throws" { return None; }
    let trimmed = before.trim_end();
    if !(trimmed.ends_with(')') && trimmed.contains("fn")) { return None; }
    Some(format!("`{}` isn't written on a lambda yet: a lambda's parameter list is followed by its block and nothing else.", found))
}

const AFTER_A_FALLBACK: [&str; 17] = ["==", "!=", "<=", ">=", "=", "<", ">", "&&", "|", "||", "..", "+", "-", "*", "/", "%", "as"];

pub fn coalesce_fallback_note(found: &str, before: &str) -> Vec<String> {
    if !before.contains("??") { return vec![]; }
    for operator in AFTER_A_FALLBACK.iter() {
        let operator = *operator;
        if found == operator { return vec![String::from("The fallback after `??` is a single value unless you use brackets, so `a ?? 0 > 3` would mean `a ?? (0 > 3)`."), String::from("Put brackets around the part you mean: `(a ?? 0) > 3`, or `a ?? (0 > 3)`.")]; }
    }
    vec![]
}


// --- parse_numbers.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Number {
    Not,
    Refused { message: String, consumed: i64 },
    Taken { magnitude: u64, negative: bool, consumed: i64 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Scale {
    pub by: u64,
    pub len: i64,
}

fn digit_of(ch: scalar, radix: i64) -> i64 {
    let mut d: i64 = -1;
    if ch >= '0' && ch <= '9' { d = ch as i64 - '0' as i64; } else if ch >= 'a' && ch <= 'f' { d = ch as i64 - 'a' as i64 + 10; } else if ch >= 'A' && ch <= 'F' { d = ch as i64 - 'A' as i64 + 10; }
    if d >= radix { return -1; }
    d
}

fn an_ascii_digit(ch: scalar) -> bool { ch >= '0' && ch <= '9' }

fn an_ascii_word(ch: scalar) -> bool { ch >= '0' && ch <= '9' || ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z' || ch == '_' }

fn an_ascii_alphanumeric(ch: scalar) -> bool { an_ascii_word(ch) && ch != '_' }

fn scale_power(ch: scalar) -> i64 {
    if ch == 'K' { return 1; }
    if ch == 'M' { return 2; }
    if ch == 'G' { return 3; }
    if ch == 'T' { return 4; }
    if ch == 'P' { return 5; }
    0
}

fn scale_at(c: &[scalar], from: i64) -> Option<Scale> {
    if from >= c.len() as i64 { return None; }
    let power = scale_power(*nikaia_std::index::get(&c, nikaia_std::index::at(from)));
    if power == 0 { return None; }
    let mut base: u64 = 1000u64;
    let mut len: i64 = 1;
    if from + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(from + 1)) == 'i' {
        base = 1024;
        len = 2;
    }
    if from + len < c.len() as i64 && an_ascii_word(*nikaia_std::index::get(&c, nikaia_std::index::at(from + len))) { return None; }
    let mut by: u64 = 1u64;
    let mut turns: i64 = 0;
    while turns < power {
        by = by * base;
        turns += 1;
    }
    Some(Scale { by, len })
}

fn upper_exponent(c: &[scalar], from: i64) -> i64 {
    if from >= c.len() as i64 || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) != 'E' { return 0; }
    let mut sign: i64 = 0;
    if from + 1 < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(from + 1)) == '+' || *nikaia_std::index::get(&c, nikaia_std::index::at(from + 1)) == '-') { sign = 1; }
    let mut digits: i64 = 0;
    while from + 1 + sign + digits < c.len() as i64 && an_ascii_digit(*nikaia_std::index::get(&c, nikaia_std::index::at(from + 1 + sign + digits))) { digits += 1; }
    if digits == 0 { return 0; }
    1 + sign + digits
}

pub fn float_end(text: &str) -> Option<String> {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let scale = scale_at(&c, 0);
    if scale.is_some() {
        let found = match scale { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(format!("a scale like `{}` stands on a whole number, not on a float", slice(&c, 0, found.len)));
    }
    let len = upper_exponent(&c, 0);
    if len > 0 { return Some(format!("an exponent is written with a lower-case `e`: `{}`", slice(&c, 0, len).replace('E', "e"))); }
    None
}

fn times(digits: &str, by: u64) -> String {
    let d: Vec<scalar> = nikaia_std::list::chars(digits.chars());
    let mut out: Vec<u64> = vec![];
    let mut carry: u64 = 0u64;
    let mut k = d.len() as i64;
    while k > 0 {
        k -= 1;
        let here = u64::try_from(digit_of(*nikaia_std::index::get(&d, nikaia_std::index::at(k)), 10)).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")) * by + carry;
        out.push(here % 10u64);
        carry = here / 10u64;
    }
    while carry > 0u64 {
        out.push(carry % 10u64);
        carry = carry / 10u64;
    }
    let mut text: String = String::from("");
    let mut at = out.len() as i64;
    while at > 0 {
        at -= 1;
        if text.is_empty() && *nikaia_std::index::get(&out, nikaia_std::index::at(at)) == 0u64 { continue; }
        text.push((u8::try_from(*nikaia_std::index::get(&out, nikaia_std::index::at(at)) + '0' as u64).unwrap_or_else(|_| panic!("the value does not fit in an `u8`"))) as scalar);
    }
    if text.is_empty() { return String::from("0"); }
    text
}

fn past(digits: &str, limit: &str) -> bool {
    if (digits.len() as i64) != limit.len() as i64 { return (digits.len() as i64) > limit.len() as i64; }
    let a: Vec<scalar> = nikaia_std::list::chars(digits.chars());
    let b: Vec<scalar> = nikaia_std::list::chars(limit.chars());
    for k in 0..a.len() as i64 { if *nikaia_std::index::get(&a, (k) as usize) != *nikaia_std::index::get(&b, (k) as usize) { return *nikaia_std::index::get(&a, (k) as usize) > *nikaia_std::index::get(&b, (k) as usize); } }
    false
}

fn without_leading_zeros(digits: &str) -> String {
    let d: Vec<scalar> = nikaia_std::list::chars(digits.chars());
    let mut at: i64 = 0;
    while at + 1 < d.len() as i64 && *nikaia_std::index::get(&d, nikaia_std::index::at(at)) == '0' { at += 1; }
    slice(&d, at, d.len() as i64)
}

fn magnitude_of(digits: &str) -> u64 {
    let mut n: u64 = 0u64;
    for ch in digits.chars() { n = n * 10u64 + u64::try_from(digit_of(ch, 10)).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")); }
    n
}

fn too_big() -> String { String::from("this number is too big: the largest integer types are `u64` and `i64`") }

pub fn number_at(text: &str, signed: bool) -> Number {
    let all: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let mut c: Vec<scalar> = vec![];
    let mut first: i64 = 0;
    if signed {
        if all.len() < 2 || *nikaia_std::index::get(&all, 0) != '-' || !an_ascii_digit(*nikaia_std::index::get(&all, 1)) { return Number::Not; }
        first = 1;
    }
    for k in first..all.len() as i64 { c.push(*nikaia_std::index::get(&all, nikaia_std::index::at(k))); }
    let mut radix: i64 = 10;
    let mut prefix: i64 = 0;
    if c.len() >= 2 && *nikaia_std::index::get(&c, 0) == '0' {
        if *nikaia_std::index::get(&c, 1) == 'x' {
            radix = 16;
            prefix = 2;
        } else if *nikaia_std::index::get(&c, 1) == 'b' {
            radix = 2;
            prefix = 2;
        } else if *nikaia_std::index::get(&c, 1) == 'o' {
            radix = 8;
            prefix = 2;
        }
    }
    let mut value: String = String::from("");
    let mut at: i64 = prefix;
    let mut after_separator = false;
    let mut wrong: String = String::from("");
    while at < c.len() as i64 {
        if digit_of(*nikaia_std::index::get(&c, nikaia_std::index::at(at)), radix) >= 0 {
            value.push(*nikaia_std::index::get(&c, nikaia_std::index::at(at)));
            after_separator = false;
            at += 1;
            continue;
        }
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '_' {
            if value.is_empty() || after_separator {
                wrong = String::from("an underscore in a number goes between two digits, like `1_000_000`");
                break;
            }
            after_separator = true;
            at += 1;
            continue;
        }
        break;
    }
    if wrong.is_empty() {
        if value.is_empty() {
            if prefix == 0 { return Number::Not; }
            wrong = String::from("a number needs at least one digit after its prefix");
        } else if after_separator { wrong = String::from("a number can't end in an underscore"); } else if prefix > 0 && at < c.len() as i64 && an_ascii_alphanumeric(*nikaia_std::index::get(&c, nikaia_std::index::at(at))) { if radix == 2 { wrong = String::from("a `0b` number only has the digits `0` and `1`"); } else if radix == 8 { wrong = String::from("a `0o` number only has the digits `0` to `7`"); } else { wrong = String::from("a `0x` number only has the digits `0` to `9` and `a` to `f`"); } }
    }
    if signed && radix == 10 && at < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '.' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == 'e' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == 'E') { return Number::Not; }
    let mut scale: Option<Scale> = None;
    if wrong.is_empty() && radix == 10 {
        let mut fraction: i64 = 0;
        if at < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '.' { while at + 1 + fraction < c.len() as i64 && (an_ascii_digit(*nikaia_std::index::get(&c, nikaia_std::index::at(at + 1 + fraction))) || *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1 + fraction)) == '_') { fraction += 1; } }
        let after: i64 = at + 1 + fraction;
        if fraction > 0 && (scale_at(&c, after).is_some() || upper_exponent(&c, after) > 0) { wrong = String::from("a float takes no scale and writes its exponent `e`"); } else if scale_at(&c, at).is_some() { scale = scale_at(&c, at); } else if upper_exponent(&c, at) > 0 {
            let len = upper_exponent(&c, at);
            let mut sign = "";
            if signed { sign = "-"; }
            wrong = format!("an exponent is written with a lower-case `e`: `{}{}{}`", sign, slice(&c, 0, at), slice(&c, at, at + len).replace('E', "e"));
        }
    }
    let mut magnitude: u64 = 0u64;
    if wrong.is_empty() {
        let mut limit = "18446744073709551615";
        if signed { limit = "9223372036854775808"; }
        if radix == 10 {
            let digits = without_leading_zeros(&value);
            let mut scale_by: u64 = 1u64;
            let mut scale_len: i64 = 0;
            if scale.is_some() {
                let found = match scale { Some(__nikaia_value) => __nikaia_value, None => return Number::Not };
                scale_by = found.by;
                scale_len = found.len;
            }
            let mut widest = "170141183460469231731687303715884105727";
            if signed { widest = "170141183460469231731687303715884105728"; }
            if past(&digits, widest) { wrong = too_big(); } else {
                let product = without_leading_zeros(&times(&digits, scale_by));
                if !past(&product, limit) { magnitude = magnitude_of(&product); } else if scale.is_some() {
                    let mut said = product.to_owned();
                    if past(&product, widest) { said = widest.to_owned(); }
                    let mut sign = "";
                    if signed { sign = "-"; }
                    wrong = format!("`{}{}{}` is {}{}, which is too big: the largest integer types are `u64` and `i64`", sign, value, slice(&c, at, at + scale_len), sign, said);
                } else { wrong = too_big(); }
            }
            if wrong.is_empty() { at += scale_len; }
        } else {
            let mut n: u64 = 0u64;
            let mut fits = true;
            for ch in value.chars() {
                let d = u64::try_from(digit_of(ch, radix)).unwrap_or_else(|_| panic!("the value does not fit in an `u64`"));
                let times_radix = n.checked_mul(u64::try_from(radix).unwrap_or_else(|_| panic!("the value does not fit in an `u64`")));
                if times_radix.is_none() {
                    fits = false;
                    break;
                }
                let sum = nikaia_std::index::or(times_radix, || 0).checked_add(d);
                if sum.is_none() {
                    fits = false;
                    break;
                }
                n = nikaia_std::index::or(sum, || 0);
            }
            if fits && signed && n > 9223372036854775808u64 { fits = false; }
            if fits { magnitude = n; } else { wrong = too_big(); }
        }
    }
    let consumed: i64 = at + first;
    if !wrong.is_empty() { return Number::Refused { message: wrong, consumed }; }
    Number::Taken { magnitude, negative: signed, consumed }
}


// --- parsed_tree.nika ---

pub fn aliases_of(items: &[Spanned<Item>], words: &winnow_grammar::InternerContext) -> collections::BTreeMap<String, String> {
    let mut out: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for item in items.iter() {
        match &item.node {
            Item::Import { path, alias } => {
                let alias = *alias;
                if path.len() == 1 && alias.is_some() {
                    let package = *nikaia_std::index::get(&path, 0);
                    let name = nikaia_std::index::or(alias, || package.into());
                    out.insert(words.resolve(name).to_owned(), words.resolve(package).to_owned());
                }
            },
            _ => { },
        }
    }
    out
}

fn grown(ty: &Type, vec: winnow_grammar::Symbol) -> Type {
    let mut generics: Vec<Type> = vec![];
    for g in ty.generics.iter() { generics.push(grown(g, vec)); }
    let copy = ty.clone();
    if ty.is_slice && !ty.is_mut { return Type { name: vec, generics: generics, is_view: false, is_slice: false, either: false, ..copy }; }
    Type { generics: generics, ..copy }
}

fn grown_fields(fields: &[FieldDef], vec: winnow_grammar::Symbol) -> Vec<FieldDef> {
    let mut out: Vec<FieldDef> = vec![];
    for field in fields.iter() {
        let copy = field.clone();
        out.push(FieldDef { ty: grown(&field.ty, vec), ..copy });
    }
    out
}

pub fn grown_items(items: &[Spanned<Item>], vec: winnow_grammar::Symbol) -> Vec<Spanned<Item>> {
    let mut out: Vec<Spanned<Item>> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, generics, fields, is_public, is_extern } => {
                let is_extern = *is_extern; let is_public = *is_public; let name = *name;
                let copy = item.clone();
                out.push(Spanned { node: Item::Struct { name, generics: generics.to_owned(), fields: grown_fields(fields, vec), is_public, is_extern }, ..copy });
            },
            Item::Enum { name, variants, is_public, is_extern } => {
                let is_extern = *is_extern; let is_public = *is_public; let name = *name;
                let mut grown_variants: Vec<EnumVariant> = vec![];
                for variant in variants.iter() {
                    let copy = variant.clone();
                    grown_variants.push(EnumVariant { fields: grown_variant(&variant.fields, vec), ..copy });
                }
                let copy = item.clone();
                out.push(Spanned { node: Item::Enum { name, variants: grown_variants, is_public, is_extern }, ..copy });
            },
            _ => { out.push(item.clone()); },
        }
    }
    out
}

fn grown_variant(fields: &VariantFields, vec: winnow_grammar::Symbol) -> VariantFields {
    match fields {
        VariantFields::Unit => return VariantFields::Unit,
        VariantFields::Tuple(types) => {
            let mut out: Vec<Type> = vec![];
            for ty in types.iter() { out.push(grown(ty, vec)); }
            return VariantFields::Tuple(out);
        },
        VariantFields::Named(named) => return VariantFields::Named(grown_fields(named, vec)),
    }
}


// --- parsed_view.nika ---

#[derive(Debug, Clone)]
pub struct ParsedView<'a, 'a1, 'a2, 'a3, 'a4, 'a5> {
    pub words: &'a winnow_grammar::InternerContext,
    pub aliases: &'a1 collections::BTreeMap<String, String>,
    pub items: &'a2 Vec<Spanned<Item>>,
    pub package: Option<&'a3 str>,
    pub spans: &'a4 collections::BTreeMap<u32, Span>,
    pub viewed_arms: &'a5 collections::BTreeSet<i64>,
}

impl<'a> ParsedView<'a, 'a, 'a, 'a, 'a, 'a> {
    pub fn text(&self, sym: winnow_grammar::Symbol) -> String { self.words.resolve(sym).to_owned() }
    pub fn unaliased(&self, name: &str) -> String { unaliased_in(self.aliases, name) }
}


// --- paths.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Export {
    pub at: String,
    pub prefix: String,
    pub name: Option<Named>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Named {
    pub name: String,
    pub alias: String,
}

pub fn after(path: &str, word: &str) -> Option<String> {
    if path == word { return Some(String::from("")); }
    let lead = format!("{}::", word);
    if !path.starts_with(&lead) { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(path.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(lead.chars());
    Some(slice(&c, w.len() as i64, c.len() as i64))
}

pub fn module_of(relative: &str) -> Option<String> {
    if !relative.starts_with("src/") || !relative.ends_with(".rs") { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(relative.chars());
    let inside = slice(&c, 4, c.len() as i64 - 3);
    if inside == "lib" { return Some(String::from("")); }
    if inside == "main" || inside.starts_with("bin/") { return None; }
    let mut path = inside.to_owned();
    if inside == "mod" { path = String::from(""); } else if inside.ends_with("/mod") {
        let i: Vec<scalar> = nikaia_std::list::chars(inside.chars());
        path = slice(&i, 0, i.len() as i64 - 4);
    }
    let mut out: String = String::from("");
    for part in path.split('/') { out = joined(&out, part); }
    Some(out)
}

pub fn joined(at: &str, name: &str) -> String {
    if at.is_empty() { return name.to_owned(); }
    if name.is_empty() { return at.to_owned(); }
    format!("{}::{}", at, name)
}

pub fn exported(at: &str, text: &str) -> Vec<Export> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = text.trim();
    let c: Vec<scalar> = nikaia_std::list::chars(whole.chars());
    let mut out: Vec<Export> = vec![];
    let open = find_text(&c, 0, "::{");
    if open >= 0 && whole.ends_with('}') {
        let prefix = slice(&c, 0, open);
        let inside = slice(&c, open + 3, c.len() as i64 - 1);
        for one in split_top_level(&inside) { if !one.is_empty() { out.push(Export { at: at.to_owned(), prefix: prefix.to_owned(), name: Some(named(&one)) }); } }
        return out;
    }
    if whole.ends_with("::*") {
        out.push(Export { at: at.to_owned(), prefix: slice(&c, 0, c.len() as i64 - 3), name: None });
        return out;
    }
    let mut path = whole.to_owned();
    let mut alias: Option<String> = None;
    let space = find_text(&c, 0, " as ");
    if space >= 0 {
        let before = __keep_frame.put(slice(&c, 0, space));
        let after_it = __keep_frame.put(slice(&c, space + 4, c.len() as i64));
        path = before.trim().to_owned();
        alias = Some(after_it.trim().to_owned());
    }
    let p: Vec<scalar> = nikaia_std::list::chars(path.chars());
    let cut = find_last_text(&p, "::");
    let mut prefix: String = String::from("");
    let mut name = path.to_owned();
    if cut >= 0 {
        prefix = slice(&p, 0, cut);
        let rest = __keep_frame.put(slice(&p, cut + 2, p.len() as i64));
        name = rest.trim().to_owned();
    }
    let offered = nikaia_std::index::or(alias, || name.to_owned().into());
    out.push(Export { at: at.to_owned(), prefix, name: Some(Named { name, alias: offered }) });
    out
}

pub fn named(written: &str) -> Named {
    let one = written.trim();
    let c: Vec<scalar> = nikaia_std::list::chars(one.chars());
    let space = find_text(&c, 0, " as ");
    if space < 0 { return Named { name: one.to_owned(), alias: one.to_owned() }; }
    let before = slice(&c, 0, space);
    let after_it = slice(&c, space + 4, c.len() as i64);
    Named { name: before.trim().to_owned(), alias: after_it.trim().to_owned() }
}

pub fn bases(export: &Export) -> Vec<String> {
    let prefix = export.prefix.trim();
    let mut out: Vec<String> = vec![];
    let from_root = after(prefix, "crate");
    if from_root.is_some() {
        out.push(nikaia_std::index::or(from_root, || "".into()));
        return out;
    }
    let from_here = after(prefix, "self");
    if from_here.is_some() {
        out.push(joined(&export.at, nikaia_std::index::or(from_here.as_deref(), || "")));
        return out;
    }
    let from_up = after(prefix, "super");
    if from_up.is_some() {
        let a: Vec<scalar> = nikaia_std::list::chars(export.at.chars());
        let cut = find_last_text(&a, "::");
        let mut parent: String = String::from("");
        if cut >= 0 { parent = slice(&a, 0, cut); }
        out.push(joined(&parent, nikaia_std::index::or(from_up.as_deref(), || "")));
        return out;
    }
    let here = joined(&export.at, prefix);
    let root = prefix.to_owned();
    if here != root { out.push(here); }
    out.push(root);
    out
}

pub fn split_top_level(text: &str) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in text.chars() {
        if c == '<' || c == '(' || c == '[' { depth += 1; } else if c == '>' || c == ')' || c == ']' { depth -= 1; } else if c == ',' && depth == 0 {
            out.push(current.trim().to_owned());
            current = String::from("");
            continue;
        }
        current.push(c);
    }
    let last = current.trim();
    if !last.is_empty() { out.push(last.to_owned()); }
    out
}

fn find_last_text(c: &[scalar], word: &str) -> i64 {
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let mut found: i64 = -1;
    if w.is_empty() || (c.len() as i64) < w.len() as i64 { return found; }
    for at in 0..c.len() as i64 - w.len() as i64 + 1 { if stands_at(c, at, &w) { found = at; } }
    found
}

fn stands_at(c: &[scalar], at: i64, w: &[scalar]) -> bool {
    for k in 0..w.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { return false; } }
    true
}


// --- proofs_book.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PbLine {
    pub key: String,
    pub kind: String,
    pub body: String,
}

pub fn pb_read(text: &str, long: &impl Fn(&str) -> Option<String>) -> Vec<PbLine> {
    let mut out: Vec<PbLine> = vec![];
    for line in text.lines() {
        if line.starts_with('#') || line.trim().is_empty() { continue; }
        let words: Vec<&str> = line.split(' ').collect::<Vec<_>>();
        if words.len() == 4 && *nikaia_std::index::get(&words, 1) == "invariant" {
            out.push(PbLine { key: (*nikaia_std::index::get(&words, 0)).to_owned(), kind: (*nikaia_std::index::get(&words, 1)).to_owned(), body: format!("{} {}", *nikaia_std::index::get(&words, 2), *nikaia_std::index::get(&words, 3)) });
            continue;
        }
        if words.len() != 3 { continue; }
        let key = (*nikaia_std::index::get(&words, 0)).to_owned();
        let kind = (*nikaia_std::index::get(&words, 1)).to_owned();
        let body = (*nikaia_std::index::get(&words, 2)).to_owned();
        if kind == "proved" && body == "@" {
            let held = match long(&key) { Some(__nikaia_value) => __nikaia_value, None => continue };
            out.push(PbLine { key, kind, body: held.trim().to_owned() });
        } else if kind == "proved" || kind == "refuted" || kind == "unknown" { out.push(PbLine { key, kind, body }); }
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PbRendered {
    pub text: String,
    pub long: collections::BTreeMap<String, String>,
}

pub fn pb_render(entries: &[PbLine], limit: i64) -> PbRendered {
    let mut out: String = String::from("# AUTO-GENERATED by `nikaia`. Commit this file like a lockfile.\n# The prover's answers, one per question it asks: the SHA-256 of the\n# question in normal form, and `proved` with its certificate,\n# `refuted` with its model, or `unknown` with the solver that gave up.\n# Every entry is checked when it is read; a wrong one is searched again.\n");
    let mut long: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for entry in entries.iter() {
        if entry.kind == "proved" && (entry.body.len() as i64) > limit {
            long.insert(entry.key.to_owned(), entry.body.to_owned());
            out.push_str(&format!("{} proved @\n", entry.key));
        } else { out.push_str(&format!("{} {} {}\n", entry.key, entry.kind, entry.body)); }
    }
    PbRendered { text: out, long }
}


// --- prove_terms.nika ---

pub fn lin_term(expr: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, pinned: &impl Fn(&str) -> Option<i64>, out: &mut Vec<SolverTerm>) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative, .. } => {
            let negative = *negative; let value = *value;
            let n = match literal_value(value, negative) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Int(n), out))
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let text = words.resolve(name);
            if !var(text) {
                let known = match pinned(text) { Some(__nikaia_value) => __nikaia_value, None => return None };
                return Some(built(SolverTerm::Int(known), out));
            }
            Some(built(SolverTerm::Var(text.to_owned()), out))
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "len" { return None; }
            let list = match path_of(receiver, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let length = format!("{}.len()", list);
            if !var(&length) { return None; }
            Some(built(SolverTerm::Var(length), out))
        },
        Expr::Field { .. } => {
            let path = match path_of(expr, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if !var(&path) { return None; }
            Some(built(SolverTerm::Var(path), out))
        },
        Expr::Call { .. } => {
            let name = call_result_name(expr);
            let ran = pinned(&name);
            if ran.is_some() { return Some(built(SolverTerm::Int(nikaia_std::index::or(ran, || 0)), out)); }
            if !var(&name) { return None; }
            Some(built(SolverTerm::Var(name), out))
        },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if *op != UnaryOp::Neg { return None; }
            let a = match lin_term(expr, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Neg(a), out))
        },
        Expr::Cast { expr, ty, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if !ty.generics.is_empty() || !is_whole_number(words.resolve(ty.name)) { return None; }
            lin_term(expr, words, var, pinned, out)
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let l = match lin_term(lhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let r = match lin_term(rhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match op {
                BinaryOp::Add => Some(built(SolverTerm::Add(l, r), out)),
                BinaryOp::Sub => Some(built(SolverTerm::Sub(l, r), out)),
                BinaryOp::Mul => {
                    if constant_at(l, &out).is_none() && constant_at(r, &out).is_none() { return None; }
                    Some(built(SolverTerm::Mul(l, r), out))
                },
                BinaryOp::Div => {
                    let y = match constant_at(r, &out) { Some(__nikaia_value) => __nikaia_value, None => match pinned(&divisor_name(rhs)) { Some(__nikaia_value) => __nikaia_value, None => return None } };
                    let known = constant_at(l, &out);
                    if known.is_some() {
                        let q = match nikaia_std::index::or(known, || 0).checked_div(y) { Some(__nikaia_value) => __nikaia_value, None => return None };
                        return Some(built(SolverTerm::Int(q), out));
                    }
                    if y <= 0 { return None; }
                    Some(built(SolverTerm::Quot(l, y), out))
                },
                BinaryOp::Rem => {
                    let y = match constant_at(r, &out) { Some(__nikaia_value) => __nikaia_value, None => match pinned(&divisor_name(rhs)) { Some(__nikaia_value) => __nikaia_value, None => return None } };
                    let known = constant_at(l, &out);
                    if known.is_some() {
                        let m = match nikaia_std::index::or(known, || 0).checked_rem(y) { Some(__nikaia_value) => __nikaia_value, None => return None };
                        return Some(built(SolverTerm::Int(m), out));
                    }
                    if y <= 0 { return None; }
                    let q = built(SolverTerm::Quot(l, y), out);
                    let k = built(SolverTerm::Int(y), out);
                    let kq = built(SolverTerm::Mul(k, q), out);
                    Some(built(SolverTerm::Sub(l, kq), out))
                },
                _ => None,
            }
        },
        _ => None,
    }
}

pub fn divisor_name(divisor: &Expr) -> String { format!("divisor@{}", node_key(divisor)) }

pub fn call_result_name(call: &Expr) -> String { format!("result@{}", node_key(call)) }

pub fn claim_term(expr: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, pinned: &impl Fn(&str) -> Option<i64>, out: &mut Vec<SolverTerm>) -> Option<i64> {
    match expr {
        Expr::LitBool(b, _) => { let b = *b; Some(built(SolverTerm::Bool(b), out)) },
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if *op != UnaryOp::Not { return None; }
            let a = match claim_term(expr, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            Some(built(SolverTerm::Not(a), out))
        },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); match op {
            BinaryOp::And => {
                let l = match claim_term(lhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let r = match claim_term(rhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                Some(built(SolverTerm::And(vec![l, r]), out))
            },
            BinaryOp::Or => {
                let l = match claim_term(lhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let r = match claim_term(rhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
                Some(built(SolverTerm::Or(vec![l, r]), out))
            },
            BinaryOp::Lt => compared(*op, lhs, rhs, words, var, pinned, out),
            BinaryOp::Le => compared(*op, lhs, rhs, words, var, pinned, out),
            BinaryOp::Gt => compared(*op, lhs, rhs, words, var, pinned, out),
            BinaryOp::Ge => compared(*op, lhs, rhs, words, var, pinned, out),
            BinaryOp::Eq => compared(*op, lhs, rhs, words, var, pinned, out),
            BinaryOp::Ne => compared(*op, lhs, rhs, words, var, pinned, out),
            _ => None,
        } },
        _ => None,
    }
}

fn compared(op: BinaryOp, lhs: &Expr, rhs: &Expr, words: &winnow_grammar::InternerContext, var: &impl Fn(&str) -> bool, pinned: &impl Fn(&str) -> Option<i64>, out: &mut Vec<SolverTerm>) -> Option<i64> {
    let a = match lin_term(lhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let b = match lin_term(rhs, words, var, pinned, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(match op {
        BinaryOp::Lt => built(SolverTerm::Lt(a, b), out),
        BinaryOp::Le => built(SolverTerm::Le(a, b), out),
        BinaryOp::Gt => built(SolverTerm::Gt(a, b), out),
        BinaryOp::Ge => built(SolverTerm::Ge(a, b), out),
        BinaryOp::Eq => built(SolverTerm::Eq(a, b), out),
        _ => built(SolverTerm::Ne(a, b), out),
    })
}

fn built(node: SolverTerm, out: &mut Vec<SolverTerm>) -> i64 {
    out.push(node);
    out.len() as i64 - 1
}

fn constant_at(at: i64, out: &[SolverTerm]) -> Option<i64> {
    match nikaia_std::index::get(&out, nikaia_std::index::at(at)) {
        SolverTerm::Int(n) => { let n = *n; Some(n) },
        SolverTerm::Neg(a) => {
            let a = *a;
            let v = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            v.checked_neg()
        },
        SolverTerm::Add(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_add(y)
        },
        SolverTerm::Sub(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_sub(y)
        },
        SolverTerm::Mul(a, b) => {
            let a = *a; let b = *b;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match constant_at(b, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_mul(y)
        },
        SolverTerm::Quot(a, k) => {
            let a = *a; let k = *k;
            let x = match constant_at(a, out) { Some(__nikaia_value) => __nikaia_value, None => return None };
            x.checked_div(k)
        },
        _ => None,
    }
}

fn literal_value(value: u64, negative: bool) -> Option<i64> {
    if value <= 9223372036854775807u64 {
        let n = i64::try_from(value).unwrap_or_else(|_| panic!("the value does not fit in an `i64`"));
        if negative { return Some(-n); }
        return Some(n);
    }
    if negative && value == 9223372036854775808u64 { return Some(-9223372036854775808i64); }
    None
}

pub fn nothing_pinned(name: &str) -> Option<i64> { None }

pub fn folded_whole(expr: &Expr, words: &winnow_grammar::InternerContext, pinned: &impl Fn(&str) -> Option<i64>) -> Option<i64> {
    match expr {
        Expr::LitInt { value, negative, .. } => { let negative = *negative; let value = *value; literal_value(value, negative) },
        Expr::Variable(name, _) => { let name = *name; pinned(words.resolve(name)) },
        Expr::Call { .. } => pinned(&call_result_name(expr)),
        Expr::Unary { op, expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if *op != UnaryOp::Neg { return None; }
            let v = match folded_whole(expr, words, pinned) { Some(__nikaia_value) => __nikaia_value, None => return None };
            v.checked_neg()
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let x = match folded_whole(lhs, words, pinned) { Some(__nikaia_value) => __nikaia_value, None => return None };
            let y = match folded_whole(rhs, words, pinned) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match op {
                BinaryOp::Add => x.checked_add(y),
                BinaryOp::Sub => x.checked_sub(y),
                BinaryOp::Mul => x.checked_mul(y),
                BinaryOp::Div => x.checked_div(y),
                BinaryOp::Rem => x.checked_rem(y),
                _ => None,
            }
        },
        _ => None,
    }
}


// --- prove_text.nika ---

pub fn rust_of(id: i64, term_of: &impl Fn(i64) -> SolverTerm, escape: &impl Fn(&str) -> String) -> String {
    match term_of(id) {
        SolverTerm::Bool(b) => if b { String::from("true") } else { String::from("false") },
        SolverTerm::Int(n) => format!("({}i128)", n),
        SolverTerm::Var(ref name) => rust_of_name(name, escape),
        SolverTerm::Neg(a) => format!("(-{})", rust_of(a, term_of, escape)),
        SolverTerm::Not(a) => format!("(!{})", rust_of(a, term_of, escape)),
        SolverTerm::Add(a, b) => format!("({} + {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Sub(a, b) => format!("({} - {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Mul(a, b) => format!("({} * {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Quot(a, k) => format!("({} / ({}i128))", rust_of(a, term_of, escape), k),
        SolverTerm::Le(a, b) => format!("({} <= {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Lt(a, b) => format!("({} < {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Ge(a, b) => format!("({} >= {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Gt(a, b) => format!("({} > {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Eq(a, b) => format!("({} == {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::Ne(a, b) => format!("({} != {})", rust_of(a, term_of, escape), rust_of(b, term_of, escape)),
        SolverTerm::And(ref parts) => rust_joined(" && ", parts, "true", term_of, escape),
        SolverTerm::Or(ref parts) => rust_joined(" || ", parts, "false", term_of, escape),
        _ => String::from(""),
    }
}

fn rust_joined(op: &str, parts: &[i64], empty: &str, term_of: &impl Fn(i64) -> SolverTerm, escape: &impl Fn(&str) -> String) -> String {
    if parts.is_empty() { return empty.to_owned(); }
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        written.push(rust_of(part, term_of, escape));
    }
    format!("({})", written.join(op))
}

pub fn rust_of_name(name: &str, escape: &impl Fn(&str) -> String) -> String {
    if name.ends_with(".len()") {
        let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
        let mut base: String = String::from("");
        for k in 0..c.len() as i64 - 6 { base.push(*nikaia_std::index::get(&c, (k) as usize)); }
        return format!("({}.len() as i128)", escape(&base));
    }
    format!("({}.clone() as i128)", escape(name))
}

pub fn term_text(id: i64, term_of: &impl Fn(i64) -> SolverTerm) -> String { term_whole(id, true, term_of) }

pub fn term_ledger_text(id: i64, term_of: &impl Fn(i64) -> SolverTerm) -> String { term_whole(id, false, term_of) }

fn term_rank(term: &SolverTerm, arrow: bool) -> i64 {
    match term {
        SolverTerm::Or(parts) => if arrow && parts.len() == 2 { 0 } else { 1 },
        SolverTerm::And(_) => 2,
        SolverTerm::Le(_, _) => 3,
        SolverTerm::Lt(_, _) => 3,
        SolverTerm::Ge(_, _) => 3,
        SolverTerm::Gt(_, _) => 3,
        SolverTerm::Eq(_, _) => 3,
        SolverTerm::Ne(_, _) => 3,
        SolverTerm::Add(_, _) => 4,
        SolverTerm::Sub(_, _) => 4,
        SolverTerm::Mul(_, _) => 5,
        SolverTerm::Quot(_, _) => 5,
        SolverTerm::Neg(_) => 6,
        SolverTerm::Not(_) => 6,
        _ => 7,
    }
}

fn term_inner(id: i64, at_least: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let text = term_whole(id, arrow, term_of);
    if term_rank(&term_of(id), arrow) < at_least { return format!("({})", text); }
    text
}

fn term_binary(op: &str, a: i64, b: i64, r: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String { format!("{} {} {}", term_inner(a, r, arrow, term_of), op, term_inner(b, r + 1, arrow, term_of)) }

fn term_joined(op: &str, parts: &[i64], r: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        written.push(term_inner(part, r + 1, arrow, term_of));
    }
    written.join(op)
}

fn term_whole(id: i64, arrow: bool, term_of: &impl Fn(i64) -> SolverTerm) -> String {
    let term = term_of(id);
    let r = term_rank(&term, arrow);
    match term {
        SolverTerm::Bool(b) => if b { String::from("true") } else { String::from("false") },
        SolverTerm::Int(n) => format!("{}", n),
        SolverTerm::Var(ref name) => name.to_owned(),
        SolverTerm::Neg(a) => format!("-{}", term_inner(a, r, arrow, term_of)),
        SolverTerm::Not(a) => format!("!{}", term_inner(a, r, arrow, term_of)),
        SolverTerm::Add(a, b) => term_binary("+", a, b, r, arrow, term_of),
        SolverTerm::Sub(a, b) => term_binary("-", a, b, r, arrow, term_of),
        SolverTerm::Mul(a, b) => term_binary("*", a, b, r, arrow, term_of),
        SolverTerm::Quot(a, k) => format!("{} / {}", term_inner(a, r, arrow, term_of), k),
        SolverTerm::Le(a, b) => term_binary("<=", a, b, r, arrow, term_of),
        SolverTerm::Lt(a, b) => term_binary("<", a, b, r, arrow, term_of),
        SolverTerm::Ge(a, b) => term_binary(">=", a, b, r, arrow, term_of),
        SolverTerm::Gt(a, b) => term_binary(">", a, b, r, arrow, term_of),
        SolverTerm::Eq(a, b) => term_binary("==", a, b, r, arrow, term_of),
        SolverTerm::Ne(a, b) => term_binary("!=", a, b, r, arrow, term_of),
        SolverTerm::Or(ref parts) => {
            if arrow && parts.len() == 2 {
                match term_of(*nikaia_std::index::get(&parts, 0)) {
                    SolverTerm::Not(taken) => { return format!("{} → {}", term_inner(taken, 1, arrow, term_of), term_inner(*nikaia_std::index::get(&parts, 1), 1, arrow, term_of)); },
                    _ => { },
                }
            }
            term_joined(" || ", parts, r, arrow, term_of)
        },
        SolverTerm::And(ref parts) => term_joined(" && ", parts, r, arrow, term_of),
        _ => String::from(""),
    }
}

pub fn shown(values: &collections::BTreeMap<String, i64>) -> String {
    if values.is_empty() { return String::from("no value of its own; the claim is false as written"); }
    let mut said: Vec<String> = vec![];
    for (name, value) in values.iter() {
        let value = nikaia_std::num::value(value);
        said.push(format!("`{}` is {}", name, value));
    }
    said.join(", ")
}

pub fn lowered_first(text: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    if c.is_empty() { return String::from(""); }
    let mut head: String = String::from("");
    head.push(*nikaia_std::index::get(&c, 0));
    let mut out = head.to_lowercase();
    for k in 1..c.len() as i64 { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    out
}

pub fn has_a_length(ty: &str) -> bool { matches!(ty, "Vec" | "String" | "str" | "Array") }


// --- prover_arena.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TermArena {
    pub nodes: Vec<SolverTerm>,
}

impl TermArena {
    pub fn empty() -> TermArena { TermArena { nodes: vec![] } }
    fn push(&mut self, node: SolverTerm) -> i64 {
        self.nodes.push(node);
        self.nodes.len() as i64 - 1
    }
    pub fn at(&self, id: i64) -> SolverTerm { (*nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id))).clone() }
    pub fn boolean(&mut self, value: bool) -> i64 { self.push(SolverTerm::Bool(value)) }
    pub fn int(&mut self, value: i64) -> i64 { self.push(SolverTerm::Int(value)) }
    pub fn var(&mut self, name: &str) -> i64 { self.push(SolverTerm::Var(name.to_owned())) }
    pub fn add(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Add(a, b)) }
    pub fn sub(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Sub(a, b)) }
    pub fn neg(&mut self, a: i64) -> i64 { self.push(SolverTerm::Neg(a)) }
    pub fn mul(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Mul(a, b)) }
    pub fn quot(&mut self, a: i64, k: i64) -> i64 { self.push(SolverTerm::Quot(a, k)) }
    pub fn le(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Le(a, b)) }
    pub fn lt(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Lt(a, b)) }
    pub fn ge(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Ge(a, b)) }
    pub fn gt(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Gt(a, b)) }
    pub fn equal(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Eq(a, b)) }
    pub fn unequal(&mut self, a: i64, b: i64) -> i64 { self.push(SolverTerm::Ne(a, b)) }
    pub fn and(&mut self, parts: Vec<i64>) -> i64 { self.push(SolverTerm::And(parts)) }
    pub fn or(&mut self, parts: Vec<i64>) -> i64 { self.push(SolverTerm::Or(parts)) }
    pub fn not(&mut self, a: i64) -> i64 { self.push(SolverTerm::Not(a)) }
    pub fn mentions(&self, id: i64, name: &str) -> bool {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(n) => n == name,
            SolverTerm::Neg(a) => { let a = *a; self.mentions(a, name) },
            SolverTerm::Not(a) => { let a = *a; self.mentions(a, name) },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Quot(a, _) => { let a = *a; self.mentions(a, name) },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.mentions(a, name) || self.mentions(b, name) },
            SolverTerm::And(parts) => self.any_mentions(parts, name),
            SolverTerm::Or(parts) => self.any_mentions(parts, name),
            _ => false,
        }
    }
    fn any_mentions(&self, parts: &[i64], name: &str) -> bool {
        for part in parts.iter() {
            let part = nikaia_std::num::value(part);
            if self.mentions(part, name) { return true; }
        }
        false
    }
    pub fn variables(&self, id: i64, names: &mut collections::BTreeSet<String>) {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(name) => { names.insert(name.to_owned()); },
            SolverTerm::Neg(a) => { let a = *a; self.variables(a, names); },
            SolverTerm::Not(a) => { let a = *a; self.variables(a, names); },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Quot(a, _) => { let a = *a; self.variables(a, names); },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.both_variables(a, b, names); },
            SolverTerm::And(parts) => {
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    self.variables(part, names);
                }
            },
            SolverTerm::Or(parts) => {
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    self.variables(part, names);
                }
            },
            _ => { },
        }
    }
    fn both_variables(&self, a: i64, b: i64, names: &mut collections::BTreeSet<String>) {
        self.variables(a, names);
        self.variables(b, names);
    }
    pub fn constant(&self, id: i64) -> Option<i64> {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Int(n) => { let n = *n; Some(n) },
            SolverTerm::Neg(a) => {
                let a = *a;
                let v = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                v.checked_neg()
            },
            SolverTerm::Add(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_add(y)
            },
            SolverTerm::Sub(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_sub(y)
            },
            SolverTerm::Mul(a, b) => {
                let a = *a; let b = *b;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.constant(b) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_mul(y)
            },
            SolverTerm::Quot(a, k) => {
                let a = *a; let k = *k;
                let x = match self.constant(a) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_div(k)
            },
            _ => None,
        }
    }
    pub fn int_value(&self, id: i64, values: &collections::BTreeMap<String, i64>) -> Option<i64> {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Int(n) => { let n = *n; Some(n) },
            SolverTerm::Var(name) => {
                let found = match *nikaia_std::index::get(&values, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
                Some(found)
            },
            SolverTerm::Neg(a) => {
                let a = *a;
                let v = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                v.checked_neg()
            },
            SolverTerm::Add(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_add(y)
            },
            SolverTerm::Sub(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_sub(y)
            },
            SolverTerm::Mul(a, b) => {
                let a = *a; let b = *b;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                let y = match self.int_value(b, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_mul(y)
            },
            SolverTerm::Quot(a, k) => {
                let a = *a; let k = *k;
                let x = match self.int_value(a, values) { Some(__nikaia_value) => __nikaia_value, None => return None };
                x.checked_div(k)
            },
            _ => None,
        }
    }
    pub fn substitute(&mut self, id: i64, given: &collections::BTreeMap<String, i64>) -> i64 {
        let node = (*nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id))).clone();
        match node {
            SolverTerm::Var(ref name) => nikaia_std::index::or(given.get(name), || id.into()),
            SolverTerm::Bool(_) => id,
            SolverTerm::Int(_) => id,
            SolverTerm::Neg(a) => {
                let x = self.substitute(a, given);
                self.push(SolverTerm::Neg(x))
            },
            SolverTerm::Not(a) => {
                let x = self.substitute(a, given);
                self.push(SolverTerm::Not(x))
            },
            SolverTerm::Add(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Add(x, y))
            },
            SolverTerm::Sub(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Sub(x, y))
            },
            SolverTerm::Mul(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Mul(x, y))
            },
            SolverTerm::Quot(a, k) => {
                let x = self.substitute(a, given);
                self.push(SolverTerm::Quot(x, k))
            },
            SolverTerm::Le(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Le(x, y))
            },
            SolverTerm::Lt(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Lt(x, y))
            },
            SolverTerm::Ge(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Ge(x, y))
            },
            SolverTerm::Gt(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Gt(x, y))
            },
            SolverTerm::Eq(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Eq(x, y))
            },
            SolverTerm::Ne(a, b) => {
                let x = self.substitute(a, given);
                let y = self.substitute(b, given);
                self.push(SolverTerm::Ne(x, y))
            },
            SolverTerm::And(ref parts) => {
                let mut changed: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    changed.push(self.substitute(part, given));
                }
                self.push(SolverTerm::And(changed))
            },
            SolverTerm::Or(ref parts) => {
                let mut changed: Vec<i64> = vec![];
                for part in parts.iter() {
                    let part = nikaia_std::num::value(part);
                    changed.push(self.substitute(part, given));
                }
                self.push(SolverTerm::Or(changed))
            },
            _ => id,
        }
    }
    pub fn size(&self, id: i64) -> i64 {
        1 + match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Neg(a) => { let a = *a; self.size(a) },
            SolverTerm::Not(a) => { let a = *a; self.size(a) },
            SolverTerm::Add(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Sub(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Mul(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Quot(a, _) => { let a = *a; self.size(a) },
            SolverTerm::Le(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Lt(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Ge(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Gt(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Eq(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::Ne(a, b) => { let a = *a; let b = *b; self.size(a) + self.size(b) },
            SolverTerm::And(parts) => self.parts_size(parts),
            SolverTerm::Or(parts) => self.parts_size(parts),
            _ => 0,
        }
    }
    fn parts_size(&self, parts: &[i64]) -> i64 {
        let mut total: i64 = 0;
        for part in parts.iter() {
            let part = nikaia_std::num::value(part);
            total += self.size(part);
        }
        total
    }
    pub fn text(&self, id: i64) -> String { term_text(id, &|at| { self.at(at) }) }
    pub fn adopt(&mut self, nodes: &[SolverTerm]) -> i64 {
        let base = self.nodes.len() as i64;
        for node in nodes.iter() {
            let moved = match node {
                SolverTerm::Add(a, b) => { let a = *a; let b = *b; SolverTerm::Add(a + base, b + base) },
                SolverTerm::Sub(a, b) => { let a = *a; let b = *b; SolverTerm::Sub(a + base, b + base) },
                SolverTerm::Neg(a) => { let a = *a; SolverTerm::Neg(a + base) },
                SolverTerm::Mul(a, b) => { let a = *a; let b = *b; SolverTerm::Mul(a + base, b + base) },
                SolverTerm::Quot(a, k) => { let a = *a; let k = *k; SolverTerm::Quot(a + base, k) },
                SolverTerm::Le(a, b) => { let a = *a; let b = *b; SolverTerm::Le(a + base, b + base) },
                SolverTerm::Lt(a, b) => { let a = *a; let b = *b; SolverTerm::Lt(a + base, b + base) },
                SolverTerm::Ge(a, b) => { let a = *a; let b = *b; SolverTerm::Ge(a + base, b + base) },
                SolverTerm::Gt(a, b) => { let a = *a; let b = *b; SolverTerm::Gt(a + base, b + base) },
                SolverTerm::Eq(a, b) => { let a = *a; let b = *b; SolverTerm::Eq(a + base, b + base) },
                SolverTerm::Ne(a, b) => { let a = *a; let b = *b; SolverTerm::Ne(a + base, b + base) },
                SolverTerm::And(parts) => SolverTerm::And(moved_by(parts, base)),
                SolverTerm::Or(parts) => SolverTerm::Or(moved_by(parts, base)),
                SolverTerm::Not(a) => { let a = *a; SolverTerm::Not(a + base) },
                _ => node.clone(),
            };
            self.nodes.push(moved);
        }
        self.nodes.len() as i64 - 1
    }
    pub fn is_the_variable(&self, id: i64, name: &str) -> bool {
        match nikaia_std::index::get(&self.nodes, nikaia_std::index::at(id)) {
            SolverTerm::Var(n) => n == name,
            _ => false,
        }
    }
}

fn moved_by(parts: &[i64], base: i64) -> Vec<i64> {
    let mut out: Vec<i64> = vec![];
    for p in parts.iter() {
        let p = nikaia_std::num::value(p);
        out.push(p + base);
    }
    out
}


// --- prover_calls.nika ---

#[derive(Debug, Clone, PartialEq)]
pub struct FreeFunction {
    pub params: Vec<String>,
    pub options: Vec<(String, Expr)>,
    pub can_throw: bool,
    pub whole_result: bool,
}

pub fn free_function(program: &Program, words: &winnow_grammar::InternerContext, wanted: &str) -> Option<FreeFunction> {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, args, config, ret_type, can_throw, .. } => {
                let can_throw = *can_throw; let name = *name;
                if receiver.is_none() && named_as((name).as_ref(), words, wanted) {
                    let mut params: Vec<String> = vec![];
                    for arg in args.iter() { params.push(words.resolve(arg.name).to_owned()); }
                    let mut options: Vec<(String, Expr)> = vec![];
                    for option in config.iter() {
                        params.push(words.resolve(option.name).to_owned());
                        options.push((words.resolve(option.name).to_owned(), option.default.clone()));
                    }
                    return Some(FreeFunction { params, options, can_throw, whole_result: whole_type((ret_type).as_ref(), words) });
                }
            },
            _ => { },
        }
    }
    None
}

pub fn arguments_in_order(function: &FreeFunction, args: &[Expr], config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> Vec<Expr> {
    let mut all: Vec<Expr> = args.to_owned();
    for (option, default) in function.options.iter() {
        let mut value = default.clone();
        for given in config.iter() { if words.resolve(given.name) == option { value = given.value.clone(); } }
        all.push(value);
    }
    all
}

fn named_as(named: Option<&winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, name: &str) -> bool {
    let symbol = match named { Some(__nikaia_value) => __nikaia_value, None => return false };
    words.resolve(*symbol) == name
}

fn whole_type(ty: Option<&Type>, words: &winnow_grammar::InternerContext) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    t.generics.is_empty() && is_whole_number(words.resolve(t.name))
}

pub fn may_throw(call: &Expr, in_throwing: bool, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unaliased: &impl Fn(&str) -> String) -> bool {
    if !in_throwing { return false; }
    let name = match thrower_named(call, words, unaliased) { Some(__nikaia_value) => __nikaia_value, None => return true };
    let function = free_function(program, words, &name);
    if function.is_some() {
        let found = match function { Some(__nikaia_value) => __nikaia_value, None => return true };
        return found.can_throw;
    }
    if own.functions.contains_key(&name) {
        let contract = match *nikaia_std::index::get(&own.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return true };
        return !contract.fails_with.is_empty();
    }
    let contract = match *nikaia_std::index::get(&library.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return true };
    !contract.fails_with.is_empty()
}

fn thrower_named(call: &Expr, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match call {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); match func {
            Expr::Variable(name, _) => { let name = *name; Some(words.resolve(name).to_owned()) },
            Expr::Path(segments, _) => {
                let mut joined: String = String::from("");
                for segment in segments.iter() {
                    let segment = *segment;
                    if !joined.is_empty() { joined.push_str("::"); }
                    joined.push_str(words.resolve(segment));
                }
                Some(unaliased(&joined))
            },
            _ => None,
        } },
        _ => None,
    }
}

pub fn from_outside(expr: &Expr, tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    match expr {
        Expr::Variable(name, _) => {
            let name = *name;
            if tainted.contains(words.resolve(name)) { return true; }
        },
        Expr::Call { func, .. } => {
            let func = nikaia_std::boxed::open(func);
            let source = outside_source_named(func, words);
            if source.is_some() && untrusted(library, nikaia_std::index::or(source.as_deref(), || "")) { return true; }
        },
        _ => { },
    }
    for hole in holes_of(expr) { if from_outside(&hole, tainted, words, library, holes_of) { return true; } }
    match expr {
        Expr::Call { func, args, config, .. } => { let func = nikaia_std::boxed::open(func); from_outside(func, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); from_outside(receiver, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); from_outside(receiver, tainted, words, library, holes_of) || any_from_outside(args, tainted, words, library, holes_of) || config_from_outside(config, tainted, words, library, holes_of) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); from_outside(lhs, tainted, words, library, holes_of) || from_outside(rhs, tainted, words, library, holes_of) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); from_outside(inner, tainted, words, library, holes_of) },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); from_outside(inner, tainted, words, library, holes_of) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); from_outside(base, tainted, words, library, holes_of) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); from_outside(base, tainted, words, library, holes_of) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); from_outside(base, tainted, words, library, holes_of) || from_outside(index, tainted, words, library, holes_of) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); from_outside(start, tainted, words, library, holes_of) || from_outside(end, tainted, words, library, holes_of) },
        Expr::Tuple(parts, _) => any_from_outside(parts, tainted, words, library, holes_of),
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); from_outside(value, tainted, words, library, holes_of) || from_outside(fallback, tainted, words, library, holes_of) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); from_outside(expr, tainted, words, library, holes_of) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); from_outside(cond, tainted, words, library, holes_of) },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            if from_outside(value, tainted, words, library, holes_of) { return true; }
            for arm in arms.iter() { if maybe_from_outside((arm.guard).as_ref(), tainted, words, library, holes_of) || from_outside(&arm.body, tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() { if maybe_from_outside((field.value).as_ref(), tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); from_outside(value, tainted, words, library, holes_of) || from_outside(count, tainted, words, library, holes_of) },
        Expr::ListLit { items, .. } => any_from_outside(items, tainted, words, library, holes_of),
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            if from_outside(base, tainted, words, library, holes_of) { return true; }
            for field in fields.iter() { if maybe_from_outside((field.value).as_ref(), tainted, words, library, holes_of) { return true; } }
            false
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_from_outside((value).as_ref(), tainted, words, library, holes_of) },
        Expr::Select(arms, _) => {
            for arm in arms.iter() { if from_outside(&arm.value, tainted, words, library, holes_of) { return true; } }
            false
        },
        _ => false,
    }
}

fn maybe_from_outside(expr: Option<&Expr>, tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    let present = match expr { Some(__nikaia_value) => __nikaia_value, None => return false };
    from_outside(present, tainted, words, library, holes_of)
}

fn any_from_outside(exprs: &[Expr], tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    for e in exprs.iter() { if from_outside(e, tainted, words, library, holes_of) { return true; } }
    false
}

fn config_from_outside(config: &[ConfigArg], tainted: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext, library: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> bool {
    for c in config.iter() { if from_outside(&c.value, tainted, words, library, holes_of) { return true; } }
    false
}

fn outside_source_named(func: &Expr, words: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(segments, _) => {
            let mut joined: String = String::from("");
            for segment in segments.iter() {
                let segment = *segment;
                if !joined.is_empty() { joined.push_str("::"); }
                joined.push_str(words.resolve(segment));
            }
            Some(joined)
        },
        _ => None,
    }
}

fn untrusted(library: &Ledger, name: &str) -> bool {
    let contract = match *nikaia_std::index::get(&library.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => return false };
    provenance == Provenance::Untrusted
}


// --- prover_claims.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PreClaim {
    pub term: i64,
    pub written: String,
    pub computed: Option<String>,
    pub message: Option<String>,
    pub origin: Option<String>,
    pub site: Option<CarriedFrom>,
}

impl PreClaim {
    pub fn failure(&self, function: &str) -> String {
        let computed = match claim_text_of((self.computed).as_deref()) { Some(__nikaia_value) => __nikaia_value, None => return format!("precondition of `{}`: `{}`", function, self.written) };
        let origin = match claim_text_of((self.origin).as_deref()) { Some(__nikaia_value) => __nikaia_value, None => return format!("precondition of `{}`: `{}`, from `assert({})`", function, computed, self.written) };
        format!("precondition of `{}`: `{}`, from `assert({})` in `{}`", function, computed, self.written, origin)
    }
    pub fn carried_from(&self, site: &CarriedFrom) -> bool {
        let mine = match carried_site_of((self.site).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return false };
        mine == *site
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CarriedFrom {
    pub at: i64,
    pub callee: String,
    pub place: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Precondition {
    pub claims: Vec<PreClaim>,
}

impl Precondition {
    pub fn none() -> Precondition { Precondition { claims: vec![] } }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PostClaim {
    pub term: i64,
    pub written: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SummaryExit {
    pub guard: i64,
    pub value: i64,
    pub term: i64,
    pub written: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SummaryAlt {
    pub guard: i64,
    pub value: i64,
    pub callee: String,
    pub call: String,
    pub why: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Foreign {
    pub params: Vec<String>,
    pub whole_result: bool,
    pub requires: Vec<PreClaim>,
    pub ensures: Vec<PostClaim>,
}

fn claim_text_of(text: Option<&str>) -> Option<String> {
    let t = match text { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(t.to_owned())
}

fn carried_site_of(site: Option<&CarriedFrom>) -> Option<CarriedFrom> {
    let s = match site { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(s.clone())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ForeignShape {
    pub params: Vec<String>,
    pub names: collections::BTreeSet<String>,
    pub whole_result: bool,
}

pub fn foreign_shape(contract: &FnContract) -> ForeignShape {
    let mut shape = ForeignShape { params: vec![], names: collections::BTreeSet::new(), whole_result: false };
    shape.names.insert(result_name());
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return shape };
    for (param, ty) in signature.params.iter() {
        match ty {
            Ty::Named { name, args, view } => {
                let view = *view;
                if args.is_empty() && !view && is_whole_number(name) { shape.names.insert(param.to_owned()); }
                if has_a_length(name) { shape.names.insert(length_of(param)); }
            },
            _ => { },
        }
        shape.params.push(param.to_owned());
    }
    shape.whole_result = whole_result_of((signature.result).as_ref());
    shape
}

fn whole_result_of(result: Option<&Ty>) -> bool {
    let ty = match result { Some(__nikaia_value) => __nikaia_value, None => return false };
    match ty {
        Ty::Named { name, args, view } => { let view = *view; args.is_empty() && !view && is_whole_number(name) },
        _ => false,
    }
}

pub fn foreign_from(contract: &FnContract, shape: ForeignShape, requires: &[i64], ensures: &[i64]) -> Foreign {
    let mut foreign = Foreign { params: shape.params, whole_result: shape.whole_result, requires: vec![], ensures: vec![] };
    for at in 0..requires.len() as i64 {
        let term = *nikaia_std::index::get(&requires, nikaia_std::index::at(at));
        if term < 0 { continue; }
        let written = assert_of(contract, at);
        let text = nikaia_std::index::get(&contract.requires, nikaia_std::index::at(at));
        let mut computed: Option<String> = None;
        if written != *text { computed = Some(text.to_owned()); }
        foreign.requires.push(PreClaim { term, written, computed, message: None, origin: None, site: None });
    }
    for at in 0..ensures.len() as i64 {
        let term = *nikaia_std::index::get(&ensures, nikaia_std::index::at(at));
        if term < 0 { continue; }
        foreign.ensures.push(PostClaim { term, written: assert_of(contract, contract.requires.len() as i64 + at) });
    }
    foreign
}

fn assert_of(contract: &FnContract, at: i64) -> String {
    if at >= contract.from.len() as i64 { return String::from(""); }
    let from = nikaia_std::index::get(&contract.from, nikaia_std::index::at(at));
    if !from.starts_with("assert(") || !from.ends_with(')') { return String::from(""); }
    let c: Vec<scalar> = nikaia_std::list::chars(from.chars());
    let mut inner: String = String::from("");
    for k in 7..c.len() as i64 - 1 { inner.push(*nikaia_std::index::get(&c, (k) as usize)); }
    inner
}


// --- prover_loops.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoopRecord {
    pub start: i64,
    pub problem: LgLoop,
    pub steps: collections::BTreeMap<String, Vec<i64>>,
    pub counter: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LoopFound {
    pub parts: Vec<(i64, String)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LoopPath {
    constraints: Vec<i64>,
    values: collections::BTreeMap<String, i64>,
    unread: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LoopEnd {
    kind: String,
    path: LoopPath,
}

fn loop_paths_most() -> i64 { 32 }

pub fn loop_before_name(name: &str, start: i64) -> String { format!("{}@{}", name, start) }

fn loop_head_name(name: &str, start: i64) -> String { format!("{}#{}", name, start) }

fn loop_after_name(name: &str, start: i64) -> String { format!("{}${}", name, start) }

#[allow(clippy::too_many_arguments)]
pub fn loop_record(arena: &mut TermArena, start: i64, state: &[String], facts: &[i64], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, cond: &Expr, body: &Block, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<LoopRecord> {
    let condition = claim_term(cond, words, &|name| { ints.contains(name) }, pinned, &mut arena.nodes);
    loop_record_of(arena, start, state, facts, ints, pinned, condition, "", -1, body, words, claims, throwing, holes_of)
}

#[allow(clippy::too_many_arguments)]
pub fn loop_record_range(arena: &mut TermArena, start: i64, state: &[String], facts: &[i64], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, counter: &str, low: i64, high: i64, inclusive: bool, body: &Block, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<LoopRecord> {
    let here = arena.var(counter);
    let mut condition = arena.lt(here, high);
    if inclusive { condition = arena.le(here, high); }
    loop_record_of(arena, start, state, facts, ints, pinned, Some(condition), counter, low, body, words, claims, throwing, holes_of)
}

#[allow(clippy::too_many_arguments)]
fn loop_record_of(arena: &mut TermArena, start: i64, outer: &[String], facts: &[i64], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, condition: Option<i64>, counter: &str, low: i64, body: &Block, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<LoopRecord> {
    let mut state = outer.to_owned();
    if counter != "" { state.push(counter.to_owned()); }
    let mut before: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut entry: Vec<i64> = vec![];
    let mut head: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for name in outer.iter() {
        let ghost = arena.var(&loop_before_name(name, start));
        before.insert(name.to_owned(), ghost);
        let here = arena.var(name);
        head.insert(name.to_owned(), here);
        entry.push(arena.equal(here, ghost));
    }
    let mut fixed: Vec<i64> = vec![];
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        fixed.push(arena.substitute(fact, &before));
    }
    if counter != "" {
        let ghost = arena.var(&loop_before_name(counter, start));
        let here = arena.var(counter);
        head.insert(counter.to_owned(), here);
        entry.push(arena.equal(here, ghost));
        let begins = arena.substitute(low, &before);
        fixed.push(arena.equal(ghost, begins));
    }
    let first = LoopPath { constraints: vec![], values: head, unread: collections::BTreeSet::new() };
    let mut ends: Vec<LoopEnd> = vec![];
    let live = match loop_block(arena, body, &vec![first], &mut ends, &state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for path in live.iter() { ends.push(LoopEnd { kind: "turn".to_owned(), path: path.clone() }); }
    if counter != "" {
        let one = arena.int(1);
        let mut stepped: Vec<LoopEnd> = vec![];
        for end in ends.iter() {
            let mut p = end.path.clone();
            if end.kind == "turn" {
                let value = nikaia_std::index::or(*nikaia_std::index::get(&p.values, counter), || arena.var(counter).into());
                let next = arena.add(value, one);
                p.values.insert(counter.to_owned(), next);
            }
            stepped.push(LoopEnd { kind: end.kind.to_owned(), path: p });
        }
        ends = stepped;
    }
    let mut turns: Vec<i64> = vec![];
    let mut exits: Vec<LgExit> = vec![];
    let mut same: Vec<i64> = vec![];
    for name in state.iter() {
        let primed = arena.var(&lg_primed(name));
        let here = arena.var(name);
        same.push(arena.equal(primed, here));
    }
    let c = nikaia_std::index::or(condition, || -1);
    if c >= 0 {
        let not_c = arena.not(c);
        same.insert(0, not_c);
    }
    exits.push(LgExit { kind: "condition".to_owned(), relation: arena.and(same) });
    let mut steps: collections::BTreeMap<String, Vec<i64>> = collections::BTreeMap::new();
    let mut unsteady: collections::BTreeSet<String> = collections::BTreeSet::new();
    for end in ends.iter() {
        let mut parts = end.path.constraints.to_owned();
        for name in state.iter() {
            let primed = arena.var(&lg_primed(name));
            let value = nikaia_std::index::or(*nikaia_std::index::get(&end.path.values, name), || arena.var(name).into());
            parts.push(arena.equal(primed, value));
            if end.kind == "turn" {
                let delta = loop_constant_step(arena, name, value);
                if delta.is_none() { unsteady.insert(name.to_owned()); } else {
                    let mut seen = nikaia_std::index::or(steps.remove(name), || vec![].into());
                    seen.push(nikaia_std::index::or(delta, || 0));
                    steps.insert(name.to_owned(), seen);
                }
            }
        }
        if end.kind == "turn" { turns.push(arena.and(parts)); } else {
            if c >= 0 { parts.insert(0, c); }
            exits.push(LgExit { kind: end.kind.to_owned(), relation: arena.and(parts) });
        }
    }
    for name in unsteady.iter() { steps.remove(name); }
    let mut step = arena.boolean(false);
    if !turns.is_empty() { step = arena.or(turns); }
    let problem = LgLoop { state: state.to_owned(), fixed, entry, condition, step, exits, goals: vec![] };
    Some(LoopRecord { start, problem, steps, counter: counter.to_owned() })
}

fn loop_constant_step(arena: &mut TermArena, name: &str, value: i64) -> Option<i64> {
    let here = arena.var(name);
    let difference = arena.sub(value, here);
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(difference, &mut read);
    let mut low: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut high: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut k = 0;
    for n in read.iter() {
        low.insert(n.to_owned(), 3 + 7 * k);
        high.insert(n.to_owned(), 11 + 13 * k);
        k += 1;
    }
    let a = match arena.int_value(difference, &low) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let b = match arena.int_value(difference, &high) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if a != b { return None; }
    Some(a)
}

fn loop_read(arena: &mut TermArena, expr: &Expr, path: &LoopPath, ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, words: &winnow_grammar::InternerContext, claim: bool) -> Option<i64> {
    let mut term: Option<i64> = None;
    if claim { term = claim_term(expr, words, &|name| { path.values.contains_key(name) || ints.contains(name) && !path.unread.contains(name) }, pinned, &mut arena.nodes); } else { term = lin_term(expr, words, &|name| { path.values.contains_key(name) || ints.contains(name) && !path.unread.contains(name) }, pinned, &mut arena.nodes); }
    let t = match term { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(arena.substitute(t, &path.values))
}

fn loop_forget(arena: &mut TermArena, path: &mut LoopPath, name: &str) {
    let fresh = arena.var(&format!("{}~{}", name, arena.nodes.len() as i64));
    path.values.insert(name.to_owned(), fresh);
}

#[allow(clippy::too_many_arguments)]
fn loop_block(arena: &mut TermArena, block: &Block, first: &[LoopPath], ends: &mut Vec<LoopEnd>, state: &[String], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<Vec<LoopPath>> {
    let mut live = first.to_owned();
    for stmt in block.stmts.iter() {
        let mut next: Vec<LoopPath> = vec![];
        for path in live.iter() {
            let mut p = path.clone();
            let mut ended: String = String::from("");
            let mut keep = true;
            match &stmt.node {
                Stmt::Break => { ended = String::from("break"); },
                Stmt::Continue => { ended = String::from("turn"); },
                Stmt::Return(_) => { ended = String::from("return"); },
                Stmt::Let { names, value, .. } => {
                    if leaves_stmt(&stmt.node, throwing, holes_of, true) { return None; }
                    for n in assigned_in_statement(&stmt.node, words) { if p.values.contains_key(&n) { loop_forget(arena, &mut p, &n); } }
                    let mut term: Option<i64> = None;
                    if names.len() == 1 { term = loop_read(arena, value, &p, ints, pinned, words, false); }
                    for name in names.iter() {
                        let name = *name;
                        let n = words.resolve(name).to_owned();
                        if nikaia_std::list::contains(&state, &n) { return None; }
                        p.values.remove(&n);
                        p.unread.insert(n.to_owned());
                    }
                    if term.is_some() {
                        let n = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
                        p.unread.remove(&n);
                        p.values.insert(n, nikaia_std::index::or(term, || 0));
                    }
                },
                Stmt::Assign { target, op, value } => {
                    if leaves_stmt(&stmt.node, throwing, holes_of, true) { return None; }
                    let name = match target {
                        Expr::Variable(s, _) => { let s = *s; words.resolve(s).to_owned() },
                        _ => "".to_owned(),
                    };
                    if name != "" && p.values.contains_key(&name) {
                        let read = loop_read(arena, value, &p, ints, pinned, words, false);
                        let old = nikaia_std::index::or(*nikaia_std::index::get(&p.values, &name), || arena.var(&name).into());
                        let mut updated: Option<i64> = None;
                        if read.is_some() {
                            let r = nikaia_std::index::or(read, || 0);
                            if op.is_none() { updated = Some(r); } else {
                                updated = match nikaia_std::index::or(op, || BinaryOp::Mul) {
                                    BinaryOp::Add => Some(arena.add(old, r)),
                                    BinaryOp::Sub => Some(arena.sub(old, r)),
                                    _ => None,
                                };
                            }
                        }
                        if updated.is_none() { loop_forget(arena, &mut p, &name); } else { p.values.insert(name.to_owned(), nikaia_std::index::or(updated, || 0)); }
                    }
                },
                Stmt::Expr(expr) => {
                    let handled = match loop_expr_stmt(arena, expr, &stmt.span, &p, &mut next, ends, state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    if handled { keep = false; } else {
                        if leaves_stmt(&stmt.node, throwing, holes_of, true) { return None; }
                        for n in assigned_in_statement(&stmt.node, words) { if p.values.contains_key(&n) { loop_forget(arena, &mut p, &n); } }
                    }
                },
                _ => {
                    if leaves_stmt(&stmt.node, throwing, holes_of, true) { return None; }
                    for n in assigned_in_statement(&stmt.node, words) { if p.values.contains_key(&n) { loop_forget(arena, &mut p, &n); } }
                },
            }
            if ended != "" { ends.push(LoopEnd { kind: ended, path: p }); } else if keep { next.push(p); }
        }
        live = next;
        if (live.len() as i64 + ends.len() as i64) > loop_paths_most() { return None; }
    }
    Some(live)
}

#[allow(clippy::too_many_arguments)]
fn loop_expr_stmt(arena: &mut TermArena, expr: &Expr, span: &Span, path: &LoopPath, next: &mut Vec<LoopPath>, ends: &mut Vec<LoopEnd>, state: &[String], ints: &collections::BTreeSet<String>, pinned: &impl Fn(&str) -> Option<i64>, words: &winnow_grammar::InternerContext, claims: &collections::BTreeSet<(i64, i64)>, throwing: &impl Fn(&Expr) -> bool, holes_of: &impl Fn(&Expr) -> Vec<Expr>) -> Option<bool> {
    match expr {
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            let c = loop_read(arena, cond, path, ints, pinned, words, true);
            let mut yes = path.clone();
            let mut no = path.clone();
            if c.is_some() {
                yes.constraints.push(nikaia_std::index::or(c, || 0));
                no.constraints.push(arena.not(nikaia_std::index::or(c, || 0)));
            }
            let after_yes = match loop_block(arena, then_branch, &vec![yes], ends, state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            next.extend(after_yes);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => {
                next.push(no);
                return Some(true);
            } };
            let after_no = match loop_block(arena, otherwise, &vec![no], ends, state, ints, pinned, words, claims, throwing, holes_of) { Some(__nikaia_value) => __nikaia_value, None => return None };
            next.extend(after_no);
            return Some(true);
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if prover_an_assert_call(func, args, &span, claims) {
                let mut p = path.clone();
                let c = loop_read(arena, nikaia_std::index::get(&args, 0), &p, ints, pinned, words, true);
                if c.is_some() { p.constraints.push(nikaia_std::index::or(c, || 0)); }
                next.push(p);
                return Some(true);
            }
            return Some(false);
        },
        _ => return Some(false),
    }
}

fn loop_candidates(arena: &mut TermArena, record: &LoopRecord) -> Vec<(i64, String)> {
    let mut found: Vec<(i64, String)> = vec![];
    let start = record.start;
    let mut steady: Vec<(String, i64)> = vec![];
    for (name, deltas) in record.steps.iter() {
        if deltas.is_empty() { continue; }
        let k = *nikaia_std::index::get(&deltas, 0);
        let mut one = true;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d != k { one = false; }
        }
        if one { steady.push((name.to_owned(), k)); }
    }
    for (name, k) in steady.iter() {
        let k = nikaia_std::num::value(k);
        let here = arena.var(name);
        let before = arena.var(&loop_before_name(name, start));
        if k == 0 { found.push((arena.equal(here, before), "closed forms".to_owned())); } else if k > 0 { found.push((arena.ge(here, before), "closed forms".to_owned())); } else { found.push((arena.le(here, before), "closed forms".to_owned())); }
    }
    for i in 0..steady.len() as i64 {
        for j in i + 1..steady.len() as i64 {
            let (x, kx) = nikaia_std::index::get(&steady, (i) as usize); let kx = nikaia_std::num::value(kx);
            let (y, ky) = nikaia_std::index::get(&steady, nikaia_std::index::at(j)); let ky = nikaia_std::num::value(ky);
            if kx == 0 || ky == 0 { continue; }
            let left = loop_scaled_offset(arena, record, &x, ky);
            let right = loop_scaled_offset(arena, record, &y, kx);
            found.push((arena.equal(left, right), "closed forms".to_owned()));
        }
    }
    let c = nikaia_std::index::or(record.problem.condition, || -1);
    if c >= 0 {
        for (name, k) in steady.iter() {
            let k = nikaia_std::num::value(k);
            let bound = match loop_bound_of(&arena, c, name, &record.problem.state) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = bound.op.to_owned();
            let e = bound.value;
            let here = arena.var(name);
            let before = arena.var(&loop_before_name(name, start));
            let kc = arena.int(k);
            let mut reach = arena.add(e, kc);
            let constant = arena.constant(e);
            if constant.is_some() { reach = arena.int(nikaia_std::index::or(constant, || 0) + k); }
            let mut near: Option<i64> = None;
            if k > 0 && op == "<" { near = Some(arena.lt(here, reach)); } else if k > 0 && op == "<=" { near = Some(arena.le(here, reach)); } else if k < 0 && op == ">" { near = Some(arena.gt(here, reach)); } else if k < 0 && op == ">=" { near = Some(arena.ge(here, reach)); }
            let n = match near { Some(__nikaia_value) => __nikaia_value, None => continue };
            found.push((n, "closed forms".to_owned()));
            let unmoved = arena.equal(here, before);
            found.push((arena.or(vec![n, unmoved]), "closed forms".to_owned()));
        }
    }
    for (name, deltas) in record.steps.iter() {
        let mut up = true;
        let mut down = true;
        let mut most: i64 = 0;
        let mut least: i64 = 0;
        for d in deltas.iter() {
            let d = nikaia_std::num::value(d);
            if d < 0 { up = false; }
            if d > 0 { down = false; }
            if d > most { most = d; }
            if d < least { least = d; }
        }
        if deltas.is_empty() || up && down { continue; }
        let ghost = loop_before_name(name, start);
        let known = match loop_known_value(&arena, &record.problem.fixed, &ghost) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let here = arena.var(name);
        let at_start = arena.int(known);
        let limit = loop_constant_limit(&arena, c, name);
        if up {
            found.push((arena.ge(here, at_start), "intervals".to_owned()));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = found_limit.op.to_owned();
            let value = found_limit.value;
            let mut top: Option<i64> = None;
            if op == "<" { top = Some(value - 1 + most); } else if op == "<=" { top = Some(value + most); }
            let t = match top { Some(__nikaia_value) => __nikaia_value, None => continue };
            let highest = if t > known { t } else { known };
            let h = arena.int(highest);
            found.push((arena.le(here, h), "intervals".to_owned()));
        } else {
            found.push((arena.le(here, at_start), "intervals".to_owned()));
            let found_limit = match limit { Some(__nikaia_value) => __nikaia_value, None => continue };
            let op = found_limit.op.to_owned();
            let value = found_limit.value;
            let mut bottom: Option<i64> = None;
            if op == ">" { bottom = Some(value + 1 + least); } else if op == ">=" { bottom = Some(value + least); }
            let b = match bottom { Some(__nikaia_value) => __nikaia_value, None => continue };
            let lowest = if b < known { b } else { known };
            let l = arena.int(lowest);
            found.push((arena.ge(here, l), "intervals".to_owned()));
        }
    }
    found
}

fn loop_scaled_offset(arena: &mut TermArena, record: &LoopRecord, name: &str, k: i64) -> i64 {
    let ghost = loop_before_name(name, record.start);
    let here = arena.var(name);
    let known = loop_known_value(&arena, &record.problem.fixed, &ghost);
    let mut offset = here;
    if known.is_none() {
        let before = arena.var(&ghost);
        offset = arena.sub(here, before);
    } else if nikaia_std::index::or(known, || 0) != 0 {
        let before = arena.int(nikaia_std::index::or(known, || 0));
        offset = arena.sub(here, before);
    }
    if k == 1 { return offset; }
    let factor = arena.int(k);
    arena.mul(factor, offset)
}

fn loop_bound_of(arena: &TermArena, c: i64, name: &str, state: &[String]) -> Option<LoopBound> {
    let (op, left, right) = match arena.at(c) {
        SolverTerm::Lt(a, b) => ("<".to_owned(), a, b),
        SolverTerm::Le(a, b) => ("<=".to_owned(), a, b),
        SolverTerm::Gt(a, b) => (">".to_owned(), a, b),
        SolverTerm::Ge(a, b) => (">=".to_owned(), a, b),
        _ => return None,
    };
    let mut other = right;
    let mut turned = false;
    if arena.is_the_variable(left, name) { other = right; } else if arena.is_the_variable(right, name) {
        other = left;
        turned = true;
    } else { return None; }
    for s in state.iter() { if arena.mentions(other, s) { return None; } }
    if !turned { return Some(LoopBound { op, value: other }); }
    let flipped = if op == "<" { ">" } else if op == "<=" { ">=" } else if op == ">" { "<" } else { "<=" };
    Some(LoopBound { op: flipped.to_owned(), value: other })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LoopBound {
    op: String,
    value: i64,
}

fn loop_constant_limit(arena: &TermArena, c: i64, name: &str) -> Option<LoopBound> {
    if c < 0 { return None; }
    let none: Vec<String> = vec![];
    let bound = match loop_bound_of(arena, c, name, &none) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let value = match arena.constant(bound.value) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LoopBound { op: bound.op.to_owned(), value })
}

fn loop_start_term(arena: &TermArena, facts: &[i64], name: &str) -> Option<i64> {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match arena.at(fact) {
            SolverTerm::Eq(a, b) => {
                if arena.is_the_variable(a, name) && !arena.text(b).contains('@') { return Some(b); }
                if arena.is_the_variable(b, name) && !arena.text(a).contains('@') { return Some(a); }
            },
            _ => { },
        }
    }
    None
}

fn loop_known_value(arena: &TermArena, facts: &[i64], name: &str) -> Option<i64> {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match arena.at(fact) {
            SolverTerm::Eq(a, b) => {
                if arena.is_the_variable(a, name) {
                    let v = arena.constant(b);
                    if v.is_some() { return std::convert::identity(v); }
                }
                if arena.is_the_variable(b, name) {
                    let v = arena.constant(a);
                    if v.is_some() { return std::convert::identity(v); }
                }
            },
            _ => { },
        }
    }
    None
}

pub fn loop_found(arena: &mut TermArena, record: &LoopRecord, proved: &impl Fn(&TermArena, &[i64], i64) -> bool, asked: &mut Vec<i64>) -> Option<LoopFound> {
    let mut kept: Vec<(i64, String)> = vec![];
    for (term, origin) in loop_candidates(arena, record) {
        let query = lg_loop_entry_query(&record.problem, term);
        asked.push(1);
        if proved(&arena, &query.facts, query.goal) { kept.push((term, origin.to_owned())); }
    }
    let mut rounds = 0;
    let mut changed = true;
    while changed && !kept.is_empty() && rounds < 4 {
        changed = false;
        rounds += 1;
        let mut all: Vec<i64> = vec![];
        for (term, _) in kept.iter() {
            let term = nikaia_std::num::value(term);
            all.push(term);
        }
        let assumed = arena.and(all);
        let mut still: Vec<(i64, String)> = vec![];
        for (term, origin) in kept.iter() {
            let term = nikaia_std::num::value(term);
            let mut query = lg_loop_turn_query(arena, &record.problem, assumed);
            query.goal = lg_loop_primed(arena, &record.problem, term);
            asked.push(1);
            if proved(&arena, &query.facts, query.goal) { still.push((term, origin.to_owned())); } else { changed = true; }
        }
        kept = still;
    }
    if kept.is_empty() || changed { return None; }
    let mut all: Vec<i64> = vec![];
    for (term, _) in kept.iter() {
        let term = nikaia_std::num::value(term);
        all.push(term);
    }
    let invariant = arena.and(all);
    let verdict = lg_loop_check(arena, &record.problem, invariant, proved);
    asked.push(2);
    if !verdict.proved() { return None; }
    Some(LoopFound { parts: kept })
}

pub fn loop_facts(arena: &mut TermArena, record: &LoopRecord, found: &LoopFound) -> Vec<i64> {
    let start = record.start;
    let mut renamed: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let mut ghosts: Vec<String> = vec![];
    for name in record.problem.state.iter() {
        renamed.insert(name.to_owned(), arena.var(&loop_head_name(name, start)));
        if *name == record.counter { renamed.insert(lg_primed(name), arena.var(&loop_after_name(name, start))); } else { renamed.insert(lg_primed(name), arena.var(name)); }
        ghosts.push(loop_before_name(name, start));
    }
    let mut facts: Vec<i64> = vec![];
    for fact in record.problem.fixed.iter() {
        let fact = nikaia_std::num::value(fact);
        for g in ghosts.iter() {
            if arena.mentions(fact, g) {
                facts.push(fact);
                break;
            }
        }
    }
    for (term, _) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        facts.push(arena.substitute(term, &renamed));
    }
    let mut ways: Vec<i64> = vec![];
    for exit in record.problem.exits.iter() { if exit.kind != "return" { ways.push(arena.substitute(exit.relation, &renamed)); } }
    facts.push(arena.or(ways));
    facts
}

pub fn loop_found_text(arena: &mut TermArena, record: &LoopRecord, found: &LoopFound) -> String {
    let mut known: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for name in record.problem.state.iter() {
        let ghost = loop_before_name(name, record.start);
        let value = match loop_start_term(&arena, &record.problem.fixed, &ghost) { Some(__nikaia_value) => __nikaia_value, None => continue };
        known.insert(ghost, value);
    }
    let mut parts: Vec<String> = vec![];
    let mut origins: Vec<String> = vec![];
    for (term, origin) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        let shown = arena.substitute(term, &known);
        let mut text = arena.text(shown);
        if text.contains(" || ") { text = format!("({})", text); }
        let mut said = nikaia_std::list::contains(&parts, &text);
        for other in parts.iter() { if text.starts_with(&format!("({} || ", other)) { said = true; } }
        if said { continue; }
        parts.push(text);
        if !nikaia_std::list::contains(&origins, &origin) { origins.push(origin.to_owned()); }
    }
    let changes = record.problem.state.join("`, `");
    format!("proved through the loop that changes `{}`, with the invariant `{}`, found by {} and checked by three queries", changes, parts.join(" && "), origins.join(" and "))
}

pub fn loop_open_text(records: &[LoopRecord]) -> String {
    let mut names: Vec<String> = vec![];
    for record in records.iter() { for n in record.problem.state.iter() { if !nikaia_std::list::contains(&names, &n) { names.push(n.to_owned()); } } }
    format!("nothing before it shows it; no invariant found for the loop that changes `{}` carries it", names.join("`, `"))
}

pub fn loop_reads(arena: &TermArena, facts: &[i64], claim: i64, records: &[LoopRecord]) -> bool {
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(claim, &mut names);
    let mut used: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut grew = true;
    while grew {
        grew = false;
        for record in records.iter() { for s in record.problem.state.iter() { if names.contains(s) { return true; } } }
        for k in 0..facts.len() as i64 {
            if used.contains(&k) { continue; }
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            arena.variables(*nikaia_std::index::get(&facts, nikaia_std::index::at(k)), &mut read);
            let mut ties = false;
            for n in read.iter() {
                if names.contains(n) {
                    ties = true;
                    break;
                }
            }
            if ties {
                used.insert(k);
                for n in read.iter() {
                    if !names.contains(n) {
                        names.insert(n.to_owned());
                        grew = true;
                    }
                }
            }
        }
    }
    false
}

pub fn loop_key(arena: &TermArena, record: &LoopRecord) -> String {
    let mut parts: Vec<String> = vec![format!("{}", record.start)];
    for fact in record.problem.fixed.iter() {
        let fact = nikaia_std::num::value(fact);
        parts.push(arena.text(fact));
    }
    for fact in record.problem.entry.iter() {
        let fact = nikaia_std::num::value(fact);
        parts.push(arena.text(fact));
    }
    parts.push(arena.text(record.problem.step));
    parts.push(arena.text(nikaia_std::index::or(record.problem.condition, || record.problem.step.into())));
    for exit in record.problem.exits.iter() { parts.push(arena.text(exit.relation)); }
    parts.join(" ; ")
}

pub fn loop_parts_text(arena: &TermArena, found: &LoopFound) -> String {
    let mut parts: Vec<String> = vec![];
    for (term, origin) in found.parts.iter() {
        let term = nikaia_std::num::value(term);
        parts.push(format!("{}={}", origin.replace(' ', "-"), loop_term_word(arena, term)));
    }
    parts.join(";")
}

fn loop_term_word(arena: &TermArena, id: i64) -> String {
    match arena.at(id) {
        SolverTerm::Bool(b) => format!("{}", b),
        SolverTerm::Int(n) => format!("{}", n),
        SolverTerm::Var(ref name) => loop_name_word(name),
        SolverTerm::Add(a, b) => loop_pair_word(arena, "add", a, b),
        SolverTerm::Sub(a, b) => loop_pair_word(arena, "sub", a, b),
        SolverTerm::Neg(a) => format!("neg({})", loop_term_word(arena, a)),
        SolverTerm::Mul(a, b) => loop_pair_word(arena, "mul", a, b),
        SolverTerm::Quot(a, k) => format!("quot({},{})", loop_term_word(arena, a), k),
        SolverTerm::Le(a, b) => loop_pair_word(arena, "le", a, b),
        SolverTerm::Lt(a, b) => loop_pair_word(arena, "lt", a, b),
        SolverTerm::Ge(a, b) => loop_pair_word(arena, "ge", a, b),
        SolverTerm::Gt(a, b) => loop_pair_word(arena, "gt", a, b),
        SolverTerm::Eq(a, b) => loop_pair_word(arena, "eq", a, b),
        SolverTerm::Ne(a, b) => loop_pair_word(arena, "ne", a, b),
        SolverTerm::And(ref parts) => format!("and({})", loop_list_word(arena, &parts)),
        SolverTerm::Or(ref parts) => format!("or({})", loop_list_word(arena, &parts)),
        SolverTerm::Not(a) => format!("not({})", loop_term_word(arena, a)),
        _ => "?".to_string(),
    }
}

fn loop_pair_word(arena: &TermArena, op: &str, a: i64, b: i64) -> String { format!("{}({},{})", op, loop_term_word(arena, a), loop_term_word(arena, b)) }

fn loop_list_word(arena: &TermArena, parts: &[i64]) -> String {
    let mut words: Vec<String> = vec![];
    for p in parts.iter() {
        let p = nikaia_std::num::value(p);
        words.push(loop_term_word(arena, p));
    }
    words.join(",")
}

fn loop_name_word(name: &str) -> String { name.replace('%', "%25").replace('(', "%28").replace(')', "%29").replace(',', "%2C").replace(';', "%3B").replace('=', "%3D").replace('|', "%7C").replace(' ', "%20") }

fn loop_name_of(word: &str) -> Option<String> {
    if word.is_empty() || word.contains('?') { return None; }
    Some(word.replace("%20", " ").replace("%7C", "|").replace("%3D", "=").replace("%3B", ";").replace("%2C", ",").replace("%29", ")").replace("%28", "(").replace("%25", "%"))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LoopParsed {
    term: i64,
    rest: String,
}

fn loop_term_of(arena: &mut TermArena, word: &str) -> Option<LoopParsed> {
    let open = nikaia_std::index::or(nikaia_std::search::find(&word, &"(", 0), || (word.len() as i64).into());
    let comma = nikaia_std::index::or(nikaia_std::search::find(&word, &",", 0), || (word.len() as i64).into());
    let close = nikaia_std::index::or(nikaia_std::search::find(&word, &")", 0), || (word.len() as i64).into());
    let first = if open < comma { open } else { comma };
    let end = if first < close { first } else { close };
    let head = nikaia_std::index::get(&word, nikaia_std::index::at(0..end)).to_owned();
    let rest = nikaia_std::index::get(&word, nikaia_std::index::at(end..)).to_owned();
    if !rest.starts_with('(') {
        if head == "true" || head == "false" { return Some(LoopParsed { term: arena.boolean(head == "true"), rest }); }
        let n = text::parse_i64(&head);
        if n.is_some() { return Some(LoopParsed { term: arena.int(nikaia_std::index::or(n, || 0)), rest }); }
        let name = match loop_name_of(&head) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(LoopParsed { term: arena.var(&name), rest });
    }
    let mut after = nikaia_std::index::or(rest.strip_prefix('('), || "").to_owned();
    if head == "quot" {
        let inner = match loop_term_of(arena, &after) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !inner.rest.starts_with(',') { return None; }
        let tail = nikaia_std::index::or(inner.rest.strip_prefix(','), || "").to_owned();
        let shut = match nikaia_std::search::find(&tail, &")", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let k = match text::parse_i64(&nikaia_std::index::get(&tail, nikaia_std::index::at(0..shut)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if k <= 0 { return None; }
        return Some(LoopParsed { term: arena.quot(inner.term, k), rest: nikaia_std::index::get(&tail, nikaia_std::index::at(shut + 1..)).to_owned() });
    }
    let mut args: Vec<i64> = vec![];
    loop {
        let arg = match loop_term_of(arena, &after) { Some(__nikaia_value) => __nikaia_value, None => return None };
        args.push(arg.term);
        if arg.rest.starts_with(',') { after = nikaia_std::index::or(arg.rest.strip_prefix(','), || "").to_owned(); } else if arg.rest.starts_with(')') {
            after = nikaia_std::index::or(arg.rest.strip_prefix(')'), || "").to_owned();
            break;
        } else { return None; }
    }
    let term = match loop_built(arena, &head, args) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(LoopParsed { term, rest: after })
}

fn loop_built(arena: &mut TermArena, op: &str, args: Vec<i64>) -> Option<i64> {
    if op == "and" { return Some(arena.and(args)); }
    if op == "or" { return Some(arena.or(args)); }
    if args.len() == 1 {
        if op == "neg" { return Some(arena.neg(*nikaia_std::index::get(&args, 0))); }
        if op == "not" { return Some(arena.not(*nikaia_std::index::get(&args, 0))); }
        return None;
    }
    if args.len() != 2 { return None; }
    let a = *nikaia_std::index::get(&args, 0);
    let b = *nikaia_std::index::get(&args, 1);
    if op == "add" { return Some(arena.add(a, b)); }
    if op == "sub" { return Some(arena.sub(a, b)); }
    if op == "mul" { return Some(arena.mul(a, b)); }
    if op == "le" { return Some(arena.le(a, b)); }
    if op == "lt" { return Some(arena.lt(a, b)); }
    if op == "ge" { return Some(arena.ge(a, b)); }
    if op == "gt" { return Some(arena.gt(a, b)); }
    if op == "eq" { return Some(arena.equal(a, b)); }
    if op == "ne" { return Some(arena.unequal(a, b)); }
    None
}

pub fn loop_recorded(arena: &mut TermArena, record: &LoopRecord, recorded: &str, proved: &impl Fn(&TermArena, &[i64], i64) -> bool, asked: &mut Vec<i64>) -> Option<LoopFound> {
    let mut parts: Vec<(i64, String)> = vec![];
    let mut all: Vec<i64> = vec![];
    for part in recorded.split(';') {
        let at = match nikaia_std::search::find(&part, &"=", 0) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let origin = nikaia_std::index::get(&part, nikaia_std::index::at(0..at)).replace('-', " ");
        let read = match loop_term_of(arena, &nikaia_std::index::get(&part, nikaia_std::index::at(at + 1..)).to_owned()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !read.rest.is_empty() || origin.is_empty() { return None; }
        parts.push((read.term, origin));
        all.push(read.term);
    }
    if parts.is_empty() { return None; }
    let invariant = arena.and(all);
    let verdict = lg_loop_check(arena, &record.problem, invariant, proved);
    asked.push(2);
    if !verdict.proved() { return None; }
    Some(LoopFound { parts })
}


// --- prover_passes.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverAnswers {
    pub entries: collections::BTreeMap<String, Vec<PreconditionCheck>>,
    pub published: collections::BTreeMap<String, Published>,
}

#[allow(clippy::too_many_arguments)]
pub fn prover_passes(walk: &mut ProverWalk, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> ProverAnswers {
    let bound = program.items.len() as i64 + 2;
    let mut preconditions: collections::BTreeMap<String, Precondition> = collections::BTreeMap::new();
    for _ in 0..bound {
        walk.state.known = preconditions;
        walk.state.preconditions = collections::BTreeMap::new();
        walk.state.candidates = collections::BTreeMap::new();
        prover_bodies(walk, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
        preconditions = walk.state.preconditions.to_owned();
        if same_preconditions(&walk.arena, &preconditions, &walk.state.known) { break; }
    }
    walk.state.known = collections::BTreeMap::new();
    walk.state.collecting = false;
    walk.state.preconditions = preconditions;
    walk.state.postconditions = walk.state.candidates.to_owned();
    walk.state.candidates = collections::BTreeMap::new();
    let mut settled = false;
    while !settled {
        walk.held = collections::BTreeMap::new();
        walk.reaches = collections::BTreeMap::new();
        walk.findings = vec![];
        walk.state.broken = collections::BTreeSet::new();
        prover_bodies(walk, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
        settled = walk.state.broken.is_empty();
        if !settled { strike_broken(&mut walk.state); }
    }
    let answers = ProverAnswers { entries: checked_entries(&walk, escape), published: published_contracts(&walk) };
    count_checked_calls(walk);
    hold_unreached(walk, program);
    answers
}

fn strike_broken(state: &mut ProverState) {
    let mut broken: Vec<(String, i64)> = vec![];
    for one in state.broken.iter() { broken.push(one.clone()); }
    let mut k = broken.len() as i64;
    while k > 0 {
        k -= 1;
        let (function, index) = nikaia_std::index::get(&broken, nikaia_std::index::at(k)); let index = nikaia_std::num::value(index);
        let mut posts = match state.postconditions.remove(function) { Some(__nikaia_value) => __nikaia_value, None => continue };
        posts.remove(nikaia_std::count::of(index));
        state.postconditions.insert(function.to_owned(), posts);
    }
    state.broken = collections::BTreeSet::new();
}

fn same_preconditions(arena: &TermArena, a: &collections::BTreeMap<String, Precondition>, b: &collections::BTreeMap<String, Precondition>) -> bool { precondition_texts(arena, a) == precondition_texts(arena, b) }

fn precondition_texts(arena: &TermArena, m: &collections::BTreeMap<String, Precondition>) -> Vec<(String, Vec<String>)> {
    let mut out: Vec<(String, Vec<String>)> = vec![];
    for (function, pre) in m.iter() {
        let mut claims: Vec<String> = vec![];
        for claim in pre.claims.iter() { claims.push(arena.text(claim.term)); }
        out.push((function.to_owned(), claims));
    }
    out
}

fn checked_entries(walk: &ProverWalk, escape: &impl Fn(&str) -> String) -> collections::BTreeMap<String, Vec<PreconditionCheck>> {
    let mut entries: collections::BTreeMap<String, Vec<PreconditionCheck>> = collections::BTreeMap::new();
    for (function, pre) in walk.state.preconditions.iter() {
        let mut checks: Vec<PreconditionCheck> = vec![];
        for claim in pre.claims.iter() {
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            walk.arena.variables(claim.term, &mut read);
            let mut operands: Vec<(String, String)> = vec![];
            for name in read.iter() { operands.push((name.to_owned(), rust_of_name(name, escape))); }
            checks.push(PreconditionCheck { rust: rust_text(&walk.arena, claim.term, escape), written: claim.failure(function), message: claim_text_of((claim.message).as_deref()), operands });
        }
        entries.insert(function.to_owned(), checks);
    }
    entries
}

fn published_contracts(walk: &ProverWalk) -> collections::BTreeMap<String, Published> {
    let mut published: collections::BTreeMap<String, Published> = collections::BTreeMap::new();
    for (function, pre) in walk.state.preconditions.iter() {
        let mut entry = nikaia_std::index::or(published.remove(function), || Published::nothing());
        for claim in pre.claims.iter() {
            entry.requires.push(ledger_term_text(&walk.arena, claim.term));
            entry.from.push(format!("assert({})", claim.written));
        }
        published.insert(function.to_owned(), entry);
    }
    for (function, posts) in walk.state.postconditions.iter() {
        if posts.is_empty() { continue; }
        let mut entry = nikaia_std::index::or(published.remove(function), || Published::nothing());
        for post in posts.iter() { entry.ensures.push(ledger_term_text(&walk.arena, post.term)); }
        published.insert(function.to_owned(), entry);
    }
    for (function, _) in walk.state.summaries.iter() { if !published.contains_key(function) { published.insert(function.to_owned(), Published::nothing()); } }
    let mut out: collections::BTreeMap<String, Published> = collections::BTreeMap::new();
    for (function, entry) in published.iter() {
        let mut full = entry.clone();
        let posts = nikaia_std::index::or(standing_posts(&walk.state.postconditions, function), || vec![].into());
        for post in posts.iter() { full.from.push(format!("assert({})", post.written)); }
        let exits = nikaia_std::index::or(match *nikaia_std::index::get(&walk.state.summaries, function) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for exit in exits.iter() { full.inferred.push(ledger_term_text(&walk.arena, exit.term)); }
        out.insert(function.to_owned(), full);
    }
    out
}

fn ledger_term_text(arena: &TermArena, id: i64) -> String { term_ledger_text(id, &|at| { arena.at(at) }) }

fn count_checked_calls(walk: &mut ProverWalk) {
    let mut checked: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (key, reach) in walk.reaches.iter() {
        match reach {
            CallReach::Checked(_) => {
                let (callee, _) = key;
                let so_far = nikaia_std::index::or(*nikaia_std::index::get(&checked, callee), || 0);
                checked.insert(callee.to_owned(), so_far + 1);
            },
            _ => { },
        }
    }
    let mut counted: collections::BTreeMap<(i64, i64), ClaimHeld> = collections::BTreeMap::new();
    for (key, held) in walk.held.iter() {
        let now = match held {
            ClaimHeld::Precondition(function, _) => ClaimHeld::Precondition(function.to_owned(), nikaia_std::index::or(*nikaia_std::index::get(&checked, function), || 0)),
            _ => held.clone(),
        };
        counted.insert(key.clone(), now);
    }
    walk.held = counted;
}

fn hold_unreached(walk: &mut ProverWalk, program: &Program) {
    let mut tests: Vec<(i64, i64)> = vec![];
    for item in program.items.iter() {
        match &item.node {
            Item::Test { .. } => { tests.push((item.span.start as i64, item.span.end as i64)); },
            Item::Bench { .. } => { tests.push((item.span.start as i64, item.span.end as i64)); },
            _ => { },
        }
    }
    for (at, node) in walk.claims.iter() {
        let at = nikaia_std::num::value(at);let node = nikaia_std::num::value(node);
        let key = (at, node);
        if walk.held.contains_key(&key) { continue; }
        let mut in_a_test = false;
        for (start, end) in tests.iter() {
            let start = nikaia_std::num::value(start);let end = nikaia_std::num::value(end);
            if at >= start && at < end { in_a_test = true; }
        }
        if in_a_test { walk.held.insert(key, ClaimHeld::ByTheTest); } else { walk.held.insert(key, ClaimHeld::AtRunTime(String::from("it stands somewhere the prover doesn't look yet"))); }
    }
}


// --- prover_results.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClaimHeld {
    ByTheTest,
    Proved,
    Precondition(String, i64),
    AtRunTime(String),
    Refused,
    ProvedThrough(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PreconditionCheck {
    pub rust: String,
    pub written: String,
    pub message: Option<String>,
    pub operands: Vec<(String, String)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CallReach {
    Proved,
    Checked(Vec<PreconditionCheck>),
    Through,
}

pub fn joined_reach(a: CallReach, b: CallReach) -> CallReach {
    match a {
        CallReach::Through => CallReach::Through,
        CallReach::Proved => b,
        CallReach::Checked(first) => match b {
            CallReach::Through => CallReach::Through,
            CallReach::Proved => CallReach::Checked(first),
            CallReach::Checked(ref second) => CallReach::Checked(both_checks(first, second)),
        },
    }
}

fn both_checks(first: Vec<PreconditionCheck>, second: &[PreconditionCheck]) -> Vec<PreconditionCheck> {
    let mut all = first;
    for check in second.iter() { if !all.contains(check) { all.push(check.clone()); } }
    all
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Published {
    pub requires: Vec<String>,
    pub ensures: Vec<String>,
    pub inferred: Vec<String>,
    pub from: Vec<String>,
}

impl Published {
    pub fn nothing() -> Published { Published { requires: vec![], ensures: vec![], inferred: vec![], from: vec![] } }
}


// --- prover_scope.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProverScope {
    pub ints: collections::BTreeSet<String>,
    pub tainted: collections::BTreeSet<String>,
    pub locals: collections::BTreeSet<String>,
    pub facts: Vec<i64>,
    pub entry: collections::BTreeMap<String, i64>,
    pub path: Option<Vec<i64>>,
    pub exact: bool,
    pub loose: collections::BTreeSet<String>,
    pub calls_of: collections::BTreeMap<String, collections::BTreeSet<String>>,
    pub summed: collections::BTreeMap<String, Vec<SummaryAlt>>,
    pub leaned: collections::BTreeMap<String, Vec<String>>,
    pub mutables: collections::BTreeSet<String>,
    pub loops: Vec<LoopRecord>,
    pub history: Vec<i64>,
}

impl ProverScope {
    pub fn unknown() -> ProverScope { ProverScope { ints: collections::BTreeSet::new(), tainted: collections::BTreeSet::new(), locals: collections::BTreeSet::new(), facts: vec![], entry: collections::BTreeMap::new(), path: None, exact: false, loose: collections::BTreeSet::new(), calls_of: collections::BTreeMap::new(), summed: collections::BTreeMap::new(), leaned: collections::BTreeMap::new(), mutables: collections::BTreeSet::new(), loops: vec![], history: vec![] } }
    pub fn at_the_entry() -> ProverScope {
        let mut scope = ProverScope::unknown();
        scope.path = Some(vec![]);
        scope.exact = true;
        scope
    }
    pub fn rebind(&mut self, arena: &TermArena, name: &str) {
        let under = format!("{}.", name);
        let mut parts: collections::BTreeSet<String> = collections::BTreeSet::new();
        let own = length_of(name);
        for n in self.ints.iter() { if n.starts_with(&under) && *n != own && n.ends_with(".len()") { parts.insert(nikaia_std::index::or(n.strip_suffix(".len()"), || "").to_owned()); } else if n.starts_with(&under) && *n != own { parts.insert(n.to_owned()); } }
        for part in parts.iter() { self.rebind(arena, part); }
        let length = length_of(name);
        self.ints.remove(name);
        self.ints.remove(&length);
        self.tainted.remove(name);
        self.entry.remove(name);
        self.entry.remove(&length);
        self.locals.insert(name.to_owned());
        self.loose.remove(name);
        self.loose.remove(&length);
        self.calls_of.remove(name);
        self.summed.remove(name);
        self.leaned.remove(name);
        if !self.loops.is_empty() {
            let mut standing: Vec<LoopRecord> = vec![];
            for record in self.loops.iter() { if !nikaia_std::list::contains(&record.problem.state, &name) { standing.push(record.clone()); } }
            self.loops = standing;
        }
        let mut gone: Vec<String> = vec![];
        for (bound, alts) in self.summed.iter() {
            for alt in alts.iter() {
                if arena.mentions(alt.guard, name) || arena.mentions(alt.value, name) || arena.mentions(alt.guard, &length) || arena.mentions(alt.value, &length) {
                    gone.push(bound.to_owned());
                    break;
                }
            }
        }
        for bound in gone.iter() { self.summed.remove(bound); }
        let mut kept: Vec<i64> = vec![];
        for fact in self.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if !arena.mentions(fact, name) && !arena.mentions(fact, &length) { kept.push(fact); }
        }
        if (kept.len() as i64) != self.facts.len() as i64 { self.exact = false; }
        self.facts = kept;
        if !self.history.is_empty() {
            let mut earlier: Vec<i64> = vec![];
            for fact in self.history.iter() {
                let fact = nikaia_std::num::value(fact);
                if !arena.mentions(fact, name) && !arena.mentions(fact, &length) { earlier.push(fact); }
            }
            self.history = earlier;
        }
    }
    pub fn renamed(&mut self, arena: &mut TermArena, name: &str, earlier: &str) {
        let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        given.insert(name.to_owned(), arena.var(earlier));
        let mut history: Vec<i64> = vec![];
        for fact in self.history.iter() {
            let fact = nikaia_std::num::value(fact);
            if arena.mentions(fact, name) { history.push(arena.substitute(fact, &given)); } else { history.push(fact); }
        }
        let mut kept: Vec<i64> = vec![];
        for fact in self.facts.iter() {
            let fact = nikaia_std::num::value(fact);
            if arena.mentions(fact, name) { history.push(arena.substitute(fact, &given)); } else { kept.push(fact); }
        }
        if (kept.len() as i64) != self.facts.len() as i64 { self.exact = false; }
        self.facts = kept;
        self.history = history;
        self.ints.insert(earlier.to_owned());
        if self.loose.contains(name) { self.loose.insert(earlier.to_owned()); }
        let at = self.entry.remove(name);
        if at.is_some() { self.entry.insert(earlier.to_owned(), nikaia_std::index::or(at, || 0)); }
        let ints = self.ints.to_owned();
        self.rebind(&arena, name);
        self.ints = ints;
    }
    pub fn history_reads(&self, arena: &TermArena, claim: i64) -> bool {
        if self.history.is_empty() { return false; }
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(claim, &mut names);
        let mut grown = true;
        while grown {
            let before = names.len() as i64;
            for fact in self.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
                arena.variables(fact, &mut read);
                if ties(&read, &names) { for n in read.iter() { names.insert(n.to_owned()); } }
            }
            grown = (names.len() as i64) != before;
        }
        for fact in self.history.iter() {
            let fact = nikaia_std::num::value(fact);
            let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
            arena.variables(fact, &mut read);
            if ties(&read, &names) { return true; }
        }
        false
    }
    pub fn with_history(&self) -> Vec<i64> {
        let mut all = self.facts.to_owned();
        all.extend(self.history.to_owned());
        all
    }
    pub fn has_length(&mut self, arena: &mut TermArena, name: &str, known: Option<i64>) {
        let length = length_of(name);
        self.ints.insert(length.to_owned());
        let len = arena.var(&length);
        let zero = arena.int(0);
        self.facts.push(arena.ge(len, zero));
        let n = match known { Some(__nikaia_value) => __nikaia_value, None => {
            self.loose.insert(length);
            return;
        } };
        let value = arena.int(n);
        self.facts.push(arena.equal(len, value));
        self.entry.insert(length, value);
    }
    pub fn not_negative(&mut self, arena: &mut TermArena, name: &str) {
        let n = arena.var(name);
        let zero = arena.int(0);
        self.facts.push(arena.ge(n, zero));
    }
    pub fn at_entry(&self, arena: &mut TermArena, term: i64) -> Option<i64> {
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(term, &mut read);
        let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for name in read.iter() {
            let value = match *nikaia_std::index::get(&self.entry, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
            values.insert(name.to_owned(), value);
        }
        Some(arena.substitute(term, &values))
    }
    pub fn on_the_path(&mut self, arena: &mut TermArena, condition: Option<i64>) {
        let at = match condition { Some(__nikaia_value) => __nikaia_value, None => {
            self.path = None;
            return;
        } };
        let c = match self.at_entry(arena, at) { Some(__nikaia_value) => __nikaia_value, None => {
            self.path = None;
            return;
        } };
        self.path = pushed(copied_path((self.path).as_ref()), c);
    }
    pub fn precondition_at(&self, arena: &mut TermArena, claim: i64, params: &collections::BTreeSet<String>) -> Option<i64> {
        let path = match copied_path((self.path).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let at_entry = match self.at_entry(arena, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let mut term = at_entry;
        if !path.is_empty() {
            let taken = arena.and(path);
            let not_taken = arena.not(taken);
            term = arena.or(vec![not_taken, at_entry]);
        }
        if !only_parameters(&arena, term, params) || arena.size(term) > precondition_terms() { return None; }
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(term, &mut read);
        if read.is_empty() { return None; }
        Some(term)
    }
    pub fn postcondition_at(&self, arena: &mut TermArena, claim: i64, returned: &str, params: &collections::BTreeSet<String>) -> Option<i64> {
        let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(claim, &mut read);
        let result = arena.var(&result_name());
        let mut values: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
        for name in read.iter() {
            if name == returned { values.insert(name.to_owned(), result); } else {
                let value = match *nikaia_std::index::get(&self.entry, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => return None };
                values.insert(name.to_owned(), value);
            }
        }
        let term = arena.substitute(claim, &values);
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(term, &mut names);
        for name in names.iter() { if *name != result_name() && !is_a_parameter(name, params) { return None; } }
        Some(term)
    }
    pub fn pinned_names(&self, arena: &TermArena, claim: i64) -> Option<collections::BTreeSet<String>> {
        if !self.exact { return None; }
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        arena.variables(claim, &mut names);
        let mut grown = true;
        while grown {
            let before = names.len() as i64;
            for fact in self.facts.iter() {
                let fact = nikaia_std::num::value(fact);
                let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
                arena.variables(fact, &mut read);
                if ties(&read, &names) { for n in read.iter() { names.insert(n.to_owned()); } }
            }
            grown = (names.len() as i64) != before;
        }
        for n in names.iter() { if self.loose.contains(n) || !self.ints.contains(n) { return None; } }
        Some(names)
    }
    pub fn blind(&self) -> ProverScope {
        let mut scope = ProverScope::unknown();
        scope.tainted = self.tainted.to_owned();
        scope.locals = self.locals.to_owned();
        scope
    }
}

pub fn length_of(name: &str) -> String { format!("{}.len()", name) }

pub fn result_name() -> String { String::from("result") }

pub fn precondition_terms() -> i64 { 64 }

fn pushed(path: Option<Vec<i64>>, c: i64) -> Option<Vec<i64>> {
    let mut p = match path { Some(__nikaia_value) => __nikaia_value, None => return None };
    p.push(c);
    Some(p)
}

pub fn copied_path(path: Option<&Vec<i64>>) -> Option<Vec<i64>> {
    let p = match path { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(p.to_owned())
}

fn only_parameters(arena: &TermArena, term: i64, params: &collections::BTreeSet<String>) -> bool {
    let mut read: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(term, &mut read);
    for name in read.iter() { if !is_a_parameter(name, params) { return false; } }
    true
}

fn ties(read: &collections::BTreeSet<String>, names: &collections::BTreeSet<String>) -> bool {
    for n in read.iter() { if names.contains(n) { return true; } }
    false
}


// --- prover_solver.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SolverAnswer {
    Proved,
    Rejected(String),
    NotProved,
}

pub fn refuting_values(arena: &mut TermArena, facts: &[i64], claim: i64, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) -> Option<collections::BTreeMap<String, i64>> {
    let negation = arena.not(claim);
    match ask(&arena, facts, negation) {
        SolverAnswer::Proved => { },
        _ => { return None; },
    }
    let falsum = arena.boolean(false);
    let values = match model(&arena, facts, falsum) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
    arena.variables(claim, &mut names);
    Some(values_of(&names, &values))
}

pub fn breaking_values(arena: &mut TermArena, scope: &ProverScope, claim: i64, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>) -> Option<collections::BTreeMap<String, i64>> {
    let names = match scope.pinned_names(&arena, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let values = match model(&arena, &scope.facts, claim) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let shown = values_of(&names, &values);
    if shown.is_empty() { return None; }
    Some(shown)
}

fn values_of(names: &collections::BTreeSet<String>, values: &collections::BTreeMap<String, i64>) -> collections::BTreeMap<String, i64> {
    let mut shown: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for name in names.iter() {
        let value = match *nikaia_std::index::get(&values, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        shown.insert(name.to_owned(), value);
    }
    shown
}


