// --- sources.nika ---

pub async fn rust_sources(src: &str) -> Result<collections::BTreeMap<String, String>, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let mut out = collections::BTreeMap::new();
    for name in fs::walk(std::path::Path::new(&(src)), &fs::Root::Anywhere).await? {
        if !nikaia_std::fs::path::ends_with(&(name), std::path::Path::new(&(".rs"))) { continue; }
        let text = fs::read_to_string(&nikaia_std::fs::path::joined(&[std::ffi::OsStr::new(&std::string::ToString::to_string(&(src))), std::ffi::OsStr::new("/"), std::convert::AsRef::<std::ffi::OsStr>::as_ref(&(name))]), &fs::Root::Anywhere).await?;
        out.insert(format!("src/{}", nikaia_std::fs::path::to_text(&(name))?), text);
    }
    Ok(out)
}


// --- specbook.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpecBlock {
    pub line: i64,
    pub code: String,
    pub discusses_a_refusal: bool,
    pub sketch: bool,
}

pub fn blocks_in(text: &str) -> Vec<SpecBlock> {
    let mut lines: Vec<String> = vec![];
    for line in text.split("\n") { lines.push(line.to_owned()); }
    let mut found: Vec<SpecBlock> = vec![];
    let mut at: i64 = 0;
    while at < lines.len() as i64 {
        if (*nikaia_std::index::get(&lines, nikaia_std::index::at(at))).trim() != "```nika" {
            at += 1;
            continue;
        }
        let start: i64 = at + 1;
        let mut end: i64 = start;
        while end < lines.len() as i64 && (*nikaia_std::index::get(&lines, nikaia_std::index::at(end))).trim() != "```" { end += 1; }
        let mut code: String = String::from("");
        for k in start..end {
            if k > start { code.push('\n'); }
            code.push_str(nikaia_std::index::get(&lines, nikaia_std::index::at(k)));
        }
        found.push(SpecBlock { line: start + 1, discusses_a_refusal: discusses_a_refusal(&code), sketch: is_a_sketch(&code), code });
        at = end + 1;
    }
    found
}

pub fn discusses_a_refusal(code: &str) -> bool {
    let lower = code.to_lowercase();
    for mark in ["error[nk", "// invalid", "// ungültig", "// fehler", "// error", "// compiler error", "refused", "does not parse"] { if lower.contains(mark) { return true; } }
    for word in lower.split_whitespace() { if word.starts_with("nk1") || word.starts_with("nk2") { return true; } }
    false
}

pub fn is_a_sketch(code: &str) -> bool {
    let c: Vec<scalar> = nikaia_std::list::chars(code.chars());
    let mut at: i64 = 0;
    while ((at) as usize) < c.len() {
        if *nikaia_std::index::get(&c, (at) as usize) == '…' { return true; }
        if ((at + 2) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == '.' && *nikaia_std::index::get(&c, (at + 1) as usize) == '.' && *nikaia_std::index::get(&c, (at + 2) as usize) == '.' {
            let named = ((at + 3) as usize) < c.len() && ((*nikaia_std::index::get(&c, (at + 3) as usize)).is_alphabetic() || *nikaia_std::index::get(&c, (at + 3) as usize) == '_');
            if !named { return true; }
            at += 3;
        } else { at += 1; }
    }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reading {
    pub name: String,
    pub source: String,
}

pub fn readings(code: &str) -> Vec<Reading> {
    let mut all: Vec<Reading> = vec![Reading { name: String::from("as written"), source: code.to_owned() }];
    if code.contains("fn main") { return all; }
    let mut with_a_main = code.trim_end().to_owned();
    with_a_main.push_str("\n\nfn main() {\n}\n");
    all.push(Reading { name: String::from("items and a main"), source: with_a_main });
    all.push(Reading { name: String::from("a body"), source: wrapped(code) });
    let parts = split_at_the_first_statement(code);
    if parts.len() == 2 {
        let mut both = (*nikaia_std::index::get(&parts, 0)).to_owned();
        both.push_str("\n\n");
        both.push_str(&wrapped(nikaia_std::index::get(&parts, 1)));
        all.push(Reading { name: String::from("items, then a body"), source: both });
    }
    all
}

fn wrapped(body: &str) -> String {
    let mut out: String = String::from("fn main() {\n");
    let mut first = true;
    for line in body.trim_end().split("\n") {
        if !first { out.push('\n'); }
        first = false;
        if !line.trim().is_empty() {
            out.push_str("    ");
            out.push_str(line);
        }
    }
    out.push_str("\n}\n");
    out
}

fn split_at_the_first_statement(code: &str) -> Vec<String> {
    let mut lines: Vec<String> = vec![];
    for line in code.trim_end().split("\n") { lines.push(line.to_owned()); }
    let mut head: i64 = 0;
    let mut depth: i64 = 0;
    for at in 0..lines.len() as i64 {
        let trimmed = (*nikaia_std::index::get(&lines, (at) as usize)).trim();
        if depth == 0 {
            if !(trimmed.is_empty() || trimmed.starts_with("//") || an_item(trimmed)) { break; }
            head = at + 1;
        }
        depth += braces(nikaia_std::index::get(&lines, (at) as usize));
    }
    if head == 0 || head >= lines.len() as i64 { return vec![]; }
    let mut before: String = String::from("");
    let mut after: String = String::from("");
    for at in 0..lines.len() as i64 {
        if at < head {
            if at > 0 { before.push('\n'); }
            before.push_str(nikaia_std::index::get(&lines, (at) as usize));
        } else {
            if at > head { after.push('\n'); }
            after.push_str(nikaia_std::index::get(&lines, (at) as usize));
        }
    }
    vec![before, after]
}

fn an_item(line: &str) -> bool {
    for word in ["use ", "struct ", "enum ", "impl ", "trait ", "fn ", "grammar ", "const ", "comptime ", "pub "] { if line.starts_with(word) { return true; } }
    false
}

fn braces(line: &str) -> i64 {
    let mut depth: i64 = 0;
    for c in line.chars() { if c == '{' { depth += 1; } else if c == '}' { depth -= 1; } }
    depth
}

pub fn opening(code: &str) -> String {
    for line in code.split("\n") {
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        let c: Vec<scalar> = nikaia_std::list::chars(trimmed.chars());
        if c.len() <= 56 { return trimmed.to_owned(); }
        let mut cut: String = String::from("");
        for k in 0..55 { cut.push(*nikaia_std::index::get(&c, (k) as usize)); }
        cut.push('…');
        return cut;
    }
    String::from("(empty)")
}


// --- spelling.nika ---

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn distance(a: &str, b: &str) -> i64 {
    let x: Vec<scalar> = nikaia_std::list::chars(a.chars());
    let y: Vec<scalar> = nikaia_std::list::chars(b.chars());
    let rows = x.len() as i64 + 1;
    let cols = y.len() as i64 + 1;
    let mut d: Vec<Vec<i64>> = Vec::new();
    for i in 0..rows {
        let mut row: Vec<i64> = Vec::new();
        for j in 0..cols { if i == 0 { row.push(j); } else if j == 0 { row.push(i); } else { row.push(0); } }
        d.push(row);
    }
    for i in 1..rows {
        for j in 1..cols {
            let cost: i64 = if *nikaia_std::index::get(&x, nikaia_std::index::at(i - 1)) == *nikaia_std::index::get(&y, nikaia_std::index::at(j - 1)) { 0 } else { 1 };
            let mut best = *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i - 1)), nikaia_std::index::at(j)) + 1;
            if *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i)), nikaia_std::index::at(j - 1)) + 1 < best { best = *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i)), nikaia_std::index::at(j - 1)) + 1; }
            if *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i - 1)), nikaia_std::index::at(j - 1)) + cost < best { best = *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i - 1)), nikaia_std::index::at(j - 1)) + cost; }
            let swapped = i > 1 && j > 1 && *nikaia_std::index::get(&x, nikaia_std::index::at(i - 1)) == *nikaia_std::index::get(&y, nikaia_std::index::at(j - 2)) && *nikaia_std::index::get(&x, nikaia_std::index::at(i - 2)) == *nikaia_std::index::get(&y, nikaia_std::index::at(j - 1));
            if swapped && *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i - 2)), nikaia_std::index::at(j - 2)) + 1 < best { best = *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(i - 2)), nikaia_std::index::at(j - 2)) + 1; }
            { let __nikaia_stored = best; nikaia_std::index::set(&mut d[nikaia_std::index::at(i)], nikaia_std::index::at(j), __nikaia_stored); }
        }
    }
    *nikaia_std::index::get(nikaia_std::index::get(&d, nikaia_std::index::at(rows - 1)), nikaia_std::index::at(cols - 1))
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn one_edit_apart(a: &str, b: &str) -> bool {
    if a == b { return false; }
    let x: Vec<scalar> = nikaia_std::list::chars(a.chars());
    let y: Vec<scalar> = nikaia_std::list::chars(b.chars());
    if (x.len() as i64) == y.len() as i64 {
        let mut differ = 0;
        for i in 0..x.len() as i64 { if *nikaia_std::index::get(&x, (i) as usize) != *nikaia_std::index::get(&y, (i) as usize) { differ += 1; } }
        return differ == 1;
    }
    if (x.len() as i64) == y.len() as i64 + 1 { return one_put_in(a, b); }
    if (y.len() as i64) == x.len() as i64 + 1 { return one_put_in(b, a); }
    false
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn one_put_in(long: &str, short: &str) -> bool {
    let kept: Vec<scalar> = nikaia_std::list::chars(short.chars());
    let mut at: i64 = 0;
    let mut skipped = false;
    for c in long.chars() { if ((at) as usize) < kept.len() && *nikaia_std::index::get(&kept, (at) as usize) == c { at += 1; } else if skipped { return false; } else { skipped = true; } }
    true
}


