pub fn read_items(surface: &mut Surface, relative: &str, items: &[RustItem<'_>]) {
    let found = module_of(relative);
    if found.is_none() { return; }
    let at = nikaia_std::index::or(found, || "".into());
    let mut imports: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    imported(items, &mut imports);
    walk(surface, items, &at, &imports);
}

pub fn resolve(surface: &mut Surface) {
    let mut direct: Vec<String> = vec![];
    for path in surface.offers.iter() { if offered(&surface, path) { direct.push(path.to_owned()); } }
    for path in surface.types.iter() { if offered(&surface, path) { direct.push(path.to_owned()); } }
    for path in direct.iter() { surface.reachable.insert(path.to_owned(), path.to_owned()); }
    let mut exports: Vec<Export> = vec![];
    for export in surface.exports.iter() { if offered(&surface, &joined(&export.at, "x")) { exports.push(export.clone()); } }
    for _ in 0..8 {
        let mut added = false;
        for export in exports.iter() {
            if export.name.is_some() {
                let named = nikaia_std::index::or(match export.name.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || Named { name: String::from(""), alias: String::from("") });
                let offered_as = joined(&export.at, &named.alias);
                for candidate in candidates(export, &named.name) {
                    if surface.functions.contains_key(&candidate) || surface.types.contains(&candidate) {
                        if !surface.reachable.contains_key(&offered_as) {
                            surface.reachable.insert(offered_as.to_owned(), candidate.to_owned());
                            added = true;
                        }
                        break;
                    }
                }
            } else {
                for base in bases(export) {
                    let under = format!("{}::", base);
                    let mut names: Vec<String> = vec![];
                    for path in surface.offers.iter() {
                        let rest = directly_under(path, &under);
                        if rest.is_some() { names.push(nikaia_std::index::or(rest, || "".into())); }
                    }
                    for path in surface.types.iter() {
                        let rest = directly_under(path, &under);
                        if rest.is_some() { names.push(nikaia_std::index::or(rest, || "".into())); }
                    }
                    for name in names.iter() {
                        let offered_as = joined(&export.at, name);
                        if !surface.reachable.contains_key(&offered_as) {
                            surface.reachable.insert(offered_as.to_owned(), format!("{}::{}", base, name));
                            added = true;
                        }
                    }
                }
            }
        }
        if !added { break; }
    }
    surface.exports = exports;
}

pub fn offered(surface: &Surface, path: &str) -> bool {
    let mut parts: Vec<String> = vec![];
    for part in path.split("::") { parts.push(part.to_owned()); }
    let mut at: String = String::from("");
    for k in 0..parts.len() as i64 - 1 {
        at = joined(&at, nikaia_std::index::get(&parts, (k) as usize));
        let public = nikaia_std::index::or(surface.modules.get(&at), || false);
        if !public { return false; }
    }
    true
}

pub fn candidates(export: &Export, name: &str) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for base in bases(export) { if base.is_empty() { out.push(name.to_owned()); } else { out.push(format!("{}::{}", base, name)); } }
    out
}

pub fn imported(items: &[RustItem<'_>], out: &mut collections::BTreeMap<String, String>) {
    for item in items.iter() {
        match item {
            RustItem::Used(text) => { let text = *text; imports_of(text, out); },
            RustItem::Export(text) => { let text = *text; imports_of(text, out); },
            RustItem::Group(g) => { imported(&g.items, out); },
            _ => { },
        }
    }
}

fn imports_of(text: &str, out: &mut collections::BTreeMap<String, String>) {
    for one in exported("", text) {
        if one.name.is_none() { continue; }
        let named = nikaia_std::index::or(match one.name.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Named { name: String::from(""), alias: String::from("") });
        if one.prefix.is_empty() { out.insert(named.alias.to_owned(), named.name.to_owned()); } else { out.insert(named.alias.to_owned(), format!("{}::{}", one.prefix, named.name)); }
    }
}

fn walk(surface: &mut Surface, items: &[RustItem<'_>], at: &str, imports: &collections::BTreeMap<String, String>) {
    for item in items.iter() {
        match item {
            RustItem::Fun(f) => {
                let path = joined(at, f.name);
                surface.offers.insert(path.to_owned());
                surface.functions.insert(path, function_of(f, imports));
            },
            RustItem::Hidden(f) => { surface.functions.insert(joined(at, f.name), function_of(f, imports)); },
            RustItem::Rec(r) => {
                let path = joined(at, r.name);
                if r.what == "struct" {
                    let mut types: Vec<String> = vec![];
                    for part in r.parts.iter() { types.push(part.ty.to_owned()); }
                    surface.fields.insert(path.to_owned(), types);
                }
                let none: collections::BTreeSet<String> = collections::BTreeSet::new();
                let mut derived = nikaia_std::index::or(*nikaia_std::index::get(&surface.derives, &path), || &none).to_owned();
                for list in r.derives.iter() {
                    let list = *list;
                    for written in list.split(',') {
                        let name = last_segment(written.trim());
                        if !name.is_empty() { derived.insert(name); }
                    }
                }
                surface.derives.insert(path.to_owned(), derived);
                surface.types.insert(path);
            },
            RustItem::Export(text) => {
                let text = *text;
                for one in exported(at, text) { surface.exports.push(one); }
            },
            RustItem::Used(_) => { },
            RustItem::Group(g) => {
                if g.what == "mod" {
                    let path = joined(at, g.name);
                    surface.modules.insert(path.to_owned(), g.visible);
                    walk(surface, &g.items, &path, imports);
                } else if g.what == "unsafe impl" && !g.via.is_empty() { surface.promises.push(format!("unsafe impl {} for {}", g.via, g.name)); } else if g.what == "impl" && !g.via.is_empty() && !g.via.contains('<') {
                    let path = joined(at, &last_segment(&before_generics(g.name)));
                    let none: collections::BTreeSet<String> = collections::BTreeSet::new();
                    let mut derived = nikaia_std::index::or(*nikaia_std::index::get(&surface.derives, &path), || &none).to_owned();
                    derived.insert(last_segment(g.via.trim()));
                    surface.derives.insert(path, derived);
                }
            },
        }
    }
}

fn function_of(f: &Fun<'_, '_, '_, '_, '_, '_>, imports: &collections::BTreeMap<String, String>) -> Function {
    let mut parameters: Vec<String> = vec![];
    for written in split_top_level(f.generics) {
        if written.starts_with('\'') { continue; }
        let name = before_colon(&written);
        if !name.is_empty() { parameters.push(name); }
    }
    let mut args: Vec<Arg> = vec![];
    for part in f.parts.iter() { if part.name != "self" { args.push(Arg { name: part.name.to_owned(), ty: part.ty.to_owned() }); } }
    let mut calls: Vec<String> = vec![];
    for call in f.calls.iter() {
        let call = *call;
        let full = nikaia_std::index::or(imports.get(call), || call);
        calls.push(full.to_owned());
    }
    Function { parameters, args, result: f.result.to_owned(), bounds: format!("{}, {}", f.generics, f.wheres), calls, pauses: f.pauses }
}

fn directly_under(path: &str, under: &str) -> Option<String> {
    if !path.starts_with(under) { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(path.chars());
    let u: Vec<scalar> = nikaia_std::list::chars(under.chars());
    let rest = between(&c, u.len() as i64, c.len() as i64);
    if rest.contains("::") { return None; }
    Some(rest)
}

fn before_colon(written: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let mut end = c.len() as i64;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, (at) as usize) == ':' && end == c.len() as i64 { end = at; } }
    let head = between(&c, 0, end);
    head.trim().to_owned()
}

fn before_generics(written: &str) -> String {
    let mut out: String = String::from("");
    for c in written.chars() {
        if c == '<' { break; }
        out.push(c);
    }
    out
}

fn last_segment(written: &str) -> String { nikaia_std::index::or(written.rsplit("::").next(), || "").to_owned() }


// --- sync.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncReach {
    pub blocked: bool,
    pub calls: collections::BTreeSet<String>,
    pub through_code: collections::BTreeSet<String>,
    pub pauses_here: bool,
}

pub fn sync_holds(graph: &collections::BTreeMap<String, SyncReach>) -> collections::BTreeMap<String, bool> {
    let mut holds: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for (name, reach) in graph.iter() { holds.insert(name.to_owned(), !reach.blocked && reach.through_code.is_empty()); }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, reach) in graph.iter() {
            if !held(&holds, name) { continue; }
            if reaches_one_that_pauses(&reach.calls, &holds) {
                holds.insert(name.to_owned(), false);
                changed = true;
            }
        }
    }
    holds
}

pub fn paused_only_by_code(graph: &collections::BTreeMap<String, SyncReach>, holds: &collections::BTreeMap<String, bool>) -> collections::BTreeMap<String, Vec<String>> {
    let mut out: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (name, reach) in graph.iter() {
        if held(holds, name) || reach.blocked || reach.through_code.is_empty() { continue; }
        if reaches_one_that_pauses(&reach.calls, holds) { continue; }
        let mut parameters: Vec<String> = vec![];
        for parameter in reach.through_code.iter() { parameters.push(parameter.to_owned()); }
        out.insert(name.to_owned(), parameters);
    }
    out
}

pub fn pause_chain(graph: &collections::BTreeMap<String, SyncReach>, holds: &collections::BTreeMap<String, bool>, start: &str) -> Vec<String> {
    let mut queue: Vec<String> = vec![start.to_owned()];
    let mut came_from: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
    seen.insert(start.to_owned());
    let mut next: i64 = 0;
    while ((next) as usize) < queue.len() {
        let at = (*nikaia_std::index::get(&queue, (next) as usize)).to_owned();
        next += 1;
        let reach = match *nikaia_std::index::get(&graph, &at) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if reach.pauses_here || reach.blocked { return chain_back_to(&came_from, &at); }
        for callee in reach.calls.iter() {
            if graph.contains_key(callee) && !held(holds, callee) && !seen.contains(callee) {
                seen.insert(callee.to_owned());
                came_from.insert(callee.to_owned(), at.to_owned());
                queue.push(callee.to_owned());
            }
        }
    }
    vec![]
}

fn chain_back_to(came_from: &collections::BTreeMap<String, String>, at: &str) -> Vec<String> {
    let mut backwards: Vec<String> = vec![at.to_owned()];
    let mut back = at.to_owned();
    while came_from.contains_key(&back) {
        back = nikaia_std::index::or(match *nikaia_std::index::get(&came_from, &back) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into());
        backwards.push(back.to_owned());
    }
    let mut chain: Vec<String> = vec![];
    let mut i = backwards.len() as i64;
    while i > 0 {
        i -= 1;
        chain.push((*nikaia_std::index::get(&backwards, nikaia_std::index::at(i))).to_owned());
    }
    chain
}

fn held(holds: &collections::BTreeMap<String, bool>, name: &str) -> bool { nikaia_std::index::or(*nikaia_std::index::get(&holds, name), || false) }

fn reaches_one_that_pauses(calls: &collections::BTreeSet<String>, holds: &collections::BTreeMap<String, bool>) -> bool {
    for callee in calls.iter() { if !held(holds, callee) { return true; } }
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Site {
    pub span: Span,
    pub what: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncNode {
    pub reach: SyncReach,
    pub site: Option<Site>,
    pub unit: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SyncGraph {
    pub methods: collections::BTreeMap<String, MethodsCalled>,
    pub nodes: collections::BTreeMap<String, SyncNode>,
    pub unit: i64,
}

pub fn unit_sync(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger, graph: &mut SyncGraph) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, args, body, .. } => {
                let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                let mut node = sync_node(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, &code_of(args, names), names, own, library, graph.unit);
                sync_methods(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut node);
                graph.nodes.insert(key, node);
            },
            Item::Impl { trait_name, target, methods, .. } => {
                let trait_name = *trait_name;
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, args, body, .. } => {
                            let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            let mut node = sync_node(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, &code_of(args, names), names, own, library, graph.unit);
                            sync_methods(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut node);
                            declared_by((trait_name).as_ref(), &key_of_function((name).as_ref(), "", names), names, own, library, &mut node);
                            graph.nodes.insert(key, node);
                        },
                        _ => { },
                    }
                }
            },
            Item::Trait { name, methods, .. } => {
                let name = *name;
                let declaring = names.resolve(name).to_owned();
                for method in methods.iter() {
                    let key = format!("{}::{}", declaring, names.resolve(method.node.name));
                    graph.nodes.insert(key, leaf(!method.node.is_sync));
                }
            },
            Item::Grammar(def) => {
                let named = names.resolve(def.name).to_owned();
                for rule in def.rules.iter() { if rule.is_entry { graph.nodes.insert(format!("{}::{}", named, names.resolve(rule.name)), leaf(false)); } }
            },
            _ => { },
        }
    }
}

fn leaf(blocked: bool) -> SyncNode { SyncNode { reach: SyncReach { blocked, calls: collections::BTreeSet::new(), through_code: collections::BTreeSet::new(), pauses_here: false }, site: None, unit: 0 } }

fn declared_by(trait_name: Option<&winnow_grammar::Symbol>, method: &str, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, node: &mut SyncNode) {
    let named = match trait_name { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = format!("{}::{}", names.resolve(*named), method);
    if own.functions.contains_key(&declared) { node.reach.calls.insert(declared); } else if library.functions.contains_key(&declared) {
        let entry = nikaia_std::index::or(match *nikaia_std::index::get(&library.functions, &declared) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || FnContract::empty());
        if !entry.sync_claim.is_sync() { node.reach.calls.insert(declared); }
    }
}

fn code_of(args: &[FnArg], names: &winnow_grammar::InternerContext) -> collections::BTreeMap<String, bool> {
    let mut code: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for arg in args.iter() {
        let declared = match (*arg.ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        code.insert(names.resolve(arg.name).to_owned(), !declared.is_sync);
    }
    code
}

fn sync_node(seen: &[Seen], program: &Program, code: &collections::BTreeMap<String, bool>, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unit: i64) -> SyncNode {
    let mut node = SyncNode { reach: SyncReach { blocked: false, calls: collections::BTreeSet::new(), through_code: collections::BTreeSet::new(), pauses_here: false }, site: None, unit };
    for one in seen.iter() {
        match one {
            Seen::Joins { construct, span } => {
                node.reach.blocked = true;
                first_site(span, &format!("an `{}` block", construct), &mut node);
            },
            Seen::Call { name, span, .. } => { sync_call((callee_named(names, name.to_owned(), own, library, &program.items)).as_ref(), span, code, &mut node); },
            Seen::Spawn { span } => { sync_call(Some(&Callee::Opaque(None)), span, code, &mut node); },
            Seen::Opaque { span } => { sync_call(Some(&Callee::Opaque(None)), span, code, &mut node); },
            _ => { },
        }
    }
    node.reach.pauses_here = node.site.is_some();
    node
}

fn sync_call(callee: Option<&Callee>, span: &Span, code: &collections::BTreeMap<String, bool>, node: &mut SyncNode) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => { node.reach.calls.insert(name.to_owned()); },
        Callee::Library { key, never_pauses } => {
            let never_pauses = *never_pauses;
            if !never_pauses {
                node.reach.blocked = true;
                first_site(span, &format!("`{}`", key), node);
            }
        },
        Callee::Opaque(name) => { opaque_call((name).as_deref(), span, code, node); },
        _ => { },
    }
}

fn opaque_call(name: Option<&str>, span: &Span, code: &collections::BTreeMap<String, bool>, node: &mut SyncNode) {
    if a_stop(name) { return; }
    if name.is_none() {
        node.reach.blocked = true;
        first_site(span, "something this compiler cannot see the end of", node);
        return;
    }
    let called = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    if code.contains_key(called) {
        if nikaia_std::index::or(*nikaia_std::index::get(&code, called), || false) {
            first_site(span, &format!("`{}`", called), node);
            node.reach.through_code.insert(called.to_owned());
        }
        return;
    }
    node.reach.blocked = true;
    first_site(span, &format!("`{}`", called), node);
}

fn first_site(span: &Span, what: &str, node: &mut SyncNode) { if node.site.is_none() { node.site = Some(Site { span: span.clone(), what: what.to_owned() }); } }

fn sync_methods(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, node: &mut SyncNode) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unseen { node.reach.blocked = true; }
    for callee in known.resolved.iter() { if own.functions.contains_key(callee) { node.reach.calls.insert(callee.to_owned()); } else if !never_pauses_in(library, callee) { node.reach.blocked = true; } }
}

fn never_pauses_in(library: &Ledger, callee: &str) -> bool {
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return false };
    contract.sync_claim.is_sync()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Violation {
    pub span: Span,
    pub caller: String,
    pub promise: String,
    pub callee: String,
    pub from_library: bool,
    pub unpromised: bool,
    pub construct: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Promise {
    caller: String,
    promise: String,
    allowed: collections::BTreeSet<String>,
}

pub fn unit_violations(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger) -> Vec<Violation> {
    let mut found: Vec<Violation> = vec![];
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                let is_sync = *is_sync; let name = *name;
                let promise = match promise_of(&key_of_function((name).as_ref(), "", names), args, is_sync, sync_by, names) { Some(__nikaia_value) => __nikaia_value, None => continue };
                violations_in(&seen_in(body, names, unaliased, holes_of, &no_root, false), &promise, program, names, own, library, &mut found);
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                            let is_sync = *is_sync; let name = *name;
                            let promise = match promise_of(&key_of_function((name).as_ref(), &owner, names), args, is_sync, sync_by, names) { Some(__nikaia_value) => __nikaia_value, None => continue };
                            violations_in(&seen_in(body, names, unaliased, holes_of, &no_root, false), &promise, program, names, own, library, &mut found);
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    found
}

fn promise_of(caller: &str, args: &[FnArg], is_sync: bool, sync_by: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext) -> Option<Promise> {
    if !is_sync && sync_by.is_empty() { return None; }
    let mut allowed: collections::BTreeSet<String> = collections::BTreeSet::new();
    for arg in args.iter() {
        let declared = match (*arg.ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        if declared.is_sync { allowed.insert(names.resolve(arg.name).to_owned()); }
    }
    let mut named: Vec<String> = vec![];
    for one in sync_by.iter() {
        let one = *one;
        let parameter = names.resolve(one).to_owned();
        allowed.insert(parameter.to_owned());
        named.push(parameter);
    }
    let mut promise: String = String::from("sync");
    if !named.is_empty() {
        let joined = named.join(", ");
        promise = format!("sync({})", joined);
    }
    Some(Promise { caller: caller.to_owned(), promise, allowed })
}

fn violations_in(seen: &[Seen], promise: &Promise, program: &Program, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, found: &mut Vec<Violation>) {
    for one in seen.iter() {
        match one {
            Seen::Joins { construct, span } => { found.push(violation(promise, span, construct, false, false, true)); },
            Seen::Call { name, span, .. } => {
                if !name.contains("::") && promise.allowed.contains(name) { continue; }
                pausing_call((callee_named(names, name.to_owned(), own, library, &program.items)).as_ref(), span, promise, own, found);
            },
            Seen::Spawn { span } => { pausing_call(Some(&Callee::Opaque(None)), span, promise, own, found); },
            Seen::Opaque { span } => { pausing_call(Some(&Callee::Opaque(None)), span, promise, own, found); },
            _ => { },
        }
    }
}

fn pausing_call(callee: Option<&Callee>, span: &Span, promise: &Promise, own: &Ledger, found: &mut Vec<Violation>) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => {
            let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return };
            if !contract.sync_claim.is_sync() { found.push(violation(promise, span, name, false, unpromised(&contract.sync_claim), false)); }
        },
        Callee::Library { key, never_pauses } => {
            let never_pauses = *never_pauses;
            if !never_pauses { found.push(violation(promise, span, key, true, false, false)); }
        },
        Callee::Opaque(name) => {
            if a_stop((name).as_deref()) { return; }
            let called = nikaia_std::index::or(match name {
                Some(__nikaia_it) => Some(__nikaia_it.to_string()),
                None => None,
            }, || "something this compiler cannot resolve".into());
            found.push(violation(promise, span, &called, false, false, false));
        },
        _ => { },
    }
}

fn a_stop(name: Option<&str>) -> bool {
    let called = match name { Some(__nikaia_value) => __nikaia_value, None => return false };
    called == "panic"
}

fn unpromised(claim: &Sync) -> bool { claim.is_unpromised() }

fn violation(promise: &Promise, span: &Span, callee: &str, from_library: bool, unpromised: bool, construct: bool) -> Violation { Violation { span: span.clone(), caller: promise.caller.to_owned(), promise: promise.promise.to_owned(), callee: callee.to_owned(), from_library, unpromised, construct } }


