#[derive(Debug, Clone, PartialEq, Eq)]
struct TextTie {
    word: String,
    depth: i64,
    through_text: bool,
}

fn open_tier_scope(walk: &mut TierWalk) { walk.frames.push(vec![]); }

fn close_tier_scope(walk: &mut TierWalk) {
    if walk.frames.is_empty() { return; }
    let names = (*nikaia_std::index::get(&walk.frames, nikaia_std::index::at(walk.frames.len() as i64 - 1))).to_owned();
    for name in names.iter() {
        let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !stack.is_empty() { stack.pop(); }
        walk.locals.insert(name.to_owned(), stack);
    }
    walk.frames.pop();
}

fn tier_local(name: &str, walk: &TierWalk) -> Option<TierLocal> {
    let stack = match *nikaia_std::index::get(&walk.locals, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if stack.is_empty() { return None; }
    Some((*nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))).clone())
}

fn set_tier_local(name: &str, local: TierLocal, walk: &mut TierWalk) {
    let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if stack.is_empty() { return; }
    stack.pop();
    stack.push(local);
    walk.locals.insert(name.to_owned(), stack);
}

fn bind_tier_local(name: String, local: TierLocal, walk: &mut TierWalk) {
    let mut stack: Vec<TierLocal> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.locals, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    stack.push(local);
    walk.locals.insert(name.to_owned(), stack);
    if !walk.frames.is_empty() {
        let last = walk.frames.len() as i64 - 1;
        walk.frames[nikaia_std::index::at(last)].push(name);
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TierReads {
    tiers: collections::BTreeSet<String>,
    keeping: collections::BTreeSet<String>,
    arms: collections::BTreeSet<i64>,
    adopted: collections::BTreeSet<i64>,
}

fn no_reads() -> TierReads { TierReads { tiers: collections::BTreeSet::new(), keeping: collections::BTreeSet::new(), arms: collections::BTreeSet::new(), adopted: collections::BTreeSet::new() } }

fn tier_keeping_read(word: String, walk: &mut TierWalk) -> bool {
    let found = walk.keeping.contains(&word);
    walk.reads.keeping.insert(word);
    found
}

fn tier_arm_read(node: i64, walk: &mut TierWalk) -> bool {
    walk.reads.arms.insert(node);
    walk.param_arms.contains(&node)
}

fn plain_local(kinds: Kinds) -> TierLocal { TierLocal { kinds, of: None, literal: -1, declared: None, from: None, empty: -1, through: vec![] } }

fn tier_at(word: &str, walk: &mut TierWalk) -> Tier {
    if !walk.reads.tiers.contains(word) { walk.reads.tiers.insert(word.to_owned()); }
    let found = match (*nikaia_std::index::get(&walk.tiers, word)).copied() { Some(__nikaia_value) => __nikaia_value, None => return Tier::Owned };
    found.clone()
}

fn mixed_at(word: &str, walk: &mut TierWalk) -> bool { mixed(tier_at(word, walk)) }

fn seen(owner: &TextOwner, path: &[i64], walk: &mut TierWalk) -> String {
    let word = position_word(owner, path);
    if !walk.flows.known.contains_key(&word) { walk.flows.known.insert(word.to_owned(), TextPosition { owner: owner.clone(), path: path.to_owned() }); }
    word
}

fn a_map(names: &winnow_grammar::InternerContext, ty: &Type) -> bool {
    let name = match container_of(names, ty) { Some(__nikaia_value) => __nikaia_value, None => return false };
    is_a_map_name(&name)
}

fn a_container(names: &winnow_grammar::InternerContext, ty: &Type) -> bool { container_of(names, ty).is_some() }

fn flow_type(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, kinds: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if plain_string(ask.names, ty) {
        let word = seen(owner, &path, walk);
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.positions, &word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        walk.flows.positions.insert(word, kinds_joined(&before, kinds));
        return;
    }
    if a_container(ask.names, ty) {
        let mut at = 0;
        let keyed = a_map(ask.names, ty);
        for arg in ty.generics.iter() {
            path.push(at);
            if keyed {
                let word = seen(owner, &path, walk);
                walk.flows.in_maps.insert(word);
            }
            flow_type(owner, arg, path, kinds, ask, walk);
            path.pop();
            at += 1;
        }
    }
}

fn flow_value(going: &TierGoing, value: Option<&Expr>, kinds: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let owner = going.owner.clone();
    let ty = going.ty.clone();
    let path = going.path.to_owned();
    let plain = plain_string(ask.names, &ty);
    if plain {
        let from = handed_parameter(value, ask, &walk);
        if from.is_some() {
            let from_word: String = nikaia_std::index::or(from, || "".into());
            let to = seen(&owner, &path, walk);
            walk.flows.param_into.insert((from_word, to));
        }
    }
    if plain && value.is_some() {
        let read = match value { Some(__nikaia_value) => __nikaia_value, None => return };
        let mut sources: Vec<String> = vec![];
        read_through(read, ask, walk, &mut sources);
        let to = seen(&owner, &path, walk);
        for from_word in sources.iter() { if *from_word != to { walk.flows.read_into.insert((from_word.to_owned(), to.to_owned())); } }
    }
    let mut linked = a_container(ask.names, &ty) && comes_whole(value, ask, walk);
    if plain && tier_a_name(value) {
        let back = nikaia_std::index::or(text_source_word(value, ask, walk), || "".into());
        linked = back != "" && back == position_word(&owner, &path);
    }
    if !linked { flow_type(&owner, &ty, &mut path.to_owned(), kinds, ask, walk); }
    if plain && kinds.still && value.is_some() {
        let given_value = match value { Some(__nikaia_value) => __nikaia_value, None => return };
        let mut sources: Vec<String> = vec![];
        still_sources(given_value, ask, walk, &mut sources);
        let to = seen(&owner, &path, walk);
        for from_word in sources.iter() { if *from_word != to { walk.flows.still_into.insert((from_word.to_owned(), to.to_owned())); } }
    }
    if a_container(ask.names, &ty) && path.is_empty() && holds_text(ask.names, &ty) { adopt(value, going, ask, walk); }
    if !plain && !a_container(ask.names, &ty) && kinds.still && value.is_some() {
        let unseen = match value { Some(__nikaia_value) => __nikaia_value, None => return };
        kept_unseen(unseen, ask, walk);
    }
    if walk.in_hole && walk.hole_text < 0 && going.wrap && plain {
        let word = seen(&owner, &path, walk);
        walk.flows.unwrappable.insert(word);
        return;
    }
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    if plain && going.wrap && !a_null(given) && mixed_at(&position_word(&owner, &path), walk) { if ty.is_nullable { hand_value_over(given, Hand::Maybe, walk); } else { hand_value_over(given, Hand::Either, walk); } }
    kept_literal(given, &owner, &path, &ty, ask, walk);
    if a_container(ask.names, &ty) { flow_whole(going, given, ask, walk); }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TierGoing {
    owner: TextOwner,
    ty: Type,
    path: Vec<i64>,
    wrap: bool,
}

fn going_into(owner: &TextOwner, ty: &Type, path: Vec<i64>, wrap: bool) -> TierGoing { TierGoing { owner: owner.clone(), ty: ty.clone(), path, wrap } }

fn adopt(value: Option<&Expr>, going: &TierGoing, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    let name = match given {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return,
    };
    let local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    if local.empty < 0 { return; }
    let kind = nikaia_std::index::or(container_of(ask.names, &going.ty), || "".into());
    if is_a_map_name(&kind) || kind == "HashSet" { return; }
    walk.flows.adopted.insert(local.empty, Declaring { owner: going.owner.clone(), ty: going.ty.clone() });
}

fn an_empty_container(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    match value {
        Expr::ListLit { items, .. } => items.is_empty(),
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !args.is_empty() { return false; }
            let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
            is_a_container_name(&callee)
        },
        _ => false,
    }
}

fn holds_text(names: &winnow_grammar::InternerContext, ty: &Type) -> bool {
    if plain_string(names, ty) { return true; }
    if !a_container(names, ty) { return false; }
    for arg in ty.generics.iter() { if holds_text(names, arg) { return true; } }
    false
}

fn flow_word(word: &str, kinds: &Kinds, walk: &mut TierWalk) {
    let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.positions, word) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || no_kinds().into());
    walk.flows.positions.insert(word.to_owned(), kinds_joined(&before, kinds));
}

fn text_source_word(value: Option<&Expr>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    let source = source_of(given, ask, walk);
    if source.is_some() {
        let found = match source { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !plain_string(ask.names, &found.ty) { return None; }
        return Some(seen(&found.owner, &no_path(), walk));
    }
    match given {
        Expr::Variable(name, _) => {
            let name = *name;
            let local = match tier_local(ask.names.resolve(name), &walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
            match local.from.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }
        },
        _ => None,
    }
}

fn read_through(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk, out: &mut Vec<String>) {
    match value {
        Expr::Coalesce { value: first, fallback, .. } => {
            let first = nikaia_std::boxed::open(first); let fallback = nikaia_std::boxed::open(fallback);
            read_through(first, ask, walk, out);
            read_through(fallback, ask, walk, out);
            return;
        },
        Expr::Try(inner, _) => {
            let inner = nikaia_std::boxed::open(inner);
            read_through(inner, ask, walk, out);
            return;
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let local = tier_local(ask.names.resolve(name), &walk);
            if local.is_some() {
                let found = match local { Some(__nikaia_value) => __nikaia_value, None => return };
                for word in found.through.iter() { out.push(word.to_owned()); }
            }
        },
        _ => { },
    }
    let source = match source_of(value, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    if plain_string(ask.names, &source.ty) { out.push(seen(&source.owner, &no_path(), walk)); }
}

fn element_word(iter: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    match iter {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let name = ask.names.resolve(method);
            if args.is_empty() && (name == "iter" || name == "drain" || name == "into_iter") { return element_word(receiver, ask, walk); }
        },
        _ => { },
    }
    let found = match source_of(iter, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ty = found.ty.clone();
    if !a_container(ask.names, &ty) || a_map(ask.names, &ty) || ty.generics.is_empty() { return None; }
    if !plain_string(ask.names, nikaia_std::index::get(&ty.generics, 0)) { return None; }
    Some(seen(&found.owner, &vec![0], walk))
}

fn tier_a_name(value: Option<&Expr>) -> bool {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return false };
    matches!(given, Expr::Variable(_, _))
}

fn map_walked(iter: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<Declaring> {
    match iter {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let name = ask.names.resolve(method);
            if args.is_empty() && (name == "iter" || name == "drain" || name == "into_iter" || name == "iter_mut") { return map_walked(receiver, ask, walk); }
        },
        _ => { },
    }
    let found = match source_of(iter, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !a_map(ask.names, &found.ty) || found.ty.generics.len() != 2 { return None; }
    Some(found)
}

fn beside_its_own(kinds: &Kinds) -> bool { kinds.still && kinds.owned }

fn any_still(given: &[Kinds]) -> bool {
    for kinds in given.iter() {
        let kinds = *kinds;
        if kinds.still { return true; }
    }
    false
}

fn std_has_method(method: &str, ask: &TierAsk<'_, '_, '_, '_>) -> bool { !method_keys(ask.methods, method).is_empty() }

fn kept_args(args: &[Expr], given: &[Kinds], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let mut at: i64 = 0;
    for arg in args.iter() {
        if ((at) as usize) < given.len() && nikaia_std::index::get(&given, (at) as usize).still { kept_unseen(arg, ask, walk); }
        at += 1;
    }
}

fn flow_payload(callee: &str, args: &[Expr], given: &[Kinds], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let parts = match match *nikaia_std::index::get(&walk.declared.variants, callee) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let (of, variant) = variant_named(callee);
    let mut at: i64 = 0;
    while at < args.len() as i64 && at < given.len() as i64 && at < parts.len() as i64 {
        let owner = TextOwner::Variant(of.to_owned(), variant.to_owned(), at);
        flow_value(&going_into(&owner, nikaia_std::index::get(&parts, nikaia_std::index::at(at)), vec![], true), Some(nikaia_std::index::get(&args, nikaia_std::index::at(at))), nikaia_std::index::get(&given, nikaia_std::index::at(at)), ask, walk);
        at += 1;
    }
}

fn bind_tuple_parts(pattern: &MatchPattern, scrutinee: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if scrutinee.either || scrutinee.owned && (scrutinee.view || scrutinee.still) { return; }
    match pattern {
        MatchPattern::Tuple { path, parts } => {
            if !path.is_empty() { return; }
            for part in parts.iter() {
                match part {
                    MatchPattern::Path(named) => { if named.len() == 1 && !names_a_type(ask.names.resolve(*nikaia_std::index::get(&named, 0))) { bind_tier_local(ask.names.resolve(*nikaia_std::index::get(&named, 0)).to_owned(), plain_local(scrutinee.clone()), walk); } },
                    _ => { },
                }
            }
        },
        _ => { },
    }
}

fn bind_static_payloads(pattern: &MatchPattern, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    let mut bound = false;
    match pattern {
        MatchPattern::Tuple { path, parts } => {
            let written = unaliased_in(ask.aliases, &joined_segments(path, ask.names));
            let declared = match match *nikaia_std::index::get(&walk.declared.variants, &written) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => return false };
            let (of, variant) = variant_named(&written);
            let mut at: i64 = 0;
            for part in parts.iter() {
                if at >= declared.len() as i64 { return bound; }
                let owner = TextOwner::Variant(of.to_owned(), variant.to_owned(), at);
                let lasting = plain_string(ask.names, nikaia_std::index::get(&declared, nikaia_std::index::at(at))) && lasting_tier(tier_at(&position_word(&owner, &no_path()), walk));
                match part {
                    MatchPattern::Path(named) => {
                        if lasting && named.len() == 1 && !names_a_type(ask.names.resolve(*nikaia_std::index::get(&named, 0))) {
                            let mut local = plain_local(still_kinds());
                            local.from = Some(seen(&owner, &no_path(), walk));
                            bind_tier_local(ask.names.resolve(*nikaia_std::index::get(&named, 0)).to_owned(), local, walk);
                            bound = true;
                        }
                    },
                    _ => { },
                }
                at += 1;
            }
        },
        _ => { },
    }
    bound
}

fn variant_named(callee: &str) -> (String, String) {
    let variant = last_segment(callee);
    let of = nikaia_std::index::or(callee.strip_suffix(&format!("::{}", variant)), || "").to_owned();
    (of, variant)
}

fn variant_handed_on(written: &str, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let parts = match match *nikaia_std::index::get(&walk.declared.variants, written) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let (of, variant) = variant_named(written);
    let mut at = 0;
    for part in parts.iter() {
        flow_type(&TextOwner::Variant(of.to_owned(), variant.to_owned(), at), part, &mut vec![], &owned_kinds(), ask, walk);
        at += 1;
    }
}

fn names_a_type(name: &str) -> bool {
    let first = match name.chars().next() { Some(__nikaia_value) => __nikaia_value, None => return false };
    first >= 'A' && first <= 'Z'
}

fn kept_unseen(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    match value {
        Expr::ListLit { items, .. } => { for item in items.iter() { kept_unseen(item, ask, walk); } },
        Expr::Tuple(items, _) => { for item in items.iter() { kept_unseen(item, ask, walk); } },
        Expr::Coalesce { value: first, fallback, .. } => {
            let first = nikaia_std::boxed::open(first); let fallback = nikaia_std::boxed::open(fallback);
            kept_unseen(first, ask, walk);
            kept_unseen(fallback, ask, walk);
        },
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let whole = source_of(base, ask, walk);
            if container_source((whole).as_ref(), ask) {
                kept_unseen(base, ask, walk);
                return;
            }
            let mut sources: Vec<String> = vec![];
            still_sources(value, ask, walk, &mut sources);
            for read_from in sources.iter() {
                flow_word(read_from, &owned_kinds(), walk);
                walk.flows.demoted.insert(read_from.to_owned());
            }
        },
        _ => {
            let whole = source_of(value, ask, walk);
            if whole.is_some() {
                let found = match whole { Some(__nikaia_value) => __nikaia_value, None => return };
                if a_container(ask.names, &found.ty) {
                    demote_inside(&found.owner, &found.ty, &mut vec![], ask, walk);
                    return;
                }
            }
            let mut sources: Vec<String> = vec![];
            still_sources(value, ask, walk, &mut sources);
            for read_from in sources.iter() {
                flow_word(read_from, &owned_kinds(), walk);
                walk.flows.demoted.insert(read_from.to_owned());
            }
        },
    }
}

fn literals_beside_null(value: &Expr) -> bool {
    let mut tails: Vec<Expr> = vec![];
    match value {
        Expr::If { then_branch, else_branch, .. } => {
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
            if then_branch.stmts.len() != 1 || otherwise.stmts.len() != 1 { return false; }
            match &nikaia_std::index::get(&then_branch.stmts, 0).node {
                Stmt::Expr(last) => { tails.push(last.clone()); },
                _ => { return false; },
            }
            match &nikaia_std::index::get(&otherwise.stmts, 0).node {
                Stmt::Expr(last) => { tails.push(last.clone()); },
                _ => { return false; },
            }
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { tails.push(arm.body.clone()); } },
        _ => { return false; },
    }
    let mut nulls = false;
    for tail in tails.iter() { if a_null(tail) { nulls = true; } else if !a_literal_text(tail) { return false; } }
    nulls
}

fn items_beside_null(items: &[Expr]) -> bool {
    let mut nulls = false;
    for item in items.iter() { if a_null(item) { nulls = true; } else if !a_literal_text(item) { return false; } }
    nulls
}

fn a_variable(expr: &Expr) -> bool { matches!(expr, Expr::Variable(_, _)) }

fn demote_inside(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if plain_string(ask.names, ty) {
        let word = seen(owner, &path, walk);
        flow_word(&word, &owned_kinds(), walk);
        walk.flows.demoted.insert(word);
        return;
    }
    if !a_container(ask.names, ty) { return; }
    let mut at = 0;
    for arg in ty.generics.iter() {
        path.push(at);
        demote_inside(owner, arg, &mut path.to_owned(), ask, walk);
        path.pop();
        at += 1;
    }
}

fn unlinked_inside(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if plain_string(ask.names, ty) {
        let word = seen(owner, &path, walk);
        walk.flows.unlinked.insert(word);
        return;
    }
    if !a_container(ask.names, ty) { return; }
    let mut at = 0;
    for arg in ty.generics.iter() {
        path.push(at);
        unlinked_inside(owner, arg, &mut path.to_owned(), ask, walk);
        path.pop();
        at += 1;
    }
}

fn still_sources(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk, out: &mut Vec<String>) {
    match value {
        Expr::Block(block, _) => { still_tail(block, ask, walk, out); },
        Expr::If { then_branch, else_branch, .. } => {
            still_tail(then_branch, ask, walk, out);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
            still_tail(otherwise, ask, walk, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { still_sources(&arm.body, ask, walk, out); } },
        Expr::Coalesce { value: first, fallback, .. } => {
            let first = nikaia_std::boxed::open(first); let fallback = nikaia_std::boxed::open(fallback);
            still_sources(first, ask, walk, out);
            still_sources(fallback, ask, walk, out);
        },
        _ => {
            let read_from = match text_source_word(Some(value), ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            out.push(read_from);
        },
    }
}

fn still_tail(block: &Block, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk, out: &mut Vec<String>) {
    if block.stmts.is_empty() { return; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(last) => { still_sources(last, ask, walk, out); },
        _ => { },
    }
}

fn changed_in_place(target: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    match target {
        Expr::Index { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let element = match element_word(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            walk.flows.unwrappable.insert(element.to_owned());
            flow_word(&element, &owned_kinds(), walk);
            return;
        },
        _ => { },
    }
    let place = place_of(target, ask, walk);
    if place.is_some() {
        let found = match place { Some(__nikaia_value) => __nikaia_value, None => return };
        if plain_string(ask.names, &found.ty) {
            let word = seen(&found.owner, &no_path(), walk);
            walk.flows.changed.insert(word.to_owned());
            walk.flows.unwrappable.insert(word.to_owned());
            flow_word(&word, &owned_kinds(), walk);
        }
        return;
    }
    let read_from = match text_source_word(Some(target), ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.flows.changed.insert(read_from.to_owned());
    walk.flows.unwrappable.insert(read_from.to_owned());
    flow_word(&read_from, &owned_kinds(), walk);
}

fn a_null(value: &Expr) -> bool { matches!(value, Expr::LitNull(_)) }

fn handed_parameter(value: Option<&Expr>, ask: &TierAsk<'_, '_, '_, '_>, walk: &TierWalk) -> Option<String> {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    let name = match given {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return None,
    };
    let local = match tier_local(&name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return None };
    let parameter = matches!(declared.owner, TextOwner::Param(_, _));
    if !parameter || !plain_string(ask.names, &declared.ty) { return None; }
    let empty: Vec<i64> = vec![];
    Some(position_word(&declared.owner, &empty))
}

fn comes_whole(value: Option<&Expr>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return false };
    let collected = match given {
        Expr::MethodCall { method, args, .. } => { let method = *method; args.is_empty() && ask.names.resolve(method) == "collect" },
        Expr::ListLit { .. } => true,
        _ => false,
    };
    !collected && source_of(given, ask, walk).is_some()
}

fn flow_whole(going: &TierGoing, value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ty = going.ty.clone();
    let a_list = a_container(ask.names, &ty) && !a_map(ask.names, &ty) && !ty.generics.is_empty();
    match value {
        Expr::ListLit { items, .. } => {
            if !a_list { return; }
            let element = (*nikaia_std::index::get(&ty.generics, 0)).clone();
            let beside_null = items_beside_null(items);
            for item in items.iter() {
                let mut kinds = tier_expr(item, ask, walk);
                if beside_null && !a_null(item) { kinds = owned_kinds(); }
                let mut at = going.path.to_owned();
                at.push(0);
                flow_value(&going_into(&going.owner, &element, at, true), Some(item), &kinds, ask, walk);
            }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if ask.names.resolve(method) == "collect" && args.is_empty() {
                collected_into(going, receiver, ask, walk);
                return;
            }
            link_from(going, value, ask, walk);
        },
        _ => { link_from(going, value, ask, walk); },
    }
}

fn link_from(going: &TierGoing, value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let source = source_of(value, ask, walk);
    if source.is_none() {
        let parameter = matches!(going.owner, TextOwner::Param(_, _));
        if parameter { unlinked_inside(&going.owner, &going.ty, &mut going.path.to_owned(), ask, walk); }
        return;
    }
    let from = match source { Some(__nikaia_value) => __nikaia_value, None => return };
    let to = Declaring { owner: going.owner.clone(), ty: going.ty.clone() };
    link(&from, &mut vec![], &to, &mut going.path.to_owned(), ask, walk);
}

fn collected_into(going: &TierGoing, receiver: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ty = going.ty.clone();
    if a_map(ask.names, &ty) {
        let keys = mixed_part(going, 0, ask, walk);
        let values = mixed_part(going, 1, ask, walk);
        if keys && values { hand_value_over(receiver, Hand::Pairs, walk); } else if keys { hand_value_over(receiver, Hand::Keys, walk); } else if values { hand_value_over(receiver, Hand::Values, walk); }
        return;
    }
    if !a_container(ask.names, &ty) || ty.generics.is_empty() { return; }
    if !plain_string(ask.names, nikaia_std::index::get(&ty.generics, 0)) { return; }
    let mut at = going.path.to_owned();
    at.push(0);
    let word = seen(&going.owner, &at, walk);
    if walk.in_hole && walk.hole_text < 0 { walk.flows.unwrappable.insert(word); } else if mixed_at(&word, walk) { hand_value_over(receiver, Hand::Items, walk); }
}

fn mixed_part(going: &TierGoing, at: i64, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    if (going.ty.generics.len() as i64) <= at { return false; }
    if !plain_string(ask.names, nikaia_std::index::get(&going.ty.generics, nikaia_std::index::at(at))) { return false; }
    let mut path = going.path.to_owned();
    path.push(at);
    let word = seen(&going.owner, &path, walk);
    if walk.in_hole && walk.hole_text < 0 {
        walk.flows.unwrappable.insert(word);
        return false;
    }
    mixed_at(&word, walk)
}

fn source_of(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<Declaring> {
    match value {
        Expr::Variable(_, _) => place_of(value, ask, walk),
        Expr::Field { .. } => place_of(value, ask, walk),
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); called_result(func, ask, &walk) },
        Expr::MethodCall { method, .. } => { let method = *method; method_result(ask.names.resolve(method), &walk) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); source_of(inner, ask, walk) },
        _ => None,
    }
}

fn called_result(func: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &TierWalk) -> Option<Declaring> {
    let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let function = match *nikaia_std::index::get(&walk.declared.fns, &callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Returned(callee.to_owned()), ty: result.clone() })
}

fn method_result(method: &str, walk: &TierWalk) -> Option<Declaring> {
    let keys = match *nikaia_std::index::get(&walk.declared.methods, method) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if keys.len() != 1 { return None; }
    let key = (*nikaia_std::index::get(&keys, 0)).to_owned();
    let function = match *nikaia_std::index::get(&walk.declared.fns, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Returned(key.to_owned()), ty: result.clone() })
}

fn tier_callee(func: &Expr, ask: &TierAsk<'_, '_, '_, '_>) -> Option<String> { written_callee(ask.names, func, &|name| { unaliased_in(ask.aliases, name) }) }

fn link(from: &Declaring, from_path: &mut Vec<i64>, to: &Declaring, to_path: &mut Vec<i64>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let from_ty = from.ty.clone();
    let to_ty = to.ty.clone();
    if plain_string(ask.names, &from_ty) && plain_string(ask.names, &to_ty) {
        let a = seen(&from.owner, &from_path, walk);
        let b = seen(&to.owner, &to_path, walk);
        if a != b { walk.flows.links.insert((a, b)); }
        return;
    }
    if !a_container(ask.names, &from_ty) || !a_container(ask.names, &to_ty) || (from_ty.generics.len() as i64) != to_ty.generics.len() as i64 { return; }
    let keyed = a_map(ask.names, &from_ty) || a_map(ask.names, &to_ty);
    for at in 0..from_ty.generics.len() as i64 {
        from_path.push(at);
        to_path.push(at);
        if keyed {
            let a = seen(&from.owner, &from_path, walk);
            let b = seen(&to.owner, &to_path, walk);
            walk.flows.in_maps.insert(a);
            walk.flows.in_maps.insert(b);
        }
        let inner_from = Declaring { owner: from.owner.clone(), ty: (*nikaia_std::index::get(&from_ty.generics, nikaia_std::index::at(at))).clone() };
        let inner_to = Declaring { owner: to.owner.clone(), ty: (*nikaia_std::index::get(&to_ty.generics, nikaia_std::index::at(at))).clone() };
        link(&inner_from, &mut from_path.to_owned(), &inner_to, &mut to_path.to_owned(), ask, walk);
        from_path.pop();
        to_path.pop();
    }
}

fn hand_value_over(value: &Expr, hand: Hand, walk: &mut TierWalk) {
    if walk.in_hole && walk.hole_text >= 0 {
        let at = walk.hole_text;
        let mut wraps: Vec<HoleWrap> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.hole_wraps, &at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        wraps.push(HoleWrap { value: value.clone(), hand });
        walk.flows.hole_wraps.insert(at, wraps);
        return;
    }
    walk.flows.wraps.insert(node_key(value), hand);
}

fn kinds_of(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    if plain_string(ask.names, ty) {
        return match tier_at(&position_word(owner, &path), walk) {
            Tier::Owned => owned_kinds(),
            Tier::View => view_kinds(),
            Tier::Mixed => either_kinds(),
            Tier::Lasting => still_kinds(),
        };
    }
    if ty.is_view && ask.names.resolve(ty.name) == "String" { return view_kinds(); }
    if a_container(ask.names, ty) {
        let mut out = no_kinds();
        let mut at = 0;
        for arg in ty.generics.iter() {
            path.push(at);
            out = kinds_joined(&out, &kinds_of(owner, arg, &mut path.to_owned(), ask, walk));
            path.pop();
            at += 1;
        }
        if !no_text(&out) { return out; }
    }
    owned_kinds()
}

fn kinds_of_declared(declared: &Declaring, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds { kinds_of(&declared.owner, &declared.ty, &mut vec![], ask, walk) }

fn element_kinds(declared: &Declaring, keys: bool, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let ty = declared.ty.clone();
    if !a_container(ask.names, &ty) { return kinds_of_declared(declared, ask, walk); }
    let mut at: i64 = 0;
    if a_map(ask.names, &ty) && !keys { at = 1; }
    if ty.generics.len() <= ((at) as usize) { return owned_kinds(); }
    kinds_of(&declared.owner, nikaia_std::index::get(&ty.generics, (at) as usize), &mut vec![at], ask, walk)
}

fn place_of(expr: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<Declaring> {
    match expr {
        Expr::Variable(name, _) => { let name = *name; declared_local(ask.names.resolve(name), &walk) },
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; field_place(base, ask.names.resolve(name), ask, walk) },
        _ => None,
    }
}

fn declared_local(name: &str, walk: &TierWalk) -> Option<Declaring> {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match local.declared.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn field_place(base: &Expr, field: &str, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<Declaring> {
    let owner = match tier_struct_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let key = (owner.to_owned(), field.to_owned());
    let found = match *nikaia_std::index::get(&walk.declared.fields, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Field(owner.to_owned(), field.to_owned()), ty: found.ty.clone() })
}

fn tier_block(block: &Block, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let back = walk.tail_back;
    walk.tail_back = false;
    open_tier_scope(walk);
    let mut tail = no_kinds();
    let mut k: i64 = 0;
    for stmt in block.stmts.iter() {
        let before = walk.handed_back;
        let bound = handed_by_name(&stmt.node, block, k, ask);
        if bound >= 0 { walk.handed_back = bound; }
        if k + 1 == block.stmts.len() as i64 && (walk.frames.len() == 2 || back) && walk.result.is_some() { walk.tail_back = a_value_statement(&stmt.node); }
        let kinds = tier_statement(&stmt.node, stmt.span.start as i64, ask, walk);
        walk.tail_back = false;
        if bound >= 0 { walk.handed_back = before; }
        if k + 1 == block.stmts.len() as i64 {
            tail = kinds;
            if (walk.frames.len() == 2 || back) && walk.result.is_some() {
                match &stmt.node {
                    Stmt::Expr(last) => {
                        tie_leaves(last, -1, None, true, ask, walk);
                        if back { tail = handed_kinds(last, &tail, ask, walk); }
                    },
                    _ => { },
                }
            }
        }
        k += 1;
    }
    close_tier_scope(walk);
    tail
}

fn a_value_statement(stmt: &Stmt) -> bool { matches!(stmt, Stmt::Expr(_)) }

fn handed_by_name(stmt: &Stmt, block: &Block, at: i64, ask: &TierAsk<'_, '_, '_, '_>) -> i64 {
    match stmt {
        Stmt::Let { names, value, .. } => { if names.len() == 1 && handed_struct(value) >= 0 && local_struct_handed_back(ask.names, block, at, ask.names.resolve(*nikaia_std::index::get(&names, 0))) > 0 { handed_struct(value) } else { -1 } },
        _ => -1,
    }
}

fn tier_statement(stmt: &Stmt, at: i64, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    match stmt {
        Stmt::Let { names, value, ty, .. } => {
            tier_let(names, value, (ty).as_ref(), at, ask, walk);
            tie_bound(names, value, ask, walk);
        },
        Stmt::Assign { target, op, value } => {
            tie_stored(target, value, ask, walk);
            tier_assign(target, value, ask, walk);
            if op.is_some() { changed_in_place(target, ask, walk); }
        },
        Stmt::For { bindings, iter, body, .. } => {
            let kinds = tier_expr(iter, ask, walk);
            let from = element_word(iter, ask, walk);
            let mut map: Option<Declaring> = None;
            if bindings.len() == 2 { map = map_walked(iter, ask, walk); }
            open_tier_scope(walk);
            let mut at = 0;
            for binding in bindings.iter() {
                let binding = *binding;
                let mut local = plain_local(kinds.clone());
                if bindings.len() == 1 {
                    local.from = match from.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    };
                }
                if map.is_some() {
                    let found = match match map.as_ref() {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    } { Some(__nikaia_value) => __nikaia_value, None => continue };
                    local = plain_local(element_kinds(&found, at == 0, ask, walk));
                    if at == 0 && plain_string(ask.names, nikaia_std::index::get(&found.ty.generics, 0)) { local.from = Some(seen(&found.owner, &vec![0], walk)); }
                }
                bind_tier_local(ask.names.resolve(binding).to_owned(), local, walk);
                at += 1;
            }
            tier_block(body, ask, walk);
            close_tier_scope(walk);
        },
        Stmt::While { cond, body } => {
            tier_expr(cond, ask, walk);
            tier_block(body, ask, walk);
        },
        Stmt::Return(value) => {
            let given = match value { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
            tie_leaves(given, -1, None, true, ask, walk);
            let before = walk.handed_back;
            walk.handed_back = handed_struct(given);
            let kinds = tier_expr(given, ask, walk);
            walk.handed_back = before;
            flow_result(given, &kinds, ask, walk);
        },
        Stmt::Expr(expr) => { return tier_expr(expr, ask, walk); },
        _ => { },
    }
    no_kinds()
}

fn tier_let(names: &[winnow_grammar::Symbol], value: &Expr, ty: Option<&Type>, at: i64, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    walk.read_here = ty.is_none();
    let kinds = tier_expr(value, ask, walk);
    let mut of = tier_struct_of(value, ask, walk);
    let mut literal: i64 = -1;
    let mut empty: i64 = -1;
    let mut declared: Option<Declaring> = None;
    let written = ty.is_some();
    let from = text_source_word(Some(value), ask, walk);
    let mut through: Vec<String> = vec![];
    read_through(value, ask, walk, &mut through);
    if written {
        let declared_ty = match match ty {
            Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        of = Some(ask.names.resolve(declared_ty.name).to_owned());
        declared = Some(Declaring { owner: TextOwner::Let(at), ty: declared_ty });
    } else {
        if a_literal_text(value) { literal = at; }
        let source = source_of(value, ask, walk);
        if container_source((source).as_ref(), ask) { declared = source; }
        if declared.is_none() && an_empty_container(value, ask) {
            empty = at;
            walk.reads.adopted.insert(at);
            declared = match *nikaia_std::index::get(&walk.adopted, &at) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
        }
    }
    let mut bound = kinds;
    if declared.is_some() {
        let found = match match declared.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        if !written { bound = kinds_of_declared(&found, ask, walk); } else {
            flow_value(&going_into(&found.owner, &found.ty, vec![], true), Some(value), &kinds, ask, walk);
            bound = kinds_of_declared(&found, ask, walk);
        }
    }
    if names.len() == 1 {
        let local = TierLocal { kinds: bound, of, literal, declared, from, empty, through };
        bind_tier_local(ask.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), local, walk);
        return;
    }
    if !written && !(bound.owned && (bound.view || bound.still)) && !bound.either {
        for name in names.iter() {
            let name = *name;
            bind_tier_local(ask.names.resolve(name).to_owned(), plain_local(bound.clone()), walk);
        }
    }
}

fn container_source(source: Option<&Declaring>, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    let found = match source { Some(__nikaia_value) => __nikaia_value, None => return false };
    a_container(ask.names, &found.ty)
}

fn a_literal_text(value: &Expr) -> bool {
    match value {
        Expr::LitStr { .. } => true,
        Expr::Block(block, _) => a_literal_tail(block),
        Expr::If { then_branch, else_branch, .. } => {
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
            a_literal_tail(then_branch) && a_literal_tail(otherwise)
        },
        Expr::Match { arms, .. } => {
            if arms.is_empty() { return false; }
            for arm in arms.iter() { if !a_literal_text(&arm.body) { return false; } }
            true
        },
        _ => false,
    }
}

fn a_literal_tail(block: &Block) -> bool {
    if block.stmts.len() != 1 { return false; }
    match &nikaia_std::index::get(&block.stmts, 0).node {
        Stmt::Expr(last) => a_literal_text(last),
        _ => false,
    }
}

fn tier_assign(target: &Expr, value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let kinds = tier_expr(value, ask, walk);
    match target {
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let key = tier_expr(index, ask, walk);
            let found_place = place_of(base, ask, walk);
            if found_place.is_none() {
                if key.still { kept_unseen(index, ask, walk); }
                if kinds.still { kept_unseen(value, ask, walk); }
                return;
            }
            let place = match found_place { Some(__nikaia_value) => __nikaia_value, None => return };
            let ty = place.ty.clone();
            if !a_container(ask.names, &ty) { return; }
            if a_map(ask.names, &ty) {
                if ty.generics.len() == 2 {
                    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(index), &key, ask, walk);
                    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 1), vec![1], true), Some(value), &kinds, ask, walk);
                }
                return;
            }
            if !ty.generics.is_empty() { flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(value), &kinds, ask, walk); }
        },
        _ => {
            let place = place_of(target, ask, walk);
            if place.is_some() {
                let found = match place { Some(__nikaia_value) => __nikaia_value, None => return };
                flow_value(&going_into(&found.owner, &found.ty, vec![], true), Some(value), &kinds, ask, walk);
            } else if kinds.still && !a_variable(target) { kept_unseen(value, ask, walk); }
            let name = match target {
                Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
                _ => return,
            };
            let mut local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            if local.declared.is_none() {
                local.kinds = kinds_joined(&local.kinds, &kinds);
                let read_from: String = nikaia_std::index::or(match local.from.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || "".into());
                if read_from != "" {
                    walk.flows.changed.insert(read_from.to_owned());
                    flow_word(&read_from, &kinds, walk);
                }
            }
            local.literal = -1;
            set_tier_local(&name, local, walk);
        },
    }
}

fn flow_result(value: &Expr, kinds: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let key = match match walk.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let function = match match *nikaia_std::index::get(&walk.declared.fns, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let result = match function.result { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut handed = handed_kinds(value, kinds, ask, walk);
    if plain_string(ask.names, &result) && !function.of_a_trait {
        let mut sides: Vec<String> = vec![];
        if lendable_sides(value, ask, walk, &mut sides) && !sides.is_empty() {
            let empty: Vec<i64> = vec![];
            let to = seen(&TextOwner::Returned(key.to_owned()), &empty, walk);
            for word in sides.iter() {
                let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.lent_kinds, word) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || no_kinds().into());
                walk.flows.lent_kinds.insert(word.to_owned(), kinds_joined(&before, &handed));
                let lent_before = nikaia_std::index::or(*nikaia_std::index::get(&walk.flows.lent_uses, word), || 0);
                walk.flows.lent_uses.insert(word.to_owned(), lent_before + 1);
                walk.flows.lent_into.insert((word.to_owned(), to.to_owned()));
            }
            handed = no_kinds();
        }
    }
    flow_value(&going_into(&TextOwner::Returned(key.to_owned()), &result, vec![], false), Some(value), &handed, ask, walk);
}

fn lendable_sides(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk, out: &mut Vec<String>) -> bool {
    match value {
        Expr::Coalesce { value: first, fallback, .. } => {
            let first = nikaia_std::boxed::open(first); let fallback = nikaia_std::boxed::open(fallback);
            return lendable_sides(first, ask, walk, out) && lendable_sides(fallback, ask, walk, out);
        },
        Expr::Return(_, _) => { return true; },
        Expr::Throw(_, _) => { return true; },
        _ => { },
    }
    if a_null(value) { return true; }
    let word = match lendable_parameter(value, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    out.push(word);
    true
}

fn count_use(name: &str, walk: &mut TierWalk) {
    let local = match tier_local(name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut word: String = String::from("");
    if local.declared.is_some() {
        let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return };
        let parameter = matches!(declared.owner, TextOwner::Param(_, _));
        if !parameter { return; }
        word = position_word(&declared.owner, &no_path());
    } else {
        word = match match local.from.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
    }
    let before = nikaia_std::index::or(*nikaia_std::index::get(&walk.flows.uses, &word), || 0);
    walk.flows.uses.insert(word, before + 1);
}

fn handed_struct(value: &Expr) -> i64 {
    match value {
        Expr::StructLit { .. } => id_of(value) as i64,
        _ => -1,
    }
}

fn lendable_parameter(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    let name = match value {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return None,
    };
    let local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut owner: Option<TextOwner> = None;
    let declared = &local.declared;
    if declared.is_some() {
        let found = match declared { Some(__nikaia_value) => __nikaia_value, None => return None };
        owner = Some(found.owner.clone());
    } else {
        let from = match local.from { Some(__nikaia_value) => __nikaia_value, None => return None };
        let position = match *nikaia_std::index::get(&walk.flows.known, &from) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if !position.path.is_empty() { return None; }
        owner = Some(position.owner.clone());
    }
    let parameter = match owner { Some(__nikaia_value) => __nikaia_value, None => return None };
    let (key, at) = match parameter {
        TextOwner::Param(ref key, at) => (key.to_owned(), at),
        _ => return None,
    };
    let function = match match *nikaia_std::index::get(&walk.declared.fns, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return None };
    if function.of_a_trait || at >= function.params.len() as i64 || *nikaia_std::index::get(&function.changes, nikaia_std::index::at(at)) { return None; }
    let ty = (*nikaia_std::index::get(&function.params, nikaia_std::index::at(at))).clone();
    if !plain_string(ask.names, &ty) || ty.is_view { return None; }
    Some(seen(&parameter, &no_path(), walk))
}

fn tie_depth(name: &str, walk: &TierWalk) -> i64 {
    let mut at = walk.frames.len() as i64 - 1;
    while at >= 0 {
        if nikaia_std::list::contains(nikaia_std::index::get(&walk.frames, nikaia_std::index::at(at)), &name) { return at; }
        at -= 1;
    }
    -1
}

fn tie_root(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>) -> Option<String> {
    match value {
        Expr::Variable(name, _) => { let name = *name; Some(ask.names.resolve(name).to_owned()) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tie_root(base, ask) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); tie_root(base, ask) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); tie_root(base, ask) },
        Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); tie_root(receiver, ask) },
        _ => None,
    }
}

fn ties_of(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Vec<TextTie> {
    let mut out: Vec<TextTie> = vec![];
    match value {
        Expr::Variable(name, _) => {
            let name = *name;
            let found = nikaia_std::index::or(match *nikaia_std::index::get(&walk.ties, ask.names.resolve(name)) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into());
            for tie in found.iter() { out.push(tie.clone()); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); return ties_of(base, ask, walk); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); return ties_of(inner, ask, walk); },
        Expr::ListLit { items, .. } => { for item in items.iter() { for tie in ties_of(item, ask, walk) { out.push(tie); } } },
        Expr::Tuple(items, _) => { for item in items.iter() { for tie in ties_of(item, ask, walk) { out.push(tie); } } },
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                let shorthand = Expr::Variable(field.name, fresh_id());
                for tie in field_ties(field, &shorthand, ask, walk) { out.push(tie); }
            }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return out };
            call_ties(&callee, args, ask, walk, &mut out);
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let name = ask.names.resolve(method);
            let of = tier_struct_of(receiver, ask, walk);
            let mut keys: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.declared.methods, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into());
            if of.is_some() {
                let own = format!("{}::{}", nikaia_std::index::or(of.as_deref(), || ""), name);
                if nikaia_std::list::contains(&keys, &own) { keys = vec![own]; } else if std_declares(name, Option::as_deref(&of), ask) { keys = vec![]; }
            }
            for key in keys.iter() { call_ties(key, args, ask, walk, &mut out); }
        },
        _ => { },
    }
    out
}

fn call_ties(callee: &str, args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk, out: &mut Vec<TextTie>) {
    let function = match match *nikaia_std::index::get(&walk.declared.fns, callee) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut at: i64 = 0;
    while at < args.len() as i64 && at < function.params.len() as i64 {
        for tie in ties_of(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask, walk) { out.push(tie); }
        if a_text_parameter(ask.names, nikaia_std::index::get(&function.params, nikaia_std::index::at(at))) {
            let root = tie_root(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask);
            if root.is_some() {
                let name: String = nikaia_std::index::or(root, || "".into());
                let local = tier_local(&name, &walk);
                if local.is_some() {
                    let found: TierLocal = nikaia_std::index::or(local, || plain_local(no_kinds()).into());
                    let kinds = found.kinds.clone();
                    let depth = tie_depth(&name, &walk);
                    if depth >= 0 && !lasting_tier(tier_of_kinds(&kinds)) {
                        let word = seen(&TextOwner::Param(callee.to_owned(), at), &no_path(), walk);
                        out.push(TextTie { word, depth, through_text: hands_back_text(&function, ask) });
                    }
                }
            }
        }
        at += 1;
    }
}

fn field_ties(field: &FieldInit, shorthand: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Vec<TextTie> {
    if field.value.is_some() {
        let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
        return ties_of(value, ask, walk);
    }
    ties_of(shorthand, ask, walk)
}

fn hands_back_text(function: &FnDecl, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    a_text_parameter(ask.names, result)
}

fn tie_leaves(value: &Expr, depth: i64, into: Option<String>, back: bool, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ties = ties_of(value, ask, walk);
    if ties.is_empty() { return; }
    for tie in ties.iter() { if tie.depth > depth && !(back && tie.depth == 0 && tie.through_text) { walk.unlent.insert(tie.word.to_owned()); } }
    let name = match into { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut all: Vec<TextTie> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.ties, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    for tie in ties.iter() { tie_add(&mut all, tie); }
    walk.ties.insert(name, all);
}

fn tie_add(all: &mut Vec<TextTie>, tie: &TextTie) {
    for held in all.iter() { if held.word == tie.word && held.depth == tie.depth && held.through_text == tie.through_text { return; } }
    all.push(tie.clone());
}

fn tie_stored(target: &Expr, value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let root = match tie_root(target, ask) { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut depth = tie_depth(&root, &walk);
    if depth <= 0 { depth = -1; }
    tie_leaves(value, depth, Some(root), false, ask, walk);
}

fn tie_bound(names: &[winnow_grammar::Symbol], value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ties = ties_of(value, ask, walk);
    if ties.is_empty() { return; }
    for name in names.iter() {
        let name = *name;
        let mut all: Vec<TextTie> = vec![];
        for tie in ties.iter() { all.push(tie.clone()); }
        walk.ties.insert(ask.names.resolve(name).to_owned(), all);
    }
}

fn lent_field(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    match value {
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            let place = match place_of(value, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
            plain_string(ask.names, &place.ty) && !place.ty.is_nullable && lent_root(base, ask, walk)
        },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); lent_element(base, ask, walk) },
        _ => false,
    }
}

fn lent_element(base: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    let list = match place_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if list.ty.is_nullable || list.ty.generics.len() != 1 || !is_a_container_name(ask.names.resolve(list.ty.name)) { return false; }
    let element = nikaia_std::index::get(&list.ty.generics, 0);
    if !plain_string(ask.names, &element) || element.is_nullable { return false; }
    match base {
        Expr::Variable(name, _) => { let name = *name; lent_list_parameter(ask.names.resolve(name), &walk) },
        Expr::Field { base: inner, .. } => { let inner = nikaia_std::boxed::open(inner); !list.ty.is_view && lent_root(inner, ask, walk) },
        _ => false,
    }
}

fn lent_list_parameter(name: &str, walk: &TierWalk) -> bool {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return false };
    match declared.owner {
        TextOwner::Param(_, _) => declared.ty.is_view && !declared.ty.is_nullable,
        _ => false,
    }
}

fn handed_kinds(value: &Expr, kinds: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    if same_kinds(kinds, &owned_kinds()) && lent_field(value, ask, walk) { return view_kinds(); }
    kinds.clone()
}

fn lent_root(base: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> bool {
    match base {
        Expr::Variable(name, _) => { let name = *name; lent_parameter(ask.names.resolve(name), &walk) },
        Expr::Field { base: inner, .. } => {
            let inner = nikaia_std::boxed::open(inner);
            let place = match place_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
            !place.ty.is_view && !place.ty.is_nullable && lent_root(inner, ask, walk)
        },
        _ => false,
    }
}

fn lent_parameter(name: &str, walk: &TierWalk) -> bool {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if name == "self" { return walk.lent_self && local.declared.is_none(); }
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return false };
    let parameter = matches!(declared.owner, TextOwner::Param(_, _));
    parameter && declared.ty.is_view && !declared.ty.is_nullable && local.of.is_some()
}

fn kept_literal(value: &Expr, owner: &TextOwner, path: &[i64], ty: &Type, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if !plain_string(ask.names, ty) { return; }
    let name = match value {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return,
    };
    let local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    if local.literal < 0 { return; }
    let word = seen(owner, path, walk);
    let mut kept: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.literal_lets, &local.literal) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    kept.insert(word);
    walk.flows.literal_lets.insert(local.literal, kept);
}

fn tier_struct_of(expr: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    match expr {
        Expr::StructLit { name, .. } => { let name = *name; Some(ask.names.resolve(name).to_owned()) },
        Expr::Variable(name, _) => { let name = *name; struct_of_local(ask.names.resolve(name), &walk) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tier_struct_of(expr, ask, walk) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); tier_struct_of(inner, ask, walk) },
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; field_struct_or_bytes(base, ask.names.resolve(name), ask, walk) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); cut_bytes(base, index, ask, walk) },
        _ => None,
    }
}

fn field_struct_or_bytes(base: &Expr, field: &str, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    let found = field_struct(base, field, ask, walk);
    if found.is_some() || field != "bytes" { return found; }
    Some(String::from("Bytes"))
}

fn cut_bytes(base: &Expr, index: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    let a_range = matches!(index, Expr::Range { .. });
    let of = match tier_struct_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if a_range && of == "Bytes" { return Some(of); }
    None
}

fn field_struct(base: &Expr, field: &str, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Option<String> {
    let place = match field_place(base, field, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !place.ty.generics.is_empty() || place.ty.is_nullable || place.ty.is_tuple || place.ty.is_slice || (*place.ty.code).is_some() { return None; }
    Some(ask.names.resolve(place.ty.name).to_owned())
}

fn struct_of_local(name: &str, walk: &TierWalk) -> Option<String> {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match local.of.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn a_text_parameter(names: &winnow_grammar::InternerContext, ty: &Type) -> bool { names.resolve(ty.name) == "String" && ty.generics.is_empty() && !ty.is_nullable && !ty.is_tuple && !ty.is_slice && (*ty.code).is_none() }

fn flow_args(key: &str, args: &[Expr], given: &[Kinds], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let function = match match *nikaia_std::index::get(&walk.declared.fns, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut at: i64 = 0;
    while at < args.len() as i64 && at < given.len() as i64 {
        if at < function.params.len() as i64 {
            let owner = TextOwner::Param(key.to_owned(), at);
            kept_through_a_call(key, at, args, ask, walk);
            if tier_a_choice(nikaia_std::index::get(&args, nikaia_std::index::at(at))) && mixed(tier_of_kinds(nikaia_std::index::get(&given, nikaia_std::index::at(at)))) && plain_string(ask.names, nikaia_std::index::get(&function.params, nikaia_std::index::at(at))) {
                let word = seen(&owner, &no_path(), walk);
                walk.unlent.insert(word);
            }
            let mut kinds = (*nikaia_std::index::get(&given, nikaia_std::index::at(at))).clone();
            if a_keeping_target(&function, at, ask) && tier_keeping_read(position_word(&owner, &no_path()), walk) {
                let only_owned = kinds.owned && !kinds.view && !kinds.either && !kinds.still;
                if only_owned && walk.late_args.contains(&node_key(nikaia_std::index::get(&args, nikaia_std::index::at(at)))) && lendable_parameter(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask, walk).is_none() && !outlived_by_a_keeper(key, at, args, ask, &walk) {
                    walk.flows.viewed_arms.insert(node_key(nikaia_std::index::get(&args, nikaia_std::index::at(at))));
                    kinds = view_kinds();
                }
                if tier_a_choice(nikaia_std::index::get(&args, nikaia_std::index::at(at))) { param_arm_leaves(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask, walk); }
            }
            if a_text_parameter(ask.names, nikaia_std::index::get(&function.params, nikaia_std::index::at(at))) {
                let source = lendable_parameter(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask, walk);
                if source.is_some() {
                    let word: String = nikaia_std::index::or(source, || "".into());
                    let to = seen(&owner, &no_path(), walk);
                    let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.lent_kinds, &word) {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || no_kinds().into());
                    walk.flows.lent_kinds.insert(word.to_owned(), kinds_joined(&before, &kinds));
                    let argued = nikaia_std::index::or(*nikaia_std::index::get(&walk.flows.arg_uses, &word), || 0);
                    walk.flows.arg_uses.insert(word.to_owned(), argued + 1);
                    walk.flows.arg_into.insert((word, to));
                    kinds = no_kinds();
                }
            }
            flow_value(&going_into(&owner, nikaia_std::index::get(&function.params, nikaia_std::index::at(at)), vec![], false), Some(nikaia_std::index::get(&args, nikaia_std::index::at(at))), &kinds, ask, walk);
            if at < function.changes.len() as i64 && *nikaia_std::index::get(&function.changes, nikaia_std::index::at(at)) { changed_in_place(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask, walk); }
        }
        at += 1;
    }
}

fn tier_a_choice(value: &Expr) -> bool { matches!(value, Expr::If { .. } | Expr::Match { .. }) }

#[derive(Debug, Clone, PartialEq, Eq)]
struct TierLateArm {
    at: i64,
    name: String,
    serial: i64,
    loops: i64,
    argument: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TierLateFound {
    arms: collections::BTreeSet<i64>,
    args: collections::BTreeSet<i64>,
    params: collections::BTreeSet<i64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TierLateBinding {
    serial: i64,
    loops: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TierLate {
    bound: collections::BTreeMap<String, Vec<TierLateBinding>>,
    frames: Vec<Vec<String>>,
    serial: i64,
    loops: i64,
    leaving: i64,
    leaves: Vec<TierLateArm>,
    pending: Vec<TierLateArm>,
    found: collections::BTreeSet<i64>,
    args: collections::BTreeSet<i64>,
    params: collections::BTreeSet<i64>,
    params_from: i64,
    params_upto: i64,
    branch_args: Vec<TierLateArm>,
    branches: i64,
}

fn late_arms(program: &Program, ask: &TierAsk<'_, '_, '_, '_>) -> TierLateFound {
    let mut late = TierLate { bound: collections::BTreeMap::new(), frames: vec![], serial: 0, loops: 0, leaving: 0, leaves: vec![], pending: vec![], found: collections::BTreeSet::new(), args: collections::BTreeSet::new(), params: collections::BTreeSet::new(), params_from: 0, params_upto: 0, branch_args: vec![], branches: 0 };
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => { late_function(&item.node, ask, &mut late); },
            Item::Impl { methods, .. } => { for method in methods.iter() { late_function(&method.node, ask, &mut late); } },
            Item::Test { body, .. } => { late_body(body, &vec![], ask, &mut late); },
            Item::Bench { body, .. } => { late_body(body, &vec![], ask, &mut late); },
            _ => { },
        }
    }
    TierLateFound { arms: late.found.to_owned(), args: late.args.to_owned(), params: late.params.to_owned() }
}

fn late_function(item: &Item, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    match item {
        Item::Fn { args, body, .. } => {
            let mut names: Vec<String> = vec!["self".to_owned()];
            for arg in args.iter() { names.push(ask.names.resolve(arg.name).to_owned()); }
            late_body(body, &names, ask, late);
        },
        _ => { },
    }
}

fn late_body(body: &Block, names: &[String], ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    late.bound = collections::BTreeMap::new();
    late.frames = vec![];
    late.loops = 0;
    late.leaving = 0;
    late.leaves = vec![];
    late.pending = vec![];
    late.branch_args = vec![];
    late.branches = 0;
    late_open(late);
    late.params_from = late.serial;
    for name in names.iter() { late_bind(name.to_owned(), late); }
    late.params_upto = late.serial;
    late_block(body, false, ask, late);
    late_close(late);
}

fn late_open(late: &mut TierLate) { late.frames.push(vec![]); }

fn late_close(late: &mut TierLate) {
    let names = match late.frames.pop() { Some(__nikaia_value) => __nikaia_value, None => return };
    for name in names.iter() {
        let mut held = match late.bound.remove(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        held.pop();
        if !held.is_empty() { late.bound.insert(name.to_owned(), held); }
    }
}

fn late_bind(name: String, late: &mut TierLate) {
    late.serial += 1;
    let mut held = nikaia_std::index::or(late.bound.remove(&name), || vec![].into());
    held.push(TierLateBinding { serial: late.serial, loops: late.loops });
    late.bound.insert(name.to_owned(), held);
    let mut frame = nikaia_std::index::or(late.frames.pop(), || vec![].into());
    frame.push(name);
    late.frames.push(frame);
}

fn late_serial(name: &str, late: &TierLate) -> i64 {
    let held = match *nikaia_std::index::get(&late.bound, name) { Some(__nikaia_value) => __nikaia_value, None => return -1 };
    if held.is_empty() { return -1; }
    nikaia_std::index::get(&held, nikaia_std::index::at(held.len() as i64 - 1)).serial
}

fn late_loops(name: &str, late: &TierLate) -> i64 {
    let held = match *nikaia_std::index::get(&late.bound, name) { Some(__nikaia_value) => __nikaia_value, None => return 0 };
    if held.is_empty() { return 0; }
    nikaia_std::index::get(&held, nikaia_std::index::at(held.len() as i64 - 1)).loops
}

fn late_read(name: &str, late: &mut TierLate) {
    let serial = late_serial(name, &late);
    if serial < 0 { return; }
    let mut read: Vec<i64> = vec![];
    let mut handed: Vec<i64> = vec![];
    let mut waiting = late.pending.to_owned();
    for arm in late.branch_args.iter() { waiting.push(arm.clone()); }
    for arm in waiting.iter() { if arm.serial == serial && arm.name == name { if arm.argument { handed.push(arm.at); } else { read.push(arm.at); } } }
    for at in read.iter() {
        let at = nikaia_std::num::value(at);
        late.found.insert(at);
    }
    for at in handed.iter() {
        let at = nikaia_std::num::value(at);
        late.args.insert(at);
    }
}

fn late_written(name: &str, late: &mut TierLate) {
    let serial = late_serial(name, &late);
    let mut kept: Vec<TierLateArm> = vec![];
    for arm in late.pending.iter() { if arm.serial != serial || arm.name != name { kept.push(arm.clone()); } }
    late.pending = kept;
    let mut branch: Vec<TierLateArm> = vec![];
    for arm in late.branch_args.iter() { if arm.serial != serial || arm.name != name { branch.push(arm.clone()); } }
    late.branch_args = branch;
}

fn late_defer(arm: TierLateArm, late: &mut TierLate) { if late.branches > 0 { late.branch_args.push(arm); } else { late.pending.push(arm); } }

fn late_branches_opened(late: &mut TierLate) -> Vec<TierLateArm> {
    let outer = late.branch_args.to_owned();
    late.branch_args = vec![];
    late.branches += 1;
    outer
}

fn late_branch_ended(gathered: &mut Vec<TierLateArm>, late: &mut TierLate) {
    for arm in late.branch_args.iter() { gathered.push(arm.clone()); }
    late.branch_args = vec![];
}

fn late_branches_closed(outer: Vec<TierLateArm>, gathered: &[TierLateArm], late: &mut TierLate) {
    late.branches -= 1;
    late.branch_args = outer;
    for arm in gathered.iter() { late_defer(arm.clone(), late); }
}

fn late_block(block: &Block, leaf: bool, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    late_open(late);
    let mut at: i64 = 0;
    for stmt in block.stmts.iter() {
        at += 1;
        late_stmt(&stmt.node, leaf && ((at) as usize) == block.stmts.len(), ask, late);
    }
    late_close(late);
}

fn late_stmt(stmt: &Stmt, leaf: bool, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    match stmt {
        Stmt::Let { names, value, .. } => {
            late_expr(value, false, ask, late);
            for name in names.iter() {
                let name = *name;
                late_bind(ask.names.resolve(name).to_owned(), late);
            }
        },
        Stmt::Comptime { name, value, .. } => {
            let name = *name;
            late_expr(value, false, ask, late);
            late_bind(ask.names.resolve(name).to_owned(), late);
        },
        Stmt::Assign { target, op, value } => {
            late_expr(value, false, ask, late);
            let assigned = match target {
                Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
                _ => "".to_owned(),
            };
            if op.is_some() || assigned == "" { late_expr(target, false, ask, late); } else { late_written(&assigned, late); }
        },
        Stmt::For { bindings, iter, body, .. } => {
            late_expr(iter, false, ask, late);
            late.loops += 1;
            late_open(late);
            for name in bindings.iter() {
                let name = *name;
                late_bind(ask.names.resolve(name).to_owned(), late);
            }
            late_block(body, false, ask, late);
            late_close(late);
            late.loops -= 1;
        },
        Stmt::While { cond, body } => {
            late.loops += 1;
            late_expr(cond, false, ask, late);
            late_block(body, false, ask, late);
            late.loops -= 1;
        },
        Stmt::Return(value) => {
            late.leaving += 1;
            late_maybe((value).as_ref(), ask, late);
            late.leaving -= 1;
        },
        Stmt::Expr(inner) => { late_expr(inner, leaf, ask, late); },
        _ => { },
    }
}

fn late_maybe(value: Option<&Expr>, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) { late_expr(match value { Some(__nikaia_value) => __nikaia_value, None => return }, false, ask, late); }

fn late_all(values: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) { for value in values.iter() { late_expr(value, false, ask, late); } }

fn late_pattern(pattern: &MatchPattern, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    match pattern {
        MatchPattern::Path(segments) => { if segments.len() == 1 && !names_a_type(ask.names.resolve(*nikaia_std::index::get(&segments, 0))) { late_bind(ask.names.resolve(*nikaia_std::index::get(&segments, 0)).to_owned(), late); } },
        MatchPattern::Tuple { parts, .. } => { for part in parts.iter() { late_pattern(part, ask, late); } },
        MatchPattern::List(parts) => { for part in parts.iter() { late_pattern(part, ask, late); } },
        MatchPattern::RestNamed(name) => { let name = *name; late_bind(ask.names.resolve(name).to_owned(), late); },
        MatchPattern::Named { fields, .. } => { for field in fields.iter() { late_pattern(&field.pat, ask, late); } },
        MatchPattern::Or(alternatives) => { if !alternatives.is_empty() { late_pattern(nikaia_std::index::get(&alternatives, 0), ask, late); } },
        _ => { },
    }
}

fn late_expr(expr: &Expr, leaf: bool, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    match expr {
        Expr::Variable(name, _) => {
            let name = *name;
            let word = ask.names.resolve(name).to_owned();
            late_read(&word, late);
            let serial = late_serial(&word, &late);
            if leaf && serial >= 0 { late.leaves.push(TierLateArm { at: node_key(expr), name: word.to_owned(), serial, loops: late_loops(&word, &late), argument: false }); }
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            late_expr(cond, false, ask, late);
            if else_branch.is_none() {
                late_block(then_branch, false, ask, late);
                return;
            }
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
            let held = late_choice_opened(leaf, late);
            let outer = late_branches_opened(late);
            let mut gathered: Vec<TierLateArm> = vec![];
            late_block(then_branch, true, ask, late);
            late_branch_ended(&mut gathered, late);
            late_block(otherwise, true, ask, late);
            late_branch_ended(&mut gathered, late);
            late_branches_closed(outer, &gathered, late);
            late_choice_closed(leaf, held, late);
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            late_expr(value, false, ask, late);
            let held = late_choice_opened(leaf, late);
            let outer = late_branches_opened(late);
            let mut gathered: Vec<TierLateArm> = vec![];
            for arm in arms.iter() {
                late_open(late);
                late_pattern(&arm.pattern, ask, late);
                if arm.guard.is_some() { late_maybe((arm.guard).as_ref(), ask, late); }
                late_expr(&arm.body, true, ask, late);
                late_close(late);
                late_branch_ended(&mut gathered, late);
            }
            late_branches_closed(outer, &gathered, late);
            late_choice_closed(leaf, held, late);
        },
        Expr::Block(block, _) => { late_block(block, leaf, ask, late); },
        Expr::Unsafe(block, _) => { late_block(block, false, ask, late); },
        Expr::Overlap(block, _) => { late_block(block, false, ask, late); },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr: inner, .. } => { late_expr(inner, false, ask, late); },
                    _ => { },
                }
            }
        },
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            late_expr(func, false, ask, late);
            late_all(args, ask, late);
            for arg in args.iter() { late_argument(arg, ask, late); }
        },
        Expr::MethodCall { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            late_expr(receiver, false, ask, late);
            late_all(args, ask, late);
        },
        Expr::SafeMethod { receiver, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            late_expr(receiver, false, ask, late);
            late_all(args, ask, late);
        },
        Expr::Tuple(parts, _) => { late_all(parts, ask, late); },
        Expr::ListLit { items, .. } => { late_all(items, ask, late); },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            late_expr(value, false, ask, late);
            late_expr(count, false, ask, late);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            late_expr(start, false, ask, late);
            late_expr(end, false, ask, late);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); late_expr(base, false, ask, late); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); late_expr(base, false, ask, late); },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { late_maybe((field.value).as_ref(), ask, late); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            late_expr(base, false, ask, late);
            for field in fields.iter() { late_maybe((field.value).as_ref(), ask, late); }
        },
        Expr::Closure { params, body, .. } => {
            late.leaving += 1;
            late_open(late);
            for name in params.iter() {
                let name = *name;
                late_bind(ask.names.resolve(name).to_owned(), late);
            }
            late_block(body, false, ask, late);
            late_close(late);
            late.leaving -= 1;
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            late.leaving += 1;
            late_expr(body, false, ask, late);
            late.leaving -= 1;
        },
        Expr::Unary { expr: inner, .. } => { let inner = nikaia_std::boxed::open(inner); late_expr(inner, false, ask, late); },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            late_expr(lhs, false, ask, late);
            late_expr(rhs, false, ask, late);
        },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); late_expr(inner, false, ask, late); },
        Expr::Throw(inner, _) => {
            let inner = nikaia_std::boxed::open(inner);
            late.leaving += 1;
            late_expr(inner, false, ask, late);
            late.leaving -= 1;
        },
        Expr::Return(value, _) => {
            let value = nikaia_std::boxed::open(value);
            late.leaving += 1;
            late_maybe((value).as_ref(), ask, late);
            late.leaving -= 1;
        },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            late_expr(base, false, ask, late);
            late_expr(index, false, ask, late);
        },
        Expr::Cast { expr: inner, .. } => { let inner = nikaia_std::boxed::open(inner); late_expr(inner, false, ask, late); },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            late_expr(value, false, ask, late);
            late_expr(fallback, false, ask, late);
        },
        Expr::TryCatch { expr: inner, handler, .. } => {
            let inner = nikaia_std::boxed::open(inner);
            late_expr(inner, false, ask, late);
            late_block(handler, false, ask, late);
        },
        _ => { },
    }
}

fn late_argument(arg: &Expr, ask: &TierAsk<'_, '_, '_, '_>, late: &mut TierLate) {
    if late.leaving > 0 { return; }
    let word = match arg {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return,
    };
    let serial = late_serial(&word, &late);
    if serial < 0 { return; }
    let loops = late_loops(&word, &late);
    if late.loops > loops {
        late.args.insert(node_key(arg));
        return;
    }
    late_defer(TierLateArm { at: node_key(arg), name: word.to_owned(), serial, loops, argument: true }, late);
}

fn late_choice_opened(leaf: bool, late: &mut TierLate) -> Vec<TierLateArm> {
    if leaf { return vec![]; }
    let held = late.leaves.to_owned();
    late.leaves = vec![];
    held
}

fn late_choice_closed(leaf: bool, held: Vec<TierLateArm>, late: &mut TierLate) {
    if leaf { return; }
    let arms = late.leaves.to_owned();
    late.leaves = held;
    if late.leaving > 0 { return; }
    for arm in arms.iter() {
        if arm.serial > late.params_from && arm.serial <= late.params_upto { late.params.insert(arm.at); }
        if late.loops > arm.loops { late.found.insert(arm.at); } else { late_defer(arm.clone(), late); }
    }
}

fn tier_expr(expr: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let read = walk.read_here;
    walk.read_here = false;
    let back = walk.tail_back;
    walk.tail_back = false;
    if !read {
        match expr {
            Expr::Variable(name, _) => { let name = *name; count_use(ask.names.resolve(name), walk); },
            _ => { },
        }
    }
    match expr {
        Expr::LitStr { .. } => lasting_kinds(),
        Expr::LitNull(_) => no_kinds(),
        Expr::LitInt { .. } => no_kinds(),
        Expr::LitFloat(_, _) => no_kinds(),
        Expr::LitBool(_, _) => no_kinds(),
        Expr::LitInterpolated { parts, .. } => {
            let outer = walk.in_hole;
            walk.in_hole = true;
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, at, .. } => {
                        let at = *at;
                        let held = walk.hole_text;
                        walk.hole_text = at as i64;
                        walk.read_here = true;
                        tier_expr(expr, ask, walk);
                        walk.hole_text = held;
                    },
                    _ => { },
                }
            }
            walk.in_hole = outer;
            owned_kinds()
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let kinds = kinds_of_local(ask.names.resolve(name), &walk);
            let late = walk.late.contains(&node_key(expr)) || tier_arm_read(node_key(expr), walk);
            if late && kinds.owned && !kinds.view && !kinds.either && !kinds.still {
                walk.flows.viewed_arms.insert(node_key(expr));
                return view_kinds();
            }
            kinds
        },
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; method_kinds(receiver, ask.names.resolve(method), args, ask, walk) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; method_kinds(receiver, ask.names.resolve(method), args, ask, walk) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); call_kinds(func, args, ask, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); field_kinds(expr, base, ask, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); field_kinds(expr, base, ask, walk) },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let received = tier_expr(base, ask, walk);
            tier_expr(index, ask, walk);
            if a_range(index) { return viewed(&received); }
            let place = match place_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return received };
            element_kinds(&place, false, ask, walk)
        },
        Expr::StructLit { name, fields, .. } => {
            let name = *name;
            let owner = ask.names.resolve(name).to_owned();
            let back = walk.handed_back >= 0 && walk.handed_back == id_of(expr) as i64;
            walk.handed_back = -1;
            for field in fields.iter() { tier_struct_field(&owner, field, back, ask, walk); }
            owned_kinds()
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            tier_expr(base, ask, walk);
            let owner = tier_struct_of(base, ask, walk);
            for field in fields.iter() {
                let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let kinds = tier_expr(value, ask, walk);
                let of = match match owner.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => continue };
                let key = (of.to_owned(), ask.names.resolve(field.name).to_owned());
                let found = match match *nikaia_std::index::get(&walk.declared.fields, &key) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => continue };
                let into = TextOwner::Field(of.to_owned(), ask.names.resolve(field.name).to_owned());
                flow_value(&going_into(&into, &found.ty, vec![], false), Some(value), &kinds, ask, walk);
            }
            owned_kinds()
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            tier_expr(cond, ask, walk);
            walk.tail_back = back;
            let mut out = tier_block(then_branch, ask, walk);
            if else_branch.is_some() {
                let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out };
                walk.tail_back = back;
                out = kinds_joined(&out, &tier_block(otherwise, ask, walk));
            }
            if beside_its_own(&out) { kept_unseen(expr, ask, walk); }
            if literals_beside_null(expr) { return owned_kinds(); }
            out
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            let scrutinee = tier_expr(value, ask, walk);
            if scrutinee.still {
                let whole = source_of(value, ask, walk);
                if container_source((whole).as_ref(), ask) { kept_unseen(value, ask, walk); }
            }
            let mut out = no_kinds();
            let mut payloads: Vec<String> = vec![];
            for arm in arms.iter() {
                open_tier_scope(walk);
                let bound = bind_static_payloads(&arm.pattern, ask, walk);
                bind_tuple_parts(&arm.pattern, &scrutinee, ask, walk);
                if arm.guard.is_some() {
                    let guard = match arm.guard.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                    tier_expr(guard, ask, walk);
                }
                walk.tail_back = back;
                let mut arm_kinds = tier_expr(&arm.body, ask, walk);
                if back {
                    tie_leaves(&arm.body, -1, None, true, ask, walk);
                    arm_kinds = handed_kinds(&arm.body, &arm_kinds, ask, walk);
                }
                out = kinds_joined(&out, &arm_kinds);
                if bound { still_sources(&arm.body, ask, walk, &mut payloads); }
                close_tier_scope(walk);
            }
            if beside_its_own(&out) {
                kept_unseen(expr, ask, walk);
                for read_from in payloads.iter() {
                    flow_word(read_from, &owned_kinds(), walk);
                    walk.flows.demoted.insert(read_from.to_owned());
                }
            }
            if literals_beside_null(expr) { return owned_kinds(); }
            out
        },
        Expr::Block(block, _) => {
            walk.tail_back = back;
            tier_block(block, ask, walk)
        },
        Expr::Unsafe(block, _) => tier_block(block, ask, walk),
        Expr::Overlap(block, _) => tier_block(block, ask, walk),
        Expr::Closure { body, .. } => {
            let held = match walk.result.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            walk.result = None;
            tier_block(body, ask, walk);
            walk.result = held;
            owned_kinds()
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            let held = match walk.result.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            walk.result = None;
            tier_expr(body, ask, walk);
            walk.result = held;
            owned_kinds()
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            let first = tier_expr(value, ask, walk);
            let out = kinds_joined(&first, &tier_expr(fallback, ask, walk));
            if beside_its_own(&out) {
                kept_unseen(value, ask, walk);
                kept_unseen(fallback, ask, walk);
            }
            out
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            let out = tier_expr(expr, ask, walk);
            kinds_joined(&out, &tier_block(handler, ask, walk))
        },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); tier_expr(inner, ask, walk) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tier_expr(expr, ask, walk) },
        Expr::Throw(inner, _) => {
            let inner = nikaia_std::boxed::open(inner);
            tier_expr(inner, ask, walk);
            no_kinds()
        },
        Expr::Return(value, _) => {
            let value = nikaia_std::boxed::open(value);
            let given = match value { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
            let kinds = tier_expr(given, ask, walk);
            flow_result(given, &kinds, ask, walk);
            no_kinds()
        },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            walk.read_here = true;
            let left = tier_expr(lhs, ask, walk);
            walk.read_here = true;
            tier_expr(rhs, ask, walk);
            let adds = matches!(op, BinaryOp::Add);
            if adds && left.still { kept_unseen(lhs, ask, walk); }
            owned_kinds()
        },
        Expr::Cast { expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            tier_expr(expr, ask, walk);
            owned_kinds()
        },
        Expr::Tuple(items, _) => {
            let out = items_kinds(items, ask, walk);
            if out.still { for item in items.iter() { kept_unseen(item, ask, walk); } }
            out
        },
        Expr::ListLit { items, .. } => {
            let out = items_kinds(items, ask, walk);
            if beside_its_own(&out) { for item in items.iter() { kept_unseen(item, ask, walk); } }
            out
        },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            tier_expr(value, ask, walk);
            tier_expr(count, ask, walk);
            owned_kinds()
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            tier_expr(start, ask, walk);
            tier_expr(end, ask, walk);
            owned_kinds()
        },
        Expr::Path(_, _) => {
            let written = match tier_callee(expr, ask) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
            variant_handed_on(&written, ask, walk);
            owned_kinds()
        },
        Expr::Break(_) => no_kinds(),
        Expr::Continue(_) => no_kinds(),
        _ => owned_kinds(),
    }
}

fn a_range(index: &Expr) -> bool { matches!(index, Expr::Range { .. }) }

fn kinds_of_local(name: &str, walk: &TierWalk) -> Kinds {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    local.kinds.clone()
}

fn items_kinds(items: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let mut out = no_kinds();
    for item in items.iter() { out = kinds_joined(&out, &tier_expr(item, ask, walk)); }
    out
}

fn field_kinds(expr: &Expr, base: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    tier_expr(base, ask, walk);
    let place = match place_of(expr, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    kinds_of_declared(&place, ask, walk)
}

fn tier_struct_field(owner: &str, field: &FieldInit, back: bool, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let shorthand = Expr::Variable(field.name, fresh_id());
    let mut kinds = field_value_kinds(field, &shorthand, ask, walk);
    let name = ask.names.resolve(field.name).to_owned();
    let key = (owner.to_owned(), name.to_owned());
    if !walk.declared.fields.contains_key(&key) {
        if kinds.still && field.value.is_some() {
            let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
            kept_unseen(value, ask, walk);
        } else if kinds.still { kept_unseen(&shorthand, ask, walk); }
        return;
    }
    let found = match match *nikaia_std::index::get(&walk.declared.fields, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let into = TextOwner::Field(owner.to_owned(), name);
    if back && plain_string(ask.names, &found.ty) && !found.ty.is_nullable {
        let mut lent: Option<String> = None;
        if field.value.is_some() {
            let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
            lent = lendable_parameter(value, ask, walk);
        } else { lent = lendable_parameter(&shorthand, ask, walk); }
        if lent.is_some() {
            let to = seen(&into, &no_path(), walk);
            let word: String = nikaia_std::index::or(lent, || "".into());
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.lent_kinds, &word) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into());
            walk.flows.lent_kinds.insert(word.to_owned(), kinds_joined(&before, &kinds));
            let lent_before = nikaia_std::index::or(*nikaia_std::index::get(&walk.flows.lent_uses, &word), || 0);
            walk.flows.lent_uses.insert(word.to_owned(), lent_before + 1);
            walk.flows.lent_into.insert((word, to));
            kinds = no_kinds();
        }
    }
    flow_value(&going_into(&into, &found.ty, vec![], false), (field.value).as_ref(), &kinds, ask, walk);
    if field.value.is_none() { kept_literal(&shorthand, &into, &no_path(), &found.ty, ask, walk); }
}

fn field_value_kinds(field: &FieldInit, shorthand: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    if field.value.is_some() {
        let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
        return tier_expr(value, ask, walk);
    }
    tier_expr(shorthand, ask, walk)
}

fn call_kinds(func: &Expr, args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let mut given: Vec<Kinds> = vec![];
    for arg in args.iter() { given.push(tier_expr(arg, ask, walk)); }
    let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    if walk.declared.fns.contains_key(&callee) {
        flow_args(&callee, args, &given, ask, walk);
        if walk.declared.rules.contains(&callee) && !args.is_empty() { parsed_parameter(nikaia_std::index::get(&args, 0), ask, walk); }
        return result_kinds(&callee, ask, walk);
    }
    if walk.declared.variants.contains_key(&callee) {
        flow_payload(&callee, args, &given, ask, walk);
        return owned_kinds();
    }
    if args.is_empty() && is_a_container_name(&callee) { return no_kinds(); }
    if names_a_type(&last_segment(&callee)) || !ask.library.functions.contains_key(&callee) { kept_args(args, &given, ask, walk); } else { std_container_args(args, ask, walk); }
    std_result(&callee, ask)
}

fn std_container_args(args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    for arg in args.iter() {
        let whole = source_of(arg, ask, walk);
        if whole.is_some() {
            let found = match whole { Some(__nikaia_value) => __nikaia_value, None => return };
            if a_container(ask.names, &found.ty) && holds_text(ask.names, &found.ty) { demote_inside(&found.owner, &found.ty, &mut vec![], ask, walk); }
        }
    }
}

fn parsed_parameter(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let name = match value {
        Expr::Variable(name, _) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return,
    };
    let local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return };
    let parameter = matches!(declared.owner, TextOwner::Param(_, _));
    if !parameter || !plain_string(ask.names, &declared.ty) { return; }
    let word = seen(&declared.owner, &no_path(), walk);
    walk.flows.viewed.insert(word);
}

fn method_kinds(receiver: &Expr, method: &str, args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    for arg in args.iter() { tie_stored(receiver, arg, ask, walk); }
    walk.read_here = true;
    let received = tier_expr(receiver, ask, walk);
    if changes_its_text(method) { changed_in_place(receiver, ask, walk); }
    let mut given: Vec<Kinds> = vec![];
    for arg in args.iter() { given.push(tier_expr(arg, ask, walk)); }
    let of = tier_struct_of(receiver, ask, walk);
    let mut keys: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.declared.methods, method) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    if of.is_some() {
        let own = format!("{}::{}", nikaia_std::index::or(of.as_deref(), || ""), method);
        if nikaia_std::list::contains(&keys, &own) { keys = vec![own]; } else if std_declares(method, Option::as_deref(&of), ask) { keys = vec![]; }
    }
    if !keys.is_empty() {
        for key in keys.iter() { flow_args(key, args, &given, ask, walk); }
        let mut out = no_kinds();
        for key in keys.iter() { out = kinds_joined(&out, &result_kinds(key, ask, walk)); }
        return out;
    }
    if !puts_its_argument(method) && any_still(&given) && !std_has_method(method, ask) { kept_args(args, &given, ask, walk); }
    if puts_its_argument(method) && any_still(&given) && place_of(receiver, ask, walk).is_none() { kept_args(args, &given, ask, walk); }
    let place = place_of(receiver, ask, walk);
    if place.is_some() {
        let found = match place { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
        let ty = found.ty.clone();
        if puts_its_argument(method) && a_container(ask.names, &ty) {
            put_into_container(&found, method, args, &given, ask, walk);
            return owned_kinds();
        }
        if method == "entry" && a_map(ask.names, &ty) && args.len() == 1 && given.len() == 1 && ty.generics.len() == 2 {
            flow_value(&going_into(&found.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(nikaia_std::index::get(&args, 0)), nikaia_std::index::get(&given, 0), ask, walk);
            return owned_kinds();
        }
        if hands_back_an_element(method) { return element_kinds(&found, method == "keys", ask, walk); }
        if (method == "clone" || method == "to_owned" || method == "to_vec") && args.is_empty() && a_container(ask.names, &ty) && received.still { demote_inside(&found.owner, &ty, &mut vec![], ask, walk); }
    }
    if method == "map" && args.len() == 1 {
        match nikaia_std::index::get(&args, 0) {
            Expr::Closure { params, body, .. } => { return mapped(params, body, &received, ask, walk); },
            _ => { },
        }
    }
    if method == "filter" || method == "rev" || method == "skip" || method == "take" || method == "step_by" { return received; }
    if owns_its_text(method) { return owned_kinds(); }
    if views_what_it_is_called_on(method) || cuts_in_two(method) { return viewed(&received); }
    if hands_back_an_element(method) { return received; }
    if std_method_views(method, (of).as_deref(), ask) { return view_kinds(); }
    owned_kinds()
}

fn std_declares(method: &str, of: Option<&str>, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    let receiver = match of { Some(__nikaia_value) => __nikaia_value, None => return false };
    let own = format!("{}::{}", last_segment(receiver), method);
    let within = format!("::{}", own);
    let bucket = match *nikaia_std::index::get(&ask.methods.keys, method) { Some(__nikaia_value) => __nikaia_value, None => return false };
    for key in bucket.iter() { if *key == own || key.ends_with(&within) { return true; } }
    false
}

fn std_method_views(method: &str, of: Option<&str>, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    let receiver = match of { Some(__nikaia_value) => __nikaia_value, None => return false };
    let own = format!("{}::{}", last_segment(receiver), method);
    let within = format!("::{}", own);
    let mut any = false;
    let bucket = match *nikaia_std::index::get(&ask.methods.keys, method) { Some(__nikaia_value) => __nikaia_value, None => return false };
    for key in bucket.iter() {
        if *key != own && !key.ends_with(&within) { continue; }
        let contract = match *nikaia_std::index::get(&ask.library.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        if !signature.takes_a_receiver() { continue; }
        let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        let text = match result {
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.clone() },
            _ => result.clone(),
        };
        if !text.is_a_view() || text.owned().text() != "String" { return false; }
        any = true;
    }
    any
}

fn cuts_in_two(method: &str) -> bool { method == "split_at" || method == "split_once" || method == "rsplit_once" }

fn put_into_container(place: &Declaring, method: &str, args: &[Expr], given: &[Kinds], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ty = place.ty.clone();
    if a_map(ask.names, &ty) {
        if args.len() == 2 && given.len() == 2 && ty.generics.len() == 2 {
            flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(nikaia_std::index::get(&args, 0)), nikaia_std::index::get(&given, 0), ask, walk);
            flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 1), vec![1], true), Some(nikaia_std::index::get(&args, 1)), nikaia_std::index::get(&given, 1), ask, walk);
        }
        return;
    }
    if ty.generics.is_empty() || args.is_empty() || given.is_empty() { return; }
    let wrap = method != "extend" && method != "append";
    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], wrap), Some(nikaia_std::index::get(&args, nikaia_std::index::at(args.len() as i64 - 1))), nikaia_std::index::get(&given, nikaia_std::index::at(given.len() as i64 - 1)), ask, walk);
}

fn mapped(params: &[winnow_grammar::Symbol], body: &Block, received: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let held = match walk.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    walk.result = None;
    open_tier_scope(walk);
    if params.is_empty() { bind_tier_local(String::from("a"), plain_local(received.clone()), walk); }
    for param in params.iter() {
        let param = *param;
        bind_tier_local(ask.names.resolve(param).to_owned(), plain_local(received.clone()), walk);
    }
    let made = tier_block(body, ask, walk);
    close_tier_scope(walk);
    walk.result = held;
    made
}

fn result_kinds(key: &str, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let function = match *nikaia_std::index::get(&walk.declared.fns, key) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let result = match match function.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    kinds_of(&TextOwner::Returned(key.to_owned()), &result, &mut vec![], ask, walk)
}

fn viewed(received: &Kinds) -> Kinds {
    if (received.lasting || received.still) && !received.owned && !received.view && !received.either {
        if received.still { return still_kinds(); }
        return lasting_kinds();
    }
    view_kinds()
}

fn std_result(callee: &str, ask: &TierAsk<'_, '_, '_, '_>) -> Kinds {
    let contract = match *nikaia_std::index::get(&ask.library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    if result.text() == "ref String" { return view_kinds(); }
    owned_kinds()
}

fn tier_units(program: &Program) -> Vec<(i64, i64)> {
    let mut units: Vec<(i64, i64)> = vec![];
    let mut at = 0;
    for item in program.items.iter() {
        match &item.node {
            Item::Impl { methods, .. } => {
                let mut m: i64 = 0;
                while ((m) as usize) < methods.len() {
                    units.push((at, m));
                    m += 1;
                }
            },
            _ => { units.push((at, -1)); },
        }
        at += 1;
    }
    units
}

fn walk_unit(program: &Program, item_at: i64, method_at: i64, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let item = nikaia_std::index::get(&program.items, nikaia_std::index::at(item_at));
    walk.read_here = false;
    walk.tail_back = false;
    walk.handed_back = -1;
    walk.lent_self = false;
    match item.node {
        Item::Fn { .. } => { walk_function(&item.node, None, ask, walk); },
        Item::Impl { ref target, ref methods, .. } => {
            let owner = ask.names.resolve(target.name).to_owned();
            walk_function(&nikaia_std::index::get(&methods, nikaia_std::index::at(method_at)).node, Some(owner), ask, walk);
        },
        Item::Grammar(ref def) => { walk_grammar(def, ask, walk); },
        Item::Test { ref body, .. } => { walk_body(body, ask, walk); },
        Item::Bench { ref body, .. } => { walk_body(body, ask, walk); },
        Item::Comptime { ref value, .. } => {
            fresh_tier_frame(walk);
            kept_unseen(value, ask, walk);
        },
        Item::Struct { ref fields, .. } => {
            fresh_tier_frame(walk);
            for field in fields.iter() {
                let given = match field.default.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                kept_unseen(&given.value, ask, walk);
            }
        },
        _ => { },
    }
}

fn merge_flows(into: &mut Flows, from: &Flows) {
    for (word, kinds) in from.positions.iter() {
        let kinds = *kinds;
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&into.positions, word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        into.positions.insert(word.to_owned(), kinds_joined(&before, &kinds));
    }
    for (word, position) in from.known.iter() { if !into.known.contains_key(word) { into.known.insert(word.to_owned(), position.clone()); } }
    for (at, kept) in from.literal_lets.iter() {
        let at = nikaia_std::num::value(at);
        let mut all: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&into.literal_lets, &at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeSet::new().into());
        for word in kept.iter() { all.insert(word.to_owned()); }
        into.literal_lets.insert(at.clone(), all);
    }
    for (at, hand) in from.wraps.iter() {
        let at = nikaia_std::num::value(at);let hand = *hand;
        into.wraps.insert(at.clone(), hand.clone());
    }
    for pair in from.param_into.iter() { into.param_into.insert(pair.clone()); }
    for (at, wraps) in from.hole_wraps.iter() {
        let at = nikaia_std::num::value(at);
        let mut all: Vec<HoleWrap> = nikaia_std::index::or(match *nikaia_std::index::get(&into.hole_wraps, &at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for wrap in wraps.iter() { all.push(wrap.clone()); }
        into.hole_wraps.insert(at.clone(), all);
    }
    for pair in from.links.iter() { into.links.insert(pair.clone()); }
    for word in from.unwrappable.iter() { into.unwrappable.insert(word.to_owned()); }
    for word in from.viewed.iter() { into.viewed.insert(word.to_owned()); }
    for pair in from.still_into.iter() { into.still_into.insert(pair.clone()); }
    for (at, target) in from.adopted.iter() {
        let at = nikaia_std::num::value(at);
        into.adopted.insert(at.clone(), target.clone());
    }
    for word in from.demoted.iter() { into.demoted.insert(word.to_owned()); }
    for word in from.in_maps.iter() { into.in_maps.insert(word.to_owned()); }
    for pair in from.lent_into.iter() { into.lent_into.insert(pair.clone()); }
    for (word, kinds) in from.lent_kinds.iter() {
        let kinds = *kinds;
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&into.lent_kinds, word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        into.lent_kinds.insert(word.to_owned(), kinds_joined(&before, &kinds));
    }
    for (word, count) in from.uses.iter() {
        let count = nikaia_std::num::value(count);
        let before = nikaia_std::index::or(*nikaia_std::index::get(&into.uses, word), || 0);
        into.uses.insert(word.to_owned(), before + count);
    }
    for (word, count) in from.lent_uses.iter() {
        let count = nikaia_std::num::value(count);
        let before = nikaia_std::index::or(*nikaia_std::index::get(&into.lent_uses, word), || 0);
        into.lent_uses.insert(word.to_owned(), before + count);
    }
    for pair in from.arg_into.iter() { into.arg_into.insert(pair.clone()); }
    for pair in from.read_into.iter() { into.read_into.insert(pair.clone()); }
    for word in from.unlinked.iter() { into.unlinked.insert(word.to_owned()); }
    for (word, count) in from.arg_uses.iter() {
        let count = nikaia_std::num::value(count);
        let before = nikaia_std::index::or(*nikaia_std::index::get(&into.arg_uses, word), || 0);
        into.arg_uses.insert(word.to_owned(), before + count);
    }
    for word in from.changed.iter() { into.changed.insert(word.to_owned()); }
    for node in from.viewed_arms.iter() {
        let node = nikaia_std::num::value(node);
        into.viewed_arms.insert(node.clone());
    }
    for pair in from.kept_through.iter() { into.kept_through.insert(pair.clone()); }
    for (node, word) in from.param_arm_into.iter() {
        let node = nikaia_std::num::value(node);
        into.param_arm_into.insert(node.clone(), word.to_owned());
    }
}

fn tier_reads_changed(reads: &TierReads, tiers: &collections::BTreeSet<String>, keeping: &collections::BTreeSet<String>, arms: &collections::BTreeSet<i64>, adopted: &collections::BTreeSet<i64>) -> bool {
    for word in tiers.iter() { if reads.tiers.contains(word) { return true; } }
    for word in keeping.iter() { if reads.keeping.contains(word) { return true; } }
    for node in arms.iter() {
        let node = nikaia_std::num::value(node);
        if reads.arms.contains(&node) { return true; }
    }
    for at in adopted.iter() {
        let at = nikaia_std::num::value(at);
        if reads.adopted.contains(&at) { return true; }
    }
    false
}

fn changed_tier_words(a: &collections::BTreeMap<String, Tier>, b: &collections::BTreeMap<String, Tier>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (word, tier) in a.iter() {
        let tier = *tier;
        if !b.contains_key(word) {
            out.insert(word.to_owned());
            continue;
        }
        let other = match (*nikaia_std::index::get(&b, word)).copied() { Some(__nikaia_value) => __nikaia_value, None => continue };
        if tier_word(tier) != tier_word(other) { out.insert(word.to_owned()); }
    }
    for (word, _) in b.iter() { if !a.contains_key(word) { out.insert(word.to_owned()); } }
    out
}

fn changed_words(a: &collections::BTreeSet<String>, b: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for word in a.iter() { if !b.contains(word) { out.insert(word.to_owned()); } }
    for word in b.iter() { if !a.contains(word) { out.insert(word.to_owned()); } }
    out
}

fn changed_nodes(a: &collections::BTreeSet<i64>, b: &collections::BTreeSet<i64>) -> collections::BTreeSet<i64> {
    let mut out: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for node in a.iter() {
        let node = nikaia_std::num::value(node);
        if !b.contains(&node) { out.insert(node.clone()); }
    }
    for node in b.iter() {
        let node = nikaia_std::num::value(node);
        if !a.contains(&node) { out.insert(node.clone()); }
    }
    out
}

fn changed_adopted(a: &collections::BTreeMap<i64, Declaring>, b: &collections::BTreeMap<i64, Declaring>) -> collections::BTreeSet<i64> {
    let mut out: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for (at, target) in a.iter() {
        let at = nikaia_std::num::value(at);
        if !b.contains_key(&at) {
            out.insert(at.clone());
            continue;
        }
        let other = match *nikaia_std::index::get(&b, &at) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if owner_word(&target.owner) != owner_word(&other.owner) { out.insert(at.clone()); }
    }
    for (at, _) in b.iter() {
        let at = nikaia_std::num::value(at);
        if !a.contains_key(&at) { out.insert(at.clone()); }
    }
    out
}

fn fresh_tier_frame(walk: &mut TierWalk) {
    walk.locals = collections::BTreeMap::new();
    walk.ties = collections::BTreeMap::new();
    walk.frames = vec![];
    walk.result = None;
    walk.in_hole = false;
    walk.hole_text = -1;
    walk.lent_self = false;
}

fn walk_body(body: &Block, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    walk.locals = collections::BTreeMap::new();
    walk.ties = collections::BTreeMap::new();
    walk.frames = vec![];
    walk.result = None;
    walk.in_hole = false;
    walk.hole_text = -1;
    walk.lent_self = false;
    tier_block(body, ask, walk);
}

fn walk_grammar(def: &GrammarDef, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let gname = ask.names.resolve(def.name).to_owned();
    let mut rules: collections::BTreeSet<String> = collections::BTreeSet::new();
    for rule in def.rules.iter() { rules.insert(ask.names.resolve(rule.name).to_owned()); }
    for rule in def.rules.iter() {
        let key = format!("{}::{}", gname, ask.names.resolve(rule.name));
        for alt in rule.alts.iter() {
            walk.locals = collections::BTreeMap::new();
            walk.ties = collections::BTreeMap::new();
            walk.frames = vec![];
            walk.result = Some(key.to_owned());
            walk.in_hole = false;
            walk.hole_text = -1;
            open_tier_scope(walk);
            bind_grammar_pattern(&gname, &rules, &alt.pattern.node, ask, walk);
            if alt.action.is_none() {
                let kinds = grammar_pattern_kinds(&gname, &rules, &alt.pattern.node, ask, walk);
                flow_pattern_result(&key, (rule.ret_type).as_ref(), &kinds, ask, walk);
            }
            walk_action((alt.action).as_ref(), ask, walk);
            close_tier_scope(walk);
        }
    }
}

fn flow_pattern_result(key: &str, ret_type: Option<&Type>, kinds: &Kinds, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let ty = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return };
    if plain_string(ask.names, ty) { flow_type(&TextOwner::Returned(key.to_owned()), ty, &mut vec![], kinds, ask, walk); }
}

fn walk_action(action: Option<&Block>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let block = match action { Some(__nikaia_value) => __nikaia_value, None => return };
    let tail = tier_block(block, ask, walk);
    if !block.stmts.is_empty() {
        match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
            Stmt::Expr(last) => { flow_result(last, &tail, ask, walk); },
            _ => { },
        }
    }
}

fn bind_grammar_pattern(gname: &str, rules: &collections::BTreeSet<String>, pattern: &Pattern, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    match pattern {
        Pattern::Bind { name, pat } => {
            let pat = nikaia_std::boxed::open(pat); let name = *name;
            let kinds = grammar_pattern_kinds(gname, rules, &pat.node, ask, walk);
            bind_tier_local(ask.names.resolve(name).to_owned(), plain_local(kinds), walk);
            bind_grammar_pattern(gname, rules, &pat.node, ask, walk);
        },
        Pattern::Seq(parts) => { for part in parts.iter() { bind_grammar_pattern(gname, rules, &part.node, ask, walk); } },
        Pattern::Choice(parts) => { for part in parts.iter() { bind_grammar_pattern(gname, rules, &part.node, ask, walk); } },
        Pattern::Ref { args, .. } => { for arg in args.iter() { bind_grammar_pattern(gname, rules, &arg.node, ask, walk); } },
        Pattern::Repeat { pat, .. } => { let pat = nikaia_std::boxed::open(pat); bind_grammar_pattern(gname, rules, &pat.node, ask, walk); },
        Pattern::Group(pat) => { let pat = nikaia_std::boxed::open(pat); bind_grammar_pattern(gname, rules, &pat.node, ask, walk); },
        _ => { },
    }
}

fn grammar_pattern_kinds(gname: &str, rules: &collections::BTreeSet<String>, pattern: &Pattern, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    match pattern {
        Pattern::Repeat { pat, .. } => { let pat = nikaia_std::boxed::open(pat); grammar_repeat_kinds(gname, rules, &pat.node, ask, walk) },
        Pattern::Group(pat) => { let pat = nikaia_std::boxed::open(pat); grammar_pattern_kinds(gname, rules, &pat.node, ask, walk) },
        Pattern::Choice(parts) => grammar_choice_kinds(gname, rules, parts, ask, walk),
        Pattern::Ref { name, generics, args } => { let name = *name; grammar_reference_kinds(gname, rules, ask.names.resolve(name), generics.len() as i64, args, ask, walk) },
        _ => no_kinds(),
    }
}

fn grammar_repeat_kinds(gname: &str, rules: &collections::BTreeSet<String>, pat: &Pattern, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    match pat {
        Pattern::Ref { name, generics, args } => {
            let name = *name;
            let called = ask.names.resolve(name);
            if generics.is_empty() && args.is_empty() && !rules.contains(called) && (called == "digit" || called == "hex_digit" || called == "any") { return view_kinds(); }
        },
        _ => { },
    }
    grammar_pattern_kinds(gname, rules, pat, ask, walk)
}

fn grammar_choice_kinds(gname: &str, rules: &collections::BTreeSet<String>, parts: &[Spanned<Pattern>], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    let mut out = no_kinds();
    for part in parts.iter() { out = kinds_joined(&out, &grammar_pattern_kinds(gname, rules, &part.node, ask, walk)); }
    out
}

fn grammar_reference_kinds(gname: &str, rules: &collections::BTreeSet<String>, called: &str, generics: i64, args: &[Spanned<Pattern>], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) -> Kinds {
    if rules.contains(called) { return result_kinds(&format!("{}::{}", gname, called), ask, walk); }
    if generics > 0 { return no_kinds(); }
    if (called == "peek" || called == "list") && !args.is_empty() { return grammar_pattern_kinds(gname, rules, &nikaia_std::index::get(&args, 0).node, ask, walk); }
    if (called == "until" || called == "text") && !args.is_empty() { return view_kinds(); }
    if args.is_empty() && (called == "raw_ident" || called == "string" || called == "alpha1" || called == "multispace0" || called == "multispace1") { return view_kinds(); }
    no_kinds()
}

fn walk_function(item: &Item, target: Option<String>, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let (name, receiver, args, config, body) = match item {
        Item::Fn { name, receiver, args, config, body, .. } => { let name = *name; (name, receiver, args, config, body) },
        _ => return,
    };
    let key = tier_key((target).as_deref(), &own_name((name).as_ref(), ask.names));
    walk.locals = collections::BTreeMap::new();
    walk.ties = collections::BTreeMap::new();
    walk.frames = vec![];
    walk.result = Some(key.to_owned());
    walk.in_hole = false;
    walk.hole_text = -1;
    open_tier_scope(walk);
    let mut at = 0;
    for arg in args.iter() {
        let owner = TextOwner::Param(key.to_owned(), at);
        let kinds = kinds_of(&owner, &arg.ty, &mut vec![], ask, walk);
        let of: String = ask.names.resolve(arg.ty.name).to_owned();
        let local = TierLocal { kinds, of: Some(of), literal: -1, declared: Some(Declaring { owner, ty: arg.ty.clone() }), from: None, empty: -1, through: vec![] };
        bind_tier_local(ask.names.resolve(arg.name).to_owned(), local, walk);
        at += 1;
    }
    for option in config.iter() { kept_unseen(&option.default, ask, walk); }
    walk.lent_self = false;
    if receiver.is_some() && target.is_some() {
        walk.lent_self = nikaia_std::index::or(receiver.as_ref().map(|__nikaia_it| __nikaia_it.is_ref), || false);
        let local = TierLocal { kinds: owned_kinds(), of: match target.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, literal: -1, declared: None, from: None, empty: -1, through: vec![] };
        bind_tier_local(String::from("self"), local, walk);
    }
    walk.handed_back = -1;
    if !body.stmts.is_empty() {
        match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1)).node {
            Stmt::Expr(last) => { walk.handed_back = handed_struct(last); },
            _ => { },
        }
    }
    let tail = tier_block(body, ask, walk);
    walk.handed_back = -1;
    if !body.stmts.is_empty() {
        match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1)).node {
            Stmt::Expr(last) => { flow_result(last, &tail, ask, walk); },
            _ => { },
        }
    }
    close_tier_scope(walk);
}

fn decide_tiers(flows: &Flows, declared: &TextDeclared, demoted: &mut collections::BTreeSet<String>, unlent: &mut collections::BTreeSet<String>) -> collections::BTreeMap<String, Tier> {
    let mut positions = flows.positions.to_owned();
    for word in flows.demoted.iter() { demoted.insert(word.to_owned()); }
    for word in demoted.iter() {
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        positions.insert(word.to_owned(), kinds_joined(&before, &owned_kinds()));
    }
    let mut lent = lent_parameters(flows, declared, &unlent, &mut positions);
    let mut fixed: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut never: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut unmixed = flows.unlinked.to_owned();
    for (word, _) in flows.known.iter() { if flows.unwrappable.contains(word) || fixed_by_publishing(word, flows, declared) { fixed.insert(word.to_owned()); } }
    let mut changed = true;
    while changed {
        changed = false;
        for (from, to) in flows.still_into.iter() {
            let into = nikaia_std::index::or(match *nikaia_std::index::get(&positions, to) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into());
            let kept = into.owned || fixed.contains(to) || never.contains(to) || a_published_parameter(to, flows, declared);
            if kept && !into.view && !into.either && joins_kinds(from, &kinds_joined(&nikaia_std::index::or(match *nikaia_std::index::get(&positions, from) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into()), &owned_kinds()), &mut positions) {
                demoted.insert(from.to_owned());
                changed = true;
            }
        }
        for (_, kept) in flows.literal_lets.iter() {
            let mut owned = false;
            for word in kept.iter() {
                let tier = tier_of_kinds(&nikaia_std::index::or(match *nikaia_std::index::get(&positions, word) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || no_kinds().into()));
                let published = fixed.contains(word) || never.contains(word) || a_published_parameter(word, flows, declared);
                if owned_tier(tier) || lasting_tier(tier) && published { owned = true; }
            }
            if owned {
                for word in kept.iter() {
                    let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, word) {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || no_kinds().into());
                    if lasting_tier(tier_of_kinds(&before)) && joins_kinds(word, &kinds_joined(&before, &owned_kinds()), &mut positions) {
                        demoted.insert(word.to_owned());
                        changed = true;
                    }
                }
            }
        }
        for (a, b) in flows.links.iter() {
            let mut both = nikaia_std::index::or(match *nikaia_std::index::get(&positions, a) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into());
            both = kinds_joined(&both, &nikaia_std::index::or(match *nikaia_std::index::get(&positions, b) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into()));
            if joins_kinds(a, &both, &mut positions) { changed = true; }
            if joins_kinds(b, &both, &mut positions) { changed = true; }
            if fixed.contains(a) != fixed.contains(b) {
                fixed.insert(a.to_owned());
                fixed.insert(b.to_owned());
                changed = true;
            }
            if never.contains(a) != never.contains(b) {
                never.insert(a.to_owned());
                never.insert(b.to_owned());
                changed = true;
            }
            if unmixed.contains(a) != unmixed.contains(b) {
                unmixed.insert(a.to_owned());
                unmixed.insert(b.to_owned());
                changed = true;
            }
        }
        for (from, to) in flows.read_into.iter() {
            if fixed.contains(to) && !fixed.contains(from) && mixed(tier_of_kinds(&nikaia_std::index::or(match *nikaia_std::index::get(&positions, from) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into()))) {
                fixed.insert(from.to_owned());
                changed = true;
            }
        }
        for (from, to) in flows.param_into.iter() {
            if fixed.contains(to) && !fixed.contains(from) {
                fixed.insert(from.to_owned());
                changed = true;
            }
        }
    }
    let mut out: collections::BTreeMap<String, Tier> = collections::BTreeMap::new();
    for (word, kinds) in positions.iter() {
        let kinds = *kinds;
        let mut tier = tier_of_kinds(&kinds);
        if mixed(tier) && (fixed.contains(word) || unmixed.contains(word)) { tier = Tier::Owned; }
        if lasting_tier(tier) && (fixed.contains(word) || never.contains(word) || a_published_parameter(word, flows, declared)) { tier = Tier::Owned; }
        if !owned_tier(tier) { out.insert(word.to_owned(), tier); }
    }
    let mut only_read: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (word, tier) in out.iter() {
        let tier = *tier;
        if lasting_tier(tier) && a_parameter_itself(word, flows) && !a_nullable_parameter(word, flows, declared) { only_read.insert(word.to_owned()); }
    }
    let mut shrinking = true;
    while shrinking {
        shrinking = false;
        for (from, to) in flows.param_into.iter() {
            if only_read.contains(from) && !only_read.contains(to) {
                only_read.remove(from);
                shrinking = true;
            }
        }
        for (from, to) in flows.still_into.iter() {
            if only_read.contains(from) && !only_read.contains(to) {
                only_read.remove(from);
                shrinking = true;
            }
        }
    }
    for word in only_read.iter() { out.remove(word); }
    for word in flows.viewed.iter() { out.insert(word.to_owned(), Tier::View); }
    for (from, to) in flows.lent_into.iter() {
        if lent.contains(from) && !same_tier(nikaia_std::index::or(match *nikaia_std::index::get(&out, to) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Tier::Owned), Tier::View) {
            unlent.insert(from.to_owned());
            lent.remove(from);
        }
    }
    for word in lent.iter() { out.insert(word.to_owned(), Tier::View); }
    out
}

fn same_tier(a: Tier, b: Tier) -> bool { tier_word(a) == tier_word(b) }

fn lent_parameters(flows: &Flows, declared: &TextDeclared, unlent: &collections::BTreeSet<String>, positions: &mut collections::BTreeMap<String, Kinds>) -> collections::BTreeSet<String> {
    let mut lent: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (from, _) in flows.lent_into.iter() {
        let given = nikaia_std::index::or(match *nikaia_std::index::get(&positions, from) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        let named = nikaia_std::index::or(*nikaia_std::index::get(&flows.uses, from), || 0);
        let handed = nikaia_std::index::or(*nikaia_std::index::get(&flows.lent_uses, from), || 0);
        let argued = nikaia_std::index::or(*nikaia_std::index::get(&flows.arg_uses, from), || 0);
        if named == handed + argued && !flows.changed.contains(from) && !unlent.contains(from) && !lasting_tier(tier_of_kinds(&given)) { lent.insert(from.to_owned()); }
    }
    for (from, to) in flows.param_into.iter() { if lent.contains(from) && !flows.lent_into.contains(&(from.to_owned(), to.to_owned())) && !a_parameter_itself(to, flows) { lent.remove(from); } }
    let mut reading: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (_, to) in flows.arg_into.iter() {
        let named = nikaia_std::index::or(*nikaia_std::index::get(&flows.uses, to), || 0);
        let argued = nikaia_std::index::or(*nikaia_std::index::get(&flows.arg_uses, to), || 0);
        if named == argued && !flows.changed.contains(to) && a_parameter_itself(to, flows) { reading.insert(to.to_owned()); }
    }
    let mut dropping = true;
    while dropping {
        dropping = false;
        for (from, to) in flows.arg_into.iter() {
            let only_reads = reading.contains(to) || lent.contains(to) || a_view_parameter(to, flows, declared);
            if !only_reads && (lent.contains(from) || reading.contains(from)) {
                lent.remove(from);
                reading.remove(from);
                dropping = true;
            }
        }
        for (from, to) in flows.lent_into.iter() {
            if !lent.contains(from) { continue; }
            let into = nikaia_std::index::or(match *nikaia_std::index::get(&positions, to) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into());
            let mut kept = into.owned || into.either || into.still || flows.in_maps.contains(to) || flows.unwrappable.contains(to) || fixed_by_publishing_field(to, flows, declared);
            for (other, target) in flows.lent_into.iter() { if target == to && !lent.contains(other) { kept = true; } }
            if kept {
                lent.remove(from);
                dropping = true;
            }
        }
    }
    for (from, to) in flows.lent_into.iter() {
        let mut kinds = nikaia_std::index::or(match *nikaia_std::index::get(&flows.lent_kinds, from) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || owned_kinds().into());
        if lent.contains(from) { kinds = view_kinds(); }
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, to) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        positions.insert(to.to_owned(), kinds_joined(&before, &kinds));
    }
    for (from, to) in flows.arg_into.iter() {
        let mut kinds = nikaia_std::index::or(match *nikaia_std::index::get(&flows.lent_kinds, from) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || owned_kinds().into());
        if lent.contains(from) { kinds = view_kinds(); }
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, to) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        positions.insert(to.to_owned(), kinds_joined(&before, &kinds));
    }
    lent
}

fn a_view_parameter(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !position.path.is_empty() { return false; }
    match &position.owner {
        TextOwner::Param(key, at) => {
            let at = *at;
            let function = match *nikaia_std::index::get(&declared.fns, key) { Some(__nikaia_value) => __nikaia_value, None => return false };
            at < function.params.len() as i64 && nikaia_std::index::get(&function.params, nikaia_std::index::at(at)).is_view
        },
        _ => false,
    }
}

fn fixed_by_publishing_field(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    match &position.owner {
        TextOwner::Field(_, _) => position_published(&position.owner, declared),
        _ => false,
    }
}

fn a_parameter_itself(word: &str, flows: &Flows) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let a_parameter = matches!(position.owner, TextOwner::Param(_, _));
    a_parameter && position.path.is_empty()
}

fn outlived_by_a_keeper(key: &str, at: i64, args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &TierWalk) -> bool {
    let word = position_word(&TextOwner::Param(key.to_owned(), at), &no_path());
    let source = match tie_root(nikaia_std::index::get(&args, nikaia_std::index::at(at)), ask) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let held = tie_depth(&source, walk);
    for (from, other) in walk.kept_into.iter() {
        let other = nikaia_std::num::value(other);
        if *from == word && other < args.len() as i64 {
            let root = match tie_root(nikaia_std::index::get(&args, nikaia_std::index::at(other)), ask) { Some(__nikaia_value) => __nikaia_value, None => return true };
            let mut depth = tie_depth(&root, walk);
            if depth <= 0 { depth = -1; }
            if depth < held { return true; }
        }
    }
    false
}

fn tier_kept_into(flows: &Flows) -> collections::BTreeSet<(String, i64)> {
    let mut out: collections::BTreeSet<(String, i64)> = collections::BTreeSet::new();
    for pair in flows.kept_through.iter() { out.insert(pair.clone()); }
    for (from, to) in flows.param_into.iter() {
        let position = match match *nikaia_std::index::get(&flows.known, to) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        if position.path.is_empty() { continue; }
        match position.owner {
            TextOwner::Param(_, other) => { out.insert((from.to_owned(), other)); },
            _ => { },
        }
    }
    out
}

fn kept_through_a_call(key: &str, at: i64, args: &[Expr], ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    let from: String = match handed_parameter(Some(nikaia_std::index::get(&args, nikaia_std::index::at(at))), ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let word = position_word(&TextOwner::Param(key.to_owned(), at), &no_path());
    let reading = tier_keeping_read(word.to_owned(), walk);
    let kept = walk.kept_into.to_owned();
    for (to, other) in kept.iter() {
        let other = nikaia_std::num::value(other);
        if *to == word && other < args.len() as i64 {
            let index = match own_parameter_index(nikaia_std::index::get(&args, nikaia_std::index::at(other)), ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => continue };
            walk.flows.kept_through.insert((from.to_owned(), index));
        }
    }
}

fn own_parameter_index(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &TierWalk) -> Option<i64> {
    let root = match tie_root(value, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let local = match tier_local(&root, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return None };
    match declared.owner {
        TextOwner::Param(_, index) => Some(index),
        _ => None,
    }
}

fn changed_keepers(a: &collections::BTreeSet<(String, i64)>, b: &collections::BTreeSet<(String, i64)>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (from, other) in a.iter() {
        let other = nikaia_std::num::value(other);
        if !b.contains(&(from.to_owned(), other)) { out.insert(from.to_owned()); }
    }
    for (from, other) in b.iter() {
        let other = nikaia_std::num::value(other);
        if !a.contains(&(from.to_owned(), other)) { out.insert(from.to_owned()); }
    }
    out
}

fn tier_keeping(flows: &Flows) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (from, to) in flows.param_into.iter() { if !a_parameter_itself(to, flows) { out.insert(from.to_owned()); } }
    let mut growing = true;
    while growing {
        growing = false;
        for (from, to) in flows.param_into.iter() {
            if out.contains(to) && !out.contains(from) {
                out.insert(from.to_owned());
                growing = true;
            }
        }
    }
    out
}

fn same_words(a: &collections::BTreeSet<String>, b: &collections::BTreeSet<String>) -> bool {
    if (a.len() as i64) != b.len() as i64 { return false; }
    for word in a.iter() { if !b.contains(word) { return false; } }
    true
}

fn viewed_param_arms(flows: &Flows, before: &collections::BTreeSet<i64>) -> collections::BTreeSet<i64> {
    let mut out = before.to_owned();
    let mut counts: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for (_, word) in flows.param_arm_into.iter() {
        let held = nikaia_std::index::or(*nikaia_std::index::get(&counts, word), || 0);
        counts.insert(word.to_owned(), held + 1);
    }
    for (at, word) in flows.param_arm_into.iter() {
        let at = nikaia_std::num::value(at);
        let named = nikaia_std::index::or(*nikaia_std::index::get(&flows.uses, word), || 0);
        let arms = nikaia_std::index::or(*nikaia_std::index::get(&counts, word), || 0);
        if named == arms { out.insert(at.clone()); }
    }
    out
}

fn a_keeping_target(function: &FnDecl, at: i64, ask: &TierAsk<'_, '_, '_, '_>) -> bool {
    if function.published || function.of_a_trait || at >= function.params.len() as i64 { return false; }
    if at < function.changes.len() as i64 && *nikaia_std::index::get(&function.changes, nikaia_std::index::at(at)) { return false; }
    let ty = (*nikaia_std::index::get(&function.params, nikaia_std::index::at(at))).clone();
    if !plain_string(ask.names, &ty) || ty.is_nullable || ty.is_view { return false; }
    true
}

fn param_arm_leaves(value: &Expr, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    match value {
        Expr::Block(block, _) => { param_arm_tail(block, ask, walk); },
        Expr::If { then_branch, else_branch, .. } => {
            param_arm_tail(then_branch, ask, walk);
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
            param_arm_tail(otherwise, ask, walk);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { param_arm_leaves(&arm.body, ask, walk); } },
        Expr::Variable(_, _) => {
            if !walk.late_params.contains(&node_key(value)) { return; }
            let word = match lendable_parameter(value, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            if walk.unlent.contains(&word) { return; }
            walk.flows.param_arm_into.insert(node_key(value), word);
        },
        _ => { },
    }
}

fn param_arm_tail(block: &Block, ask: &TierAsk<'_, '_, '_, '_>, walk: &mut TierWalk) {
    if block.stmts.is_empty() { return; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(last) => { param_arm_leaves(last, ask, walk); },
        _ => { },
    }
}

fn a_nullable_parameter(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    match &position.owner {
        TextOwner::Param(key, at) => {
            let at = *at;
            let function = match *nikaia_std::index::get(&declared.fns, key) { Some(__nikaia_value) => __nikaia_value, None => return false };
            at < function.params.len() as i64 && nikaia_std::index::get(&function.params, nikaia_std::index::at(at)).is_nullable
        },
        _ => false,
    }
}

fn a_published_parameter(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let a_parameter = matches!(position.owner, TextOwner::Param(_, _));
    a_parameter && position_published(&position.owner, declared)
}

fn joins_kinds(word: &str, both: &Kinds, positions: &mut collections::BTreeMap<String, Kinds>) -> bool {
    let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, word) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || no_kinds().into());
    if positions.contains_key(word) && same_kinds(&before, both) { return false; }
    positions.insert(word.to_owned(), both.clone());
    true
}

fn fixed_by_publishing(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !position_published(&position.owner, declared) { return false; }
    let a_parameter = matches!(position.owner, TextOwner::Param(_, _));
    !(a_parameter && position.path.is_empty())
}

fn same_tiers(a: &collections::BTreeMap<String, Tier>, b: &collections::BTreeMap<String, Tier>) -> bool {
    if (a.len() as i64) != b.len() as i64 { return false; }
    for (word, tier) in a.iter() {
        let tier = *tier;
        let other = match (*nikaia_std::index::get(&b, word)).copied() { Some(__nikaia_value) => __nikaia_value, None => return false };
        if tier_word(tier) != tier_word(other) { return false; }
    }
    true
}

fn tier_word(tier: Tier) -> &'static str {
    match tier {
        Tier::Owned => "owned",
        Tier::View => "view",
        Tier::Mixed => "mixed",
        Tier::Lasting => "lasting",
    }
}

pub fn text_tiers(program: &Program, ask: &TierAsk<'_, '_, '_, '_>) -> TextTiers {
    let declared = declared_of(program, ask.names);
    let text = string_type(&declared, ask.names);
    let mut walk = TierWalk { declared, tiers: collections::BTreeMap::new(), flows: no_flows(), locals: collections::BTreeMap::new(), frames: vec![], result: None, in_hole: false, hole_text: -1, lent_self: false, adopted: collections::BTreeMap::new(), demoted: collections::BTreeSet::new(), handed_back: -1, unlent: collections::BTreeSet::new(), read_here: false, tail_back: false, ties: collections::BTreeMap::new(), late: collections::BTreeSet::new(), late_args: collections::BTreeSet::new(), late_params: collections::BTreeSet::new(), keeping: collections::BTreeSet::new(), kept_into: collections::BTreeSet::new(), param_arms: collections::BTreeSet::new(), reads: no_reads() };
    let found = late_arms(program, ask);
    walk.late = found.arms;
    walk.late_args = found.args;
    walk.late_params = found.params;
    let units = tier_units(program);
    let mut found_flows: Vec<Flows> = vec![];
    let mut found_reads: Vec<TierReads> = vec![];
    let mut dirty: Vec<bool> = vec![];
    for _ in units.iter() {
        found_flows.push(no_flows());
        found_reads.push(no_reads());
        dirty.push(true);
    }
    for _ in 0..16 {
        let mut u: i64 = 0;
        while ((u) as usize) < units.len() {
            if *nikaia_std::index::get(&dirty, (u) as usize) {
                walk.flows = no_flows();
                walk.reads = no_reads();
                let (item_at, method_at) = *nikaia_std::index::get(&units, (u) as usize);
                walk_unit(program, item_at, method_at, ask, &mut walk);
                { let __nikaia_stored = walk.flows.clone(); nikaia_std::index::set(&mut found_flows, (u) as usize, __nikaia_stored); }
                { let __nikaia_stored = walk.reads.clone(); nikaia_std::index::set(&mut found_reads, (u) as usize, __nikaia_stored); }
            }
            u += 1;
        }
        walk.flows = no_flows();
        for unit_flows in found_flows.iter() { merge_flows(&mut walk.flows, unit_flows); }
        let demoted_before = walk.demoted.len() as i64;
        let unlent_before = walk.unlent.len() as i64;
        let next = decide_tiers(&walk.flows, &walk.declared, &mut walk.demoted, &mut walk.unlent);
        let linked = same_adopted(&walk.flows.adopted, &walk.adopted);
        let keeping = tier_keeping(&walk.flows);
        let kept_into = tier_kept_into(&walk.flows);
        let keepers_moved = changed_keepers(&kept_into, &walk.kept_into);
        let arms = viewed_param_arms(&walk.flows, &walk.param_arms);
        let settled = same_words(&keeping, &walk.keeping) && keepers_moved.is_empty() && (arms.len() as i64) == walk.param_arms.len() as i64;
        if same_tiers(&next, &walk.tiers) && linked && settled && (walk.demoted.len() as i64) == demoted_before && (walk.unlent.len() as i64) == unlent_before { break; }
        let tiers_moved = changed_tier_words(&next, &walk.tiers);
        let mut keeping_moved = changed_words(&keeping, &walk.keeping);
        for word in keepers_moved.iter() { keeping_moved.insert(word.to_owned()); }
        let arms_moved = changed_nodes(&arms, &walk.param_arms);
        let adopted_moved = changed_adopted(&walk.flows.adopted, &walk.adopted);
        let mut v: i64 = 0;
        while ((v) as usize) < units.len() {
            { let __nikaia_stored = tier_reads_changed(nikaia_std::index::get(&found_reads, (v) as usize), &tiers_moved, &keeping_moved, &arms_moved, &adopted_moved); nikaia_std::index::set(&mut dirty, (v) as usize, __nikaia_stored); }
            v += 1;
        }
        walk.tiers = next;
        walk.adopted = walk.flows.adopted.to_owned();
        walk.keeping = keeping;
        walk.kept_into = kept_into;
        walk.param_arms = arms;
    }
    let mut tiers: Vec<(TextPosition, Tier)> = vec![];
    for (word, tier) in walk.tiers.iter() {
        let tier = *tier;
        let position = match match *nikaia_std::index::get(&walk.flows.known, word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        tiers.push((position, tier.clone()));
    }
    let mut lets: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for (at, kept) in walk.flows.literal_lets.iter() {
        let at = nikaia_std::num::value(at);
        for word in kept.iter() {
            if !walk.tiers.contains_key(word) {
                lets.insert(at.clone());
                break;
            }
        }
    }
    let mut adopted: collections::BTreeMap<i64, TierAdopted> = collections::BTreeMap::new();
    for (at, target) in walk.flows.adopted.iter() {
        let at = nikaia_std::num::value(at);
        adopted.insert(at.clone(), TierAdopted { owner: target.owner.clone(), ty: target.ty.clone() });
    }
    TextTiers { tiers, lets, text, wraps: walk.flows.wraps.to_owned(), hole_wraps: walk.flows.hole_wraps.to_owned(), adopted, viewed_arms: walk.flows.viewed_arms.to_owned() }
}

fn same_adopted(a: &collections::BTreeMap<i64, Declaring>, b: &collections::BTreeMap<i64, Declaring>) -> bool {
    if (a.len() as i64) != b.len() as i64 { return false; }
    for (at, target) in a.iter() {
        let at = nikaia_std::num::value(at);
        let other = match *nikaia_std::index::get(&b, &at) { Some(__nikaia_value) => __nikaia_value, None => return false };
        if owner_word(&target.owner) != owner_word(&other.owner) { return false; }
    }
    true
}

fn no_path() -> Vec<i64> { vec![] }


// --- threads.nika ---

const PLAIN_DATA: [&str; 19] = ["bool", "char", "scalar", "str", "String", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64"];

const CONTAINER_TYPES: [&str; 11] = ["BTreeMap", "BTreeSet", "HashMap", "HashSet", "List", "Option", "Receiver", "Result", "Sender", "Shared", "Vec"];

const CHOSEN_TYPES: [&str; 3] = ["Locked", "SharedMut", "Shared"];

const CROSSING_DEPTH: i64 = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Going {
    Ours,
    Foreign,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Refusal {
    Lock,
    Count,
    Said,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Crossing {
    May,
    MayNot { part: String, at: Option<String>, why: Refusal },
    Undecided { part: String },
}

impl Crossing {
    pub fn may(&self) -> bool { matches!(self, Crossing::May) }
    pub fn refused_part(&self) -> Option<String> {
        match self {
            Crossing::MayNot { part, .. } => Some(part.to_owned()),
            _ => None,
        }
    }
    pub fn refused_at(&self) -> Option<String> {
        match self {
            Crossing::MayNot { at, .. } => a_copy_of((at).as_deref()),
            _ => None,
        }
    }
    pub fn why(&self) -> Option<Refusal> {
        match self {
            Crossing::MayNot { why, .. } => Some(why.clone()),
            _ => None,
        }
    }
    pub fn way_out(&self) -> Option<String> {
        match self {
            Crossing::MayNot { why, .. } => Some(way_out_of(*why)),
            _ => None,
        }
    }
    pub fn note(&self) -> Option<String> {
        match self {
            Crossing::May => None,
            Crossing::MayNot { part, at, why } => Some(refusal_note(part, (at).as_deref(), *why)),
            Crossing::Undecided { part } => Some(format!("Nothing says whether `{}` can move to another thread, so the compiler assumes it can't.", part)),
        }
    }
}

fn a_copy_of(text: Option<&str>) -> Option<String> {
    let there = match text { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(there.to_owned())
}

fn way_out_of(why: Refusal) -> String {
    match why {
        Refusal::Lock => String::from("Open the lock here and pass the value inside it, so the called code gets an ordinary value and no lock."),
        Refusal::Count => String::from("Pass what the shared value holds, a view or a copy, instead of the shared value itself."),
        Refusal::Said => String::from("Keep it here, and pass the call only what it needs from it."),
    }
}

fn refusal_note(part: &str, at: Option<&str>, why: Refusal) -> String {
    let clause = held_clause(at);
    match why {
        Refusal::Lock => format!("`{}`{} holds a lock, and a lock can't be passed to code the compiler knows nothing about.", part, clause),
        Refusal::Count => format!("`{}`{} is shared, and how a shared value is counted is decided per value, so code outside Nikaia can't be written to handle it.", part, clause),
        Refusal::Said => format!("`{}`{} is described as a value that can't move to another thread.", part, clause),
    }
}

fn held_clause(at: Option<&str>) -> String {
    let field = match at { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!(", which its field `{}` holds,", field)
}

pub fn crossing(ty: &Ty, walking: &Walking<'_, '_>) -> Crossing {
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
    crossing_walk(ty, walking, &mut seen, CROSSING_DEPTH)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Walking<'a, 'a1> {
    pub own: &'a Ledger,
    pub library: &'a1 Ledger,
    pub into: Going,
}

fn crossing_walk(ty: &Ty, walking: &Walking<'_, '_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    if depth == 0 { return Crossing::Undecided { part: ty.text() }; }
    match ty {
        Ty::Unknown => Crossing::Undecided { part: String::from("?") },
        Ty::Count(_) => Crossing::May,
        Ty::Pointed { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Var { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Fn { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Seq { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); crossing_walk(inner, walking, seen, depth - 1) },
        Ty::Tuple(parts) => all_of(parts, walking, seen, depth),
        Ty::Named { name, args, .. } => named_crossing(ty, name, args, walking, seen, depth),
    }
}

fn named_crossing(ty: &Ty, name: &str, args: &[Ty], walking: &Walking<'_, '_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let base = base_name(name);
    if one_of(&PLAIN_DATA, &base) {
        if args.is_empty() { return Crossing::May; }
        return Crossing::Undecided { part: ty.text() };
    }
    let foreign = match walking.into {
        Going::Foreign => true,
        Going::Ours => false,
    };
    if one_of(&CONTAINER_TYPES, &base) {
        let inside = if args.is_empty() { Crossing::Undecided { part: ty.text() } } else { all_of(args, walking, seen, depth) };
        if foreign && one_of(&CHOSEN_TYPES, name) && inside.refused_part().is_none() { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Count }; }
        return inside;
    }
    if one_of(&CHOSEN_TYPES, name) {
        if foreign { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Lock }; }
        if args.is_empty() { return Crossing::Undecided { part: ty.text() }; }
        return all_of(args, walking, seen, depth);
    }
    described_crossing(ty, name, args, walking, seen, depth)
}

fn described_crossing(ty: &Ty, name: &str, args: &[Ty], walking: &Walking<'_, '_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let contract = match ledger_type(name, walking.own, walking.library) { Some(__nikaia_value) => __nikaia_value, None => return Crossing::Undecided { part: ty.text() } };
    if contract.crosses.may_not() { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Said }; }
    if contract.crosses.may() && args.is_empty() { return Crossing::May; }
    if contract.fields.is_empty() { return Crossing::Undecided { part: ty.text() }; }
    if !seen.insert(name.to_owned()) { return Crossing::May; }
    let mut worst = Crossing::May;
    for field in contract.fields.iter() {
        let answer = name_the_field(&field.name, crossing_walk(&field.ty, walking, seen, depth - 1));
        worst = worst_of(worst, answer);
    }
    seen.remove(name);
    worst
}

fn all_of(parts: &[Ty], walking: &Walking<'_, '_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let mut worst = Crossing::May;
    for part in parts.iter() { worst = worst_of(worst, crossing_walk(part, walking, seen, depth - 1)); }
    worst
}

pub fn worst_of(worst: Crossing, answer: Crossing) -> Crossing {
    match worst {
        Crossing::MayNot { .. } => worst,
        Crossing::Undecided { .. } => match answer {
            Crossing::MayNot { .. } => answer,
            _ => worst,
        },
        Crossing::May => answer,
    }
}

fn name_the_field(field: &str, answer: Crossing) -> Crossing {
    match answer {
        Crossing::MayNot { ref part, ref at, why } => field_named_at(field, part, (at).as_deref(), &why),
        _ => answer,
    }
}

fn field_named_at(field: &str, part: &str, at: Option<&str>, why: &Refusal) -> Crossing {
    let already = match at { Some(__nikaia_value) => __nikaia_value, None => return Crossing::MayNot { part: part.to_owned(), at: Some(field.to_owned()), why: why.clone() } };
    Crossing::MayNot { part: part.to_owned(), at: Some(already.to_owned()), why: why.clone() }
}

fn ledger_type(name: &str, own: &Ledger, library: &Ledger) -> Option<TypeContract> {
    let suffix = format!("::{}", name);
    let mine = in_one_ledger(name, &suffix, own);
    if mine.is_some() { return std::convert::identity(mine); }
    in_one_ledger(name, &suffix, library)
}

fn in_one_ledger(name: &str, suffix: &str, ledger: &Ledger) -> Option<TypeContract> {
    let whole: Option<TypeContract> = match *nikaia_std::index::get(&ledger.types, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if whole.is_some() { return std::convert::identity(whole); }
    for (key, contract) in ledger.types.iter() { if key.ends_with(suffix) { return Some(contract.clone()); } }
    None
}

fn base_name(name: &str) -> String {
    let parts: Vec<&str> = name.split("::").collect::<Vec<_>>();
    (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned()
}

fn one_of(names: &[&str], name: &str) -> bool {
    for one in names.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

pub fn held_across_a_pause(bound: &[(String, i64)], pauses: &[i64], named: &collections::BTreeMap<String, i64>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (name, at) in bound.iter() {
        let at = nikaia_std::num::value(at);
        let last = match *nikaia_std::index::get(&named, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        for pause in pauses.iter() {
            let pause = nikaia_std::num::value(pause);
            if pause > at && last > pause { out.insert(name.to_owned()); }
        }
    }
    out
}


// --- throws.nika ---

const UNNAMED: &str = "?";

pub const AS_VALUE: &str = "<as a value>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MethodsCalled {
    pub resolved: collections::BTreeSet<String>,
    pub unseen: bool,
    pub fields: collections::BTreeSet<String>,
    pub swallowed: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ThrowsGraph {
    pub methods: collections::BTreeMap<String, MethodsCalled>,
    pub direct: collections::BTreeMap<String, collections::BTreeSet<String>>,
    pub calls: collections::BTreeMap<String, collections::BTreeSet<String>>,
    pub fatal_calls: collections::BTreeMap<String, collections::BTreeMap<String, collections::BTreeSet<String>>>,
    pub fatal: collections::BTreeSet<String>,
}

pub fn unit_throws(program: &Program, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, own: &Ledger, library: &Ledger, graph: &mut ThrowsGraph) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, can_throw, .. } => {
                let can_throw = *can_throw; let name = *name;
                if can_throw {
                    let thrown = thrown_by(body, names, holes_of, contribution_of);
                    with_methods(&key_of_function((name).as_ref(), "", names), &thrown, own, library, graph);
                }
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, can_throw, .. } => {
                            let can_throw = *can_throw; let name = *name;
                            if can_throw {
                                let thrown = thrown_by(body, names, holes_of, contribution_of);
                                with_methods(&key_of_function((name).as_ref(), &owner, names), &thrown, own, library, graph);
                            }
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
}

fn with_methods(key: &str, thrown: &Thrown, own: &Ledger, library: &Ledger, graph: &mut ThrowsGraph) {
    let mut named = thrown.direct.to_owned();
    let mut called: collections::BTreeSet<String> = collections::BTreeSet::new();
    let fields: collections::BTreeSet<String> = nikaia_std::index::or(match (*nikaia_std::index::get(&graph.methods, key)).as_ref().map(|__nikaia_it| &__nikaia_it.fields) {
        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
        None => None,
    }, || collections::BTreeSet::new().into());
    for callee in thrown.calls.iter() {
        if !callee.starts_with('@') {
            called.insert(callee.to_owned());
            continue;
        }
        let local: String = nikaia_std::index::or(callee.strip_prefix('@'), || "").to_owned();
        let place = format!("{}::{}", key, local);
        if !fields.contains(&place) { named.insert(UNNAMED.to_owned()); }
    }
    let mut fatal_calls = thrown.fatal_calls.to_owned();
    methods_into(*nikaia_std::index::get(&graph.methods, key), own, library, &graph.fatal, &mut named, &mut called, &mut fatal_calls);
    graph.direct.insert(key.to_owned(), named);
    graph.calls.insert(key.to_owned(), called);
    graph.fatal_calls.insert(key.to_owned(), fatal_calls);
}

fn methods_into(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, fatal: &collections::BTreeSet<String>, named: &mut collections::BTreeSet<String>, called: &mut collections::BTreeSet<String>, fatal_calls: &mut collections::BTreeMap<String, collections::BTreeSet<String>>) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    for field in known.fields.iter() { called.insert(field.to_owned()); }
    if known.unseen { named.insert(UNNAMED.to_owned()); }
    for callee in known.resolved.iter() {
        if known.swallowed.contains_key(callee) {
            let taken: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&known.swallowed, callee) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            if own.functions.contains_key(callee) { if !fatal_calls.contains_key(callee) { fatal_calls.insert(callee.to_owned(), taken); } } else { for error in fails_with_of(library, callee) { if fatal.contains(&error) && !taken.contains(&error) { named.insert(error); } } }
            continue;
        }
        if own.functions.contains_key(callee) { called.insert(callee.to_owned()); } else { for error in fails_with_of(library, callee) { named.insert(error); } }
    }
}

pub fn stored_throws(field: &str, resolved: &collections::BTreeSet<String>, unresolved: bool, free: &collections::BTreeSet<String>, own: &Ledger, library: &Ledger, graph: &mut ThrowsGraph) {
    let mut named: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut called: collections::BTreeSet<String> = collections::BTreeSet::new();
    if unresolved { named.insert(UNNAMED.to_owned()); }
    for callee in free.iter() { if callee.starts_with('@') { called.insert(nikaia_std::index::or(callee.strip_prefix('@'), || "").to_owned()); } else if own.functions.contains_key(callee) { called.insert(callee.to_owned()); } else if library.functions.contains_key(callee) { for error in fails_with_of(library, callee) { named.insert(error); } } }
    let known: Option<MethodsCalled> = Some(MethodsCalled { resolved: resolved.to_owned(), unseen: false, fields: collections::BTreeSet::new(), swallowed: collections::BTreeMap::new() });
    let mut fatal_calls: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    methods_into((known).as_ref(), own, library, &graph.fatal, &mut named, &mut called, &mut fatal_calls);
    graph.direct.insert(field.to_owned(), named);
    graph.calls.insert(field.to_owned(), called);
}

pub fn params_as_places(own: &Ledger, stored: &mut collections::BTreeMap<String, CheckStoredCode>) -> collections::BTreeSet<String> {
    let mut open: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut kept: collections::BTreeSet<String> = collections::BTreeSet::new();
    let named: CheckStoredCode = nikaia_std::index::or(stored.remove(AS_VALUE), || CheckStoredCode::empty());
    for free in named.free.iter() { kept.insert(free.to_owned()); }
    for (_, code) in stored.iter() { for free in code.free.iter() { kept.insert(free.to_owned()); } }
    for (owner, contract) in own.types.iter() {
        if !contract.public { continue; }
        for field in contract.fields.iter() {
            if !field.public || !check_core_stmt_holds_code(&field.ty) { continue; }
            let key = format!("{}.{}", owner, field.name);
            let mut entry: CheckStoredCode = nikaia_std::index::or(stored.remove(&key), || CheckStoredCode::empty());
            entry.unresolved = true;
            stored.insert(key, entry);
        }
    }
    for (name, contract) in own.functions.iter() {
        if name.contains("::") { continue; }
        let signature: &Signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        for (param, ty) in signature.params.iter() {
            if !check_core_stmt_holds_code(ty) { continue; }
            let key = format!("{}::{}", name, param);
            let entry: CheckStoredCode = nikaia_std::index::or(stored.remove(&key), || CheckStoredCode::empty());
            if contract.public || kept.contains(name) { open.insert(key.to_owned()); }
            stored.insert(key, entry);
        }
    }
    open
}

pub fn throws_given(error: &str) -> bool { error.starts_with("from(") && error.ends_with(')') }

pub fn throws_published(name: &str, errors: &[String]) -> Vec<String> {
    let prefix = format!("from({}::", name);
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for error in errors.iter() {
        if !throws_given(error) { out.insert(error.to_owned()); } else if error.starts_with(&prefix) {
            let rest: String = nikaia_std::index::or(error.strip_prefix(&prefix), || "").to_owned();
            out.insert(format!("from({}", rest));
        } else { out.insert(UNNAMED.to_owned()); }
    }
    let mut list: Vec<String> = vec![];
    for error in out.iter() { list.push(error.to_owned()); }
    list
}

fn fails_with_of(library: &Ledger, callee: &str) -> Vec<String> {
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return vec![String::from("?")] };
    contract.fails_with.to_owned()
}

pub fn error_sets(direct: &collections::BTreeMap<String, collections::BTreeSet<String>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>, fatal_calls: &collections::BTreeMap<String, collections::BTreeMap<String, collections::BTreeSet<String>>>, fatal: &collections::BTreeSet<String>, own: &Ledger, places: &collections::BTreeSet<String>) -> collections::BTreeMap<String, Vec<String>> {
    let mut sets = direct.to_owned();
    throws_grow(&mut sets, calls, fatal_calls, fatal, own);
    let mut unnamed: Vec<String> = vec![];
    for (name, set) in sets.iter() {
        if !set.is_empty() || places.contains(name) { continue; }
        let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !contract.fails_with.is_empty() { unnamed.push(name.to_owned()); }
    }
    if !unnamed.is_empty() {
        for name in unnamed.iter() {
            let mut only: collections::BTreeSet<String> = collections::BTreeSet::new();
            only.insert(UNNAMED.to_owned());
            sets.insert(name.to_owned(), only);
        }
        throws_grow(&mut sets, calls, fatal_calls, fatal, own);
    }
    let mut settled: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (name, set) in sets.iter() {
        if places.contains(name) {
            let mut union: Vec<String> = vec![];
            for error in set.iter() { union.push(error.to_owned()); }
            settled.insert(name.to_owned(), union);
            continue;
        }
        let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if contract.fails_with.is_empty() { continue; }
        let own_prefix = format!("from({}::", name);
        let mut mapped: collections::BTreeSet<String> = collections::BTreeSet::new();
        for error in set.iter() {
            if !throws_given(error) || error.starts_with(&own_prefix) {
                mapped.insert(error.to_owned());
                continue;
            }
            let mut through: String = error.to_owned();
            for callee in nikaia_std::index::or(match *nikaia_std::index::get(&calls, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into()) {
                if places.contains(&callee) && callee.starts_with(&format!("{}::", name)) {
                    let held = nikaia_std::index::or(match *nikaia_std::index::get(&sets, &callee) {
                        Some(__nikaia_it) => Some(__nikaia_it.clone()),
                        None => None,
                    }, || collections::BTreeSet::new().into());
                    if held.contains(error) { through = format!("from({})", callee); }
                }
            }
            mapped.insert(through);
        }
        let mut errors: Vec<String> = vec![];
        for error in mapped.iter() { errors.push(error.to_owned()); }
        if errors.is_empty() { errors.push(String::from("?")); }
        settled.insert(name.to_owned(), errors);
    }
    settled
}

fn throws_grow(sets: &mut collections::BTreeMap<String, collections::BTreeSet<String>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>, fatal_calls: &collections::BTreeMap<String, collections::BTreeMap<String, collections::BTreeSet<String>>>, fatal: &collections::BTreeSet<String>, own: &Ledger) {
    let mut changed = true;
    while changed {
        changed = false;
        for (name, callees) in calls.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&sets, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let mut grown = before.to_owned();
            for callee in callees.iter() { for error in theirs(&sets, own, callee) { grown.insert(error); } }
            let caught = nikaia_std::index::or(match *nikaia_std::index::get(&fatal_calls, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeMap::new().into());
            for (callee, named) in caught.iter() { for error in theirs(&sets, own, callee) { if fatal.contains(&error) && !named.contains(&error) { grown.insert(error); } } }
            if (grown.len() as i64) != before.len() as i64 {
                sets.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
}

fn theirs(sets: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger, callee: &str) -> Vec<String> {
    let mut errors: Vec<String> = vec![];
    let prefix = format!("from({}::", callee);
    if sets.contains_key(callee) {
        let set = match *nikaia_std::index::get(&sets, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
        for error in set.iter() { if !error.starts_with(&prefix) { errors.push(error.to_owned()); } }
        return errors;
    }
    let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
    for error in contract.fails_with.iter() { errors.push(error.to_owned()); }
    errors
}

pub fn error_type(names: &winnow_grammar::InternerContext, thrown: &Expr) -> Option<String> {
    match thrown {
        Expr::Path(segments, _) => if segments.len() > 1 { Some(all_but_the_last(names, segments)) } else { None },
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); error_type(names, func) },
        Expr::StructLit { name, .. } => { let name = *name; Some(struct_type(names.resolve(name))) },
        _ => None,
    }
}

fn all_but_the_last(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol]) -> String {
    let mut written: String = String::from("");
    for k in 0..segments.len() as i64 - 1 {
        if k > 0 { written = format!("{}::", written); }
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        written = format!("{}{}", written, segment);
    }
    written
}

fn struct_type(written: &str) -> String {
    let mut parts: Vec<String> = vec![];
    for part in written.split("::") { parts.push(part.to_owned()); }
    if parts.len() < 2 { return written.to_owned(); }
    let mut ty: String = String::from("");
    for k in 0..parts.len() as i64 - 1 {
        if k > 0 { ty = format!("{}::", ty); }
        ty = format!("{}{}", ty, *nikaia_std::index::get(&parts, (k) as usize));
    }
    ty
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Thrown {
    pub direct: collections::BTreeSet<String>,
    pub calls: collections::BTreeSet<String>,
    passes_on: bool,
    named: collections::BTreeSet<String>,
    pub fatal_calls: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Contribution {
    pub call: Option<String>,
    pub given: Vec<String>,
    pub errors: Vec<String>,
    pub fatal: Vec<String>,
    pub result: Option<String>,
}

pub fn thrown_by(body: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> Thrown {
    let mut out = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false, named: collections::BTreeSet::new(), fatal_calls: collections::BTreeMap::new() };
    thrown_in_block(body, names, holes_of, contribution_of, false, &mut out);
    out
}

fn thrown_in_block(block: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => { thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out); },
            Stmt::Comptime { value, .. } => { thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out); },
            Stmt::Expr(value) => { thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out); },
            Stmt::Return(value) => { thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, false, out); },
            Stmt::Assign { target, value, .. } => {
                thrown_in(target, names, holes_of, contribution_of, in_a_handler, false, out);
                thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out);
            },
            Stmt::For { iter, .. } => { thrown_in(iter, names, holes_of, contribution_of, in_a_handler, false, out); },
            Stmt::While { cond, .. } => { thrown_in(cond, names, holes_of, contribution_of, in_a_handler, false, out); },
            _ => { },
        }
        match &stmt.node {
            Stmt::For { body, .. } => { thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::While { body, .. } => { thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::Let { value, .. } => { thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::Comptime { value, .. } => { thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::Expr(value) => { thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::Return(value) => { thrown_in_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, out); },
            Stmt::Assign { target, value, .. } => {
                thrown_in_blocks(target, names, holes_of, contribution_of, in_a_handler, out);
                thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out);
            },
            _ => { },
        }
    }
}

fn thrown_in(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    a_contribution(expr, names, contribution_of, in_a_handler, caught, out);
    for hole in holes_of(expr) { thrown_in(&hole, names, holes_of, contribution_of, in_a_handler, caught, out); }
    match expr {
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in(func, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            thrown_in(lhs, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(rhs, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(index, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            thrown_in(start, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(end, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { thrown_in(part, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(fallback, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            let into_the_handler = caught || !passes_on(handler, names, holes_of, contribution_of);
            let outer = out.named.to_owned();
            if !caught { out.named = fatal_named(handler, names); }
            thrown_in(expr, names, holes_of, contribution_of, in_a_handler, into_the_handler, out);
            out.named = outer;
        },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); thrown_in(cond, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arm in arms.iter() {
                maybe_thrown_in((arm.guard).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out);
                thrown_in(&arm.body, names, holes_of, contribution_of, in_a_handler, caught, out);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(count, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { thrown_in(item, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out); },
        Expr::Select(arms, _) => { for arm in arms.iter() { thrown_in(&arm.value, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        _ => { },
    }
}

fn maybe_thrown_in(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) { thrown_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out); }

fn thrown_in_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    match expr {
        Expr::Block(block, _) => { thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out); },
        Expr::Unsafe(block, _) => { thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out); },
        Expr::Overlap(block, _) => { thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out); },
        Expr::Closure { body, .. } => { thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out); },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); thrown_in_blocks(body, names, holes_of, contribution_of, in_a_handler, out); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in_blocks(func, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            thrown_in_block(then_branch, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, out);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            thrown_in_blocks(expr, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(handler, names, holes_of, contribution_of, true, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { thrown_in_blocks(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        Expr::Select(arms, _) => { for arm in arms.iter() { thrown_in_block(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        _ => { },
    }
}

fn a_contribution(expr: &Expr, names: &winnow_grammar::InternerContext, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    let passing = the_caught_error(expr, names);
    if passing { out.passes_on = true; }
    if in_a_handler && passing { return; }
    if caught {
        match expr {
            Expr::Throw(_, _) => { },
            _ => {
                let given = contribution_of(expr);
                for error in given.fatal.iter() { if !out.named.contains(error) { out.direct.insert(error.to_owned()); } }
                let call = nikaia_std::index::or(given.call, || "".into());
                if !call.is_empty() && !out.fatal_calls.contains_key(&call) { out.fatal_calls.insert(call, out.named.to_owned()); }
            },
        }
        return;
    }
    match expr {
        Expr::Throw(thrown, _) => {
            let thrown = nikaia_std::boxed::open(thrown);
            let written: String = nikaia_std::index::or(error_type(names, thrown), || "".into());
            if !written.is_empty() { out.direct.insert(written); } else {
                let given = contribution_of(thrown);
                out.direct.insert(nikaia_std::index::or(given.result, || "?".into()));
            }
        },
        _ => {
            let given = contribution_of(expr);
            let call = nikaia_std::index::or(given.call, || "".into());
            if !call.is_empty() { out.calls.insert(call); }
            for handed in given.given.iter() { out.calls.insert(handed.to_owned()); }
            for error in given.errors.iter() { out.direct.insert(error.to_owned()); }
        },
    }
}

fn the_caught_error(expr: &Expr, names: &winnow_grammar::InternerContext) -> bool {
    match expr {
        Expr::Throw(thrown, _) => { let thrown = nikaia_std::boxed::open(thrown); match thrown {
            Expr::Variable(name, _) => { let name = *name; names.resolve(name) == "error" },
            _ => false,
        } },
        _ => false,
    }
}

fn passes_on(handler: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> bool {
    let mut seen = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false, named: collections::BTreeSet::new(), fatal_calls: collections::BTreeMap::new() };
    thrown_in_block(handler, names, holes_of, contribution_of, false, &mut seen);
    seen.passes_on
}

pub fn throws_handler_passes_on(handler: &Block, names: &winnow_grammar::InternerContext) -> bool {
    for stmt in handler.stmts.iter() {
        for expr in check_visit_stmt(&stmt.node) { if the_caught_error(expr, names) { return true; } }
        for block in check_visit_stmt_blocks(&stmt.node) { if throws_handler_passes_on(block, names) { return true; } }
    }
    false
}

pub fn fatal_named(handler: &Block, names: &winnow_grammar::InternerContext) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for stmt in handler.stmts.iter() {
        match &stmt.node {
            Stmt::Expr(value) => { named_in_match(value, names, &mut out); },
            Stmt::Let { value, .. } => { named_in_match(value, names, &mut out); },
            Stmt::Return(value) => { named_in_match(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, &mut out); },
            _ => { },
        }
    }
    out
}

fn named_in_match(expr: &Expr, names: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            if !the_error(value, names) { return; }
            for arm in arms.iter() {
                let path = match pattern_path(&arm.pattern) { Some(__nikaia_value) => __nikaia_value, None => continue };
                if path.len() < 2 { continue; }
                let mut parts: Vec<String> = vec![];
                for at in 0..path.len() as i64 - 1 { parts.push(names.resolve(*nikaia_std::index::get(&path, (at) as usize)).to_owned()); }
                out.insert(parts.join("::"));
            }
        },
        _ => { },
    }
}

fn the_error(expr: &Expr, names: &winnow_grammar::InternerContext) -> bool {
    match expr {
        Expr::Variable(name, _) => { let name = *name; names.resolve(name) == "error" },
        _ => false,
    }
}

fn pattern_path(pattern: &MatchPattern) -> Option<Vec<winnow_grammar::Symbol>> {
    match pattern {
        MatchPattern::Path(path) => { return Some(path.to_owned()); },
        MatchPattern::Tuple { path, .. } => { return Some(path.to_owned()); },
        MatchPattern::Named { path, .. } => { return Some(path.to_owned()); },
        _ => { },
    }
    None
}


// --- tiers.nika ---

const OWNS: [&str; 10] = ["clone", "to_owned", "to_string", "clone_text", "to_uppercase", "to_lowercase", "repeat", "replace", "join", "concat"];

const VIEWS: [&str; 17] = ["trim", "trim_start", "trim_end", "trim_matches", "trim_start_matches", "trim_end_matches", "strip_prefix", "strip_suffix", "lines", "split", "split_whitespace", "splitn", "rsplit", "rsplitn", "split_terminator", "matches", "as_str"];

const ELEMENTS: [&str; 15] = ["collect", "next", "unwrap", "first", "last", "get", "iter", "nth", "peek", "pop", "remove", "values", "keys", "drain", "into_iter"];

const CHANGES: [&str; 14] = ["push_str", "push", "insert", "insert_str", "clear", "truncate", "pop", "remove", "retain", "drain", "extend", "make_ascii_uppercase", "make_ascii_lowercase", "split_off"];

const PUTS: [&str; 6] = ["push", "push_back", "push_front", "insert", "extend", "append"];

const RUNS: [&str; 4] = ["Vec", "List", "VecDeque", "Deque"];

const SETS: [&str; 3] = ["HashSet", "BTreeSet", "Set"];

const MAPS: [&str; 3] = ["HashMap", "BTreeMap", "Map"];

pub fn owns_its_text(method: &str) -> bool {
    for one in OWNS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn views_what_it_is_called_on(method: &str) -> bool {
    for one in VIEWS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn hands_back_an_element(method: &str) -> bool {
    for one in ELEMENTS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn changes_its_text(method: &str) -> bool {
    for one in CHANGES.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn puts_its_argument(method: &str) -> bool {
    for one in PUTS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn is_a_map_name(name: &str) -> bool {
    for one in MAPS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

pub fn is_a_container_name(callee: &str) -> bool {
    let name = last_segment(callee);
    for one in RUNS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    for one in SETS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    is_a_map_name(&name)
}

pub fn plain_string(names: &winnow_grammar::InternerContext, ty: &Type) -> bool { names.resolve(ty.name) == "String" && ty.generics.is_empty() && !ty.is_view && !ty.is_tuple && !ty.is_slice && (*ty.code).is_none() }

pub fn container_of(names: &winnow_grammar::InternerContext, ty: &Type) -> Option<String> {
    if ty.is_view || ty.is_nullable || ty.is_tuple || (*ty.code).is_some() { return None; }
    let name = last_segment(names.resolve(ty.name));
    if is_a_container_name(&name) { return Some(name); }
    None
}


// --- touch.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reached {
    pub kind: String,
    pub named: Option<String>,
    pub unknown: bool,
    pub write: bool,
}

impl Reached {
    pub fn might_be_same(&self, other: &Reached) -> bool {
        if family(&self.kind) != family(&other.kind) { return false; }
        if self.unknown || other.unknown { return true; }
        let mine = match match self.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        let theirs = match match other.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        mine == theirs
    }
    pub fn conflicts_with(&self, other: &Reached) -> bool { (self.write || other.write) && self.might_be_same(other) }
}

fn family(kind: &str) -> String {
    if kind == "stderr" { return String::from("stdout"); }
    kind.to_owned()
}

pub fn touches_of(unknown: &collections::BTreeMap<String, bool>, outside: &collections::BTreeMap<String, Vec<Touch>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>) -> collections::BTreeMap<String, Vec<Touch>> {
    let mut known: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for (name, lost) in unknown.iter() {
        let lost = nikaia_std::num::value(lost);
        known.insert(name.to_owned(), !lost);
    }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in calls.iter() {
            let holds = nikaia_std::index::or(*nikaia_std::index::get(&known, name), || false);
            if !holds { continue; }
            let mut reaches_unknown = false;
            for callee in called.iter() {
                let theirs = nikaia_std::index::or(*nikaia_std::index::get(&known, callee), || false);
                if !theirs { reaches_unknown = true; }
            }
            if reaches_unknown {
                known.insert(name.to_owned(), false);
                changed = true;
            }
        }
    }
    let mut settled: collections::BTreeMap<String, Vec<Touch>> = collections::BTreeMap::new();
    for (name, holds) in known.iter() {
        let holds = nikaia_std::num::value(holds);
        if !holds { continue; }
        let mut found: Vec<Touch> = vec![];
        let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
        let mut todo: Vec<String> = vec![name.to_owned()];
        while !todo.is_empty() {
            let here = match todo.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
            if seen.contains(&here) { continue; }
            seen.insert(here.to_owned());
            for touch in nikaia_std::index::or(match *nikaia_std::index::get(&outside, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()) { found.push(touch); }
            for callee in nikaia_std::index::or(match *nikaia_std::index::get(&calls, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into()) { todo.push(callee); }
        }
        settled.insert(name.to_owned(), found);
    }
    settled
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reach {
    pub unknown: bool,
    pub outside: Vec<Touch>,
    pub calls: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TouchGraph {
    pub methods: collections::BTreeMap<String, MethodsCalled>,
    pub reaches: collections::BTreeMap<String, Reach>,
}

pub fn unit_touches(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger, graph: &mut TouchGraph) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                let mut reach = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                reached_by(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut reach);
                methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
                graph.reaches.insert(key, reach);
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, .. } => {
                            let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            let mut reach = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                            reached_by(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut reach);
                            methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
                            graph.reaches.insert(key, reach);
                        },
                        _ => { },
                    }
                }
            },
            Item::Grammar(def) => {
                let mut whole = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                for rule in def.rules.iter() {
                    for alt in rule.alts.iter() {
                        let action = match alt.action.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                        reached_by(&seen_in(action, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut whole);
                    }
                }
                rules_into(def, names, &whole, own, library, graph);
            },
            _ => { },
        }
    }
}

pub fn touches_of_graph(graph: &TouchGraph) -> collections::BTreeMap<String, Vec<Touch>> {
    let mut unknown: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    let mut outside: collections::BTreeMap<String, Vec<Touch>> = collections::BTreeMap::new();
    let mut calls: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, reach) in graph.reaches.iter() {
        unknown.insert(name.to_owned(), reach.unknown);
        outside.insert(name.to_owned(), reach.outside.to_owned());
        calls.insert(name.to_owned(), reach.calls.to_owned());
    }
    touches_of(&unknown, &outside, &calls)
}

fn rules_into(def: &GrammarDef, names: &winnow_grammar::InternerContext, whole: &Reach, own: &Ledger, library: &Ledger, graph: &mut TouchGraph) {
    let named = names.resolve(def.name).to_owned();
    for rule in def.rules.iter() {
        if !rule.is_entry { continue; }
        let key = format!("{}::{}", named, names.resolve(rule.name));
        let mut reach = Reach { unknown: whole.unknown, outside: whole.outside.to_owned(), calls: whole.calls.to_owned() };
        methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
        graph.reaches.insert(key, reach);
    }
}

fn reached_by(seen: &[Seen], program: &Program, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, reach: &mut Reach) {
    for one in seen.iter() {
        match one {
            Seen::Call { name, .. } => { reached_call((callee_named(names, name.to_owned(), own, library, &program.items)).as_ref(), library, reach); },
            Seen::Spawn { .. } => { reach.unknown = true; },
            Seen::Opaque { .. } => { reach.unknown = true; },
            _ => { },
        }
    }
}

fn reached_call(callee: Option<&Callee>, library: &Ledger, reach: &mut Reach) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => { reach.calls.insert(name.to_owned()); },
        Callee::Library { key, .. } => { absorb(*nikaia_std::index::get(&library.functions, key), reach); },
        Callee::Opaque(_) => { reach.unknown = true; },
        _ => { },
    }
}

fn methods_reach(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, reach: &mut Reach) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unseen { reach.unknown = true; }
    for callee in known.resolved.iter() { if own.functions.contains_key(callee) { reach.calls.insert(callee.to_owned()); } else { absorb(*nikaia_std::index::get(&library.functions, callee), reach); } }
}

fn absorb(contract: Option<&FnContract>, reach: &mut Reach) {
    if !touches_said(contract) {
        reach.unknown = true;
        return;
    }
    let known = match contract { Some(__nikaia_value) => __nikaia_value, None => return };
    for touch in known.touches.iter() { if touch.parameter.is_some() { reach.unknown = true; } else if !holds_touch(&reach.outside, touch) { reach.outside.push(touch.clone()); } }
}

fn touches_said(contract: Option<&FnContract>) -> bool {
    let known = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    known.touches_known
}

fn holds_touch(touches: &[Touch], touch: &Touch) -> bool {
    for one in touches.iter() { if one.kind == touch.kind && one.write == touch.write { return true; } }
    false
}


// --- traits.nika ---

pub fn check_impls(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Impl { trait_name, target, methods } => {
                let trait_name = *trait_name;
                let written_trait = match trait_name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let named = names.resolve(written_trait).to_owned();
                for one in receivers(names, items, &named, methods) { found.push(one); }
                if (named == "Eq" || named == "Ord") && !own.traits.contains_key(&named) {
                    let target_text = names.resolve(target.name).to_owned();
                    for one in language_trait(names, own, &named, &target_text, methods, item.span.clone()) { found.push(one); }
                    continue;
                }
                if !own.traits.contains_key(&named) { continue; }
                let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.traits, &named) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || collections::BTreeSet::new().into());
                let target_name = names.resolve(target.name).to_owned();
                let mut given: Vec<String> = vec![];
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, .. } => {
                            let name = *name;
                            let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                            let written = names.resolve(symbol).to_owned();
                            given.push(written.to_owned());
                            if !declared.contains(&written) {
                                found.push(not_in_the_trait(&named, &target_name, &written, method.span.clone()));
                                continue;
                            }
                            for one in pausing(own, &named, &target_name, &written, method.span.clone()) { found.push(one); }
                        },
                        _ => { },
                    }
                }
                let mut missing: Vec<String> = vec![];
                for wanted in declared.iter() { if !given.contains(&wanted.to_owned()) { missing.push(wanted.to_owned()); } }
                if !missing.is_empty() { found.push(incomplete(&named, &target_name, &missing, item.span.clone())); }
            },
            _ => { },
        }
    }
    found
}

fn language_trait(names: &winnow_grammar::InternerContext, own: &Ledger, trait_name: &str, target: &str, methods: &[Spanned<Item>], span: Span) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    let mut wanted: String = String::from("eq");
    if trait_name == "Ord" { wanted = "compare".to_owned(); }
    let mut given = false;
    for method in methods.iter() {
        match &method.node {
            Item::Fn { name, .. } => {
                let name = *name;
                let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let written = names.resolve(symbol).to_owned();
                if written == wanted { given = true; } else { found.push(not_in_the_trait(trait_name, target, &written, method.span.clone())); }
            },
            _ => { },
        }
    }
    if !given {
        let missing: Vec<String> = vec![wanted.to_owned()];
        found.push(incomplete(trait_name, target, &missing, span.clone()));
    }
    let key = format!("{}::{}", target, wanted);
    if own.functions.contains_key(&key) {
        let contract = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || FnContract::empty());
        if !contract.sync_claim.is_sync() {
            let notes: Vec<String> = vec![format!("`{}` is the language's, and an operator such as `==` or `<` cannot wait for anything.", trait_name)];
            found.push(refusal("NK1129", span, format!("`{}` can pause, but `{}`'s `{}` is `sync`.", key, trait_name, wanted), notes, String::from("Take out the part that waits (a read, a lock, a call that pauses) and compare what is already in hand.")));
        }
    }
    found
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Wanted {
    known: bool,
    receiver: Option<Receiver>,
}

fn receivers(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], trait_name: &str, methods: &[Spanned<Item>]) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for method in methods.iter() {
        match &method.node {
            Item::Fn { name, receiver, .. } => {
                let name = *name;
                let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let written = names.resolve(symbol).to_owned();
                let wanted = wanted_receiver(names, items, trait_name, &written);
                if !wanted.known || same_receiver(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, match receiver {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }) { continue; }
                let theirs = receiver_text(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                });
                let ours = receiver_text(match receiver {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                });
                let notes: Vec<String> = vec![String::from("Callers go through the trait, so they pass the value the way the trait declares.")];
                found.push(refusal("NK1196", method.span.clone(), format!("`{}`'s `{}` takes {}, but this one takes {}.", trait_name, written, theirs, ours), notes, format!("Take it as {}, like `{}` declares.", theirs, trait_name)));
            },
            _ => { },
        }
    }
    found
}

fn wanted_receiver(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], trait_name: &str, method: &str) -> Wanted {
    for item in items.iter() {
        match &item.node {
            Item::Trait { name, methods, .. } => {
                let name = *name;
                if names.resolve(name) == trait_name {
                    for declared in methods.iter() {
                        if names.resolve(declared.node.name) == method {
                            return Wanted { known: true, receiver: match declared.node.receiver.as_ref() {
                                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                                None => None,
                            } };
                        }
                    }
                    return Wanted { known: false, receiver: None };
                }
            },
            _ => { },
        }
    }
    let shared = Receiver { is_ref: true, is_mut: false };
    let changed = Receiver { is_ref: true, is_mut: true };
    if trait_name == "Error" && method == "message" || trait_name == "Eq" && method == "eq" || trait_name == "Ord" && method == "compare" { return Wanted { known: true, receiver: Some(shared) }; }
    if trait_name == "Drop" && method == "drop" || trait_name == "Cleanup" && method == "cleanup" { return Wanted { known: true, receiver: Some(changed) }; }
    Wanted { known: false, receiver: None }
}

fn same_receiver(a: Option<Receiver>, b: Option<Receiver>) -> bool {
    if a.is_none() || b.is_none() { return a.is_none() && b.is_none(); }
    let one = nikaia_std::index::or(a, || Receiver { is_ref: false, is_mut: false });
    let other = nikaia_std::index::or(b, || Receiver { is_ref: false, is_mut: false });
    one.is_ref == other.is_ref && one.is_mut == other.is_mut
}

fn receiver_text(receiver: Option<Receiver>) -> &'static str {
    let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => return "no `self`" };
    if taken.is_ref && taken.is_mut { return "`ref mut self`"; }
    if taken.is_ref { return "`ref self`"; }
    if taken.is_mut { return "`mut self`"; }
    "`self`"
}

fn pausing(own: &Ledger, trait_name: &str, target: &str, method: &str, span: Span) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    let implemented = format!("{}::{}", target, method);
    let declaring = format!("{}::{}", trait_name, method);
    if !own.functions.contains_key(&implemented) || !own.functions.contains_key(&declaring) { return found; }
    let contract = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &implemented) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &declaring) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    if declared.sync_claim.is_sync() && !contract.sync_claim.is_sync() {
        let notes: Vec<String> = vec![String::from("`sync` in a trait promises that every implementation never pauses. (The opposite is fine: a body that never pauses can implement a method that may.)")];
        found.push(refusal("NK1129", span.clone(), format!("`{}::{}` can pause, but `{}` declares `{}` as `sync`.", target, method, trait_name, method), notes, format!("Remove `sync` from `{}`'s `{}`, or take out what pauses in the body, such as a file read, a sleep or a `.join()`.", trait_name, method)));
    }
    if declared.fails_with.is_empty() && !contract.fails_with.is_empty() {
        let notes: Vec<String> = vec![String::from("A trait method without `throws` promises that no implementation fails. (The opposite is fine: a body that can't fail can implement one with `throws`.)")];
        found.push(refusal("NK1140", span, format!("`{}::{}` can fail, but `{}` declares `{}` without `throws`.", target, method, trait_name, method), notes, format!("Add `throws` to `{}`'s `{}`, or handle the failure in the body with `catch`.", trait_name, method)));
    }
    found
}

fn not_in_the_trait(trait_name: &str, target: &str, method: &str, span: Span) -> Finding {
    let notes: Vec<String> = vec![format!("`impl {} for {}` can only hold `{}`'s methods. The type's own methods go in a separate `impl {}`.", trait_name, target, trait_name, target)];
    refusal("NK1130", span, format!("`{}` has no method called `{}`.", trait_name, method), notes, format!("Move it to `impl {}`, or add `{}` to `{}` if every type that implements it should have one.", target, method, trait_name))
}

fn incomplete(trait_name: &str, target: &str, missing: &[String], span: Span) -> Finding {
    let mut listed: String = String::from("");
    for at in 0..missing.len() as i64 {
        if at > 0 { listed.push_str(", "); }
        let one = nikaia_std::index::get(&missing, (at) as usize);
        let quoted = format!("`{}`", one);
        listed.push_str(&quoted);
    }
    let pronoun = if missing.len() == 1 { "it" } else { "them" };
    let notes: Vec<String> = vec![String::from("A trait promises that all its methods are there, which is what lets code call them through a bound.")];
    refusal("NK1130", span, format!("`{}` is missing {} from `{}`.", target, listed, trait_name), notes, format!("Add {} to this `impl`, or remove {} from `{}`.", listed, pronoun, trait_name))
}


// --- tree_build.nika ---

#[derive(Debug, Clone, PartialEq)]
pub enum Postfix {
    Field(winnow_grammar::Symbol),
    SafeField(winnow_grammar::Symbol),
    SafeMethod(winnow_grammar::Symbol, Vec<Expr>, Vec<ConfigArg>),
    Method(winnow_grammar::Symbol, Vec<Expr>, Vec<ConfigArg>),
    Index(Expr),
    IndexFrom(Expr, winnow_grammar::Symbol),
    With(Vec<FieldInit>, u32),
}

pub fn split_mut(params: &[(bool, winnow_grammar::Symbol)]) -> (Vec<winnow_grammar::Symbol>, Vec<winnow_grammar::Symbol>) {
    let mut names: Vec<winnow_grammar::Symbol> = vec![];
    let mut mutable: Vec<winnow_grammar::Symbol> = vec![];
    for param in params.iter() {
        names.push(param.1);
        if param.0 { mutable.push(param.1); }
    }
    (names, mutable)
}

pub fn params_of(receiver: Option<Receiver>, args: Vec<FnArg>, zone: Option<ConfigZone>) -> FnParams {
    if zone.is_none() { return FnParams { receiver, args, config: vec![], spread: None }; }
    match nikaia_std::index::or(zone, || ConfigZone::Options(vec![])) {
        ConfigZone::Options(options) => { return FnParams { receiver, args, config: options, spread: None }; },
        ConfigZone::Spread(name) => { return FnParams { receiver, args, config: vec![], spread: Some(name) }; },
    }
}

pub fn guarded(jump: Stmt, cond: Expr, span: Span, id: node_id::NodeId) -> Stmt { Stmt::Expr(Expr::If { cond: Box::new(cond), then_branch: Block { stmts: vec![Spanned { node: jump, span, doc: None, attributes: vec![] }] }, else_branch: None, id }) }

pub fn fold_binary(head: Expr, tail: Vec<(BinaryOp, Expr, Span)>, first: u32) -> Expr {
    let mut lhs = head;
    let mut next = first;
    for step in tail.into_iter() {
        lhs = Expr::Binary { op: step.0, lhs: Box::new(lhs), rhs: Box::new(step.1), span: step.2, grouped: false, id: numbered_id(next) };
        next = next + 1u32;
    }
    lhs
}

pub fn grouped(e: Expr) -> Expr {
    match e {
        Expr::Binary { op, lhs, rhs, span, id, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            return Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs), span, grouped: true, id };
        },
        other => { return other; },
    }
}

pub fn fold_postfix(base: Expr, tail: Vec<Postfix>, first: u32) -> Expr {
    let mut recv = base;
    let mut next = first;
    for step in tail.into_iter() {
        let id = numbered_id(next);
        recv = match step {
            Postfix::Field(name) => Expr::Field { base: Box::new(recv), name, id },
            Postfix::SafeField(name) => Expr::SafeField { base: Box::new(recv), name, id },
            Postfix::SafeMethod(method, args, config) => Expr::SafeMethod { receiver: Box::new(recv), method, args, config, id },
            Postfix::Method(method, args, config) => Expr::MethodCall { receiver: Box::new(recv), method, args, config, id },
            Postfix::Index(index) => Expr::Index { base: Box::new(recv), index: Box::new(index), id },
            Postfix::IndexFrom(start, len) => Expr::Index { base: Box::new(recv.clone()), index: Box::new(Expr::Range { start: Box::new(start), end: Box::new(Expr::MethodCall { receiver: Box::new(recv), method: len, args: vec![], config: vec![], id: numbered_id(next + 1u32) }), inclusive: false, id: numbered_id(next + 2u32) }), id },
            Postfix::With(fields, at) => Expr::With { base: Box::new(recv), fields, at, id },
        };
        next = next + 3u32;
    }
    recv
}


// --- trust.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Wrote {
    Anywhere,
    TheFilesystemRoot,
}

pub fn spelled(wrote: Wrote) -> String {
    match wrote {
        Wrote::Anywhere => String::from("Anywhere"),
        Wrote::TheFilesystemRoot => String::from("Dir(\"/\") - which is every directory"),
    }
}

pub fn written_root(names: &winnow_grammar::InternerContext, arg: &Expr) -> Option<Wrote> {
    match arg {
        Expr::Path(segments, _) => if ends_with_variant(names, segments, "Anywhere") { Some(Wrote::Anywhere) } else { None },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); the_whole_filesystem(names, func, args) },
        _ => None,
    }
}

fn the_whole_filesystem(names: &winnow_grammar::InternerContext, func: &Expr, args: &[Expr]) -> Option<Wrote> {
    let is_dir = match func {
        Expr::Path(segments, _) => ends_with_variant(names, segments, "Dir"),
        _ => false,
    };
    if !is_dir || args.is_empty() { return None; }
    match nikaia_std::index::get(&args, 0) {
        Expr::LitStr { text, .. } => if text == "/" { Some(Wrote::TheFilesystemRoot) } else { None },
        _ => None,
    }
}

fn ends_with_variant(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol], variant: &str) -> bool {
    let n = segments.len() as i64;
    n >= 2 && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 2))) == "Root" && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 1))) == variant
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reason {
    pub source: String,
    pub untrusted: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Place {
    pub line: i64,
    pub column: i64,
    pub entry: String,
    pub wrote: Wrote,
}

pub fn render(untrusted: bool, reasons: &[Reason], places: &[Place], path: &str) -> String {
    let mut out = format!("input provenance: {}\n", provenance(untrusted));
    if reasons.is_empty() { out.push_str("    no source is read, so nothing entered from outside\n"); }
    for reason in reasons.iter() { out.push_str(&format!("    {} is {}\n", reason.source, provenance(reason.untrusted))); }
    let hash = if untrusted { "keyed, per-process random seed - key choice cannot be aimed at the table" } else { "fast, fixed seed - no adversary chooses these keys" };
    out.push_str(&format!("hash for a map keyed by the input: {}\n", hash));
    out.push_str("file access with no root to check against:\n");
    if places.is_empty() { out.push_str("    none - every path here names a directory it may not leave\n"); }
    for place in places.iter() { out.push_str(&format!("    {}:{}:{}  {} writes {}\n", path, place.line, place.column, place.entry, spelled(place.wrote))); }
    out
}

fn provenance(untrusted: bool) -> &'static str { if untrusted { "untrusted" } else { "trusted" } }


#[derive(Debug, Clone, PartialEq, Eq)]
struct KeyDeps {
    known: bool,
    ids: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapEnv {
    sources: collections::BTreeSet<String>,
    own: collections::BTreeSet<String>,
    privates: collections::BTreeMap<winnow_grammar::Symbol, i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapClasses {
    parent: collections::BTreeMap<String, String>,
    poisoned: collections::BTreeSet<String>,
    lets: Vec<i64>,
    slots: Vec<String>,
    unread: bool,
    escaped: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MapPlan {
    pub lets: collections::BTreeSet<i64>,
    pub slots: collections::BTreeSet<String>,
    pub escaped: collections::BTreeSet<i64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct MapMade {
    at: i64,
    name: winnow_grammar::Symbol,
    id: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapKept {
    id: i64,
    deps: KeyDeps,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapWalk {
    nodes: Vec<String>,
    ret: String,
    scopes: Vec<collections::BTreeMap<winnow_grammar::Symbol, i64>>,
    given: Vec<Vec<KeyDeps>>,
    made: Vec<MapMade>,
    kept: Vec<MapKept>,
    escapes: collections::BTreeSet<i64>,
    bound: collections::BTreeMap<winnow_grammar::Symbol, i64>,
    unread: bool,
}

fn tm_never() -> KeyDeps { KeyDeps { known: false, ids: vec![] } }

fn tm_nothing() -> KeyDeps { KeyDeps { known: true, ids: vec![] } }

fn tm_reading(id: i64) -> KeyDeps { KeyDeps { known: true, ids: vec![id] } }

fn tm_join(a: &KeyDeps, b: &KeyDeps) -> KeyDeps {
    if !a.known || !b.known { return tm_never(); }
    let mut ids: Vec<i64> = vec![];
    for id in a.ids.iter() {
        let id = nikaia_std::num::value(id);
        ids.push(id);
    }
    for id in b.ids.iter() {
        let id = nikaia_std::num::value(id);
        ids.push(id);
    }
    KeyDeps { known: true, ids }
}

fn mc_find(classes: &MapClasses, node: &str) -> String {
    let mut at: String = node.to_owned();
    let mut moving = true;
    while moving {
        let up = classes.parent.get(&at);
        if up.is_none() { moving = false; } else {
            let next = nikaia_std::index::or(up, || "").to_owned();
            if next == at { moving = false; } else { at = next; }
        }
    }
    at
}

fn mc_union(classes: &mut MapClasses, a: &str, b: &str) {
    let ra = mc_find(&classes, a);
    let rb = mc_find(&classes, b);
    if ra != rb { classes.parent.insert(ra, rb); }
}

fn mc_poison(classes: &mut MapClasses, node: &str) { classes.poisoned.insert(node.to_owned()); }

fn mc_poison_function(classes: &mut MapClasses, name: &str, arity: i64) {
    let ret = format!("r:{}", name);
    mc_poison(classes, &ret);
    let mut at: i64 = 0;
    while at < arity {
        let param = format!("p:{}:{}", name, at);
        mc_poison(classes, &param);
        at = at + 1;
    }
}

pub fn trusted_maps(program: &Program, words: &winnow_grammar::InternerContext, library: &Ledger) -> MapPlan {
    let mut env = MapEnv { sources: collections::BTreeSet::new(), own: collections::BTreeSet::new(), privates: collections::BTreeMap::new() };
    for (key, contract) in library.functions.iter() {
        let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => continue };
        if provenance == Provenance::Untrusted {
            let parts: Vec<&str> = key.split("::").collect::<Vec<_>>();
            env.sources.insert((*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned());
        }
    }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, generics, args, is_public, is_extern, .. } => {
                let is_extern = *is_extern; let is_public = *is_public; let name = *name;
                tm_remember(name, words, &mut env.own);
                if !is_public && !is_extern && generics.is_empty() {
                    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                    env.privates.insert(symbol, args.len() as i64);
                }
            },
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, .. } => { let name = *name; tm_remember(name, words, &mut env.own); },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    let mut classes = MapClasses { parent: collections::BTreeMap::new(), poisoned: collections::BTreeSet::new(), lets: vec![], slots: vec![], unread: false, escaped: vec![] };
    let mut counter = 0;
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, generics, args, body, is_public, is_extern, .. } => {
                let is_extern = *is_extern; let is_public = *is_public; let name = *name;
                let mut fname: String = String::from("fn");
                let mut alone = false;
                if !is_public && !is_extern && generics.is_empty() {
                    let symbol = name;
                    if symbol.is_some() {
                        fname = words.resolve(match symbol { Some(__nikaia_value) => __nikaia_value, None => continue }).to_owned();
                        alone = true;
                    }
                }
                if !alone {
                    counter = counter + 1;
                    fname = format!("#{}", counter);
                }
                tm_walk_function(&fname, alone, args, body, words, library, &env, &mut classes);
            },
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { args, body, .. } => {
                            counter = counter + 1;
                            let fname = format!("#{}", counter);
                            tm_walk_function(&fname, false, args, body, words, library, &env, &mut classes);
                        },
                        _ => { },
                    }
                }
            },
            Item::Struct { .. } => { },
            Item::Enum { .. } => { },
            Item::Extern { .. } => { },
            Item::Import { .. } => { },
            _ => { classes.unread = true; },
        }
    }
    if classes.unread {
        let every = classes.slots.to_owned();
        for slot in every.iter() { mc_poison(&mut classes, slot); }
    }
    let mut bad: collections::BTreeSet<String> = collections::BTreeSet::new();
    for node in classes.poisoned.iter() { bad.insert(mc_find(&classes, node)); }
    let mut plan = MapPlan { lets: collections::BTreeSet::new(), slots: collections::BTreeSet::new(), escaped: collections::BTreeSet::new() };
    for at in classes.escaped.iter() {
        let at = nikaia_std::num::value(at);
        plan.escaped.insert(at);
    }
    for at in classes.lets.iter() {
        let at = nikaia_std::num::value(at);
        let node = format!("l:{}", at);
        if !bad.contains(&mc_find(&classes, &node)) { plan.lets.insert(at); }
    }
    for slot in classes.slots.iter() { if !bad.contains(&mc_find(&classes, slot)) { plan.slots.insert(slot.to_owned()); } }
    plan
}

fn tm_remember(name: Option<winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, own: &mut collections::BTreeSet<String>) {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    own.insert(words.resolve(symbol).to_owned());
}

#[allow(clippy::too_many_arguments)]
fn tm_walk_function(fname: &str, alone: bool, args: &[FnArg], body: &Block, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, classes: &mut MapClasses) {
    let ret = format!("r:{}", fname);
    let mut first: collections::BTreeMap<winnow_grammar::Symbol, i64> = collections::BTreeMap::new();
    let mut walk = MapWalk { nodes: vec![], ret: ret.to_owned(), scopes: vec![], given: vec![], made: vec![], kept: vec![], escapes: collections::BTreeSet::new(), bound: collections::BTreeMap::new(), unread: false };
    if alone { classes.slots.push(ret.to_owned()); } else { mc_poison(classes, &ret); }
    let mut at = 0;
    for arg in args.iter() {
        let node = format!("p:{}:{}", fname, at);
        if alone { classes.slots.push(node.to_owned()); } else { mc_poison(classes, &node); }
        let id = walk.given.len() as i64;
        walk.given.push(vec![tm_never()]);
        walk.nodes.push(node.to_owned());
        let name = arg.name.to_owned();
        walk.made.push(MapMade { at: -1, name: name.to_owned(), id });
        tm_count_binding(name, &mut walk);
        first.insert(name.to_owned(), id);
        at = at + 1;
    }
    walk.scopes.push(first);
    tm_walk_block(body, words, library, env, classes, &mut walk);
    if walk.unread {
        classes.unread = true;
        for made in walk.made.iter() {
            let made = *made;
            if made.at >= 0 && walk.escapes.contains(&made.id) { classes.escaped.push(made.at); }
        }
        for node in walk.nodes.iter() { mc_poison(classes, node); }
        mc_poison(classes, &ret);
        return;
    }
    let trusted = tm_trusted_bindings(&walk.given);
    for kept in walk.kept.iter() {
        let mut keys_trusted = kept.deps.known;
        for dep in kept.deps.ids.iter() {
            let dep = nikaia_std::num::value(dep);
            if !trusted.contains(&dep) { keys_trusted = false; }
        }
        if !keys_trusted { mc_poison(classes, nikaia_std::index::get(&walk.nodes, nikaia_std::index::at(kept.id))); }
    }
    for id in walk.escapes.iter() {
        let id = nikaia_std::num::value(id);
        mc_poison(classes, nikaia_std::index::get(&walk.nodes, nikaia_std::index::at(id)));
    }
    for made in walk.made.iter() {
        let made = *made;
        if nikaia_std::index::or(walk.bound.get(&made.name), || 0) != 1 { mc_poison(classes, nikaia_std::index::get(&walk.nodes, nikaia_std::index::at(made.id))); }
        if made.at >= 0 {
            classes.lets.push(made.at);
            if walk.escapes.contains(&made.id) { classes.escaped.push(made.at); }
        }
    }
}

fn tm_trusted_bindings(given: &[Vec<KeyDeps>]) -> collections::BTreeSet<i64> {
    let mut trusted: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut id: i64 = 0;
    while id < given.len() as i64 {
        let mut every = true;
        for one in (*nikaia_std::index::get(&given, nikaia_std::index::at(id))).iter() { if !one.known { every = false; } }
        if every { trusted.insert(id); }
        id = id + 1;
    }
    let mut settled = false;
    while !settled {
        let mut now: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for id in trusted.iter() {
            let id = nikaia_std::num::value(id);
            now.insert(id);
        }
        let mut next: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for id in now.iter() {
            let id = nikaia_std::num::value(id);
            let mut holds = true;
            for one in (*nikaia_std::index::get(&given, nikaia_std::index::at(id))).iter() {
                if !one.known { holds = false; }
                for dep in one.ids.iter() {
                    let dep = nikaia_std::num::value(dep);
                    if !now.contains(&dep) { holds = false; }
                }
            }
            if holds { next.insert(id); }
        }
        if (next.len() as i64) == now.len() as i64 { settled = true; }
        trusted = next;
    }
    trusted
}

fn tm_bind(name: winnow_grammar::Symbol, given: &KeyDeps, node: &str, walk: &mut MapWalk) -> i64 {
    let id = walk.given.len() as i64;
    walk.nodes.push(node.to_owned());
    walk.given.push(vec![KeyDeps { known: given.known, ids: given.ids.to_owned() }]);
    tm_count_binding(name, walk);
    let last = walk.scopes.len() as i64 - 1;
    walk.scopes[nikaia_std::index::at(last)].insert(name.to_owned(), id);
    id
}

fn tm_opaque(name: winnow_grammar::Symbol, walk: &mut MapWalk) {
    tm_count_binding(name, walk);
    let last = walk.scopes.len() as i64 - 1;
    walk.scopes[nikaia_std::index::at(last)].insert(name.to_owned(), -1);
}

fn tm_count_binding(name: winnow_grammar::Symbol, walk: &mut MapWalk) {
    let before = nikaia_std::index::or(walk.bound.get(&name), || 0);
    walk.bound.insert(name.to_owned(), before + 1);
}

fn tm_resolve(name: winnow_grammar::Symbol, walk: &MapWalk) -> i64 {
    let mut at = walk.scopes.len() as i64;
    while at > 0 {
        at = at - 1;
        let found = (*nikaia_std::index::get(&walk.scopes, nikaia_std::index::at(at))).get(&name);
        if found.is_some() { return nikaia_std::index::or(found, || -2); }
    }
    -2
}

fn tm_walk_block(block: &Block, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, classes: &mut MapClasses, walk: &mut MapWalk) {
    walk.scopes.push(collections::BTreeMap::new());
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names, value, .. } => {
                let given = tm_deps_of(value, words, library, env, &walk);
                if names.len() == 1 {
                    let name = (*nikaia_std::index::get(&names, 0)).to_owned();
                    let node = format!("l:{}", stmt.span.start);
                    if is_a_map_made(value, words) { tm_walk_expr(value, words, library, env, classes, walk); } else { tm_flow(&node, value, words, library, env, classes, walk); }
                    let id = tm_bind(name, &given, &node, walk);
                    walk.made.push(MapMade { at: stmt.span.start as i64, name: name.to_owned(), id });
                } else {
                    tm_walk_expr(value, words, library, env, classes, walk);
                    for one in names.iter() {
                        let one = *one;
                        tm_opaque(one.to_owned(), walk);
                    }
                }
            },
            Stmt::Assign { target, value, .. } => {
                tm_walk_expr(target, words, library, env, classes, walk);
                tm_walk_expr(value, words, library, env, classes, walk);
                match target {
                    Expr::Variable(name, _) => {
                        let name = *name;
                        let given = tm_deps_of(value, words, library, env, &walk);
                        let id = tm_resolve(name.to_owned(), &walk);
                        if id >= 0 { walk.given[nikaia_std::index::at(id)].push(given); }
                    },
                    _ => { },
                }
            },
            Stmt::For { bindings, iter, body, .. } => {
                match iter {
                    Expr::Variable(name, _) => {
                        let name = *name;
                        let id = tm_resolve(name.to_owned(), &walk);
                        if id >= 0 { walk.kept.push(MapKept { id, deps: tm_nothing() }); }
                    },
                    _ => { tm_walk_expr(iter, words, library, env, classes, walk); },
                }
                let given = tm_deps_of(iter, words, library, env, &walk);
                walk.scopes.push(collections::BTreeMap::new());
                for one in bindings.iter() {
                    let one = *one;
                    let node = format!("b:{}", walk.given.len() as i64);
                    tm_bind(one.to_owned(), &given, &node, walk);
                }
                tm_walk_block(body, words, library, env, classes, walk);
                walk.scopes.pop();
            },
            Stmt::While { cond, body } => {
                tm_walk_expr(cond, words, library, env, classes, walk);
                tm_walk_block(body, words, library, env, classes, walk);
            },
            Stmt::Expr(value) => { tm_walk_expr(value, words, library, env, classes, walk); },
            Stmt::Return(value) => {
                if value.is_some() {
                    let ret = walk.ret.to_owned();
                    tm_flow(&ret, match value { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, classes, walk);
                }
            },
            _ => { walk.unread = true; },
        }
    }
    walk.scopes.pop();
}

fn tm_private_callee(func: &Expr, env: &MapEnv, walk: &MapWalk) -> Option<winnow_grammar::Symbol> {
    match func {
        Expr::Variable(name, _) => {
            let name = *name;
            if tm_resolve(name.to_owned(), walk) == -2 && env.privates.contains_key(&name) { Some(name.to_owned()) } else { None }
        },
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn tm_call_args(callee: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, classes: &mut MapClasses, walk: &mut MapWalk) {
    let arity = nikaia_std::index::or(env.privates.get(&callee), || -1);
    let written = words.resolve(callee);
    if arity != args.len() as i64 {
        mc_poison_function(classes, written, arity);
        for a in args.iter() { tm_walk_expr(a, words, library, env, classes, walk); }
    } else {
        let mut at = 0;
        for a in args.iter() {
            let param = format!("p:{}:{}", written, at);
            tm_flow(&param, a, words, library, env, classes, walk);
            at = at + 1;
        }
    }
    for c in config.iter() { tm_walk_expr(&c.value, words, library, env, classes, walk); }
}

fn tm_flow(sink: &str, value: &Expr, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, classes: &mut MapClasses, walk: &mut MapWalk) {
    match value {
        Expr::Variable(name, _) => {
            let name = *name;
            let id = tm_resolve(name.to_owned(), &walk);
            if id >= 0 {
                let node = (*nikaia_std::index::get(&walk.nodes, nikaia_std::index::at(id))).to_owned();
                mc_union(classes, sink, &node);
            } else {
                mc_poison(classes, sink);
                tm_walk_expr(value, words, library, env, classes, walk);
            }
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            let found = tm_private_callee(func, env, &walk);
            if found.is_some() {
                let callee = match found { Some(__nikaia_value) => __nikaia_value, None => return };
                let ret = format!("r:{}", words.resolve(callee));
                mc_union(classes, sink, &ret);
                tm_call_args(callee, args, config, words, library, env, classes, walk);
            } else {
                mc_poison(classes, sink);
                tm_walk_expr(value, words, library, env, classes, walk);
            }
        },
        _ => {
            mc_poison(classes, sink);
            tm_walk_expr(value, words, library, env, classes, walk);
        },
    }
}

fn map_named(receiver: &Expr, words: &winnow_grammar::InternerContext, walk: &MapWalk) -> i64 {
    match receiver {
        Expr::Variable(name, _) => {
            let name = *name;
            let id = tm_resolve(name.to_owned(), walk);
            if id >= 0 { id } else { -1 }
        },
        _ => -1,
    }
}

fn tm_walk_expr(expr: &Expr, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, classes: &mut MapClasses, walk: &mut MapWalk) {
    match expr {
        Expr::Block(b, _) => { tm_walk_block(b, words, library, env, classes, walk); },
        Expr::Unsafe(b, _) => { tm_walk_block(b, words, library, env, classes, walk); },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            tm_walk_expr(cond, words, library, env, classes, walk);
            tm_walk_block(then_branch, words, library, env, classes, walk);
            if else_branch.is_some() { tm_walk_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, classes, walk); }
        },
        Expr::MethodCall { receiver, method, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let id = map_named(receiver, words, &walk);
            if id >= 0 && words.resolve(method) != "clone" {
                let mut all = tm_nothing();
                for a in args.iter() { all = tm_join(&all, &tm_deps_of(a, words, library, env, &walk)); }
                walk.kept.push(MapKept { id, deps: all });
            } else { tm_walk_expr(receiver, words, library, env, classes, walk); }
            for a in args.iter() { tm_walk_expr(a, words, library, env, classes, walk); }
            for c in config.iter() { tm_walk_expr(&c.value, words, library, env, classes, walk); }
        },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let id = map_named(base, words, &walk);
            if id >= 0 {
                let deps = tm_deps_of(index, words, library, env, &walk);
                walk.kept.push(MapKept { id, deps });
            } else { tm_walk_expr(base, words, library, env, classes, walk); }
            tm_walk_expr(index, words, library, env, classes, walk);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            let found = tm_private_callee(func, env, &walk);
            if found.is_some() {
                let callee = match found { Some(__nikaia_value) => __nikaia_value, None => return };
                let ret = format!("r:{}", words.resolve(callee));
                mc_poison(classes, &ret);
                tm_call_args(callee, args, config, words, library, env, classes, walk);
            } else {
                tm_walk_expr(func, words, library, env, classes, walk);
                for a in args.iter() { tm_walk_expr(a, words, library, env, classes, walk); }
                for c in config.iter() { tm_walk_expr(&c.value, words, library, env, classes, walk); }
            }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            tm_walk_expr(lhs, words, library, env, classes, walk);
            tm_walk_expr(rhs, words, library, env, classes, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_walk_expr(expr, words, library, env, classes, walk); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_walk_expr(expr, words, library, env, classes, walk); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); tm_walk_expr(inner, words, library, env, classes, walk); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); tm_walk_expr(inner, words, library, env, classes, walk); },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tm_walk_expr(base, words, library, env, classes, walk); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); tm_walk_expr(base, words, library, env, classes, walk); },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            tm_walk_expr(value, words, library, env, classes, walk);
            tm_walk_expr(fallback, words, library, env, classes, walk);
        },
        Expr::Tuple(items, _) => { for i in items.iter() { tm_walk_expr(i, words, library, env, classes, walk); } },
        Expr::ListLit { items, .. } => { for i in items.iter() { tm_walk_expr(i, words, library, env, classes, walk); } },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            tm_walk_expr(value, words, library, env, classes, walk);
            tm_walk_expr(count, words, library, env, classes, walk);
        },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { tm_walk_expr(expr, words, library, env, classes, walk); },
                    _ => { },
                }
            }
        },
        Expr::Return(value, _) => {
            let value = nikaia_std::boxed::open(value);
            if value.is_some() {
                let ret = walk.ret.to_owned();
                tm_flow(&ret, match value { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, classes, walk);
            }
        },
        Expr::Variable(name, _) => {
            let name = *name;
            let id = tm_resolve(name.to_owned(), &walk);
            if id >= 0 { walk.escapes.insert(id); }
            if id == -2 {
                let arity = nikaia_std::index::or(env.privates.get(&name), || -1);
                if arity >= 0 { mc_poison_function(classes, words.resolve(name), arity); }
            }
        },
        Expr::StructLit { fields, .. } => {
            for field in fields.iter() {
                if field.value.is_some() { tm_walk_expr(match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, classes, walk); } else {
                    let id = tm_resolve(field.name.to_owned(), &walk);
                    if id >= 0 { walk.escapes.insert(id); }
                }
            }
            walk.unread = true;
        },
        Expr::Path(_, _) => { },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_, _) => { },
        Expr::LitStr { .. } => { },
        Expr::LitChar(_, _) => { },
        Expr::LitBool(_, _) => { },
        Expr::LitNull(_) => { },
        Expr::Break(_) => { },
        Expr::Continue(_) => { },
        _ => { walk.unread = true; },
    }
}

fn tm_all_deps(items: &[Expr], words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    let mut all = tm_nothing();
    for item in items.iter() {
        all = tm_join(&all, &tm_deps_of(item, words, library, env, walk));
        if !all.known { return all; }
    }
    all
}

fn tm_deps_of(value: &Expr, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    match value {
        Expr::LitInt { .. } => tm_nothing(),
        Expr::LitFloat(_, _) => tm_nothing(),
        Expr::LitStr { .. } => tm_nothing(),
        Expr::LitChar(_, _) => tm_nothing(),
        Expr::LitBool(_, _) => tm_nothing(),
        Expr::LitNull(_) => tm_nothing(),
        Expr::Variable(name, _) => {
            let name = *name;
            let id = tm_resolve(name.to_owned(), walk);
            if id >= 0 { tm_reading(id) } else { tm_never() }
        },
        Expr::LitInterpolated { parts, .. } => {
            let mut all = tm_nothing();
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { all = tm_join(&all, &tm_deps_of(expr, words, library, env, walk)); },
                    _ => { },
                }
            }
            all
        },
        Expr::Tuple(items, _) => tm_all_deps(items, words, library, env, walk),
        Expr::ListLit { items, .. } => tm_all_deps(items, words, library, env, walk),
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); tm_join(&tm_deps_of(value, words, library, env, walk), &tm_deps_of(count, words, library, env, walk)) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_deps_of(expr, words, library, env, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_deps_of(expr, words, library, env, walk) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); tm_join(&tm_deps_of(lhs, words, library, env, walk), &tm_deps_of(rhs, words, library, env, walk)) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tm_deps_of(base, words, library, env, walk) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); tm_join(&tm_deps_of(base, words, library, env, walk), &tm_deps_of(index, words, library, env, walk)) },
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); tm_join(&tm_deps_of(value, words, library, env, walk), &tm_deps_of(fallback, words, library, env, walk)) },
        Expr::Call { func, args, config, .. } => { let func = nikaia_std::boxed::open(func); tm_call_deps(func, args, config, words, library, env, walk) },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let name = words.resolve(method);
            if env.sources.contains(name) || env.own.contains(name) { tm_never() } else { tm_join(&tm_deps_of(receiver, words, library, env, walk), &tm_all_deps(args, words, library, env, walk)) }
        },
        _ => tm_never(),
    }
}

fn tm_call_deps(func: &Expr, args: &[Expr], config: &[ConfigArg], words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    let name = match func {
        Expr::Path(segments, _) => {
            let mut joined: String = String::from("");
            for segment in segments.iter() {
                let segment = *segment;
                if !joined.is_empty() { joined.push_str("::"); }
                joined.push_str(words.resolve(segment));
            }
            joined
        },
        Expr::Variable(one, _) => { let one = *one; words.resolve(one).to_owned() },
        _ => return tm_never(),
    };
    if env.own.contains(&name) { return tm_never(); }
    let contract = match *nikaia_std::index::get(&library.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return tm_never() };
    if contract.provenance.is_some() {
        let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => return tm_never() };
        if provenance == Provenance::Trusted { return tm_nothing(); }
        return tm_never();
    }
    let mut all = tm_all_deps(args, words, library, env, walk);
    for c in config.iter() { all = tm_join(&all, &tm_deps_of(&c.value, words, library, env, walk)); }
    all
}

fn is_a_map_made(value: &Expr, words: &winnow_grammar::InternerContext) -> bool {
    match value {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !args.is_empty() { false } else {
                match func {
                    Expr::Path(segments, _) => {
                        let last = words.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1)));
                        last == "HashMap" || last == "HashSet"
                    },
                    Expr::Variable(one, _) => {
                        let one = *one;
                        let last = words.resolve(one);
                        last == "HashMap" || last == "HashSet"
                    },
                    _ => false,
                }
            }
        },
        _ => false,
    }
}


// --- ty.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    Unknown,
    Named { name: String, args: Vec<Ty>, view: bool },
    Tuple(Vec<Ty>),
    Pointed { item: Box<Ty>, slice: bool, mutable: bool },
    Count(i64),
    Var { name: String, view: bool },
    Fn { params: Vec<Ty>, result: Box<Option<Ty>>, is_sync: bool, can_throw: bool },
    Nullable(Box<Ty>),
    Seq { item: Box<Ty>, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: Shape },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Shape {
    pub ends: bool,
    pub sized: bool,
    pub replays: bool,
}

impl Shape {
    pub fn none() -> Shape { Shape { ends: false, sized: false, replays: false } }
    pub fn meets(&self, wanted: &Shape) -> bool { self.missing(wanted).is_empty() }
    pub fn missing(&self, wanted: &Shape) -> Vec<String> {
        let mut words: Vec<String> = vec![];
        if wanted.ends && !self.ends { words.push(ENDS.to_owned()); }
        if wanted.sized && !self.sized { words.push(SIZED.to_owned()); }
        if wanted.replays && !self.replays { words.push(REPLAYS.to_owned()); }
        words
    }
}

pub const ENDS: &str = "ends";

pub const SIZED: &str = "sized";

pub const REPLAYS: &str = "replays";

pub const SEQ: &str = "Seq";

pub const PAR: &str = "Par";

pub const PAUSES: &str = "pauses";

pub const ARRAY: &str = "Array";

const ARRAY_OPEN: &str = "Array[";

const ARRAY_OPEN_LENGTH: i64 = 6;

pub const TEXT: &str = "String";

pub const TEXT_VIEW: &str = "str";

impl Ty {
    pub fn text(&self) -> String { text(self) }
}

pub fn text(ty: &Ty) -> String {
    match ty {
        Ty::Unknown => String::from("?"),
        Ty::Count(n) => { let n = *n; format!("{}", n) },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; pointed(item, slice, mutable) },
        Ty::Tuple(parts) => format!("({})", listed(parts)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; code(params, (result).as_ref(), is_sync, can_throw) },
        Ty::Var { name, view } => { let view = *view; if view { format!("ref ${}", name) } else { format!("${}", name) } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}?", text(inner)) },
        Ty::Named { name, args, view } => { let view = *view; named_text(name, args, view) },
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; sequence(item, is_sync, pauses, can_throw, parallel, shape) },
    }
}

fn listed(parts: &[Ty]) -> String {
    let mut out: String = String::from("");
    for part in parts.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(&text(part));
    }
    out
}

fn pointed(item: &Ty, slice: bool, mutable: bool) -> String {
    let mut out: String = String::from("ref ");
    if mutable { out.push_str("mut "); }
    if !slice {
        out.push_str(&text(item));
        return out;
    }
    let written = match item {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}[{}]?", ARRAY, text(inner)) },
        _ => format!("{}[{}]", ARRAY, text(item)),
    };
    out.push_str(&written);
    out
}

fn code(params: &[Ty], result: Option<&Ty>, is_sync: bool, can_throw: bool) -> String {
    let mut out = format!("fn({})", listed(params));
    if result.is_some() {
        let returned = nikaia_std::index::or(match result {
            Some(__nikaia_it) => Some(__nikaia_it.text()),
            None => None,
        }, || "".into());
        out.push_str(&format!(" -> {}", returned));
    }
    if is_sync { out.push_str(" sync"); }
    if can_throw { out.push_str(" throws"); }
    out
}

fn named_text(name: &str, args: &[Ty], view: bool) -> String {
    let mut out: String = if view { String::from("ref ") } else { String::from("") };
    if view && name == TEXT_VIEW { out.push_str(TEXT); } else { out.push_str(name); }
    if !args.is_empty() { out.push_str(&format!("[{}]", listed(args))); }
    out
}

fn sequence(item: &Ty, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: &Shape) -> String {
    let word = if parallel { PAR } else { SEQ };
    let mut out = format!("{}[{}]", word, text(item));
    if is_sync { out.push_str(" sync"); }
    if pauses { out.push_str(&format!(" {}", PAUSES)); }
    if can_throw { out.push_str(" throws"); }
    for word in Shape::none().missing(shape) { out.push_str(&format!(" {}", word)); }
    out
}

pub fn parse(written: &str) -> Ty {
    let trimmed = written.trim();
    if trimmed.is_empty() || trimmed == "?" { return Ty::Unknown; }
    let count = text::parse_i64(trimmed);
    if count.is_some() { return Ty::Count(nikaia_std::index::or(count, || 0)); }
    let viewed = a_view_of(trimmed);
    let is_a_view = viewed.is_some();
    let marked: String = nikaia_std::index::or(viewed, || "".into());
    if is_a_view {
        let pointer = pointed_at(&marked);
        if pointer.is_some() { return nikaia_std::index::or(pointer, || Ty::Unknown); }
    }
    if trimmed.ends_with('?') { return Ty::Nullable(Box::new(parse(&cut(trimmed, 0, 1)))); }
    if trimmed.starts_with('(') && trimmed.ends_with(')') { return Ty::Tuple(each(&split_args(&cut(trimmed, 1, 1)))); }
    if trimmed.starts_with("fn(") {
        let code = a_function(trimmed);
        if code.is_some() { return nikaia_std::index::or(code, || Ty::Unknown); }
    }
    let sequence = a_sequence(trimmed, SEQ, false);
    if sequence.is_some() { return nikaia_std::index::or(sequence, || Ty::Unknown); }
    let parallel = a_sequence(trimmed, PAR, true);
    if parallel.is_some() { return nikaia_std::index::or(parallel, || Ty::Unknown); }
    if is_a_view { return a_name(marked.trim(), true); }
    a_name(trimmed, false)
}

pub fn split_args(written: &str) -> Vec<String> {
    let mut parts: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in written.chars() {
        if c == '[' || c == '(' {
            depth += 1;
            current.push(c);
        } else if c == ']' || c == ')' {
            if depth > 0 { depth -= 1; }
            current.push(c);
        } else if c == ',' && depth == 0 {
            parts.push(current.trim().to_owned());
            current = String::from("");
        } else { current.push(c); }
    }
    if !current.trim().is_empty() { parts.push(current.trim().to_owned()); }
    parts
}

pub fn a_view_of(written: &str) -> Option<String> {
    if written.starts_with("ref(") {
        let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
        let close = closing(&c, 4, ')');
        if close >= 0 {
            let rest = between(&c, close + 1, c.len() as i64);
            return Some(rest.trim_start().to_owned());
        }
    }
    if written.starts_with("ref ") {
        let rest = cut(written, 4, 0);
        return Some(rest.trim_start().to_owned());
    }
    if written.starts_with('&') {
        let rest = cut(written, 1, 0);
        return Some(rest.trim_start().to_owned());
    }
    None
}

fn each(parts: &[String]) -> Vec<Ty> {
    let mut read: Vec<Ty> = vec![];
    for part in parts.iter() { read.push(parse(part)); }
    read
}

fn between(c: &[scalar], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn cut(written: &str, front: i64, back: i64) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    between(&c, front, c.len() as i64 - back)
}

fn closing(c: &[scalar], from: i64, closer: scalar) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        let ch = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
        if ch == '(' || ch == '[' { depth += 1; } else if ch == closer {
            if depth == 0 { return at; }
            depth -= 1;
        } else if ch == ')' || ch == ']' {
            if depth == 0 { return -1; }
            depth -= 1;
        }
    }
    -1
}

fn word_off(tail: &str, word: &str) -> Option<String> {
    if !tail.ends_with(word) { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(tail.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let shorter = between(&c, 0, c.len() as i64 - w.len() as i64);
    if shorter.is_empty() { return Some(shorter); }
    if (*nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - w.len() as i64 - 1))).is_whitespace() { return Some(shorter.trim_end().to_owned()); }
    None
}

fn pointed_at(viewed: &str) -> Option<Ty> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut rest: String = viewed.to_owned();
    let mut mutable = false;
    if rest.starts_with("mut ") {
        mutable = true;
        let shorter = __keep_frame.put(cut(&rest, 4, 0));
        rest = shorter.trim_start().to_owned();
    }
    let mut absent = false;
    if rest.ends_with('?') {
        absent = true;
        let shorter = __keep_frame.put(cut(&rest, 0, 1));
        rest = shorter.trim_end().to_owned();
    }
    let mut slice = false;
    let mut inner: String = String::from("");
    if rest.starts_with(ARRAY_OPEN) && rest.ends_with(']') {
        let args = cut(&rest, ARRAY_OPEN_LENGTH, 1);
        if split_args(&args).len() == 1 {
            slice = true;
            inner = args;
        }
    }
    if !slice && rest.starts_with('[') && rest.ends_with(']') {
        slice = true;
        inner = cut(&rest, 1, 1);
    }
    if !mutable && !slice { return None; }
    if !slice { inner = rest.to_owned(); }
    let item = parse(&inner);
    if absent { return Some(Ty::Pointed { item: Box::new(Ty::Nullable(Box::new(item))), slice, mutable }); }
    Some(Ty::Pointed { item: Box::new(item), slice, mutable })
}

fn a_function(written: &str) -> Option<Ty> {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let close = closing(&c, 3, ')');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut can_throw = false;
    while !tail.is_empty() {
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        break;
    }
    let params = each(&split_args(&between(&c, 3, close)));
    if tail.starts_with("->") {
        let result = parse(&cut(&tail, 2, 0));
        return Some(Ty::Fn { params, result: Box::new(Some(result)), is_sync, can_throw });
    }
    Some(Ty::Fn { params, result: Box::new(None), is_sync, can_throw })
}

fn a_sequence(written: &str, word: &str, parallel: bool) -> Option<Ty> {
    if !written.starts_with(word) { return None; }
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let after_word = cut(written, w.len() as i64, 0);
    let rest: String = after_word.trim_start().to_owned();
    if !rest.starts_with('[') { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(rest.chars());
    let close = closing(&c, 1, ']');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut pauses = false;
    let mut can_throw = false;
    let mut ends = false;
    let mut sized = false;
    let mut replays = false;
    while !tail.is_empty() {
        let without_ends = word_off(&tail, ENDS);
        if without_ends.is_some() {
            ends = true;
            tail = nikaia_std::index::or(without_ends, || "".into());
            continue;
        }
        let without_sized = word_off(&tail, SIZED);
        if without_sized.is_some() {
            sized = true;
            tail = nikaia_std::index::or(without_sized, || "".into());
            continue;
        }
        let without_replays = word_off(&tail, REPLAYS);
        if without_replays.is_some() {
            replays = true;
            tail = nikaia_std::index::or(without_replays, || "".into());
            continue;
        }
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        let without_pauses = word_off(&tail, PAUSES);
        if without_pauses.is_some() {
            pauses = true;
            tail = nikaia_std::index::or(without_pauses, || "".into());
            continue;
        }
        break;
    }
    if is_sync && pauses { return None; }
    if !tail.is_empty() { return None; }
    let item = parse(&between(&c, 1, close));
    let shape = Shape { ends, sized, replays };
    Some(Ty::Seq { item: Box::new(item), is_sync, pauses, can_throw, parallel, shape })
}

fn a_name(rest: &str, view: bool) -> Ty {
    if rest.starts_with('$') && rest.len() > 1 { return Ty::Var { name: cut(rest, 1, 0), view }; }
    if view && rest == TEXT { return Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }; }
    if rest == "char" { return Ty::Named { name: String::from("scalar"), args: vec![], view }; }
    if !rest.ends_with(']') { return Ty::Named { name: rest.to_owned(), args: vec![], view }; }
    let c: Vec<scalar> = nikaia_std::list::chars(rest.chars());
    let mut open: i64 = -1;
    for at in 0..c.len() as i64 { if open < 0 && *nikaia_std::index::get(&c, (at) as usize) == '[' { open = at; } }
    if open >= 0 {
        let named_text = between(&c, 0, open);
        return Ty::Named { name: named_text.trim().to_owned(), args: each(&split_args(&between(&c, open + 1, c.len() as i64 - 1))), view };
    }
    Ty::Named { name: rest.to_owned(), args: vec![], view }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Provenance {
    Trusted,
    Untrusted,
}

impl Provenance {
    pub fn join(self, other: Provenance) -> Provenance {
        if self == Provenance::Untrusted || other == Provenance::Untrusted { return Provenance::Untrusted; }
        Provenance::Trusted
    }
    pub fn as_str(self) -> String {
        match self {
            Provenance::Trusted => String::from("trusted"),
            Provenance::Untrusted => String::from("untrusted"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Sync {
    No,
    Inferred,
    Asserted,
    From(String),
    Unpromised,
}

impl Sync {
    pub fn is_sync(&self) -> bool { !matches!(self, Sync::No | Sync::Unpromised) }
    pub fn is_unpromised(&self) -> bool { matches!(self, Sync::Unpromised) }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lock {
    No,
    Holds,
    Undecided,
}

impl Lock {
    pub fn holds(self) -> bool { self == Lock::Holds }
    pub fn or(self, other: Lock) -> Lock {
        if self == Lock::Holds || other == Lock::Holds { return Lock::Holds; }
        if self == Lock::Undecided || other == Lock::Undecided { return Lock::Undecided; }
        Lock::No
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Crosses {
    May,
    MayNot,
    Undecided,
}

impl Crosses {
    pub fn may(self) -> bool { self == Crosses::May }
    pub fn may_not(self) -> bool { self == Crosses::MayNot }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Threads {
    May,
    MayNot,
    Undecided,
}

impl Threads {
    pub fn may(self) -> bool { self == Threads::May }
    pub fn may_not(self) -> bool { self == Threads::MayNot }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Touch {
    pub kind: String,
    pub parameter: Option<String>,
    pub write: bool,
}

impl Touch {
    pub fn names_a_lock(&self) -> bool { self.kind == "lock" }
    pub fn text(&self) -> String { touched(&self.kind, (self.parameter).as_deref(), self.write) }
}

fn touched(kind: &str, parameter: Option<&str>, write: bool) -> String {
    let access = if write { "write" } else { "read" };
    if parameter.is_none() { return format!("{} {}", kind, access); }
    let named_text = nikaia_std::index::or(parameter, || "");
    format!("{}({}) {}", kind, named_text, access)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Borrowed,
    Tethered,
}

impl State {
    pub fn as_str(self) -> String {
        match self {
            State::Borrowed => String::from("borrowed"),
            State::Tethered => String::from("tethered"),
        }
    }
    pub fn parse(written: &str) -> Option<State> {
        let word = written.trim();
        if word == "borrowed" { return Some(State::Borrowed); }
        if word == "tethered" { return Some(State::Tethered); }
        None
    }
    pub fn or(self, other: State) -> State {
        if self == State::Tethered || other == State::Tethered { return State::Tethered; }
        State::Borrowed
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Held {
    pub position: String,
    pub state: State,
}

impl Held {
    pub fn text(&self) -> String { format!("{}: {}", self.position, self.state.as_str()) }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Count {
    Plain,
    Word,
    Atomic,
}

impl Count {
    pub fn join(self, other: Count) -> Count {
        if self == Count::Atomic || other == Count::Atomic { return Count::Atomic; }
        if self == Count::Word || other == Count::Word { return Count::Word; }
        Count::Plain
    }
    pub fn rank(self) -> i64 {
        match self {
            Count::Plain => 0,
            Count::Word => 1,
            Count::Atomic => 2,
        }
    }
    pub fn as_str(self) -> String {
        match self {
            Count::Plain => String::from("plain"),
            Count::Word => String::from("word"),
            Count::Atomic => String::from("atomic"),
        }
    }
    pub fn parse(written: &str) -> Option<Count> {
        let word = written.trim();
        if word == "plain" { return Some(Count::Plain); }
        if word == "word" { return Some(Count::Word); }
        if word == "atomic" { return Some(Count::Atomic); }
        None
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Class {
    pub members: Vec<String>,
    pub count: Count,
}

impl Class {
    pub fn text(&self) -> String {
        let mut out: String = String::from("");
        for member in self.members.iter() {
            if !out.is_empty() { out.push_str(" | "); }
            out.push_str(member);
        }
        format!("{}: {}", out, self.count.as_str())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FieldContract {
    pub name: String,
    pub ty: Ty,
    pub public: bool,
    pub default: String,
    pub attributes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VariantContract {
    pub name: String,
    pub holds: Vec<FieldContract>,
    pub positional: bool,
    pub attributes: Vec<String>,
}

impl VariantContract {
    pub fn text(&self) -> String {
        if self.holds.is_empty() { return self.name.to_owned(); }
        let mut parts: String = String::from("");
        for field in self.holds.iter() {
            if !parts.is_empty() { parts.push_str(", "); }
            if self.positional { parts.push_str(&field.ty.text()); } else { parts.push_str(&format!("{}: {}", field.name, field.ty.text())); }
        }
        if self.positional { return format!("{}({})", self.name, parts); }
        format!("{} {{ {} }}", self.name, parts)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConfigContract {
    pub name: String,
    pub ty: Ty,
    pub default: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signature {
    pub bounds: Vec<(String, Vec<String>)>,
    pub params: Vec<(String, Ty)>,
    pub mutable: Vec<String>,
    pub config: Vec<ConfigContract>,
    pub result: Option<Ty>,
}

impl Signature {
    pub fn empty() -> Signature { Signature { bounds: vec![], params: vec![], mutable: vec![], config: vec![], result: None } }
    pub fn takes_a_receiver(&self) -> bool { !self.params.is_empty() && nikaia_std::index::get(&self.params, 0).0 == "self" }
    pub fn result_or_unit(&self) -> Ty {
        nikaia_std::index::or(match self.result.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Ty::Tuple(vec![]))
    }
    pub fn text(&self) -> String {
        let mut inside: String = String::from("");
        for (name, ty) in self.params.iter() {
            if !inside.is_empty() { inside.push_str(", "); }
            if name == "self" { inside.push_str(&ty.text()); } else {
                if nikaia_std::list::contains(&self.mutable, &name) { inside.push_str("mut "); }
                inside.push_str(&format!("{}: {}", name, ty.text()));
            }
        }
        if !self.config.is_empty() {
            inside.push_str("; ");
            let mut first = true;
            for option in self.config.iter() {
                if !first { inside.push_str(", "); }
                first = false;
                inside.push_str(&format!("{}: {} = {}", option.name, option.ty.text(), option.default));
            }
        }
        let mut before: String = String::from("");
        if !self.bounds.is_empty() {
            before.push('[');
            let mut first = true;
            for (name, traits) in self.bounds.iter() {
                if !first { before.push_str(", "); }
                first = false;
                before.push_str(name);
                if !traits.is_empty() {
                    before.push_str(": ");
                    let mut one = true;
                    for bound in traits.iter() {
                        if !one { before.push_str(" + "); }
                        one = false;
                        before.push_str(bound);
                    }
                }
            }
            before.push(']');
        }
        if self.result.is_none() { return format!("{}({})", before, inside); }
        format!("{}({}) -> {}", before, inside, self.result_or_unit().text())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
