pub const SEEN: &str = "Seen";

impl Ty {
    pub fn is_unknown(&self) -> bool { matches!(self, Ty::Unknown) }
    pub fn as_a_view(&self) -> Ty {
        match self {
            Ty::Named { name, args, view } => { let view = *view; viewed_name(name, args, view) },
            _ => self.clone(),
        }
    }
    pub fn is_seen(&self) -> bool {
        match self {
            Ty::Named { name, args, .. } => name == SEEN && args.len() == 1,
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_seen() },
            _ => false,
        }
    }
    pub fn unseen(&self) -> Ty {
        match self {
            Ty::Named { name, args, .. } => { if name == SEEN && args.len() == 1 { return (*nikaia_std::index::get(&args, 0)).clone(); } },
            Ty::Nullable(inner) => {
                let inner = nikaia_std::boxed::open(inner);
                return Ty::Nullable(Box::new(inner.unseen()));
            },
            _ => { },
        }
        self.clone()
    }
    pub fn owned(&self) -> Ty {
        match self {
            Ty::Named { name, args, view } => { let view = *view; if view && name == TEXT_VIEW && args.is_empty() { Ty::Named { name: TEXT.to_owned(), args: vec![], view: false } } else if view { Ty::Named { name: name.to_owned(), args: args.to_owned(), view: false } } else { self.clone() } },
            _ => self.clone(),
        }
    }
    pub fn is_a_view(&self) -> bool {
        match self {
            Ty::Named { view, .. } => { let view = *view; view },
            Ty::Var { view, .. } => { let view = *view; view },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_a_view() },
            Ty::Pointed { slice, mutable, .. } => { let mutable = *mutable; let slice = *slice; slice && !mutable },
            _ => false,
        }
    }
    pub fn fits(&self, expected: &Ty) -> bool {
        if self.is_unknown() || expected.is_unknown() { return true; }
        if self.is_seen() || expected.is_seen() { return self.unseen().fits(&expected.unseen()); }
        match self {
            Ty::Tuple(parts) => { if a_tuple(expected) { return tuple_fits(parts, expected); } },
            Ty::Count(n) => {
                let n = *n;
                if a_count(expected) { return count_fits(n, expected); }
            },
            Ty::Pointed { item, slice, mutable } => {
                let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice;
                if a_pointed(expected) { return pointed_fits(item, slice, mutable, expected); }
            },
            Ty::Named { name, args, view } => {
                let view = *view;
                if !view && name == ARRAY && args.len() == 2 && an_array_of_any_length(expected) { return array_fits(args, expected); }
            },
            _ => { },
        }
        match expected {
            Ty::Pointed { item, slice, .. } => {
                let item = nikaia_std::boxed::open(item); let slice = *slice;
                if slice { return lends_a_run_of(self, item); }
                return self.fits(item);
            },
            _ => { },
        }
        match self {
            Ty::Fn { params, result, is_sync, can_throw } => {
                let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync;
                if a_function_type(expected) { return function_fits(params, (result).as_ref(), is_sync, can_throw, expected); }
            },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => {
                let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses;
                if a_sequence_type(expected) { return sequence_fits(item, is_sync, pauses, can_throw, parallel, shape, expected); }
            },
            Ty::Var { .. } => { return true; },
            _ => { },
        }
        match expected {
            Ty::Var { .. } => { return true; },
            Ty::Nullable(wanted) => {
                let wanted = nikaia_std::boxed::open(wanted);
                return nullable_fits(self, wanted);
            },
            Ty::Named { name, args, view } => {
                let view = *view;
                return named_fits(self, name, args, view);
            },
            _ => { },
        }
        false
    }
    pub fn erase(&self, parameters: &collections::BTreeSet<String>) -> Ty {
        match self {
            Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(item.erase(parameters)), slice, mutable } },
            Ty::Tuple(parts) => Ty::Tuple(erased_each(parts, parameters)),
            Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: erased_each(params, parameters), result: Box::new(match result {
                Some(__nikaia_it) => Some(__nikaia_it.erase(parameters)),
                None => None,
            }), is_sync, can_throw } },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(item.erase(parameters)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(inner.erase(parameters))) },
            Ty::Named { name, args, view } => { let view = *view; erased_name(name, args, view, parameters) },
            _ => self.clone(),
        }
    }
    pub fn parameterise(&self, parameters: &collections::BTreeSet<String>) -> Ty {
        match self {
            Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(item.parameterise(parameters)), slice, mutable } },
            Ty::Tuple(parts) => Ty::Tuple(parameterised_each(parts, parameters)),
            Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: parameterised_each(params, parameters), result: Box::new(match result {
                Some(__nikaia_it) => Some(__nikaia_it.parameterise(parameters)),
                None => None,
            }), is_sync, can_throw } },
            Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(item.parameterise(parameters)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
            Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(inner.parameterise(parameters))) },
            Ty::Named { name, args, view } => { let view = *view; parameterised_name(name, args, view, parameters) },
            _ => self.clone(),
        }
    }
}

impl Ty {
    fn fits_any(&self, wanted: Option<&Ty>) -> bool {
        nikaia_std::index::or(match wanted {
            Some(__nikaia_it) => Some(__nikaia_it.fitted_by(self)),
            None => None,
        }, || true)
    }
    fn fitted_by(&self, found: &Ty) -> bool { found.fits(self) }
    fn substituted_in(&self, bound: &collections::BTreeMap<String, Ty>) -> Ty { substitute(self, bound) }
    fn qualified_in(&self, module: &str, declared: &collections::BTreeSet<String>) -> Ty { qualify(self, module, declared) }
    fn renamed_by(&self, renames: &collections::BTreeMap<String, String>) -> Ty { renamed(self, renames) }
}

fn viewed_name(name: &str, args: &[Ty], view: bool) -> Ty {
    if view { return Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }; }
    if args.is_empty() && (name == TEXT || name.ends_with("::String")) { return Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }; }
    Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }
}

fn a_tuple(ty: &Ty) -> bool { matches!(ty, Ty::Tuple(_)) }

fn a_count(ty: &Ty) -> bool { matches!(ty, Ty::Count(_)) }

fn a_pointed(ty: &Ty) -> bool { matches!(ty, Ty::Pointed { .. }) }

fn a_function_type(ty: &Ty) -> bool { matches!(ty, Ty::Fn { .. }) }

fn a_sequence_type(ty: &Ty) -> bool { matches!(ty, Ty::Seq { .. }) }

fn all_fit(found: &[Ty], wanted: &[Ty]) -> bool {
    if (found.len() as i64) != wanted.len() as i64 { return false; }
    for at in 0..found.len() as i64 { if !(*nikaia_std::index::get(&found, (at) as usize)).fits(nikaia_std::index::get(&wanted, (at) as usize)) { return false; } }
    true
}

fn tuple_fits(parts: &[Ty], expected: &Ty) -> bool {
    match expected {
        Ty::Tuple(wanted) => all_fit(parts, wanted),
        _ => false,
    }
}

fn count_fits(n: i64, expected: &Ty) -> bool {
    match expected {
        Ty::Count(wanted) => { let wanted = *wanted; n == wanted },
        _ => false,
    }
}

fn pointed_fits(found: &Ty, run: bool, writes: bool, expected: &Ty) -> bool {
    match expected {
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; found.fits(item) && run == slice && writes == mutable },
        _ => false,
    }
}

fn an_array_of_any_length(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && name == ARRAY && args.len() == 1 },
        _ => false,
    }
}

fn array_fits(given: &[Ty], expected: &Ty) -> bool {
    match expected {
        Ty::Named { args, .. } => (*nikaia_std::index::get(&given, 0)).fits(nikaia_std::index::get(&args, 0)),
        _ => false,
    }
}

fn lends_a_run_of(found: &Ty, item: &Ty) -> bool {
    match found {
        Ty::Unknown => true,
        Ty::Named { name, args, .. } => a_run_named(name, args, item),
        _ => false,
    }
}

fn a_run_named(name: &str, args: &[Ty], item: &Ty) -> bool {
    if (name == "Vec" || name == "List") && args.len() == 1 { return (*nikaia_std::index::get(&args, 0)).fits(item); }
    if name == ARRAY && (args.len() == 1 || args.len() == 2) { return (*nikaia_std::index::get(&args, 0)).fits(item); }
    if (name == "String" || name == "str") && args.is_empty() {
        return match item {
            Ty::Named { name, .. } => name == "u8",
            _ => false,
        };
    }
    false
}

fn function_fits(found: &[Ty], found_result: Option<&Ty>, never_pauses: bool, fails: bool, expected: &Ty) -> bool {
    match expected {
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; all_fit(found, params) && results_fit(found_result, (result).as_ref()) && (never_pauses || !is_sync) && (!fails || can_throw) },
        _ => false,
    }
}

fn results_fit(found: Option<&Ty>, wanted: Option<&Ty>) -> bool {
    if found.is_none() || wanted.is_none() { return true; }
    nikaia_std::index::or(match found {
        Some(__nikaia_it) => Some(__nikaia_it.fits_any(wanted)),
        None => None,
    }, || true)
}

fn sequence_fits(found: &Ty, never_pauses: bool, may_pause: bool, fails: bool, at_once: bool, has: &Shape, expected: &Ty) -> bool {
    match expected {
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; found.fits(item) && (never_pauses || !is_sync) && (!may_pause || pauses) && (!fails || can_throw) && (at_once || !parallel) && has.meets(shape) },
        _ => false,
    }
}

fn nullable_fits(found: &Ty, wanted: &Ty) -> bool {
    match found {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.fits(wanted) },
        _ => found.fits(wanted),
    }
}

fn named_fits(found: &Ty, wanted: &str, wanted_args: &[Ty], wanted_view: bool) -> bool {
    match found {
        Ty::Named { name, args, view } => { let view = *view; name == wanted && view == wanted_view && all_fit(args, wanted_args) },
        _ => false,
    }
}

fn erased_each(parts: &[Ty], parameters: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(part.erase(parameters)); }
    out
}

fn erased_name(name: &str, args: &[Ty], view: bool, parameters: &collections::BTreeSet<String>) -> Ty {
    if args.is_empty() && parameters.contains(name) { return Ty::Unknown; }
    Ty::Named { name: name.to_owned(), args: erased_each(args, parameters), view }
}

fn parameterised_each(parts: &[Ty], parameters: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(part.parameterise(parameters)); }
    out
}

fn parameterised_name(name: &str, args: &[Ty], view: bool, parameters: &collections::BTreeSet<String>) -> Ty {
    if args.is_empty() && parameters.contains(name) { return Ty::Var { name: name.to_owned(), view }; }
    Ty::Named { name: name.to_owned(), args: parameterised_each(args, parameters), view }
}

pub fn bind(pattern: &Ty, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match pattern {
        Ty::Var { name, .. } => { if !out.contains_key(name) { out.insert(name.to_owned(), actual.clone()); } },
        Ty::Named { name, args, .. } => { bind_named(name, args, actual, out); },
        Ty::Seq { item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bind_item(item, actual, out);
        },
        Ty::Fn { params, result, .. } => {
            let result = nikaia_std::boxed::open(result);
            bind_code(params, (result).as_ref(), actual, out);
        },
        _ => { },
    }
}

fn bind_named(pattern_name: &str, pattern_args: &[Ty], actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Named { name, args, .. } => { bind_arguments(pattern_name, pattern_args, name, args, out); },
        _ => { },
    }
}

fn bind_arguments(pattern_name: &str, pattern_args: &[Ty], name: &str, args: &[Ty], out: &mut collections::BTreeMap<String, Ty>) {
    if name != pattern_name || (args.len() as i64) != pattern_args.len() as i64 { return; }
    for at in 0..args.len() as i64 { bind(nikaia_std::index::get(&pattern_args, (at) as usize), nikaia_std::index::get(&args, (at) as usize), out); }
}

fn bind_item(pattern: &Ty, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Seq { item, .. } => {
            let item = nikaia_std::boxed::open(item);
            bind(pattern, item, out);
        },
        _ => { },
    }
}

fn bind_code(pattern_params: &[Ty], pattern_result: Option<&Ty>, actual: &Ty, out: &mut collections::BTreeMap<String, Ty>) {
    match actual {
        Ty::Fn { params, result, .. } => {
            let result = nikaia_std::boxed::open(result);
            let shorter = if (params.len() as i64) < pattern_params.len() as i64 { params.len() as i64 } else { pattern_params.len() as i64 };
            for at in 0..shorter { bind(nikaia_std::index::get(&pattern_params, (at) as usize), nikaia_std::index::get(&params, (at) as usize), out); }
            if pattern_result.is_some() && result.is_some() {
                let pattern = nikaia_std::index::or(match pattern_result {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, || Ty::Unknown);
                let bound_from = nikaia_std::index::or(match result {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, || Ty::Unknown);
                bind(&pattern, &bound_from, out);
            }
        },
        _ => { },
    }
}

pub fn substitute(ty: &Ty, bound: &collections::BTreeMap<String, Ty>) -> Ty {
    match ty {
        Ty::Var { name, view } => { let view = *view; substituted(name, view, bound) },
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: name.to_owned(), args: substituted_each(args, bound), view } },
        Ty::Tuple(parts) => Ty::Tuple(substituted_each(parts, bound)),
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; Ty::Pointed { item: Box::new(substitute(item, bound)), slice, mutable } },
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: substituted_each(params, bound), result: Box::new(substituted_result((result).as_ref(), bound)), is_sync, can_throw } },
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; Ty::Seq { item: Box::new(substitute(item, bound)), is_sync, pauses, can_throw, parallel, shape: shape.clone() } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(substitute(inner, bound))) },
        _ => ty.clone(),
    }
}

fn substituted(name: &str, view: bool, bound: &collections::BTreeMap<String, Ty>) -> Ty {
    if !bound.contains_key(name) { return Ty::Unknown; }
    let found = nikaia_std::index::or(match *nikaia_std::index::get(&bound, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Ty::Unknown);
    if view {
        match found {
            Ty::Named { ref name, ref args, .. } => { return Ty::Named { name: name.to_owned(), args: args.to_owned(), view: true }; },
            _ => { },
        }
    }
    found.clone()
}

fn substituted_each(parts: &[Ty], bound: &collections::BTreeMap<String, Ty>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(substitute(part, bound)); }
    out
}

fn substituted_result(result: Option<&Ty>, bound: &collections::BTreeMap<String, Ty>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.substituted_in(bound)),
        None => None,
    }
}

pub fn qualify(ty: &Ty, module: &str, declared: &collections::BTreeSet<String>) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: qualified_name(name, module, declared), args: qualified_each(args, module, declared), view } },
        Ty::Tuple(parts) => Ty::Tuple(qualified_each(parts, module, declared)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: qualified_each(params, module, declared), result: Box::new(qualified_result((result).as_ref(), module, declared)), is_sync, can_throw } },
        _ => ty.clone(),
    }
}

fn qualified_name(name: &str, module: &str, declared: &collections::BTreeSet<String>) -> String {
    if declared.contains(name) { return format!("{}::{}", module, name); }
    name.to_owned()
}

fn qualified_each(parts: &[Ty], module: &str, declared: &collections::BTreeSet<String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(qualify(part, module, declared)); }
    out
}

fn qualified_result(result: Option<&Ty>, module: &str, declared: &collections::BTreeSet<String>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.qualified_in(module, declared)),
        None => None,
    }
}

pub fn renamed(ty: &Ty, renames: &collections::BTreeMap<String, String>) -> Ty {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; Ty::Named { name: renamed_name(name, renames), args: renamed_each(args, renames), view } },
        Ty::Tuple(parts) => Ty::Tuple(renamed_each(parts, renames)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; Ty::Fn { params: renamed_each(params, renames), result: Box::new(renamed_result((result).as_ref(), renames)), is_sync, can_throw } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); Ty::Nullable(Box::new(renamed(inner, renames))) },
        _ => ty.clone(),
    }
}

fn renamed_name(name: &str, renames: &collections::BTreeMap<String, String>) -> String {
    if name.starts_with('&') {
        let rest = cut(name, 1, 0);
        let path = renamed_path(&rest, renames);
        return format!("&{}", path);
    }
    renamed_path(name, renames)
}

fn renamed_path(name: &str, renames: &collections::BTreeMap<String, String>) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
    for at in 0..c.len() as i64 {
        if at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ':' && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == ':' {
            let package = between(&c, 0, at);
            if renames.contains_key(&package) {
                let ours = nikaia_std::index::or(*nikaia_std::index::get(&renames, &package), || "");
                let rest = between(&c, at, c.len() as i64);
                return format!("{}{}", ours, rest);
            }
            return name.to_owned();
        }
    }
    name.to_owned()
}

fn renamed_each(parts: &[Ty], renames: &collections::BTreeMap<String, String>) -> Vec<Ty> {
    let mut out: Vec<Ty> = vec![];
    for part in parts.iter() { out.push(renamed(part, renames)); }
    out
}

fn renamed_result(result: Option<&Ty>, renames: &collections::BTreeMap<String, String>) -> Option<Ty> {
    match result {
        Some(__nikaia_it) => Some(__nikaia_it.renamed_by(renames)),
        None => None,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MethodIndex {
    pub keys: collections::BTreeMap<String, Vec<String>>,
}

pub fn method_index(ledger: &Ledger) -> MethodIndex {
    let mut keys: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (key, _) in ledger.functions.iter() {
        let last = nikaia_std::index::or(key.rsplit("::").next(), || "").to_owned();
        let mut held = nikaia_std::index::or(keys.remove(&last), || vec![].into());
        held.push(key.to_owned());
        keys.insert(last, held);
    }
    MethodIndex { keys }
}

pub fn method_keys(index: &MethodIndex, method: &str) -> Vec<String> {
    let last = nikaia_std::index::or(method.rsplit("::").next(), || "");
    let bucket = match *nikaia_std::index::get(&index.keys, last) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    let suffix = format!("::{}", method);
    let mut out: Vec<String> = vec![];
    for key in bucket.iter() { if key.ends_with(&suffix) { out.push(key.to_owned()); } }
    out
}


// --- types.nika ---

const SHAPE_BOUNDS: [&str; 2] = ["Struct", "Enum"];

const STANDARD_BOUNDS: [&str; 2] = ["Eq", "Ord"];

const BUILT_IN: [&str; 28] = ["int", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64", "bool", "char", "scalar", "String", "str", "Self", "Vec", "Shared", "SharedMut", "Locked", "TaskHandle", "Array", "Bytes"];

const UNOFFERED_WIDTHS: [&str; 7] = ["usize", "isize", "i8", "i16", "u16", "i128", "u128"];

const STD_MODULES: [&str; 7] = ["cli", "collections", "channel", "foreign", "fs", "io", "time"];

pub fn types_checked(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger, library: &Ledger, declared: &collections::BTreeSet<String>, impl_parameters: &[Vec<String>], views: &collections::BTreeSet<String>) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    declared_once_in(names, items, &mut found);
    let known = known_names(own, library, declared);
    let traits = known_traits(names, items, own, library);
    let plain = types_plain_enums(names, items);
    for k in 0..items.len() as i64 {
        let mut here = known.to_owned();
        for parameter in generic_names(names, &nikaia_std::index::get(&items, (k) as usize).node) { here.insert(parameter); }
        for parameter in (*nikaia_std::index::get(&impl_parameters, (k) as usize)).iter() { here.insert(parameter.to_owned()); }
        bounds_of(names, &nikaia_std::index::get(&items, (k) as usize).node, &traits, &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
        item_types(names, &nikaia_std::index::get(&items, (k) as usize).node, &here, &plain, views, "", &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
        inherent_at_home(names, &nikaia_std::index::get(&items, (k) as usize).node, library, declared, &nikaia_std::index::get(&items, (k) as usize).span, &mut found);
    }
    found
}

fn inherent_at_home(names: &winnow_grammar::InternerContext, item: &Item, library: &Ledger, declared: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    let target = match item {
        Item::Impl { trait_name, target, .. } => { let trait_name = *trait_name; if trait_name.is_none() { names.resolve(target.name).to_owned() } else { return; } },
        _ => return,
    };
    if declared.contains(&target) || target == "Self" { return; }
    let foreign = target.contains("::") || nikaia_std::list::contains(&BUILT_IN, &target) || library.types.contains_key(&target);
    if !foreign { return; }
    out.push(refusal("NK1209", span.clone(), format!("You can't add methods to `{}` with `impl {}`: your program doesn't declare it.", target, target), vec![String::from("A type's own methods belong to the code that declares the type, so an `impl` without a trait works only on your own `struct` or `enum`.")], format!("Declare a trait and implement it for the type: `trait Doubled {{ fn doubled(self) -> ... }}` and `impl Doubled for {} {{ ... }}`.", target)));
}

fn known_traits(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger, library: &Ledger) -> collections::BTreeSet<String> {
    let mut known: collections::BTreeSet<String> = collections::BTreeSet::new();
    for shape in SHAPE_BOUNDS.iter() {
        let shape = *shape;
        known.insert(shape.to_owned());
    }
    for standard in STANDARD_BOUNDS.iter() {
        let standard = *standard;
        known.insert(standard.to_owned());
    }
    for (key, _) in own.traits.iter() { with_its_last_segment(key, &mut known); }
    for (key, _) in library.traits.iter() { with_its_last_segment(key, &mut known); }
    for item in items.iter() {
        match &item.node {
            Item::Trait { name, .. } => {
                let name = *name;
                known.insert(names.resolve(name).to_owned());
            },
            _ => { },
        }
    }
    known
}

fn with_its_last_segment(key: &str, known: &mut collections::BTreeSet<String>) {
    known.insert(key.to_owned());
    let c: Vec<scalar> = nikaia_std::list::chars(key.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    if last >= 0 { known.insert(slice(&c, last + 2, c.len() as i64)); }
}

fn known_names(own: &Ledger, library: &Ledger, declared: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut known: collections::BTreeSet<String> = collections::BTreeSet::new();
    for name in BUILT_IN.iter() {
        let name = *name;
        known.insert(name.to_owned());
    }
    for (key, _) in library.types.iter() { known.insert(key.to_owned()); }
    for (key, _) in own.types.iter() { with_its_last_segment(key, &mut known); }
    for name in declared.iter() { known.insert(name.to_owned()); }
    known
}

fn generic_names(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Fn { generics, .. } => { for parameter in generics.iter() { out.push(names.resolve(parameter.name).to_owned()); } },
        Item::Struct { generics, .. } => { for parameter in generics.iter() { out.push(names.resolve(parameter.name).to_owned()); } },
        _ => { },
    }
    out
}

fn bounds_of(names: &winnow_grammar::InternerContext, item: &Item, traits: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    match item {
        Item::Fn { generics, .. } => { bounds_in(names, generics, traits, span, out); },
        Item::Struct { generics, .. } => { bounds_in(names, generics, traits, span, out); },
        _ => { },
    }
}

fn bounds_in(names: &winnow_grammar::InternerContext, generics: &[GenericParam], traits: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) {
    for parameter in generics.iter() {
        for bound in parameter.bounds.iter() {
            let bound = *bound;
            let name = names.resolve(bound.to_owned()).to_owned();
            if !name.contains("::") && !traits.contains(&name) { out.push(refusal("NK1135", span.clone(), format!("There's no trait called `{}`.", name), vec![String::from("A bound names a trait the caller's type has to implement, and no trait by this name is declared.")], format!("Declare `{}` with `trait`, or remove the bound. (Without a bound, the value can only be moved and passed on.)", name))); }
        }
    }
}

fn declared_once_in(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], out: &mut Vec<Finding>) {
    let mut seen: collections::BTreeMap<String, &'static str> = collections::BTreeMap::new();
    for item in items.iter() {
        let kind = kind_declared(&item.node);
        if kind.is_empty() { continue; }
        let name = name_declared(names, &item.node);
        if name.is_empty() { continue; }
        let earlier: Option<String> = match *nikaia_std::index::get(&seen, &name) {
            Some(__nikaia_it) => Some(__nikaia_it.to_string()),
            None => None,
        };
        if earlier.is_none() {
            seen.insert(name, kind);
            continue;
        }
        let first = match earlier { Some(__nikaia_value) => __nikaia_value, None => continue };
        let kinds = if first == kind { format!("both times as a `{}`", first) } else { format!("once as a `{}` and once as a `{}`", first, kind) };
        out.push(refusal("NK1148", item.span.clone(), format!("`{}` is declared twice in this file, {}.", name, kinds), vec![String::from("A name means one thing, so there's never a question of which declaration wins. All files of a package share their names for the same reason.")], format!("Rename one of the two. (A `struct`'s name is already its constructor, so `{}` can't also be a function.)", name)));
    }
}

fn kind_declared(item: &Item) -> &'static str {
    match item {
        Item::Fn { name, .. } => { let name = *name; if name.is_some() { "fn" } else { "" } },
        Item::Struct { .. } => "struct",
        Item::Enum { .. } => "enum",
        Item::Trait { .. } => "trait",
        Item::Grammar(_) => "grammar",
        _ => "",
    }
}

fn name_declared(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; a_symbols_text(names, name) },
        Item::Struct { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Enum { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Trait { name, .. } => { let name = *name; names.resolve(name).to_owned() },
        Item::Grammar(def) => names.resolve(def.name).to_owned(),
        _ => String::from(""),
    }
}

fn a_symbols_text(names: &winnow_grammar::InternerContext, name: Option<winnow_grammar::Symbol>) -> String {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    names.resolve(symbol).to_owned()
}

#[allow(clippy::too_many_arguments)]
fn item_types(names: &winnow_grammar::InternerContext, item: &Item, known: &collections::BTreeSet<String>, plain: &collections::BTreeSet<String>, views: &collections::BTreeSet<String>, owner: &str, span: &Span, out: &mut Vec<Finding>) {
    match item {
        Item::Fn { name, args, config, ret_type, body, is_extern, .. } => {
            let is_extern = *is_extern; let name = *name;
            let mut key = owner.to_owned();
            if name.is_some() { key.push_str(names.resolve(match name { Some(__nikaia_value) => __nikaia_value, None => return })); } else { key.push_str("new"); }
            let mut at = 0;
            for arg in args.iter() {
                written_at(names, &arg.ty, known, true, span, out);
                widths_written(names, &arg.ty, is_extern, span, out);
                if !is_extern {
                    types_word_by_ref(names, &arg.ty, plain, "parameter", span, out);
                    types_text_by_ref(names, &arg.ty, "parameter", views, &format!("param {} {}", key, at), span, out);
                }
                at += 1;
            }
            for option in config.iter() {
                written_at(names, &option.ty, known, true, span, out);
                widths_written(names, &option.ty, is_extern, span, out);
                if !is_extern {
                    types_word_by_ref(names, &option.ty, plain, "parameter", span, out);
                    types_text_by_ref(names, &option.ty, "parameter", views, "", span, out);
                }
            }
            maybe_written(names, (ret_type).as_ref(), known, span, out);
            widths_written_maybe(names, (ret_type).as_ref(), is_extern, span, out);
            if !is_extern {
                types_word_by_ref_maybe(names, (ret_type).as_ref(), plain, span, out);
                types_text_by_ref_maybe(names, (ret_type).as_ref(), "result", views, &format!("result {}", key), span, out);
            }
            block_types(names, body, known, views, plain, out);
        },
        Item::Struct { name, fields, is_extern, .. } => {
            let is_extern = *is_extern; let name = *name;
            let of = names.resolve(name).to_owned();
            for field in fields.iter() {
                written_at(names, &field.ty, known, false, span, out);
                widths_written(names, &field.ty, is_extern, span, out);
                types_word_by_ref(names, &field.ty, plain, "field", span, out);
                if !is_extern { types_text_by_ref(names, &field.ty, "field", views, &format!("field {} {}", of, names.resolve(field.name)), span, out); }
            }
        },
        Item::Enum { name, variants, is_extern, .. } => {
            let is_extern = *is_extern; let name = *name;
            let of = names.resolve(name).to_owned();
            for variant in variants.iter() {
                match &variant.fields {
                    VariantFields::Unit => { },
                    VariantFields::Tuple(parts) => {
                        let mut at = 0;
                        for ty in parts.iter() {
                            written_at(names, ty, known, false, span, out);
                            widths_written(names, ty, false, span, out);
                            if !is_extern { types_text_by_ref(names, ty, "payload", views, &format!("variant {} {} {}", of, names.resolve(variant.name), at), span, out); }
                            at += 1;
                        }
                    },
                    VariantFields::Named(fields) => {
                        for field in fields.iter() {
                            written_at(names, &field.ty, known, false, span, out);
                            widths_written(names, &field.ty, false, span, out);
                        }
                    },
                }
            }
        },
        Item::Extern { declarations, .. } => {
            for declaration in declarations.iter() {
                for arg in declaration.node.args.iter() {
                    written_foreign(names, &arg.ty, known, true, &declaration.span, out);
                    widths_written(names, &arg.ty, true, &declaration.span, out);
                }
                maybe_written_foreign(names, (declaration.node.ret_type).as_ref(), known, &declaration.span, out);
                widths_written_maybe(names, (declaration.node.ret_type).as_ref(), true, &declaration.span, out);
            }
        },
        Item::Trait { methods, .. } => {
            for method in methods.iter() {
                let mut here = known.to_owned();
                for parameter in method.node.generics.iter() { here.insert(names.resolve(parameter.name).to_owned()); }
                for arg in method.node.args.iter() {
                    written_at(names, &arg.ty, &here, true, &method.span, out);
                    widths_written(names, &arg.ty, false, &method.span, out);
                    types_word_by_ref(names, &arg.ty, plain, "parameter", &method.span, out);
                    types_text_by_ref(names, &arg.ty, "parameter", views, "", &method.span, out);
                }
                maybe_written(names, (method.node.ret_type).as_ref(), &here, &method.span, out);
                widths_written_maybe(names, (method.node.ret_type).as_ref(), false, &method.span, out);
                types_word_by_ref_maybe(names, (method.node.ret_type).as_ref(), plain, &method.span, out);
                types_text_by_ref_maybe(names, (method.node.ret_type).as_ref(), "result", views, "", &method.span, out);
            }
        },
        Item::Impl { target, methods, .. } => {
            let prefix = format!("{}::", names.resolve(target.name));
            for method in methods.iter() {
                let mut here = known.to_owned();
                for parameter in generic_names(names, &method.node) { here.insert(parameter); }
                item_types(names, &method.node, &here, plain, views, &prefix, &method.span, out);
            }
        },
        _ => { },
    }
}

fn types_word_by_ref(names: &winnow_grammar::InternerContext, ty: &Type, plain: &collections::BTreeSet<String>, position: &str, span: &Span, out: &mut Vec<Finding>) {
    for inner in ty.generics.iter() { types_word_by_ref(names, inner, plain, "type argument", span, out); }
    if (*ty.code).is_some() {
        let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
        types_word_by_ref_maybe(names, (*code.result).as_ref(), plain, span, out);
    }
    types_word_by_ref_here(names, ty, plain, position, span, out);
}

fn types_word_by_ref_here(names: &winnow_grammar::InternerContext, ty: &Type, plain: &collections::BTreeSet<String>, position: &str, span: &Span, out: &mut Vec<Finding>) {
    if !ty.is_view || ty.is_mut || ty.is_slice || ty.is_tuple || !ty.generics.is_empty() { return; }
    let name = names.resolve(ty.name).to_owned();
    let words = vec!["int", "i8", "i16", "i32", "i64", "i128", "u8", "u16", "u32", "u64", "u128", "isize", "usize", "f32", "f64", "bool", "scalar"];
    let mut a_word = plain.contains(&name);
    for word in words.iter() {
        let word = *word;
        if word == name { a_word = true; }
    }
    if !a_word { return; }
    let mut written = name.to_owned();
    if ty.is_nullable { written = format!("{}?", name); }
    out.push(refusal("NK1257", span.clone(), format!("A `{}` is copied at a read, so a {} can't be a `ref {}`.", name, position, written), vec!["A number, a `bool`, a `scalar` and an enum whose variants hold nothing are copied at a read (ADR-279 D8): the copy is never dearer than a pointer, so `ref` on one says nothing. Only an `extern \"C\"` declaration writes it, as the pointer C expects.".to_owned()], format!("Write `{}` without `ref`; a parameter the function changes is `mut name: {}`.", written, written)));
}

fn types_word_by_ref_maybe(names: &winnow_grammar::InternerContext, ty: Option<&Type>, plain: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { types_word_by_ref(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, plain, "result", span, out); }

fn types_text_by_ref(names: &winnow_grammar::InternerContext, ty: &Type, position: &str, views: &collections::BTreeSet<String>, key: &str, span: &Span, out: &mut Vec<Finding>) {
    if views.contains(key) { return; }
    if !ty.is_view || ty.is_mut || ty.is_slice || ty.is_tuple || !ty.generics.is_empty() { return; }
    if names.resolve(ty.name) != "String" { return; }
    let mut written: &'static str = "String";
    if ty.is_nullable { written = "String?"; }
    out.push(Finding { code: String::from("NK1261"), span: span.clone(), message: format!("`ref` is redundant here: a {} written `ref {}` says what `{}` already says.", position, written, written), notes: vec!["Text is a view wherever a view suffices, and the ledger records whether a published parameter is lent or kept and what a result points into (ADR-282 D2). Only an `extern \"C\"` declaration and a `pub extern fn` write `ref String`, as the pointer C expects.".to_owned()], help: Some(format!("Write `{}` without `ref`.", written)), warning: true, labels: vec![] });
}

fn types_text_by_ref_maybe(names: &winnow_grammar::InternerContext, ty: Option<&Type>, position: &str, views: &collections::BTreeSet<String>, key: &str, span: &Span, out: &mut Vec<Finding>) { types_text_by_ref(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, position, views, key, span, out); }

fn types_plain_enums(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut plain: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut holds = false;
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        _ => { holds = true; },
                    }
                }
                if !holds { plain.insert(names.resolve(name).to_owned()); }
            },
            _ => { },
        }
    }
    plain
}

fn widths_written(names: &winnow_grammar::InternerContext, ty: &Type, at_c: bool, span: &Span, out: &mut Vec<Finding>) {
    let name = names.resolve(ty.name).to_owned();
    if at_c && name == "int" {
        out.push(refusal("NK1262", span.clone(), String::from("`int` can't be written where C sees the value."), vec![String::from("An `int` holds the values of an `i64`, but how it is stored is the compiler's choice (ADR-285 D37); C reads the bytes, so the width has to be written.")], String::from("Write `i64` here, or the fixed width the C side declares.")));
        return;
    }
    if !at_c && nikaia_std::list::contains(&UNOFFERED_WIDTHS, &name) {
        out.push(refusal("NK1135", span.clone(), format!("There's no type called `{}`.", name), vec![String::from("Nikaia's integers are `int` and the fixed widths `i64`, `i32`, `u8`, `u32` and `u64` (Part I 2.2); Rust's other widths are written only in an `extern \"C\"` declaration.")], String::from("Write `int` for an ordinary number, or the fixed width that holds the values.")));
        return;
    }
    for argument in ty.generics.iter() { widths_written(names, argument, at_c, span, out); }
    widths_written_maybe(names, (*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), at_c, span, out);
}

fn widths_written_maybe(names: &winnow_grammar::InternerContext, ty: Option<&Type>, at_c: bool, span: &Span, out: &mut Vec<Finding>) { widths_written(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, at_c, span, out); }

fn maybe_written(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_at(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

fn maybe_written_foreign(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_foreign(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

fn block_types(names: &winnow_grammar::InternerContext, block: &Block, known: &collections::BTreeSet<String>, views: &collections::BTreeSet<String>, plain: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, value, .. } => {
                maybe_written(names, (ty).as_ref(), known, &stmt.span, out);
                types_text_by_ref_maybe(names, (ty).as_ref(), "`let`", views, &format!("let {}", stmt.span.start), &stmt.span, out);
                widths_written_maybe(names, (ty).as_ref(), false, &stmt.span, out);
                if ty.is_some() {
                    let annotated: &Type = match ty { Some(__nikaia_value) => __nikaia_value, None => continue };
                    for inner in annotated.generics.iter() { types_word_by_ref(names, inner, plain, "type argument", &stmt.span, out); }
                }
                blocks_types(names, value, known, views, plain, out);
            },
            Stmt::Comptime { value, .. } => { blocks_types(names, value, known, views, plain, out); },
            Stmt::Expr(value) => { blocks_types(names, value, known, views, plain, out); },
            Stmt::Return(value) => { blocks_types(names, match value { Some(__nikaia_value) => __nikaia_value, None => continue }, known, views, plain, out); },
            Stmt::Assign { target, value, .. } => {
                blocks_types(names, target, known, views, plain, out);
                blocks_types(names, value, known, views, plain, out);
            },
            Stmt::For { body, .. } => { block_types(names, body, known, views, plain, out); },
            Stmt::While { body, .. } => { block_types(names, body, known, views, plain, out); },
            _ => { },
        }
    }
}

fn blocks_types(names: &winnow_grammar::InternerContext, expr: &Expr, known: &collections::BTreeSet<String>, views: &collections::BTreeSet<String>, plain: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    match expr {
        Expr::Block(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Unsafe(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Overlap(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Closure { body, .. } => { block_types(names, body, known, views, plain, out); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            blocks_types(names, func, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            block_types(names, then_branch, known, views, plain, out);
            block_types(names, match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, known, views, plain, out);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            blocks_types(names, expr, known, views, plain, out);
            block_types(names, handler, known, views, plain, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { blocks_types(names, &arm.body, known, views, plain, out); } },
        Expr::Select(arms, _) => { for arm in arms.iter() { block_types(names, &arm.body, known, views, plain, out); } },
        _ => { },
    }
}

fn written_foreign(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_slice && !ty.generics.is_empty() {
        written_at(names, nikaia_std::index::get(&ty.generics, 0), known, false, span, out);
        return;
    }
    written_at_the_boundary(names, ty, known, a_parameter, true, span, out);
}

fn written_at(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) { written_at_the_boundary(names, ty, known, a_parameter, false, span, out); }

fn written_at_the_boundary(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, at_c: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_mut && !at_c {
        out.push(refusal("NK1158", span.clone(), String::from("`ref mut` can only be used when talking to C."), vec![String::from("`ref mut` is only for `extern \"C\"` declarations. Everywhere else, Nikaia has its own way to say it.")], String::from("Put `mut` in front of the name instead: `fn fill(mut out: Vec[i64])`.")));
        return;
    }
    let name = names.resolve(ty.name).to_owned();
    if name == "char" {
        out.push(refusal("NK1135", span.clone(), String::from("There's no type called `char`."), vec![String::from("One Unicode character is a `scalar`, and one byte of text is a `u8`: which of the two a character is depends on how the text is read (Part I 2.6).")], String::from("Write `scalar` for a character, or `u8` for a byte.")));
        return;
    }
    if !a_parameter && !ty.is_view && !ty.is_slice && ty.count.is_none() && ty.generics.len() == 1 && name == "Array" {
        let element = names.resolve(nikaia_std::index::get(&ty.generics, 0).name).to_owned();
        out.push(refusal("NK1182", span.clone(), format!("`Array[{}]` needs a length here.", element), vec![format!("`Array[{}]` without a length only works for a parameter, where each call supplies the length. A field or a result has no call to take it from.", element)], format!("Use `Vec[{}]` for a list that can grow, `ref Array[{}]` to look at elements something else keeps, or `Array[{}, N]` to write the length down.", element, element, element)));
        return;
    }
    if ty.count.is_some() { return; }
    if ty.is_slice {
        for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
        return;
    }
    if !ty.is_tuple && (*ty.code).is_none() && !known.contains(&name) && !name.contains("::") { out.push(nothing_declares(&name, known, span)); }
    for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
    maybe_written(names, (*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), known, span, out);
}

fn nothing_declares(name: &str, known: &collections::BTreeSet<String>, span: &Span) -> Finding {
    let module = std_module_of(name, known);
    if !module.is_empty() { return refusal("NK1135", span.clone(), format!("`{}` needs its module in front of it.", name), vec![format!("Its full name is `{}::{}`: a type from a module is written with the module's name.", module, name)], format!("Write `use std::{}` at the top of the file, and `{}::{}` here.", module, module, name)); }
    refusal("NK1135", span.clone(), format!("There's no type called `{}`.", name), vec![String::from("A type is either built in, declared in your program with `struct` or `enum`, provided by `std`, or a type parameter.")], format!("Check the spelling, or declare `{}` with `struct` or `enum`.", name))
}

pub fn nobody_knows(name: &str, own: &Ledger, library: &Ledger) -> bool {
    if nikaia_std::list::contains(&BUILT_IN, &name) || own.types.contains_key(name) || library.types.contains_key(name) { return false; }
    let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    let wanted = if last < 0 { format!("::{}", name) } else { format!("{}::", slice(&c, 0, last)) };
    for ledger in [own, library] {
        for (key, _) in ledger.types.iter() { if last < 0 && key.ends_with(&wanted) || last >= 0 && key.starts_with(&wanted) { return false; } }
        for (key, _) in ledger.functions.iter() { if last >= 0 && key.starts_with(&wanted) { return false; } }
    }
    true
}

fn std_module_of(name: &str, known: &collections::BTreeSet<String>) -> String {
    let ending = format!("::{}", name);
    for key in known.iter() {
        if key.ends_with(&ending) {
            let c: Vec<scalar> = nikaia_std::list::chars(key.chars());
            let at = find_text(&c, 0, "::");
            let module = slice(&c, 0, at);
            for one in STD_MODULES.iter() {
                let one = *one;
                if module == one { return module; }
            }
            return String::from("");
        }
    }
    String::from("")
}


// --- views.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Stored {
    pub span: Span,
    pub param: String,
    pub ty: String,
    pub function: String,
    pub subject: Option<String>,
    pub into: Destination,
    pub carried: bool,
    pub method: u32,
    pub symbol: winnow_grammar::Symbol,
    pub carrier: Option<winnow_grammar::Symbol>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Destination {
    Field { owner: String, field: String, ty: String },
    Subject { owner: String },
    Task,
    ParamField { param: winnow_grammar::Symbol, owner: String, field: String, ty: String },
}

#[derive(Debug, Clone)]
pub struct Asked<'a, 'a1, 'a2> {
    pub names: &'a winnow_grammar::InternerContext,
    pub own: &'a1 Ledger,
    pub library: &'a2 Ledger,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Unit {
    borrowing: collections::BTreeSet<String>,
    fields: collections::BTreeMap<String, Vec<(String, Type)>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Here {
    subject: Option<Type>,
    subject_fields: Vec<(String, Type)>,
    declared: Vec<(winnow_grammar::Symbol, Type)>,
    ours: Option<String>,
    carriers: collections::BTreeSet<String>,
    found: Vec<(Span, Destination)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Root {
    Subject,
    SubjectField(String),
    Param(winnow_grammar::Symbol),
    ParamField(winnow_grammar::Symbol, String),
    Elsewhere,
}

pub fn views_stored(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<Stored> {
    let unit = Unit { borrowing: borrowing_types(asked.names, items), fields: view_fields(asked.names, items) };
    let mut found: Vec<Stored> = vec![];
    let nothing: Option<Type> = None;
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => { scan(&unit, asked, (nothing).as_ref(), item.span.start, &item.node, own_buffer, &mut found); },
            Item::Impl { target, methods, .. } => {
                let subject: Option<Type> = Some(target.clone());
                for method in methods.iter() { scan(&unit, asked, (subject).as_ref(), method.span.start, &method.node, own_buffer, &mut found); }
            },
            _ => { },
        }
    }
    in_source_order(&found)
}

pub fn views_checked(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<Finding> {
    let mut out: Vec<Finding> = vec![];
    for stored in views_stored(asked, items, own_buffer) { if !stored.carried { out.push(finding(&stored)); } }
    rsrc_findings(asked, items, own_buffer, &mut out);
    out
}

fn in_source_order(found: &[Stored]) -> Vec<Stored> {
    let mut out: Vec<Stored> = vec![];
    for stored in found.iter() {
        let mut at = out.len() as i64;
        while at > 0 && nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).span.start > stored.span.start { at -= 1; }
        out.insert(nikaia_std::count::of(at), stored.clone());
    }
    out
}

fn finding(stored: &Stored) -> Finding {
    let param = stored.param.to_owned();
    let written = stored.ty.to_owned();
    let function = stored.function.to_owned();
    let where_it_goes = match &stored.into {
        Destination::Field { owner, field, .. } => format!("`{}.{}`", owner, field),
        Destination::ParamField { owner, field, .. } => format!("`{}.{}`", owner, field),
        Destination::Subject { owner } => format!("`{}`, through a call on it", owner),
        Destination::Task => String::from("a task, which goes on running after the call"),
    };
    let why = match &stored.into {
        Destination::ParamField { owner, field, .. } => format!("`{}.{}` belongs to a struct that was passed in, and this function stores into more than one such struct, so it's unclear whose data `{}` points into.", owner, field, param),
        Destination::Field { owner, field, ty } => format!("`{}.{}` is a `{}`, so it points into some data, but `{}: {}` doesn't say whose.", owner, field, ty, param, written),
        Destination::Subject { owner } => format!("A call on `{}` might keep what it's given, and nothing says it doesn't, so `{}` counts as kept.", owner, param),
        Destination::Task => String::from("A task keeps running after the call that started it, so anything it looks at has to live longer than the call."),
    };
    let of = of_what((stored.subject).as_deref(), &function);
    let mut help: String = String::from("Put the view in a struct and pass the struct, so its declaration says whose data it is (like `Reading` in `examples/1brc.nika`):\n           struct Held { ");
    help.push_str(&format!("{}: {}", param, written));
    help.push_str(" }\n           …\n           fn ");
    help.push_str(&format!("{}(…, held: Held)", function));
    help.push_str(" { … held.");
    help.push_str(&param);
    help.push_str(" … }\n       Or keep a copy of the text with `.clone()`, which costs one allocation.");
    refusal("NK2302", stored.span.clone(), format!("{} keeps `{}` after this call, but `{}: {}` doesn't say whose data it points into.", of, param, param, written), vec![format!("It's stored in {}.", where_it_goes), why], help)
}

fn of_what(subject: Option<&str>, function: &str) -> String {
    let owner = match subject { Some(__nikaia_value) => __nikaia_value, None => return format!("`{}`", function) };
    format!("`{}.{}`", owner, function)
}

fn package_borrowing_types(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut borrowing = borrowing_types(asked.names, items);
    for (name, described) in asked.own.types.iter() { if !described.tethered.is_empty() { borrowing.insert(name.to_owned()); } }
    borrowing
}

fn borrowing_types(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut types_of: Vec<(String, Vec<Type>)> = vec![];
    let mut borrowing: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut types: Vec<Type> = vec![];
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        VariantFields::Tuple(written) => { for ty in written.iter() { types.push(ty.clone()); } },
                        VariantFields::Named(declared) => { for field in declared.iter() { types.push(field.ty.clone()); } },
                    }
                }
                a_shape(names.resolve(name).to_owned(), types, &mut borrowing, &mut types_of);
            },
            Item::Struct { name, fields, .. } => {
                let name = *name;
                let mut types: Vec<Type> = vec![];
                for field in fields.iter() { types.push(field.ty.clone()); }
                a_shape(names.resolve(name).to_owned(), types, &mut borrowing, &mut types_of);
            },
            _ => { },
        }
    }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, types) in types_of.iter() {
            if !borrowing.contains(name) && any_names_borrowing(names, types, &borrowing) {
                borrowing.insert(name.to_owned());
                changed = true;
            }
        }
    }
    borrowing
}

fn a_shape(name: String, types: Vec<Type>, borrowing: &mut collections::BTreeSet<String>, types_of: &mut Vec<(String, Vec<Type>)>) {
    for ty in types.iter() { if holds_view(ty) { borrowing.insert(name.to_owned()); } }
    types_of.push((name, types));
}

fn any_names_borrowing(names: &winnow_grammar::InternerContext, types: &[Type], borrowing: &collections::BTreeSet<String>) -> bool {
    for ty in types.iter() { if names_borrowing(names, ty, borrowing) { return true; } }
    false
}

pub fn holds_view(ty: &Type) -> bool {
    let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return holds_view_written(ty) };
    let result = match (*code.result).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    if views_the_call_s(ty, 0) { return false; }
    holds_view(result)
}

pub fn views_the_call_s(ty: &Type, borrowing: i64) -> bool {
    let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !code.is_sync { return false; }
    let mut lent = borrowing;
    for part in ty.generics.iter() { if holds_view(part) { lent += 1; } }
    lent > 1
}

fn holds_view_written(ty: &Type) -> bool {
    if ty.is_view && !ty.lasting { return true; }
    for inner in ty.generics.iter() { if holds_view(inner) { return true; } }
    false
}

fn names_borrowing(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> bool {
    if (*ty.code).is_some() {
        let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        let result = match (*code.result).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
        let mut named: i64 = 0;
        for part in ty.generics.iter() { if !holds_view(part) && names_borrowing(names, part, borrowing) { named += 1; } }
        if views_the_call_s(ty, named) { return false; }
        return names_borrowing(names, result, borrowing);
    }
    if borrowing.contains(names.resolve(ty.name)) { return true; }
    for inner in ty.generics.iter() { if names_borrowing(names, inner, borrowing) { return true; } }
    false
}

fn brings_buffer(unit: &Unit, asked: &Asked<'_, '_, '_>, ty: &Type) -> bool { holds_view(ty) || names_borrowing(asked.names, ty, &unit.borrowing) }

fn view_fields(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeMap<String, Vec<(String, Type)>> {
    let mut out: collections::BTreeMap<String, Vec<(String, Type)>> = collections::BTreeMap::new();
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, fields, .. } => {
                let name = *name;
                let mut declared: Vec<(String, Type)> = vec![];
                for field in fields.iter() { declared.push((names.resolve(field.name).to_owned(), field.ty.clone())); }
                out.insert(names.resolve(name).to_owned(), declared);
            },
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut carried: Vec<(String, Type)> = vec![];
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        VariantFields::Tuple(written) => { for i in 0..written.len() as i64 { carried.push((format!("{}", i), (*nikaia_std::index::get(&written, (i) as usize)).clone())); } },
                        VariantFields::Named(declared) => { for field in declared.iter() { carried.push((names.resolve(field.name).to_owned(), field.ty.clone())); } },
                    }
                }
                out.insert(names.resolve(name).to_owned(), carried);
            },
            _ => { },
        }
    }
    out
}

pub fn written_type(names: &winnow_grammar::InternerContext, ty: &Type) -> String {
    let mut out: String = String::from("");
    if ty.is_view {
        out.push_str("ref ");
        if ty.is_mut { out.push_str("mut "); }
    }
    let mut parts: Vec<String> = vec![];
    for inner in ty.generics.iter() { parts.push(written_type(names, inner)); }
    let joined = parts.join(", ");
    if ty.is_tuple {
        out.push_str(&format!("({})", joined));
        return out;
    }
    let name = names.resolve(ty.name);
    if ty.is_view && name == "str" { out.push_str(TEXT); } else { out.push_str(name); }
    if !parts.is_empty() { out.push_str(&format!("[{}]", joined)); }
    out
}

fn scan(unit: &Unit, asked: &Asked<'_, '_, '_>, target: Option<&Type>, method: u32, item: &Item, own_buffer: &impl Fn(&Expr) -> bool, out: &mut Vec<Stored>) {
    match item {
        Item::Fn { name, receiver, args, config, ret_type, body, .. } => {
            let name = *name;
            let mut declared: Vec<(winnow_grammar::Symbol, Type)> = vec![];
            for arg in args.iter() { declared.push((arg.name, arg.ty.clone())); }
            for option in config.iter() { declared.push((option.name, option.ty.clone())); }
            let mut any_view = false;
            for (_, ty) in declared.iter() { if ty.is_view { any_view = true; } }
            if !any_view { return; }
            let result_holds_view = buffered(unit, asked, (ret_type).as_ref());
            let subject_names_a_buffer = named_in(asked, target, &unit.borrowing);
            let subject_name = text_of(asked, target);
            let function = function_name(asked.names, name);
            let subject_fields = fields_of_type(unit, asked, target);
            for (param, ty) in declared.iter() {
                let param = *param;
                if !ty.is_view { continue; }
                let param_name = asked.names.resolve(param).to_owned();
                let mut carriers: collections::BTreeSet<String> = collections::BTreeSet::new();
                carriers.insert(param_name.to_owned());
                let mut here = Here { subject: match target {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }, subject_fields: subject_fields.to_owned(), declared: declared.to_owned(), ours: if result_holds_view { text_of(asked, (ret_type).as_ref()) } else { None }, carriers, found: vec![] };
                walk_block(unit, asked, body, true, own_buffer, &mut here);
                one_answer(asked, &here, param, Scanned { param: param_name, ty: written_type(asked.names, ty), function: function.to_owned(), subject: match subject_name.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, method, names_a_buffer: subject_names_a_buffer }, out);
            }
        },
        _ => { },
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Scanned {
    param: String,
    ty: String,
    function: String,
    subject: Option<String>,
    method: u32,
    names_a_buffer: bool,
}

fn one_answer(asked: &Asked<'_, '_, '_>, here: &Here, symbol: winnow_grammar::Symbol, signed: Scanned, out: &mut Vec<Stored>) {
    let mut carriers: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut carrier: Option<winnow_grammar::Symbol> = None;
    for (_, into) in here.found.iter() {
        match into {
            Destination::ParamField { param, .. } => {
                let param = *param;
                if carriers.insert(asked.names.resolve(param).to_owned()) && carrier.is_none() { carrier = Some(param); }
            },
            _ => { },
        }
    }
    let one_carrier = carriers.len() == 1 && !signed.names_a_buffer;
    let mut unreached: Vec<(Span, Destination)> = vec![];
    let mut reached: Vec<(Span, Destination)> = vec![];
    for (span, into) in here.found.iter() {
        let span = *span;
        if covered_by_the_subject(signed.names_a_buffer, into) || one_carrier && a_param_field(into) { reached.push((span.clone(), into.clone())); } else { unreached.push((span.clone(), into.clone())); }
    }
    let carried = unreached.is_empty();
    let candidates = if carried { reached } else { unreached };
    if candidates.is_empty() { return; }
    let mut best: i64 = 0;
    for i in 1..candidates.len() as i64 {
        let rank_i = rank(&nikaia_std::index::get(&candidates, (i) as usize).1);
        let rank_best = rank(&nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).1);
        if rank_i < rank_best || rank_i == rank_best && nikaia_std::index::get(&candidates, (i) as usize).0.start < nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).0.start { best = i; }
    }
    out.push(Stored { span: nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).0.clone(), param: signed.param, ty: signed.ty, function: signed.function, subject: signed.subject, into: nikaia_std::index::get(&candidates, nikaia_std::index::at(best)).1.clone(), carried, method: signed.method, symbol, carrier: if one_carrier && carried { carrier } else { None } });
}

fn a_param_field(into: &Destination) -> bool { matches!(into, Destination::ParamField { .. }) }

fn covered_by_the_subject(subject_names_a_buffer: bool, into: &Destination) -> bool { subject_names_a_buffer && matches!(into, Destination::Field { .. } | Destination::Subject { .. }) }

fn rank(into: &Destination) -> i64 {
    match into {
        Destination::Field { .. } => 0,
        Destination::Subject { .. } => 1,
        Destination::Task => 2,
        Destination::ParamField { .. } => 0,
    }
}

fn takes_a_view_of_itself(receiver: Option<&Receiver>) -> bool {
    let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => return false };
    taken.is_ref
}

fn buffered(unit: &Unit, asked: &Asked<'_, '_, '_>, ty: Option<&Type>) -> bool { brings_buffer(unit, asked, match ty { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn rsrc_unknown_named(unit: &Unit, asked: &Asked<'_, '_, '_>, ty: &Type) -> bool {
    if (*ty.code).is_some() { return false; }
    let written = asked.names.resolve(ty.name).to_owned();
    let mut name = written.to_owned();
    let segments: Vec<&str> = written.split("::").collect::<Vec<_>>();
    if segments.len() > 1 { name = (*nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1))).to_owned(); }
    let first: Vec<scalar> = nikaia_std::list::chars(name.chars());
    let a_word = !first.is_empty() && (*nikaia_std::index::get(&first, 0)).is_alphabetic();
    if a_word && !rsrc_plain_name(&name) && name != "Self" && !unit.fields.contains_key(&name) {
        if asked.own.types.contains_key(&name) {
            let described = match match *nikaia_std::index::get(&asked.own.types, &name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => return true };
            if !described.tethered.is_empty() { return true; }
        } else if asked.library.types.contains_key(&name) {
            let described = match match *nikaia_std::index::get(&asked.library.types, &name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => return true };
            if !described.tethered.is_empty() { return true; }
        } else if name.len() > 1 { return true; }
    }
    for inner in ty.generics.iter() { if rsrc_unknown_named(unit, asked, inner) { return true; } }
    false
}

fn named_in(asked: &Asked<'_, '_, '_>, ty: Option<&Type>, borrowing: &collections::BTreeSet<String>) -> bool {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    borrowing.contains(asked.names.resolve(named.name))
}

fn text_of(asked: &Asked<'_, '_, '_>, ty: Option<&Type>) -> Option<String> {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(asked.names.resolve(named.name).to_owned())
}

fn function_name(names: &winnow_grammar::InternerContext, name: Option<winnow_grammar::Symbol>) -> String {
    let named = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("new") };
    names.resolve(named).to_owned()
}

fn fields_of_type(unit: &Unit, asked: &Asked<'_, '_, '_>, ty: Option<&Type>) -> Vec<(String, Type)> {
    let named = match ty { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, asked.names.resolve(named.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into())
}

fn walk_block(unit: &Unit, asked: &Asked<'_, '_, '_>, block: &Block, tail: bool, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    let count = block.stmts.len() as i64;
    for i in 0..count {
        let returning = tail && i + 1 == count;
        let span = nikaia_std::index::get(&block.stmts, nikaia_std::index::at(i)).span.clone();
        match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(i)).node {
            Stmt::Let { names, value, .. } => {
                if mentions(unit, asked, &here, value) && !own_buffer(value) {
                    for name in names.iter() {
                        let name = *name;
                        here.carriers.insert(asked.names.resolve(name).to_owned());
                    }
                }
                if views_a_local_struct(asked, block, i, names, value, (here.ours).as_deref()) { descend(unit, asked, value, &span, own_buffer, here); } else { stores(unit, asked, value, &span, own_buffer, here); }
            },
            Stmt::Comptime { name, value, .. } => {
                let name = *name;
                if mentions(unit, asked, &here, value) { here.carriers.insert(asked.names.resolve(name).to_owned()); }
                stores(unit, asked, value, &span, own_buffer, here);
            },
            Stmt::Assign { target, value, .. } => {
                if mentions(unit, asked, &here, value) {
                    match target {
                        Expr::Variable(name, _) => {
                            let name = *name;
                            here.carriers.insert(asked.names.resolve(name).to_owned());
                        },
                        _ => { assigned(unit, asked, target, &span, here); },
                    }
                }
                stores(unit, asked, target, &span, own_buffer, here);
                stores(unit, asked, value, &span, own_buffer, here);
            },
            Stmt::Return(value) => { handed_back_maybe(unit, asked, (value).as_ref(), &span, own_buffer, here); },
            Stmt::Expr(expr) => { if returning { handed_back(unit, asked, expr, &span, own_buffer, here); } else { stores(unit, asked, expr, &span, own_buffer, here); } },
            Stmt::For { bindings, iter, body, .. } => {
                if mentions(unit, asked, &here, iter) {
                    for binding in bindings.iter() {
                        let binding = *binding;
                        here.carriers.insert(asked.names.resolve(binding).to_owned());
                    }
                }
                stores(unit, asked, iter, &span, own_buffer, here);
                walk_block(unit, asked, body, false, own_buffer, here);
            },
            Stmt::While { cond, body } => {
                stores(unit, asked, cond, &span, own_buffer, here);
                walk_block(unit, asked, body, false, own_buffer, here);
            },
            Stmt::Break => { },
            Stmt::Continue => { },
        }
    }
}

fn views_a_local_struct(asked: &Asked<'_, '_, '_>, block: &Block, at: i64, names: &[winnow_grammar::Symbol], value: &Expr, ours: Option<&str>) -> bool {
    let literal = match value {
        Expr::StructLit { name, .. } => { let name = *name; asked.names.resolve(name).to_owned() },
        _ => return false,
    };
    if names.len() != 1 { return false; }
    let handed = local_struct_handed_back(asked.names, block, at, asked.names.resolve(*nikaia_std::index::get(&names, 0)));
    if handed == 0 { return true; }
    let result = match ours { Some(__nikaia_value) => __nikaia_value, None => return false };
    handed > 0 && result == literal
}

pub fn local_struct_handed_back(names: &winnow_grammar::InternerContext, block: &Block, at: i64, name: &str) -> i64 {
    let mut uses: i64 = 0;
    let mut through: i64 = 0;
    let mut handed: i64 = 0;
    for j in at + 1..block.stmts.len() as i64 {
        if returns_named(names, &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(j)).node, name) { handed += 1; }
        for each in visited_in_stmt(&nikaia_std::index::get(&block.stmts, nikaia_std::index::at(j)).node) {
            match each {
                Expr::Variable(n, _) => {
                    let n = *n;
                    if names.resolve(n) == name { uses += 1; }
                },
                Expr::Field { base, .. } => {
                    let base = nikaia_std::boxed::open(base);
                    if a_variable_named(names, base, name) { through += 1; }
                },
                Expr::SafeField { base, .. } => {
                    let base = nikaia_std::boxed::open(base);
                    if a_variable_named(names, base, name) { through += 1; }
                },
                _ => { },
            }
        }
    }
    if uses != through + handed { return -1; }
    handed
}

fn returns_named(names: &winnow_grammar::InternerContext, stmt: &Stmt, name: &str) -> bool {
    match stmt {
        Stmt::Return(value) => returns_variable(names, (value).as_ref(), name),
        _ => false,
    }
}

fn returns_variable(names: &winnow_grammar::InternerContext, value: Option<&Expr>, name: &str) -> bool {
    let back = match value { Some(__nikaia_value) => __nikaia_value, None => return false };
    a_variable_named(names, back, name)
}

fn a_variable_named(names: &winnow_grammar::InternerContext, expr: &Expr, name: &str) -> bool {
    match expr {
        Expr::Variable(n, _) => { let n = *n; names.resolve(n) == name },
        _ => false,
    }
}

fn handed_back_maybe(unit: &Unit, asked: &Asked<'_, '_, '_>, value: Option<&Expr>, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    let handed = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    handed_back(unit, asked, handed, span, own_buffer, here);
}

fn handed_back(unit: &Unit, asked: &Asked<'_, '_, '_>, value: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match value {
        Expr::StructLit { name, .. } => {
            let name = *name;
            if ours_is(asked, (here.ours).as_deref(), name) { descend(unit, asked, value, span, own_buffer, here); } else { stores(unit, asked, value, span, own_buffer, here); }
        },
        _ => { stores(unit, asked, value, span, own_buffer, here); },
    }
}

fn ours_is(asked: &Asked<'_, '_, '_>, ours: Option<&str>, name: winnow_grammar::Symbol) -> bool {
    let named = match ours { Some(__nikaia_value) => __nikaia_value, None => return false };
    named == asked.names.resolve(name)
}

fn assigned(unit: &Unit, asked: &Asked<'_, '_, '_>, target: &Expr, span: &Span, here: &mut Here) {
    match root(unit, asked, &here, target) {
        Root::SubjectField(ref field) => { field_of_subject(unit, asked, field, span, here); },
        Root::Subject => { subject_destination(unit, asked, span, here); },
        Root::ParamField(param, ref field) => { field_of_param(unit, asked, param, field, span, here); },
        Root::Param(_) => { },
        Root::Elsewhere => { },
    }
}

fn a_struct_parameter(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, name: winnow_grammar::Symbol) -> Option<String> {
    let wanted = asked.names.resolve(name);
    for (declared, ty) in here.declared.iter() {
        let declared = *declared;
        if asked.names.resolve(declared) == wanted {
            let owner = asked.names.resolve(ty.name);
            if !ty.is_view && unit.borrowing.contains(owner) { return Some(owner.to_owned()); }
            return None;
        }
    }
    None
}

fn field_of_param(unit: &Unit, asked: &Asked<'_, '_, '_>, param: winnow_grammar::Symbol, field: &str, span: &Span, here: &mut Here) {
    let owner = match a_struct_parameter(unit, asked, &here, param) { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, &owner) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    for (name, ty) in declared.iter() {
        if name == field {
            if brings_buffer(unit, asked, ty) { here.found.push((span.clone(), Destination::ParamField { param, owner, field: field.to_owned(), ty: written_type(asked.names, ty) })); }
            return;
        }
    }
}

fn joined_path(asked: &Asked<'_, '_, '_>, parts: &[winnow_grammar::Symbol]) -> String {
    let mut written: Vec<String> = vec![];
    for part in parts.iter() {
        let part = *part;
        written.push(asked.names.resolve(part).to_owned());
    }
    written.join("::")
}

fn type_of(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, receiver: &Expr) -> Option<Type> {
    match receiver {
        Expr::Variable(name, _) => { let name = *name; variable_type(asked, here, asked.names.resolve(name)) },
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; field_type(unit, asked, here, base, asked.names.resolve(name)) },
        _ => None,
    }
}

fn variable_type(asked: &Asked<'_, '_, '_>, here: &Here, name: &str) -> Option<Type> {
    if name == "self" {
        return match here.subject.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
    }
    for (param, ty) in here.declared.iter() {
        let param = *param;
        if asked.names.resolve(param) == name { return Some(ty.clone()); }
    }
    None
}

fn field_type(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, base: &Expr, name: &str) -> Option<Type> {
    let fields = match fields_reached(unit, asked, here, base) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for (field, ty) in fields.iter() { if field == name { return Some(ty.clone()); } }
    None
}

fn fields_reached(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, base: &Expr) -> Option<Vec<(String, Type)>> {
    if is_self(asked, base) { return Some(here.subject_fields.to_owned()); }
    let ty = match type_of(unit, asked, here, base) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match *nikaia_std::index::get(&unit.fields, asked.names.resolve(ty.name)) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn is_self(asked: &Asked<'_, '_, '_>, expr: &Expr) -> bool {
    match expr {
        Expr::Variable(name, _) => { let name = *name; asked.names.resolve(name) == "self" },
        _ => false,
    }
}

fn stores(unit: &Unit, asked: &Asked<'_, '_, '_>, expr: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match expr {
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            handed_to(unit, asked, receiver, args, config, span, here);
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            handed_to(unit, asked, receiver, args, config, span, here);
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::StructLit { name, fields, .. } => {
            let name = *name;
            let owner = asked.names.resolve(name).to_owned();
            if unit.borrowing.contains(&owner) {
                let declared = nikaia_std::index::or(match *nikaia_std::index::get(&unit.fields, &owner) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || vec![].into());
                for init in fields.iter() { a_field_built(unit, asked, &owner, &declared, init, span, here); }
            }
            descend(unit, asked, expr, span, own_buffer, here);
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            if mentions(unit, asked, &here, body) { here.found.push((span.clone(), Destination::Task)); }
            descend(unit, asked, expr, span, own_buffer, here);
        },
        _ => { descend(unit, asked, expr, span, own_buffer, here); },
    }
}

fn handed_to(unit: &Unit, asked: &Asked<'_, '_, '_>, receiver: &Expr, args: &[Expr], config: &[ConfigArg], span: &Span, here: &mut Here) {
    let mut handed_over = false;
    for arg in args.iter() { if mentions(unit, asked, &here, arg) { handed_over = true; } }
    for setting in config.iter() { if mentions(unit, asked, &here, &setting.value) { handed_over = true; } }
    if !handed_over { return; }
    match root(unit, asked, &here, receiver) {
        Root::SubjectField(ref field) => { field_of_subject(unit, asked, field, span, here); },
        Root::Subject => { subject_destination(unit, asked, span, here); },
        _ => { },
    }
}

fn a_field_built(unit: &Unit, asked: &Asked<'_, '_, '_>, owner: &str, declared: &[(String, Type)], init: &FieldInit, span: &Span, here: &mut Here) {
    let field = asked.names.resolve(init.name).to_owned();
    let mentioned = value_mentions(unit, asked, &here, (init.value).as_ref(), &field);
    if !mentioned { return; }
    for (name, ty) in declared.iter() {
        if *name == field {
            if brings_buffer(unit, asked, ty) { here.found.push((span.clone(), Destination::Field { owner: owner.to_owned(), field, ty: written_type(asked.names, ty) })); }
            return;
        }
    }
}

fn value_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, value: Option<&Expr>, field: &str) -> bool {
    let written = match value { Some(__nikaia_value) => __nikaia_value, None => return here.carriers.contains(field) };
    mentions(unit, asked, here, written)
}

fn subject_destination(unit: &Unit, asked: &Asked<'_, '_, '_>, span: &Span, here: &mut Here) {
    let owner = match text_of(asked, (here.subject).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return };
    let known = unit.fields.contains_key(&owner);
    let mut can_hold = false;
    for (_, ty) in here.subject_fields.iter() { if brings_buffer(unit, asked, ty) { can_hold = true; } }
    if known && !can_hold { return; }
    if !known && !declared_elsewhere_with_a_view(asked, &owner) { return; }
    here.found.push((span.clone(), Destination::Subject { owner }));
}

fn declared_elsewhere_with_a_view(asked: &Asked<'_, '_, '_>, owner: &str) -> bool {
    let declared = match *nikaia_std::index::get(&asked.own.types, owner) { Some(__nikaia_value) => __nikaia_value, None => return true };
    for field in declared.fields.iter() { if a_ledger_type_with_a_view(&field.ty) { return true; } }
    for variant in declared.variants.iter() { for part in variant.holds.iter() { if a_ledger_type_with_a_view(&part.ty) { return true; } } }
    false
}

fn field_of_subject(unit: &Unit, asked: &Asked<'_, '_, '_>, field: &str, span: &Span, here: &mut Here) {
    let mut written: Option<String> = None;
    for (name, ty) in here.subject_fields.iter() {
        if written.is_none() && name == field && brings_buffer(unit, asked, ty) { written = Some(written_type(asked.names, ty)); }
        if name == field { break; }
    }
    let ty = match written { Some(__nikaia_value) => __nikaia_value, None => return };
    let owner = match text_of(asked, (here.subject).as_ref()) { Some(__nikaia_value) => __nikaia_value, None => return };
    here.found.push((span.clone(), Destination::Field { owner, field: field.to_owned(), ty }));
}

fn root(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, expr: &Expr) -> Root {
    match expr {
        Expr::Variable(name, _) => { let name = *name; a_variable_root(unit, asked, here, name) },
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; match root(unit, asked, here, base) {
            Root::Subject => Root::SubjectField(asked.names.resolve(name).to_owned()),
            Root::Param(param) => Root::ParamField(param, asked.names.resolve(name).to_owned()),
            Root::SubjectField(field) => Root::SubjectField(field),
            Root::ParamField(param, field) => Root::ParamField(param, field),
            Root::Elsewhere => Root::Elsewhere,
        } },
        Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); root(unit, asked, here, receiver) },
        Expr::SafeMethod { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); root(unit, asked, here, receiver) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); root(unit, asked, here, base) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); root(unit, asked, here, inner) },
        _ => Root::Elsewhere,
    }
}

fn a_variable_root(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, name: winnow_grammar::Symbol) -> Root {
    if asked.names.resolve(name) == "self" { return Root::Subject; }
    if a_struct_parameter(unit, asked, here, name).is_some() { return Root::Param(name); }
    Root::Elsewhere
}

fn mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, node: &Expr) -> bool {
    match node {
        Expr::Variable(name, _) => { let name = *name; here.carriers.contains(asked.names.resolve(name)) },
        Expr::MethodCall { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); mentions(unit, asked, here, receiver) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::SafeMethod { receiver, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); mentions(unit, asked, here, receiver) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::Call { func, args, config, .. } => { let func = nikaia_std::boxed::open(func); mentions(unit, asked, here, func) || any_mentions(unit, asked, here, args) || config_mentions(unit, asked, here, config) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); mentions(unit, asked, here, base) || mentions(unit, asked, here, index) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); mentions(unit, asked, here, lhs) || mentions(unit, asked, here, rhs) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); mentions(unit, asked, here, inner) },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); mentions(unit, asked, here, inner) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); mentions(unit, asked, here, body) },
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); mentions(unit, asked, here, value) || mentions(unit, asked, here, fallback) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); mentions(unit, asked, here, start) || mentions(unit, asked, here, end) },
        Expr::Tuple(parts, _) => any_mentions(unit, asked, here, parts),
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); mentions(unit, asked, here, value) || mentions(unit, asked, here, count) },
        Expr::ListLit { items, .. } => any_mentions(unit, asked, here, items),
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); maybe_mentions(unit, asked, here, (value).as_ref()) },
        Expr::StructLit { fields, .. } => fields_mention(unit, asked, here, fields),
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); mentions(unit, asked, here, base) || fields_mention(unit, asked, here, fields) },
        Expr::Match { value, arms, .. } => { let value = nikaia_std::boxed::open(value); mentions(unit, asked, here, value) || arms_mention(unit, asked, here, arms) },
        Expr::If { cond, then_branch, else_branch, .. } => { let cond = nikaia_std::boxed::open(cond); mentions(unit, asked, here, cond) || block_mentions(unit, asked, here, then_branch) || maybe_block_mentions(unit, asked, here, (else_branch).as_ref()) },
        Expr::Block(block, _) => block_mentions(unit, asked, here, block),
        Expr::Unsafe(block, _) => block_mentions(unit, asked, here, block),
        Expr::Overlap(block, _) => block_mentions(unit, asked, here, block),
        Expr::Closure { body, .. } => block_mentions(unit, asked, here, body),
        Expr::Select(arms, _) => select_mentions(unit, asked, here, arms),
        Expr::TryCatch { expr, handler, .. } => { let expr = nikaia_std::boxed::open(expr); mentions(unit, asked, here, expr) || block_mentions(unit, asked, here, handler) },
        Expr::Break(_) => false,
        Expr::Continue(_) => false,
        Expr::Asm { .. } => false,
        Expr::Dsl { .. } => false,
        Expr::Path(_, _) => false,
        Expr::LitInt { .. } => false,
        Expr::LitFloat(_, _) => false,
        Expr::LitStr { .. } => false,
        Expr::LitInterpolated { .. } => false,
        Expr::LitChar(_, _) => false,
        Expr::LitBool(_, _) => false,
        Expr::LitNull(_) => false,
    }
}

fn any_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, exprs: &[Expr]) -> bool {
    for expr in exprs.iter() { if mentions(unit, asked, here, expr) { return true; } }
    false
}

fn config_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, config: &[ConfigArg]) -> bool {
    for setting in config.iter() { if mentions(unit, asked, here, &setting.value) { return true; } }
    false
}

fn fields_mention(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, fields: &[FieldInit]) -> bool {
    for field in fields.iter() { if maybe_mentions(unit, asked, here, (field.value).as_ref()) { return true; } }
    false
}

fn arms_mention(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, arms: &[MatchArm]) -> bool {
    for arm in arms.iter() { if mentions(unit, asked, here, &arm.body) { return true; } }
    false
}

fn select_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, arms: &[SelectArm]) -> bool {
    for arm in arms.iter() { if mentions(unit, asked, here, &arm.value) || block_mentions(unit, asked, here, &arm.body) { return true; } }
    false
}

fn maybe_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, expr: Option<&Expr>) -> bool { mentions(unit, asked, here, match expr { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn maybe_block_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, block: Option<&Block>) -> bool { block_mentions(unit, asked, here, match block { Some(__nikaia_value) => __nikaia_value, None => return false }) }

fn block_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, block: &Block) -> bool {
    for stmt in block.stmts.iter() { if statement_mentions(unit, asked, here, &stmt.node) { return true; } }
    false
}

fn statement_mentions(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Let { value, .. } => mentions(unit, asked, here, value),
        Stmt::Comptime { value, .. } => mentions(unit, asked, here, value),
        Stmt::Expr(expr) => mentions(unit, asked, here, expr),
        Stmt::Return(value) => maybe_mentions(unit, asked, here, (value).as_ref()),
        Stmt::Assign { target, value, .. } => mentions(unit, asked, here, target) || mentions(unit, asked, here, value),
        Stmt::For { iter, body, .. } => mentions(unit, asked, here, iter) || block_mentions(unit, asked, here, body),
        Stmt::While { cond, body } => mentions(unit, asked, here, cond) || block_mentions(unit, asked, here, body),
        Stmt::Break => false,
        Stmt::Continue => false,
    }
}

fn descend(unit: &Unit, asked: &Asked<'_, '_, '_>, node: &Expr, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) {
    match node {
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            stores(unit, asked, receiver, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            stores(unit, asked, receiver, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            stores(unit, asked, func, span, own_buffer, here);
            stores_all(unit, asked, args, span, own_buffer, here);
            stores_config(unit, asked, config, span, own_buffer, here);
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); stores(unit, asked, base, span, own_buffer, here); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); stores(unit, asked, base, span, own_buffer, here); },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            stores(unit, asked, base, span, own_buffer, here);
            stores(unit, asked, index, span, own_buffer, here);
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            stores(unit, asked, lhs, span, own_buffer, here);
            stores(unit, asked, rhs, span, own_buffer, here);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); stores(unit, asked, expr, span, own_buffer, here); },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); stores(unit, asked, inner, span, own_buffer, here); },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); stores(unit, asked, inner, span, own_buffer, here); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); stores(unit, asked, expr, span, own_buffer, here); },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); stores(unit, asked, body, span, own_buffer, here); },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            stores(unit, asked, value, span, own_buffer, here);
            stores(unit, asked, fallback, span, own_buffer, here);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            stores(unit, asked, start, span, own_buffer, here);
            stores(unit, asked, end, span, own_buffer, here);
        },
        Expr::Tuple(parts, _) => { stores_all(unit, asked, parts, span, own_buffer, here); },
        Expr::ListRepeat { value, count, .. } => {
            let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count);
            stores(unit, asked, value, span, own_buffer, here);
            stores(unit, asked, count, span, own_buffer, here);
        },
        Expr::ListLit { items, .. } => { stores_all(unit, asked, items, span, own_buffer, here); },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); stores_maybe(unit, asked, (value).as_ref(), span, own_buffer, here); },
        Expr::StructLit { fields, .. } => { stores_fields(unit, asked, fields, span, own_buffer, here); },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            stores(unit, asked, base, span, own_buffer, here);
            stores_fields(unit, asked, fields, span, own_buffer, here);
        },
        Expr::Match { value, arms, .. } => {
            let value = nikaia_std::boxed::open(value);
            stores(unit, asked, value, span, own_buffer, here);
            for arm in arms.iter() { stores(unit, asked, &arm.body, span, own_buffer, here); }
        },
        Expr::If { cond, then_branch, else_branch, .. } => {
            let cond = nikaia_std::boxed::open(cond);
            stores(unit, asked, cond, span, own_buffer, here);
            walk_block(unit, asked, then_branch, false, own_buffer, here);
            walk_maybe_block(unit, asked, (else_branch).as_ref(), own_buffer, here);
        },
        Expr::Block(block, _) => { walk_block(unit, asked, block, false, own_buffer, here); },
        Expr::Unsafe(block, _) => { walk_block(unit, asked, block, false, own_buffer, here); },
        Expr::Overlap(block, _) => { walk_block(unit, asked, block, false, own_buffer, here); },
        Expr::Closure { body, .. } => { walk_block(unit, asked, body, false, own_buffer, here); },
        Expr::Select(arms, _) => {
            for arm in arms.iter() { stores(unit, asked, &arm.value, span, own_buffer, here); }
            for arm in arms.iter() { walk_block(unit, asked, &arm.body, false, own_buffer, here); }
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            stores(unit, asked, expr, span, own_buffer, here);
            walk_block(unit, asked, handler, false, own_buffer, here);
        },
        Expr::Break(_) => { },
        Expr::Continue(_) => { },
        Expr::Asm { .. } => { },
        Expr::Dsl { .. } => { },
        Expr::Path(_, _) => { },
        Expr::Variable(_, _) => { },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_, _) => { },
        Expr::LitStr { .. } => { },
        Expr::LitInterpolated { .. } => { },
        Expr::LitChar(_, _) => { },
        Expr::LitBool(_, _) => { },
        Expr::LitNull(_) => { },
    }
}

fn stores_all(unit: &Unit, asked: &Asked<'_, '_, '_>, exprs: &[Expr], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for expr in exprs.iter() { stores(unit, asked, expr, span, own_buffer, here); } }

fn stores_config(unit: &Unit, asked: &Asked<'_, '_, '_>, config: &[ConfigArg], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for setting in config.iter() { stores(unit, asked, &setting.value, span, own_buffer, here); } }

fn stores_fields(unit: &Unit, asked: &Asked<'_, '_, '_>, fields: &[FieldInit], span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { for field in fields.iter() { stores_maybe(unit, asked, (field.value).as_ref(), span, own_buffer, here); } }

fn stores_maybe(unit: &Unit, asked: &Asked<'_, '_, '_>, expr: Option<&Expr>, span: &Span, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { stores(unit, asked, match expr { Some(__nikaia_value) => __nikaia_value, None => return }, span, own_buffer, here); }

fn walk_maybe_block(unit: &Unit, asked: &Asked<'_, '_, '_>, block: Option<&Block>, own_buffer: &impl Fn(&Expr) -> bool, here: &mut Here) { walk_block(unit, asked, match block { Some(__nikaia_value) => __nikaia_value, None => return }, false, own_buffer, here); }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FieldsHeld {
    pub name: winnow_grammar::Symbol,
    pub fields: Vec<(String, Type)>,
}

pub fn fields_held(words: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<FieldsHeld> {
    let mut out: Vec<FieldsHeld> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, fields, .. } => {
                let name = *name;
                let mut held: Vec<(String, Type)> = vec![];
                for f in fields.iter() { held.push((words.resolve(f.name).to_owned(), f.ty.clone())); }
                out.push(FieldsHeld { name, fields: held });
            },
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut held: Vec<(String, Type)> = vec![];
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        VariantFields::Tuple(types) => { for k in 0..types.len() as i64 { held.push((format!("{}", k), (*nikaia_std::index::get(&types, (k) as usize)).clone())); } },
                        VariantFields::Named(fields) => { for f in fields.iter() { held.push((words.resolve(f.name).to_owned(), f.ty.clone())); } },
                    }
                }
                out.push(FieldsHeld { name, fields: held });
            },
            _ => { },
        }
    }
    out
}

pub fn carrying(stored: &[Stored]) -> Vec<(u32, winnow_grammar::Symbol)> {
    let mut out: Vec<(u32, winnow_grammar::Symbol)> = vec![];
    for s in stored.iter() {
        if s.carried {
            out.push((s.method, s.symbol));
            if s.carrier.is_some() {
                let carrier = nikaia_std::index::or(s.carrier, || s.symbol.into());
                out.push((s.method, carrier));
            }
        }
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ResultSrcWay {
    span: Span,
    reach: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ResultSrcKnown {
    declared: bool,
    params: Vec<String>,
    reach: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ResultSrcFlow {
    env: collections::BTreeMap<String, collections::BTreeSet<String>>,
    ways: Vec<ResultSrcWay>,
    at: Span,
    depth: i64,
    inner: collections::BTreeSet<String>,
    shadow: collections::BTreeSet<String>,
    annotated: collections::BTreeMap<String, Type>,
    places: collections::BTreeSet<String>,
    stores: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

fn rsrc_none() -> collections::BTreeSet<String> {
    let empty: collections::BTreeSet<String> = collections::BTreeSet::new();
    empty
}

fn rsrc_join(into: &mut collections::BTreeSet<String>, more: &collections::BTreeSet<String>) { for name in more.iter() { into.insert(name.to_owned()); } }

fn rsrc_param_of(entry: &str) -> String {
    let parts = entry.split(':').collect::<Vec<_>>();
    (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned()
}

fn rsrc_path_of(entry: &str) -> String {
    let parts = entry.split(':').collect::<Vec<_>>();
    if parts.len() < 2 { return String::from(""); }
    (*nikaia_std::index::get(&parts, 0)).to_owned()
}

fn rsrc_under(path: &str, entries: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for entry in entries.iter() { if path.is_empty() { out.insert(entry.to_owned()); } else { out.insert(format!("{}:{}", path, rsrc_param_of(entry))); } }
    out
}

fn rsrc_out_of(name: &str, entries: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for entry in entries.iter() {
        let path = rsrc_path_of(entry);
        if path.is_empty() { out.insert(entry.to_owned()); } else if path == name { out.insert(rsrc_param_of(entry)); } else if !path.starts_with(&format!("{}.", name)) { out.insert(rsrc_loosened(&rsrc_param_of(entry))); } else if path.starts_with(&format!("{}.", name)) {
            let rest = nikaia_std::index::or(path.strip_prefix(&format!("{}.", name)), || "").to_owned();
            out.insert(format!("{}:{}", rest, rsrc_param_of(entry)));
        }
    }
    out
}

fn rsrc_plain(entries: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for entry in entries.iter() { out.insert(rsrc_bare(&rsrc_param_of(entry))); }
    out
}

fn rsrc_bare(param: &str) -> String {
    if param.starts_with('~') { return nikaia_std::index::or(param.strip_prefix('~'), || "").to_owned(); }
    param.to_owned()
}

fn rsrc_loosened(param: &str) -> String {
    if param.starts_with('~') { return param.to_owned(); }
    format!("~{}", param)
}

fn rsrc_all_loose(entries: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for entry in entries.iter() {
        let path = rsrc_path_of(entry);
        let param = rsrc_loosened(&rsrc_param_of(entry));
        if path.is_empty() { out.insert(param); } else { out.insert(format!("{}:{}", path, param)); }
    }
    out
}

fn rsrc_flow(at: &Span) -> ResultSrcFlow {
    let env: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    ResultSrcFlow { env, ways: vec![], at: Span { start: at.start, end: at.end }, depth: 0, inner: rsrc_none(), shadow: rsrc_none(), annotated: collections::BTreeMap::new(), places: rsrc_none(), stores: collections::BTreeMap::new() }
}

fn rsrc_shadow(asked: &Asked<'_, '_, '_>, here: &Here, name: &str, flow: &mut ResultSrcFlow) { if variable_type(asked, here, name).is_some() { flow.shadow.insert(name.to_owned()); } }

fn rsrc_root_name(asked: &Asked<'_, '_, '_>, place: &Expr) -> Option<String> {
    match place {
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_name(asked, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_name(asked, base) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_name(asked, base) },
        Expr::Variable(name, _) => { let name = *name; Some(asked.names.resolve(name).to_owned()) },
        _ => None,
    }
}

fn rsrc_type(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, flow: &ResultSrcFlow, place: &Expr) -> Option<Type> {
    let root = rsrc_root_name(asked, place);
    if root.is_some() {
        let named = nikaia_std::index::or(root, || "".into());
        if flow.shadow.contains(&named) { return None; }
    }
    type_of(unit, asked, here, place)
}

fn rsrc_of_name(flow: &ResultSrcFlow, name: &str) -> collections::BTreeSet<String> {
    nikaia_std::index::or(match *nikaia_std::index::get(&flow.env, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || rsrc_none().into())
}

fn rsrc_bind(flow: &mut ResultSrcFlow, name: &str, reach: &collections::BTreeSet<String>) {
    if reach.is_empty() { return; }
    let mut now = rsrc_of_name(&flow, name);
    rsrc_join(&mut now, reach);
    flow.env.insert(name.to_owned(), now);
}

fn rsrc_bind_symbol(asked: &Asked<'_, '_, '_>, binding: Option<winnow_grammar::Symbol>, reach: &collections::BTreeSet<String>, flow: &mut ResultSrcFlow) {
    let name = match binding { Some(__nikaia_value) => __nikaia_value, None => return };
    rsrc_bind(flow, asked.names.resolve(name), reach);
}

fn rsrc_bind_root(asked: &Asked<'_, '_, '_>, here: &Here, target: &Expr, reach: &collections::BTreeSet<String>, flow: &mut ResultSrcFlow) {
    match target {
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_bind_root(asked, here, base, reach, flow); },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_bind_root(asked, here, base, reach, flow); },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_bind_root(asked, here, base, reach, flow); },
        Expr::Variable(name, _) => {
            let name = *name;
            let written = asked.names.resolve(name).to_owned();
            if variable_type(asked, here, &written).is_none() || flow.shadow.contains(&written) { rsrc_bind(flow, &written, reach); }
        },
        _ => { },
    }
}

fn rsrc_scalar(asked: &Asked<'_, '_, '_>, ty: &Type) -> bool {
    if ty.is_view || !ty.generics.is_empty() { return false; }
    let name = asked.names.resolve(ty.name);
    name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "isize" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "usize" || name == "f32" || name == "f64" || name == "bool" || name == "char"
}

fn rsrc_ty_holds_view(asked: &Asked<'_, '_, '_>, ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => {
            let view = *view;
            if view || rsrc_any_ty_holds_view(asked, args) { return true; }
            let own = nikaia_std::index::or(match (*nikaia_std::index::get(&asked.own.types, name)).as_ref().map(|__nikaia_it| &__nikaia_it.tethered) {
                Some(__nikaia_it) => Some(__nikaia_it.len() as i64),
                None => None,
            }, || -1);
            if own >= 0 { return own > 0; }
            let library = nikaia_std::index::or(match (*nikaia_std::index::get(&asked.library.types, name)).as_ref().map(|__nikaia_it| &__nikaia_it.tethered) {
                Some(__nikaia_it) => Some(__nikaia_it.len() as i64),
                None => None,
            }, || -1);
            if library >= 0 { return library > 0; }
            return !rsrc_plain_name(name);
        },
        Ty::Tuple(parts) => rsrc_any_ty_holds_view(asked, parts),
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); rsrc_ty_holds_view(asked, inner) },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); rsrc_ty_holds_view(asked, item) },
        Ty::Fn { .. } => false,
        Ty::Count(_) => false,
        _ => true,
    }
}

fn rsrc_plain_name(name: &str) -> bool { name == "String" || name == "bool" || name == "char" || name == "i8" || name == "i16" || name == "i32" || name == "i64" || name == "isize" || name == "u8" || name == "u16" || name == "u32" || name == "u64" || name == "usize" || name == "f32" || name == "f64" || name == "Vec" || name == "Array" || name == "Option" || name == "BTreeSet" || name == "BTreeMap" || name == "HashSet" || name == "HashMap" || name == "VecDeque" || name == "Box" || name == "Tuple" || name == "Duration" || name == "Instant" || name == "scalar" || name == "bytes" }

fn rsrc_any_ty_holds_view(asked: &Asked<'_, '_, '_>, types: &[Ty]) -> bool {
    for ty in types.iter() { if rsrc_ty_holds_view(asked, ty) { return true; } }
    false
}

fn rsrc_eval(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, node: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let reach = rsrc_eval_node(unit, asked, here, known, own_buffer, node, flow);
    if rsrc_passes_whole(node) { return reach; }
    rsrc_derived(&reach)
}

fn rsrc_passes_whole(node: &Expr) -> bool { matches!(node, Expr::Variable(_, _) | Expr::Block(_, _) | Expr::Unsafe(_, _) | Expr::Overlap(_, _) | Expr::If { .. } | Expr::Match { .. } | Expr::Coalesce { .. } | Expr::Return(_, _)) }

fn rsrc_derived(reach: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for entry in reach.iter() { if entry.starts_with('=') { out.insert(format!("!{}", nikaia_std::index::or(entry.strip_prefix('='), || ""))); } else { out.insert(entry.to_owned()); } }
    out
}

fn rsrc_eval_node(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, node: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    match node {
        Expr::Variable(name, _) => { let name = *name; rsrc_of_name(&flow, asked.names.resolve(name)) },
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; rsrc_field(unit, asked, here, known, own_buffer, base, asked.names.resolve(name), flow) },
        Expr::SafeField { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; rsrc_field(unit, asked, here, known, own_buffer, base, asked.names.resolve(name), flow) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); rsrc_index(unit, asked, here, known, own_buffer, base, index, flow) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); rsrc_eval(unit, asked, here, known, own_buffer, expr, flow) },
        Expr::Try(inner, _) => { let inner = nikaia_std::boxed::open(inner); rsrc_eval(unit, asked, here, known, own_buffer, inner, flow) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); rsrc_eval(unit, asked, here, known, own_buffer, expr, flow) },
        Expr::Throw(inner, _) => { let inner = nikaia_std::boxed::open(inner); rsrc_nothing(unit, asked, here, known, own_buffer, inner, flow) },
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); rsrc_both(unit, asked, here, known, own_buffer, value, fallback, flow) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); rsrc_nothing_of(unit, asked, here, known, own_buffer, lhs, rhs, flow) },
        Expr::Range { start, end, .. } => { let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); rsrc_nothing_of(unit, asked, here, known, own_buffer, start, end, flow) },
        Expr::Tuple(parts, _) => rsrc_all(unit, asked, here, known, own_buffer, parts, flow),
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); rsrc_nothing_of(unit, asked, here, known, own_buffer, value, count, flow) },
        Expr::ListLit { items, .. } => rsrc_all(unit, asked, here, known, own_buffer, items, flow),
        Expr::StructLit { name, fields, .. } => { let name = *name; rsrc_struct_fields(unit, asked, here, known, own_buffer, asked.names.resolve(name), fields, flow) },
        Expr::With { base, fields, .. } => { let base = nikaia_std::boxed::open(base); rsrc_with(unit, asked, here, known, own_buffer, base, fields, flow) },
        Expr::MethodCall { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; rsrc_method(unit, asked, here, known, own_buffer, receiver, method, args, config, flow) },
        Expr::SafeMethod { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; rsrc_method(unit, asked, here, known, own_buffer, receiver, method, args, config, flow) },
        Expr::Call { func, args, config, .. } => { let func = nikaia_std::boxed::open(func); rsrc_call(unit, asked, here, known, own_buffer, func, args, config, flow) },
        Expr::Return(value, _) => { let value = nikaia_std::boxed::open(value); rsrc_return(unit, asked, here, known, own_buffer, (value).as_ref(), flow) },
        Expr::Block(block, _) => rsrc_block(unit, asked, here, known, own_buffer, block, flow),
        Expr::Unsafe(block, _) => rsrc_block(unit, asked, here, known, own_buffer, block, flow),
        Expr::Overlap(block, _) => rsrc_block(unit, asked, here, known, own_buffer, block, flow),
        Expr::If { cond, then_branch, else_branch, .. } => { let cond = nikaia_std::boxed::open(cond); rsrc_if(unit, asked, here, known, own_buffer, cond, then_branch, (else_branch).as_ref(), flow) },
        Expr::Match { value, arms, .. } => { let value = nikaia_std::boxed::open(value); rsrc_match(unit, asked, here, known, own_buffer, value, arms, flow) },
        Expr::Closure { body, .. } => rsrc_closure(unit, asked, here, known, own_buffer, body, flow),
        Expr::Select(arms, _) => rsrc_select(unit, asked, here, known, own_buffer, arms, flow),
        Expr::TryCatch { expr, handler, .. } => { let expr = nikaia_std::boxed::open(expr); rsrc_both_blocks(unit, asked, here, known, own_buffer, expr, handler, flow) },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); rsrc_task(unit, asked, here, known, own_buffer, body, flow) },
        Expr::Break(_) => rsrc_none(),
        Expr::Continue(_) => rsrc_none(),
        Expr::Asm { .. } => rsrc_none(),
        Expr::Dsl { .. } => rsrc_none(),
        Expr::Path(_, _) => rsrc_none(),
        Expr::LitInt { .. } => rsrc_none(),
        Expr::LitFloat(_, _) => rsrc_none(),
        Expr::LitStr { .. } => rsrc_none(),
        Expr::LitInterpolated { .. } => rsrc_none(),
        Expr::LitChar(_, _) => rsrc_none(),
        Expr::LitBool(_, _) => rsrc_none(),
        Expr::LitNull(_) => rsrc_none(),
    }
}

fn rsrc_nothing(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, node: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let walked = rsrc_eval(unit, asked, here, known, own_buffer, node, flow);
    rsrc_none()
}

#[allow(clippy::too_many_arguments)]
fn rsrc_nothing_of(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, first: &Expr, second: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let walked = rsrc_eval(unit, asked, here, known, own_buffer, first, flow);
    let other = rsrc_eval(unit, asked, here, known, own_buffer, second, flow);
    rsrc_none()
}

#[allow(clippy::too_many_arguments)]
fn rsrc_both(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, first: &Expr, second: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_eval(unit, asked, here, known, own_buffer, first, flow);
    let more = rsrc_eval(unit, asked, here, known, own_buffer, second, flow);
    rsrc_join(&mut out, &more);
    out
}

#[allow(clippy::too_many_arguments)]
fn rsrc_both_blocks(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, first: &Expr, handler: &Block, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_eval(unit, asked, here, known, own_buffer, first, flow);
    let more = rsrc_block(unit, asked, here, known, own_buffer, handler, flow);
    rsrc_join(&mut out, &more);
    out
}

fn rsrc_all(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, exprs: &[Expr], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for expr in exprs.iter() {
        let more = rsrc_eval(unit, asked, here, known, own_buffer, expr, flow);
        rsrc_join(&mut out, &more);
    }
    out
}

fn rsrc_maybe(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, expr: Option<&Expr>, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let written = match expr { Some(__nikaia_value) => __nikaia_value, None => return rsrc_none() };
    rsrc_eval(unit, asked, here, known, own_buffer, written, flow)
}

#[allow(clippy::too_many_arguments)]
fn rsrc_field(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, base: &Expr, name: &str, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let inner = rsrc_eval(unit, asked, here, known, own_buffer, base, flow);
    let hidden = rsrc_type(unit, asked, here, &flow, base);
    if hidden.is_none() && rsrc_root_name(asked, base).is_some() && !is_self(asked, base) { return rsrc_out_of(name, &inner); }
    let declared = match field_type(unit, asked, here, base, name) { Some(__nikaia_value) => __nikaia_value, None => return rsrc_out_of(name, &inner) };
    if rsrc_scalar(asked, &declared) { return rsrc_none(); }
    rsrc_out_of(name, &inner)
}

#[allow(clippy::too_many_arguments)]
fn rsrc_index(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, base: &Expr, index: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let inner = rsrc_eval(unit, asked, here, known, own_buffer, base, flow);
    let read = rsrc_eval(unit, asked, here, known, own_buffer, index, flow);
    inner
}

#[allow(clippy::too_many_arguments)]
fn rsrc_struct_fields(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, owner: &str, fields: &[FieldInit], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let declared = match *nikaia_std::index::get(&unit.fields, owner) { Some(__nikaia_value) => __nikaia_value, None => return rsrc_fields(unit, asked, here, known, own_buffer, fields, flow) };
    let mut out = rsrc_none();
    for field in fields.iter() {
        let named = asked.names.resolve(field.name);
        let mut more = rsrc_none();
        if field.value.is_none() { more = rsrc_of_name(&flow, named); } else { more = rsrc_maybe(unit, asked, here, known, own_buffer, (field.value).as_ref(), flow); }
        let mut owning = false;
        for (written, ty) in declared.iter() { if written == named && !ty.is_view && !ty.either && (rsrc_plain_text(asked, ty) || rsrc_scalar(asked, ty)) { owning = true; } }
        if !owning { rsrc_join(&mut out, &rsrc_under(named, &more)); }
    }
    out
}

fn rsrc_fields(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, fields: &[FieldInit], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for field in fields.iter() {
        let mut more = rsrc_none();
        if field.value.is_none() { more = rsrc_of_name(&flow, asked.names.resolve(field.name)); } else { more = rsrc_maybe(unit, asked, here, known, own_buffer, (field.value).as_ref(), flow); }
        rsrc_join(&mut out, &rsrc_under(asked.names.resolve(field.name), &more));
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn rsrc_with(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, base: &Expr, fields: &[FieldInit], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_eval(unit, asked, here, known, own_buffer, base, flow);
    let more = rsrc_fields(unit, asked, here, known, own_buffer, fields, flow);
    rsrc_join(&mut out, &more);
    out
}

fn rsrc_return(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, value: Option<&Expr>, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let reach = rsrc_maybe(unit, asked, here, known, own_buffer, value, flow);
    rsrc_record(&reach, flow);
    rsrc_none()
}

fn rsrc_record(reach: &collections::BTreeSet<String>, flow: &mut ResultSrcFlow) {
    if flow.depth > 0 {
        for name in reach.iter() { flow.inner.insert(name.to_owned()); }
        return;
    }
    flow.ways.push(ResultSrcWay { span: Span { start: flow.at.start, end: flow.at.end }, reach: reach.to_owned() });
}

#[allow(clippy::too_many_arguments)]
fn rsrc_if(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, cond: &Expr, then_branch: &Block, else_branch: Option<&Block>, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let tested = rsrc_eval(unit, asked, here, known, own_buffer, cond, flow);
    let mut out = rsrc_block(unit, asked, here, known, own_buffer, then_branch, flow);
    let other = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out };
    let more = rsrc_block(unit, asked, here, known, own_buffer, other, flow);
    rsrc_join(&mut out, &more);
    out
}

fn rsrc_pattern_names(asked: &Asked<'_, '_, '_>, pattern: &MatchPattern, out: &mut Vec<String>) {
    match pattern {
        MatchPattern::Path(parts) => { if parts.len() == 1 { out.push(asked.names.resolve(*nikaia_std::index::get(&parts, 0)).to_owned()); } },
        MatchPattern::Tuple { parts, .. } => { for part in parts.iter() { rsrc_pattern_names(asked, part, out); } },
        MatchPattern::List(parts) => { for part in parts.iter() { rsrc_pattern_names(asked, part, out); } },
        MatchPattern::RestNamed(name) => { let name = *name; out.push(asked.names.resolve(name).to_owned()); },
        MatchPattern::Named { fields, .. } => { for field in fields.iter() { rsrc_pattern_names(asked, &field.pat, out); } },
        MatchPattern::Or(alternatives) => { for alternative in alternatives.iter() { rsrc_pattern_names(asked, alternative, out); } },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn rsrc_match(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, value: &Expr, arms: &[MatchArm], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let matched = rsrc_eval(unit, asked, here, known, own_buffer, value, flow);
    let mut out = rsrc_none();
    for arm in arms.iter() {
        let mut names: Vec<String> = vec![];
        rsrc_pattern_names(asked, &arm.pattern, &mut names);
        for name in names.iter() {
            rsrc_shadow(asked, here, name, flow);
            rsrc_bind(flow, name, &matched);
        }
        let guarded = rsrc_maybe(unit, asked, here, known, own_buffer, (arm.guard).as_ref(), flow);
        let more = rsrc_eval(unit, asked, here, known, own_buffer, &arm.body, flow);
        rsrc_join(&mut out, &more);
    }
    out
}

fn rsrc_closure(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, body: &Block, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let saved = flow.inner.to_owned();
    flow.inner = rsrc_none();
    flow.depth += 1;
    let mut out = rsrc_block(unit, asked, here, known, own_buffer, body, flow);
    flow.depth -= 1;
    for name in flow.inner.iter() { out.insert(name.to_owned()); }
    flow.inner = saved;
    out
}

fn rsrc_task(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, body: &Expr, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let saved = flow.inner.to_owned();
    flow.depth += 1;
    let walked = rsrc_eval(unit, asked, here, known, own_buffer, body, flow);
    flow.depth -= 1;
    flow.inner = saved;
    rsrc_none()
}

fn rsrc_select(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, arms: &[SelectArm], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut out = rsrc_none();
    for arm in arms.iter() {
        let raced = rsrc_eval(unit, asked, here, known, own_buffer, &arm.value, flow);
        rsrc_bind_symbol(asked, arm.binding, &raced, flow);
        let more = rsrc_block(unit, asked, here, known, own_buffer, &arm.body, flow);
        rsrc_join(&mut out, &more);
    }
    out
}

fn rsrc_block(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, block: &Block, flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let count = block.stmts.len() as i64;
    let mut tail = rsrc_none();
    for i in 0..count {
        flow.at = Span { start: nikaia_std::index::get(&block.stmts, (i) as usize).span.start, end: nikaia_std::index::get(&block.stmts, (i) as usize).span.end };
        let last = i + 1 == count;
        match &nikaia_std::index::get(&block.stmts, (i) as usize).node {
            Stmt::Let { names, value, ty, .. } => {
                let reach = rsrc_eval(unit, asked, here, known, own_buffer, value, flow);
                for name in names.iter() {
                    let name = *name;
                    rsrc_shadow(asked, here, asked.names.resolve(name), flow);
                }
                if names.len() == 1 && ty.is_some() {
                    let annotation = match ty { Some(__nikaia_value) => __nikaia_value, None => return tail };
                    flow.annotated.insert(asked.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), annotation.clone());
                }
                if !own_buffer(value) {
                    for name in names.iter() {
                        let name = *name;
                        rsrc_bind(flow, asked.names.resolve(name), &reach);
                    }
                }
            },
            Stmt::Comptime { name, value, .. } => {
                let name = *name;
                let reach = rsrc_eval(unit, asked, here, known, own_buffer, value, flow);
                rsrc_bind(flow, asked.names.resolve(name), &reach);
            },
            Stmt::Assign { target, value, .. } => {
                let reach = rsrc_eval(unit, asked, here, known, own_buffer, value, flow);
                match target {
                    Expr::Variable(name, _) => { let name = *name; rsrc_bind(flow, asked.names.resolve(name), &reach); },
                    _ => {
                        rsrc_bind_root(asked, here, target, &reach, flow);
                        rsrc_store(asked, target, &reach, flow);
                    },
                }
            },
            Stmt::Return(value) => {
                let reach = rsrc_maybe(unit, asked, here, known, own_buffer, (value).as_ref(), flow);
                rsrc_record(&reach, flow);
            },
            Stmt::Expr(expr) => {
                let reach = rsrc_eval(unit, asked, here, known, own_buffer, expr, flow);
                if last { tail = reach; }
            },
            Stmt::For { bindings, iter, body, .. } => {
                let reach = rsrc_eval(unit, asked, here, known, own_buffer, iter, flow);
                for binding in bindings.iter() {
                    let binding = *binding;
                    rsrc_shadow(asked, here, asked.names.resolve(binding), flow);
                    rsrc_bind(flow, asked.names.resolve(binding), &reach);
                }
                let walked = rsrc_block(unit, asked, here, known, own_buffer, body, flow);
            },
            Stmt::While { cond, body } => {
                let tested = rsrc_eval(unit, asked, here, known, own_buffer, cond, flow);
                let walked = rsrc_block(unit, asked, here, known, own_buffer, body, flow);
            },
            Stmt::Break => { },
            Stmt::Continue => { },
        }
    }
    tail
}

fn rsrc_copy(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, flow: &ResultSrcFlow, receiver: &Expr, on: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let ty = match rsrc_type(unit, asked, here, flow, receiver) { Some(__nikaia_value) => __nikaia_value, None => return on.to_owned() };
    if names_borrowing(asked.names, &ty, &unit.borrowing) { return on.to_owned(); }
    for inner in ty.generics.iter() { if holds_view(inner) { return on.to_owned(); } }
    rsrc_none()
}

fn rsrc_may_hold(unit: &Unit, asked: &Asked<'_, '_, '_>, flow: &ResultSrcFlow, name: &str) -> bool {
    let written = match match *nikaia_std::index::get(&flow.annotated, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return true };
    brings_buffer(unit, asked, &written) || rsrc_unknown_named(unit, asked, &written)
}

fn rsrc_root_local(asked: &Asked<'_, '_, '_>, here: &Here, flow: &ResultSrcFlow, place: &Expr) -> Option<String> {
    match place {
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_local(asked, here, flow, base) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_local(asked, here, flow, base) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); rsrc_root_local(asked, here, flow, base) },
        Expr::Variable(name, _) => {
            let name = *name;
            let written = asked.names.resolve(name).to_owned();
            if variable_type(asked, here, &written).is_none() || flow.shadow.contains(&written) { return Some(written); }
            return None;
        },
        _ => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn rsrc_method(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let on = rsrc_eval(unit, asked, here, known, own_buffer, receiver, flow);
    let mut positional: Vec<collections::BTreeSet<String>> = vec![];
    positional.push(on.to_owned());
    let mut everything = on.to_owned();
    for arg in args.iter() {
        let reach = rsrc_eval(unit, asked, here, known, own_buffer, arg, flow);
        rsrc_join(&mut everything, &reach);
        positional.push(reach);
    }
    for option in config.iter() {
        let reach = rsrc_eval(unit, asked, here, known, own_buffer, &option.value, flow);
        rsrc_join(&mut everything, &reach);
    }
    let name = asked.names.resolve(method);
    if name == "clone" || name == "to_string" { return rsrc_copy(unit, asked, here, &flow, receiver, &on); }
    let mut stored = rsrc_none();
    for i in 1..positional.len() as i64 { rsrc_join(&mut stored, nikaia_std::index::get(&positional, (i) as usize)); }
    let root = rsrc_root_local(asked, here, &flow, receiver);
    let ty = rsrc_type(unit, asked, here, &flow, receiver);
    if !stored.is_empty() && !flow.places.is_empty() && rsrc_changes_described(asked, (ty).as_ref(), name) { rsrc_store(asked, receiver, &stored, flow); }
    if !stored.is_empty() && root.is_some() {
        let mut changes = true;
        if ty.is_some() {
            let kind = match match ty.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => return everything };
            let described = nikaia_std::index::or_maybe(match *nikaia_std::index::get(&asked.own.functions, &(format!("{}::{}", asked.names.resolve(kind.name), name))) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || match *nikaia_std::index::get(&asked.library.functions, &(format!("{}::{}", asked.names.resolve(kind.name), name))) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            });
            if described.is_some() {
                let contract = match described { Some(__nikaia_value) => __nikaia_value, None => return everything };
                changes = contract.mutates;
            }
        }
        let local = nikaia_std::index::or(root.as_deref(), || "").to_owned();
        if changes && rsrc_may_hold(unit, asked, &flow, &local) { rsrc_bind(flow, &local, &stored); }
    }
    let known_type = match ty { Some(__nikaia_value) => __nikaia_value, None => return everything };
    let subject = asked.names.resolve(known_type.name);
    let key = format!("{}::{}", subject, name);
    rsrc_callee(asked, known, &key, &positional, &everything)
}

fn rsrc_store(asked: &Asked<'_, '_, '_>, place: &Expr, reach: &collections::BTreeSet<String>, flow: &mut ResultSrcFlow) {
    if reach.is_empty() || flow.places.is_empty() { return; }
    let root = match rsrc_root_name(asked, place) { Some(__nikaia_value) => __nikaia_value, None => return };
    if !flow.places.contains(&root) || flow.shadow.contains(&root) { return; }
    let mut now = nikaia_std::index::or(match *nikaia_std::index::get(&flow.stores, &root) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || rsrc_none().into());
    rsrc_join(&mut now, reach);
    flow.stores.insert(root.to_owned(), now);
}

fn rsrc_changes_described(asked: &Asked<'_, '_, '_>, ty: Option<&Type>, name: &str) -> bool {
    let kind = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let subject = asked.names.resolve(kind.name);
    let described = nikaia_std::index::or_maybe(match *nikaia_std::index::get(&asked.own.functions, &(format!("{}::{}", subject, name))) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || match *nikaia_std::index::get(&asked.library.functions, &(format!("{}::{}", subject, name))) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    });
    let contract = match described { Some(__nikaia_value) => __nikaia_value, None => return false };
    contract.mutates
}

#[allow(clippy::too_many_arguments)]
fn rsrc_call(unit: &Unit, asked: &Asked<'_, '_, '_>, here: &Here, known: &collections::BTreeMap<String, ResultSrcKnown>, own_buffer: &impl Fn(&Expr) -> bool, func: &Expr, args: &[Expr], config: &[ConfigArg], flow: &mut ResultSrcFlow) -> collections::BTreeSet<String> {
    let mut key: String = String::from("");
    let mut named = false;
    let mut everything = rsrc_none();
    match func {
        Expr::Variable(name, _) => {
            let name = *name;
            let written = asked.names.resolve(name).to_owned();
            let carried = rsrc_of_name(&flow, &written);
            if carried.is_empty() && (variable_type(asked, here, &written).is_none() || flow.shadow.contains(&written)) {
                key = written;
                named = true;
            }
            rsrc_join(&mut everything, &carried);
        },
        Expr::Path(parts, _) => {
            key = joined_path(asked, parts);
            named = true;
        },
        _ => {
            let reach = rsrc_eval(unit, asked, here, known, own_buffer, func, flow);
            rsrc_join(&mut everything, &reach);
        },
    }
    let mut positional: Vec<collections::BTreeSet<String>> = vec![];
    for arg in args.iter() {
        let reach = rsrc_eval(unit, asked, here, known, own_buffer, arg, flow);
        rsrc_join(&mut everything, &reach);
        positional.push(reach);
    }
    for option in config.iter() {
        let reach = rsrc_eval(unit, asked, here, known, own_buffer, &option.value, flow);
        rsrc_join(&mut everything, &reach);
    }
    if !named { return everything; }
    let described = nikaia_std::index::or_maybe(match *nikaia_std::index::get(&asked.own.functions, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || match *nikaia_std::index::get(&asked.library.functions, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    });
    if described.is_some() && args.len() > 1 {
        let contract = match described { Some(__nikaia_value) => __nikaia_value, None => return rsrc_callee(asked, known, &key, &positional, &everything) };
        let signature = match match contract.signature.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return rsrc_callee(asked, known, &key, &positional, &everything) };
        for i in 0..args.len() as i64 {
            if ((i) as usize) < signature.params.len() && signature.mutable.contains(&nikaia_std::index::get(&signature.params, (i) as usize).0) {
                let root = rsrc_root_local(asked, here, &flow, nikaia_std::index::get(&args, (i) as usize));
                let kept_views = rsrc_ty_holds_view(asked, &nikaia_std::index::get(&signature.params, (i) as usize).1);
                if root.is_some() && kept_views && rsrc_may_hold(unit, asked, &flow, &nikaia_std::index::or(root.as_deref(), || "").to_owned()) { rsrc_bind(flow, &nikaia_std::index::or(root.as_deref(), || "").to_owned(), &everything); }
            }
        }
        for entry in contract.stores.iter() {
            let parts: Vec<&str> = entry.split(':').collect::<Vec<_>>();
            if parts.len() != 2 { continue; }
            let place = rsrc_param_index(&signature, *nikaia_std::index::get(&parts, 0));
            let source = rsrc_param_index(&signature, *nikaia_std::index::get(&parts, 1));
            if place >= 0 && source >= 0 && place < args.len() as i64 && source < positional.len() as i64 { rsrc_store(asked, nikaia_std::index::get(&args, nikaia_std::index::at(place)), nikaia_std::index::get(&positional, nikaia_std::index::at(source)), flow); }
        }
    }
    rsrc_callee(asked, known, &key, &positional, &everything)
}

fn rsrc_param_index(signature: &Signature, name: &str) -> i64 {
    let mut at: i64 = 0;
    for (named, _) in signature.params.iter() {
        if named == name { return at; }
        at += 1;
    }
    -1
}

fn rsrc_callee(asked: &Asked<'_, '_, '_>, known: &collections::BTreeMap<String, ResultSrcKnown>, key: &str, positional: &[collections::BTreeSet<String>], everything: &collections::BTreeSet<String>) -> collections::BTreeSet<String> {
    let found = nikaia_std::index::or(match *nikaia_std::index::get(&known, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || ResultSrcKnown { declared: false, params: vec![], reach: rsrc_none() });
    if found.declared {
        let mut out = rsrc_none();
        for entry in found.reach.iter() {
            let written = rsrc_param_of(entry);
            if written.starts_with('=') { continue; }
            let borrowed = rsrc_bare(&written);
            let mut at: i64 = -1;
            for i in 0..found.params.len() as i64 { if at < 0 && *nikaia_std::index::get(&found.params, (i) as usize) == borrowed { at = i; } }
            if at < 0 || at >= positional.len() as i64 { return everything.to_owned(); }
            let mapped = rsrc_under(&rsrc_path_of(entry), nikaia_std::index::get(&positional, nikaia_std::index::at(at)));
            if written.starts_with('~') { rsrc_join(&mut out, &rsrc_all_loose(&mapped)); } else { rsrc_join(&mut out, &mapped); }
        }
        return out;
    }
    let contract = match match *nikaia_std::index::get(&asked.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => match match *nikaia_std::index::get(&asked.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return everything.to_owned() } };
    let signature = match match contract.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return everything.to_owned() };
    if signature.result.is_some() {
        let result = nikaia_std::index::or(match signature.result.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Ty::Unknown);
        if !rsrc_ty_holds_view(asked, &result) { return rsrc_none(); }
    }
    if contract.borrows.is_empty() {
        if !positional.is_empty() && rsrc_result_is_receivers(asked, &signature) { return (*nikaia_std::index::get(&positional, 0)).to_owned(); }
        return everything.to_owned();
    }
    let mut out = rsrc_none();
    for (path, borrowed) in rsrc_written_paths(&contract) {
        let mut at: i64 = -1;
        for i in 0..signature.params.len() as i64 { if at < 0 && nikaia_std::index::get(&signature.params, (i) as usize).0 == borrowed { at = i; } }
        if at < 0 || at >= positional.len() as i64 { return everything.to_owned(); }
        rsrc_join(&mut out, &rsrc_under(&path, nikaia_std::index::get(&positional, nikaia_std::index::at(at))));
    }
    out
}

fn rsrc_written_paths(contract: &FnContract) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = vec![];
    if contract.returns.is_empty() {
        for borrowed in contract.borrows.iter() { out.push(("".to_owned(), borrowed.to_owned())); }
        return out;
    }
    for part in contract.returns.split("),") {
        let pieces: Vec<&str> = part.split(':').collect::<Vec<_>>();
        if pieces.len() != 2 { continue; }
        let path = (*nikaia_std::index::get(&pieces, 0)).trim().to_owned();
        let inside = (*nikaia_std::index::get(&pieces, 1)).trim();
        let names = nikaia_std::index::or(inside.strip_prefix("ref("), || inside.into()).to_owned();
        for name in names.split('|') {
            let bare = nikaia_std::index::or(name.trim().strip_suffix(')'), || name.trim().into()).to_owned();
            if !bare.is_empty() { out.push((path.to_owned(), bare)); }
        }
    }
    out
}

fn rsrc_result_is_receivers(asked: &Asked<'_, '_, '_>, signature: &Signature) -> bool {
    let result = match match signature.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return false };
    if signature.params.is_empty() || nikaia_std::index::get(&signature.params, 0).0 != "self" { return false; }
    let mut wanted: Vec<String> = vec![];
    rsrc_ty_names(&result, &mut wanted);
    let mut generics = 0;
    let mut receiver: Vec<String> = vec![];
    rsrc_ty_names(&nikaia_std::index::get(&signature.params, 0).1, &mut receiver);
    for name in wanted.iter() {
        let generic = !rsrc_plain_name(name) && !name.contains("::") && !asked.own.types.contains_key(name) && !asked.library.types.contains_key(name);
        if generic {
            generics += 1;
            if !nikaia_std::list::contains(&receiver, &name) { return false; }
            for i in 1..signature.params.len() as i64 {
                let mut other: Vec<String> = vec![];
                rsrc_ty_names(&nikaia_std::index::get(&signature.params, (i) as usize).1, &mut other);
                if nikaia_std::list::contains(&other, &name) { return false; }
            }
        }
    }
    generics > 0
}

fn rsrc_ty_names(ty: &Ty, out: &mut Vec<String>) {
    match ty {
        Ty::Named { name, args, .. } => {
            out.push(name.to_owned());
            for arg in args.iter() { rsrc_ty_names(arg, out); }
        },
        Ty::Var { name, .. } => { out.push(name.to_owned()); },
        Ty::Tuple(parts) => { for part in parts.iter() { rsrc_ty_names(part, out); } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); rsrc_ty_names(inner, out); },
        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); rsrc_ty_names(item, out); },
        _ => { },
    }
}

fn rsrc_a_source(unit: &Unit, asked: &Asked<'_, '_, '_>, arg: &FnArg, contract: Option<&FnContract>, at: i64) -> bool {
    if (*arg.ty.code).is_some() { return false; }
    if arg.ty.is_view || brings_buffer(unit, asked, &arg.ty) { return true; }
    let own = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    lends_in_own(own, at, &vec![asked.library])
}

fn rsrc_size(flow: &ResultSrcFlow) -> i64 {
    let mut total = flow.env.len() as i64;
    for (_, reach) in flow.env.iter() { total += reach.len() as i64; }
    total
}

fn rsrc_key(owner: Option<&str>, function: &str) -> String {
    let named = match owner { Some(__nikaia_value) => __nikaia_value, None => return function.to_owned() };
    format!("{}::{}", named, function)
}

fn rsrc_params(asked: &Asked<'_, '_, '_>, receiver: Option<&Receiver>, args: &[FnArg], config: &[ConfigParam]) -> Vec<String> {
    let mut params: Vec<String> = vec![];
    if receiver.is_some() {
        let self_name: String = String::from("self");
        params.push(self_name);
    }
    for arg in args.iter() { params.push(asked.names.resolve(arg.name).to_owned()); }
    for option in config.iter() { params.push(asked.names.resolve(option.name).to_owned()); }
    params
}

fn rsrc_seed(unit: &Unit, asked: &Asked<'_, '_, '_>, subject: Option<&Type>, item: &Item, known: &mut collections::BTreeMap<String, ResultSrcKnown>) {
    match item {
        Item::Fn { name, receiver, args, config, ret_type, .. } => {
            let name = *name;
            if buffered(unit, asked, (ret_type).as_ref()) {
                let owner = text_of(asked, subject);
                let key = rsrc_key((owner).as_deref(), &function_name(asked.names, name));
                known.insert(key, ResultSrcKnown { declared: true, params: rsrc_params(asked, (receiver).as_ref(), args, config), reach: rsrc_none() });
            }
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn rsrc_function(unit: &Unit, asked: &Asked<'_, '_, '_>, subject: Option<&Type>, trait_name: Option<&winnow_grammar::Symbol>, at: &Span, item: &Item, own_buffer: &impl Fn(&Expr) -> bool, known: &mut collections::BTreeMap<String, ResultSrcKnown>, out: &mut Vec<Finding>, report: bool) -> bool {
    match item {
        Item::Fn { name, receiver, args, config, ret_type, body, .. } => {
            let name = *name;
            if !buffered(unit, asked, (ret_type).as_ref()) { return false; }
            let function = function_name(asked.names, name);
            let owner = text_of(asked, subject);
            let key = rsrc_key((owner).as_deref(), &function);
            let own_contract = match *nikaia_std::index::get(&asked.own.functions, &key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            let params = rsrc_params(asked, (receiver).as_ref(), args, config);
            let self_name: &'static str = "self";
            let mut sources: Vec<String> = vec![];
            let mut position: i64 = 0;
            if receiver.is_some() {
                position = 1;
                if takes_a_view_of_itself((receiver).as_ref()) { sources.push(self_name.to_owned()); } else if subject.is_some() {
                    let held = match subject { Some(__nikaia_value) => __nikaia_value, None => return false };
                    if names_borrowing(asked.names, held, &unit.borrowing) { sources.push(self_name.to_owned()); }
                }
            }
            let mut declared: Vec<(winnow_grammar::Symbol, Type)> = vec![];
            for arg in args.iter() {
                declared.push((arg.name, arg.ty.clone()));
                if rsrc_a_source(unit, asked, arg, (own_contract).as_ref(), position) { sources.push(asked.names.resolve(arg.name).to_owned()); }
                position += 1;
            }
            for option in config.iter() {
                declared.push((option.name, option.ty.clone()));
                if (*option.ty.code).is_none() && brings_buffer(unit, asked, &option.ty) { sources.push(asked.names.resolve(option.name).to_owned()); }
            }
            let mut declared_views: Vec<String> = vec![];
            for arg in args.iter() { if (*arg.ty.code).is_none() && brings_buffer(unit, asked, &arg.ty) { declared_views.push(asked.names.resolve(arg.name).to_owned()); } }
            let walked_here = Here { subject: match subject {
                Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                None => None,
            }, subject_fields: fields_of_type(unit, asked, subject), declared, ours: None, carriers: collections::BTreeSet::new(), found: vec![] };
            let mut flow = rsrc_flow(at);
            for source in sources.iter() {
                let mut own = rsrc_none();
                own.insert(source.to_owned());
                flow.env.insert(source.to_owned(), own);
            }
            for arg in args.iter() {
                let owned = asked.names.resolve(arg.name).to_owned();
                if (*arg.ty.code).is_none() && !arg.mutable && !nikaia_std::list::contains(&sources, &owned) && !rsrc_scalar(asked, &arg.ty) {
                    let mut marked = rsrc_none();
                    if rsrc_either_text(asked, (ret_type).as_ref()) && rsrc_plain_text(asked, &arg.ty) { marked.insert(format!("={}", owned)); } else { marked.insert(format!("!{}", owned)); }
                    flow.env.insert(owned, marked);
                }
            }
            let mut size: i64 = 0;
            let mut rounds = 0;
            let mut settled = false;
            while rounds < 64 {
                flow.ways = vec![];
                flow.depth = 0;
                let tail = rsrc_block(unit, asked, &walked_here, &known, own_buffer, body, &mut flow);
                rsrc_tail(body, &tail, &mut flow);
                let now = rsrc_size(&flow);
                if rounds > 0 && now == size {
                    settled = true;
                    break;
                }
                size = now;
                rounds += 1;
            }
            let mut reach = rsrc_none();
            for way in flow.ways.iter() { rsrc_join(&mut reach, &way.reach); }
            if !settled { for source in sources.iter() { reach.insert(source.to_owned()); } }
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&known, &key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || ResultSrcKnown { declared: false, params: vec![], reach: rsrc_none() });
            let changed = (before.reach.len() as i64) != reach.len() as i64;
            known.insert(key.to_owned(), ResultSrcKnown { declared: true, params, reach: reach.to_owned() });
            if report {
                let of = of_what((owner).as_deref(), &function);
                let mut plain_ways: Vec<ResultSrcWay> = vec![];
                for way in flow.ways.iter() { plain_ways.push(ResultSrcWay { span: Span { start: way.span.start, end: way.span.end }, reach: rsrc_plain(&way.reach) }); }
                rsrc_report(asked, &of, &sources, &declared_views, &plain_ways, &rsrc_plain(&reach), (receiver).as_ref(), trait_name, at, out);
            }
            return changed;
        },
        _ => { },
    }
    false
}

fn rsrc_either_text(asked: &Asked<'_, '_, '_>, ty: Option<&Type>) -> bool {
    let result = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    result.either && rsrc_plain_text(asked, result)
}

fn rsrc_plain_text(asked: &Asked<'_, '_, '_>, ty: &Type) -> bool { (*ty.code).is_none() && !ty.is_nullable && ty.generics.is_empty() && asked.names.resolve(ty.name) == "String" }

fn rsrc_tail(body: &Block, tail: &collections::BTreeSet<String>, flow: &mut ResultSrcFlow) {
    let count = body.stmts.len() as i64;
    if count == 0 { return; }
    match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(count - 1)).node {
        Stmt::Expr(_) => {
            let span = Span { start: nikaia_std::index::get(&body.stmts, nikaia_std::index::at(count - 1)).span.start, end: nikaia_std::index::get(&body.stmts, nikaia_std::index::at(count - 1)).span.end };
            flow.ways.push(ResultSrcWay { span, reach: tail.to_owned() });
        },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
fn rsrc_report(asked: &Asked<'_, '_, '_>, of: &str, sources: &[String], declared_views: &[String], ways: &[ResultSrcWay], reach: &collections::BTreeSet<String>, receiver: Option<&Receiver>, trait_name: Option<&winnow_grammar::Symbol>, at: &Span, out: &mut Vec<Finding>) {
    for way in ways.iter() {
        for each in way.reach.iter() {
            if each.starts_with('!') {
                let owned = nikaia_std::index::or(each.strip_prefix('!'), || "");
                let message = format!("{} hands back a view of `{}`, which it takes by value, so the data is gone when the call returns.", of, owned);
                let note = format!("`{}` is moved into {} and ends with it; a view of it can't outlive the call.", owned, of);
                let help: String = String::from("Take it as `ref`, so the view is of the caller's data, or hand back a copy: declare `-> String` and write `.clone()`.");
                out.push(refusal("NK2302", Span { start: way.span.start, end: way.span.end }, message, vec![note], help));
                return;
            }
        }
    }
    let mut named: Vec<String> = vec![];
    for source in sources.iter() { if reach.contains(source) { named.push(source.to_owned()); } }
    if trait_name.is_none() { return; }
    let mut allowed: String = String::from("");
    if takes_a_view_of_itself(receiver) { allowed = String::from("self"); } else if declared_views.len() == 1 { allowed = (*nikaia_std::index::get(&declared_views, 0)).to_owned(); } else if declared_views.len() > 1 { return; }
    for source in named.iter() {
        if *source != allowed {
            let message = format!("{} implements a trait method that hands back views of `{}` only, but this hands back a view of `{}`'s data.", of, allowed, source);
            let note = format!("Whoever calls it through the trait reads the trait's declaration, which says the result points into `{}`.", allowed);
            let help: String = String::from("Hand back a view of the one the trait names, or a copy: declare `-> String` and write `.clone()`.");
            out.push(refusal("NK2302", Span { start: at.start, end: at.end }, message, vec![note], help));
            return;
        }
    }
}

fn rsrc_function_type(unit: &Unit, asked: &Asked<'_, '_, '_>, ty: &Type, at: &Span, out: &mut Vec<Finding>) {
    if (*ty.code).is_some() {
        let code = match (*ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return };
        let mut views = 0;
        for part in ty.generics.iter() { if brings_buffer(unit, asked, part) { views += 1; } }
        let answer = match (*code.result).as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
        if views == 0 && buffered(unit, asked, (answer).as_ref()) {
            let message: String = String::from("A function type that takes no view and hands one back doesn't say whose data the result points into.");
            let note = "Whoever calls through it has to keep the data the result points into unchanged, and the type has nothing to point at.".to_string();
            let help: String = String::from("Take the view it hands back as a parameter, or hand back a copy: declare `-> String`.");
            out.push(refusal("NK2302", Span { start: at.start, end: at.end }, message, vec![note], help));
            return;
        }
    }
    for part in ty.generics.iter() { rsrc_function_type(unit, asked, part, at, out); }
}

fn rsrc_function_types(unit: &Unit, asked: &Asked<'_, '_, '_>, args: &[FnArg], ret_type: Option<&Type>, at: &Span, out: &mut Vec<Finding>) {
    for arg in args.iter() { rsrc_function_type(unit, asked, &arg.ty, &arg.span, out); }
    let written = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return };
    rsrc_function_type(unit, asked, written, at, out);
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ResultSource {
    pub key: String,
    pub borrows: Vec<String>,
    pub returns: String,
}

pub fn result_sources(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<ResultSource> {
    let unit = Unit { borrowing: package_borrowing_types(asked, items), fields: view_fields(asked.names, items) };
    let mut known: collections::BTreeMap<String, ResultSrcKnown> = collections::BTreeMap::new();
    let mut ignored: Vec<Finding> = vec![];
    rsrc_solve(&unit, asked, items, own_buffer, &mut known, &mut ignored);
    let mut out: Vec<ResultSource> = vec![];
    for (key, found) in known.iter() {
        if !found.declared { continue; }
        let plain = rsrc_plain(&found.reach);
        let mut borrows: Vec<String> = vec![];
        for param in found.params.iter() { if plain.contains(param) { borrows.push(param.to_owned()); } }
        out.push(ResultSource { key: key.to_owned(), borrows, returns: rsrc_returns_text(&found.params, &found.reach) });
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PlacesStored {
    pub key: String,
    pub stores: Vec<String>,
}

pub fn places_stored(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool) -> Vec<PlacesStored> {
    let unit = Unit { borrowing: package_borrowing_types(asked, items), fields: view_fields(asked.names, items) };
    let mut known: collections::BTreeMap<String, ResultSrcKnown> = collections::BTreeMap::new();
    let mut ignored: Vec<Finding> = vec![];
    rsrc_solve(&unit, asked, items, own_buffer, &mut known, &mut ignored);
    let mut out: Vec<PlacesStored> = vec![];
    let nothing: Option<Type> = None;
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => { places_of(&unit, asked, (nothing).as_ref(), &item.span, &item.node, own_buffer, &known, &mut out); },
            Item::Impl { target, methods, .. } => {
                let subject: Option<Type> = Some(target.clone());
                for method in methods.iter() { places_of(&unit, asked, (subject).as_ref(), &method.span, &method.node, own_buffer, &known, &mut out); }
            },
            _ => { },
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn places_of(unit: &Unit, asked: &Asked<'_, '_, '_>, subject: Option<&Type>, at: &Span, item: &Item, own_buffer: &impl Fn(&Expr) -> bool, known: &collections::BTreeMap<String, ResultSrcKnown>, out: &mut Vec<PlacesStored>) {
    match item {
        Item::Fn { name, receiver, args, config, body, .. } => {
            let name = *name;
            let owner = text_of(asked, subject);
            let function = function_name(asked.names, name);
            let key = rsrc_key((owner).as_deref(), &function);
            let own_contract = match *nikaia_std::index::get(&asked.own.functions, &key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            let mut places = rsrc_none();
            let mut sources: Vec<String> = vec![];
            let mut position: i64 = 0;
            if receiver.is_some() { position = 1; }
            for arg in args.iter() {
                let named = asked.names.resolve(arg.name).to_owned();
                if arg.mutable && (*arg.ty.code).is_none() && !rsrc_scalar(asked, &arg.ty) { places.insert(named.to_owned()); } else if !arg.mutable && rsrc_plain_text(asked, &arg.ty) && (arg.ty.is_view || rsrc_lent(asked, (own_contract).as_ref(), position)) { sources.push(named.to_owned()); }
                position += 1;
            }
            if places.is_empty() || sources.is_empty() { return; }
            let mut declared: Vec<(winnow_grammar::Symbol, Type)> = vec![];
            for arg in args.iter() { declared.push((arg.name, arg.ty.clone())); }
            for option in config.iter() { declared.push((option.name, option.ty.clone())); }
            let here = Here { subject: match subject {
                Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                None => None,
            }, subject_fields: fields_of_type(unit, asked, subject), declared, ours: None, carriers: collections::BTreeSet::new(), found: vec![] };
            let mut flow = rsrc_flow(at);
            flow.places = places;
            for source in sources.iter() {
                let mut own = rsrc_none();
                own.insert(source.to_owned());
                flow.env.insert(source.to_owned(), own);
            }
            let mut size: i64 = -1;
            let mut rounds = 0;
            while rounds < 64 {
                flow.ways = vec![];
                flow.depth = 0;
                let tail = rsrc_block(unit, asked, &here, known, own_buffer, body, &mut flow);
                let mut now = rsrc_size(&flow);
                for (_, kept) in flow.stores.iter() { now += kept.len() as i64; }
                if now == size { break; }
                size = now;
                rounds += 1;
            }
            let mut stores: Vec<String> = vec![];
            for (place, kept) in flow.stores.iter() {
                let reached = rsrc_plain(kept);
                for source in sources.iter() { if reached.contains(source) { stores.push(format!("{}:{}", place, source)); } }
            }
            if !stores.is_empty() { out.push(PlacesStored { key, stores }); }
        },
        _ => { },
    }
}

fn rsrc_lent(asked: &Asked<'_, '_, '_>, contract: Option<&FnContract>, at: i64) -> bool {
    let own = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    lends_in_own(own, at, &vec![asked.library])
}

fn rsrc_returns_text(params: &[String], reach: &collections::BTreeSet<String>) -> String {
    let mut whole: collections::BTreeSet<String> = rsrc_none();
    let mut paths: collections::BTreeSet<String> = rsrc_none();
    for entry in reach.iter() {
        let path = rsrc_path_of(entry);
        if rsrc_param_of(entry).starts_with('~') { continue; }
        if path.is_empty() { whole.insert(entry.to_owned()); } else { paths.insert(path); }
    }
    let mut parts: Vec<String> = vec![];
    for path in paths.iter() {
        let mut named: Vec<String> = vec![];
        for param in params.iter() { if whole.contains(param) || reach.contains(&format!("{}:{}", path, param)) { named.push(param.to_owned()); } }
        if !named.is_empty() {
            let list = named.join(" | ");
            parts.push(format!("{}: ref({})", path, list));
        }
    }
    parts.join(", ")
}

fn rsrc_findings(asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool, out: &mut Vec<Finding>) {
    let unit = Unit { borrowing: package_borrowing_types(asked, items), fields: view_fields(asked.names, items) };
    let mut known: collections::BTreeMap<String, ResultSrcKnown> = collections::BTreeMap::new();
    rsrc_solve(&unit, asked, items, own_buffer, &mut known, out);
}

fn rsrc_solve(unit: &Unit, asked: &Asked<'_, '_, '_>, items: &[Spanned<Item>], own_buffer: &impl Fn(&Expr) -> bool, known: &mut collections::BTreeMap<String, ResultSrcKnown>, out: &mut Vec<Finding>) {
    let nothing: Option<Type> = None;
    let no_trait: Option<winnow_grammar::Symbol> = None;
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => { rsrc_seed(unit, asked, (nothing).as_ref(), &item.node, known); },
            Item::Impl { target, methods, .. } => {
                let subject: Option<Type> = Some(target.clone());
                for method in methods.iter() { rsrc_seed(unit, asked, (subject).as_ref(), &method.node, known); }
            },
            _ => { },
        }
    }
    let mut round = 0;
    let mut settled = false;
    while round < 64 {
        let mut grew = false;
        for item in items.iter() {
            match &item.node {
                Item::Fn { .. } => { if rsrc_function(unit, asked, (nothing).as_ref(), (no_trait).as_ref(), &item.span, &item.node, own_buffer, known, out, false) { grew = true; } },
                Item::Impl { target, methods, .. } => {
                    let subject: Option<Type> = Some(target.clone());
                    for method in methods.iter() { if rsrc_function(unit, asked, (subject).as_ref(), (no_trait).as_ref(), &method.span, &method.node, own_buffer, known, out, false) { grew = true; } }
                },
                _ => { },
            }
        }
        if !grew {
            settled = true;
            break;
        }
        round += 1;
    }
    if !settled && !items.is_empty() {
        let message: String = String::from("A chain of functions handing back views is too long for the build to follow, so a caller can't tell whose data a result is.");
        let help: String = String::from("Split the chain, or hand back a copy: declare `-> String` and write `.clone()`.");
        out.push(refusal("NK2302", Span { start: nikaia_std::index::get(&items, 0).span.start, end: nikaia_std::index::get(&items, 0).span.end }, message, vec![], help));
    }
    for item in items.iter() {
        match &item.node {
            Item::Fn { args, ret_type, .. } => {
                let grew = rsrc_function(unit, asked, (nothing).as_ref(), (no_trait).as_ref(), &item.span, &item.node, own_buffer, known, out, true);
                rsrc_function_types(unit, asked, args, (ret_type).as_ref(), &item.span, out);
            },
            Item::Impl { trait_name, target, methods, .. } => {
                let trait_name = *trait_name;
                let subject: Option<Type> = Some(target.clone());
                for method in methods.iter() {
                    let grew = rsrc_function(unit, asked, (subject).as_ref(), (trait_name).as_ref(), &method.span, &method.node, own_buffer, known, out, true);
                    match &method.node {
                        Item::Fn { args, ret_type, .. } => { rsrc_function_types(unit, asked, args, (ret_type).as_ref(), &method.span, out); },
                        _ => { },
                    }
                }
            },
            Item::Trait { methods, .. } => { for method in methods.iter() { rsrc_function_types(unit, asked, &method.node.args, (method.node.ret_type).as_ref(), &method.span, out); } },
            Item::Struct { fields, .. } => { for field in fields.iter() { rsrc_function_type(unit, asked, &field.ty, &field.span, out); } },
            _ => { },
        }
    }
}


// --- written.nika ---

pub fn written_expression(names: &winnow_grammar::InternerContext, expr: &Expr) -> String {
    match expr {
        Expr::LitInt { value, negative, .. } => { let negative = *negative; let value = *value; if negative && value > 0u64 { format!("-{}", value) } else { format!("{}", value) } },
        Expr::LitFloat(text, _) => text.to_owned(),
        Expr::LitBool(value, _) => { let value = *value; if value { String::from("true") } else { String::from("false") } },
        Expr::LitChar(text, _) => format!("'{}'", text),
        Expr::LitStr { text, .. } => format!("\"{}\"", text),
        Expr::LitInterpolated { parts, .. } => {
            let mut body: String = String::from("");
            for part in parts.iter() {
                match part {
                    FPart::Text(text) => { body.push_str(text); },
                    FPart::Hole { expr, spec, .. } => { body.push_str(&hole_written(names, expr, (spec).as_deref())); },
                }
            }
            format!("f\"{}\"", body)
        },
        Expr::LitNull(_) => String::from("null"),
        Expr::Variable(name, _) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments, _) => path_written(names, segments),
        Expr::Field { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; format!("{}.{}", operand(names, base), names.resolve(name)) },
        Expr::SafeField { base, name, .. } => { let base = nikaia_std::boxed::open(base); let name = *name; format!("{}?.{}", operand(names, base), names.resolve(name)) },
        Expr::Index { base, index, .. } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); format!("{}[{}]", operand(names, base), written_expression(names, index)) },
        Expr::Call { func, args, config, .. } => { let func = nikaia_std::boxed::open(func); format!("{}{}", written_expression(names, func), call_written(names, args, config)) },
        Expr::MethodCall { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; format!("{}.{}{}", operand(names, receiver), names.resolve(method), call_written(names, args, config)) },
        Expr::SafeMethod { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; format!("{}?.{}{}", operand(names, receiver), names.resolve(method), call_written(names, args, config)) },
        Expr::Unary { op, expr, .. } => { let expr = nikaia_std::boxed::open(expr); format!("{}{}", unary_word(op), operand(names, expr)) },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            let here = binds(op);
            format!("{} {} {}", side(names, lhs, here, false), binary_word(op), side(names, rhs, here, true))
        },
        Expr::Coalesce { value, fallback, .. } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); format!("{} ?? {}", operand(names, value), operand(names, fallback)) },
        Expr::Tuple(items, _) => format!("({})", all_written(names, items)),
        Expr::ListLit { items, .. } => format!("[{}]", all_written(names, items)),
        Expr::ListRepeat { value, count, .. } => { let value = nikaia_std::boxed::open(value); let count = nikaia_std::boxed::open(count); format!("[{}; {}]", written_expression(names, value), written_expression(names, count)) },
        Expr::Range { start, end, inclusive, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end); let inclusive = *inclusive;
            let dots = if inclusive { ".." } else { "..<" };
            format!("{}{}{}", operand(names, start), dots, operand(names, end))
        },
        _ => String::from("…"),
    }
}

fn hole_written(names: &winnow_grammar::InternerContext, expr: &Expr, spec: Option<&str>) -> String {
    let format = match spec { Some(__nikaia_value) => __nikaia_value, None => return format!("{{{}}}", written_expression(names, expr)) };
    format!("{{{}:{}}}", written_expression(names, expr), format)
}

fn path_written(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol]) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() {
        let segment = *segment;
        parts.push(names.resolve(segment).to_owned());
    }
    parts.join("::")
}

fn all_written(names: &winnow_grammar::InternerContext, items: &[Expr]) -> String {
    let mut parts: Vec<String> = vec![];
    for item in items.iter() { parts.push(written_expression(names, item)); }
    parts.join(", ")
}

fn call_written(names: &winnow_grammar::InternerContext, args: &[Expr], config: &[ConfigArg]) -> String {
    if config.is_empty() { return format!("({})", all_written(names, args)); }
    let mut options: Vec<String> = vec![];
    for option in config.iter() { options.push(format!("{}: {}", names.resolve(option.name), written_expression(names, &option.value))); }
    if args.is_empty() { return format!("(; {})", options.join(", ")); }
    format!("({}; {})", all_written(names, args), options.join(", "))
}

fn operand(names: &winnow_grammar::InternerContext, expr: &Expr) -> String {
    match expr {
        Expr::Binary { .. } => format!("({})", written_expression(names, expr)),
        Expr::Coalesce { .. } => format!("({})", written_expression(names, expr)),
        Expr::Cast { .. } => format!("({})", written_expression(names, expr)),
        _ => written_expression(names, expr),
    }
}

fn side(names: &winnow_grammar::InternerContext, expr: &Expr, here: i64, right: bool) -> String {
    match expr {
        Expr::Binary { op, .. } => {
            let inner = binds(op);
            if inner < here || right && inner == here { format!("({})", written_expression(names, expr)) } else { written_expression(names, expr) }
        },
        _ => operand(names, expr),
    }
}

fn binds(op: &BinaryOp) -> i64 {
    match op {
        BinaryOp::Or => 1,
        BinaryOp::And => 2,
        BinaryOp::Eq => 3,
        BinaryOp::Ne => 3,
        BinaryOp::Lt => 3,
        BinaryOp::Le => 3,
        BinaryOp::Gt => 3,
        BinaryOp::Ge => 3,
        BinaryOp::BitOr => 4,
        BinaryOp::BitXor => 5,
        BinaryOp::BitAnd => 6,
        BinaryOp::Shl => 7,
        BinaryOp::Shr => 7,
        BinaryOp::Add => 8,
        BinaryOp::Sub => 8,
        BinaryOp::Mul => 9,
        BinaryOp::Div => 9,
        BinaryOp::Rem => 9,
    }
}

fn binary_word(op: &BinaryOp) -> &'static str {
    match op {
        BinaryOp::Add => "+",
        BinaryOp::Sub => "-",
        BinaryOp::Mul => "*",
        BinaryOp::Div => "/",
        BinaryOp::Rem => "%",
        BinaryOp::Eq => "==",
        BinaryOp::Ne => "!=",
        BinaryOp::Lt => "<",
        BinaryOp::Le => "<=",
        BinaryOp::Gt => ">",
        BinaryOp::Ge => ">=",
        BinaryOp::And => "&&",
        BinaryOp::Or => "||",
        BinaryOp::BitAnd => "&",
        BinaryOp::BitOr => "|",
        BinaryOp::BitXor => "^",
        BinaryOp::Shl => "<<",
        BinaryOp::Shr => ">>",
    }
}

fn unary_word(op: &UnaryOp) -> &'static str {
    match op {
        UnaryOp::Neg => "-",
        UnaryOp::Not => "!",
        UnaryOp::Ref => "&",
    }
}

pub fn written_pattern(names: &winnow_grammar::InternerContext, pattern: &MatchPattern) -> String {
    match pattern {
        MatchPattern::Path(path) => path_written(names, path),
        MatchPattern::Tuple { path, .. } => format!("{}(…)", path_written(names, path)),
        MatchPattern::Named { path, .. } => format!("{} {{ … }}", path_written(names, path)),
        MatchPattern::Literal(literal) => written_expression(names, literal),
        MatchPattern::Or(alternatives) => {
            let mut parts: Vec<String> = vec![];
            for alternative in alternatives.iter() { parts.push(written_pattern(names, alternative)); }
            parts.join(" | ")
        },
        _ => String::from("this pattern"),
    }
}


